def _apply_proxy_fix(flask_app, hops: int) -> bool:
    """Wrap *flask_app*'s WSGI app in ProxyFix when *hops* > 0. Returns whether
    it wrapped.

    Trust model: set api_server.trusted_proxy_hops only when a reverse proxy YOU
    control fronts this API, to the number of trusted hops it adds. Clients (HA,
    LAN dashboards) reach this server directly today, so a non-zero value lets
    any client forge X-Forwarded-For — spoofing per-request rate-limit buckets
    and poisoning the remote_addr recorded in the audit log, the trusted-proxy
    check and the per-peer chat session key (_get_chat_client_id). At 0 the
    header is never parsed at all.
    """
    if hops <= 0:
        return False
    from werkzeug.middleware.proxy_fix import ProxyFix
    flask_app.wsgi_app = ProxyFix(flask_app.wsgi_app, x_for=hops, x_proto=hops,
                                  x_host=0, x_port=0, x_prefix=0)
    return True


def _configured_proxy_hops() -> int:
    """Trusted-proxy hop count from config; 0 when unset or unreadable."""
    try:
        from puffpai.config import get_config
        return max(0, int(getattr(get_config().api_server,
                                  'trusted_proxy_hops', 0) or 0))
    except Exception:
        return 0  # fail closed: an unreadable config trusts no proxy


#: Whether a reverse proxy is trusted for X-Forwarded-For. When true,
#: request.remote_addr is derived from a client-supplied header, so the
#: same-host arm of the endpoint gate must not honour it.
_PROXY_FIX_ACTIVE = _apply_proxy_fix(app, _configured_proxy_hops())

