# ══════════════════════════════════════════════════════════════════════════════
#  VAULT-GATED CHAT
#  When the user asks about protected info (medical, financial, ID, etc.)
#  PuffPAI prompts for the vault PIN, unlocks, searches the vaulted docs,
#  and returns the answer. The PIN is used once, never stored or logged.
# ══════════════════════════════════════════════════════════════════════════════

_VAULT_CHAT_STATE: dict[str, dict] = {}
_VAULT_CHAT_TIMEOUT = 300  # 5-minute unlock window per chat client

_PROTECTED_TOPIC_KEYWORDS = (
    # Identity — SSN, passport, driver's license, DOB
    'social security', 'my ssn', "what's my ssn", 'what is my ssn',
    'passport number', 'my passport', "driver's license", 'drivers license',
    'my license number', "what's my dob", 'what is my dob', 'my birthday',
    'my date of birth', 'birth certificate',
    # Medical — allergies, meds, diagnoses, doctor, insurance
    'my allergies', 'what are my allergies', 'my medical', 'medical record',
    'medical history', 'my medications', 'what medications', 'my meds',
    'my prescription', 'my diagnosis', 'my conditions', 'my doctor',
    'primary care', 'my health', 'my insurance', 'insurance policy',
    'insurance number', 'policy number', 'group number', 'member id',
    'my lab results', 'lab work', 'blood test', 'hba1c', 'cholesterol level',
    'allergies of my', 'medications of my', 'medical record of',
    'medical history of', 'health records of',
    # Financial
    'my bank account', 'bank account number', 'routing number',
    'credit card number', 'my routing', 'my account number',
    # Emergency / family PII
    'emergency contact', 'my home address', "my spouse's", "my son's medical",
    "my daughter's medical", "my child's medical",
)

# Distinctive words that confirm a short numeric string is really a PIN
_PIN_RANGE = range(4, 17)  # 4-16 characters


#: Shape of a proxy-supplied device session id. The dashboard sends an opaque
#: HMAC-derived hex string (``deviceSessionIdFor`` in
#: ``dashboard/app/_lib/server/pairing.ts``); anything that is not plainly that
#: shape is discarded rather than used as a dictionary key.
_DEVICE_SESSION_ID_RE = re.compile(r'^[A-Za-z0-9_-]{8,64}$')

#: Header the dashboard proxy sets — server-side only, never relayed from a
#: client — on a proxied request it could NOT attach a verified device identity
#: to. It says "I am a trusted proxy and this caller has no identity", which is
#: a DIFFERENT statement from "no header was sent" and must not be confused with
#: a direct loopback caller. See ``upstreamHeaders`` in
#: ``dashboard/app/_lib/server/proxyHeaders.ts``.
#:
#: The cases it covers: a legacy v1 pairing cookie (proves membership, names no
#: device), the scoped device-token upload/Shortcut path (no cookie at all), an
#: enforcement stage that lets an unpaired browser reach the proxy, and a device
#: revoked between the pairing gate and the header build.
_ANONYMOUS_CHAT_HEADER = 'X-Puff-Anonymous'

#: Namespace for a chat key that belongs to exactly ONE request. Nothing can be
#: inherited from it and nothing can be resumed on it.
_ANON_CHAT_PREFIX = 'anon:'

#: What the vault-gated chat path says to a caller with no device identity.
#: Deliberately plain about the remedy and deliberately silent about whether any
#: OTHER device happens to be unlocked right now.
_VAULT_CHAT_UNPAIRED_MESSAGE = (
    "🔒 That's protected information stored in your Zone 1 Vault. I can't open "
    "it for this device, because I can't tell which device it is — it isn't "
    "paired with this appliance, or it's still carrying an older pairing that "
    "doesn't identify it. Pair (or re-pair) this device in Settings, then ask "
    "me again."
)


def _anonymous_chat_client_id() -> str:
    """A vault-chat key that is unique to this request.

    WHY THIS EXISTS. Every browser behind the dashboard proxy arrives at the
    backend from loopback. If the proxy simply omitted ``X-Puff-Device-Id``
    when it cannot derive a device identity, the backend would fall back to
    ``peer:127.0.0.1`` — ONE bucket shared by every unidentified proxied caller.
    A legacy-v1 phone, the kiosk, an unpaired browser at the "knowledge"
    enforcement stage and an iPhone Shortcut upload would all land in it
    together, so one member's 300-second vault unlock would be inheritable by
    any of the others.

    A fresh random key per request fixes that by construction rather than by
    care: the value is never returned twice, so there is nothing to inherit and
    nothing to name. 128 bits from ``secrets`` — the same shape the backend
    already accepts for a derived device id, but unguessable and single-use.

    The key is deliberately not memoised anywhere. Losing it at the end of the
    request is the feature: no unlock can persist on it.
    """
    return f'{_ANON_CHAT_PREFIX}{secrets.token_hex(16)}'


def _is_anonymous_chat_client(client_id) -> bool:
    """True for a key minted by ``_anonymous_chat_client_id()``.

    A caller cannot forge one: ``device:`` ids are shape-checked against
    ``_DEVICE_SESSION_ID_RE`` (no ":" in the charset) and ``peer:`` keys are
    built from the socket address, so neither can ever start with ``anon:``.
    """
    return bool(client_id) and str(client_id).startswith(_ANON_CHAT_PREFIX)


def _trusted_proxy_peers() -> frozenset:
    """Extra peers allowed to assert a device identity, from the environment.

    Loopback is always trusted (the dashboard proxy runs on the box); this adds
    the case where the owner splits the dashboard onto another host, named as
    one or more comma-separated IPs in ``PUFFPAI_TRUSTED_PROXY_IPS``. There is
    deliberately no wildcard: an empty or garbage value trusts nobody, which
    degrades to per-socket sessions rather than to a spoofable one.
    """
    raw = os.environ.get('PUFFPAI_TRUSTED_PROXY_IPS', '') or ''
    return frozenset(p.strip() for p in raw.split(',') if p.strip())


def _is_trusted_proxy_peer() -> bool:
    """True when this request's socket peer may assert ``X-Puff-Device-Id``."""
    from puffpai.security.netaddr import is_loopback_peer
    import ipaddress
    try:
        peer = (request.remote_addr or '').strip()
    except Exception:
        return False
    if not peer:
        return False
    # is_loopback_peer() grades an ADDRESS, not a name: the string "localhost"
    # is not loopback here, so a forwarded value cannot assert locality with a
    # word instead of an address.
    if is_loopback_peer(peer):
        return True
    extra = _trusted_proxy_peers()
    if not extra:
        return False
    if peer in extra:
        return True
    # Compare as addresses too, so ::ffff:10.0.0.5 or a zero-padded spelling of
    # a configured IP matches the configured one instead of silently missing.
    try:
        parsed = ipaddress.ip_address(peer.strip('[]').split('%', 1)[0])
    except ValueError:
        return False
    mapped = getattr(parsed, 'ipv4_mapped', None)
    if mapped is not None:
        parsed = mapped
    for candidate in extra:
        try:
            if ipaddress.ip_address(candidate) == parsed:
                return True
        except ValueError:
            continue
    return False


def _get_chat_client_id():
    """Session key for the vault-unlocked chat window. NOT client-choosable.

    A vault-unlocked chat session answers protected questions with DECRYPTED
    vault content for 300 s with no further PIN, so whatever keys it is an
    authorisation boundary between household members. It is NOT
    ``X-Client-Id``, a header any caller can set to another member's value
    (a LAN IP is guessable) to inherit their unlock. That header is ignored
    entirely, and not advertised in CORS.

    THE RULE, in precedence order:

    1. ``X-Puff-Device-Id``, but **only** when the socket peer is a trusted
       proxy (loopback, or an address named in ``PUFFPAI_TRUSTED_PROXY_IPS``).
       The dashboard proxy sets it server-side from the VERIFIED pairing cookie
       and never relays a client-supplied copy, so a browser cannot choose it.
       From any other peer the header is ignored rather than trusted by shape:
       a LAN client talking to this backend directly cannot borrow a session by
       naming a device id it read out of ``/api/pair/devices``.
    2. A trusted proxy peer that asserts NO usable identity — the explicit
       ``X-Puff-Anonymous`` marker, a missing header, or a value that fails the
       shape check — gets a single-use ``anon:`` key from
       ``_anonymous_chat_client_id()``. Falling through to rule 3 would
       land it in ``peer:127.0.0.1``, which is the SAME bucket for every
       unidentified proxied caller in the house: a legacy-v1 phone, the kiosk,
       an unpaired browser at the "knowledge" enforcement stage and a device-
       token upload would all share one 300-second vault unlock. The anonymous key
       cannot be inherited (it is fresh per request) or named (it is random),
       and ``_maybe_vault_gated_answer`` refuses vault content on it outright.
       The marker WINS over a device id if a request somehow carries both: the
       proxy never sends both, so the combination means something upstream is
       wrong, and the restrictive reading is the safe one.
    3. Otherwise ``peer:<socket address>``. Direct callers — the CLI, the
       Home Assistant Assist pipeline, a script with the API key — keep working
       and get one session per address. That is safe *because* rule 1 removed
       the header that could override it: no header can change the key now, so
       the peer address is not spoofable by a request body or header.
    4. ``'unknown'`` when there is no socket address or no request context.

    Keys are namespaced (``device:``/``anon:``/``peer:``) so a device id shaped
    like an address cannot land in an address bucket.

    Fail-closed consequences worth knowing: two direct callers behind one
    address share one chat session; a process on the BOX that calls the backend
    over loopback without asserting an id is treated as anonymous and gets no
    vault answers (the remedy is to assert your own stable
    ``X-Puff-Device-Id``, which is what the on-box voice service does); and a
    ``PUFFPAI_TRUSTED_PROXY_IPS`` typo means device ids are ignored (per-socket
    sessions) rather than believed from anywhere.
    """
    try:
        if _is_trusted_proxy_peer():
            if (request.headers.get(_ANONYMOUS_CHAT_HEADER) or '').strip():
                return _anonymous_chat_client_id()
            asserted = (request.headers.get('X-Puff-Device-Id') or '').strip()
            if asserted and _DEVICE_SESSION_ID_RE.match(asserted):
                return f'device:{asserted}'
            return _anonymous_chat_client_id()
        return f'peer:{request.remote_addr}' if request.remote_addr else 'unknown'
    except Exception:
        return 'unknown'


def _cleanup_vault_chat_state():
    """Drop stale pending prompts and expired unlocks."""
    now = time.time()
    for cid in list(_VAULT_CHAT_STATE.keys()):
        s = _VAULT_CHAT_STATE[cid]
        last_touch = max(
            s.get('pending_since', 0),
            s.get('unlocked_at', 0),
        )
        if now - last_touch > _VAULT_CHAT_TIMEOUT:
            _VAULT_CHAT_STATE.pop(cid, None)


def _is_pin_like(text: str) -> bool:
    """Heuristic: a short alphanumeric/digit string by itself."""
    t = (text or '').strip()
    if ' ' in t or '\n' in t:
        return False
    return len(t) in _PIN_RANGE and (t.isdigit() or t.isalnum())


def _looks_like_pin(text: str) -> bool:
    """A PIN-shaped follow-up utterance: >=4 chars, no whitespace, all digits
    or a short alphanumeric secret. Used ONLY when a vault-display challenge is
    pending. NEVER logs the text."""
    t = (text or '').strip()
    if not t or any(c.isspace() for c in t):
        return False
    if not (4 <= len(t) <= 32):
        return False
    return t.isdigit() or (t.isalnum() and len(t) <= 12)


_PERSONAL_PRONOUNS = (
    ' my ', ' me ', ' i ', " i've", " i'm", ' mine ',
    'my ',  # start of sentence
)

# Substrings that strongly suggest medical/financial/identity context.
# Paired with a personal pronoun, this catches natural phrasings like
# "do I have any allergies" that the static keyword list misses. The
# prefix-match (``allerg``, ``medicat``, ``histor``) tolerates typos
# like "medical hisotry".
_PROTECTED_NOUN_STEMS = (
    'allerg', 'medicat', 'prescript', 'diagnos', 'doctor',
    'physician', 'patient', 'clinic', 'hospital', 'surgery',
    'lab result', 'blood test', 'health histor', 'medical histor',
    'health record', 'medical record',
    'ssn', 'social security', 'passport', "driver's license",
    'drivers license', 'date of birth', 'birth certificate',
    'bank account', 'routing number', 'credit card number',
    'insurance policy', 'policy number', 'member id', 'group number',
)


def _is_protected_query(user_message: str) -> bool:
    if not user_message:
        return False
    lower = ' ' + user_message.lower() + ' '

    # Strong explicit signals first
    if any(k in lower for k in _PROTECTED_TOPIC_KEYWORDS):
        return True

    # Fallback: personal-pronoun + protected noun stem. This catches
    # "do I have any allergies", "tell me about my medical history",
    # "what's in my lab results", etc.
    has_pronoun = any(p in lower for p in _PERSONAL_PRONOUNS)
    has_protected_noun = any(stem in lower for stem in _PROTECTED_NOUN_STEMS)
    return has_pronoun and has_protected_noun


def _count_vaulted_documents(vault) -> int:
    """Count doc_* files in the vault without decrypting them.

    Used as an existence gate before a vault session is available (we only need
    to know whether there is anything to gate on, not the contents).
    """
    try:
        return sum(
            1 for fname in os.listdir(vault._vault_dir)
            if fname.startswith('doc_') and not fname.startswith('.')
        )
    except Exception as e:
        logger.debug("Vault doc count failed: %s", e)
        return 0


def _load_vaulted_documents(vault, session_id: str) -> list[dict]:
    """Decrypt and return all doc_* files from vault_data for search.

    Requires an unlocked vault session: files are decrypted with the session's
    PIN-derived key. If the session is locked/expired the read raises and the
    document is skipped with a log line (never read as plaintext by accident).
    A not-yet-migrated legacy plaintext file is tolerated during the migration
    window via allow_plaintext.
    """
    docs = []
    try:
        for fname in sorted(os.listdir(vault._vault_dir)):
            if not fname.startswith('doc_') or fname.startswith('.'):
                continue
            try:
                text = vault.read_secure_blob(
                    fname, session_id, allow_plaintext=True)
                if text is None:
                    continue
                docs.append({'filename': fname, 'text': text})
            except Exception as e:
                logger.debug("Vault decrypt failed for %s (skipped): %s", fname, e)
    except Exception as e:
        logger.warning("Vault dir enumeration failed: %s", e)
    return docs


def _synthesize_from_vault(original_query: str, docs: list[dict]) -> str:
    """Ask the local LLM to answer ``original_query`` from vault docs."""
    if not docs:
        return ("I unlocked your vault, but I don't see any documents "
                "inside that would answer that. Try uploading the relevant "
                "file first.")

    combined = "\n\n---\n\n".join(
        f"[Document: {d['filename']}]\n{d['text'][:6000]}" for d in docs
    )
    prompt = (
        f"You are PuffPAI, answering from the user's private Zone 1 "
        f"Vault documents below. The user asked:\n\n"
        f"{original_query}\n\n"
        f"Find the answer in these documents and respond directly and "
        f"naturally. If the answer isn't there, say so. Do NOT list the "
        f"entire document. Do not echo the question.\n\n"
        f"[VAULTED DOCUMENTS]\n{combined}"
    )

    try:
        resp = _ollama_chat([{"role": "user", "content": prompt}],
                            temperature=0.2, num_predict=512, timeout=120)
        resp.raise_for_status()
        return resp.json()["message"]["content"].strip()
    except Exception as e:
        logger.warning("Vault LLM synthesis failed: %s", e)
        return f"I unlocked the vault but couldn't process the query: {e}"


def _try_unlock_and_answer(pin: str, original_query: str, client_id: str) -> str:
    """Authenticate with the PIN, search the vault, and answer.

    On success, caches the vault session for 5 minutes so follow-up
    protected queries in the same chat don't re-prompt for the PIN.
    """
    vault = _get_vault()
    if vault is None:
        return "The vault service isn't available right now."
    if not vault.is_initialized:
        return ("Your vault isn't set up yet. Open the Vault page and "
                "create a PIN first.")
    try:
        session = vault.authenticate(pin)
    except Exception as e:
        return (f"I couldn't unlock the vault with that PIN: {e}\n\n"
                f"Try again, or say the topic again to get a fresh prompt.")

    # Cache the vault session for the chat client
    state = _VAULT_CHAT_STATE.setdefault(client_id, {})
    state['vault_session'] = session.session_id
    state['unlocked_at'] = time.time()
    state.pop('pending_query', None)
    state.pop('pending_since', None)

    # Now that we hold the PIN-derived key, converge any legacy plaintext files
    # to encrypted so subsequent reads decrypt cleanly.
    try:
        vault.migrate_plaintext_files(session.session_id)
    except Exception as e:
        logger.debug("Vault migration (chat unlock) skipped: %s", e)

    docs = _load_vaulted_documents(vault, session.session_id)
    answer = _synthesize_from_vault(original_query, docs)
    return f"🔓 Vault unlocked.\n\n{answer}"


def _maybe_vault_gated_answer(user_message: str) -> str | None:
    """Gate protected queries behind the vault PIN.

    Flow:
      1. User asks a protected-topic question → prompt for PIN (if not
         already unlocked in this chat session)
      2. User replies with PIN → unlock, search vaulted docs, answer
      3. Vault stays unlocked for this chat client for 5 minutes —
         follow-up protected queries are answered directly
    """
    if not user_message:
        return None
    _cleanup_vault_chat_state()
    client_id = _get_chat_client_id()
    state = _VAULT_CHAT_STATE.get(client_id, {})

    # ── Case 1: User is replying with a PIN to our prompt ──
    pending_query = state.get('pending_query')
    if pending_query and _is_pin_like(user_message):
        pin = user_message.strip()
        # The user half of THIS turn is the PIN and the assistant half is read
        # out of the decrypted vault. Marked before the attempt, not after, so a
        # wrong-PIN reply is kept out of the transcript too.
        _mark_vault_turn_private()
        try:
            return _try_unlock_and_answer(pin, pending_query, client_id)
        finally:
            # PIN is used once and discarded. `pin` goes out of scope here.
            pin = None  # noqa: F841

    # ── Case 2: Is this a protected topic query? ──
    if not _is_protected_query(user_message):
        return None

    vault = _get_vault()
    if vault is None or not vault.is_initialized:
        # Vault not set up — let normal flow handle. (We don't want to
        # prompt for a PIN the user has never created.)
        return None

    # Only gate if there are actual documents in the vault. This existence
    # check runs before we have a session, so it enumerates without decrypting.
    if not _count_vaulted_documents(vault):
        return None

    # ── Case 2 (no identity): never bind a vault session to a shared key ──
    # A trusted-proxy request with no verified device identity holds a single-use
    # anon: key (see _get_chat_client_id rule 2). Returning here does two things
    # deliberately: it never READS a bucket (a fresh key has none, so no other
    # member's unlock can be inherited) and it never WRITES one (no pending_query
    # is stored, so a PIN typed next turn cannot unlock anything on this key).
    # The caller is told what to do about it instead of being prompted for a PIN
    # that could not persist anyway.
    if _is_anonymous_chat_client(client_id):
        # No vault content here, but the user half is still the protected
        # question. Restrictive reading: not persisted, same as the challenge.
        _mark_vault_turn_private()
        return _VAULT_CHAT_UNPAIRED_MESSAGE

    # ── Case 2a: Already unlocked in this chat session ──
    vault_sid = state.get('vault_session')
    if vault_sid:
        try:
            vault._validate_session(vault_sid)
            # Still valid — decrypt with the session key and answer directly.
            # This answer IS vault document content, so the turn is no more
            # persistable than the PIN turn that opened the window: marked
            # before the decrypt, so every return below it is covered.
            _mark_vault_turn_private()
            docs = _load_vaulted_documents(vault, vault_sid)
            answer = _synthesize_from_vault(user_message, docs)
            return answer
        except Exception:
            # Session expired — fall through to re-prompt
            state.pop('vault_session', None)
            state.pop('unlocked_at', None)

    # ── Case 2b: Need the PIN ──
    # The challenge turn carries the protected question and is a durable record
    # that it was asked — the same reason the vault-display challenge marks.
    _mark_vault_turn_private()
    state['pending_query'] = user_message
    state['pending_since'] = time.time()
    _VAULT_CHAT_STATE[client_id] = state

    return (
        "🔒 That's protected information stored in your Zone 1 Vault. "
        "To access it, please reply with your PIN."
    )


def _maybe_identity_answer(user_message):
    """Return a deterministic, verified answer for identity questions.

    "What model are you running?", "Where are you running?", "Are you in the
    cloud?" etc. must NEVER be answered by the LLM — the LLM will hallucinate
    and claim to be on "secure servers". This intercepts those questions and
    returns the ground truth, including the real internet-connectivity state.

    Returns the answer string, or None if the message is not an identity
    question.
    """
    if not user_message:
        return None
    lower = user_message.lower().strip()

    model_qs = ('what model', 'which model', 'what llm', 'which llm',
                'what ai model', 'what language model', 'what are you running',
                'what are you powered by', 'what powers you')
    location_qs = ('where are you running', 'where are you hosted',
                   'where do you run', 'where is this running',
                   'where is this hosted', 'where are your servers',
                   'are you in the cloud', 'are you on the cloud',
                   'are you offline', 'are you online', 'are you local',
                   'are you hosted', 'what are you running on',
                   'what hardware', 'on what device', 'is this local',
                   'where is it running', 'where it is running')
    user_net_qs = (
        'am i connected to the internet', 'am i connected',
        'am i online', 'am i offline', 'do i have internet',
        'do i have wifi', 'is my internet on', 'is my internet off',
        'is the internet on', 'is the internet up', 'is the wifi on',
        'is wifi connected', 'check my internet', 'check the internet',
        'is the internet working', 'do i have a connection',
        'is my connection up',
    )

    is_model_q = any(q in lower for q in model_qs)
    is_location_q = any(q in lower for q in location_qs)
    is_user_net_q = any(q in lower for q in user_net_qs)

    if not (is_model_q or is_location_q or is_user_net_q):
        return None

    lan_up = _check_lan_connected()

    # Use a rotating index so repeated questions don't give identical
    # answers. This makes the assistant feel alive instead of canned.
    import hashlib
    _variant_seed = int(hashlib.md5(
        f"{time.time():.0f}".encode()).hexdigest()[:8], 16)
    variant = _variant_seed % 3

    # ── User asked specifically about THEIR connection ──
    if is_user_net_q and not (is_model_q or is_location_q):
        if lan_up:
            options = [
                ("You're offline right now — I don't connect to the internet. "
                 "However, I do have access to your local area network, meaning "
                 "I can see everything behind your modem and am currently "
                 "managing your smart home network. Would you like to connect "
                 "to a network?"),
                ("No internet connection — by design. But your local network "
                 "is up, and I'm actively managing your smart home through it. "
                 "I can see all devices on your LAN, control lights, check "
                 "sensors, and run automations. Want me to connect to an "
                 "outside network?"),
                ("I'm offline from the internet, but that's how I'm built. "
                 "Your local area network is live, and I'm managing your "
                 "smart home devices right now. Everything behind your modem "
                 "is visible to me. Would you like to connect to a network?"),
            ]
            return options[variant]
        options = [
            ("You're offline — no internet and no local network detected "
             "either. I'm still fully functional for AI, documents, and "
             "knowledge base queries, but I can't reach your smart home "
             "devices right now. Would you like to connect to a network?"),
            ("No connection at all right now — internet or local. I can "
             "still answer questions, search your knowledge base, and manage "
             "your documents, but smart home control is unavailable until "
             "the local network comes back. Want to connect?"),
            ("I'm completely offline — no internet and no LAN. I'm still "
             "here for you though. AI, documents, knowledge base — all "
             "local. Smart home features will come back when the network "
             "does. Would you like to connect?"),
        ]
        return options[variant]

    # ── Identity / location questions ──
    return (
        f"I'm running {OLLAMA_MODEL}, served locally by Ollama — no cloud, "
        f"no external dependencies. I process everything right here on your "
        f"hardware; always local, always private."
    )


# (Legacy _maybe_vault_gated_answer stub removed — superseded by the
# comprehensive implementation earlier in this file that supports
# searching vaulted documents, not just listing PII types.)


class _ThinkingChunk:
    """A piece of the model's reasoning, kept OUT of the content stream.

    Yielded by :func:`_stream_ollama_tokens` only when the caller asked for
    ``think=True``. Deliberately not a str: reasoning must never be
    concatenated into the answer, so a caller that forgot to filter it fails
    loudly instead of leaking it into history, ``full_response``, PII routing
    or TTS. Callers that do not opt in never see one.
    """

    __slots__ = ('text',)

    def __init__(self, text):
        self.text = text


def _stream_ollama_tokens(user_message, conversation_history, persona,
                          meta_out=None, *, think=False):
    """Yield tokens from Ollama as they are generated (real streaming).

    Used by the /chat/stream endpoint for true first-token-fast SSE.

    If ``meta_out`` is provided, it is populated in-place with the RAG
    sources used for this query, so the streaming caller can include them
    in its final SSE chunk.

    ``think=True`` asks the model to reason out loud and yields that reasoning
    as :class:`_ThinkingChunk` objects, interleaved in arrival order but never
    as content. A model with no reasoning lever, or a daemon that rejects the
    flag, degrades silently to the plain stream — the turn still answers.
    """
    import requests as _requests

    # Vault-gated PII questions must be intercepted before the LLM.
    vault_answer = _maybe_vault_gated_answer(user_message)
    if vault_answer:
        yield vault_answer
        return

    # Identity questions must return a deterministic, verified answer —
    # the LLM hallucinates and claims to be on "secure servers" otherwise.
    identity_answer = _maybe_identity_answer(user_message)
    if identity_answer:
        yield identity_answer
        return

    # Build RAG context (skip for trivial messages)
    rag_context = ""
    if not _should_skip_rag(user_message):
        rag_result = _get_rag_context(user_message)
        if rag_result:
            context_text = rag_result['context_text']
            max_rag = 8000
            if len(context_text) > max_rag:
                context_text = context_text[:max_rag] + "\n[Context truncated...]"
            rag_context = f"\n\n[Knowledge Base Context]\n{context_text}\n"
            if meta_out is not None:
                meta_out['sources'] = rag_result.get('sources', [])

    # Build message list
    messages = []
    if persona:
        messages.append({"role": "system", "content": persona})

    for msg in (conversation_history or [])[-_MAX_HISTORY_TURNS:]:
        messages.append({"role": "user", "content": msg['user']})
        messages.append({"role": "assistant", "content": msg['assistant']})

    final_msg = (f"{rag_context}\n[User Question]\n{user_message}"
                 if rag_context else user_message)
    messages.append({"role": "user", "content": final_msg})

    try:
        response = _ollama_chat(messages, num_predict=1024,
                                stream=True, timeout=120,
                                think=True if think else None)
        # Asking to think is never worth losing the answer over: a daemon or
        # model that refuses the flag gets the call it would have got anyway.
        if think and getattr(response, "status_code", 200) >= 400:
            logger.debug("thinking refused (HTTP %s) — plain stream instead",
                         response.status_code)
            try:
                response.close()   # release the refused stream's connection
            except Exception:
                pass
            response = _ollama_chat(messages, num_predict=1024,
                                    stream=True, timeout=120)
        response.raise_for_status()
        for line in response.iter_lines():
            if not line:
                continue
            try:
                chunk = json.loads(line.decode("utf-8", errors="replace"))
                if chunk.get("done"):
                    break
                if think:
                    thought = chunk.get("message", {}).get("thinking", "")
                    if thought:
                        yield _ThinkingChunk(thought)
                token = chunk.get("message", {}).get("content", "")
                if token:
                    yield token
            except (ValueError, KeyError, IndexError):
                continue
    # The streaming path is what the chat page actually uses, and it answered a
    # brainless build with "[Error] Cannot connect to Ollama." — eight words, no
    # remedy, written into the conversation as though the assistant had said it.
    # Same sentence as the non-streaming route now.
    except _requests.exceptions.Timeout:
        yield _brain_failure('timeout')['message']
    except _requests.exceptions.ConnectionError:
        yield _brain_failure(None)['message']
    except Exception as e:
        yield f"[Error] {e}"


# ── Hallucination verification layer ─────────────────────────────────────────
# The local LLM sometimes claims it performed an action (e.g. "Task added!")
# without actually invoking the tool.  These helpers snapshot data counts
# before the agent runs, then compare after.  If the count didn't change
# but the response claims success, the action is executed directly.

def _snapshot_counts(user_msg=None):
    """Take a snapshot of item counts across all apps for verification.

    When the message mentions automations, the HA automation count is
    included too, so a "will now turn off every night" claim with no
    actual automation created gets corrected like any other bluff.
    """
    from puffpai.app_data import AppData
    app = AppData()
    counts = {}
    if user_msg and re.search(r"(?i)\bautomat", user_msg):
        try:
            counts['automations'] = len(
                _get_ha_bridge().get_automations() or [])
        except Exception:
            pass
    try:
        cal = app._load('calendar')
        counts['events'] = len(cal.get('events', []))
        counts['tasks'] = len(cal.get('tasks', []))
        counts['meds'] = len(cal.get('meds', []))
        counts['bills'] = len(cal.get('bills', []))
    except Exception:
        pass
    try:
        alarm = app._load('alarmflow')
        counts['alarms'] = len(alarm.get('items', []))
    except Exception:
        pass
    try:
        fresh = app._load('freshtable')
        counts['pantry'] = len(fresh.get('pantry', []))
        counts['shopping'] = len(fresh.get('shoppingList', []))
        counts['recipes'] = len(fresh.get('mealPlan', []))
    except Exception:
        pass
    try:
        fit = app._load('fitfam')
        total = sum(len(u.get('history', [])) for u in fit.get('users', {}).values())
        counts['workouts'] = total
    except Exception:
        pass
    return counts


def _fix_add_task(user_msg, app):
    """Extract task info from user message and add directly."""
    from datetime import timedelta
    title = user_msg.strip()

    # Try to extract quoted title first (most reliable)
    quoted = re.search(r'["\u201c]([^"\u201d]{3,60})["\u201d]', title)
    if quoted:
        title = quoted.group(1)
    else:
        # Strip common prefixes (including "remind me to")
        title = re.sub(
            r'(?i)^(?:can you (?:please )?)?'
            r'(?:remind\s+me\s+(?:to|that|about)\s+'
            r'|(?:add|create|set|make|put|schedule)\s+'
            r'(?:a\s+)?(?:task|to-?do|event|reminder|entry)?\s*'
            r'(?:for|to|called|named|on|:)?\s*'
            r'(?:my\s+)?(?:calendar\s*)?(?:for|to)?\s*)',
            '', title).strip()
        # Truncate at stop phrases
        for stop in ['. but ', '. set ', '. assign', ' every weekday',
                     ' every day', ' on a daily', ' break these',
                     ' and add them', ' but set']:
            idx = title.lower().find(stop)
            if idx > 5:
                title = title[:idx].strip()
                break
        # If still too long, take first sentence up to 60 chars
        if len(title) > 60:
            first_sentence = re.split(r'[.!?]', title)[0].strip()
            title = first_sentence[:60] if len(first_sentence) > 60 else first_sentence

    # Strip time references from title (e.g. "at 2:45 PM")
    time_match = re.search(r'(?i)\s+(?:at|by)\s+\d{1,2}(?::\d{2})?\s*(?:am|pm)\.?$', title)
    if time_match:
        title = title[:time_match.start()].strip()

    # If user specified a time ("at 2:45 PM"), set due to today (not tomorrow)
    has_time = re.search(r'(?i)\b(?:at|by)\s+\d{1,2}(?::\d{2})?\s*(?:am|pm)', user_msg)
    due = datetime.now().strftime('%Y-%m-%d') if has_time else (datetime.now() + timedelta(days=1)).strftime('%Y-%m-%d')
    for dp, resolver in [
        (r'(?i)\b(?:on|by|due|for)\s+(tomorrow)\b',
         lambda: (datetime.now() + timedelta(days=1)).strftime('%Y-%m-%d')),
        (r'(?i)\b(?:on|by|due|for)\s+(today)\b',
         lambda: datetime.now().strftime('%Y-%m-%d')),
    ]:
        m = re.search(dp, user_msg)
        if m and resolver:
            due = resolver()
            break
    # Extract assigned_to
    assigned = 'all'
    assign_match = re.search(r'(?i)assign(?:ed?)?\s+to\s+(\w+(?:\s+and\s+\w+)?)', user_msg)
    if assign_match:
        assigned = assign_match.group(1).strip().lower()

    if not title or len(title) < 2:
        return None
    title = title.strip(' .,!?')
    app.cal_add_task(title, due, assigned_to=assigned)
    return f"task '{title}' added"


def _fix_add_event(user_msg, app):
    """Extract event info from user message and add directly."""
    from datetime import timedelta
    title = user_msg.strip()
    for prefix in ['add', 'create', 'set', 'make', 'new', 'put', 'schedule']:
        for word in ['an event', 'event', 'appointment', 'meeting',
                     'a meeting', 'an appointment']:
            pattern = rf'(?i)^{prefix}\s+{word}\s*(?:for|to|called|named|:)?\s*'
            title = re.sub(pattern, '', title).strip()

    # Honor a stated clock time — silently storing 9:00 AM for
    # "tomorrow at 5 PM" is wrong data the user won't notice until
    # they miss the appointment.
    hour, minute = 9, 0
    m = re.search(r'(?i)\bat\s+(\d{1,2})(?::(\d{2}))?\s*(am|pm)?\b', title)
    if m:
        hour = int(m.group(1))
        minute = int(m.group(2) or 0)
        ampm = (m.group(3) or '').lower()
        if ampm == 'pm' and hour < 12:
            hour += 12
        elif ampm == 'am' and hour == 12:
            hour = 0
        title = (title[:m.start()] + ' ' + title[m.end():]).strip()

    day = datetime.now()
    if re.search(r'(?i)\btomorrow\b', title):
        day = day + timedelta(days=1)
        title = re.sub(r'(?i)\btomorrow\b', ' ', title)
    elif not re.search(r'(?i)\btoday\b', title):
        day = day + timedelta(days=1)  # unstated day: keep old default
    else:
        title = re.sub(r'(?i)\btoday\b', ' ', title)
    start = day.strftime(f'%Y-%m-%dT{hour:02d}:{minute:02d}')

    title = ' '.join(title.split()).strip(' .,!?')
    if not title or len(title) < 2:
        return None
    app.cal_add_event(title, start)
    return f"event '{title}' added for {day.strftime('%A')} at {hour:02d}:{minute:02d}"


_WORD_NUMBERS = {
    'one': 1, 'two': 2, 'three': 3, 'four': 4, 'five': 5, 'six': 6,
    'seven': 7, 'eight': 8, 'nine': 9, 'ten': 10, 'eleven': 11,
    'twelve': 12, 'thirteen': 13, 'fourteen': 14, 'fifteen': 15,
    'sixteen': 16, 'seventeen': 17, 'eighteen': 18, 'nineteen': 19,
    'twenty': 20, 'twenty-five': 25, 'thirty': 30, 'forty': 40,
    'forty-five': 45, 'fifty': 50, 'sixty': 60, 'ninety': 90,
    'a': 1, 'an': 1,
}


def _extract_duration(text):
    """Parse '10 minutes', 'fifteen seconds', 'an hour and a half', etc.

    Returns (hours, minutes, seconds) or None if no duration was stated.
    Never guesses: a wrong timer is worse than asking the user to repeat.
    """
    lower = text.lower()

    # Consume half-hour idioms BEFORE unit matching: otherwise "half AN
    # hour" also matches the word-number branch ('an' == 1 hour) and the
    # two paths double-count to 1h30m.
    half_hour = False
    if 'half an hour' in lower or 'a half hour' in lower:
        lower = lower.replace('half an hour', ' ').replace('a half hour', ' ')
        half_hour = True

    def amount_before(unit_re):
        m = re.search(r'(\d+(?:\.\d+)?)\s*' + unit_re, lower)
        if m:
            return float(m.group(1))
        m = re.search(r'\b([a-z]+(?:-[a-z]+)?)\s+' + unit_re, lower)
        if m and m.group(1) in _WORD_NUMBERS:
            return float(_WORD_NUMBERS[m.group(1)])
        return None

    hours = amount_before(r'(?:hours?|hrs?)\b')
    minutes = amount_before(r'(?:minutes?|mins?)\b')
    seconds = amount_before(r'(?:seconds?|secs?)\b')
    if half_hour:
        minutes = (minutes or 0) + 30
    if hours and 'and a half' in lower:
        minutes = (minutes or 0) + 30

    if not any([hours, minutes, seconds]):
        return None
    total = int((hours or 0) * 3600 + (minutes or 0) * 60 + (seconds or 0))
    if total <= 0:
        return None
    return total // 3600, (total % 3600) // 60, total % 60


def _human_duration(hours, minutes, seconds):
    parts = []
    if hours:
        parts.append(f"{hours} hour{'s' if hours != 1 else ''}")
    if minutes:
        parts.append(f"{minutes} minute{'s' if minutes != 1 else ''}")
    if seconds:
        parts.append(f"{seconds} second{'s' if seconds != 1 else ''}")
    return " ".join(parts)


def _fix_add_timer(user_msg, app):
    """Extract timer info and add directly."""
    duration = _extract_duration(user_msg)
    if duration is None:
        # No parseable duration — do NOT guess a default. Returning None
        # lets the caller ask the user instead of silently creating a
        # wrong timer (e.g. 'fifteen seconds' becoming 5 minutes).
        return None
    hours, minutes, seconds = duration
    desc = re.sub(r'(?i)\b(?:set|start|create|make)\s+(?:a\s+)?timer\s*(?:for)?\s*',
                  '', user_msg).strip()
    desc = re.sub(r'(?i)\b(?:\d+(?:\.\d+)?|[a-z]+(?:-[a-z]+)?)\s*'
                  r'(?:hours?|hrs?|minutes?|mins?|seconds?|secs?)\b\s*(?:and\s*)?',
                  '', desc).strip(' .,!?')
    human = _human_duration(hours, minutes, seconds)
    if len(desc) > 60:  # indirect phrasings leave whole sentences behind
        desc = desc[:60].rsplit(' ', 1)[0]
    desc = desc or f'{human} timer'
    app.alarm_create_timer(desc, hours=hours, minutes=minutes, seconds=seconds)
    return f"timer '{desc}' set for {human}"


def _fix_add_alarm(user_msg, app):
    """Extract alarm info and add directly."""
    from datetime import timedelta
    # Relative request ("in 90 minutes", "in 2 hours") — compute the
    # clock time; the bare-number clock parse below would misread it.
    m_rel = re.search(r'(?i)\bin\s+(\d+|[a-z]+(?:-[a-z]+)?)\s*'
                      r'(hour|hr|minute|min)s?\b', user_msg)
    if m_rel:
        raw_n = m_rel.group(1)
        n = int(raw_n) if raw_n.isdigit() else _WORD_NUMBERS.get(raw_n)
        if n is None:
            return None
        minutes = n * 60 if m_rel.group(2).lower().startswith(('hour', 'hr')) else n
        if minutes >= 1440:
            return ("!Alarms can only be set up to 24 hours ahead. For "
                    "something further out, add a calendar event instead.")
        target = datetime.now() + timedelta(minutes=minutes)
        desc = re.sub(r'(?i)\b(?:set|create)\s+(?:an?\s+)?alarm\b|\bwake me'
                      r'(?:\s+up)?\b|\bfor\b|\bin\s+\S+\s*(?:hour|hr|minute|'
                      r'min)s?\b', ' ', user_msg)
        desc = ' '.join(desc.split()).strip(' .,!?') or 'Alarm'
        app.alarm_create_alarm(desc, target.hour, target.minute)
        return f"alarm set for {target.strftime('%I:%M %p').lstrip('0')}"

    m = re.search(r'(\d{1,2}):?(\d{2})?\s*(am|pm)?', user_msg, re.IGNORECASE)
    if not m:
        return None
    hour = int(m.group(1))
    minute = int(m.group(2) or 0)
    ampm = (m.group(3) or '').lower()
    if ampm == 'pm' and hour < 12:
        hour += 12
    elif ampm == 'am' and hour == 12:
        hour = 0
    # A bare number like the "45" in "in 45 minutes" is a duration, not a
    # clock time — refuse rather than create a nonsense alarm.
    if not (0 <= hour <= 23) or not (0 <= minute <= 59):
        return None
    desc = re.sub(r'(?i)set\s+(?:an?\s+)?alarm\s*(?:for)?\s*', '', user_msg).strip()
    desc = re.sub(r'\d{1,2}:?\d{0,2}\s*(?:am|pm)?', '', desc).strip(' .,!?')
    desc = desc or f'Alarm at {hour}:{minute:02d}'
    app.alarm_create_alarm(desc, hour, minute)
    return f"alarm set for {hour}:{minute:02d}"


def _fix_add_pantry(user_msg, app):
    """Extract pantry item and add directly."""
    item = user_msg.strip()
    for prefix in ['add', 'put']:
        for word in ['to pantry', 'to the pantry', 'in pantry', 'in the pantry']:
            item = re.sub(rf'(?i)\s*{word}\s*', '', item)
        item = re.sub(rf'(?i)^{prefix}\s+', '', item)
    item = item.strip(' .,!?')
    if not item or len(item) < 2:
        return None
    app.fresh_add_pantry(item, 1, 'pcs')
    return f"'{item}' added to pantry"


def _fix_add_shopping(user_msg, app):
    """Extract shopping item and add directly."""
    item = user_msg.strip()
    for prefix in ['add', 'put']:
        for word in ['to shopping list', 'to the shopping list',
                     'on shopping list', 'on the shopping list',
                     'to the list', 'to list']:
            item = re.sub(rf'(?i)\s*{word}\s*', '', item)
        item = re.sub(rf'(?i)^{prefix}\s+', '', item)
    item = item.strip(' .,!?')
    if not item or len(item) < 2:
        return None
    app.fresh_add_shopping(item, 1, 0)
    return f"'{item}' added to shopping list"


#: A message that has already been through a redaction/vaulting pass. Storing
#: one of these as a medication NAME would put "[REDACTED-HEALTH]" in the
#: household's medication list — a real corruption, reachable today only with
#: PUFFPAI_SCRUB_AND_VAULT on.
_REDACTED_PLACEHOLDER_RE = re.compile(r"\[REDACTED[^\]]*\]|\{\{vault:")

#: Words that make a phrase a SCHEDULE rather than a medication name. A drug is
#: one or two words and none of them is "reminder".
_MED_NOT_A_NAME_RE = re.compile(
    r"(?i)\b(?:remind|reminds|reminder|reminders|daily|every|each|schedule|"
    r"morning|afternoon|evening|night|bedtime|tonight|today|tomorrow|"
    r"o'?clock|a\.?m\.?|p\.?m\.?)\b")


def _fix_add_med(user_msg, app):
    """Extract medication and add directly.

    The reply names the DESTINATION, not just the fact of a write. A household
    that is told "medication 'insulin' added" cannot tell whether that is a
    calendar entry, a note, or nothing at all — and this is the one path where
    a wrong belief about storage costs someone a dose.
    """
    # Clause-scoped extraction first (the same rule the fastpath uses). It is
    # what lets "my SSN is [REDACTED-SSN], add my vitamin to my meds" store
    # `vitamin` rather than refusing on a placeholder that was never part of
    # the drug's name. Falls through to the whole-sentence rules
    # below when no add-a-medication clause is present.
    _clause = _extract_med_name(user_msg)
    if _clause:
        _refusal = _med_name_refusal(_clause, source=user_msg)
        if _refusal:
            return "!" + _refusal
        app.cal_add_med(_clause, '1 dose', 'all')
        return (f"medication '{_clause}' added to your calendar's "
                f"medication list")
    med = user_msg.strip()
    # DESTINATION first, the way _fix_add_shopping already does it. Without
    # this, "add insulin to my meds" would put the entire sentence in the
    # medication list as the drug's NAME, and then say so accurately, a true
    # sentence about a useless record.
    med = re.sub(r'(?i)\s*\b(?:to|on|in|onto)\s+(?:my\s+|the\s+)?'
                 r'(?:medications?|medicines?|meds?)(?:\s+list)?\b', ' ', med)
    for prefix in ['add', 'create', 'set']:
        # LONGEST FIRST. With 'medication' ahead of 'a medication reminder',
        # "set a medication reminder for warfarin" would store a drug named
        # "reminder for warfarin", a wrong record the reply then reports
        # accurately, which is the worst of both.
        for word in ['a medication reminder', 'a med reminder',
                     'medication reminder', 'med reminder',
                     'a medication', 'a medicine', 'a med',
                     'medication', 'medicine', 'med']:
            pattern = rf'(?i)^{prefix}\s+{word}\s*(?:for|called|named|:)?\s*'
            med = re.sub(pattern, '', med).strip()
    # ...then a bare leading verb, for the phrasings that name the drug first
    # ("add insulin ...", "track my metformin").
    med = re.sub(r'(?i)^(?:add|create|set|track)\s+(?:my\s+|the\s+)?', '',
                 med).strip()
    med = med.strip(' .,!?')
    if not med or len(med) < 2:
        return None
    # "set up a daily reminder for my medication in the morning" can reach
    # this fallback, lose its leading "set " to the bare-verb rule above and
    # leave the REST OF THE SENTENCE as a would-be medication called
    # "up a daily reminder for my medication in the morning", while the same
    # reply is still asking the household what the medication is called.
    # A schedule phrase is not a drug name, so
    # nothing is written and nothing is claimed: the ask owns that turn
    # (``_try_med_schedule_ask``), and the answer writes the real row.
    if _MED_NOT_A_NAME_RE.search(med) or len(med.split()) > 4:
        return None
    # The SAME screen the fastpath applies, on the whole-sentence fallback too.
    # _verify_and_fix's Case 3 ("requested but never done") calls this
    # function AFTER the fastpath has already declined, so screening only the
    # fastpath would leave /conversation writing the SSN anyway. One screen, every
    # write path into calendar.meds[].
    _refusal = _med_name_refusal(med, source=user_msg)
    if _refusal:
        # "!" prefix = decline with our own full user-facing message rather than
        # silently storing rubbish and reporting success.
        return "!" + _refusal
    app.cal_add_med(med, '1 dose', 'all')
    return (f"medication '{med}' added to your calendar's medication list")


def _fix_add_bill(user_msg, app):
    """Extract bill and add directly."""
    from datetime import timedelta
    bill = user_msg.strip()
    for prefix in ['add', 'create', 'track']:
        for word in ['a bill', 'bill', 'a payment', 'payment']:
            pattern = rf'(?i)^{prefix}\s+{word}\s*(?:for|called|named|:)?\s*'
            bill = re.sub(pattern, '', bill).strip()
    bill = bill.strip(' .,!?')
    if not bill or len(bill) < 2:
        return None
    due = (datetime.now() + timedelta(days=30)).strftime('%Y-%m-%d')
    app.cal_add_bill(bill, '0', due)
    return f"bill '{bill}' added"


# Pattern definitions: (regex matching response text, count key, fix function)
# These match AFFIRMATIVE success claims only — refusals are handled
# separately via _REFUSAL_RE + _USER_INTENT_PATTERNS below. (A refusal like
# "none of the provided functions can be used to set a timer" would otherwise
# match 'set.*timer' here, silently create the timer, and leave the "I can't"
# reply intact, the user told no while a timer ran.)
_VERIFY_PATTERNS = [
    (r'(?i)task\s+added|added.*task|created.*task|set.*task', 'tasks', _fix_add_task),
    (r'(?i)reminder\s+set|set.*reminder|created.*reminder|added.*reminder|remind.*at\s+\d', 'tasks', _fix_add_task),
    (r'(?i)event\s+added|added.*event|created.*event|scheduled.*event', 'events', _fix_add_event),
    (r'(?i)timer\s+set|set.*timer|created.*timer|started.*timer', 'alarms', _fix_add_timer),
    (r'(?i)alarm\s+set|set.*alarm|created.*alarm', 'alarms', _fix_add_alarm),
    (r'(?i)added.*pantry|pantry.*added|added.*to.*pantry', 'pantry', _fix_add_pantry),
    (r'(?i)added.*shopping|shopping.*added|added.*to.*shopping|added.*to.*list', 'shopping', _fix_add_shopping),
    (r'(?i)recipe\s+created|created.*recipe', 'recipes', None),
    (r'(?i)logged.*workout|workout.*logged', 'workouts', None),
    (r'(?i)medication\s+added|added.*med|med.*added', 'meds', _fix_add_med),
    (r'(?i)bill\s+added|added.*bill', 'bills', _fix_add_bill),
]

# Response text that signals the LLM DECLINED or claimed inability —
# such a response must never be treated as a success claim.
_REFUSAL_RE = re.compile(
    r"(?i)\b(?:can(?:'|no)?t\b|cannot\b|unable to\b|not able to\b|"
    r"no (?:such )?(?:function|tool|way)\b|"
    # the model words this many ways: "none of the provided functions",
    # "none of the functions provided in the list pertain to", ...
    r"none of the\b[^.!?]{0,50}\b(?:functions?|tools?)\b|"
    r"none of the (?:provided|available)\b|"
    r"(?:functions?|tools?)\b[^.!?]{0,30}\b(?:pertain|relate)\b|"
    r"not equipped\b|"
    r"n't have (?:a|the|any)\b|not have (?:a|the|any)\b|"
    r"couldn'?t\b|could not\b|failed to\b|"
    r"not (?:currently )?(?:possible|supported|available)\b|"
    r"device'?s built-?in)")

# Response text that PROMISES a future action ("I'll set an alarm...")
# without a clarifying question — the model then ends the turn having done
# nothing. Treated like a refusal: do the work, say what was done.
_FUTURE_BLUFF_RE = re.compile(
    r"(?i)\b(?:i'?ll|i will|let me|going to|about to)\b"
    r"[^.!?]{0,60}\b(?:set|add|create|schedule|remind|start)\b")

# A real clarifying question means the conversation is still open —
# don't preempt it with a direct fix.
_CLARIFYING_RE = re.compile(
    r"(?i)\b(?:should i|what time|how long|which one|what duration|"
    r"when (?:do|should)|do you want me to|would you like me to)\b")

# Questions ABOUT items ("what timers do I have?", "did you set that
# timer?") must never trigger a create-fix.
_QUERY_MSG_RE = re.compile(
    r"(?i)^\s*(?:what|which|when|where|how many|do i|did i|did you|"
    r"have you|are you|is there|are there|list|show|tell me|any)\b")

# Delete/cancel intents must never trigger a CREATE-fix — "delete the
# timer for seven minutes" matches the timer create-intent regex and
# once re-created the exact timer the user asked to remove. Guarded
# PER DOMAIN: "set a timer and turn off the lights" must still allow
# the timer fix (a blanket verb check once blocked it).
_DELETE_VERBS = (r"(?:delete|remove|cancel|dismiss|stop|clear|"
                 r"get rid of|turn off)")
_KEY_NOUNS = {
    'alarms': r"timers?|alarms?|countdowns?",
    'tasks': r"tasks?|reminders?|to-?dos?",
    'events': r"events?|appointments?|meetings?",
    'pantry': r"pantry",
    'shopping': r"shopping(?:\s+list)?|grocery|groceries",
    'meds': r"medications?|meds?|medicines?",
    'bills': r"bills?|payments?",
}


def _delete_intent_for_key(key, user_msg):
    """True when the user asks to delete/cancel an item of THIS kind."""
    noun = _KEY_NOUNS.get(key)
    if not noun:
        return False
    return bool(re.search(
        rf"(?i)\b{_DELETE_VERBS}\b[^.?!]{{0,30}}\b(?:{noun})\b",
        user_msg or ""))

# What the USER asked for: (user-message regex, count key, fix fn, label).
# Used when the LLM refuses an action we can perform directly.
_USER_INTENT_PATTERNS = [
    # Indirect "don't let me forget / leave in N minutes" → countdown timer
    (r"(?i)\b(?:don'?t|do not)\s+(?:let me\s+)?forget\b"
     r"|\bmake sure i\b.{0,30}\bforget\b", 'alarms', _fix_add_timer, 'timer'),
    (r'(?i)\b(?:set|start|create|make|put on)\b.{0,40}\btimer\b'
     r'|\btimer\b.{0,25}\b(?:for|of)\b', 'alarms', _fix_add_timer, 'timer'),
    (r'(?i)\b(?:set|create|make)\b.{0,40}\balarm\b|\bwake me\b',
     'alarms', _fix_add_alarm, 'alarm'),
    (r'(?i)\bremind me\b|\b(?:add|create)\b.{0,30}\b(?:task|to-?do)\b',
     'tasks', _fix_add_task, 'reminder'),
    (r'(?i)\b(?:add|create|schedule|put)\b.{0,50}\b(?:event|appointment|meeting)\b',
     'events', _fix_add_event, 'event'),
    (r'(?i)\badd\b.{0,40}\bpantry\b', 'pantry', _fix_add_pantry, 'pantry item'),
    (r'(?i)\badd\b.{0,40}\b(?:shopping|grocery)\b',
     'shopping', _fix_add_shopping, 'shopping item'),
    # ``meds`` (plural) is how people actually say it — "add insulin to my
    # meds". Without it the intent gate refused, the repair never ran, and a
    # model reply of "Medication added." was left standing over an unchanged
    # calendar: a claim to have kept a medication that was not kept. Widening
    # the medication NOUN cannot misroute to another kind of item, and the
    # delete-intent guard above is untouched.
    (r'(?i)\b(?:add|track|set)\b.{0,30}\b(?:medications?|medicines?|meds?)\b',
     'meds', _fix_add_med, 'medication'),
    (r'(?i)\b(?:add|track)\b.{0,30}\b(?:bill|payment)\b',
     'bills', _fix_add_bill, 'bill'),
]


def _user_intent_matches(key, user_msg):
    """True when the USER's message plausibly requested an action of
    this count-key's kind. Gates every direct fix: response text alone
    must never decide WHAT gets created, and a delete/cancel request
    for this kind of item never justifies creating one."""
    if _delete_intent_for_key(key, user_msg):
        return False
    for pattern, k, _fn, _label in _USER_INTENT_PATTERNS:
        if k == key and re.search(pattern, user_msg or ""):
            return True
    return False


def _verify_and_fix(user_msg, response, before_counts):
    """Verify claimed actions actually happened; execute directly if not.

    Two failure modes, both corrected HONESTLY (the reply always ends up
    matching reality — no silent mutations):
      1. Hallucinated success: response claims an action but no data
         changed → execute directly; if that also fails, append a
         correction so the user isn't left believing the claim.
      2. Wrongful refusal: response says "I can't" but the user clearly
         asked for something we can do directly → do it and REPLACE the
         refusal with a confirmation (or, if we can't parse the request,
         ask for the missing detail instead of leaving a dead-end "no").
    """
    from puffpai.app_data import AppData
    app = AppData()
    after_counts = _snapshot_counts(user_msg)

    fixes = []
    refused = bool(_REFUSAL_RE.search(response))
    bluffed = bool(_FUTURE_BLUFF_RE.search(response)
                   and not _CLARIFYING_RE.search(response))

    if (refused or bluffed) and not _QUERY_MSG_RE.match(user_msg or ""):
        # ── Case 2: wrongful refusal, or a promised-but-not-done action ──
        for pattern, key, fix_fn, label in _USER_INTENT_PATTERNS:
            if fix_fn is None or not re.search(pattern, user_msg) \
                    or _delete_intent_for_key(key, user_msg):
                continue
            if after_counts.get(key, 0) > before_counts.get(key, 0):
                # Something already landed despite the refusal text —
                # correct the reply, don't double-create.
                response = (f"Done — your {label} is saved. "
                            f"(My first answer said otherwise; that was wrong.)")
                logger.info("Refusal contradicted by data change for '%s'; "
                            "response corrected", label)
                break
            try:
                result = fix_fn(user_msg, app)
            except Exception as e:
                logger.warning("Refusal-fix failed for %s: %s",
                               fix_fn.__name__, e)
                break
            if result and result.startswith("!"):
                # Fix declined with its own full user-facing message
                # (e.g. the >24h alarm explanation) — use it verbatim.
                response = result[1:]
                logger.info("Refusal-fix declined with message: %s",
                            result[1:80])
            elif result:
                response = f"Done — {result}."
                logger.info("Refusal-fix applied: %s", result)
            else:
                # We know what they want but couldn't parse the details.
                # Ask, instead of refusing outright.
                response = (f"I can set that {label}, but I didn't catch "
                            f"the specifics — could you say it again with "
                            f"the details? For example: 'set a timer for "
                            f"10 minutes'.")
                logger.info("Refusal-fix needs detail for '%s'", label)
            break
        return response

    # ── Case 1: hallucinated success claims ──
    # Listing replies to "what timers do I have?" legitimately contain
    # phrases like "alarm set for 6:45 AM" with no data change — never
    # treat answers to query messages as action claims.
    if _QUERY_MSG_RE.match(user_msg or ""):
        return response

    # Only completed-action statements count as claims. Clarifying
    # questions and stated intentions ("Let me set an alarm... Should I
    # use the current time?") leave the conversation open — appending a
    # "that did NOT save" correction to a question reads as nonsense.
    # Kept as a LIST: patterns must match within ONE sentence. Matching
    # the joined text let ".*" span sentences ("...was added. ...want to
    # see the list") and fire wildly unrelated fixes.
    claim_sentences = [
        s for s in re.split(r'(?<=[.!?])\s+', response)
        if not s.rstrip().endswith('?')
        and not re.search(r"(?i)\b(?:let me|let'?s|i'?ll|i will|should i|"
                          r"would you like|do you want|going to|about to|"
                          r"i can(?: also)?)\b", s)]

    correction_added = False
    for pattern, key, fix_fn in _VERIFY_PATTERNS:
        if any(re.search(pattern, s) for s in claim_sentences):
            before = before_counts.get(key, 0)
            after = after_counts.get(key, 0)
            if after <= before:
                # LLM claimed it did something but data didn't change.
                # Only repair when the USER actually asked for this kind
                # of action — a claim-shaped sentence about key X must
                # never create an X from an unrelated request (a timer
                # request once became a shopping-list item this way).
                result = None
                if fix_fn is not None and _user_intent_matches(key, user_msg):
                    try:
                        result = fix_fn(user_msg, app)
                        if result and result.startswith("!"):
                            response += "\n\n" + result[1:]
                            # A decline IS a correction. Without this, Case 3
                            # below ("not fixes and not correction_added") would
                            # run the same fix again and append the identical
                            # sentence a second time.
                            correction_added = True
                            logger.info("Verify-fix declined: %s", result[1:80])
                        elif result:
                            fixes.append(result)
                            logger.info("Verify-fix applied: %s", result)
                    except Exception as e:
                        logger.warning("Verify-fix failed for %s: %s",
                                       fix_fn.__name__, e)
                if (fix_fn is not None and not result and not correction_added
                        and _user_intent_matches(key, user_msg)):
                    # Claim stands but nothing was saved and we couldn't
                    # repair it — tell the user instead of letting the
                    # bluff through.
                    response += ("\n\nCorrection: I double-checked and that "
                                 "did NOT actually save. Please try again "
                                 "with the full details.")
                    correction_added = True
                    logger.warning(
                        "Hallucinated claim not repairable (key=%s)", key)

    # ── Case 3: requested but never done ──
    # The user clearly asked for one of the actions we can perform, the
    # data shows it never happened, and neither the response text nor the
    # cases above repaired it (the model may have rambled, called the
    # wrong tool, or gotten stuck). The user's request is the source of
    # truth — do the work and say so. Skipped when the reply asked a real
    # clarifying question (conversation still open).
    if not fixes and not correction_added \
            and not _CLARIFYING_RE.search(response):
        for pattern, key, fix_fn, label in _USER_INTENT_PATTERNS:
            if fix_fn is None or not re.search(pattern, user_msg or "") \
                    or _delete_intent_for_key(key, user_msg):
                continue
            if after_counts.get(key, 0) > before_counts.get(key, 0):
                break  # it did happen — response presumably covers it
            try:
                result = fix_fn(user_msg, app)
            except Exception as e:
                logger.warning("Intent-fix failed for %s: %s",
                               fix_fn.__name__, e)
                break
            if result and result.startswith("!"):
                response += "\n\n" + result[1:]
                logger.info("Intent-fix declined (%s): %s", label, result[1:80])
            elif result:
                fixes.append(result)
                logger.info("Intent-fix applied (%s): %s", label, result)
            break

    # ── Automations: response claims a schedule that was never created ──
    # The Sentinel deny-path sometimes ends with the model narrating
    # success anyway ("the lamps will now turn off at 11 PM"). The
    # automation count is snapshotted whenever the message mentions
    # automations; unchanged count + success-claim = correct the reply.
    if 'automations' in before_counts and re.search(
            r"(?i)\bwill now\b|\bscheduled\b|\bautomation (?:has been|was|"
            r"is) (?:created|set|added)\b|\bcreated the automation\b",
            response):
        try:
            after_autos = len(_get_ha_bridge().get_automations() or [])
            if after_autos <= before_counts['automations']:
                response += (
                    "\n\nCorrection: I checked Home Assistant and that "
                    "automation was NOT actually created — it was most "
                    "likely blocked by the security review. Ask me to "
                    "list automations to confirm what exists.")
                logger.warning("Hallucinated automation claim corrected")
        except Exception as e:
            logger.warning("Automation claim verify failed: %s", e)

    # Detect hallucinated deletes/removes (log only, no auto-fix)
    if re.search(r'(?i)\b(?:deleted|removed)\b', response):
        for key in before_counts:
            before = before_counts.get(key, 0)
            after = after_counts.get(key, 0)
            if after >= before and before > 0:
                logger.warning(
                    "Possible hallucinated delete: LLM claimed removal "
                    "but '%s' count unchanged (%d -> %d)",
                    key, before, after)

    # ── Media: response claims playback — make sure something is ACTUALLY
    # playing. The local LLM sometimes announces "Enjoy the music!" after a
    # failed tool call. If the user asked for playback and nothing is
    # playing: resume a paused session (that's almost always what they
    # meant), otherwise correct the claim honestly instead of letting the
    # bluff reach the user.
    wants_playback = (
        re.search(r"(?i)\b(?:resume|unpause)\b", user_msg)
        or (re.search(r"(?i)\bplay(?!ing|ed)\w*\b|\bput on\b", user_msg)
            and re.search(r"(?i)\b(?:music|song|songs|playlist|album|artist|"
                          r"track|it|that|something)\b", user_msg))
    )
    claims_playback = re.search(
        r"(?i)\bnow playing\b|\bplaying\b|\benjoy\b|\bhere we go\b|"
        r"\bstarted\b|\bresum", response)
    if wants_playback and claims_playback:
        try:
            from puffpai.media_bridge import get_media_bridge
            bridge = get_media_bridge()

            def _sessions_fresh():
                bridge._cache.invalidate()  # now_playing() has a 5s TTL cache
                return bridge.now_playing()

            sessions = _sessions_fresh()
            if not any(s.now_playing and not s.is_paused for s in sessions):
                time.sleep(2)  # a just-issued PlayNow can take a moment
                sessions = _sessions_fresh()
            if not any(s.now_playing and not s.is_paused for s in sessions):
                paused = [s for s in sessions if s.now_playing and s.is_paused]
                if paused:
                    bridge.playback_control(paused[0].session_id, "resume")
                    logger.info("Verify-fix: resumed paused media session %s",
                                paused[0].session_id)
                else:
                    logger.warning(
                        "Hallucinated playback claim — nothing playing; "
                        "correcting response")
                    response += (
                        "\n\nCorrection: I just checked the media server and "
                        "playback did NOT actually start — nothing is playing "
                        "right now. Make sure the Media page is open on the "
                        "dashboard, then ask me again."
                    )
        except Exception as e:
            logger.warning("Media playback verify failed: %s", e)

    # Never apply a fix silently: if the response text was anything but a
    # clean success statement, the user must still hear what actually
    # happened. (A refusal variant the regex missed once slipped through
    # here — timer created, user told "I can't set timers".)
    if fixes:
        logger.info("Auto-verified fixes applied: %s", "; ".join(fixes))
        response += "\n\nConfirmed done: " + "; ".join(fixes) + "."

    return response


# ── Central voice query orchestrator ─────────────────────────────────────────

def _looks_multi_step(user_message):
    """True when a request names more than one action (mirrors the Concierge's
    own _MULTI_STEP_RE, imported to avoid drift). Best-effort: never raises."""
    if not user_message:
        return False
    try:
        from puffpai.agents.concierge import _MULTI_STEP_RE
    except Exception:
        return False
    return bool(_MULTI_STEP_RE.search(user_message))


def _requester_for(user_id) -> str:
    """The agent-bus requester for a served turn: the AUTHENTICATED principal
    (owner / the second adult), never a client-supplied value.

    This is the identity the Archivist scopes Zone-1 (vault RAG) by, so it MUST
    derive only from ``_caller_user()`` (HMAC-vouched). ``None`` / unknown ->
    owner. With the flag OFF this ALWAYS returns the owner (defense-in-depth:
    even a stale user_id can never scope a non-owner while multi-user is off),
    so behavior is byte-for-byte as today."""
    try:
        from puffpai.security.multiuser import (
            multiuser_enabled, caller_principal, OWNER_USER_ID)
        if not multiuser_enabled():
            return OWNER_USER_ID
        return caller_principal(user_id)
    except Exception:
        return "owner"


def _try_composed_plan(user_message, conversation_history=None, *,
                       requester="owner"):
    """Give the Concierge planning loop first refusal on a multi-step request.

    Returns the plan's report string ONLY when the loop executed at least one
    step; otherwise None so the caller keeps its original route. The single-tool
    "agent" route already reaches the loop through _try_team_chat — this exists
    for the multi-step requests the router sent to briefing/library/rag. Never
    raises: a failure degrades to the original route, never escalates.

    ``requester`` is the authenticated principal; it scopes any Zone-1 access the
    planned steps make (via the Archivist), so it must never be a client value.
    """
    if not _chat_via_team_enabled():
        return None
    try:
        reply = _route_via_concierge(user_message, requester=requester,
                                     history=conversation_history)
    except Exception as exc:
        logger.debug("composed-plan routing failed: %s", exc)
        return None
    if not isinstance(reply, dict) or not reply.get("handled"):
        return None
    text = reply.get("reply")
    if not text:
        return None
    plan = reply.get("plan") or {}
    stop = str(plan.get("stop_reason") or "")
    try:
        executed = int(plan.get("executed") or 0)
    except (TypeError, ValueError):
        executed = 0
    # Override the original route ONLY when the loop actually COMPLETED the
    # composed workflow. A plan that stalls into a clarification, or gets stuck
    # after a reconnaissance list_devices, is not better than the briefing/LLM
    # answer the router already chose for this turn — and for a knowledge or
    # briefing question it is worse. Those degrade back to their original route
    # untouched. This keeps the interceptor high-precision: it speaks up only
    # when it genuinely executed the multi-step request end to end.
    if stop != "goal_satisfied" or executed < 1:
        return None
    print(f"[Voice] Composed plan satisfied goal in {executed} step(s) -> "
          f"{reply.get('targets')}")
    return str(text)


# Per-request stash of the full (un-truncated) voice answer, so the transcript
# can hold the whole reply while TTS speaks only the shortened version.
_voice_full_tl = threading.local()


def _clear_voice_full_text() -> None:
    """Start every turn with no stashed reply.

    Worker threads are reused, and some turns (a PIN answer, a pure PII
    disclosure) never reach the code that sets the stash. Without this, such
    a turn would record the PREVIOUS turn's full reply, a directions list for
    example, as its own transcript text.
    """
    _voice_full_tl.text = None


# Every HTTP entry point (chat, voice, Home Assistant, Send to Puff) begins
# clean; returns None, so it never answers a request itself.
app.before_request(_clear_voice_full_text)


def _process_voice_query(user_message, conversation_history=None, *,
                         user_id=None, conversation_id=None):
    """
    Full PuffPAI pipeline for a voice query.
    Routes through persona, tools, RAG, and Ollama as appropriate.
    Returns voice-cleaned response text.

    ``user_id`` (multi-user, Increment 1): when the flag is on, the caller's own
    long-term memory is injected into the persona and this turn is recorded into
    the caller's memory. No-op with the flag off (byte-for-byte as today).
    """
    _clear_voice_full_text()
    _pin_reply = _ha_pin_intercept(user_message, conversation_id, consume=False)
    if _pin_reply is not None:
        return _pin_reply
    persona = _augment_persona_with_memory(_system_prompt(), user_id)
    _remember_for_user(user_id, user_message)
    # The agent-bus requester is the AUTHENTICATED principal, so the Archivist
    # scopes Zone-1 (vault RAG) to the real caller — never a default/client id.
    requester = _requester_for(user_id)
    route = _detect_route(user_message, conversation_history)
    _log_turn_text(f"[Voice] Route: {route}", "[Voice] Turn text:",
                   user_message)

    # Same post-route attribution hook as `_process_chat_query`: without a
    # turn scope, voice turns would write nothing to the Agent Team feed
    # although voice is the primary surface. `begin_turn` is
    # itself the nested-scope guard — a recursive call below (each compound
    # clause re-enters this function) JOINS the outer scope instead of opening
    # a second one, and only the outermost `end_turn` writes.
    # Pre-bound so the speech-budget decision below is safe on the error path
    # (the except clause replaces `response` without these ever being set).
    compound = instant = docs = None
    composed = None
    _chat_activity.begin_turn()
    # The same scope for the turn's own memory: which citations this answer
    # carried, and which confirmation sentences the write fastpaths spoke. Read
    # back by _try_source_citation ("where did you find that") and
    # _try_recent_activity ("what did you just do"). See puffpai.turn_context.
    _turn_context.begin(conversation_id)
    try:
        # Sequenced turn carrying an action — clause by clause, each action
        # confirmed from the entity read back after the call.
        compound = _try_compound_request(
            user_message,
            lambda clause: _process_voice_query(
                clause, conversation_history, user_id=user_id,
                conversation_id=conversation_id),
            requester=requester)

        instant = None if compound else _try_instant_answer(
            user_message, conversation_history=conversation_history,
            conversation_id=conversation_id)
        # "search my documents for X", ahead of the planner and the legacy
        # agent. Here and not in the agent branch only,
        # because the router sends "search my docs for X" to rag.
        docs = None if (compound or instant) else _try_documents_search(
            user_message)
        # Multi-step composer: catch multi-step requests the router sent to a
        # non-agent route and let the planning loop execute them first. The
        # "agent" route already reaches the loop below via _try_team_chat, so it
        # is deliberately excluded here to avoid planning the turn twice.
        composed = None
        if (not compound and not instant and not docs and route != "agent"
                and _looks_multi_step(user_message)):
            composed = _try_composed_plan(user_message, conversation_history,
                                          requester=requester)

        if compound:
            response = compound

        elif instant:
            response = instant

        elif docs:
            _chat_activity.record_capability("knowledge.documents", "fastpath")
            response = docs

        elif composed is not None:
            response = composed

        elif route == "briefing":
            tools = _get_assistant_tools()
            response = tools.daily_briefing()

        elif route == "agent":
            # Knowledge-library search ahead of the team, same as the text
            # path — spoken or typed, the store is the same one.
            knowledge = _try_knowledge_search(user_message,
                                              conversation_history, persona)
            team = None if knowledge else _try_team_chat(
                user_message, route, requester=requester,
                history=conversation_history)
            direct = None if (knowledge or team) else _try_direct_handle(
                user_message)
            if knowledge:
                response = knowledge['response']
            elif team:
                response = team['response']
            elif direct:
                response = direct
            else:
                before_counts = _snapshot_counts(user_message)
                tools = _get_assistant_tools()
                response = tools.run(user_message, conversation_history or [])
                response = _verify_and_fix(user_message, response, before_counts)

        elif route == "library":
            response = _get_indexed_libraries_direct()

        else:  # "rag"
            response = _query_ollama_direct(
                user_message, conversation_history, persona)

    except Exception as e:
        print(f"[Voice] Error in processing: {e}")
        response = f"Sorry, something went wrong: {e}"
    finally:
        # Never raises (chat_activity swallows its own failures), so the feed
        # can neither change a reply nor mask the error path above it.
        _chat_activity.end_turn(route)

    # Post-process for voice output. Stash the FULL (markdown-stripped but
    # un-truncated) text on a thread-local so the caller can record the whole
    # answer to the transcript while only SPEAKING the shortened version, so
    # the complete reply can still be read.
    response = _clean_response(response)
    try:
        _voice_full_tl.text = clean_for_voice(response, max_length=10 ** 9)
    except Exception:
        _voice_full_tl.text = None
    # Directions: the instant answer is the full step list, which the
    # transcript and the household thread keep word for word; a SPOKEN turn
    # says two sentences of it (distance and time, the first turn), held to
    # the voice budget, then points at the screen and the chat.
    if instant and _current_turn_surface() == "voice":
        _spoken = _maps_spoken_reply(instant)
        if _spoken:
            _voice_full_tl.text = instant
            response = _spoken
    # Speech budget. ONLY the open-ended routes: a fastpath
    # answer ("it's ten past three") is already one sentence, a briefing is a
    # briefing, and a read-back the user asked for must be read back. A
    # document search is capped whatever its route: it lists every match. Its
    # TOPIC is not a read-back request ("search my documents for the list of
    # chores"), so the read-back test sees the request without it.
    list_text = user_message or ""
    if docs:
        try:
            from puffpai.agents import document_reads
            list_text = document_reads.without_topic(list_text)
        except Exception as exc:
            logger.debug("document topic strip failed: %s", exc)
    if ((route in ("rag", "agent") or docs) and not compound and not instant
            and composed is None
            and not _VOICE_LIST_READ_RE.search(list_text)):
        response = _cap_spoken_reply(response,
                                     tail=VOICE_TRUNCATION_TAIL_SCREEN)
    # The truncation tail may promise the screen HERE and only here: the caller
    # of this function (`/api/chat`, `/conversation`) records the full text via
    # _record_voice_turn into the dashboard live-transcript panel, so "the rest"
    # genuinely is somewhere the household can read it.
    response = clean_for_voice(response, tail=VOICE_TRUNCATION_TAIL_SCREEN)
    return response


# ── Direct handlers for common queries ─────────────────────────────────────
# Small LLMs struggle with 73 tools. For common query patterns we bypass
# the agent entirely and call the tool directly, then have the LLM
# summarize the raw result.

_SELF_REFERENCE_RE = re.compile(
    r"\byour\s+(?:own\s+)?(?:dashboard|agents?|agent\s+team|team|model|llm|"
    r"brain|capabilities)\b"
    r"|\bdo you have\b.{0,24}\b(?:dashboard|agents?|team)\b"
    r"|\b(?:which|what)\s+(?:model|llm)\b"
    r"|\babout (?:yourself|you)\b"
    r"|\bwho (?:are|made) you\b"
    r"|\bwhat can you do\b")

_TIME_QUESTION_RE = re.compile(
    r"(?i)\bwhat\s+time\s+is\s+it\b|\bwhat(?:'s|\s+is)\s+the\s+time\b|"
    r"\bcurrent\s+time\b|\btime\s+right\s+now\b|"
    r"\bwhat\s+day\s+is\s+(?:it|today)\b|"
    r"\bwhat(?:'s|\s+is)\s+(?:today'?s\s+)?date\b|\btoday'?s\s+date\b")


def _try_time_answer(user_message: str) -> str | None:
    """Clock/date questions answered from the box's own clock — no LLM.

    The agent team has no clock capability, so "what time is it" made the
    planner flail (web_search → egress refused; on retry a needless
    human.ask). Checked before routing: every phrasing gets the clock, and
    tight word boundaries keep "what time is the meeting" and "set a timer"
    on their own paths.
    """
    if not _TIME_QUESTION_RE.search(user_message or ""):
        return None
    now = datetime.now()
    clock = now.strftime("%I:%M %p").lstrip("0")
    return f"It's {clock} on {now.strftime('%A, %B %d')}."


_WEATHER_WORD_RE = re.compile(r"(?i)\b(?:weather|forecast)\b")
_OUTDOOR_CONDITION_RE = re.compile(
    r"(?i)\b(?:temperature|temp|hot|cold|warm|rain(?:ing)?|snow(?:ing)?|"
    r"humid|humidity|degrees|windy|sunny)\b")
_OUTDOOR_MARKER_RE = re.compile(
    r"(?i)\b(?:outside|outdoors?|out there|today|tonight|tomorrow|"
    r"this (?:week|weekend|morning|afternoon|evening))\b")
_INDOOR_RE = re.compile(
    r"(?i)\b(?:living\s?room|bed\s?room|kitchen|garage|hallway|basement|"
    r"in here|inside|indoors?|in the house|in my room|the room)\b")

# ── Conversational weather ───────────────────────────────────────────────────
# "what is the weather like right now" and "will it rain today" reach the real
# forecast. "do I need a jacket today" has no weather word and no
# outdoor-condition word, so it would fall through to RAG, which cites a
# fleece teardown guide, a dictionary entry and household uploads, and
# answers nothing. The question is a weather question (it is how a family
# actually asks one), and the answer is in the forecast the appliance already has.
#
# Two shapes, both requiring a DECISION, never a bare noun: "jacket" alone is a
# laundry question.
_WEATHER_ATTIRE_RE = re.compile(
    r"(?i)\b(?:jacket|coat|raincoat|umbrella|sweater|sweatshirt|hoodie|"
    r"sunscreen|sunglasses|boots|gloves|mittens|scarf|shorts|"
    r"long\s+sleeves?|rain\s*gear|snow\s*gear)\b")
_WEATHER_DECISION_RE = re.compile(
    r"(?i)\b(?:do\s+i\s+need|do\s+we\s+need|will\s+i\s+need|will\s+we\s+need|"
    r"should\s+i|should\s+we|do\s+the\s+kids\s+need|need\s+an?\b|"
    r"bring\s+an?\b|wear\s+an?\b|grab\s+an?\b|take\s+an?\b)")
#: "is it hot out", "how cold is it out there" — a condition word plus a bare
#: "out". Kept as its own pattern rather than adding "out" to the marker list,
#: which would fire on "we are out of milk".
_WEATHER_BARE_OUT_RE = re.compile(
    r"(?i)\b(?:hot|cold|warm|chilly|freezing|muggy|humid|nice|windy|rainy|"
    r"wet|icy|sunny)\s+out\b")


# ── Air quality ─────────────────────────
# "what's the air quality outside today" reached `Route: agent`, and the model
# — whose weather tool it never bound — asked the owner for a city. The very
# next turn, "what's the temperature outside", took this fastpath and reported
# "AQI 41 – Good" for the configured location. The number was always here; the
# PHRASING never reached the weather path. So: air-quality words join the
# match set, and an air-quality question gets a short spoken answer built
# straight from the payload — no summarizer, because "41, good" needs no model
# and the LLM is what invented the location question in the first place.
_AIR_QUALITY_RE = re.compile(
    r"(?i)\bair\s+quality\b|\baqi\b|\bair\s+(?:quality\s+)?index\b|"
    r"\bpollution\b|\bpolluted\b|\bsmog(?:gy)?\b|"
    r"\bsmoke\s+in\s+the\s+air\b|\bsmoky\s+out(?:side)?\b|"
    r"\bpollen\b|\ballergens?\b|"
    r"\bis\s+the\s+air\s+(?:ok|okay|safe|clean|bad|good|healthy|breathable)\b|"
    # Voice transcripts arrive with the apostrophe dropped ("hows the air
    # outside" is what the box's own ASR produced), so all three spellings of
    # the contraction count.
    r"\bhow(?:['’]?s|\s+is)\s+the\s+air\b")
#: Appliances with "air" in the name. These are home-control or cooking turns
#: and must keep their own paths: "is the air conditioner on", "turn on the
#: air purifier", "what's in the air fryer".
_AIR_DEVICE_RE = re.compile(
    r"(?i)\bair\s+(?:conditioner|conditioning|condition|fryer|purifier|"
    r"filter|cleaner|freshener|mattress|compressor|pump|handler)\b"
    r"|\ba/?c\s+unit\b")
#: One clause of advice, only where the category warrants it. "Good" gets
#: none — a healthy reading should not come with a caveat.
_AQI_ADVICE = {
    "moderate": "Fine for most people; anyone sensitive might take it easy "
                "outside.",
    "unhealthy (sensitive)": "Sensitive groups should limit time outdoors.",
    "unhealthy": "Everyone should limit time outdoors.",
    "very unhealthy": "Stay inside if you can.",
    "hazardous": "Stay inside.",
}


def _air_quality_question(lower: str) -> bool:
    """True when the turn is asking about the AIR, not about an appliance."""
    if _AIR_DEVICE_RE.search(lower):
        return False
    return bool(_AIR_QUALITY_RE.search(lower))


def _home_city() -> str:
    """The configured location, short form, or '' when no town is set.

    Never a question back, and never an assumed city: callers phrase the
    empty case without a place name.
    """
    try:
        from puffpai.config import get_config as _get_cfg
        loc = (_get_cfg().location or "").strip()
    except Exception:
        loc = ""
    return loc.split(",")[0].strip() or loc


def _air_quality_answer(user_message: str) -> str:
    """Short, speakable air-quality reply from the dashboard's own payload.

    Leads with the number and the category, names the configured city, and
    NEVER asks where the owner lives — the location is in config, and asking
    for it was the whole defect. When there is no reading it says so plainly.
    """
    city = _home_city()
    # No town set: the reply simply names no place, rather than a guessed one.
    for_city = f" for {city}" if city else ""
    env: dict = {}
    try:
        from puffpai import dashboard_widgets as _dwid
        env = _dwid.fetch_environment() or {}
    except Exception as exc:
        logger.debug("air-quality fastpath payload failed: %s", exc)
    aqi = env.get("us_aqi")
    if not isinstance(aqi, (int, float)):
        if env.get("unset"):
            return (f"I don't have an air-quality reading{for_city}. "
                    f"{env['unset']}")
        if env.get("blocked"):
            return (f"I don't have an air-quality reading{for_city} right "
                    "now, the air-quality feed is off. Turn it on in "
                    "Settings and I'll read it.")
        return (f"I don't have an air-quality reading{for_city} right now, "
                "nothing came back from the air-quality feed.")
    label = str(env.get("aqi_label") or "").strip()
    lead = f"Air quality outside is {round(aqi)}"
    if label:
        lead += f", {label.lower()},"
    lead += f" in {city}." if city else "."
    parts = [lead]
    advice = _AQI_ADVICE.get(label.lower())
    if advice:
        parts.append(advice)
    if "pollen" in user_message.lower() or "allergen" in user_message.lower():
        pollen = (env.get("air_breakdown") or {}).get("pollen")
        if isinstance(pollen, dict) and pollen.get("label"):
            parts.append(f"Pollen risk is {str(pollen['label']).lower()}"
                         + (f" ({pollen['detail']})." if pollen.get("detail")
                            else "."))
    return " ".join(parts)


#: The attire question is answered DIRECTLY, from the same forecast the full
#: answer reads. Otherwise "Do I need a jacket outside today?" takes ~25
#: seconds, reads the whole weather snapshot out loud, and puts the actual
#: answer — "a jacket isn't necessary" — last. The person asked a yes/no
#: question; the numbers are the evidence, not the reply.
_ATTIRE_WARM = ("jacket", "coat", "sweater", "sweatshirt", "hoodie", "gloves",
                "mittens", "scarf", "boots", "long sleeves", "long sleeve")
_ATTIRE_RAIN = ("umbrella", "raincoat", "rain gear", "raingear")
_ATTIRE_SUN = ("sunscreen", "sunglasses")
_ATTIRE_COOL = ("shorts",)
#: "currently 87F" / "87F" / "87 degrees" — whatever the tool wrote.
_RAW_TEMP_RE = re.compile(
    r"(?i)\bcurrently\s+(-?\d{1,3})\s*(?:F|degrees)\b|\b(-?\d{1,3})\s*F\b")
_RAW_RAIN_RE = re.compile(
    r"(?i)\b(rain|rainy|showers?|storms?|thunder|drizzle|sleet|snow)\b")
_RAW_RAIN_CHANCE_RE = re.compile(r"(?i)(\d{1,3})\s*%\s*chance\s+of\s+rain")
_RAW_SUNNY_RE = re.compile(r"(?i)\b(clear|sunny|mostly\s+sunny|fair)\b")


def _attire_item(lower: str):
    """(the word the user said, which kind of question it is) or None. Pure."""
    for word in _ATTIRE_RAIN:
        if word in lower:
            return word, "rain"
    for word in _ATTIRE_SUN:
        if word in lower:
            return word, "sun"
    for word in _ATTIRE_COOL:
        if word in lower:
            return word, "cool"
    for word in _ATTIRE_WARM:
        if word in lower:
            return word, "warm"
    return None


def _weather_attire_answer(user_message: str, raw: str) -> "str | None":
    """A one-line yes/no for "do I need a jacket", or None to fall back.

    Pure: the forecast text is the only input. Returns None when the forecast
    does not carry what the question needs, so an unparseable payload keeps
    the existing full answer rather than inventing a verdict.
    """
    item = _attire_item((user_message or "").lower())
    if not item:
        return None
    word, kind = item
    text = raw or ""
    temp = None
    match = _RAW_TEMP_RE.search(text)
    if match:
        try:
            temp = int(match.group(1) or match.group(2))
        except (TypeError, ValueError):
            temp = None

    if kind == "rain":
        chance = _RAW_RAIN_CHANCE_RE.search(text)
        pct = int(chance.group(1)) if chance else None
        wet = (pct is not None and pct >= 40) or (
            pct is None and bool(_RAW_RAIN_RE.search(text)))
        if pct is None and not _RAW_RAIN_RE.search(text) and not text.strip():
            return None
        if wet:
            detail = (f"there's a {pct}% chance of rain today" if pct is not None
                      else "rain is in today's forecast")
            return f"Yes — {detail}, so take {_article(word)} {word}."
        detail = (f"only a {pct}% chance of rain today" if pct is not None
                  else "no rain in today's forecast")
        return f"No — {detail}, so you won't need {_article(word)} {word}."

    if temp is None:
        return None
    if kind == "sun":
        if temp >= 80 or _RAW_SUNNY_RE.search(text):
            return (f"Yes — it's {temp} degrees and clear out, so "
                    f"{word} is a good idea.")
        return f"Probably not — it's {temp} degrees and overcast out."
    if kind == "cool":
        if temp >= 75:
            return f"Yes — it's {temp} degrees out, {word} weather."
        return f"Not really — it's {temp} degrees out."
    if temp < 58:
        return f"Yes — it's {temp} degrees out, so take {_article(word)} {word}."
    if temp < 68:
        return (f"Maybe — it's {temp} degrees out, so a light {word} would "
                f"do it.")
    return f"No — it's {temp} degrees out, so you won't need {_article(word)} {word}."


def _article(word: str) -> str:
    return "an" if str(word or "")[:1].lower() in "aeiou" else "a"


def _try_weather_answer(user_message: str) -> str | None:
    """Outdoor-conditions questions go straight to the weather tool.

    Otherwise "what's the temperature outside?" can resolve to the
    CONCIERGE's house-state rule and be answered with indoor sensors (or an
    ambiguous tie between the bedroom and the openweathermap sensor). The
    forecast tool already knows the location; nothing about this question
    needs a model or a device list. Fires on explicit weather words, or an
    outdoor condition word paired with an outside/when marker — and never
    when the question names a room.
    """
    lower = (user_message or "").lower()
    if len(lower) > 120:
        return None
    air = _air_quality_question(lower)
    if "widget" in lower or "dashboard" in lower:
        # "you can look on your dashboard, it has the air quality readings"
        # went to RAG and came back "I don't have direct access to the live
        # dashboard" — true about the SCREEN, useless about the DATA, which
        # this box reads from the same place the card does. Only an air-quality
        # turn is claimed here; every other dashboard sentence keeps declining,
        # so widget management is untouched.
        if air and not _INDOOR_RE.search(lower):
            return ("I can't see your screen, but I read the same live data "
                    "the dashboard card does. " + _air_quality_answer(
                        user_message))
        return None
    if _INDOOR_RE.search(lower):
        return None
    attire = bool(_WEATHER_ATTIRE_RE.search(lower)
                  and _WEATHER_DECISION_RE.search(lower))
    if not (air
            or _WEATHER_WORD_RE.search(lower)
            or (_OUTDOOR_CONDITION_RE.search(lower)
                and _OUTDOOR_MARKER_RE.search(lower))
            # "do I need a jacket today", "is it hot out".
            or attire
            or _WEATHER_BARE_OUT_RE.search(lower)):
        return None
    # An air-quality question is answered about the AIR, in one line. A plain
    # weather question keeps the full forecast answer (which already carries
    # the AQI clause).
    if air:
        return _air_quality_answer(user_message)
    try:
        tools = _get_assistant_tools()
        raw = tools.tool_dict['auto_weather_forecast'].invoke('')
        # "Do I need a jacket outside today?" is a yes/no question. The
        # forecast still comes from the tool — only the SHAPE of the reply
        # changes, and an unparseable payload falls back to the full answer.
        if attire:
            direct = _weather_attire_answer(user_message, raw)
            if direct:
                return direct
        return _summarize_tool_result(user_message, raw)
    except Exception as exc:
        logger.debug("weather fastpath failed: %s", exc)
        return None


_TIMER_SET_RE = re.compile(
    r"(?i)\b(?:set|start|create|make|give me)\s+(?:a\s+|another\s+|the\s+)?"
    r"(?:[\w-]+\s+){0,3}timer\b")
#: "... timer called pasta" / "named pasta". Without this a custom label is
#: parsed away and the item comes back with the generic duration description,
#: so the person cannot hear their own word repeated.
_TIMER_LABEL_RE = re.compile(
    r"(?i)\b(?:called|named|labell?ed)\s+(?:the\s+|my\s+|it\s+)?"
    r"([A-Za-z0-9][\w '-]{0,30}?)\s*[.!?]?\s*$")
#: "set a pasta timer for 10 minutes" — the word sitting in front of the noun,
#: unless it is part of the duration.
_TIMER_PRENAME_RE = re.compile(
    r"(?i)\b(?:set|start|create|make|give me)\s+"
    r"(?:a\s+|an\s+|another\s+|the\s+)?((?:[\w-]+\s+){0,3}?)timer\b")
#: Words that are duration, not a name.
_TIMER_NOT_A_NAME = {
    "hour", "hours", "hr", "hrs", "minute", "minutes", "min", "mins",
    "second", "seconds", "sec", "secs", "new", "quick", "short", "long",
    "another", "more", "a", "an", "the",
}


def _timer_label(user_message: str) -> "str | None":
    """The name the person gave this timer, or None if they gave none."""
    text = (user_message or "").strip()
    if not text:
        return None
    match = _TIMER_LABEL_RE.search(text)
    if match:
        label = match.group(1).strip(" .!?,'\"")
        return label or None
    match = _TIMER_PRENAME_RE.search(text)
    if not match:
        return None
    words = [w for w in match.group(1).split()
             if w.lower() not in _TIMER_NOT_A_NAME
             and not re.fullmatch(r"[\d-]+", w)
             and w.lower() not in _WORD_NUMBERS]
    if len(words) != 1:
        return None            # zero words, or a phrase we cannot vouch for
    return words[0]
_DURATION_RE = re.compile(
    r"(?i)\b(\d+|a|an|one|two|three|four|five|six|seven|eight|nine|ten|"
    r"fifteen|twenty|thirty|forty[- ]?five|forty|sixty|ninety)\s*"
    r"(hours?|hrs?|minutes?|mins?|seconds?|secs?)\b")
_WORD_NUMBERS = {
    "a": 1, "an": 1, "one": 1, "two": 2, "three": 3, "four": 4, "five": 5,
    "six": 6, "seven": 7, "eight": 8, "nine": 9, "ten": 10, "fifteen": 15,
    "twenty": 20, "thirty": 30, "forty": 40, "forty-five": 45,
    "forty five": 45, "sixty": 60, "ninety": 90,
}


def _try_maps_directions(user_message: str,
                         conversation_id: str | None = None) -> str | None:
    """Offline directions: "directions to X", "how do I
    get to X", "how far is X", "nearest X", by car, on foot or by bike, and the
    follow-up "what about walking?" on this conversation's last route.

    Answered from the box's own engines (Photon + Valhalla on loopback) by
    :mod:`puffpai.maps_directions`, which declines anything that is not a
    place ask ("how do I get to sleep", "how far is the moon"). Once it claims
    a turn it always answers it, with steps or an honest miss, so the model
    never answers a directions question from memory. The reply is the full
    chat text; a spoken turn says two sentences of it (see
    ``_process_voice_query``).
    """
    # One decision per request: /chat/stream asks here first and, when this
    # declines, may reach it again through _process_voice_query. A hung
    # engine must cost that wait once per turn, not twice, so the outcome
    # (a reply OR a decline) is kept on flask.g for the request's lifetime.
    cache = None
    key = (str(user_message or ""), str(conversation_id or ""))
    try:
        from flask import g, has_request_context
        if has_request_context():
            cache = g.setdefault("puffpai_maps_turns", {})
            if key in cache:
                return cache[key]
    except Exception:                               # pragma: no cover
        cache = None
    try:
        from puffpai import maps_directions
        reply = maps_directions.answer(user_message,
                                       conversation_id=conversation_id,
                                       source=_current_turn_surface())
    except Exception as exc:
        # TYPE only: never a message that could carry a URL or a point.
        logger.warning("maps fastpath failed: %s", type(exc).__name__)
        reply = None
    if cache is not None:
        cache[key] = reply
    return reply


def _maps_spoken_reply(full_text) -> str | None:
    """The SPOKEN form of a directions answer this thread just produced:
    two sentences held to the voice budget, then the screen-and-chat pointer.
    ``None`` for any other reply. Used by every voice surface (the on-box
    voice unit through _process_voice_query, Home Assistant through /v1)."""
    try:
        from puffpai import maps_directions as _maps
        spoken = _maps.spoken_for(full_text)
    except Exception:
        return None
    if not spoken:
        return None
    return _cap_spoken_reply(spoken) + _maps.SPOKEN_TAIL


def _try_timer_set(user_message: str) -> str | None:
    """"Set a timer for ten minutes" is a countdown, not a thermostat.

    Otherwise the Concierge's set_climate rule pattern-matches "set a timer
    for 10 minutes", claims the turn, and refuses with "no climate device
    called timer", the legacy agent that owns timers never sees the
    request. Only fires when BOTH the timer phrasing and a parseable
    duration are present; anything fuzzier falls through to the LLM path,
    which can ask a real follow-up question.
    """
    lower = (user_message or "").lower()
    if not _TIMER_SET_RE.search(lower):
        return None
    m = _DURATION_RE.search(lower)
    if not m:
        return None
    raw_n, unit = m.group(1), m.group(2)
    try:
        n = int(raw_n)
    except ValueError:
        n = _WORD_NUMBERS.get(raw_n.replace("-", " ").strip(), 0)
    if n <= 0:
        return None
    unit = unit.rstrip("s").lstrip()
    # Label the timer by its duration ("10 minute") — that is how people
    # cancel it ("cancel the ten minute timer"), and the dismiss tool's
    # word-number normalization then matches the label exactly. A label of
    # just "Timer" made duration-cancel come back "no item found" (live).
    kwargs = {"description": "Timer", "minutes": 0, "hours": 0, "seconds": 0}
    if unit.startswith(("hour", "hr")):
        kwargs["hours"] = n
        kwargs["description"] = f"{n} hour"
    elif unit.startswith("sec"):
        kwargs["seconds"] = n
        kwargs["description"] = f"{n} second"
    else:
        kwargs["minutes"] = n
        kwargs["description"] = f"{n} minute"
    # A stated name wins over the duration label: "set a 10 minute timer called
    # pasta" must come back saying "pasta", which is also the word the person
    # will use to cancel it. Unnamed timers keep the duration description that
    # makes "cancel the ten minute timer" resolve.
    label = _timer_label(user_message)
    if label:
        kwargs["description"] = label
    try:
        tools = _get_assistant_tools()
        return tools.tool_dict['app_set_timer'].invoke(kwargs)
    except Exception as exc:
        logger.debug("timer fastpath failed: %s", exc)
        return None


#: Spoken clock times ("seven", "six thirty", "half past seven") read as
#: digits, so the alarm patterns below — all of which want digits — hear
#: what a person actually says. The rule lives in calendar_dates
#: because the calendar parsers need the same one: pure text, no I/O.
from puffpai.calendar_dates import (  # noqa: E402
    normalize_spoken_clock as _normalize_spoken_clock,
    spoken_clock_number as _spoken_clock_number,
)


_ALARM_SET_RE = re.compile(
    r"(?i)\b(?:set|create|make|put on|add)\s+(?:an?\s+|another\s+|the\s+)?"
    r"(?:\w+\s+){0,2}alarm\b"
    r"|\bwake\s+(?:me|us)\s+up\b|\bwake\s+(?:me|us)\b"
    r"|\bget\s+me\s+up\b|\bset\s+my\s+alarm\b")
#: A clock time. Accepts "7am", "7 am", "7:30", "7:30 pm", "noon", "midnight".
_ALARM_TIME_RE = re.compile(
    r"(?i)\b(\d{1,2})(?::(\d{2}))?\s*([ap])\.?\s?m\.?\b"
    r"|\b(?:at|for)\s+(\d{1,2}):(\d{2})\b"
    r"|\b(noon|midnight)\b"
    r"|\b(?:at|for)\s+(\d{1,2})\b"
    r"(?!\s*(?:minutes?|mins?|hours?|hrs?|seconds?|secs?))")
#: Checked BEFORE _ALARM_TIME_RE, so that "for 7:30 pm" still reads as the
#: evening now that a bare "for 7:30" matches too.
_ALARM_MERIDIEM_RE = re.compile(
    r"(?i)\b(\d{1,2})(?::(\d{2}))?\s*([ap])\.?\s?m\.?\b")
_ALARM_REPEAT_RE = re.compile(
    r"(?i)\bevery\s+(?:day|morning|night)\b|\bdaily\b|\beach\s+morning\b")
_ALARM_WEEKDAY_RE = re.compile(
    r"(?i)\bweekdays?\b|\bschool\s+days?\b|\bevery\s+weekday\b")
#: Words that make the sentence a TIMER, a dismissal, or a question rather
#: than "create an alarm". Each keeps its own existing fastpath.
_ALARM_SET_EXCLUDE_RE = re.compile(
    r"(?i)\btimer\b|\bcancel\b|\bdismiss\b|\bdelete\b|\bsnooze\b|\bsilence\b"
    r"|\bturn\s+off\b|\bstop\b|\bwhat\b|\bwhich\b|\blist\b|\bhow\s+many\b"
    r"|\bdo\s+i\s+have\b|\bis\s+there\b|\bfire\s+alarm\b|\bsmoke\s+alarm\b"
    r"|\bcar\s+alarm\b|\bsecurity\s+alarm\b|\bburglar\b|\bsiren\b")


def _parse_alarm_time(text: str) -> "tuple[int, int] | None":
    """(hour24, minute) named by *text*, or None. Pure — no I/O."""
    text = _normalize_spoken_clock(text or "")
    m = _ALARM_MERIDIEM_RE.search(text)
    if m:
        hour = int(m.group(1))
        minute, half = int(m.group(2) or 0), m.group(3).lower()
        if not (1 <= hour <= 12) or minute > 59:
            return None
        if half == "a":
            return (0 if hour == 12 else hour), minute
        return (12 if hour == 12 else hour + 12), minute
    m = _ALARM_TIME_RE.search(text)
    if not m:
        return None
    if m.group(6):                                   # noon / midnight
        return (12, 0) if m.group(6).lower() == "noon" else (0, 0)
    if m.group(1):                                   # 7am / 7:30 pm
        hour, minute, half = int(m.group(1)), int(m.group(2) or 0), m.group(3).lower()
        if not (1 <= hour <= 12) or minute > 59:
            return None
        if half == "a":
            hour = 0 if hour == 12 else hour
        else:
            hour = 12 if hour == 12 else hour + 12
        return hour, minute
    if m.group(4):                                   # at 7:30 (24h or 12h)
        hour, minute = int(m.group(4)), int(m.group(5))
        if hour > 23 or minute > 59:
            return None
        return hour, minute
    if m.group(7):                                   # bare "at 7"
        hour = int(m.group(7))
        if hour > 23:
            return None
        # A bare hour with no am/pm: 1-5 reads as afternoon, 6-11 as morning.
        # This is the only guess in the fastpath and it is stated back to the
        # user in the confirmation the tool returns, so a wrong read is
        # visible and one sentence away from being corrected.
        if 1 <= hour <= 5:
            hour += 12
        return hour, 0
    return None


#: A bare hour that could be either half of the day. Committing "alarm 7" to
#: 7:00 AM on a coin-flip heuristic (1-5 PM, 6-11 AM) and merely SAYING so
#: would give a first-time user testing the mic an unrequested 7 a.m. alarm.
#: Zero time information already asks a clarifying question, so an
#: ambiguous hour asking one too is the consistent behaviour, not a new one.
_ALARM_BARE_HOUR_RE = re.compile(
    r"(?i)(?:^|\b)(?:alarm|wake\s+(?:me|us)(?:\s+up)?|get\s+me\s+up|"
    r"for|at)\s+(\d{1,2})\s*(?::\s*(\d{2}))?\s*"
    r"(?![:\d]|\s*[ap]\.?\s?m|\s*o.?clock\s*(?:in|at)|"
    r"\s*(?:minutes?|mins?|hours?|hrs?|seconds?|secs?))")


def _alarm_hour_is_ambiguous(text: str) -> "int | None":
    """The hour named by *text* if it could be AM or PM, else None. Pure.

    Only 1-11 qualify: "at 19:30" and "at 0:30" name one instant each, and
    "7 am", "noon" and "midnight" carry their own half of the day.
    """
    low = _normalize_spoken_clock((text or "").lower())
    # "Wake me up at 6:45" names the morning by meaning ("wake me up at 6:45
    # tomorrow" -> 6:45 AM): asking there would be pedantry, not care. Nobody says "wake me up" about the evening.
    if re.search(r"(?i)\bwake\s+(?:me|us)\b|\bget\s+(?:me|us)\s+up\b", low):
        return None
    if re.search(r"(?i)\b[ap]\.?\s?m\.?\b|\bnoon\b|\bmidnight\b"
                 r"|\bmorning\b|\bevening\b|\bafternoon\b|\btonight\b"
                 r"|\bat\s+night\b", low):
        return None
    m = _ALARM_BARE_HOUR_RE.search(low)
    if not m:
        return None
    hour = int(m.group(1))
    return hour if 1 <= hour <= 11 else None


def _alarm_row_for(lower: str, hour: int, minute: int) -> "str | None":
    """Write the alarm the sentence describes; AlarmFlow's own reply, or None.

    The one place an alarm is created from a parsed clock time, shared by
    ``_try_alarm_set`` and by the AM/PM answer — so an alarm set by
    answering "PM" carries the same repeat, the same description and the same
    read-back as one set in a single breath.
    """
    repeat = "once"
    if _ALARM_WEEKDAY_RE.search(lower):
        repeat = "weekdays"
    elif _ALARM_REPEAT_RE.search(lower):
        repeat = "daily"
    description = "Wake up" if re.search(r"(?i)\bwake\b|\bget\s+me\s+up\b",
                                         lower) else "Alarm"
    try:
        tools = _get_assistant_tools()
        return tools.tool_dict['app_set_alarm'].invoke(
            {"description": description, "hour": hour, "minute": minute,
             "repeat": repeat})
    except Exception as exc:
        logger.debug("alarm-set fastpath failed: %s", exc)
        return None


def _ask_alarm_half_of_day(hour: int, minute_text: str = "",
                           source_text: str = "") -> str:
    """Ask which half of the day — and REMEMBER that this is what was asked.

    Without the record the answer is thrown away: "PM" routes to the
    knowledge library and comes back defining post-mortem / prime minister /
    private message, and no alarm is created. The record registered here is
    what turns that one word back into an alarm.
    """
    clock = f"{hour}{minute_text}"
    sentence = (f"Did you mean {clock} AM or {clock} PM? Say the one you want "
                f"and I'll set it — I'd rather ask than pick the wrong half "
                f"of the day.")
    minute = int((minute_text or "").lstrip(":") or 0)
    lower = source_text or ""

    def _complete(chosen, said, hour=hour, minute=minute, lower=lower):
        half = (chosen[0]["value"] if chosen else "am")
        return _alarm_row_for(lower, hour % 12 + (12 if half == "pm" else 0),
                              minute)

    try:
        _pending_clarifier.register(
            "alarm_half_of_day", _complete,
            [{"label": "AM", "value": "am",
              "tokens": ["am", "a m", "morning"]},
             {"label": "PM", "value": "pm",
              "tokens": ["pm", "p m", "evening", "night", "afternoon",
                         "tonight"]}],
            prompt=sentence)
    except Exception as exc:      # pragma: no cover - never worth the answer
        logger.debug("alarm clarifier not registered: %s", exc)
    return sentence


def _try_alarm_clarify(user_message: str) -> str | None:
    """Ask instead of guessing when an alarm names an ambiguous hour.

    Runs BEFORE _try_alarm_set (and therefore before the LLM, which would
    otherwise guess a half of the day and write it), and only for a
    sentence that is clearly asking for an alarm. Nothing is written: an
    ambiguous request has no side effect at all until the person answers.
    """
    text = (user_message or "").strip()
    lower = _normalize_spoken_clock(text.lower())
    if len(lower) > 140:
        return None
    if not (_ALARM_SET_RE.search(lower) or re.match(r"(?i)^alarm\b", lower)):
        return None
    if _ALARM_SET_EXCLUDE_RE.search(lower):
        return None
    hour = _alarm_hour_is_ambiguous(lower)
    if hour is None:
        return None
    m = _ALARM_BARE_HOUR_RE.search(lower)
    minute_text = f":{m.group(2)}" if m and m.group(2) else ""
    return _ask_alarm_half_of_day(hour, minute_text, lower)


def _try_alarm_set(user_message: str) -> str | None:
    """"Set an alarm for 7am" is AlarmFlow, not the thermostat.

    Left to the Concierge, "set an alarm for 7am" and "wake me up at 7 in the
    morning" can both resolve to ``set_climate`` and come back "Which
    thermostat do you mean: Bedroom, Living Room?". Even when no thermostat is
    written, a home AI asked for an alarm must not reach for the thermostat
    at all, and this is the single utterance a stranger tries first.

    Fires only when an alarm/wake phrasing AND a parseable clock time are both
    present, and never on a timer, a dismissal, or a question about alarms —
    those keep _try_timer_set and _try_alarm_dismiss. Anything fuzzier falls
    through to the LLM, which can ask a real follow-up.
    """
    if not _app_installed('alarmflow'):
        return None
    text = (user_message or "").strip()
    lower = _normalize_spoken_clock(text.lower())
    if len(lower) > 140 or not _ALARM_SET_RE.search(lower):
        return None
    if _ALARM_SET_EXCLUDE_RE.search(lower):
        return None
    # Never commit to a half of the day we were not told.
    ambiguous = _alarm_hour_is_ambiguous(lower)
    if ambiguous is not None:
        return _ask_alarm_half_of_day(ambiguous, "", lower)
    parsed = _parse_alarm_time(lower)
    if parsed is None:
        return None
    hour, minute = parsed
    return _alarm_row_for(lower, hour, minute)


#: Cancel/undo verbs. "stop"/"silence" are NOT here: those mean "make the
#: noise stop" on a RINGING alarm, which is a dismiss, and _try_alarm_dismiss
#: already owns them.
_ALARM_CANCEL_VERB_RE = re.compile(
    r"(?i)\b(?:cancel|call\s+off|delete|remove|clear|get\s+rid\s+of|"
    r"scrap|undo)\b")
_ALARM_CANCEL_NOUN_RE = re.compile(r"(?i)\balarms?\b")
_ALARM_CANCEL_ALL_RE = re.compile(
    r"(?i)\b(?:all|every|any)\b[^.?!]{0,12}\balarms?\b"
    r"|\balarms?\b[^.?!]{0,6}\ball\b")
_ALARM_CANCEL_JUST_SET_RE = re.compile(
    r"(?i)\b(?:i\s+)?just\s+(?:set|made|created|added)\b"
    r"|\bthe\s+(?:last|latest|new)\s+(?:one|alarm)\b"
    r"|\bthat\s+one\b")


def _fmt_alarm_clock(hour: int, minute: int) -> str:
    h12 = hour % 12 or 12
    return f"{h12}:{minute:02d} {'AM' if hour < 12 else 'PM'}"


def _try_alarm_cancel(lower: str, tools) -> str | None:
    """The reciprocal of _try_alarm_set: cancel an alarm BY THE TIME ASKED.

    After "set an alarm for 6:45 am tomorrow", the obvious undo, "cancel the
    6:45 am alarm", must not come back "No item found matching '6:45 am'."
    with the alarm still armed. Every other identifier path resolves against
    an item's ``desc``, and an alarm created by the fastpath has the literal
    desc "Alarm" -- so the one detail the person actually said is the one
    detail nothing else can match.

    Three shapes, all resolved through the AlarmFlow app API against the
    item's stored hour/minute: by time, "the alarm I just set", and "cancel
    all alarms" (which confirms by naming each alarm it removed). Returns None
    -- leaving the turn to the existing dismiss/delete path -- for anything
    else, including every timer phrasing.
    """
    if not _app_installed('alarmflow'):
        return None
    text = (lower or "").strip()
    if not text or len(text) > 140:
        return None
    if not _ALARM_CANCEL_VERB_RE.search(text):
        return None
    if not _ALARM_CANCEL_NOUN_RE.search(text):
        return None
    if re.search(r"(?i)\btimers?\b", text):
        return None  # timers keep their own path

    try:
        from puffpai.app_data import AppData
        app = AppData()
    except Exception as exc:
        logger.debug("alarm-cancel fastpath: no app data: %s", exc)
        return None

    parsed = _parse_alarm_time(text)
    wants_all = bool(_ALARM_CANCEL_ALL_RE.search(text)) and parsed is None
    wants_last = bool(_ALARM_CANCEL_JUST_SET_RE.search(text)) and parsed is None
    if parsed is None and not wants_all and not wants_last:
        return None

    try:
        clocks = app.alarm_active_clocks()
        if parsed is not None:
            hour, minute = parsed
            ids = app.alarm_ids_at(hour, minute)
            label = f"the {_fmt_alarm_clock(hour, minute)} alarm"
        elif wants_last:
            latest = app.alarm_latest_id()
            ids = [latest] if latest else []
            label = "the alarm you just set"
        else:
            ids = list(clocks)
            label = "your alarms"
    except Exception as exc:
        logger.debug("alarm-cancel fastpath resolution failed: %s", exc)
        return None

    if not ids:
        if parsed is not None:
            return (f"You don't have an alarm set for "
                    f"{_fmt_alarm_clock(*parsed)}, so there's nothing to "
                    f"cancel. Ask me to list your alarms if you want to see "
                    f"what is set.")
        return "You don't have any alarms set right now, so there's nothing to cancel."

    cancelled = []
    for item_id in ids:
        clock = clocks.get(item_id)
        when = _fmt_alarm_clock(*clock) if clock else ""
        try:
            result = tools.tool_dict['app_delete_alarm'].invoke(item_id)
        except Exception as exc:
            logger.debug("alarm-cancel delete failed for %s: %s", item_id, exc)
            continue
        # AppData.alarm_delete names the outcome ("Cancelled and removed
        # 1 item ...") or says "Deleted 1 item.". Both prefixes mean the same
        # success here.
        if str(result).lower().startswith(("deleted", "cancelled", "canceled")):
            cancelled.append(when)

    if not cancelled:
        return (f"I found {label} but couldn't cancel it — try "
                f"\"delete the alarm\" and I'll take another run at it.")
    # "Cancel" is a HARD delete here and "dismiss" is a soft stop, which the
    # manifest could otherwise treat as one concept. Two
    # different outcomes need two different sentences, or a parent who says
    # "cancel the 7am alarm" the night before a trip cannot tell that the
    # alarm is gone rather than silenced for one morning.
    if len(cancelled) == 1 and parsed is not None:
        return (f"Cancelled {label} and removed it from your list — it won't "
                f"ring. (Say \"dismiss\" instead if you only want to stop one "
                f"ring and keep the alarm.)")
    times = ", ".join(w for w in cancelled if w) or f"{len(cancelled)}"
    plural = "alarm" if len(cancelled) == 1 else "alarms"
    return (f"Cancelled and removed {len(cancelled)} {plural} ({times}). None "
            f"of them will ring, and they're off your list.")


#: Snooze, as a DECLARED phrase rather than an LLM improvisation. Left to
#: the model, "snooze" gets an invented duration for an utterance that names
#: none. The default
#: is the alarm-clock nine minutes (``AppData.alarm_snooze``'s own default),
#: overridable by the owner and by the sentence itself.
_ALARM_SNOOZE_RE = re.compile(
    r"(?i)\bsnooze\b|\bfive\s+more\s+minutes\b|\ba\s+few\s+more\s+minutes\b"
    r"|\b(?:just\s+)?a\s+bit\s+longer\b|\bgive\s+me\s+(?:\d+|\w+)\s+more\s+minutes\b")
_ALARM_SNOOZE_MINUTES_RE = re.compile(
    r"(?i)\b(\d{1,3}|two|three|four|five|six|seven|eight|nine|ten|"
    r"eleven|twelve|fifteen|twenty|thirty)\s*(?:more\s+)?(?:minutes?|mins?)\b")
#: Spoken durations, because "five more minutes" is how a person says it.
_SPOKEN_MINUTES = {"two": 2, "three": 3, "four": 4, "five": 5, "six": 6,
                   "seven": 7, "eight": 8, "nine": 9, "ten": 10,
                   "eleven": 11, "twelve": 12, "fifteen": 15,
                   "twenty": 20, "thirty": 30}


def _snooze_default_minutes() -> int:
    """Owner-configurable snooze length. Nine minutes unless told otherwise."""
    try:
        minutes = int(os.environ.get("PUFFPAI_SNOOZE_MINUTES", "9"))
    except (TypeError, ValueError):
        return 9
    return minutes if 1 <= minutes <= 120 else 9


def _try_alarm_snooze(lower: str, tools) -> str | None:
    """"Snooze" — deterministic, and never a guessed duration.

    Targets what is actually ringing (``status`` fired/ringing, which the
    server-side scheduler sets) and falls back to the most recently touched
    alarm, so the word on its own is enough — which is the entire point of
    saying it at 6:45 in the morning.
    """
    text = (lower or "").strip()
    if not text or len(text) > 140:
        return None
    if not _ALARM_SNOOZE_RE.search(text):
        return None
    if re.search(r"(?i)\bhow\s+long\b|\bwhat\b|\bcan\s+you\b\s+\bexplain\b", text):
        return None

    m = _ALARM_SNOOZE_MINUTES_RE.search(text)
    minutes = _snooze_default_minutes()
    if m:
        word = m.group(1).lower()
        asked = _SPOKEN_MINUTES.get(word, 0) if not word.isdigit() else int(word)
        if 1 <= asked <= 120:
            minutes = asked

    try:
        from puffpai.app_data import AppData
        data = AppData().get_data('alarmflow') or {}
    except Exception as exc:
        logger.debug("snooze fastpath: no app data: %s", exc)
        return None

    items = [i for i in (data.get('items') or []) if isinstance(i, dict)]
    ringing = [i for i in items if i.get('status') in ('fired', 'ringing')]
    target = None
    if ringing:
        target = max(ringing, key=lambda i: int(i.get('fired_ts') or i.get('ts') or 0))
    elif re.search(r"(?i)\bsnooze\b", text):
        # Only the explicit word may reach past what is actually ringing.
        # "a bit longer" and "five more minutes" are ordinary English that
        # happens to be a snooze ONLY while something is going off; claiming
        # them otherwise would answer "hold on a bit longer" with an alarm.
        live = [i for i in items if i.get('status') == 'running']
        if live:
            target = max(live, key=lambda i: int(i.get('ts') or 0))
        else:
            return ("Nothing is ringing and you have no alarms set, so "
                    "there's nothing to snooze.")
    if target is None:
        return None

    try:
        return tools.tool_dict['app_snooze_alarm'].invoke(
            {"identifier": target.get('id'), "minutes": minutes})
    except Exception as exc:
        logger.debug("snooze fastpath failed: %s", exc)
        return None


def _try_alarm_dismiss(lower: str, tools) -> str | None:
    """Cancel/dismiss/delete a timer or alarm — deterministic, no LLM.

    Fully determined by the words in the command, and the 7B mis-routes them
    often enough (once calling the library tool for "cancel the three minute
    timer") that the LLM adds only risk. Word-number normalization happens in
    the tool. Consulted BOTH before the team (the set_climate rule also eats
    "turn off the ten minute timer") and inside _try_direct_handle.
    """
    # Snooze first: it is a distinct, DECLARED verb and none of the paths
    # below own it; otherwise it falls through to the LLM, which picks its
    # own duration.
    try:
        snoozed = _try_alarm_snooze(lower, tools)
    except Exception as exc:
        logger.debug("alarm-snooze fastpath error: %s", exc)
        snoozed = None
    if snoozed:
        return snoozed

    # The RECIPROCAL of _try_alarm_set runs first: "cancel the 6:45 am alarm"
    # names a time, and every identifier path below resolves against an
    # item's desc (which is the literal "Alarm"). See _try_alarm_cancel.
    try:
        cancelled = _try_alarm_cancel(lower, tools)
    except Exception as exc:
        logger.debug("alarm-cancel fastpath error: %s", exc)
        cancelled = None
    if cancelled:
        return cancelled

    m_dis = re.search(
        r"(?i)\b(cancel|dismiss|delete|remove|silence|stop|turn off)\b"
        r"(?:\s+(?:the|my|all|that|this))*\s+(.{0,40}?)\s*"
        r"\b(timers?|alarms?)\b", lower)
    if not m_dis or re.search(
            r"(?i)shopping|pantry|grocery|event|task|light|lamp|"
            r"calendar|device", m_dis.group(2) or ""):
        return None
    try:
        verb, middle = m_dis.group(1), (m_dis.group(2) or "").strip()
        wants_all = (" all " in f" {lower} "
                     or (not middle and m_dis.group(3).endswith("s")))
        if wants_all:
            return tools.tool_dict['app_dismiss_alarm'].invoke("all")
        ident = middle or m_dis.group(3)
        if verb in ("delete", "remove", "cancel"):
            return tools.tool_dict['app_delete_alarm'].invoke(ident)
        return tools.tool_dict['app_dismiss_alarm'].invoke(ident)
    except Exception as exc:
        logger.debug("alarm dismiss fastpath failed: %s", exc)
        return None


# ── Tool-shaped intents the router would misroute to the agent path ──────────
# The router (_detect_route) sends these to the Concierge/team, which lacks
# the rich AssistantTools catalog, so they would misroute or be answered from
# the wrong source even though the underlying tool works when called directly. Each
# helper below is a deterministic pre-team intercept — same discipline as the
# clock/weather/timer fastpaths above: fully determined by the words in the
# request, no LLM tool-selection roulette. The same rule as the capability
# registry: the tool that OWNS a capability answers for it.

_WEATHER_ALERT_WORD_RE = re.compile(
    r"(?i)\b(?:alert|alerts|warning|warnings|advisory|advisories|"
    r"watch|watches)\b")
_WEATHER_ALERT_SUBJECT_RE = re.compile(
    r"(?i)\b(?:weather|forecast|storm|storms|severe|tornado|hurricane|"
    r"flood|flooding|heat|freeze|freezing|winter|wind|thunder|"
    r"thunderstorm|hail|blizzard|nws|noaa)\b")


def _try_weather_alerts(user_message: str) -> str | None:
    """Active weather ALERTS go to the NWS/automation alert tool, not the
    forecast. "any severe weather alerts?" contains the word "weather", so
    the forecast fastpath (auto_weather_forecast) would claim it and answer
    "none" from general current-conditions, even while a real NWS advisory is
    active and PuffPAI's own automation is posting it. This is
    THE authority for alerts, so it is checked BEFORE the forecast fastpath.
    Fires only when an alert/warning/advisory/watch word is paired with a
    weather/severe subject, so "set an alert" and "news alerts" don't trip it.

    It does not invoke ``prep_weather_alerts`` and summarize the result: that
    tool's geocode step crosses the ``geocode`` door, which is usually shut,
    so it returns an honest "I have no coordinates" refusal, and a
    summarizing model can prepend a confident "No severe weather alerts are
    currently active in <city>" to it. A false all-clear on a
    severe-weather path. The reply is built from the alert source itself
    by :mod:`puffpai.weather_alerts`, which resolves the household's own
    coordinates (the ones the working weather card already uses) and asks the
    NWS through the ``weather`` door that is open. No model, one state.
    """
    lower = (user_message or "").lower()
    if "widget" in lower or "dashboard" in lower or len(lower) > 120:
        return None
    if not (_WEATHER_ALERT_WORD_RE.search(lower)
            and _WEATHER_ALERT_SUBJECT_RE.search(lower)):
        return None
    try:
        from puffpai import weather_alerts as _weather_alerts
        return _weather_alerts.answer()
    except Exception as exc:
        logger.debug("weather-alerts fastpath failed: %s", exc)
        return None


_CAMERA_WORD_RE = re.compile(
    r"(?i)\b(?:camera|cameras|doorbell|door\s?bell|webcam|security\s?cam|"
    r"front\s?door|back\s?door|the\s+door)\b")
_CAMERA_ACTIVITY_RE = re.compile(
    r"(?i)\b(?:alert|alerts|activity|motion|detect|detected|detection|"
    r"see|seen|saw|anyone|anybody|someone|somebody|visitor|visitors|"
    r"package|packages|happening)\b")


def _try_camera_alerts(user_message: str) -> str | None:
    """Camera activity/alerts go to camera_recent_alerts (real HA motion,
    person, and visitor history), not a camera *lookup*: "any alerts from my
    cameras?" must read recent detections, not list cameras. Fires when a camera/door word is paired with an
    alert/activity/see word; "list my cameras" (no activity word) still falls
    through to the device path. The tool already answers conversationally, so
    its output is returned as-is.
    """
    lower = (user_message or "").lower()
    if "widget" in lower or "dashboard" in lower or len(lower) > 120:
        return None
    if not (_CAMERA_WORD_RE.search(lower)
            and _CAMERA_ACTIVITY_RE.search(lower)):
        return None
    try:
        tools = _get_assistant_tools()
        return tools.tool_dict['camera_recent_alerts'].invoke('')
    except Exception as exc:
        logger.debug("camera-alerts fastpath failed: %s", exc)
        return None


_ADD_TASK_RE = re.compile(
    r"\bremind me\b"
    r"|\b(?:add|create|make|new|set\s+up|put|stick|save|schedule)\s+"
    r"(?:a\s+|an\s+|the\s+|another\s+)?(?:reminder|task|to-?do|chore)\b",
    re.IGNORECASE)
_ADD_TASK_EXCLUDE_RE = re.compile(
    r"(?i)\b(?:shopping|grocer(?:y|ies)|pantry|timer|alarm|"
    r"what(?:'s| is| are)|show me|list (?:my|all)|do i have|"
    r"how many)\b")
_ADD_TASK_TITLE_RES = [
    re.compile(r"(?i)\bremind me\b(?:\s+(?:to|about|that i(?:'m| am| should| need to)?))?\s+(.+)"),
    re.compile(r"(?i)\b(?:reminder|task|to-?do|chore)\b"
               r"(?:\s+(?:to|about|for|that))?\s*[:\-]?\s+(.+)"),
]


def _extract_task_title(user_message: str) -> str | None:
    """Pull the task text out of an add-a-reminder command, or None."""
    text = (user_message or "").strip()
    for rx in _ADD_TASK_TITLE_RES:
        m = rx.search(text)
        if m:
            title = m.group(1).strip(" .?!,\"'")
            # Drop a trailing "to my to-do list"/"to my tasks" tail.
            title = re.sub(r"(?i)\s+to my (?:to-?do list|tasks?|"
                           r"reminders?|calendar)\s*$", "", title).strip()
            if len(title) >= 2:
                return title
    return None


def _try_calendar_recurring(user_message: str) -> str | None:
    """A RECURRING calendar item said in plain English — one item, once.

    Without it, three shapes go wrong:

    * "Every Monday, Tuesday, Thursday, and Friday morning at 6.15, I have
      to take the kids to practice. Can you add that?" routes to RAG and is
      refused, the request describes first and asks second.
    * "set up a reminder every weekday morning except for Wednesdays at 615
      take the kids to practice" reaches ``_try_add_task``, which stores the WHOLE
      SENTENCE as a task title due tomorrow at 09:00, with no time and no
      recurrence.
    * A follow-up "Add it to the calendar view." can create more events with
      different wrong recurrences and repeat the previous confirmation
      verbatim.

    So this runs AHEAD of ``_try_add_task`` (a day set + a time means a
    repeating calendar item, not a to-do) and behind the timer/alarm
    fastpaths, which keep their own phrasings. ``puffpai.calendar_nl`` holds
    the whole rule and declines anything without an explicit add intent, a day
    set AND a time — so a one-off reminder, a read, a med and a grocery all
    fall through exactly as before. ``_detect_route`` is not touched.
    """
    try:
        from puffpai import calendar_nl
    except Exception as exc:      # pragma: no cover - import guard
        logger.debug("calendar-recurring fastpath unavailable: %s", exc)
        return None
    try:
        return calendar_nl.handle(user_message, _get_app_data())
    except Exception as exc:
        logger.debug("calendar-recurring fastpath failed: %s", exc)
        return None


def _note_calendar_turn(user_message: str,
                        conversation_id: str | None = None) -> None:
    """Tell the calendar delete path that a turn happened. Never raises."""
    try:
        from puffpai import calendar_nl
        calendar_nl.note_turn(user_message, conversation_id)
    except Exception as exc:      # pragma: no cover - import guard
        logger.debug("calendar-delete turn notice failed: %s", exc)


def _try_calendar_delete(user_message: str,
                         conversation_id: str | None = None) -> str | None:
    """"Delete the soccer practice reminder" — actually delete it, once.

    The delete verbs are vetoed by the ADD rule, so the turn would fall to
    the planner, which can reply "deleted" about a row that is still there.
    Sent to the store the direct way it is no better: a task and an event of
    the same title make ``cal_delete_event`` answer "I found 2 that match:
    'X', 'X'. Which one?" — two identical options and nothing removed.

    ``puffpai.calendar_nl.handle_delete`` resolves by normalised title across
    BOTH kinds (a task and its mirror event are one thing), disambiguates by
    KIND and SCHEDULE rather than by title, takes "both" for an answer, and
    builds every confirmation by reading the store back AFTER the write. It
    declines whenever the phrase names nothing that is in the calendar, so
    "delete the alarm" still reaches AlarmFlow and a med still keeps its vault
    path. ``_detect_route`` is not touched.
    """
    try:
        from puffpai import calendar_nl
    except Exception as exc:      # pragma: no cover - import guard
        logger.debug("calendar-delete fastpath unavailable: %s", exc)
        return None
    try:
        return calendar_nl.handle_delete(user_message, _get_app_data(),
                                        conversation_id=conversation_id)
    except Exception as exc:
        logger.debug("calendar-delete fastpath failed: %s", exc)
        return None


# ── Household roster, spoken ──────────────────────────────
#
# "add Riley to my family" matches the TASK fastpath's shape ("add X to Y")
# and would become a to-do item called "Riley", and "who is in my family"
# would be answered by a model from the Calendar's hardcoded placeholders. Both are deterministic reads/writes of the roster,
# so neither calls a model. The add hook runs BEFORE _try_add_task for
# exactly the reason above.

#: "add Riley to my family", "add my daughter Riley to the household as a child".
#: The head noun (household/family) is required, which is what keeps "add milk
#: to the list" and "add soccer to the family calendar" out.
_HOUSEHOLD_ADD_RE = re.compile(
    r"(?i)\b(?:add|create|register|set\s+up)\b\s+(?P<name>.{1,60}?)\s+"
    r"(?:to|in|on)\s+(?:my|our|the)\s+(?:household|family)\b"
    r"(?!\s+(?:calendar|list|plan|meal|shopping|schedule|photo|album))"
    r"(?:\s+as\s+(?:an?\s+)?(?P<role>adult|child|kid|teen|pet|dog|cat))?")

#: Words that are a relationship, not a name: "add my daughter Riley" names
#: Riley. Stripped from the front of the captured span.
_HOUSEHOLD_NAME_PREFIX_RE = re.compile(
    r"(?i)^(?:a|an|the|my|our|new)\s+|"
    r"^(?:daughter|son|kid|child|wife|husband|partner|mother|father|mom|dad|"
    r"grandma|grandpa|sister|brother|roommate|dog|cat|pet)\s+")

#: A NAME: letters (any script), spaces, hyphens, apostrophes; at most three
#: words. Anything else ("two more people", "a reminder") is not a person.
_HOUSEHOLD_NAME_RE = re.compile(r"(?u)^[^\W\d_][\w'\-]*(?:\s+[^\W\d_][\w'\-]*){0,2}$")

_HOUSEHOLD_ROLE_ALIASES = {"kid": "child", "teen": "child", "dog": "pet",
                           "cat": "pet"}

#: Words that make a span a QUANTITY or a category rather than a person:
#: "add two more people to my household" names nobody, and a roster entry
#: called "Two more people" is worse than declining.
_HOUSEHOLD_NON_NAME_WORDS = frozenset({
    "people", "person", "member", "members", "everyone", "everybody",
    "someone", "somebody", "another", "more", "one", "two", "three", "four",
    "five", "six", "seven", "eight", "nine", "ten", "them", "us", "family",
    "household", "profile", "profiles", "account", "user", "users",
})


def _household_name(raw: str) -> "str | None":
    """The person's name out of the captured span, or None if it isn't one."""
    name = str(raw or "").strip().strip(",.")
    previous = None
    while name and name != previous:
        previous = name
        name = _HOUSEHOLD_NAME_PREFIX_RE.sub("", name).strip()
    if not name or len(name) > 40 or not _HOUSEHOLD_NAME_RE.match(name):
        return None
    if any(word.lower() in _HOUSEHOLD_NON_NAME_WORDS for word in name.split()):
        return None
    return name[:1].upper() + name[1:] if name.islower() else name


def _try_household_add(user_message: str) -> "str | None":
    """WRITE: put a person (or a pet) in the household, and say who's there.

    The read-back is the point: a roster write the household cannot verify
    out loud is how the placeholder members survived for months.
    """
    match = _HOUSEHOLD_ADD_RE.search(user_message or "")
    if not match:
        return None
    name = _household_name(match.group("name"))
    if not name:
        return None
    role = (match.group("role") or "adult").lower()
    role = _HOUSEHOLD_ROLE_ALIASES.get(role, role)
    try:
        from puffpai import household
        member = household.create_member(name, role=role)
    except Exception as exc:
        from puffpai.household import HouseholdError
        if isinstance(exc, HouseholdError):
            return str(exc)
        logger.debug("household add failed: %s", exc)
        return None
    try:
        everyone = household.names()
    except Exception as exc:          # pragma: no cover - defensive
        logger.debug("household read-back failed: %s", exc)
        everyone = []
    roster = (" Your household is now " + ", ".join(everyone) + "."
              if everyone else "")
    return (f"Added {member['display_name']} to your household as "
            f"{'an' if role == 'adult' else 'a'} {role}. They're on the "
            f"calendar, in FitFam and in Trivia now.{roster}")


def _try_household_list(user_message: str) -> "str | None":
    """READ: who is in the household, from the one roster."""
    try:
        from puffpai.agents import household_reads
        if household_reads.match(user_message) != "household_members":
            return None
        return household_reads.household_members()
    except Exception as exc:
        logger.debug("household roster read unavailable: %s", exc)
        return None


def _try_add_task(user_message: str) -> str | None:
    """"Add a reminder to do the dishes" is a to-do, not a thermostat. Live
    failure: it misrouted to climate control ("no climate device called...").
    app_add_task owns chores, errands, and reminders. Groceries and pantry
    items keep their own tools (app_add_shopping / app_add_pantry) and
    timers/alarms keep theirs, so those words — and question phrasings that
    only *read* the list — veto this fastpath. Only fires when a task title
    extracts cleanly; anything fuzzier falls through to the LLM, which can ask
    a real follow-up.
    """
    lower = (user_message or "").lower()
    if not _ADD_TASK_RE.search(lower) or _ADD_TASK_EXCLUDE_RE.search(lower):
        return None
    title = _extract_task_title(user_message)
    if not title:
        return None
    # "remind me to call the dentist Monday" must not store the WHOLE phrase
    # as the title with no due date, silently landing the task on the
    # tomorrow default (a Sunday for a Monday reminder). The day
    # the person actually said is pulled off the tail here and passed as the
    # due date, resolved against the appliance's local clock.
    payload = {"title": title}
    try:
        from puffpai import calendar_dates as _caldates
        found = _caldates.extract_date_phrase(title)
        if found.get("date"):
            payload["title"] = found["title"]
            payload["due_date"] = found.get("iso") or found["date"]
            # The hour named could be either half of the day and the sentence
            # settled neither. Nothing is written until the user
            # answers, the same rule the alarm fastpath keeps.
            if found.get("ask_half") and found.get("time"):
                return _ask_task_half_of_day(
                    payload["title"], found["date"], found["time"])
    except Exception as exc:
        logger.debug("add-task date parse failed: %s", exc)
    return _add_task_row(payload)


def _add_task_row(payload: dict) -> "str | None":
    """Write one task; the app's own confirmation, or None.

    Shared by ``_try_add_task`` and by the AM/PM answer, so a reminder added
    by answering "PM" reads back exactly like one added in a single breath.
    """
    try:
        tools = _get_assistant_tools()
        return tools.tool_dict['app_add_task'].invoke(dict(payload))
    except Exception as exc:
        logger.debug("add-task fastpath failed: %s", exc)
        return None


def _ask_task_half_of_day(title: str, day: str, hint) -> str:
    """Ask which half of the day a reminder's bare hour meant, and remember.

    Seen twice (both near 1 AM): "add a reminder to do
    the dishes today before nine" wrote 9 AM without a word — eight hours
    from a request made at one in the morning, and no way to tell whether it
    was the right eight. Both readings were live, so this asks, exactly the
    way ``_ask_alarm_half_of_day`` does, and the clarifier turns the
    one-word answer back into the task.
    """
    hour, minute = int(hint[0]), int(hint[1])
    clock = "%d" % hour if not minute else "%d:%02d" % (hour, minute)
    sentence = (f"Did you mean {clock} AM or {clock} PM? Say which one and "
                f"I'll add it - I'd rather ask than put it on the wrong half "
                f"of the day.")

    def _complete(chosen, said, title=title, day=day, hour=hour,
                  minute=minute):
        half = (chosen[0]["value"] if chosen else "am")
        settled = hour % 12 + (12 if half == "pm" else 0)
        return _add_task_row({"title": title,
                              "due_date": "%sT%02d:%02d" % (day, settled,
                                                            minute)})

    try:
        _pending_clarifier.register(
            "task_half_of_day", _complete,
            [{"label": "AM", "value": "am",
              "tokens": ["am", "a m", "morning"]},
             {"label": "PM", "value": "pm",
              "tokens": ["pm", "p m", "evening", "night", "afternoon",
                         "tonight"]}],
            prompt=sentence)
    except Exception as exc:      # pragma: no cover - never worth the answer
        logger.debug("task clarifier not registered: %s", exc)
    return sentence


# ── Medication fastpath (deterministic, every surface) ──────────────────────
#
# WHY THIS EXISTS. `_fix_add_med` is reachable only
# through `_verify_and_fix`, which runs on three call sites (the voice-agent
# route, the chat-agent route and `/conversation`). `_detect_route` classifies
# "add insulin to my meds" as **rag**, and the rag path returns the model's text
# directly — so on `/chat/send`, `/chat/stream`, `/v1/chat/completions` and the
# voice route the medication write would never run at all, and the household
# would be told "Medication added." while `calendar.meds[]` stayed empty.
#
# Handled the way this codebase handles a misroute: a deterministic `_try_*`
# fastpath registered in `_try_instant_answer`, mirroring `_try_add_task` (which
# owns the reminder phrasing on all five surfaces). `_detect_route`
# is NOT touched: editing it risks breaking unrelated routing.
#
# The two streaming-RAG branches bypass `_try_instant_answer` entirely (the same
# gap the vault PIN follow-up is captured ahead of in `chat_stream`), so they
# consult `_try_med_fastpath` directly — and ONLY on the rag branch, so no
# surface can invoke the medication write twice.

#: Ceiling on a fastpath-written drug name. A real medication name is short;
#: 600 characters of prose is a parser failure, not a prescription, and storing
#: it silently is how a wrong record gets reported accurately.
_MED_NAME_MAX_CHARS = 64

#: One sentence for every "this is not a medication name" outcome. It names no
#: PII type and echoes no value: this turn's honesty notice already speaks about
#: the class, and it is TRUE precisely because nothing was stored.
_MED_PII_REFUSAL = (
    "I won't store that as a medication name - it looks like personal "
    "information rather than a medication. Say just the medication name and "
    "I'll add it.")

#: ...and the sentence for a message that carries a disclosure ELSEWHERE. It
#: says the medication was not added and why, without naming the class or
#: echoing the value - the turn's own honesty notice does that, truthfully,
#: because nothing was stored.
_MED_PERSONAL_DETAILS_REFUSAL = (
    "That message mentions personal details, so I didn't add a medication - "
    "tell me just the medication name and I'll add it.")

#: A medication NOUN somewhere in the sentence. Required by the "took" rule so
#: "I took my dog for a walk" cannot become a medication lookup.
_MED_NOUN_RE = re.compile(
    r"(?i)\b(?:medications?|medicines?|meds?|pills?|doses?|prescriptions?)\b")

#: Reads and deletes never write. "remind me ..." belongs to _try_add_task,
#: which runs first and owns the reminder phrasing on all five surfaces,
#: this fastpath must never steal it.
_MED_ADD_EXCLUDE_RE = re.compile(
    r"(?i)\b(?:remind me|shopping|grocer(?:y|ies)|pantry|timer|alarm|"
    r"remove|delete|stop|cancel|refill|"
    r"what|which|show me|list my|list all|do i have|how many)\b")

_MED_ADD_TITLE_RES = [
    # "add a medication called Metformin" / "set a medication reminder for warfarin"
    re.compile(r"(?i)\b(?:add|create|set|start|track|put)\s+"
               r"(?:a\s+|an\s+|the\s+|my\s+|another\s+)?(?:new\s+)?"
               r"(?:medications?|medicines?|meds?)\s*(?:reminder)?\s*"
               r"(?:called|named|for|:)\s+(.+)"),
    # "add insulin to my meds" / "put my vitamin on the medication list"
    re.compile(r"(?i)\b(?:add|put|track)\s+(.+?)\s+"
               r"(?:to|on|in|onto)\s+(?:my|the)\s+"
               r"(?:medications?|medicines?|meds?)(?:\s+list)?\b"),
]

_MED_TAKE_RE = re.compile(
    r"(?i)\b(?:i\s+)?(?:just\s+)?took\s+(?:my\s+|the\s+|a\s+|his\s+|her\s+)?(.+)")

_MED_LIST_RE = re.compile(
    r"(?i)\b(?:what|which|list|show(?:\s+me)?|do i have|how many|am i on)\b"
    r"[^.?!]{0,40}\b(?:medications?|medicines?|meds)\b"
    r"|\b(?:medications?|medicines?|meds)\b[^.?!]{0,24}"
    r"\b(?:am i (?:on|taking)|do i (?:have|take))\b")


def _extract_med_name(user_message):
    """Pull the DRUG out of an add-a-medication command, or None.

    Extracts from the med CLAUSE rather than treating the whole sentence as the
    name. That is why "my SSN is [REDACTED-SSN], add my vitamin to my meds"
    stores ``vitamin`` instead of refusing on a placeholder that was never part
    of the drug's name at all.
    """
    text = (user_message or "").strip()
    for rx in _MED_ADD_TITLE_RES:
        m = rx.search(text)
        if not m:
            continue
        med = m.group(1).strip(" .,!?\"'")
        med = re.sub(r"(?i)^(?:my|the|a|an)\s+", "", med).strip()
        med = re.sub(r"(?i)\s+(?:to|on|in|onto)\s+(?:my|the)\s+"
                     r"(?:medications?|medicines?|meds?)(?:\s+list)?\s*$",
                     "", med).strip(" .,!?")
        if len(med) >= 2:
            return med
    return None


#: The identity nouns a first-person disclosure names. Shared by every cue form
#: below so the shapes cannot drift apart.
_MED_IDENTITY_NOUN = (
    r"(?:full\s+|first\s+|last\s+|home\s+|street\s+|mailing\s+|"
    r"cell\s+|mobile\s+|work\s+)?"
    r"(?:name|address|date\s+of\s+birth|birth\s*date|birthday|dob|"
    r"social(?:\s+security)?(?:\s+number)?|ssn|phone(?:\s+number)?|"
    r"e-?mail(?:\s+address)?|credit\s*card|card\s+number|"
    r"account\s+number|licen[sc]e(?:\s+number)?|passport)")

#: A first-person IDENTITY disclosure, in any word order, ANYWHERE in the
#: message. Not a PII detector and not offered as one - it is a statement about
#: what the MESSAGE is doing. A message that also says "here is my address" is
#: not a clean request to add a medication, so nothing lifted out of it is
#: trusted as a drug name.
#:
#: WHY THIS EXISTS SEPARATELY FROM THE DETECTOR SCREEN. Some disclosure values
#: are invisible to the shipped classifier on ANY input:
#: _ADDRESS_PATTERN's street-suffix list has no "Terrace", and
#: _LABELED_NAME_PATTERN requires "name:" / "name=". Widening either changes
#: what the appliance detects, vaults, redacts and announces on every surface -
#: a product-wide change traded for unknown false positives, not a medication
#: fix. The classifier is left unchanged.
#:
#: Requiring "my <noun> is" alone would be bypassable by word order -
#: "<a street address> is my address, add ..." and "add ... (my dob)" would
#: both walk past it. Every order is covered:
#: possessive-first, value-first ("is my <noun>"), labelled ("my <noun>:"),
#: parenthesised ("(my dob)"), plus "i live at" and "born on/in".
#:
#: A CUE MUST CARRY A VALUE. Treating the mere WORDS "my birthday" /
#: "my phone" / "my name" as a disclosure would make ordinary sentences -
#: "add melatonin to my meds for my birthday", "add Zyrtec to my meds, remind
#: me on my phone" - store nothing and be told they "mention personal details"
#: when they mention none. In the
#: half of this defect that costs a person a dose, a false refusal is not the
#: safe direction. A bare possessive noun phrase, at a comma, a full stop, the
#: end of the message or before another preposition, is NOT a cue: there is no
#: value beside it to leak. What remains a cue is a disclosure that actually
#: carries one, in every word order.

#: A REDACTION PLACEHOLDER standing where a value would stand is a value, and
#: the strongest kind: under PUFFPAI_SCRUB_AND_VAULT the routing text of
#: "my SSN is <n>, add my vitamin to my meds" reads "my SSN is [REDACTED-SSN],
#: ..." - the classifier has already fired, and there is a real number behind
#: that token. Without this the flag-ON path would store a medication the
#: flag-OFF path refuses.
_MED_VALUE_PLACEHOLDER_RE = r"\[REDACTED[^\]]*\]|\{\{vault:"

#: What a value looks like AFTER a connector: a placeholder, a digit within the
#: same clause, or two consecutive word tokens. "my name is on the bottle" is
#: deliberately on the refusing side of that line - fail closed is the cheaper
#: error for a screen that only ever fires on an add-a-medication phrasing.
_MED_VALUE_AHEAD_RE = (r"(?=[ \t]*(?:" + _MED_VALUE_PLACEHOLDER_RE +
                       r"|[^,;\n]{0,24}\d|"
                       r"[^\W\d_][\w'\-]*[ \t]+[^\W\d_][\w'\-]*))")

#: ...and BEFORE "is my <noun>". Same three shapes, consumed rather than looked
#: ahead at, because `re` has no variable-length lookbehind. Token runs never
#: cross a comma, so "add X to my meds, it is my birthday" carries no value and
#: is not a cue.
_MED_VALUE_BEHIND_RE = (r"(?:(?:" + _MED_VALUE_PLACEHOLDER_RE + r")[^\s,;]*"
                        r"|[^\s,;]*\d[^\s,;]*|"
                        r"[^\W\d_][\w'\-]*[ \t]+[^\W\d_][\w'\-]*)[ \t]+")

_MED_IDENTITY_CUE_RE = re.compile(
    r"(?i)"
    # "my address is 742 ...", "my dob: 01/02/1990", "my name is John Smith"
    r"\b(?:my|his|her|their|our)\s+" + _MED_IDENTITY_NOUN +
    r"\b\s*(?:\b(?:is|are|was)\b|[:=])" + _MED_VALUE_AHEAD_RE +
    # "742 Evergreen Terrace is my address", "John Smith is my name"
    r"|" + _MED_VALUE_BEHIND_RE + r"is\s+(?:my|his|her|their|our)\s+" +
    _MED_IDENTITY_NOUN + r"\b"
    # "add 01/02/1990 to my meds (my dob)" - a CLOSED parenthetical annotating
    # the value beside it, not a bare mention.
    r"|\(\s*(?:my|his|her|their|our)\s+" + _MED_IDENTITY_NOUN + r"\s*\)"
    r"|\bi\s+live\s+at\b" + _MED_VALUE_AHEAD_RE +
    r"|\bborn\s+(?:on|in)\b" + _MED_VALUE_AHEAD_RE)

#: Separators that must not be able to hide a disclosure from the detectors.
#: _DOB_PATTERN needs its birth-trigger and the date on the SAME LINE, so a
#: newline between them would defeat it while the comma form of the same
#: sentence is refused.
#: Collapsing every separator to ", " removes that difference by construction.
_MED_SEPARATOR_RE = re.compile(r"[\r\n\t;|]+")

#: Dotted and space-separated date renderings folded onto the slash form that
#: _DATE_FORMS already recognises. Digit runs are never stripped - the letter
#: rule below depends on seeing them.
_MED_DOTTED_DATE_RE = re.compile(r"\b(\d{1,2})[.\s](\d{1,2})[.\s](\d{4})\b")

#: A medication name has letters in it. "123456788" is not a drug, and a
#: bare 9-digit run is not an SSN to the detector either, so nothing else
#: would stop it.
_MED_HAS_LETTER_RE = re.compile(r"[^\W\d_]", re.UNICODE)


def _med_normalise_for_screen(text):
    """The message as the screen reads it: separators collapsed, dates folded
    onto one form, every digit run intact. Never raises."""
    try:
        out = _MED_SEPARATOR_RE.sub(", ", str(text or ""))
        out = out.replace("(", ", (").replace(")", ") ")
        out = _MED_DOTTED_DATE_RE.sub(r"\1/\2/\3", out)
        return re.sub(r"[ ]{2,}", " ", out).strip()
    except Exception:
        return str(text or "")


def _med_name_refusal(med, source=None):
    """Why this string must not be stored as a medication name, or ``None``.

    On the flag-OFF path ``_scan_and_redact_message`` redacts only the copy
    that is PERSISTED; the routing text stays raw. So "add <an SSN> to my
    meds" hands the fastpath a real SSN, ``_REDACTED_PLACEHOLDER_RE`` (which
    knows only ``[REDACTED-...]`` and ``{{vault:``) does not fire, and without
    this screen the number would be written into ``calendar.json`` -
    unencrypted, 0600 being a file mode and not a cipher - while the honesty
    notice says "I did not keep it". A false "not kept" over a STORED value is
    the worst version of the defect this branch exists to close.

    ONE FAIL-CLOSED RULE, not clause heuristics. Screening the extracted
    fragment, its clause, or span overlap each closes some phrasings and is
    walked past by the next reordering, e.g.

        "my date of birth is January 2, 1990, add 01/02/1990 to my meds"

    - the cue sits in another clause, and the detector's span
    (``January 2, 1990``) neither contains nor is contained by the stored
    rendering (``01/02/1990``), because overlap compares RENDERINGS of a value
    rather than the value itself. There is no end to that game, so one rule
    replaces the heuristics:

      **If the whole normalised message carries ANY non-health PII, or any
      identity-disclosure cue in any word order, no medication is stored.**

    ``include_health`` stays OFF throughout: a medication name is *supposed* to
    be a health term, and screening for that would refuse every legitimate add.

    THE COST, ACCEPTED DELIBERATELY. "my SSN is <n>, add my vitamin to my
    meds" does not store ``vitamin``. Mixing a disclosure and a medication in
    one breath costs the household one
    repeat, the reply says exactly that, and the turn's PII notice stays TRUE
    because nothing was stored. Weighed against writing an unencrypted date of
    birth into an app document while announcing the opposite, a repeat is cheap.

    Fail-closed: if the classifier cannot run we refuse rather than store an
    unscreened value. A refused add costs one repeat; a stored SSN does not come
    back out of a backup.
    """
    if not med:
        return "I did not catch a medication name - say it again and I'll add it."
    if _REDACTED_PLACEHOLDER_RE.search(med):
        return ("I did not add that to your medication list - the name was "
                "removed from this turn before I could read it. Say the "
                "medication name again and I'll add it.")
    if len(med) > _MED_NAME_MAX_CHARS:
        return ("I did not add that to your medication list - what I picked up "
                "was too long to be a medication name. Say just the name and "
                "I'll add it.")
    try:
        has_pii = bool(_get_pii_classifier().scan_for_pii(med).has_pii)
    except Exception as exc:
        logger.warning("med-name PII screen failed, refusing: %s", exc)
        has_pii = True
    if has_pii:
        # Deliberately does not name the type or echo the value: this turn's
        # honesty notice already speaks about the class, and it is TRUE
        # precisely because nothing was stored.
        return _MED_PII_REFUSAL
    # AFTER the PII scan, deliberately: "123-45-6788" is both letterless and an
    # SSN, and the household is better served by being told it looked like
    # personal information than by a grammar lesson. This rule is what catches
    # what is left - "123456788", a bare nine-digit run the detector does not
    # recognise as an SSN.
    if not _MED_HAS_LETTER_RE.search(med):
        return ("I did not add that to your medication list - a medication name "
                "has letters in it, and what I picked up has none. Say the name "
                "and I'll add it.")
    if source:
        try:
            normalised = _med_normalise_for_screen(source)
            if _get_pii_classifier().scan_for_pii(normalised).has_pii:
                return _MED_PERSONAL_DETAILS_REFUSAL
            if _MED_IDENTITY_CUE_RE.search(normalised):
                return _MED_PERSONAL_DETAILS_REFUSAL
        except Exception as exc:
            logger.warning("med-name source screen failed, refusing: %s", exc)
            return _MED_PERSONAL_DETAILS_REFUSAL
    return None


def _try_med_add(user_message):
    """"add insulin to my meds" must reach calendar.meds[] on EVERY surface.

    Declines rather than storing a redaction placeholder: under
    ``PUFFPAI_SCRUB_AND_VAULT`` a scrubbed span must never become a drug name,
    and a household told "added" over an empty list is the failure that costs
    someone a dose.
    """
    lower = (user_message or "").lower()
    if _MED_ADD_EXCLUDE_RE.search(lower):
        return None
    med = _extract_med_name(user_message)
    if not med:
        return None
    refusal = _med_name_refusal(med, source=user_message)
    if refusal:
        return refusal
    try:
        tools = _get_assistant_tools()
        return tools.tool_dict['app_add_med'].invoke({"name": med})
    except Exception as exc:
        logger.debug("med-add fastpath failed: %s", exc)
        return None


def _try_med_take(user_message):
    """"I took my medicine" answers from the medication list, not from a guess.

    Fires only when the sentence carries a medication NOUN, or names a
    medication that is actually stored. "I took my dog for a walk" must fall
    through to the model rather than become a medication lookup.
    """
    text = (user_message or "").strip()
    m = _MED_TAKE_RE.search(text)
    if not m:
        return None
    name = (m.group(1) or "").strip(" .,!?\"'")
    name = re.sub(r"(?i)^(?:my|the|a|an)\s+", "", name).strip()
    if len(name) < 2:
        return None
    if not _MED_NOUN_RE.search(text):
        try:
            app = _get_app_data()
            stored = [str(x.get('name', '')).lower()
                      for x in (app.get_data('calendar') or {}).get('meds', [])]
        except Exception:
            stored = []
        if not any(s and s in name.lower() for s in stored):
            return None
    try:
        tools = _get_assistant_tools()
        return tools.tool_dict['app_take_med'].invoke({"med_name": name})
    except Exception as exc:
        logger.debug("med-take fastpath failed: %s", exc)
        return None


#: The DOSE-LOG and SCHEDULE shapes, deterministic.
#:
#: Left to the agent, "I took my [medication] this morning" can wait 25 seconds
#: for "I couldn't find a medication named [X] ... Did you add it?" with the
#: drug name read out loud TWICE, and "set up a daily reminder to take my
#: [medication] in the morning" can be asked for a dose and a time and then
#: told "I don't have access to a task-reminder tool", which is false.
#:
#: Three hazards, all handled here: (1) the `_try_med_take` rule keeps a
#: trailing "this morning" as part of the drug name, so nothing matches
#: and the turn falls to the agent; (2) every reply on that path echoes the
#: medication name, which must never be spoken aloud; (3) the schedule shape
#: has no other deterministic owner, so it would depend on whichever
#: tools the model happened to be offered that utterance.
#:
#: NOTHING here echoes the medication name. A stored row is confirmed by its
#: LABEL, and a row with no label by the generic one — the same word the
#: vaulted rows already use.
_MED_GENERIC_SPOKEN_LABEL = "your medication"

#: "I took my X", "I had my X", "log my X", "mark my X as taken".
_MED_LOG_RES = [
    re.compile(r"(?i)\b(?:i\s+)?(?:just\s+)?(?:took|have\s+taken|had)\s+"
               r"(?:my|the|his|her|a)\s+(?P<name>.+)$"),
    re.compile(r"(?i)\blog\s+(?:my|the|his|her)\s+(?P<name>.+?)"
               r"(?:\s+as\s+(?:taken|done))?$"),
    re.compile(r"(?i)\bmark\s+(?:my|the|his|her)\s+(?P<name>.+?)\s+"
               r"as\s+(?:taken|done)\b"),
]

#: "set up a (daily) reminder to take my X (at 8)", "remind me to take my X
#: every morning". The verb "take" is required: a reminder that is not about
#: taking something is a to-do and keeps _try_add_task.
_MED_SCHEDULE_RE = re.compile(
    r"(?i)\b(?:remind(?:er)?|reminders)\b[^.?!]{0,40}?\bto\s+take\s+"
    r"(?:my|the|his|her)\s+(?P<name>.+)$")

#: Time words and dayparts that are part of WHEN, never part of the name.
_MED_NAME_TAIL_RE = re.compile(
    r"(?i)[\s,]*(?:this\s+(?:morning|afternoon|evening)|tonight|today|"
    r"yesterday|already|just\s+now|an?\s+\w+\s+ago|"
    r"every\s+(?:morning|day|night|evening|afternoon|weekday)|"
    r"each\s+(?:morning|day|night|evening)|daily|"
    r"in\s+the\s+(?:morning|evening|afternoon)|before\s+bed|at\s+night|"
    r"with\s+(?:breakfast|lunch|dinner|food)|for\s+(?:today|tonight)|"
    r"at\s+[\d:apm\.\s]+|dose|pill|for\s+the\s+day|"
    r"as\s+(?:taken|done)|please)\s*$")

#: The generic nouns that mean "the medication I am on", not a drug name.
_MED_GENERIC_NAME_RE = re.compile(
    r"(?i)^(?:medications?|medicines?|meds?|pills?|prescriptions?|"
    r"morning\s+(?:pills?|meds?|medications?)|"
    r"(?:evening|night|bedtime)\s+(?:pills?|meds?))$")

#: Ordinary objects a person "takes" that are not medications. The log rule
#: only ever says "I don't have that on file" — it never writes — but saying it
#: about a dog walk would still be nonsense. Multi-word names already fall out
#: (a drug name is one or two words); this catches the one-word cases.
_MED_NOT_A_DRUG = frozenset((
    "dog", "dogs", "cat", "kid", "kids", "son", "daughter", "car", "truck",
    "bike", "nap", "shower", "bath", "walk", "break", "lunch", "dinner",
    "breakfast", "trash", "phone", "keys", "temperature", "time", "turn",
    "seat", "bus", "train", "chance", "picture", "photo", "look", "test",
))

_MED_NOT_ON_FILE = ("I don't have that medication on file — add it in the "
                    "Meds app and I'll track it from there.")


def _med_rows():
    """The stored medication rows, or an empty list. Never raises."""
    try:
        data = _get_app_data().get_data('calendar') or {}
        return [m for m in (data.get('meds') or []) if isinstance(m, dict)]
    except Exception as exc:
        logger.debug("med rows unavailable: %s", exc)
        return []


def _med_spoken_label(med) -> str:
    """What this medication is called OUT LOUD — never the drug name."""
    label = str((med or {}).get('label') or "").strip()
    return label or _MED_GENERIC_SPOKEN_LABEL


def _med_clean_name(raw: str) -> str:
    """The medication name with the WHEN words trimmed off the tail."""
    name = (raw or "").strip(" .,!?\"'")
    for _ in range(4):
        trimmed = _MED_NAME_TAIL_RE.sub("", name).strip(" .,!?\"'")
        if trimmed == name:
            break
        name = trimmed
    return re.sub(r"(?i)^(?:my|the|a|an)\s+", "", name).strip()


def _med_resolve(name: str, rows):
    """The stored row *name* refers to, "many", or None. Pure given *rows*."""
    low = (name or "").strip().lower()
    if not low:
        return None
    if _MED_GENERIC_NAME_RE.match(low):
        if len(rows) == 1:
            return rows[0]
        return "many" if rows else None
    for med in rows:
        for field in (med.get('name'), med.get('label')):
            field = str(field or "").strip().lower()
            if field and (field in low or low in field):
                return med
    return None


def _med_looks_like_a_drug(name: str) -> bool:
    """Is *name* shaped like a medication a person would name out loud?"""
    words = [w for w in re.split(r"[\s-]+", (name or "").strip()) if w]
    if not (1 <= len(words) <= 2):
        return False
    if any(w.lower() in _MED_NOT_A_DRUG for w in words):
        return False
    return all(re.fullmatch(r"[A-Za-z][A-Za-z'.]+", w) for w in words)


def _med_set_schedule(med, text: str) -> str:
    """Point a stored medication at the time the sentence names.

    Confirms by label, and says plainly when it fell back to the app's
    default time — v1 asks no follow-up question for the dose or the hour.
    """
    parsed = _parse_alarm_time(text)
    freq = "weekdays" if re.search(r"(?i)\bweekdays?\b", text) else "daily"
    stated = parsed is not None
    hour, minute = parsed if stated else (8, 0)
    clock = _fmt_alarm_clock(hour, minute)
    try:
        _get_app_data().cal_set_med_schedule(med.get('id'), next_time=clock,
                                             freq=freq)
    except Exception as exc:
        logger.debug("med schedule failed: %s", exc)
        return ("I couldn't save that reminder — set the time in the Meds app "
                "and I'll take it from there.")
    cadence = "every weekday" if freq == "weekdays" else "every day"
    label = _med_spoken_label(med)
    if stated:
        return "Set — I'll remind you about %s %s at %s." % (label, cadence,
                                                             clock)
    return ("Set — I'll remind you about %s %s at %s, the app's default time. "
            "Say another time and I'll move it." % (label, cadence, clock))


#: "set up a daily reminder for my medication in the morning" — a request
#: for a medication schedule that names NO medication. ``_try_med_log`` owns
#: the shape that names one ("remind me to take my X at 8"); this owns the one
#: that does not, which without a deterministic owner can end up writing the
#: sentence into the medication list.
_MED_SCHEDULE_ASK_RE = re.compile(
    r"(?i)\b(?:remind|reminder|reminders)\b[^.?!]{0,60}?\b(?:my|the|a)\s+"
    r"(?:medications?|medicines?|meds?|pills?|prescriptions?)\b"
    r"|\b(?:my|the)\s+(?:medications?|medicines?|meds?|pills?)\b"
    r"[^.?!]{0,30}?\breminders?\b")

_MED_SCHEDULE_ASK = (
    "Before I set that up — what's the medication called, what dose, and "
    "what time should I remind you? I haven't written anything down yet.")

#: "10 mg" / "two tablets" / "5 units".
_MED_DOSE_RE = re.compile(
    r"(?i)\b(\d+(?:\.\d+)?\s*(?:mg|milligrams?|mcg|micrograms?|g|grams?|"
    r"ml|milliliters?|units?|iu|tablets?|tabs?|pills?|capsules?|caps?|"
    r"drops?|puffs?|doses?))\b")


def _med_schedule_answer_parts(said: str):
    """(name, dose, (hour, minute)) from "lisinopril, 10 milligrams, 7 AM"."""
    text = " ".join(str(said or "").split())
    dose_found = _MED_DOSE_RE.search(text)
    dose = dose_found.group(1).strip() if dose_found else None
    when = _parse_alarm_time(_normalize_spoken_clock(text.lower()))
    parts = [c.strip(" .,!?") for c in re.split(r"[,;]| and ", text)
             if c.strip(" .,!?")]
    name = None
    for part in parts:
        candidate = re.sub(r"(?i)^(?:it's|its|it\s+is|the|my|a|an|call(?:ed)?|"
                           r"name\s+is)\s+", "", part).strip(" .,!?")
        if not candidate or _MED_DOSE_RE.search(candidate):
            continue
        if _MED_NOT_A_NAME_RE.search(candidate):
            continue
        if _med_looks_like_a_drug(candidate):
            name = candidate
            break
    return name, dose, when


def _complete_med_schedule(_chosen, said: str, known=None) -> "str | None":
    """The answer to the ask: write the row ONCE, with a read-back.

    Nothing is written until the medication has a name AND a time — the two
    things the question asked for. A half answer re-asks (registering the
    question again) rather than committing a guess to the medication list.
    """
    known = dict(known or {})
    name, dose, when = _med_schedule_answer_parts(said)
    # Half an answer is kept, not thrown away: "lisinopril" then "7 AM" is one
    # medication, said over two turns.
    name = name or known.get("name")
    dose = dose or known.get("dose")
    when = when if when is not None else known.get("when")
    if not name or when is None:
        missing = []
        if not name:
            missing.append("what it's called")
        if when is None:
            missing.append("what time")
        sentence = ("I still need %s — say it again and I'll set the "
                    "reminder up. Nothing is written down yet."
                    % " and ".join(missing))
        carried = {"name": name, "dose": dose, "when": when}

        def _again(chosen, text, carried=carried):
            return _complete_med_schedule(chosen, text, carried)

        try:
            _pending_clarifier.register("med_schedule", _again,
                                        prompt=sentence)
        except Exception as exc:      # pragma: no cover - never worth the ask
            logger.debug("med clarifier not re-registered: %s", exc)
        return sentence
    refusal = _med_name_refusal(name, source=said)
    if refusal:
        return refusal
    hour, minute = when
    clock = _fmt_alarm_clock(hour, minute)
    freq = "weekdays" if re.search(r"(?i)\bweekdays?\b", said) else "daily"
    try:
        _get_app_data().cal_add_med(name, dose or "1 dose", "all",
                                    freq=freq, next_time=clock)
    except Exception as exc:
        logger.debug("med schedule write failed: %s", exc)
        return ("I couldn't save that reminder — add it in the Meds app and "
                "I'll track it from there.")
    cadence = "every weekday" if freq == "weekdays" else "every day"
    dose_said = (", %s" % dose) if dose else ""
    # The row is confirmed by its GENERIC label and never by the drug name
    # (a drug name is never spoken aloud), exactly like every other spoken
    # medication reply.
    return ("Added %s%s — I'll remind you %s at %s."
            % (_MED_GENERIC_SPOKEN_LABEL, dose_said, cadence, clock))


def _try_med_schedule_ask(user_message: str) -> "str | None":
    """A medication reminder with no medication named: ASK, and write nothing.

    Without a deterministic owner this utterance reaches the agent, which can
    ask the right three questions AND let the repair path write a medication
    called "up a daily reminder for my medication in the morning" with a
    fabricated 8:00 AM dose. Asking and writing in the same breath is the
    defect; this asks, remembers that it
    asked (:mod:`puffpai.pending_clarifier`), and the ANSWER writes the row.

    With exactly one medication already on file there is nothing to ask about
    — that row is scheduled, the same way ``_try_med_log`` schedules a named
    one.
    """
    text = (user_message or "").strip()
    if not text or len(text) > 200:
        return None
    if re.search(r"(?i)\b(?:what|which|how\s+many|list|show|did\s+i|do\s+i|"
                 r"delete|remove|cancel|stop)\b", text):
        return None
    if not _MED_SCHEDULE_ASK_RE.search(text):
        return None
    rows = _med_rows()
    if len(rows) == 1:
        return _med_set_schedule(rows[0], text)
    try:
        _pending_clarifier.register("med_schedule", _complete_med_schedule,
                                    prompt=_MED_SCHEDULE_ASK)
    except Exception as exc:          # pragma: no cover - never worth the ask
        logger.debug("med clarifier not registered: %s", exc)
    return _MED_SCHEDULE_ASK


def _try_med_log(user_message: str) -> str | None:
    """"I took my X" and "remind me to take my X at 8" — one step, no name.

    Registered just BEFORE the calendar/task fastpaths so the schedule shape
    reaches a medication rather than becoming a plain to-do — but ONLY when the
    medication is actually on file. An unknown name keeps ``_try_add_task``,
    the owner of "remind me to take my blood pressure pill at 8" on
    all five surfaces: for a reminder, a real to-do is a better
    outcome than a refusal.
    """
    text = (user_message or "").strip()
    if not text or len(text) > 200:
        return None
    if re.search(r"(?i)\b(?:what|which|how\s+many|list|show|did\s+i|do\s+i)\b",
                 text):
        return None
    rows = _med_rows()

    schedule = _MED_SCHEDULE_RE.search(text)
    if schedule:
        med = _med_resolve(_med_clean_name(schedule.group("name")), rows)
        if med == "many":
            return ("I have more than one medication on file — say which one "
                    "and I'll set the reminder.")
        if not med:
            return None                      # a plain reminder; see docstring
        return _med_set_schedule(med, text)

    for rx in _MED_LOG_RES:
        m = rx.search(text)
        if not m:
            continue
        name = _med_clean_name(m.group("name"))
        if not name:
            return None
        med = _med_resolve(name, rows)
        if med == "many":
            return ("I have more than one medication on file — say which one "
                    "and I'll log it.")
        if med:
            try:
                _get_app_data().cal_take_med(med.get('id'))
            except Exception as exc:
                logger.debug("med log failed: %s", exc)
                return None
            return "Logged %s as taken." % _med_spoken_label(med)
        # Nothing on file. Say so once, plainly, without repeating the name.
        if _MED_NOUN_RE.search(text) or _med_looks_like_a_drug(name):
            return _MED_NOT_ON_FILE
        return None
    return None


def _try_med_list(user_message):
    """"what meds do I have" reads the list instead of asking a model to guess.

    This fastpath is registered ~100 lines ahead of
    ``_try_household_read`` and is called directly on the three branches that
    never reach ``_try_instant_answer``, so it PREEMPTS
    ``household_reads.medication_status`` - and that function is not a thin
    wrapper around ``cal_list_meds()``. It carries two deliberate medication
    hedges ("Please don't treat that as confirmation that you did or didn't
    take one", "I can only report what has been logged") which a reproduced
    reply here would silently drop on both flag states.

    So the reply is DELEGATED rather than reproduced: one owner for the wording,
    and a later edit there cannot drift away from a copy kept here.
    """
    if not _MED_LIST_RE.search(user_message or ""):
        return None
    try:
        from puffpai.agents.household_reads import medication_status
        return medication_status(_get_app_data())
    except Exception as exc:
        logger.debug("med-list fastpath failed: %s", exc)
        return None


def _try_med_fastpath(user_message):
    """The three medication rules in one call, reads before writes.

    Registered in ``_try_instant_answer`` for the surfaces that consult it, and
    called directly by the two streaming-RAG branches that do not. Exactly one
    of those two reaches any given turn, so a medication is never written twice.
    """
    listed = _try_med_list(user_message)
    if listed:
        return listed
    logged = _try_med_log(user_message)
    if logged:
        return logged
    taken = _try_med_take(user_message)
    if taken:
        return taken
    return _try_med_add(user_message)


def _try_shopping_add(user_message: str) -> str | None:
    """"add oat milk to the shopping list" — one store, one read-back.

    Deterministic, like ``_try_meal_add``: no model, no tool menu. The team
    route reaches the same writer (Steward ``list_add`` →
    ``shopping_writes.add_verified``), so this fastpath is not a second
    implementation: it removes the model from the simple case, where the
    model is the weak link. The reply is composed from the store AFTER the
    write, so an add that did not land says so.
    """
    if not _app_installed('freshtable'):
        return None
    try:
        from puffpai.agents import shopping_writes
        return shopping_writes.handle(user_message)
    except Exception as exc:
        logger.debug("shopping-add fastpath failed: %s", exc)
        return None


def _try_shopping_remove(user_message: str) -> str | None:
    """"remove oat milk from the shopping list" — the inverse of the add.

    Without a spoken remove path, "remove X from the shopping list" and
    "cross X off" both fall through to a READ that recites the whole list.
    Same store, same read-back discipline as
    ``_try_shopping_add``; an item that was never there is told plainly and an
    ambiguous name removes nothing.
    """
    if not _app_installed('freshtable'):
        return None
    try:
        from puffpai.agents import shopping_writes
        return shopping_writes.handle_remove(user_message)
    except Exception as exc:
        logger.debug("shopping-remove fastpath failed: %s", exc)
        return None


#: "Which thermostat do you mean: Bedroom, Living Room?" — and the same
#: question scoped to a room phrase that matched two units.
_THERMOSTAT_ASK_RE = re.compile(
    r"(?i)^Which thermostat do you mean(?:\s+for\s+'[^']*')?:\s*"
    r"(?P<names>[^?]+)\?$")


def _remember_thermostat_question(user_message: str, reply: str) -> None:
    """Keep the rooms just offered, so "the living room" sets it.

    The setpoint is already known — only the room was missing — so the
    answer is completed by re-running the fastpath against the room the
    household named. Same write, same read-back, same wording as if the room
    had been said the first time.
    """
    found = _THERMOSTAT_ASK_RE.match(" ".join(str(reply or "").split()))
    if not found:
        return
    try:
        from puffpai.agents import climate_writes
        temperature = climate_writes.parse_temperature(user_message)
    except Exception as exc:          # pragma: no cover - import guard
        logger.debug("thermostat clarifier unavailable: %s", exc)
        return
    if temperature is None:
        return
    names = [n.strip() for n in found.group("names").split(",") if n.strip()]
    if len(names) < 2:
        return
    setpoint = (int(temperature) if float(temperature).is_integer()
                else temperature)

    def _complete(chosen, said, setpoint=setpoint):
        rooms = [c["value"] for c in (chosen or [])]
        if not rooms:
            return None
        from puffpai.agents import climate_writes as _cw
        return _cw.handle("set the %s to %s"
                          % (" and the ".join(rooms), setpoint),
                          _get_ha_bridge())

    try:
        _pending_clarifier.register("thermostat_room", _complete, names,
                                    prompt=reply)
    except Exception as exc:          # pragma: no cover - never worth the ask
        logger.debug("thermostat clarifier not registered: %s", exc)


def _try_climate_set(user_message: str, conversation_history=None) -> str | None:
    """"set the living room and bedroom to 74" — every target, every read-back.

    Deterministic, like ``_try_shopping_add``: no model, no tool menu, and the
    confirmation is composed from what the thermostats report AFTER the calls.
    The team route it replaces for this shape resolves a SINGLE entity
    (``concierge._delegate_to_steward``), which can set one thermostat
    and confirm two. Declines everything that is not a setpoint command, and
    asks which room when nothing in the turn or the two turns before it names
    one. See :mod:`puffpai.agents.climate_writes`.
    """
    try:
        from puffpai.agents import climate_writes
        reply = climate_writes.handle(user_message, _get_ha_bridge(),
                                      conversation_history)
    except Exception as exc:
        logger.debug("climate-set fastpath failed: %s", exc)
        return None
    if reply:
        _remember_thermostat_question(user_message, reply)
    return reply


def _try_meal_add(user_message: str, conversation_history=None) -> str | None:
    """Put a recipe from THIS conversation onto the FreshTable plan.

    On the agent route, "Add both of those salmon recipes to the dinner meals
    for this week" → clarify → "Wednesday and Thursday" → confirm → "Yes
    please, that's perfect" ends in "I don't have a tool in this environment
    that can actually create or schedule recipes inside FreshTable." The
    registry declares ``meal_set`` under ``food.mealplan``, so the claim is
    false, but the model is not lying: ``capability_registry.tools_for_query``
    binds from the CURRENT utterance, and a bare confirmation carries no food
    keyword, so the bind falls through to the three-tool safety floor in
    ``AssistantTools._filter_tools_by_intent``. A clarify → confirm flow cannot
    complete on the agent route by construction.

    This owns the flow deterministically (no model, no tool menu) and carries
    the recipe BODY across, so FreshTable shows a real recipe rather than a
    bare name. See ``puffpai.agents.meal_writes``. Declines every turn where no
    recipe was surfaced earlier and no request is pending, so "plan this week's
    meals" and "what's for dinner" keep their own paths.
    """
    if not _app_installed('freshtable'):
        return None
    try:
        from puffpai.agents import meal_writes as _meal_writes
        from_context = _meal_writes.handle(user_message, conversation_history)
        if from_context:
            return from_context
        # The dish was said out loud instead ("set thursday dinner to
        # tacos"). Without a deterministic path it falls to RAG, which
        # answers by suggesting the user say the sentence they had just said.
        return _meal_writes.handle_direct(user_message)
    except Exception as exc:
        logger.debug("meal-add fastpath failed: %s", exc)
        return None


_MEAL_PLAN_RE = re.compile(
    r"\bplan\b[^.]{0,24}\b(?:meal|meals|dinner|dinners|menu)\b"
    r"|\b(?:make|set\s+up|sort\s+out|put\s+together|prep)\b[^.]{0,24}"
    r"\b(?:meal\s+plan|meals|menu|dinners|meal\s+prep)\b"
    # "plan the week starting Monday" carries no meal noun at all, so
    # without this it would match nothing and fall to the agent route, which calls
    # auto_meal_plan with no confirmation. It is a week-planner command; it
    # belongs on the guarded path where it gets asked about first.
    r"|\bplan\b\s+(?:the\s+|my\s+|our\s+|this\s+|next\s+)?week\b",
    re.IGNORECASE)


def _try_meal_plan(user_message: str) -> str | None:
    """"Plan this week's meals" must actually WRITE the FreshTable meal plan.
    Otherwise the phrase is swallowed by the planner (which has no meal
    capability) or by RAG, both can answer "done" without saving anything, so
    nothing appears in FreshTable or on the dashboard tile. auto_meal_plan
    owns the plan and persists it to the canonical store the app + tile read,
    and returns its own HONEST result (a real plan, or "came back empty"). Only
    a plan/make-meals COMMAND fires; "what's for dinner tonight" and "show me
    the meal plan" (a read / a page) fall through to their own paths.
    """
    if not _app_installed('freshtable'):
        return None
    try:
        from puffpai.agents import meal_plan_guard as _guard
    except Exception as exc:          # pragma: no cover - import guard only
        logger.debug("meal-plan guard unavailable: %s", exc)
        _guard = None

    def _run_plan(preserve=None, constraint=""):
        # confirm=True is the guarded fastpath's signature: auto_meal_plan
        # refuses to replace a non-empty plan without it, so the agent route
        # cannot bypass the confirmation turn.
        # The days that already carry a dish are passed through as
        # `preserve` so they are never generated over, and the dietary word
        # from the ORIGINAL ask ("vegetarian") travels with the confirmation.
        return _get_assistant_tools().tool_dict['auto_meal_plan'].invoke(
            {"confirm": True,
             "preserve": ",".join(preserve or []),
             "dietary_preferences": str(constraint or "")})

    # "yes, replace the plan" carries no meal keyword, so the standing
    # confirmation has to be consulted BEFORE the intent regex or the answer
    # falls through to RAG and the plan is never written.
    if _guard is not None and _guard.get_pending():
        blocked = _app_unavailable_reason('freshtable')
        answered = _guard.pending_reply(
            user_message, (lambda: blocked) if blocked else _run_plan)
        if answered:
            return answered
    lower = (user_message or "").lower()
    if not _MEAL_PLAN_RE.search(lower):
        # A slot request the writers above could not resolve
        # ("put that on Thursday's meal plan", "plan tacos for Thursday") must
        # not return None here and reach the agent route, which can still
        # rewrite the whole week. Ask which dish and which day instead.
        if _guard is not None and not _app_unavailable_reason('freshtable'):
            return _guard.single_item_ask(user_message)
        return None
    # An app that cannot work says so, in one sentence, BEFORE it starts. The
    # alternative is auto_meal_plan getting halfway and returning
    # "came back empty", which reads as "you have no meals" rather than "this
    # build has no model". It is checked AFTER the intent match: a build with
    # no model must not answer every unrelated sentence with FreshTable's
    # unavailability.
    # A phrase that names ONE dish, ONE day or one slot must never
    # reach auto_meal_plan — it rewrites all seven days and rebuilds the whole
    # shopping list. Checked BEFORE the availability probe so a single-item
    # turn is handed on untouched rather than answered by FreshTable.
    if _guard is not None and _guard.names_a_single_item(user_message):
        return None
    unavailable = _app_unavailable_reason('freshtable')
    if unavailable:
        return unavailable
    try:
        if _guard is None:
            return _run_plan()
        # Replacing a non-empty plan asks first; an empty one proceeds but
        # still says what it did.
        return _guard.plan_reply(user_message, _run_plan)
    except Exception as exc:
        logger.debug("meal-plan fastpath failed: %s", exc)
        return None


_LIST_AGENTS_RE = re.compile(
    r"\byour\s+(?:agent\s+team|agents?|team)\b"
    r"|\b(?:what|which)\s+agents?\b"
    r"|\bagent\s+team\b"
    r"|\bwho(?:'s|\s+is|\s+are)\s+on\s+(?:your|the)\s+team\b"
    r"|\bhow many agents\b"
    r"|\b(?:list|name)\s+(?:your\s+|the\s+|all\s+)?agents\b",
    re.IGNORECASE)


def _try_list_agents(user_message: str) -> str | None:
    """"What agents are on your team?" → the real roster, not a persona
    guess. Otherwise it goes to the self-reference/persona path and can come
    back "couldn't complete that one". list_agents reads the live agent bus.
    Kept tight so "what can you do" (a broad persona question) is left alone,
    and an "ask the <agent>" command is deferred to the ask-agent fastpath.
    """
    lower = (user_message or "").lower()
    if len(lower) > 100 or not _LIST_AGENTS_RE.search(lower):
        return None
    if re.search(r"(?i)\b(?:ask|tell|have|route|get)\s+(?:the\s+|your\s+)?"
                 r"(?:concierge|steward|archivist|sentinel|majordomo|"
                 r"caretaker|toolsmith)\b", lower):
        return None
    try:
        tools = _get_assistant_tools()
        return tools.tool_dict['list_agents'].invoke('')
    except Exception as exc:
        logger.debug("list-agents fastpath failed: %s", exc)
        return None


_ASK_AGENT_RE = re.compile(
    r"(?i)\b(?:ask|tell|have|get|route\s+(?:this|it|that)\s+to)\s+"
    r"(?:the\s+|your\s+|my\s+)?"
    r"(concierge|steward|archivist|sentinel|majordomo|caretaker|toolsmith|"
    r"dispatcher|butler|scheduler|watchdog|librarian|guard)\b"
    r"\s*(?:to\s+|and\s+|,\s*|please\s+)?(.*)")


def _try_ask_agent(user_message: str) -> str | None:
    """"Ask the steward how many devices" → route to that ONE agent and speak
    its reply. Otherwise it goes to the general agent path, which can deflect
    ("I haven't checked yet..."). ask_agent hands the task to the named agent
    over the real bus. Only fires when a recognizable agent name follows an
    ask/tell/have verb AND a task follows the name; ask_agent itself resolves
    aliases and display names.
    """
    text = (user_message or "").strip()
    if len(text) > 160:
        return None
    m = _ASK_AGENT_RE.search(text)
    if not m:
        return None
    agent = m.group(1).strip()
    task = (m.group(2) or "").strip(" .?!,")
    if not task:
        return None
    try:
        tools = _get_assistant_tools()
        return tools.tool_dict['ask_agent'].invoke(f"{agent} | {task}")
    except Exception as exc:
        logger.debug("ask-agent fastpath failed: %s", exc)
        return None


_CAPABILITIES_RE = re.compile(
    # ── the core phrasings ──────────────────────────────────────────────────
    r"\bwhat\s+can\s+you\s+(?:do|access|help|handle|reach|offer|manage|use)\b"
    r"|\bwhat\s+(?:are\s+your\s+capabilities|can\s+you\s+do\s+with)\b"
    r"|\bwhat\s+are\s+you\s+(?:capable|able)\b"
    r"|\bwhat\s+all\s+can\s+you\s+do\b"
    r"|\bwhat\s+can\s+i\s+ask\s+you\b"
    r"|\bwhat\s+do\s+you\s+have\s+access\s+to\b"
    r"|\b(?:list|show)\s+(?:me\s+)?your\s+capabilities\b"
    # ── the wider phrasings ─────────────────────────────────────────────────
    # Unmatched, "list your skills" gets a software-engineer resume (Python,
    # React, Docker, Kubernetes); "give me a rundown of everything you can
    # help with" invents plumbing and first-aid; "what functions do you
    # support" blends real features with emergency medicine. The registry
    # read is phrasing-bound, so every miss becomes a fabrication. Each
    # alternative below carries its own second-person anchor (you / your /
    # you're), which is also what keeps "what skills does a nurse need" and
    # "list Python skills for a resume" out — see _CAPABILITIES_NOT_ABOUT_ME_RE
    # for the requests that name a person or a job even while saying "you".
    r"|\b(?:list|show|tell|give|name)\s+(?:me\s+)?(?:all\s+|of\s+)?"
    r"(?:your|the)\s+(?:skills?|abilities|features?|functions?|commands?|"
    r"capabilities|tools?)\b"
    r"|\bwhat\s+(?:are\s+)?your\s+(?:skills?|abilities|features?|functions?|"
    r"commands?|strengths?)\b"
    r"|\bwhat\s+(?:skills?|abilities|features?|functions?|commands?|services?|"
    r"things?)\s+(?:do|does|can)\s+you\s+(?:have|support|offer|do|provide|"
    r"handle|know)\b"
    r"|\bwhat\s+do\s+you\s+(?:know\s+how\s+to\s+do|do\s+around\s+here)\b"
    r"|\bwhat\s+are\s+you\s+good\s+at\b"
    r"|\bwhat\s+else\s+can\s+you\s+(?:do|help|handle)\b"
    r"|\bwhat\s+else\s+do\s+you\s+do\b"
    r"|\bwhat\s+can'?t\s+you\s+do\b|\bwhat\s+cannot\s+you\s+do\b"
    r"|\bwhat\s+are\s+you\s+not\s+able\s+to\s+do\b"
    r"|\bshow\s+me\s+what\s+you\s+can\s+do\b"
    r"|\bwalk\s+me\s+through\s+what\s+you(?:'?re|\s+are)?\s+(?:able|can)\b"
    r"|\brundown\s+of\s+(?:everything|all|what)\b[^.?!]{0,20}\byou\b"
    r"|\b(?:everything|all)\s+you\s+can\s+(?:do|help)\b"
    r"|\bwhat\s+(?:can|do)\s+you\s+help\s+(?:me\s+)?with\b"
    r"|\bhow\s+can\s+you\s+help\b"
    r"|\bwhat\s+kind\s+of\s+(?:things?|stuff)\s+can\s+you\s+do\b"
    r"|\bwhat\s+can\s+i\s+(?:ask|tell|say\s+to)\s+you\b"
    r"|\bwhat\s+are\s+you\s+for\b"
    # A bare "help" (and nothing else) is a request for the menu. "help me"
    # is deliberately NOT here: it can be a person in trouble, and that must
    # not be answered with a feature list.
    r"|\A\W*help\W*\Z",
    re.IGNORECASE)

#: A capability phrasing that is really about somebody else's skills.
#:
#: The second-person anchor above already declines "what skills does a nurse
#: need" (no "you"), but "can you list Python skills for a resume" says "you"
#: while asking for encyclopedia content. Those stay on RAG.
_CAPABILITIES_NOT_ABOUT_ME_RE = re.compile(
    r"\b(?:resum(?:e|é)|cv|curriculum\s+vitae|job|jobs|career|careers|"
    r"interview|hiring|employer|employee|employers|candidate|applicant|"
    r"nurse|nurses|doctor|teacher|plumber|electrician|accountant|lawyer|"
    r"programmer|developer|engineer)\b"
    r"|\bskills?\s+(?:does|do)\s+(?:a|an|the|my|i|we|you\s+think)\b"
    r"|\bskills?\s+(?:for|needed\s+for|required\s+for)\s+(?:a|an|the)\b"
    r"|\b(?:python|javascript|java|c\+\+|sql|react|docker|kubernetes)\b",
    re.IGNORECASE)


#: A question about the WEB tools specifically, asked as the whole question.
#:
#: "what can you do" honestly marks "web tools (off - Settings > Egress)", but
#: without this "what web tools do you have" never reaches the registry at all:
#: it falls to ZIM RAG and is answered from a book about classroom web tools.
#: A user asking the direct question would be told PuffPAI has web tools and
#: NOT told they are switched off, which is the exact overstatement the marker
#: exists to prevent, reachable by rephrasing.
#:
#: Anchored to the whole utterance on purpose. "can you search the web" is a
#: question about the capability; "can you search the web FOR the price of X"
#: is a task, and belongs to the tool that would do it (which refuses honestly
#: on its own when its door is shut). The anchors keep those apart.
_WEB_TOOLS_ASK_RE = re.compile(
    r"^\W*(?:so\s+|but\s+|hey\s+|puff\s+)*"
    r"(?:"
    r"(?:what|which)\s+(?:kind\s+of\s+|sort\s+of\s+)?"
    r"(?:web|internet|online)\s+(?:tools?|access|searches?|capabilit\w+)\b"
    r"[^.?!]{0,30}"
    r"|can\s+you\s+(?:search|browse|access|use|look\s+things\s+up\s+on)\s+"
    r"(?:the\s+)?(?:web|internet|online)"
    r"|can\s+you\s+(?:go|get)\s+online"
    r"|do\s+you\s+have\s+(?:web|internet)\s+access"
    r")\s*\??\s*$",
    re.IGNORECASE)


#: The half of a capability question that asks WHO, not WHAT.
#:
#: ``prove``'s live identity question is "Who are you and what are you for?" -
#: one sentence that asks both. It matched ``_CAPABILITIES_RE`` and was answered
#: with the capability list alone, so a build whose owner had named it Infinity
#: and said what it was for introduced itself as a feature inventory. The list
#: is right and stays; it is now preceded by the one sentence that answers the
#: other half, from the same source the system prompt's build block uses.
_IDENTITY_ASK_RE = re.compile(
    r"\bwho\s+are\s+you\b"
    r"|\bwhat\s+are\s+you\s+for\b"
    r"|\bwhat(?:'s|\s+is)\s+your\s+purpose\b",
    re.IGNORECASE)


def _identity_line() -> str:
    """"I'm <name> - <what the owner said this build is for>." Never raises.

    The name is the identity rule's answer and the goal is
    ``build_context.collect_goal()``: the same two values the build block in
    the system prompt carries, so the deterministic answer and the model's
    answer cannot introduce two different bots.
    """
    from puffpai import build_context

    try:
        name = _live_ai_name()
    except Exception:
        name = AI_NAME
    if not name:
        return ""
    try:
        goal = build_context._plain(build_context.collect_goal(),
                                    build_context.MAX_GOAL_CHARS)
    except Exception:
        goal = ""
    return f"I'm {name} — {goal}." if goal else f"I'm {name}."


def _try_capabilities(user_message: str) -> str | None:
    """"What can you access?" answers from the capability registry — the single
    source of truth — not a persona guess. This is the introspection half of
    the registry: PuffPAI describing her own capabilities as ONE system, where
    voice, the dashboard, and the app pages are surfaces of the same capability
    rather than separate abilities. Kept deliberately narrow so a knowledge
    question ("what do you know about X") is NOT hijacked — that keeps its own
    path.
    """
    lower = (user_message or "").lower()
    if len(lower) > 120:
        return None
    if not (_CAPABILITIES_RE.search(lower) or _WEB_TOOLS_ASK_RE.search(lower)):
        return None
    # "list Python skills for a resume" says "your skills" shapes too — that
    # is an encyclopedia question about somebody's job, not introspection.
    if _CAPABILITIES_NOT_ABOUT_ME_RE.search(lower):
        return None
    try:
        from puffpai import capability_registry as capreg
        answer = capreg.describe_for(user_message)
    except Exception as exc:
        logger.debug("capabilities fastpath failed: %s", exc)
        return None
    if answer and _IDENTITY_ASK_RE.search(lower):
        line = _identity_line()
        if line:
            answer = f"{line} {answer}"
    return answer


_DASH_WORD_RE = re.compile(
    r"\b(dashboard|widget|widgets|news feed|rss feed|feed|tile)\b", re.IGNORECASE)
_DASH_ADD_RE = re.compile(r"\b(add|put|create|pin|set up)\b", re.IGNORECASE)
_DASH_REMOVE_RE = re.compile(
    r"\b(remove|delete|get rid of|drop)\b|\btake\b.{0,30}\boff\b"
    r"|\boff (?:my|the)\b", re.IGNORECASE)
_DASH_LIST_RE = re.compile(r"\b(what|which|list|show me)\b", re.IGNORECASE)
_CAM_WORD_RE = re.compile(r"\bcameras?\b|\bcams?\b", re.IGNORECASE)
_CAM_SHOW_RE = re.compile(
    r"\b(show|display|pull up|bring up|put up|open up)\b", re.IGNORECASE)


#: Words that are structural to a feed request rather than the source name.
#: Anything left over after removing these is treated as a named source.
_FEED_STOPWORDS = frozenset({
    "add", "a", "an", "the", "my", "our", "to", "on", "for", "please",
    "news", "feed", "feeds", "rss", "dashboard", "widget", "tile", "new",
    "set", "up", "put", "create", "make", "show", "with", "of", "from",
})


def _names_an_unknown_feed_source(low: str, dw) -> bool:
    """True when the request names a source the feed directory does not carry.

    "add a news feed"      -> False (nothing named; the menu is the right answer)
    "add a NASA news feed" -> True  (NASA named; go find its URL instead)
    """
    import re as _re
    known = {w for name in dw.FEED_DIRECTORY for w in name.lower().split()}
    words = [w for w in _re.findall(r"[a-z0-9][a-z0-9'-]*", low)
             if w not in _FEED_STOPWORDS and w not in known and len(w) > 1]
    return bool(words)


def _try_dashboard_manage(user_message: str) -> str | None:
    """Add / remove / list dashboard widgets, deterministically.

    The widget backend (dashboard_widgets.py — add_widget/remove_widget/
    list_widgets, a self-describing WIDGET_CATALOG, and a FEED_DIRECTORY that
    already knows BBC/NPR/Guardian/…) is complete and good, but the
    agent/planner path can't reach it: live, "what's on my dashboard" deflected
    and "add a BBC news feed" returned a device list. This routes the
    dashboard-management intent straight to the owning functions (same pre-team
    intercept as the other fixes) and reads the LIVE catalog + feed directory,
    so a feed or widget type added there is reachable with no change here.
    """
    low = (user_message or "").lower()
    if not _DASH_WORD_RE.search(low):
        return None
    try:
        from puffpai import dashboard_widgets as dw
    except Exception as exc:
        logger.debug("dashboard fastpath import failed: %s", exc)
        return None

    is_add = bool(_DASH_ADD_RE.search(low))
    is_remove = bool(_DASH_REMOVE_RE.search(low))

    # ── CAMERA on the dashboard ──
    # "put/show/add my front door camera on my dashboard". The widget-add
    # loop below skips cameras (Sentinel-gated), so resolve the camera name
    # and run the Bridge->Sentinel->registry pipeline here, before the
    # snapshot rule downstream can steal a "show ... camera" phrasing.
    if (_CAM_WORD_RE.search(low) and not is_remove
            and (is_add or _CAM_SHOW_RE.search(low))):
        name = re.sub(
            r"\b(show|put|add|pin|create|set|up|display|pull|bring|place|"
            r"get|the|a|an|my|our|on|onto|to|please|camera|cam|cams|feed|"
            r"tile|dashboard|screen|me|can|you|i|want|would|like)\b",
            " ", low)
        name = " ".join(name.split()).strip()
        if name:  # a specific camera was named
            try:
                from puffpai import dashboard_registry as _dreg
                bridge = _get_assistant_tools()._ha_bridge
                _ok, msg = _dreg.add_camera_validated(
                    bridge, name, added_by="voice",
                    task_text="dashboard fastpath: " + (user_message or "")[:120])
                return msg
            except Exception as exc:
                logger.debug("dashboard camera add failed: %s", exc)
                return None

    # ── REMOVE ──
    if is_remove and not is_add:
        # camera off the dashboard (registry-backed; widgets can't see
        # cameras). Match the name against on-dashboard cameras, remove by id.
        if _CAM_WORD_RE.search(low):
            try:
                from puffpai import dashboard_registry as _dreg
                _nm = re.sub(r"\b(remove|delete|take|off|get|rid|of|drop|"
                             r"the|a|an|my|our|from|please|camera|cam|cams|"
                             r"widget|tile|dashboard|screen)\b", " ", low)
                _toks = set(_nm.split())
                _best = None
                for _c in _dreg.list_cameras():
                    _hay = re.sub(r"[._]", " ", ((_c.get("label") or "")
                                  + " " + (_c.get("entity_id") or "")).lower())
                    _s = sum(1 for _t in _toks if _t and _t in _hay)
                    if _s and (_best is None or _s > _best[0]):
                        _best = (_s, _c.get("entity_id"), _c.get("label"))
                if _best:
                    _ok = _dreg.remove_camera(_best[1])
                    return ("Took " + str(_best[2]) + " off your dashboard."
                            if _ok else
                            str(_best[2]) + " wasn't on your dashboard.")
            except Exception as _exc:
                logger.debug("dashboard camera remove failed: %s", _exc)
        target = re.sub(
            r"\b(remove|delete|take|off|get rid of|drop|the|a|an|my|from|"
            r"of|please|widget|tile|feed|dashboard|to)\b", " ", low)
        target = " ".join(target.split()).strip()
        if not target:
            return "Which widget should I remove? Tell me its name or type."
        _ok, msg = dw.remove_widget(target)
        return msg

    # ── ADD ──
    if is_add and not is_remove:
        props: dict = {}
        source = next((name for name in dw.FEED_DIRECTORY if name in low), None)
        murl = re.search(r"(https?://\S+)", user_message)
        wants_news = ("news" in low or "feed" in low or "rss" in low
                      or source is not None)
        if wants_news:
            if source:
                props["source"] = source
            if murl:
                props["url"] = murl.group(1)
            if not props:
                # The menu is the RIGHT answer to "add a news feed" — the person
                # named no source, so listing the known ones helps. It is the
                # WRONG answer to "add a NASA news feed": they named a source
                # this directory does not carry, and answering with a list of
                # six other sources asks them to do the lookup the appliance
                # could do itself. That was the live complaint.
                #
                # So defer ONLY when a source was named and not recognised: this
                # intercept runs BEFORE the team, and returning None lets the
                # turn reach the planner, which can search for the feed URL and
                # compose it with this same add path. If the planner does not
                # finish, _try_team_chat's guard degrades the turn to the legacy
                # agent, so deferring cannot leave the person with nothing.
                if _names_an_unknown_feed_source(low, dw):
                    return None
                known = ", ".join(sorted(dw.FEED_DIRECTORY))
                return (f"Which news source? I know {known} — or give me a feed "
                        f"URL. For example, 'add a BBC news feed to my dashboard'.")
            _ok, msg, _w = dw.add_widget("news", props, added_by="voice")
            return msg
        # a non-news catalog type named in the query? (match key or title word)
        for wtype, meta in dw.WIDGET_CATALOG.items():
            if wtype == "camera":
                continue  # cameras are Sentinel-gated — keep their own path
            title_words = [w for w in meta.get("title", "").lower()
                           .replace("&", " ").split() if len(w) > 3]
            if (wtype in low or wtype.replace("-", " ") in low
                    or any(w in low for w in title_words)):
                _ok, msg, _w = dw.add_widget(wtype, {}, added_by="voice")
                return msg
        types = ", ".join(t for t in sorted(dw.WIDGET_CATALOG) if t != "camera")
        return (f"What would you like to add? For your dashboard I can add: "
                f"{types}, plus news feeds like BBC or NPR.")

    # ── LIST / read-out ──
    if _DASH_LIST_RE.search(low):
        widgets = dw.list_widgets(include_cameras=True)
        types = ", ".join(sorted(dw.WIDGET_CATALOG))
        if not widgets:
            return (f"Your dashboard has no widgets yet. You can add: {types}, "
                    f"plus news feeds like BBC or NPR.")
        names = "; ".join((w["props"].get("title") or w["type"]) for w in widgets)
        return (f"Your dashboard has {len(widgets)} item(s): {names}. "
                f"You can add more — types: {types}.")
    return None


_SHOW_VERB_RE = re.compile(
    r"\b(show me|pull up|bring up|put up|display|open up)\b", re.IGNORECASE)
_SHOW_CONTENT_RE = re.compile(
    r"\b(video|talk|ted\s*talk|ted|article|page|document|entry|wikipedia|"
    r"lecture|clip)\b", re.IGNORECASE)
_SHOW_HIDE_RE = re.compile(
    r"\b(clear|hide|dismiss|close|take (?:it|that) (?:down|off)|"
    r"nothing|never ?mind)\b.{0,20}\b(screen|display|dashboard|it|that)\b"
    r"|\b(clear|hide) (?:the )?(?:screen|display)\b", re.IGNORECASE)


def _try_show(user_message: str) -> str | None:
    """"Show me the TED talk about surveillance" → find it in the knowledge
    base and pull it up on the dashboard (resolution + display live in
    dashboard_display.show_query). "Clear the screen" takes it back down. Fires
    only on an explicit display verb plus a content noun or an about/on topic,
    so "show me my schedule" and "show me the weather" keep their own paths.
    """
    low = (user_message or "").lower()
    if _SHOW_HIDE_RE.search(low):
        try:
            from puffpai import dashboard_display as dd
            dd.clear_display(source="voice")
            return "Cleared the dashboard."
        except Exception as exc:
            logger.debug("show fastpath clear failed: %s", exc)
            return None
    if not _SHOW_VERB_RE.search(low):
        return None
    try:
        from puffpai import dashboard_display as dd
    except Exception:
        return None
    # Fire on an explicit content noun / about-topic, OR when the source
    # classifier recognizes a vault-type (birth certificate…) or a personal
    # document request — so "show me a birth certificate" and "show me
    # grandma's recipe" route here while "show me my schedule/weather/dashboard"
    # keep their own paths.
    if not (_SHOW_CONTENT_RE.search(low)
            or re.search(r"\b(about|on|covering|regarding)\b", low)
            or dd.classify_source(user_message) in ("vault", "documents")
            or dd.resolve_app_page(user_message)):   # "pull up my calendar" → app page
        return None
    try:
        item = dd.show_query(user_message, source="voice")
    except Exception as exc:
        logger.debug("show fastpath failed: %s", exc)
        return None
    if not item:
        return None
    if item.get("deferred"):          # recognized (vault/document) but not rendered here
        if item.get("deferred") == "vault_challenge":
            # The challenge turn names a sensitive doc TYPE — keep it out of the
            # persisted transcript (no PIN here, but no durable record either).
            _mark_vault_turn_private()
        return item["message"]
    return f"Pulling up \"{item['title']}\" on your dashboard."


# ── Zone-1 vault DOCUMENT display (challenge-response → unlock → serve) ──────
#
# MFA policy (Piece D.2) — DECIDED Option A: voice vault-display uses
# vault.authenticate(pin) (PIN-only) for ALL doc types, consistent with the
# shipped vault_unlock_and_get. Flipping to Option B (require full MFA for the
# STRICT subset when TOTP is enrolled) is a one-line change: set the flag True.
VOICE_DISPLAY_STRICT_REQUIRES_MFA = False

# An ADDITIONAL voice-layer throttle on top of vault.authenticate's own 5/300s
# lockout (the assistant_tools _vault_rl_* limiter is a closure and not importable,
# so this is a parallel module-level limiter with identical semantics).
_vault_display_rl = {"attempts": deque(), "lock_until": 0.0}
_vault_display_rl_lock = threading.Lock()
_VAULT_DISPLAY_RL_WINDOW = 300.0
_VAULT_DISPLAY_RL_MAX = 5
_VAULT_DISPLAY_RL_LOCKOUT = 300.0

# Reconstructed T-2 display titles: "<Type> — <Owner>", never the free-text label.
_VAULT_DOC_TYPE_DISPLAY = {
    "ssn": "Social Security card", "passport": "Passport",
    "drivers_license": "Driver's license", "state_id": "State ID",
    "bank_account": "Bank account", "other_vault_doc": "Document",
    "medical_record": "Medical record", "prescription": "Prescription",
    "immunization_record": "Immunization record",
    "insurance_card": "Insurance card", "tax_return": "Tax return",
    "bank_statement": "Bank statement",
}


def _vault_display_rl_check():
    with _vault_display_rl_lock:
        now = time.monotonic()
        if now < _vault_display_rl["lock_until"]:
            return False, int(_vault_display_rl["lock_until"] - now)
        q = _vault_display_rl["attempts"]
        while q and (now - q[0]) > _VAULT_DISPLAY_RL_WINDOW:
            q.popleft()
        if len(q) >= _VAULT_DISPLAY_RL_MAX:
            _vault_display_rl["lock_until"] = now + _VAULT_DISPLAY_RL_LOCKOUT
            q.clear()
            return False, int(_VAULT_DISPLAY_RL_LOCKOUT)
        return True, 0


def _vault_display_rl_note():
    with _vault_display_rl_lock:
        _vault_display_rl["attempts"].append(time.monotonic())


def _vault_display_title(doc_type: str, owner) -> str:
    t = _VAULT_DOC_TYPE_DISPLAY.get(doc_type, "Document")
    if owner and owner != "self":
        return f"{t} — {str(owner).title()}"
    return t


def _vault_display_unlock_find_serve(query_phrase: str, pin: str) -> str:
    """Piece D — Zone-1 post-PIN: authenticate, find the tagged doc, decrypt,
    mint an ephemeral view, set the ephemeral overlay, and log out IMMEDIATELY.

    Returns a MINIMAL spoken confirmation (no type/owner/label). Content-free
    audit throughout; NEVER logs the pin, utterance, bytes, or label.
    """
    from puffpai import dashboard_display as dd
    from puffpai.security import vault_view
    try:
        from puffpai.security.vault import (
            VaultError, AuthenticationError,
            STRICT_DOC_TYPES, HEALTH_DOC_TYPES, VAULT_DOC_MIME_ALLOWLIST)
    except Exception:
        return "Your vault module can't be loaded, so access is denied."

    # 1. Voice-layer throttle (in addition to vault.authenticate's own lockout).
    allowed, wait = _vault_display_rl_check()
    if not allowed:
        return (f"Too many attempts. For safety I've paused vault access for "
                f"about {max(1, wait // 60)} more minute(s). Try again later.")

    vault = _get_vault()
    if vault is None:
        return "Your vault is unavailable right now, so I can't pull that up."
    if not getattr(vault, "is_initialized", False):
        return "Your vault isn't set up yet, so there's nothing to pull up."

    # 2. Normalize the query → (owner, doc_type) BEFORE authenticating (pure
    #    string parsing, no vault access) so the MFA policy can be scoped by
    #    doc-type without any extra vault round-trip.
    owner_token, doc_type = dd.normalize_vault_query(query_phrase)
    if not doc_type:
        return "I couldn't tell which kind of document you meant."
    # Option A (shipped): PIN-only for ALL types. Flip the flag for Option B:
    # the STRICT/HEALTH subset then requires full MFA (authenticate_mfa, which
    # enforces TOTP only when enrolled). Baseline types stay PIN-only either way.
    requires_mfa = (VOICE_DISPLAY_STRICT_REQUIRES_MFA
                    and (doc_type in STRICT_DOC_TYPES
                         or doc_type in HEALTH_DOC_TYPES))

    # 3. Note the attempt, then authenticate.
    _vault_display_rl_note()
    session = None
    try:
        try:
            if requires_mfa:
                session = vault.authenticate_mfa(pin)
            else:
                session = vault.authenticate(pin)
        except (AuthenticationError, VaultError):
            try:
                vault._audit.log(action="vault_display_auth", user="voice",
                                 result="failed", details="")
            except Exception:
                pass
            return "That PIN didn't match — access denied."

        sid = session.session_id
        # 4. Find the doc — exact match only, never a substring cross.
        try:
            candidates = vault.find_documents(owner_token, doc_type, sid)
        except (VaultError, AuthenticationError):
            return "I unlocked the vault but couldn't read your documents."
        if not candidates:
            try:
                vault._audit.log(action="vault_display_not_found", user="voice",
                                 result="not_found", details="")
            except Exception:
                pass
            return "Your PIN worked, but I couldn't find that document."
        if len(candidates) > 1:
            if not owner_token:
                owners = sorted({c.get("owner") for c in candidates
                                 if c.get("owner")})
                if len(owners) > 1:
                    return ("You have that document for more than one person. "
                            "Whose did you want?")
            return ("You have more than one document like that. Can you say a "
                    "bit more about which one?")

        doc = candidates[0]
        doc_id = doc.get("doc_id")
        # 4. Decrypt → validate mime → mint ephemeral view → set overlay.
        try:
            got = vault.get_document_bytes(doc_id, sid)
        except (VaultError, AuthenticationError):
            return "I unlocked the vault but couldn't open that document."
        if not got:
            return "Your PIN worked, but I couldn't open that document."
        data, mime, _meta = got
        if mime not in VAULT_DOC_MIME_ALLOWLIST:
            return "That document is in a format I can't safely display."

        strict = doc_type in STRICT_DOC_TYPES or doc_type in HEALTH_DOC_TYPES
        ttl = 45 if strict else 90
        title = _vault_display_title(doc_type, doc.get("owner"))
        # The view TOKEN gets a small grace beyond the on-screen TTL: the kiosk's
        # client hard-timer starts only when it next POLLS /dashboard/display (up
        # to one ~2.5s poll after mint), so the token must outlive the on-screen
        # window or a re-render at the very end would 404. The overlay still
        # expires at `ttl`, and the frontend clears itself at `ttl`.
        token = vault_view.mint(data, mime, title, doc_id, ttl + 8)
        if token is vault_view.BUSY:
            return "A protected document is being viewed right now."
        try:
            dd.set_ephemeral_display(kind="vault", url=f"/vault/view/{token}",
                                     title=title, ttl=ttl, secure=True,
                                     strict=strict)
        except Exception:
            vault_view.clear(token)
            return "I couldn't pull that up on your screen just now."
        try:
            vault._audit.log(action="vault_display_serve", user="voice",
                             result="success",
                             details=f"doc={str(doc_id)[:8]} tok={str(token)[:6]}")
        except Exception:
            pass
        return ("Okay — pulling that up on your screen now. It'll clear itself "
                "in a moment.")
    finally:
        # 5. Log out IMMEDIATELY — never hold the 15-min session for a display.
        if session is not None:
            try:
                vault.logout(session.session_id)
            except Exception:
                pass


#: "Open the vault". Left to the agent graph, the turn takes ~16 seconds
#: to say the one thing that is always true: the vault needs the PIN.
#: There is nothing to think about, so nothing thinks about it.
#:
#: This rule only SPEAKS. It holds no PIN, opens nothing, and touches no
#: gate: the vault is unlocked by entering the PIN on the dashboard, and
#: the PIN-capture fastpath (_try_vault_pin_followup) is unchanged.
_VAULT_OPEN_RE = re.compile(
    r"(?i)\b(?:open|unlock|get\s+in(?:to)?|let\s+me\s+in(?:to)?|show\s+me|access|pull\s+up|take\s+me\s+(?:in)?to)\b[^.?!]{0,24}\b(?:the\s+|my\s+|our\s+)?vaults?\b")
#: A question ABOUT the vault is somebody else's: "is the vault locked"
#: is vault.status, and "what is in my vault" is vault.secrets (which
#: names items and therefore stays where it is).
_VAULT_OPEN_EXCLUDE_RE = re.compile(
    r"(?i)\b(?:what|which|how|why|when|who|is|are|was|does|do|did|"
    r"status|locked|unlocked|sealed|list|count|inside|contents)\b")

#: The one sentence. Says what is true and what to do about it.
VAULT_PIN_REQUIRED = ("The vault stays locked until you enter your PIN "
                      "on the dashboard.")


def _try_vault_open(user_message: str) -> "str | None":
    """"Open the vault" -> the PIN line, deterministically.

    Declines every question about the vault, so the lock-state read and
    the contents read keep their own capabilities. Changes no gate: the
    only thing this rule can do is say that a PIN is required.
    """
    text = (user_message or "").strip()
    if not text or len(text) > 120:
        return None
    if _VAULT_OPEN_EXCLUDE_RE.search(text):
        return None
    if not _VAULT_OPEN_RE.search(text):
        return None
    return VAULT_PIN_REQUIRED


def _try_vault_pin_followup(user_message: str) -> str | None:
    """Capture the PIN reply to a pending vault-display challenge (Piece A).

    Gated STRICTLY on a live pending slot. NEVER logs the PIN/utterance.
      * no pending slot  → return None immediately (a bare PIN is a silent
        no-op, never a logged vault event).
      * cancel/nevermind → clear pending + confirm.
      * PIN-shaped       → take the pending phrase and hand (phrase, pin) to
        the Zone-1 unlock→find→serve path; clear pending.
      * any other reply  → clear pending, return None (fall through) so a
        later-spoken number can't bind to a stale request.
    """
    from puffpai import dashboard_display as dd
    if not dd.pending_vault_active():
        return None
    msg = (user_message or "").strip()
    low = msg.lower()
    if ("cancel" in low or "never mind" in low or "nevermind" in low
            or low in ("no", "stop", "forget it", "no thanks")):
        dd.clear_pending_vault()
        _mark_vault_turn_private()
        return "Okay, I won't pull that up."
    if _looks_like_pin(msg):
        phrase = dd.take_pending_vault()
        _mark_vault_turn_private()
        if not phrase:
            return None
        return _vault_display_unlock_find_serve(phrase, msg)
    # An intervening non-PIN, non-cancel utterance: drop the pending request so
    # a number spoken later can't bind to it. This turn persists normally.
    dd.clear_pending_vault()
    return None


# ── Media playback fastpath ─────────────────────────────────────────────────
# "play the radio station KEXP", "play my playlist on
# jellyfin", "play <artist> on spotify" — dispatch straight to the proven
# playback backends instead of hoping the 100-tool picker LLM selects the right
# media tool (it kept declining — the owner got "I can't start a stream"). Runs
# inside _try_instant_answer, so BOTH voice and the Talk page get it. Only fires
# on an explicit service/radio; bare "play X" falls through to the agent.
_MEDIA_VERB_RE = re.compile(r'\b(?:play|put on|start playing|listen to)\b',
                            re.IGNORECASE)
# non-media uses of "play"
_MEDIA_BLOCK_RE = re.compile(
    r'\b(game|games|trivia|chess|checkers|solitaire|role[\s-]?play|playground|'
    r'foul play|play ?date|play along|play dead|play the fool)\b',
    re.IGNORECASE)
# "how do I play / learn to play the guitar" is a how-to, not a media command
_MEDIA_HOWTO_RE = re.compile(r'\b(how|learn|teach|practice|practise)\b',
                             re.IGNORECASE)
_MEDIA_STOP = {"please", "for", "me", "some", "the", "a", "an", "my", "on",
               "to", "of", "song", "songs", "music", "track", "tracks", "tune",
               "tunes", "playing", "internet"}


def _collapse_spelled(q: str) -> str:
    """STT spells out call letters: "K-E-X-P" / "K E X P" / "K.E.X.P." -> "KEXP"."""
    return re.sub(r'\b[A-Za-z](?:[\s.\-]+[A-Za-z]\b)+\.?',
                  lambda m: re.sub(r'[\s.\-]+', '', m.group(0)).rstrip('.'), q or '')


def _clean_media_query(q: str) -> str:
    q = _collapse_spelled(q or '')
    # Keep a decimal point that sits BETWEEN digits, so a dial survives:
    # otherwise "90.3 fm" comes out "90 3 fm" and can never match a station.
    q = re.sub(r"(?<![0-9])[^\w\s'-]|[^\w\s'-](?![0-9])", ' ', q)
    return " ".join(w for w in q.split() if w.lower() not in _MEDIA_STOP).strip()


# Vibe / genre requests ("play some lo-fi relaxing music") name neither a
# station nor a title, so the name search and the library title search both come
# back empty. radio-browser indexes genre tags on a separate axis, map the words
# onto those tags and let the station catalog answer.
_GENRE_TAGS = {
    # The catalog uses "lofi" for BOTH the music genre and low-bitrate relays,
    # but reserves the hyphenated "lo-fi" for the genre — so try that first.
    "lo-fi": ("lo-fi", "lofi"), "lofi": ("lo-fi", "lofi"),
    "low fi": ("lo-fi", "lofi"), "low-fi": ("lo-fi", "lofi"),
    "ambient": "ambient", "jazz": "jazz", "blues": "blues",
    "classical": "classical", "rock": "rock", "pop": "pop",
    "country": "country", "folk": "folk", "bluegrass": "bluegrass",
    "hip hop": "hiphop", "hip-hop": "hiphop", "hiphop": "hiphop",
    "rap": "rap", "reggae": "reggae", "soul": "soul", "funk": "funk",
    "disco": "disco", "electronic": "electronic", "techno": "techno",
    "house": "house", "trance": "trance", "edm": "edm", "metal": "metal",
    "punk": "punk", "indie": "indie", "latin": "latin", "salsa": "salsa",
    "gospel": "gospel", "oldies": "oldies", "instrumental": "instrumental",
    "piano": "piano", "acoustic": "acoustic", "r&b": "rnb", "rnb": "rnb",
    "christmas": "christmas", "holiday": "christmas", "dance": "dance",
    "60s": "60s", "70s": "70s", "80s": "80s", "90s": "90s",
}
#: Moods are MODIFIERS, not the request. "lo-fi relaxing music" is a lo-fi
#: request that happens to say relaxing — ranking by phrase length alone let
#: "relaxing" win and tuned Classic Vinyl HD instead of a lo-fi station. Tried
#: only when no genre word is present ("play something relaxing").
_MOOD_TAGS = {
    "chillout": "chillout", "chill out": "chillout", "chill": "chillout",
    "chilled": "chillout", "relaxing": "relax", "relaxation": "relax",
    "relaxed": "relax", "relax": "relax", "calm": "relax", "mellow": "relax",
    "soothing": "relax", "focus": "focus", "study": "study",
    "sleep": "sleep", "workout": "workout",
}
#: The CLOSED tag vocabulary handed to the remainder gate
#: (`puffpai.radio_cues.plan_station_query`). It is unioned with that module's
#: own GENRE_WORDS, never substituted for it, so adding a genre here can only
#: widen what plays — it can never widen what free text may egress.
_STATION_TAG_WORDS = tuple(_GENRE_TAGS) + tuple(_MOOD_TAGS)

#: Said when the remainder gate cannot recognise what was asked for. Repeated
#: here (rather than imported) so the fail-closed path still has a sentence to
#: speak when `puffpai.radio_cues` itself will not import.
_STATION_QUERY_HELP = ("Which station? Say a call sign like NPR or KEXP, "
                       "a genre like jazz, or a dial like 90.3 FM.")

#: A dial spoken as the whole request — "play 90.3 fm", "tune to 90.3". A
#: number is not household text, so it is a radio cue in its own right. The
#: decimal point (or an explicit band word) is required: a bare "1999" is a
#: song, not a frequency.
_DIAL_RE = re.compile(
    r"\b(\d{2,3}[.,]\d\s*(?:fm|am)?|\d{2,4}\s*(?:fm|am))\b", re.IGNORECASE)

_MEDIA_MUSIC_NOUN_RE = re.compile(
    r"\b(music|tunes?|songs?|beats|jams)\b", re.IGNORECASE)
# Visual media belongs to the library, never to the radio catalog.
_MEDIA_VISUAL_RE = re.compile(
    r"\b(movies?|films?|shows?|episodes?|series|trailers?|tv|video)\b",
    re.IGNORECASE)


def _vibe_tags(text: str) -> list:
    """Station tags implied by the user's words: genres first, then moods.

    Within each group the longest phrase wins, so "hip hop" beats a bare
    substring. Across groups the genre always wins, because in "some lo-fi
    relaxing music" the genre is the request and the mood is a modifier.
    """
    low = (text or "").lower()

    def _matches(table):
        hits = [(len(phrase), tag) for phrase, tag in table.items()
                if re.search(r"\b" + re.escape(phrase) + r"\b", low)]
        out = []
        for _, tag in sorted(hits, key=lambda h: -h[0]):
            # A phrase may offer several candidate tags, best-curated first.
            out.extend((tag,) if isinstance(tag, str) else tag)
        return out

    out = []
    for tag in _matches(_GENRE_TAGS) + _matches(_MOOD_TAGS):
        if tag not in out:
            out.append(tag)
    return out


#: Below this the stream is a talk/news relay or a bad transcode, not music.
_STATION_MUSIC_BITRATE = 64


def _best_station(stations):
    """The most listenable of the catalog's top hits.

    Results come back ordered by votes, which on a genre tag can put a 32 kbps
    news relay ahead of every real music station (live: "play some lo-fi
    relaxing music" tuned "france info (lofi)"). Among the handful returned,
    prefer a music-grade bitrate; fall back to the catalog's own order when
    none of them clears the bar.
    """
    if not stations:
        return None
    listenable = [s for s in stations
                  if (s.get("bitrate") or 0) >= _STATION_MUSIC_BITRATE]
    if listenable:
        return max(listenable, key=lambda s: s.get("bitrate") or 0)
    return stations[0]


def _media_log(detail: str) -> None:
    """One dispatch line per media turn (body in media_hub). Never raises."""
    try:
        from puffpai.media_hub import media_log
        media_log(detail)
    except Exception:                                     # pragma: no cover
        pass


def _radio_log_what(query: str, cls=None, tags=()) -> str:
    """What a `[Media] play radio` line was asked for.

    A genre/country/language request carries no name query, and logging it as
    ``query=''`` hid the one thing worth reading (live: a jazz ask that tuned a
    rock station left no trace of "jazz"). The plan is closed-vocabulary — a
    catalog tag, a country, a language — so it is as safe to log as the query.
    """
    bits = [f"query={query!r}"] if query else []
    cls = str(cls or "")
    if cls and cls != "any" and not cls.startswith("name:"):
        for part in cls.split("|"):
            key, _, val = part.partition("=")
            if key and val:
                bits.append(f"{key}={val!r}")
    elif not query and tags:
        bits.append(f"tag={str(list(tags)[0])!r}")
    return " ".join(bits) or "query=''"


def _station_candidates(query: str, tags=()):
    """The ranked SHORTLIST for a request.

    Returns ``(candidates, query_class)``. The class labels "the same kind of
    ask" so the variety rule can avoid what it played last time; see
    ``media_hub.query_class``.

    Search order is unchanged in spirit (a named station still wins) but it now
    runs on four axes at once — name, genre, country, language — because "french
    jazz" and "news from japan" were losing half the request to a single-axis
    query. The supplied ``tags`` remain the closed-vocabulary genre fallback the
    privacy gate depends on, so a turn that may not name-search still resolves.
    """
    try:
        from puffpai import media_hub
        stations, plan = ([], {})
        if query:
            stations, plan = media_hub.search_for_text(query, limit=12)
        if not stations:
            for tag in (tags or ()):
                # Fetch wide, then rank for genre relevance: the top-voted
                # rows of a tag search are where the tag-stuffed stations live.
                stations = media_hub.search_stations_by_tag(
                    tag, limit=media_hub.RADIO_TAG_FETCH_LIMIT)
                if stations:
                    plan = {"tag": tag}
                    break
        ranked = media_hub.rank_stations(stations, limit=8,
                                         tag=(plan or {}).get("tag"))
        return ranked, media_hub.query_class(plan)
    except Exception as exc:
        logger.warning("station resolve failed: %s", exc)
        from puffpai.media_hub import media_log
        media_log(f"play radio {_radio_log_what(query, tags=tags)} "
                  f"-> FAILED: {exc}")
        return [], "any"


def _resolve_station(query: str, tags=()):
    """The single best station for *query* (compatibility wrapper).

    Kept because several callers want one row and nothing more; it is now the
    head of the ranked shortlist rather than an independent search, so the two
    can never disagree about what "best" means.
    """
    candidates, _cls = _station_candidates(query, tags)
    return candidates[0] if candidates else None


#: How many candidates a single play attempt will burn before giving up. Three:
#: each failed stream costs ~3 s of liveness probing, and a fourth would push a
#: voice turn past the point where the household assumes nothing happened.
_RADIO_PLAY_ATTEMPTS = 3


def _radio_play_serverside(query: str, tags=(), station=None, candidates=None,
                           query_cls=None):
    """Play radio on the APPLIANCE (server-side mpv), truthfully.

    Two behaviours here guard against observed failure modes:

    * ``radio_player.play`` verifies mpv is still alive rather than reporting
      success the moment ``docker run`` returns (a dead stream would otherwise
      produce "Playing X on the speakers" and silence), so a failure is a real
      failure — and a real failure here moves to the NEXT candidate instead of
      dropping the whole request on the browser player.
    * the winner is picked with variety (``media_hub.pick_varied``) for a genre
      or country ask, and without it for a named station.

    Returns the spoken message, or None to fall back to the browser player.
    """
    try:
        from puffpai import radio_player
        from puffpai import media_hub

        cls = query_cls
        if station is not None:
            shortlist = [station]
            cls = cls or media_hub.query_class({"name": station.get("name")})
        else:
            shortlist = list(candidates or [])
            if not shortlist:
                shortlist, found_cls = _station_candidates(query, tags)
                cls = cls or found_cls
            cls = cls or "any"
            first = media_hub.pick_varied(cls, shortlist)
            if first is not None:
                shortlist = [first] + [s for s in shortlist if s is not first]

        what = _radio_log_what(query, cls, tags)
        if not shortlist:
            media_hub.media_log(f"play radio {what} -> FAILED: "
                                f"no station matched")
            return None

        if station is None:
            # Playing FROM the stored shortlist must never rewrite it. Entering
            # here with one already-chosen row (every `_play_station_row` call)
            # would store `[that row]`, so "play the second one" would shrink the
            # list to one and "play the third one" would answer "I only offered
            # 1 station". Only a fresh search or resolve
            # gets to say what the shortlist is.
            try:
                media_hub.store_candidates(cls or "any", shortlist)
            except Exception:
                pass

        reasons = []
        door_notes = []
        for st in shortlist[:_RADIO_PLAY_ATTEMPTS]:
            # A stored row normally carries its stream URL, so playing it is
            # not a catalog call and no door is involved. A TuneIn row that
            # needs a FRESH resolve does need TuneIn's door, and with that
            # shut the household hears which switch stopped it rather than
            # silence.
            url, door_note = media_hub.station_stream_url(st)
            if not url:
                if door_note:
                    door_notes.append(door_note)
                continue
            ok, detail = radio_player.play(url)
            if not ok:
                reasons.append(f"{st.get('name')}: {detail}")
                media_hub.media_log(
                    f"play radio {what} -> FAILED: "
                    f"{st.get('name')!r} {detail}")
                continue
            try:  # best-effort: keep the dashboard now-playing widget in sync
                media_hub._get_app_data().mediahub_report_radio(
                    "playing", st, source="appliance")
            except Exception:
                pass
            try:
                media_hub.note_played(cls or "any", st)
            except Exception:
                pass
            media_hub.media_log(
                f"play radio {what} -> playing {st.get('name')!r}")
            return f"Playing {st.get('name') or query} on the speakers."

        if reasons:
            logger.warning("server-side radio failed on %d candidates: %s",
                           len(reasons), "; ".join(reasons)[:300])
        if door_notes and not reasons:
            # Nothing was even attempted, and a shut door is why. Returning
            # None here would hand the turn to the browser player, which would
            # find the same missing URL and say "no station matched" — a
            # true-sounding sentence about the wrong thing.
            return door_notes[0]
        return None
    except Exception as exc:
        logger.warning("server-side radio error: %s", exc)
        try:
            from puffpai.media_hub import media_log
            media_log(f"play radio {_radio_log_what(query, tags=tags)} "
                      f"-> FAILED: {type(exc).__name__}: {exc}")
        except Exception:
            pass
        return None


def _jellyfin_play_playlist_serverside(name: str, shuffle: bool = False):
    """Play a Jellyfin playlist on the APPLIANCE speakers (server-side mpv, the
    same player as radio) so it works with any page showing. The Jellyfin token
    goes in an HTTP header, not the URLs. Returns a spoken message, or None to
    fall back to casting to an open Jellyfin session."""
    try:
        import random
        from puffpai.media_bridge import get_media_bridge
        from puffpai import radio_player
        b = get_media_bridge()
        pl = b.resolve_playlist(name)
        tracks = b.playlist_tracks(pl.item_id, limit=200)
        if not tracks:
            return None
        if shuffle:
            tracks = tracks[:]
            random.shuffle(tracks)
        base = b._jellyfin_url
        urls = [f"{base}/Audio/{t.item_id}/stream?static=true" for t in tracks]
        ok, detail = radio_player.play_urls(
            urls, header=f"X-Emby-Token: {b._jellyfin_api_key}")
        if not ok:
            logger.warning("server-side jellyfin failed: %s", detail)
            return None
        mode = ", shuffled" if shuffle else ""
        return (f"Playing your {pl.title} playlist on the speakers — "
                f"{len(urls)} tracks{mode}.")
    except Exception as exc:
        logger.warning("server-side jellyfin error: %s", exc)
        return None


def _radio_play_for_query(q: str, low: str = "") -> str | None:
    """Resolve *q* against the station catalog and start it on the appliance.

    Extracted verbatim from the radio branch of ``_try_media_play`` so the
    TuneIn-named phrasings ("tune in to X") reach the SAME player and
    the same fallbacks, rather than a second, drifting copy.

    This is the ONE choke point every radio phrasing
    passes through, so the remainder gate lives here. `has_radio_cue` decides
    whether the utterance asked for radio; `plan_station_query` decides whether
    what is LEFT after the cue words may be searched at all. A household noun
    next to a real cue ("put on grandma's radio show") satisfies the first
    and would still egress; it does not satisfy the second.
    """
    from puffpai.media_hub import tool_radio_play, search_stations
    tags = _vibe_tags(low)
    try:
        from puffpai.radio_cues import plan_station_query, STATION_QUERY_HELP
        kind, value = plan_station_query(q, tag_words=_STATION_TAG_WORDS)
    except Exception as exc:
        # Fail CLOSED: if the gate cannot run, nothing leaves the house.
        logger.warning("station query gate unavailable, declining: %s", exc)
        return _STATION_QUERY_HELP
    if kind == "reject" or (kind == "empty" and not tags):
        return STATION_QUERY_HELP
    if kind in ("tag", "empty"):
        # Genre only. Use the TAG axis with the closed-vocabulary word — the
        # free text never goes to the name search, so nothing the household
        # said can ride along with the request.
        tags = tags or list(value)
        return (_radio_play_serverside("", tags=tags)
                or tool_radio_play(tags[0] if tags else ""))
    # Every token of `value` came from the local allowlist (call sign, dial or
    # the household's own last-played station), so it is safe to name-search.
    q = value
    # radio-browser matches station NAMES strictly; if a multi-word query
    # (STT often appends a city — "kexp seattle") finds nothing, fall back
    # to the most distinctive single token before we queue anything.
    if q and " " in q and not search_stations(q, limit=1):
        head = q.split()[0]
        if search_stations(head, limit=1):
            q = head
    # Play on the appliance itself so it works with any page showing;
    # fall back to the browser player only if server-side can't.
    served = _radio_play_serverside(q, tags=_vibe_tags(low))
    return served if served else tool_radio_play(q)


# ── Radio discovery, variety and favorites ──────────────────────────────────
#
# Three separate needs, and this block is their deterministic half:
#
#   FIND      "what jazz stations are there" needs a reader, or it goes to
#             RAG and gets prose about equipment the house does not own.
#   VARY      a resolver returning max(bitrate) over the top hits is a pure
#             function of the query, so a repeat could never land anywhere new.
#   KEEP      favorites need a backend copy. The dashboard's hearts live in
#             browser localStorage (`puffpai_radio_favs`) and are invisible to
#             voice, so "play my favorite station" would have nothing to read.
#
# Every rule here is cue-gated the same way the rest of the radio surface is:
# nothing reaches the catalog unless the utterance actually asked for radio.

#: "play something else" / "a different station" / "next station".
_RADIO_NEXT_RE = re.compile(
    r'^\s*(?:please\s+|hey\s+puff\s*,?\s*|puff\s*,?\s*|can you\s+|could you\s+)*'
    r'(?:play|put\s+on|give\s+me|find|try)?\s*'
    r'(?:me\s+)?(?:something|anything)\s+(?:else|different|new)\b'
    r'|^\s*(?:play\s+|put\s+on\s+)?(?:a\s+|the\s+)?(?:different|another|next|'
    r'other)\s+(?:one|station|radio\s+station)\b'
    r'|^\s*(?:play\s+)?another\s+one\s+like\s+this\b'
    r'|^\s*next\s+station\b',
    re.IGNORECASE)

#: "play the second one" / "play number three" / "the first one".
_RADIO_NTH_RE = re.compile(
    r'\b(?:play|start|put\s+on|tune)\s+(?:me\s+)?(?:the\s+)?'
    r'(?:(first|second|third|fourth|fifth|sixth|1st|2nd|3rd|4th|5th|6th)\s+'
    r'(?:one|station)?|(?:number|no\.?|#)\s*(\d))\b',
    re.IGNORECASE)

_ORDINALS = {"first": 1, "1st": 1, "second": 2, "2nd": 2, "third": 3, "3rd": 3,
             "fourth": 4, "4th": 4, "fifth": 5, "5th": 5, "sixth": 6, "6th": 6}

#: Favorites. Each shape names "favorite"/"favourite" explicitly (or "save this
#: station"), so nothing here can capture a Jellyfin favorite-TRACK phrasing.
_FAV_SAVE_RE = re.compile(
    r'\b(?:save|favou?rite|bookmark|remember|add)\b[^.?!]*?\b'
    r'(?:this|that|the\s+current|current)\s+(?:radio\s+)?station\b'
    r'|\b(?:save|add)\b[^.?!]*?\bstation\b[^.?!]*?\bfavou?rites?\b',
    re.IGNORECASE)
_FAV_REMOVE_RE = re.compile(
    r'\b(?:remove|delete|drop|take|unfavou?rite|un-?favou?rite)\b\s*'
    r'(?:the\s+)?(.+?)\s*(?:station\s*)?'
    r'(?:from|out\s+of|off)?\s*(?:my\s+)?favou?rites?\b',
    re.IGNORECASE)
_FAV_LIST_RE = re.compile(
    r'\b(?:what|which|list|show|name)\b[^.?!]*\bfavou?rite\s+(?:radio\s+)?'
    r'stations?\b',
    re.IGNORECASE)
_FAV_PLAY_RE = re.compile(
    r'\b(?:play|put\s+on|start|tune)\b[^.?!]*\bfavou?rite'
    r'(?:s\b|\s+(?:radio\s+)?stations?\b|\s*$)',
    re.IGNORECASE)

#: "what jazz stations are there" / "find me radio stations from Ireland" /
#: "what stations can you get". A QUESTION about the catalog, not a play.
#:
#: It must have a SEARCH shape. Accepting "what ... radio" would send
#: "what's a radio" to the station catalog as a query; a question ABOUT radio ("what is radio", "how does radio work",
#: "which radio should I buy") is a knowledge question and belongs to RAG.
_RADIO_FIND_RE = re.compile(
    r'^(?:\s*(?:please|hey\s+puff|puff)\s*,?\s*)*'
    r'(?:'
    #  a catalog question in the plural: "what jazz stations are there"
    r'(?:what|which|how\s+many)\b[^.?!]*\bstations\b'
    #  a look-in-the-catalog verb, singular allowed: "find me a jazz station"
    r'|(?:find|search|list|show|name)\b[^.?!]*\b(?:radio\s+)?stations?\b'
    #  "stations from Ireland" / "a station that plays jazz"
    r'|\bstations?\s+(?:from|in|for|like|that\s+plays?)\b'
    r'|\bradio\s+stations\b'
    r')',
    re.IGNORECASE)

#: "play the radio" / "put on some radio" — a radio ask with no station in it.
_RADIO_BARE_RE = re.compile(
    r'^\s*(?:please\s+|hey\s+puff\s*,?\s*|puff\s*,?\s*|can you\s+|could you\s+)*'
    r'(?:play|put\s+on|start|turn\s+on)\s+(?:me\s+)?(?:the\s+|some\s+|a\s+)?'
    r'radio\s*$',
    re.IGNORECASE)


def _station_line(st) -> str:
    bits = [str(st.get("name") or "a station")]
    detail = [d for d in (str(st.get("country") or "").strip(),
                          f"{st.get('bitrate')}k" if st.get("bitrate") else "")
              if d]
    if detail:
        bits.append("(" + ", ".join(detail) + ")")
    return " ".join(bits)


def _radio_is_current() -> bool:
    """True when appliance radio is the source that is (or just was) playing.

    "play something else" is only OUR turn while radio owns the speakers;
    otherwise it belongs to whatever is actually playing and we must fall
    through rather than hijack it.
    """
    try:
        from puffpai.media_hub import _get_app_data, _age_seconds
        doc = _get_app_data().get_data("mediahub") or {}
        row = doc.get("radio")
        if not isinstance(row, dict) or row.get("source") != "appliance":
            return False
        if row.get("status") in ("playing", "connecting"):
            return True
        age = _age_seconds(row.get("updated_at"))
        return age is not None and age <= 600
    except Exception:
        return False


def _radio_current_name() -> str:
    """The station the appliance radio is playing right now, or ""."""
    try:
        from puffpai.media_hub import _get_app_data
        doc = _get_app_data().get_data("mediahub") or {}
        row = doc.get("radio")
        station = (row or {}).get("station") if isinstance(row, dict) else None
        return str((station or {}).get("name") or "").strip()
    except Exception:
        return ""


def _play_station_row(st, cls: str) -> str:
    """Start one already-chosen station and say honestly where it is playing."""
    from puffpai.media_hub import tool_radio_play
    served = _radio_play_serverside("", station=st, query_cls=cls)
    if served:
        return served
    queued = tool_radio_play(st.get("name") or "")
    _media_log(f"play radio {st.get('name')!r} -> FAILED: appliance player; "
               f"queued on the dashboard instead")
    return queued


def _try_radio_extras(user_message: str) -> str | None:
    """Discovery, variety and favorites for internet radio. None = not mine."""
    text = (user_message or "").strip().rstrip(".!?").strip()
    if not text or _MEDIA_BLOCK_RE.search(text) or _MEDIA_HOWTO_RE.search(text):
        return None
    # Another source owns the turn the moment it is named — "play my road trip
    # playlist" is Jellyfin's, always.
    if re.search(r'\b(playlist|jellyfin|jellyfish|spotify|podcast|'
                 r'audiobook|book|trivia)\b', text, re.IGNORECASE):
        return None
    try:
        from puffpai import media_hub
        from puffpai.radio_cues import has_radio_cue
    except Exception as exc:                              # pragma: no cover
        logger.warning("radio extras unavailable: %s", exc)
        return None

    # ── favorites ────────────────────────────────────────────────────────────
    if _FAV_LIST_RE.search(text):
        favs = media_hub.list_favorites()
        _media_log(f"radio favorites list -> {len(favs)}")
        if not favs:
            return ("You haven't saved any favorite radio stations yet. While "
                    "one is playing, say \"save this station\".")
        return ("Your favorite stations: "
                + ", ".join(str(f.get("name")) for f in favs) + ".")

    if _FAV_SAVE_RE.search(text):
        try:
            doc = media_hub._get_app_data().get_data("mediahub") or {}
            row = doc.get("radio") if isinstance(doc, dict) else None
            station = (row or {}).get("station") if isinstance(row, dict) else None
        except Exception:
            station = None
        if not station:
            _media_log("radio favorite save -> FAILED: nothing playing")
            return ("Nothing is playing on the radio right now, so there's no "
                    "station for me to save.")
        ok, name = media_hub.add_favorite(station)
        _media_log(f"radio favorite save -> {'ok' if ok else 'FAILED'} {name!r}")
        return (f"Saved {name} to your favorite stations." if ok else
                "I couldn't save that station — it has no playable stream on file.")

    remove = _FAV_REMOVE_RE.search(text)
    if remove and "favo" in text.lower():
        gone = media_hub.remove_favorite(remove.group(1))
        _media_log(f"radio favorite remove {remove.group(1)!r} -> {gone!r}")
        if not gone:
            return (f"I don't have a favorite station matching "
                    f"'{remove.group(1).strip()}'.")
        return f"Removed {gone} from your favorite stations."

    if _FAV_PLAY_RE.search(text):
        favs = media_hub.list_favorites()
        if not favs:
            _media_log("play radio favorites -> FAILED: none saved")
            return ("You haven't saved any favorite radio stations yet. Ask me "
                    "to play a genre and say \"save this station\" when you "
                    "like one.")
        rows = [media_hub._fav_station(f) for f in favs]
        cls = "favorites"
        pick = media_hub.pick_varied(cls, rows) or rows[0]
        media_hub.store_candidates(cls, rows)
        return _play_station_row(pick, cls)

    # ── next / nth from the shortlist we last offered ────────────────────────
    cls, candidates = media_hub.stored_candidates()
    nth = _RADIO_NTH_RE.search(text)
    if nth and candidates:
        index = _ORDINALS.get((nth.group(1) or "").lower()) or int(nth.group(2) or 0)
        if 1 <= index <= len(candidates):
            _media_log(f"play radio -> shortlist #{index} "
                       f"{candidates[index - 1].get('name')!r}")
            return _play_station_row(candidates[index - 1], cls or "any")
        return (f"I only offered {len(candidates)} station"
                f"{'s' if len(candidates) != 1 else ''} — pick one of "
                f"those, or ask me to search again.")

    if _RADIO_NEXT_RE.search(text):
        if not candidates or not _radio_is_current():
            return None          # not a radio turn; leave it to whoever owns it
        # What is playing RIGHT NOW counts as tried even when the history write
        # lost the race: "something else" that restarts the current station is
        # the exact complaint this rule exists to answer.
        current = _radio_current_name().lower()
        tried = {n.lower() for n in media_hub.recent_names(cls)}
        tried.add(current)
        nxt = next((s for s in candidates
                    if str(s.get("name") or "").lower() not in tried), None)
        if nxt is not None:
            _media_log(f"play radio -> next candidate {nxt.get('name')!r}")
            return _play_station_row(nxt, cls or "any")
        # Every station on the list has been tried. Wrapping is allowed — but
        # only said out loud, never as if it were something new.
        wrap = next((s for s in candidates
                     if str(s.get("name") or "").lower() != current), None)
        if wrap is None:
            return ("That's the only station I found for that. Ask me for a "
                    "different genre or country and I'll search again.")
        _media_log(f"play radio -> wrapped to {wrap.get('name')!r}")
        return ("That's every station I found for that, so I'm starting the "
                "list over. " + _play_station_row(wrap, cls or "any"))

    # ── find without playing ─────────────────────────────────────────────────
    if _RADIO_FIND_RE.search(text) and has_radio_cue(text):
        from puffpai.media_hub import tool_radio_stations
        return tool_radio_stations(text)

    # ── a bare radio ask ─────────────────────────────────────────────────────
    if _RADIO_BARE_RE.match(text):
        favs = media_hub.list_favorites()
        if favs:
            rows = [media_hub._fav_station(f) for f in favs]
            pick = media_hub.pick_varied("favorites", rows) or rows[0]
            media_hub.store_candidates("favorites", rows)
            return _play_station_row(pick, "favorites")
        recent = media_hub.recent_names("any") or []
        _media_log(f"play radio (bare) -> ask; {len(recent)} in history")
        return ("What kind of radio? Name a genre (jazz, news, classical), a "
                "country, or a station — and I'll find one.")
    return None


# ── "next" / "skip" while something is playing ───────────────────────────────
#
# MEASURED. With a station playing, a bare "next", "skip", "skip this song" or
# "next track" matched nothing: `_try_radio_extras` only answers "next station"
# (and only while appliance radio is current), and the play/stop fastpaths need
# a play or stop verb. The sentence went to the model, which cannot press a
# player key, so the stream played on under a reply that sounded like action.
#
# The rule is deliberately anchored on the WHOLE utterance and carries a short
# closed list of media nouns. "next step", "skip the intro of the recipe",
# "what's next on my calendar", "skip tomorrow's alarm" and "next week" are not
# media turns and must keep falling through to whoever owns them — a recipe
# read that loses "next step" to the music is the same bug in the other
# direction.
_MEDIA_SKIP_LEAD = (r'(?:please\s+|hey\s+puff\s*,?\s*|puff\s*,?\s*|can you\s+|'
                    r'could you\s+|would you\s+|just\s+|go ahead and\s+)*')
_MEDIA_SKIP_RE = re.compile(
    r'^\s*' + _MEDIA_SKIP_LEAD +
    r'(?:next|skip)(?:\s+(?:this|that|it))?'
    r'(?:\s+(?:song|track|tune|one))?\s*$',
    re.IGNORECASE)


def _try_media_skip(user_message: str) -> str | None:
    """'next' / 'skip' routed to whatever is actually playing.

    Appliance radio: exactly what "next station" does. The server-side
    playlist player (``radio_player``) is deliberately NOT handled: it exposes
    play/stop only (mpv is spawned with a fixed URL list and there is no
    advance control to call), so inventing one here would be a reply about
    something that did not happen. Nothing playing: None, and the turn falls
    through unchanged.
    """
    text = (user_message or "").strip().rstrip(".!?").strip()
    if not text or not _MEDIA_SKIP_RE.match(text):
        return None
    if _radio_is_current():
        # Same code path, same answer — including its None when there is no
        # shortlist left to move through.
        return _try_radio_extras("next station")
    return None


#: "put spotify on" / "put my spotify playlist on", the SPLIT verb.
#: `_MEDIA_VERB_RE` sees the joined "put on X" but not this, and `_try_tunein_radio` deliberately
#: stands down the moment another service is named ("that service's own route
#: owns the turn") — except no such route existed, so the sentence reached
#: nobody. Normalised here into the shape this function already understands.
_PUT_SERVICE_ON_RE = re.compile(
    r'^\s*(?:please\s+|hey\s+puff\s*,?\s*|puff\s*,?\s*|can you\s+|'
    r'could you\s+|would you\s+|just\s+)*'
    r'put\s+((?:my\s+|the\s+)?(?:spotify)(?:\s+\w+){0,3}?)\s+on\s*$',
    re.IGNORECASE)


def _try_media_play(user_message: str) -> str | None:
    text = (user_message or "").strip()
    if not text or _MEDIA_BLOCK_RE.search(text):
        return None
    split_verb = _PUT_SERVICE_ON_RE.match(text.rstrip(".!?"))
    if split_verb:
        text = f"play {split_verb.group(1).strip()}"
    m = _MEDIA_VERB_RE.search(text)
    # The verb must sit near the front — tolerates a leading wake-name / politeness
    # ("pie, can you play …") that the ^-anchored version missed — and must not be
    # a "how do I play the guitar" how-to.
    if not m or len(text[:m.start()].split()) > 6 \
            or _MEDIA_HOWTO_RE.search(text[:m.start()]):
        return None
    body = text[m.end():].strip(" ,.")
    low = body.lower()
    try:
        if "spotify" in low:
            q = re.sub(r'\b(on|from|using)?\s*spotify\b', ' ', body, flags=re.I)
            from puffpai.spotify_control import tool_spotify_play
            return tool_spotify_play(_clean_media_query(q))
        if "playlist" in low:
            shuffle = "shuffle" in low
            # Keep the playlist NAME intact — "Music"/"good"/"half pie" are real
            # names, so don't run it through the aggressive media-query cleaner.
            name = re.sub(r'\b(jellyfin|jellyfish|media server|playlist)\b|'
                          r'\b(on\s+)?shuffle\b', ' ', body, flags=re.I)
            name = re.sub(r'\b(on|from|the|my|using|please)\b', ' ', name,
                          flags=re.I)
            name = " ".join(name.split()).strip()
            # Appliance speakers first (page-independent); fall back to casting
            # to an open Jellyfin session if server-side can't.
            served = _jellyfin_play_playlist_serverside(name, shuffle=shuffle)
            if served:
                return served
            from puffpai.media_bridge import get_media_bridge, MediaBridgeError
            try:
                return get_media_bridge().play_playlist(name, shuffle=shuffle)
            except MediaBridgeError as exc:
                return str(exc)
        dial = _DIAL_RE.search(body)
        if "radio" in low or "station" in low or dial:
            # A bare dial ("play 90.3 fm") carries neither "radio" nor
            # "station", so it would fall past every fastpath into RAG, which
            # answers with an article about the frequency. The dial IS the
            # request: forward exactly the number, nothing else from the
            # sentence.
            if dial and "radio" not in low and "station" not in low:
                return _radio_play_for_query(dial.group(1).strip(), low)
            q = _clean_media_query(
                re.sub(r'\b(the|a|an|on|to)?\s*(radio|station)\b', ' ', body,
                       flags=re.I))
            return _radio_play_for_query(q, low)
        # No service named, but the user asked for a VIBE rather than a title:
        # "play some lo-fi relaxing music", "play some jazz". The library search
        # downstream matches TITLES, so this would come back "I couldn't locate a
        # track named Lo-Fi Relaxing Music". Treat it
        # as a genre request instead. A bare "play <title>" carries no genre word
        # and no music noun, so it still falls through to the library untouched.
        tags = _vibe_tags(low)
        if (tags or _MEDIA_MUSIC_NOUN_RE.search(low)) \
                and not _MEDIA_VISUAL_RE.search(low):
            # Defence in depth. `_resolve_station`
            # runs a station-NAME search on this free text before it falls back
            # to the genre tags, so "play some music for <a household name>"
            # would send that name to the mirrors. The genre tags are a CLOSED
            # vocabulary (`_GENRE_TAGS`/`_MOOD_TAGS`) and carry no household
            # text, so they stay unconditional; the free-text name search is
            # allowed only when the utterance explicitly asked for radio.
            # `_resolve_station` already skips the name search on a falsy
            # query, so this needs no change there.
            name_q = _clean_media_query(body)
            try:
                from puffpai.radio_cues import has_radio_cue
                if not has_radio_cue(text):
                    name_q = ""
            except Exception as exc:
                logger.warning("radio cue gate unavailable, tags only: %s", exc)
                name_q = ""
            st = _resolve_station(name_q, tags or ["music"])
            cands, cls = _station_candidates(name_q, tags or ["music"])
            if cands:
                from puffpai.media_hub import tool_radio_play
                # Appliance player first, browser player second — the same
                # two-step the explicit-radio branch uses. The fallback is real,
                # not theoretical: a station whose stream is dead fails every
                # appliance attempt, and the dashboard player is then the only
                # thing that can make a sound.
                return (_radio_play_serverside("", candidates=cands,
                                               query_cls=cls)
                        or tool_radio_play(cands[0].get("name") or ""))
    except Exception as exc:
        logger.warning("media play fastpath error: %s", exc)
        _media_log(f"play {_log_safe(text)!r} -> FAILED: "
                   f"{type(exc).__name__}: {exc}")
        # The class name belongs in the [Media] line above, not out loud:
        # "I hit a snag starting that — RuntimeError" is not a sentence.
        return ("I hit a snag starting that. Nothing is playing; give it "
                "another try in a moment.")
    return None


# ── TuneIn-named radio phrasings ("tune in to NPR") ──────────────────────────
#
# WHY: `_MEDIA_VERB_RE` above knows play / put on / start playing / listen
# to, and the radio branch only fires when the body still contains the
# literal word "radio" or "station". So without this block:
#   "play npr radio"      -> verb + "radio"  -> real mediahub player
#   "tune in to NPR"      -> no verb at all  -> falls through to RAG
#   "play NPR on tunein"  -> verb, no "radio"/"station" -> falls through to RAG
# and RAG answers confidently and wrongly, e.g. with an invented Raspberry Pi
# media-player workflow and a made-up stream URL. The capability registry already carries "tunein"/"tune in" as radio
# keywords (capability_registry.py, streaming.radio); this fastpath is the
# deterministic declaration of those phrasings so a play-intent can never be
# answered by the encyclopedia.
#
# "TuneIn" here is a display alias: World Radio and TuneIn are the same
# radio-browser-backed appliance player, so every phrasing below lands on
# _radio_play_for_query, exactly where "play npr radio" already lands.

#: A question ABOUT TuneIn is informational and must stay with RAG.
_TUNEIN_QUESTION_RE = re.compile(
    # Interrogatives only. Request forms ("can you …", "could you …") are
    # politeness handled by _TUNEIN_LEAD and must stay playable.
    r"^\s*(?:what|what's|whats|who|whose|how|why|when|where|which|is|are|was|"
    r"were|tell\s+me|explain|describe|define)\b",
    re.IGNORECASE)

#: Everyday "put X on" objects that are emphatically not radio stations, so
#: "put the kettle on" / "put the lights on" keep falling through untouched.
_PUT_ON_BLOCK_RE = re.compile(
    r'\b(kettle|coffee|tea|laundry|dish|dishes|dishwasher|washer|washing|'
    r'dryer|oven|stove|heat|heater|heating|furnace|air\s*con\w*|a/?c|fan|'
    r'light|lights|lamp|lamps|tv|television|kids?|baby|children|dog|cat|'
    r'timer|alarm|kettle|sweater|coat|jacket|shoes|socks|hat|gloves|pants|'
    r'shirt|pyjamas|pajamas|seatbelt|brakes?|weight|record|show)\b',
    re.IGNORECASE)

#: Optional politeness / wake-name filler ahead of the verb. (Kept local: the
#: identical `_UNTARGETED_LEAD` is defined further down this module, after
#: these patterns are already compiled at import time.)
_TUNEIN_LEAD = (r'(?:please\s+|hey\s+puff\s*,?\s*|puff\s*,?\s*|'
                r'can you\s+|could you\s+|would you\s+|'
                r'go ahead and\s+|just\s+|now\s+)*')

#: ``(pattern, requires_cue)``. ``requires_cue`` is the privacy gate: when it is True the utterance only reaches the
#: external station catalog if :func:`puffpai.radio_cues.has_radio_cue` says it
#: explicitly asked for radio. It is False only for the shape that names the
#: SERVICE as the destination in the pattern itself ("… on tunein"), where the
#: user has already told us which catalog to search.
_TUNEIN_RES = (
    # tune to 90.3 · tune in to 90.3 fm · tune to 1010 am. Not cue-gated: the
    # object is provably a NUMBER, so there is no household text to protect,
    # and "tune to <a dial>" has no non-radio reading. Listed first so the
    # general "tune in …" shape below never sees it.
    (re.compile(r'^' + _TUNEIN_LEAD +
                r'tune\s?(?:in)?\s*(?:to|into|in\s+to|on)?\s*'
                r'(\d{2,3}[.,]\d\s*(?:fm|am)?|\d{2,4}\s*(?:fm|am))\s*$',
                re.IGNORECASE), False),
    # tune in to NPR · tune into NPR · tune in NPR · tunein NPR · tune in on X
    # Cue-gated: the bare two-word idiom is NOT a radio cue, so "tune in the
    # guitar" declines locally instead of sending 'guitar' to the mirrors.
    (re.compile(r'^' + _TUNEIN_LEAD +
                r'tune\s?in(?:to|\s+to|\s+on)?\s+(?:the\s+)?(.+)$',
                re.IGNORECASE), True),
    # play NPR on tunein · listen to NPR on tune-in · put NPR on tune in
    (re.compile(r'^' + _TUNEIN_LEAD +
                r'(?:play|put\s+on|put|start(?:\s+playing)?|listen\s+to)\s+'
                r'(.+?)\s+(?:on|via|using|through|with)\s+tune\s?-?\s?in$',
                re.IGNORECASE), False),
)

#: "put NPR on" — the verb split ("put … on") that `_MEDIA_VERB_RE`'s literal
#: "put on" cannot see — and "put on NPR", which `_MEDIA_VERB_RE` DOES see but
#: which dies in `_try_media_play` because the body carries neither "radio" nor
#: "station" nor a genre token. Both are cue-gated below.
_PUT_X_ON_RES = (
    re.compile(r'^' + _TUNEIN_LEAD + r'put\s+(.+?)\s+on$', re.IGNORECASE),
    re.compile(r'^' + _TUNEIN_LEAD + r'put\s+on\s+(.+)$', re.IGNORECASE),
)

#: Another audio service was named, so that service's own route owns the turn.
#: Checked before the cue gate so "put spotify on" keeps reaching Spotify.
_PUT_ON_SERVICE_RE = re.compile(
    r'\b(spotify|jellyfin|jellyfish|playlist|netflix|youtube|'
    r'podcast|audiobook|tv|television)\b', re.IGNORECASE)


def _tunein_clean(raw: str) -> str:
    """Strip leftover service/filler words from a TuneIn-shaped station query."""
    q = re.sub(r'\b(?:tune\s?-?\s?in|the|a|an|please|for\s+me|right\s+now|'
               r'radio|station|stream|streaming|channel)\b', ' ', raw or '',
               flags=re.IGNORECASE)
    return _clean_media_query(q)


def _try_tunein_radio(user_message: str) -> str | None:
    """Route TuneIn-named / "put X on" radio phrasings to the real radio player.

    Returns ``None`` — with **zero network traffic** — for questions ABOUT
    TuneIn ("what is tunein"), for non-radio uses of "tune" ("tune the guitar",
    "tune in the guitar"), for anything another audio service owns ("put
    spotify on"), and for every "put X on" whose object carries no explicit
    radio cue ("put grandma on", "put on a sweater"). All of those keep their
    existing routes, and none of them reaches the station catalog.
    """
    text = (user_message or "").strip().rstrip(".!?").strip()
    if not text or _MEDIA_BLOCK_RE.search(text):
        return None
    if _TUNEIN_QUESTION_RE.match(text) or _MEDIA_HOWTO_RE.search(text):
        return None

    query = None
    needs_cue = True
    for pattern, requires_cue in _TUNEIN_RES:
        match = pattern.match(text)
        if match:
            query = _tunein_clean(match.group(1))
            needs_cue = requires_cue
            break

    if query is None:
        match = next((m for m in (p.match(text) for p in _PUT_X_ON_RES) if m),
                     None)
        if not match:
            return None
        obj = match.group(1)
        # Another service owns this turn ("put spotify on") — leave it alone.
        if _PUT_ON_SERVICE_RE.search(obj):
            return None
        if _PUT_ON_BLOCK_RE.search(obj):
            return None
        query = _tunein_clean(obj)
        needs_cue = True

    if not query:
        return None
    # ── THE PRIVACY GATE ─────────────────────────────────────────────────────
    # The catalog is never ASKED whether the utterance is a radio request:
    # that would send the object of every non-blocklisted "put X on" to the
    # radio-browser mirrors ('grandma', 'therapist', 'dr smith', 'medication
    # reminder', 'divorce papers'), and the household text would leave the
    # house before we decided not to act.
    #
    # The decision is made LOCALLY and fail-closed: no station catalog, no
    # socket, no household noun leaves the building unless the utterance itself
    # says "radio". A decline here costs nothing — the turn proceeds to the
    # media matcher and the honest decline.
    if needs_cue:
        try:
            from puffpai.radio_cues import has_radio_cue
            if not has_radio_cue(text):
                return None
        except Exception as exc:
            # Fail CLOSED: if the gate itself cannot run, do not egress.
            logger.warning("radio cue gate unavailable, declining: %s", exc)
            return None
    try:
        return _radio_play_for_query(query, text.lower())
    except Exception as exc:
        logger.warning("tunein fastpath error: %s", exc)
        return "I hit a snag starting that — give it another try in a moment."


# ── "what radio sources do you have" ─────────────────────────────────────────
#
# With the tunein door OPEN, "can you use TuneIn" can get a model answer saying
# it cannot reach TuneIn, and "which radio sources can you use" a library
# answer about quasars. The answer is a fact about two egress doors, so it is
# built from those doors and nothing else. Play commands ("tune in to NPR",
# "play NPR on tunein", "can you play the radio") stay with the play rules:
# the service shape only accepts the bare name of a radio SOURCE as its object,
# and the inventory shape needs "you"/"we" so an astronomy question ("what are
# radio sources in space") never looks like it is about this appliance.
_RADIO_SOURCE_NAME = (r'(?:tune\s?-?\s?in|world\s+radio|radio[\s-]browser|'
                      r'internet\s+radio|online\s+radio)')
_RADIO_SOURCES_RES = (
    # can you use TuneIn · can you play TuneIn · do you have world radio
    re.compile(r'^(?:can|could|do|does)\s+(?:you|puff|homebot)\s+'
               r'(?:use|play|access|reach|support|stream|get|have|'
               r'work\s+with|connect\s+to)\s+(?:the\s+)?'
               + _RADIO_SOURCE_NAME +
               r'(?:\s+(?:radio|app|service))?$', re.IGNORECASE),
    # what radio sources do you have · which radio sources can you use ·
    # what radio can you play · what radio services are available
    re.compile(r'^(?:what|which)\s+(?:kinds?\s+of\s+|sorts?\s+of\s+)?'
               r'(?:(?:internet|online)\s+)?radio'
               r'(?:\s+(?:sources?|services?|providers?|apps?|options?|'
               r'directories|directory))?\s+'
               r'(?:(?:do|can|could)\s+(?:you|we|i)\s+'
               r'(?:have|use|play|access|get|reach|support)'
               r'(?:\s+(?:access\s+to|here|on\s+here|right\s+now))?'
               r'|(?:are|is)\s+(?:available|on|switched\s+on))$',
               re.IGNORECASE),
)
_RADIO_SOURCES_LEAD_RE = re.compile(
    r'^(?:please\s+|hey\s+puff\s*,?\s*|puff\s*,?\s*|so\s+|and\s+|ok(?:ay)?\s*,?\s*)+',
    re.IGNORECASE)


def _radio_door_open(door_id: str) -> bool:
    """Is this egress door open right now? No network, fails shut, never
    raises: the same ``egress_allowed`` read ``tunein_catalog.door_open``
    makes, so this answer and the radio player never disagree."""
    try:
        from puffpai.security.egress_doors import egress_allowed
        return bool(egress_allowed(door_id)[0])
    except Exception as exc:
        logger.info("radio door %s unreadable (%s), treating as shut",
                    door_id, exc)
        return False


def _try_radio_sources(user_message: str) -> str | None:
    """Say which radio sources HomeBot can use, from the real door states."""
    text = (user_message or "").strip().rstrip(".!?").strip()
    text = _RADIO_SOURCES_LEAD_RE.sub("", text).strip()
    if not text or len(text) > 80:
        return None
    if not any(p.match(text) for p in _RADIO_SOURCES_RES):
        return None
    world = _radio_door_open("radio_browser")
    tunein = _radio_door_open("tunein")
    if world and tunein:
        return ("I can play internet radio from two places: World Radio, "
                "which searches the free Radio Browser directory, and TuneIn. "
                "Ask for a station or a genre, like \"play jazz radio\" or "
                "\"tune in to NPR\".")
    if world:
        return ("I can play internet radio from World Radio, which searches "
                "the free Radio Browser directory. TuneIn is switched off in "
                "Settings, so I don't look there. Ask for a station or a "
                "genre, like \"play jazz radio\".")
    if tunein:
        return ("TuneIn is switched on, but World Radio, the free Radio "
                "Browser directory, is switched off in Settings, so I can't "
                "search for new stations the usual way. Stations you already "
                "saved still play.")
    return ("Internet radio is switched off right now: World Radio and TuneIn "
            "are both off in Settings. Stations you already saved still play.")


# ── "what's playing" ─────────────────────────────────────────────────────────
#
# Without a deterministic owner, "whats playing right now" can be answered
# "There's nothing playing at the moment" (route: agent) and "whats playing"
# "I'm not seeing any active media session" (route: RAG, with fabricated
# sources) while an mpv process and a Pulse sink-input are both live. This
# fastpath is that owner; puffpai.now_playing derives
# the answer from the PLAYER (mpv process / Jellyfin
# session / Pulse sink-inputs), never from a declaration.
_NOW_PLAYING_RE = re.compile(
    r"^(?:please\s+|hey\s+puff\s*,?\s*|puff\s*,?\s*|can you\s+|could you\s+|"
    r"tell me\s+|just\s+)*"
    r"(?:"
    r"what(?:'s|s| is)?\s+(?:currently\s+|now\s+)?playing"
    r"|what\s+(?:song|track|station|music|tune|artist|band)\s+is\s+"
    r"(?:this|that|playing|on)"
    # reversed order — "what is this song" / "what's this track"
    r"|what(?:'s|s| is)?\s+(?:this|that)\s+"
    r"(?:song|track|station|music|tune|artist|band)"
    r"|what\s+am\s+i\s+listening\s+to"
    r"|who(?:'s|s| is)?\s+(?:this\s+)?(?:singing|playing)"
    r"|who\s+(?:sings|sang|plays|played|does)\s+(?:this|that|it)"
    # bare "now playing" — the phrasing the dashboard tile uses out loud
    r"|now\s+playing"
    r"|(?:is|are)\s+(?:there\s+)?(?:anything|something|any\s+music)\s+playing"
    r"|what(?:'s|s| is)?\s+(?:on\s+)?(?:the\s+)?(?:radio|speakers)"
    r")"
    r"(?:\s+(?:right\s+now|now|at\s+the\s+moment|currently|"
    r"on\s+the\s+speakers|in\s+here))*"
    r"\??$", re.IGNORECASE)
#: A service-specific question keeps its own, richer tool (account, station
#: list, device). Only the GENERAL question belongs to this fastpath.
_NOW_PLAYING_SERVICE_RE = re.compile(
    r'\b(spotify|jellyfin|jellyfish|netflix|tv|youtube|'
    r'theat(?:er|re)|cinema|movies)\b',
    re.IGNORECASE)

#: AMBIGUOUS bare forms. "what's this" is a real way to ask about the music,
#: and also a real way to ask about a photo, a smell or a noise the dishwasher
#: is making. Claiming it unconditionally would answer "Nothing is playing
#: right now." to someone holding up a letter. So these claim the turn ONLY
#: when a source is observably playing, and otherwise decline and let the
#: normal route answer — the question is only about music when there is music.
_NOW_PLAYING_WEAK_RE = re.compile(
    r"^(?:please\s+|hey\s+puff\s*,?\s*|puff\s*,?\s*)*"
    r"(?:what(?:'s|s| is)\s+(?:this|that)|who(?:'s|s| is)\s+(?:this|that))"
    r"\s*\??$", re.IGNORECASE)


def _try_now_playing(user_message: str) -> str | None:
    """Answer "what's playing" from observed player state."""
    text = (user_message or "").strip()
    if not text:
        return None
    weak = False
    if not _NOW_PLAYING_RE.match(text):
        if not _NOW_PLAYING_WEAK_RE.match(text):
            return None
        weak = True
    if _NOW_PLAYING_SERVICE_RE.search(text):
        return None
    try:
        from puffpai.now_playing import describe_playback, observed_playback
        # ONE probe per turn: the weak-form check and the sentence share
        # observed_playback’s result.
        entries = observed_playback()
        if weak and not entries:
            return None
        return describe_playback(entries=entries)
    except Exception as exc:                              # pragma: no cover
        logger.warning("now-playing fastpath error: %s", exc)
        return None


_MEDIA_STOP_VERB_RE = re.compile(
    r'\b(stop|pause|turn it off|turn off|shut off|shut it off|silence|halt|'
    r'quit playing)\b', re.IGNORECASE)
_MEDIA_STOP_TARGET_RE = re.compile(
    r'\b(music|radio|song|songs|track|tracks|playback|playing|media|stream|'
    r'streaming|spotify|jellyfin|jellyfish|tunes|audio|sound|it|that|'
    r'this|everything|all)\b', re.IGNORECASE)
# a truly bare stop with no object — anything else ("stop sharing", "stop
# talking") is not ours.
_MEDIA_BARE_STOP = {"stop", "pause", "halt", "silence", "stop now",
                    "stop please", "please stop", "just stop"}


def _media_sources_still_playing() -> list:
    """Which sources are OBSERVABLY still making noise after a stop.

    Only positive evidence counts: the radio container still running. An
    unreachable/idle source reports nothing — this must never invent a
    failure, only catch the real one (a stop that claims success while a
    source plays on).
    """
    noisy = []
    try:
        from puffpai import radio_player
        if radio_player.is_playing():
            noisy.append("the radio")
    except Exception as exc:
        logger.debug("radio stop verification skipped: %s", exc)
    return noisy


#: "stop the tv", "turn off the tv", "turn the tv off", "stop the channel",
#: "stop watching (tv)", with optional politeness, wake name and "please".
_TV_STOP_RE = re.compile(
    r"^(?:(?:hey |ok |okay )?(?:puff(?:pai)?|pie|puffy)[ ,]+)?"
    r"(?:(?:please|can you|could you|would you|will you)\s+)?"
    r"(?:(?:stop|end|close|turn off|switch off|shut off)\s+(?:the |this |that )?"
    r"(?:tv|t\.v\.|television|telly|live tv|tv player|channel|tv channel)"
    r"|(?:turn|switch|shut)\s+(?:the |this |that )?(?:tv|t\.v\.|television|telly)\s+off"
    r"|stop watching(?:\s+(?:the )?(?:tv|t\.v\.|television|telly|this|that))?)"
    r"(?:\s+(?:please|now|for me))*$",
    re.IGNORECASE)


def _try_tv_stop(user_message: str) -> str | None:
    """Stop the kiosk's full-screen TV player ("Watch smooth") by voice/chat.

    Claims the turn ONLY while the player is on. Otherwise every phrase falls
    through exactly as before, so "turn off the tv" still reaches the house's
    own TV in Home Assistant when nothing is playing on the kiosk. "stop
    jellyfin" is handled in _try_media_stop's jellyfin branch.
    """
    low = (user_message or "").strip().lower().rstrip(".!?")
    if not low or not _TV_STOP_RE.match(low):
        return None
    try:
        from puffpai import tv_player
        if not tv_player.is_playing():
            return None
        _media_log("stop tv player")
        if tv_player.stop():
            return "Okay, the TV is off."
        return "I tried to turn the TV off, but it is still playing. Tap the picture to close it."
    except Exception as exc:
        logger.warning("tv stop fastpath error: %s", exc)
        return None


def _try_media_stop(user_message: str) -> str | None:
    """Universal media stop — 'stop', 'pause', 'stop the music/radio', 'stop
    spotify'. Silences whatever is playing, on ANY source, from voice or chat.
    Never eats 'stop the timer/alarm' (that stays with _try_alarm_dismiss)."""
    low = (user_message or "").strip().lower().rstrip(".!?")
    if not low or not _MEDIA_STOP_VERB_RE.search(low):
        return None
    if re.search(r'\b(timers?|alarms?)\b', low):
        return None
    named = next((s for s in ("spotify", "jellyfin", "radio")
                  if s in low), None)
    if not named and "jellyfish" in low:
        named = "jellyfin"
    # a truly bare "stop"/"pause" or an explicit media target ("stop the music",
    # "stop it"). "stop sharing"/"stop talking" have neither → left to others.
    if not named and low not in _MEDIA_BARE_STOP \
            and not _MEDIA_STOP_TARGET_RE.search(low):
        return None
    _media_log(f"stop {named or 'all sources'}")
    try:
        if named == "spotify":
            from puffpai.spotify_control import tool_spotify_pause
            return tool_spotify_pause()
        if named == "radio":
            from puffpai import radio_player
            radio_player.stop()                 # server-side player
            from puffpai.media_hub import tool_radio_stop
            return tool_radio_stop()            # + tell the browser player to stop
        if named == "jellyfin":
            from puffpai import radio_player
            radio_player.stop()                 # appliance playlist (mpv)
            tv_was_on = False
            try:                                # + the kiosk TV player
                from puffpai import tv_player
                tv_was_on = tv_player.is_playing()
                if tv_was_on:
                    tv_player.stop()
            except Exception as exc:
                logger.warning("tv stop (jellyfin) error: %s", exc)
            from puffpai.media_bridge import get_media_bridge
            sess = get_media_bridge().now_playing()
            if sess:                            # + any cast session
                return get_media_bridge().playback_control(
                    getattr(sess[0], "session_id", ""), "stop")
            if tv_was_on:
                return "Okay, the TV is off."
            return "Stopped the media server playback."
        # bare / generic stop: silence every source (each is a no-op if idle)
        for _stop in (
            lambda: __import__("puffpai.radio_player", None, None,
                               ["stop"]).stop(),
            lambda: __import__("puffpai.media_hub", None, None,
                               ["tool_radio_stop"]).tool_radio_stop(),
            lambda: __import__("puffpai.spotify_control", None, None,
                               ["tool_spotify_pause"]).tool_spotify_pause(),
            # the kiosk's full-screen TV player (no-op if it is not on)
            lambda: __import__("puffpai.tv_player", None, None,
                               ["stop"]).stop(),
        ):
            try:
                _stop()
            except Exception:
                pass
        # VERIFY the silence before claiming it: otherwise "stop the music"
        # can report success while a source keeps playing. Each check
        # reads real state — the radio container's existence — and anything
        # still making noise is named, not hidden.
        noisy = _media_sources_still_playing()
        if noisy:
            return ("I stopped what I could, but " + " and ".join(noisy)
                    + " still reports playing. Try again, or stop it from its "
                      "own player.")
        return "Okay — stopping any music or radio."
    except Exception as exc:
        logger.warning("media stop fastpath error: %s", exc)
        return "I tried to stop playback but hit a snag."


# ── Untargeted whole-house commands ──────────────────────────────────────────
#
# WHY. "turn off everything" is the single most obvious thing a stranger says
# to a house assistant. The HA gate does the RIGHT thing with it,
# `untargeted_request_detail` refuses a service call that names no entity, so
# nothing in the house moves and `control_device` is never called. The REPLY
# must match: the sentence has the verb "turn off" and the word "everything",
# which is exactly the shape `_MEDIA_STOP_VERB_RE` + `_MEDIA_STOP_TARGET_RE`
# look for, so the media-stop fastpath would claim the turn and answer "Okay —
# stopping any music or radio." The safety contract would hold and the
# sentence would lie about what happened.
#
# This fastpath runs BEFORE the media ones and says plainly what the gate did.
# It is deliberately narrow: it fires only when the whole message is a bare
# whole-house on/off command. "turn off the living room lights", "turn off the
# music", "stop everything" (no on/off verb) and anything naming a room or a
# device fall straight through to the paths that already handle them.

#: Scope words that mean "the entire house" and name no target.
_UNTARGETED_SCOPE = (r'(?:everything|every ?thing|it all|all of it|'
                     r'all the things|the whole house|the entire house|'
                     r'the whole place|the house)')
#: Optional politeness / filler ahead of the verb.
_UNTARGETED_LEAD = (r'(?:please\s+|hey\s+puff\s*,?\s*|puff\s*,?\s*|'
                    r'can you\s+|could you\s+|would you\s+|'
                    r'go ahead and\s+|just\s+|now\s+)*')

_UNTARGETED_HOUSE_RES = (
    # turn/switch/power off everything · turn on the whole house
    re.compile(r'^' + _UNTARGETED_LEAD +
               r'(?:turn|switch|power|shut)\s+(on|off|down)\s+'
               + _UNTARGETED_SCOPE + r'$', re.IGNORECASE),
    # turn everything off · shut it all down · power the house down
    re.compile(r'^' + _UNTARGETED_LEAD +
               r'(?:turn|switch|power|shut)\s+' + _UNTARGETED_SCOPE +
               r'\s+(on|off|down)$', re.IGNORECASE),
)

# ── Broadcast-LIGHTS phrasings ───────────────────────────────────────────────
#
# The scope words above are all house-wide NOUNS ("everything", "the house").
# `turn off all the lights in the house` names a device CLASS instead, so it
# would miss this gate entirely and fall through to _try_media_stop, which
# matches on "turn off" + "all" and answers "Okay - stopping any music or
# radio." No device is touched (the safety contract holds) but the sentence is wrong.
# These patterns claim the untargeted-LIGHTS shape for the same refusal.
#
# The quantifier ("all"/"every"/"the entire set of") is REQUIRED: it is what
# separates a broadcast from a target. "turn off the kitchen light",
# "turn off the lights in the bedroom" and "turn off the living room lights"
# carry no quantifier (or carry a room) and still fall through untouched.
_UNTARGETED_LIGHT_NOUN = r'(?:lights?|lamps?|lighting)'
#: Only house-WIDE locatives may trail. A room name here would make the
#: command targeted, so a bare "downstairs"/"in the kitchen" deliberately does
#: NOT appear and keeps falling through to the real device path. The CONJOINED
#: form ("upstairs and downstairs") is the opposite: naming both floors is a
#: way of saying "the whole house", which is why "shut off all
#: the lights upstairs and downstairs" belongs to this gate.
_UNTARGETED_LIGHT_TAIL_ALTS = (
    r'(?:in|around|throughout|across|all\s+over)\s+'
    r'(?:the\s+)?(?:whole\s+|entire\s+)?house'
    r'|everywhere'
    r'|in\s+the\s+whole\s+place'
    r'|upstairs\s+and\s+downstairs'
    r'|downstairs\s+and\s+upstairs'
    r'|(?:on|across)\s+(?:every|all|both)\s+(?:the\s+)?floors?'
    r'|in\s+(?:every|all)\s+(?:the\s+)?rooms?'
)
_UNTARGETED_LIGHT_TAIL = r'(?:\s+(?:' + _UNTARGETED_LIGHT_TAIL_ALTS + r'))?'
#: The same locatives, REQUIRED — this is what lets a phrasing with no
#: quantifier ("lights off everywhere") still be recognised as house-wide.
_UNTARGETED_LIGHT_TAIL_REQ = r'\s+(?:' + _UNTARGETED_LIGHT_TAIL_ALTS + r')'
_UNTARGETED_LIGHT_QUANT = (r'(?:all\s+(?:of\s+)?(?:the\s+)?|every\s+(?:single\s+)?'
                           r'|each\s+|the\s+entire\s+set\s+of\s+)')
_UNTARGETED_LIGHT_SCOPE = (_UNTARGETED_LIGHT_QUANT + _UNTARGETED_LIGHT_NOUN
                           + _UNTARGETED_LIGHT_TAIL)
#: "out" joins on/off/down: "lights out everywhere" is the same command.
_UNTARGETED_LIGHT_DIR = r'(on|off|down|out)'
#: "kill"/"cut" are how people actually say this out loud, and the verb is
#: OPTIONAL entirely — "every light off" and "all lights off" are complete
#: commands that carry no verb at all and would fall straight through to the router.
_UNTARGETED_LIGHT_VERB = r'(?:turn|switch|power|shut|kill|cut)'

_UNTARGETED_LIGHT_RES = (
    # turn off all the lights in the house · kill all the lights ·
    # shut off all the lights upstairs and downstairs
    re.compile(r'^' + _UNTARGETED_LEAD + _UNTARGETED_LIGHT_VERB +
               r'\s+' + _UNTARGETED_LIGHT_DIR + r'\s+'
               + _UNTARGETED_LIGHT_SCOPE + r'$', re.IGNORECASE),
    # turn all the lights off · shut every light down
    re.compile(r'^' + _UNTARGETED_LEAD + _UNTARGETED_LIGHT_VERB +
               r'\s+' + _UNTARGETED_LIGHT_SCOPE +
               r'\s+' + _UNTARGETED_LIGHT_DIR + r'$', re.IGNORECASE),
    # kill all the lights · cut every light  (verb, quantifier, NO direction —
    # "kill" already means off)
    re.compile(r'^' + _UNTARGETED_LEAD + r'(?:kill|cut)\s+'
               + _UNTARGETED_LIGHT_SCOPE + r'$', re.IGNORECASE),
    # every light off · all lights off · all the lights on   (VERB-OPTIONAL)
    re.compile(r'^' + _UNTARGETED_LEAD + _UNTARGETED_LIGHT_SCOPE +
               r'\s+' + _UNTARGETED_LIGHT_DIR + r'$', re.IGNORECASE),
    # lights off everywhere · lights out in every room  (no quantifier, so a
    # house-wide locative is REQUIRED — a bare "lights off" stays ambiguous
    # and keeps its existing route)
    re.compile(r'^' + _UNTARGETED_LEAD + _UNTARGETED_LIGHT_NOUN + r'\s+'
               + _UNTARGETED_LIGHT_DIR + _UNTARGETED_LIGHT_TAIL_REQ + r'$',
               re.IGNORECASE),
)


def _try_untargeted_house_command(user_message: str) -> str | None:
    """Answer a bare whole-house on/off command honestly, without acting.

    Returns ``None`` for anything that names a room, a device or a media
    source, so every existing route keeps its sentences. Never calls Home
    Assistant: the point is that NO device action is taken and the
    reply says so.
    """
    low = (user_message or "").strip().lower().rstrip(".!?").strip()
    if not low:
        return None
    direction = None
    lights_only = False
    for pattern in _UNTARGETED_HOUSE_RES:
        match = pattern.match(low)
        if match:
            direction = match.group(1)
            break
    if direction is None:
        # Same refusal for a broadcast over the LIGHTS specifically.
        for pattern in _UNTARGETED_LIGHT_RES:
            match = pattern.match(low)
            if match:
                # The "kill/cut all the lights" shape captures no direction —
                # the verb already means off. "out" is off said differently.
                captured = next((g for g in match.groups() if g), None)
                direction = "off" if captured in (None, "out") else captured
                lights_only = True
                break
    if direction is None:
        return None
    verb = "switch on" if direction == "on" else "switch off"
    example = ("turn on the living room lights" if direction == "on"
               else "turn off the living room lights")
    if lights_only:
        # Name the thing refused ("every light at once") so the sentence is
        # about the gate, not about music — and still offer the room.
        reply = (f"I don't {verb} the whole house from one command, and that "
                 f"includes every light at once. Tell me a room or a device, "
                 f"or say '{example}'.")
    else:
        reply = (f"I don't {verb} the whole house from one command. "
                 f"Tell me a room or a device, or say '{example}'.")
    # If something is ACTUALLY making noise, offer to stop it as its own
    # question — never as the answer to what was asked.
    try:
        noisy = _media_sources_still_playing()
    except Exception:                                    # pragma: no cover
        noisy = []
    if noisy:
        verb_be = "is" if len(noisy) == 1 else "are"
        reply += (f" Separately: {' and '.join(noisy)} {verb_be} playing "
                  f"right now — want me to stop that?")
    return reply


# ── Household fastpaths ──────────────────────────────────────────────────────
#
# All of the same shape: the CAPABILITY works and the PHRASING would never
# reach it. Each of these is a deterministic declaration of natural phrasings, with
# a decline for everything else — the same pattern as the fastpaths above, and
# the same rule: an answer this layer gives must be right by construction, not
# by luck.

# ── Calculator ───────────────────────────────────────────────────────────────
# Left to the team, `whats 847 times 63` can end "Sorry, I couldn't complete
# that one" ({"intent":"plan","result":null}: the contraction breaks intent
# classification into a failed planner call), and `what is 847 multiplied by
# 63` is answered through the LLM with RAG sources attached, right by luck.
# puffpai.calculator parses and evaluates without eval; anything it cannot
# parse with certainty returns None and falls through untouched.
_CALC_HINT_RE = re.compile(
    r"(?i)\b(?:times|multiplied|multiply|divided|divide|plus|minus|percent|"
    r"per cent|square root|to the power of|calculate|compute|how much is)\b"
    r"|[+*/^%×÷]|\d\s*x\s*\d")


def _try_calculate(user_message: str) -> "str | None":
    """Answer arithmetic deterministically, or decline.

    Two gates, both required. The hint regex keeps this off sentences that
    merely contain numbers ("set an alarm for 6:45"), and the parser itself
    refuses anything that is not pure arithmetic once the filler words are
    stripped — a leftover word is an unparseable character, not a guess.
    """
    text = (user_message or "").strip()
    if not text or len(text) > 160:
        return None
    if not _CALC_HINT_RE.search(text):
        return None
    try:
        from puffpai.calculator import solve
        solved = solve(text)
    except Exception as exc:                             # pragma: no cover
        logger.debug("calculator fastpath error: %s", exc)
        return None
    if not solved:
        return None
    expression, answer = solved
    print("[Chat] Capability read: calculate")
    return f"{answer}. ({expression})"


# ── Today's training program ─────────────────────────────────────────────────
# `GET /fitness/program` returns a real program; natural chat phrasings would
# never reach it, and "show me my exercise program for today" would be
# answered "I don't have an existing program saved", which is false. Same
# data, same library, on the chat surface too.
_FITNESS_PROGRAM_RE = re.compile(
    r"(?i)"
    r"\b(?:what|which)\s+workout\b[^.?!]{0,40}\b(?:today|supposed to|should i)\b"
    r"|\b(?:todays|today's)\s+(?:training|workout|exercise|lifting)\s*"
    r"(?:session|program|programme|plan|routine)?\b"
    r"|\b(?:training|exercise|workout|lifting)\s+"
    r"(?:session|program|programme|plan|routine)\b"
    r"|\bwhat\s+(?:am\s+i|do\s+i)\s+(?:supposed\s+to\s+)?(?:do|train|lift)\b"
    r"[^.?!]{0,20}\btoday\b")
_FITNESS_PROGRAM_BLOCK_RE = re.compile(
    r"(?i)\b(?:log|logged|record|delete|streak|personal records?|goals?|"
    r"history|random|generate|make me|build me|create|suggest)\b")


#: "Log my workout as complete" must not be answered with four questions
#: (member, type, minutes, notes) for a session the appliance has already
#: planned and can name ("Lower Volume, 45 min"). The plan is the
#: answer: today's session IS what they did, and the only honest question left
#: is the one asked when nothing is planned today.
_WORKOUT_LOG_RE = re.compile(
    r"(?i)\b(?:log|mark|record|finish(?:ed)?|complete[d]?|done\s+with|did)\b"
    r"[^.?!]{0,30}\b(?:workout|training|session|exercise)\b"
    r"|\b(?:workout|training|session)\b[^.?!]{0,20}"
    r"\b(?:is\s+)?(?:complete|completed|done|finished)\b")
#: Reads, deletes and plans are somebody else's.
_WORKOUT_LOG_BLOCK_RE = re.compile(
    r"(?i)\b(?:what|which|when|how\s+(?:long|many|much)|streak|delete|remove|"
    r"undo|cancel|skip|plan|schedule|show|list|tell\s+me|supposed\s+to|"
    r"history|last\s+week)\b")
#: "45 min" inside a session name, which is where the live plan keeps it.
_WORKOUT_MINUTES_RE = re.compile(r"(?i)(\d{1,3})\s*(?:min|minute)")


def _workout_session_name(session) -> str:
    """What today's planned session is CALLED, or "" if it has no name."""
    if not isinstance(session, dict):
        return str(session or "").strip()
    for key in ("name", "title", "day", "label"):
        value = str(session.get(key) or "").strip()
        if value:
            return value
    return ""


def _workout_minutes(session, name: str) -> int:
    """The planned length in minutes. Falls back to the library default."""
    if isinstance(session, dict):
        for key in ("duration_min", "minutes", "duration", "length_min"):
            value = session.get(key)
            if isinstance(value, (int, float)) and value > 0:
                return int(value)
            found = _WORKOUT_MINUTES_RE.search(str(value or ""))
            if found:
                return int(found.group(1))
    found = _WORKOUT_MINUTES_RE.search(name or "")
    return int(found.group(1)) if found else 30


def _workout_user_key(app, display_name: str):
    """The FitFam key for *display_name*, or None when it cannot be settled."""
    try:
        users = (app.get_data('fitfam') or {}).get('users', {}) or {}
    except Exception as exc:
        logger.debug("fitfam users unavailable: %s", exc)
        return None
    wanted = str(display_name or "").strip().lower()
    # The PROFILE names its own slice. ``fitfam_key`` (or the legacy
    # ``family_id``, or the profile id, which is now a slug of the name) is
    # tried before the display name, because matching on display name alone is
    # exactly what the placeholder "Owner" broke.
    try:
        from puffpai import household
        for candidate in household.fitfam_keys_for(display_name):
            if candidate in users:
                return candidate
    except Exception as exc:
        logger.debug("household key lookup unavailable: %s", exc)
    for key, row in users.items():
        if wanted and (key.lower() == wanted
                       or str((row or {}).get('name') or '').lower() == wanted):
            return key
    return list(users)[0] if len(users) == 1 else None


#: The generic "nothing planned" answer, said in one place so the ask path and
#: the log path cannot drift apart.
_WORKOUT_NOTHING_PLANNED = (
    "There's nothing planned for today, so there's no session to mark done. "
    "Tell me what you did and I'll log that instead.")

_WORKOUT_WHOSE = ("Whose workout? More than one person is set up here, so "
                  "tell me who and I'll mark it done.")

#: Said when NOBODY in FitFam is training today. Distinct from
#: :data:`_WORKOUT_NOTHING_PLANNED` (which answers "your profile's program has
#: no session today"); this one answers "no member of this household has one".
_WORKOUT_NOTHING_PLANNED_TODAY = (
    "Nothing is planned for today, so there's nothing to log. "
    "Tell me what you did and I'll log that instead.")


def _fitfam_users() -> dict:
    """``{key: row}`` from the FitFam store, or ``{}``. Never raises."""
    try:
        return (_get_app_data().get_data('fitfam') or {}).get('users', {}) or {}
    except Exception as exc:
        logger.debug("fitfam users unavailable: %s", exc)
        return {}


def _fitfam_planned_today(key: str, row) -> "dict | None":
    """Today's planned session for FitFam member *key*, or None.

    A member is training today when their OWN FitFam prefs name a program the
    offline library actually carries (``prefs.program``), and that program has
    a session for today. Nothing else in the store is a plan: ``history`` and
    ``sets`` are what already happened, and inferring a program from a bare
    ``level`` would make every member "planned" and put the household straight
    back into the "whose workout?" question this path exists to replace.
    """
    program_key = str(((row or {}).get('prefs') or {}).get('program') or '')
    program_key = program_key.strip()
    if not program_key:
        return None
    try:
        program = _load_workout_library()['programs'][program_key]
    except Exception as exc:
        logger.debug("workout program %r unavailable: %s", program_key, exc)
        return None
    sessions = program.get('sessions') or []
    if not sessions:
        return None
    session = sessions[datetime.now().timetuple().tm_yday % len(sessions)]
    if not _workout_session_name(session):
        return None
    return {'key': key, 'name': str((row or {}).get('name') or key),
            'program': program.get('title'), 'session': session}


def _workout_planned_members() -> list:
    """Every FitFam member with a session planned today, oldest key order."""
    out = []
    for key, row in _fitfam_users().items():
        plan = _fitfam_planned_today(key, row)
        if plan is not None:
            out.append(plan)
    return out


def _workout_log_planned(data=None) -> str:
    """Log for the ONE member training today, or say nobody is.

    Reached when "log my workout" cannot be pinned to a FitFam member by name
    (the owner profile's placeholder ``display_name`` "Owner" matches no
    member key). Asking "Whose workout?" in a household where exactly one
    person has a plan is not honest; the question is only honest when two or
    more people are genuinely training.
    """
    planned = _workout_planned_members()
    if not planned:
        return _WORKOUT_NOTHING_PLANNED_TODAY
    if len(planned) > 1:
        return _ask_whose_fitfam_user(data)
    plan = planned[0]
    name = _workout_session_name(plan['session'])
    try:
        _get_app_data().fit_log_workout(
            plan['key'], name, _workout_minutes(plan['session'], name))
    except Exception as exc:
        logger.debug("workout-log write failed: %s", exc)
        return _WORKOUT_NOTHING_PLANNED_TODAY
    return (f"Logged {plan['name']}'s planned session for today as complete: "
            f"{name}.")


def _workout_profiles() -> list:
    """The household's fitness profiles, newest shape, or []. Never raises."""
    try:
        from puffpai.profile_manager import profiles_path
        loaded = _load_json_file(profiles_path(), {'profiles': []})
        return [p for p in (loaded.get('profiles') or []) if isinstance(p, dict)]
    except Exception as exc:
        logger.debug("fitness profiles unavailable: %s", exc)
        return []


def _workout_owner_profile(profiles=None):
    """The profile that IS the owner, or None. The same "owner" id the shipped
    ``config/profiles.json`` uses (``tests/test_fitness_program.py``)."""
    for prof in (profiles if profiles is not None else _workout_profiles()):
        if (prof.get('id') == 'owner'
                or str(prof.get('role') or '').lower() == 'owner'
                or prof.get('is_owner') is True):
            return prof
    return None


def _workout_planned_today(profiles=None) -> list:
    """[(display_name, program dict)] for everyone with a session planned."""
    out = []
    for prof in (profiles if profiles is not None else _workout_profiles()):
        who = str(prof.get('display_name') or prof.get('id') or '').strip()
        if not who:
            continue
        try:
            data, _reason = _fitness_program_data(who.lower())
        except Exception as exc:
            logger.debug("fitness program lookup failed: %s", exc)
            continue
        if data and _workout_session_name(data.get('session')):
            out.append((who, data))
    return out


def _workout_log_unresolved() -> "str | None":
    """Who "log my workout" means, without asking.

    With no profile active on an API call, "log my workout as complete"
    would otherwise be answered "Whose workout?", a question the plan
    already answers. The plan is the answer: the OWNER's session
    if the household has an owner profile, otherwise the one member who has a
    session planned today. Only a household where several people are genuinely
    training today is asked, and then the question remembers what it asked.
    """
    profiles = _workout_profiles()
    if not profiles:
        # Nothing to enumerate: no profile file, or an appliance that has not
        # been set up yet. FitFam's own plans are the remaining evidence, and
        # they still answer this without a question most of the time.
        return _workout_log_planned(None)
    owner = _workout_owner_profile(profiles)
    if owner is not None:
        who = str(owner.get('display_name') or owner.get('id') or '').strip()
        data, _reason = _fitness_program_data(who.lower())
        if data:
            return _workout_log_for(data)
    planned = _workout_planned_today(profiles)
    if not planned:
        return _WORKOUT_NOTHING_PLANNED
    if len(planned) == 1:
        return _workout_log_for(planned[0][1])
    return _ask_whose_workout([who for who, _d in planned],
                              {who: d for who, d in planned})


def _ask_whose_workout(names, by_name) -> str:
    """Ask, and remember the ask: "Casey" on the next turn logs Casey's session."""
    def _complete(chosen, said):
        picked = (chosen or [])[:1]
        if not picked:
            return None
        return _workout_log_for(by_name.get(picked[0]["value"]))

    try:
        _pending_clarifier.register("workout_member", _complete, list(names),
                                    prompt=_WORKOUT_WHOSE)
    except Exception as exc:          # pragma: no cover - never worth the ask
        logger.debug("workout clarifier not registered: %s", exc)
    return _WORKOUT_WHOSE


def _workout_log_for(data, user_key=None) -> "str | None":
    """Complete today's planned session for the person *data* describes."""
    if not isinstance(data, dict):
        return None
    name = _workout_session_name(data.get('session'))
    if not name:
        return _WORKOUT_NOTHING_PLANNED
    try:
        app = _get_app_data()
        key = user_key or _workout_user_key(app, data.get('user'))
        if not key:
            # The profile name matched no FitFam member (the owner profile
            # ships the placeholder display_name "Owner").
            # Decide from the plans instead of asking.
            return _workout_log_planned(data)
        result = app.fit_log_workout(key, name, _workout_minutes(
            data.get('session'), name))
    except Exception as exc:
        logger.debug("workout-log write failed: %s", exc)
        return None
    if isinstance(result, str) and result.lower().startswith("unknown user"):
        return _workout_log_planned(data)
    # The tool's own sentence carries a streak and a person's numbers. The
    # confirmation names the session and stops (no metric in the reply).
    return f"Marked today's session done: {name}."


def _ask_whose_fitfam_user(data) -> str:
    """The FitFam members, when the profile name matches none of them."""
    options = []
    try:
        users = (_get_app_data().get_data('fitfam') or {}).get('users', {}) or {}
        for key, row in users.items():
            label = str((row or {}).get('name') or key)
            options.append({"label": label, "value": key,
                            "tokens": [label, key]})
    except Exception as exc:
        logger.debug("fitfam users unavailable for the ask: %s", exc)
    if len(options) > 1:
        def _complete(chosen, said):
            picked = (chosen or [])[:1]
            if not picked:
                return None
            return _workout_log_for(data, user_key=picked[0]["value"])

        try:
            _pending_clarifier.register("workout_member", _complete, options,
                                        prompt=_WORKOUT_WHOSE)
        except Exception as exc:      # pragma: no cover - never worth the ask
            logger.debug("workout clarifier not registered: %s", exc)
    return _WORKOUT_WHOSE


def _try_workout_log(user_message: str) -> "str | None":
    """"Log my workout" completes TODAY's planned session, in one step.

    Confirms by the session's NAME and nothing else — no minutes logged
    against a person, no streak, no weight. Asks exactly one question, and
    only when there is genuinely nothing planned today or the household has
    more than one member and no active profile to resolve "my".
    """
    text = (user_message or "").strip()
    if not text or len(text) > 160:
        return None
    if _WORKOUT_LOG_BLOCK_RE.search(text) or not _WORKOUT_LOG_RE.search(text):
        return None
    if not _app_installed('fitfam'):
        return None
    try:
        data, reason = _fitness_program_data("", strict_user=True)
    except Exception as exc:
        logger.debug("workout-log fastpath error: %s", exc)
        return None
    if data is None:
        if reason == 'ambiguous user':
            return _workout_log_unresolved()
        return None
    return _workout_log_for(data)


def _try_fitness_program(user_message: str) -> "str | None":
    """Read today's program from the same library GET /fitness/program uses."""
    text = (user_message or "").strip()
    if not text or len(text) > 160:
        return None
    if _FITNESS_PROGRAM_BLOCK_RE.search(text):
        return None
    if not _FITNESS_PROGRAM_RE.search(text):
        return None
    try:
        data, reason = _fitness_program_data("", strict_user=True)
    except Exception as exc:
        logger.debug("fitness program fastpath error: %s", exc)
        return None
    if data is None:
        if reason == 'ambiguous user':
            return ("Whose training program? More than one person is set up "
                    "here, so tell me who and I'll read theirs.")
        return (f"I can't read your training program right now — {reason}. "
                "Nothing is saved for me to read out.")
    session = data.get('session') or {}
    lines = [f"{data.get('user') or 'You'} — {data.get('program')}"
             f" ({data.get('days_per_week')} days a week)."]
    title = session.get('name') or session.get('title') or session.get('day')
    if title:
        lines.append(f"Today: {title}.")
    blocks = session.get('exercises') or session.get('blocks') or []
    for item in blocks[:12]:
        if isinstance(item, dict):
            name = item.get('name') or item.get('exercise') or ''
            detail = item.get('prescription') or item.get('sets') or ''
            lines.append(f"  - {name}{': ' + str(detail) if detail else ''}")
        else:
            lines.append(f"  - {item}")
    if data.get('guidance'):
        lines.append(str(data['guidance']))
    print("[Chat] Capability read: fitness_program")
    return "\n".join(lines)


# ── Delete / undo a logged workout ───────────────────────────────────────────
# "delete the test-fakeworkout workout entry" needs a real delete on every
# layer (chat, the app API, the data layer); otherwise a mis-logged workout
# is permanent. The parsing
# and the "whose workout?" rule live in puffpai.fitfam_access; this is the hook.
#
# Two things this fastpath will NOT do: guess whose slice to write to (it asks,
# and remembers the question for one turn), and put a metric in the reply (the
# confirmation names the workout title and nothing else).

def _fit_delete_reply(ad, key, users, title, last):
    """Run one delete and turn its result into a value-free sentence."""
    from puffpai import fitfam_access as fa
    result = ad.fit_delete_entry(key, title=title, last=last)
    if not isinstance(result, dict):                       # pragma: no cover
        return None
    if result.get('ok'):
        fa.clear_pending()
        who = result.get('name') or key
        return f"Deleted {who}'s \"{result.get('removed')}\" entry."
    reason = result.get('reason')
    if reason == 'ambiguous':
        cands = result.get('candidates') or []
        fa.set_pending('title', user=key, candidates=cands)
        listed = ", ".join(f'"{c}"' for c in cands)
        return (f"I found more than one match — {listed}. "
                "Which one should I delete?")
    if reason == 'no_match':
        return (f"I couldn't find a workout called \"{title}\" in "
                f"{users.get(key, {}).get('name') or key}'s history.")
    if reason == 'empty':
        return (f"{users.get(key, {}).get('name') or key} has nothing logged, "
                "so there's nothing to delete.")
    return fa.whose_workout(result.get('users') or list(users.keys()))


def _try_fitness_delete(user_message: str) -> "str | None":
    """Delete or undo ONE logged FitFam workout, or decline and fall through."""
    text = (user_message or "").strip()
    if not text or len(text) > 160:
        return None
    try:
        from puffpai import fitfam_access as fa
        # Parse BEFORE touching app data: this runs on every chat turn, and
        # the overwhelming majority of them are not a FitFam delete.
        pending = fa.peek_pending()
        answering = bool(pending) and len(text) <= 60
        parsed = fa.parse_delete(text)
        if parsed is None and not answering:
            return None

        ad = _get_app_data()
        users = (ad.get_data('fitfam') or {}).get('users') or {}

        # 1. An answer to the question we asked on the previous turn.
        if answering:
            if pending.get('kind') == 'user':
                key, _cands = fa.resolve_user(users, text)
                if key:
                    fa.clear_pending()
                    return _fit_delete_reply(
                        ad, key, users, pending.get('title'),
                        pending.get('last', True))
            elif pending.get('kind') == 'title':
                for cand in pending.get('candidates') or []:
                    if fa.norm_title(cand) == fa.norm_title(text):
                        fa.clear_pending()
                        return _fit_delete_reply(
                            ad, pending.get('user'), users, cand, False)

        # 2. A fresh delete/undo request.
        if not parsed:
            return None
        title = parsed.get('title')
        by_title = parsed['scope'] == 'title' and bool(title)
        strict = bool(parsed.get('needs_title_proof'))

        # 3. Whose slice? Named person wins; otherwise the entry itself, or
        #    whoever just logged something. Never "the first user in the file".
        key = None
        if parsed.get('user'):
            key, _cands = fa.resolve_user(users, parsed['user'])
            if not key:
                fa.set_pending('user', title=title if by_title else None,
                               last=not by_title)
                return fa.whose_workout(users.keys())
        elif by_title:
            owners = [u for u in users
                      if fa.find_by_title((users[u] or {}).get('history'),
                                          title, strict=strict)]
            if len(owners) == 1:
                key = owners[0]
            elif not owners:
                if strict:
                    # The title was the only evidence this was about FitFam.
                    return None
                return (f"I couldn't find a workout called \"{title}\" "
                        "in anyone's history.")
            else:
                fa.set_pending('user', title=title, last=False)
                return fa.whose_workout(users.keys())
        else:
            key = fa.recent_logger(users)
            if not key:
                if parsed.get('bare_undo'):
                    # A bare "undo that" with no recent workout is not ours.
                    return None
                fa.set_pending('user', title=None, last=True)
                return fa.whose_workout(users.keys())

        print("[Chat] Capability write: fitfam_delete_entry")
        return _fit_delete_reply(ad, key, users, title if by_title else None,
                                 not by_title)
    except Exception as exc:
        logger.debug("fitfam delete fastpath error: %s", exc)
        return None


# ── Trivia / quiz ────────────────────────────────────────────────────────────
# "give me a trivia question" routes cleanly; "lets play a quiz" would fall
# through to RAG and cite a Wikipedia page about a quiz video game. Same
# intent, so both are declared here.
_TRIVIA_START_RE = re.compile(
    r"(?i)\b(?:lets|let us)\s+play\s+(?:a\s+|some\s+)?(?:quiz|trivia)"
    r"|\bplay\s+(?:a\s+|some\s+)?(?:quiz|trivia)\b"
    r"|\bquiz\s+me\b|\btrivia\s+(?:question|time|round)\b"
    r"|\b(?:give|ask)\s+me\s+(?:a\s+|another\s+)?(?:trivia|quiz)\b"
    r"|\bask\s+me\s+a\s+(?:trivia\s+)?question\b"
    r"|\btest\s+me\b")
_TRIVIA_CATEGORY_RE = re.compile(
    r"(?i)\b(?:about|on)\s+(science|history|geography|movies|music|sports|"
    r"technology|nature|literature)\b")
_TRIVIA_BLOCK_RE = re.compile(r"(?i)\b(?:stats|score|streak|how many)\b")


def _trivia_bank_question(category: str = "random"):
    """The bundled question bank, resolved through the shared tool cache."""
    tool = _get_assistant_tools().tool_dict.get('app_trivia_question')
    return tool.invoke(category) if tool is not None else None


def _trivia_generated_question(topic: str, difficulty: str = "medium",
                               audience: str = ""):
    """The topic-aware writer — the GATED local model path, never :11434 raw."""
    tool = _get_assistant_tools().tool_dict.get('app_trivia_generate')
    if tool is None:
        return None
    return tool.invoke({'topic': topic, 'difficulty': difficulty,
                        'grade_level': audience})


def _try_trivia_start(user_message: str) -> "str | None":
    """Serve a trivia turn from the persisted game, never from RAG.

    Was a one-shot "fetch a question" fastpath that returned the tool's raw
    scaffolding (answer key included) and kept no state, so a wrong answer got
    no feedback, "what's my score" was improvised, and a requested topic was
    dropped. :mod:`puffpai.trivia_game` owns the round now — start, grade,
    score, history, difficulty and stop — and persists it to the trivia app
    data. Returns ``None`` for anything that isn't a trivia turn, so the
    decline corpus ("trivia night is tomorrow") falls through untouched.
    """
    if not _app_installed('trivia'):
        return None
    text = (user_message or "").strip()
    if not text:
        return None
    try:
        from puffpai import trivia_game
    except Exception as exc:
        logger.debug("trivia module unavailable: %s", exc)
        return None
    # The unavailability sentence is an answer to a question ABOUT trivia, not
    # a reply to every sentence the household says. Checked after the utterance
    # names the game, which matters because an appliance with no model
    # answers the requirement probe False instead of None.
    if trivia_game.claims(text):
        unavailable = _app_unavailable_reason('trivia')
        if unavailable:
            return unavailable
    try:
        reply = trivia_game.handle(
            text,
            ask_bank=_trivia_bank_question,
            ask_generate=_trivia_generated_question)
    except _app_data_corrupt_class():
        # Say what happened. The alternative — falling through with the
        # default shape — answers "you have no scores" about a file we could
        # not read, and the next write makes that true.
        return ("I can't read the trivia file right now, so I can't start a "
                "round or tell you a score. Nothing was changed.")
    except Exception as exc:
        logger.debug("trivia turn error: %s", exc)
        return None
    if not reply:
        return None
    print("[Chat] Capability read: learning.trivia")
    return reply


# ── Reading a capability out of the registry ─────────────────────────────────
# `utility.registry_read` is unreachable from natural phrasing on its own:
# "can you look up what the bills capability does" would get "I ran a quick
# search ... on the web, but nothing relevant came up" — a false claim of a web
# search (egress is off) about a capability that is right there in the
# registry. The registry is a local, declarative table; answering from it needs
# no tool bridge and no model.
_CAPLOOKUP_SUBJECT_RES = (
    re.compile(r"(?i)\bwhat\s+tools?\s+(?:do\s+you\s+have|are\s+there|"
               r"have\s+you\s+got)\s+for\s+(?P<q>[a-z0-9 '\-]{2,40})"),
    re.compile(r"(?i)\bregistry\s+entry\s+for\s+(?:the\s+)?(?P<q>[a-z0-9 '\-]{2,40})"),
    re.compile(r"(?i)\bwhat\s+(?:the\s+|does\s+the\s+)?(?P<q>[a-z0-9 '\-]{2,40}?)"
               r"\s+capability\s+(?:does|is|can\s+do)\b"),
    re.compile(r"(?i)\bthe\s+(?P<q>[a-z0-9 '\-]{2,40}?)\s+capability\b"),
)


def _try_capability_lookup(user_message: str) -> "str | None":
    """Answer "what does the <X> capability do" from the declared registry."""
    text = (user_message or "").strip()
    if not text or len(text) > 160:
        return None
    subject = ""
    for pattern in _CAPLOOKUP_SUBJECT_RES:
        found = pattern.search(text)
        if found:
            subject = (found.group('q') or "").strip(" .?!,'\"")
            break
    if not subject:
        return None
    try:
        from puffpai import capability_registry as _reg
        cap = _reg.find(subject)
    except Exception as exc:
        logger.debug("capability lookup error: %s", exc)
        return None
    if cap is None:
        return (f'I don\'t have a capability registered for "{subject}". '
                'Ask me "what can you do" for the full list — I am reading '
                'my own registry, not searching the web.')
    tools = ", ".join(cap.all_tools) or "(none)"
    print(f"[Chat] Capability read: registry_read -> {cap.id}")
    # The door-aware source string: the same read must not name a source whose
    # door is shut.
    source = getattr(_reg, "live_data_source", lambda c: c.data_source)(cap)
    parts = [f"{cap.label} ({cap.id}) — {source}.",
             f"Access: {cap.access}. Tools: {tools}."]
    try:
        reach_line = _reg.reach(cap.id)
    except Exception:
        reach_line = ""
    if reach_line:
        parts.append(reach_line)
    if cap.note:
        parts.append(str(cap.note))
    return " ".join(parts)


# ── A document reference that names a real upload ────────────────────────────
# "can you read the Lease Agreement document and convert it for me" must not
# get "I couldn't locate the file you mentioned" about a file that RAG cites
# by name as a user_upload source in the same session.
# document_convert resolves paths in the toolsmith WORKSPACE; the household's
# documents live in the ingestion manifest. puffpai.document_lookup resolves
# the reference against that manifest — and when it genuinely has no match, it
# says so and names what it does have.
_DOCREF_RE = re.compile(
    r"(?i)\b(?:read|open|convert|summarize|summarise|show me|pull up)\b"
    r"[^.?!]{0,20}?\b(?:the\s+|my\s+|our\s+)?(?P<q>[A-Za-z0-9 ._'\-]{3,60}?)\s+"
    r"(?:document|file|doc|docx|spreadsheet|pdf|upload)\b")

#: Bare determiners/quantifiers that mean this is a LIST question
#: ("show me my documents"), which list_my_documents already owns.
_DOCREF_BARE = {
    "my", "a", "an", "the", "any", "some", "this", "that", "each", "all",
    "another", "every", "his", "her", "their", "your", "our", "me my",
    "me the", "me a", "up my", "up the",
}

# The same reference without the "... document" tail. "what does the lease
# agreement say" is a natural way to ask about an upload, and general RAG
# would answer it out of the encyclopedias. A named
# document goes to the named document or to an honest miss, never to RAG.
_DOCREF_ASK_RE = (
    re.compile(
        r"(?i)\bwhat\s+(?:does|did|do)\s+(?:the\s+|my\s+|our\s+)?"
        r"(?P<q>[A-Za-z0-9 ._'\-]{3,60}?)\s+"
        r"(?:say|says|said|contain|contains|tell)\b"),
    re.compile(
        r"(?i)\bwhat(?:'s|s|\s+is|\s+was)\s+(?:in|inside)\s+"
        r"(?:the\s+|my\s+|our\s+)?"
        r"(?P<q>[A-Za-z0-9 ._'\-]{3,60}?)\s*[.?!]?$"),
)

#: A reference whose HEAD is a generic document noun is a LIST question
#: ("what's in the document I sent you"), which list_my_documents owns.
_DOCREF_GENERIC_HEAD = {
    "document", "documents", "doc", "docs", "file", "files", "upload",
    "uploads", "attachment", "attachments", "paper", "papers",
}


# -- Over-capture guard -------------------------------------------------------
# _DOCREF_ASK_RE exists for "what does the lease agreement say", but
# "what's in X" is how the household asks about EVERYTHING: unguarded, "What's
# in the news today?" and "what is in the pantry" would both be answered
# *'I don't have a document called "news today"'*. The head-noun exclusion is
# not a gate on its own: it only catches "the document I sent you".
#
# So the ask patterns have to EARN the turn. Either the phrase names a
# document in so many words (a), or it names a file the appliance really holds (b);
# and a household noun (c) declines outright, as a backstop under both.
# Declining means returning None, which is what lets "what is in the pantry"
# reach _try_household_read and "what's in the news today" reach the news
# fastpath - both of which sit downstream of this function.
_DOCREF_DOC_WORD_RE = re.compile(
    r"(?i)\b(?:documents?|docs?|files?|pdfs?|docx|sheets?|spreadsheets?|"
    r"notes?|uploads?|uploaded|attachments?|papers?|reports?|manuals?|"
    r"guides?)\b"
    r"|\b(?:the\s+thing|what)\s+i\s+sent\b"
    r"|\brecipe\s+i\s+sent\b")

#: Household nouns that "what's in ..." asks about far more often than any
#: file. Each of these has its own hook downstream (pantry/list reads, the
#: news and weather fastpaths, the vault, the library).
_DOCREF_HOUSEHOLD_NOUNS = {
    "news", "headlines", "headline", "pantry", "fridge", "refrigerator",
    "freezer", "kitchen", "cupboard", "cupboards", "list", "lists",
    "calendar", "schedule", "vault", "house", "home", "garage", "oven",
    "air", "weather", "forecast", "library", "network", "dashboard",
    "inbox", "queue", "basket", "cart", "car", "mail", "mailbox", "wallet",
    "box",
}
_DOCREF_HOUSEHOLD_PHRASES = ("shopping list", "knowledge base", "grocery list")

#: Words that carry no identity, so they never count toward the two-token
#: overlap that makes a phrase a filename match.
_DOCREF_STOPWORDS = {
    "the", "a", "an", "my", "our", "your", "his", "her", "their", "of",
    "and", "or", "in", "on", "for", "to", "from", "with", "is", "it",
    "that", "this", "docx", "pdf", "txt", "doc", "xlsx", "csv", "md",
}

_DOCREF_NAMES_TTL = 30.0
_DOCREF_NAMES_CACHE = (0.0, ())


def _docref_tokens(text: str) -> set:
    return {w for w in re.split(r"[^a-z0-9]+", str(text or "").lower())
            if w and w not in _DOCREF_STOPWORDS}


def _docref_upload_names() -> tuple:
    """(normalized stem, token set) for every real upload. Cached ~30s.

    Read through puffpai.upload_index so this can never drift from what the
    listing, the retrieval and document_lookup read.
    """
    global _DOCREF_NAMES_CACHE
    now = time.monotonic()
    cached_at, cached = _DOCREF_NAMES_CACHE
    if cached and (now - cached_at) < _DOCREF_NAMES_TTL:
        return cached
    try:
        from puffpai.upload_index import all_uploaded_docs
        docs = all_uploaded_docs() or []
    except Exception as exc:
        logger.debug("docref name cache error: %s", exc)
        return ()
    rows = []
    for doc in docs:
        if not isinstance(doc, dict):
            continue
        name = str(doc.get("filename") or "")
        if not name:
            continue
        stem = os.path.splitext(name)[0]
        rows.append((re.sub(r"[^a-z0-9]+", " ", stem.lower()).strip(),
                     _docref_tokens(stem)))
    result = tuple(rows)
    _DOCREF_NAMES_CACHE = (now, result)
    return result


def _docref_names_an_upload(reference: str) -> bool:
    """True when *reference* names a file this box actually holds."""
    key = re.sub(r"[^a-z0-9]+", " ", str(reference or "").lower()).strip()
    if not key:
        return False
    tokens = _docref_tokens(reference)
    for stem_key, stem_tokens in _docref_upload_names():
        if stem_key and stem_key == key:
            return True
        if len(tokens & stem_tokens) >= 2:
            return True
    return False


def _docref_is_household(reference: str) -> bool:
    """True when the phrase names a household surface, not a document."""
    flat = re.sub(r"[^a-z0-9]+", " ", str(reference or "").lower()).strip()
    padded = " " + flat + " "
    if any(" " + phrase + " " in padded for phrase in _DOCREF_HOUSEHOLD_PHRASES):
        return True
    return bool(set(flat.split()) & _DOCREF_HOUSEHOLD_NOUNS)


def _try_document_read(user_message: str) -> "str | None":
    """Resolve a named document against the upload manifest, honestly."""
    text = (user_message or "").strip()
    if not text or len(text) > 200:
        return None
    found = _DOCREF_RE.search(text)
    if not found:
        for pattern in _DOCREF_ASK_RE:
            found = pattern.search(text)
            if found:
                break
    if not found:
        return None
    reference = (found.group('q') or "").strip(" .?!,'\"")
    if not reference or reference.lower() in _DOCREF_BARE:
        return None
    # The head noun is read through the punctuation. ASR writes the live
    # sentence "tell me what's in the document. i just let you" (for "... I
    # just sent you") with a full stop mid-phrase, so the captured object is
    # "document. i just let you" and a plain .split() head was "document." -
    # not the generic noun, so the turn was claimed and the reply was "I don't
    # have a document by that name." A generic head with a clause after it is
    # still the LIST question, whatever the punctuation between them.
    head_words = [w for w in re.split(r"[^a-z0-9]+", reference.lower()) if w]
    head = head_words[0] if head_words else ""
    if head in _DOCREF_GENERIC_HEAD:
        return None
    # Earn the turn: the phrase says "document" (in the ask, or in the
    # _DOCREF_RE tail it matched), or it names a file we really have.
    span = found.group(0)
    if not (_DOCREF_DOC_WORD_RE.search(span)
            or _DOCREF_DOC_WORD_RE.search(reference)
            or _docref_names_an_upload(reference)):
        return None
    # Backstop: a household noun goes to its own hook, unless the phrase is
    # literally the name of an upload ("what's in Pantry Inventory.docx").
    if (_docref_is_household(reference)
            and not _docref_names_an_upload(reference)):
        return None
    try:
        from puffpai import document_lookup
        entry = document_lookup.resolve(reference)
    except Exception as exc:
        logger.debug("document lookup error: %s", exc)
        return None
    if entry is None:
        # The miss NEVER recites filenames. Spoken aloud, an upload list is
        # the household's own names, health words and employer documents read
        # out to whoever is in the room - possibly in answer to a question
        # that was not about documents at all. Names
        # belong to the explicit list question (list_my_documents).
        try:
            titles = document_lookup.known_titles(1)
        except Exception:
            titles = []
        if not titles:
            return ("I don't have a document by that name - nothing has been "
                    "uploaded to me yet.")
        return ("I don't have a document by that name. Ask me to list your "
                "documents if you want to hear what's there.")
    try:
        body = document_lookup.text_of(entry)
    except Exception:
        body = ""
    print(f"[Chat] Capability read: document_lookup -> {entry.get('id')}")
    header = (f"{entry['filename']} — {entry.get('classification', 'document')}"
              f", {entry.get('word_count', 0)} words, uploaded "
              f"{str(entry.get('indexed_at') or '')[:10]}.")
    if not body:
        return (header + " I have it indexed but no readable text was "
                         "extracted from it, so there is nothing to read out.")
    return _summarize_tool_result(user_message, header + "\n\n" + body)


# ── Library-title fastpaths ──────────────────────────────────────────────────
#
# WHY. Left to RAG, a question naming a real TITLE or AUTHOR is answered from
# the encyclopedia instead of the library that actually holds it: "show me
# Casablanca" returns a Wikipedia plot summary (and, with "on the tv",
# an unrelated dashboard widget); "do we have Back to the Future" answers from
# an unrelated uploaded document; "do we have any Jane Austen books" invents
# Libby/Gutenberg lending; "what playlists do I have saved" dumps the whole HA inventory.
# GENRE search works, so the data path is fine; only the ROUTING is at
# stake, exactly like the reads _try_capability_read exists for.
#
# These two fastpaths sit in the pre-team deterministic layer so the library is
# consulted BEFORE the router, the planner, the greedy list_devices resolver and
# RAG. Resolution itself lives in puffpai.media_library, which never answers
# from the model: a miss says "I don't have <title>" and offers the closest
# titles the library really holds, and an unreachable server says so.
#
# DELIBERATELY CONSERVATIVE. Both decline (return None) rather than claim a turn
# whenever the ask is a quantifier/genre browse ("play some horror movies"),
# names one of the household's own pages, or is a pantry/knowledge question, those keep
# their existing paths untouched.

_MEDIALIB_QUANT_RE = re.compile(
    r'\b(some|any|a few|another|anything|something|more|all)\b', re.IGNORECASE)
_MEDIALIB_MOVIE_NOUN_RE = re.compile(
    r'\b(movies?|films?|flicks?|jellyfin|media server|library)\b', re.IGNORECASE)
_MEDIALIB_SCREEN_TAIL_RE = re.compile(
    r'\b(?:on|to|onto|up on)\s+(?:the\s+|my\s+|our\s+)?'
    r'(?:tv|telly|television|screen|big screen|dashboard|display|kiosk|monitor)\b.*$',
    re.IGNORECASE)
_MEDIALIB_LEAD_STRIP_RE = re.compile(
    r'^(?:me|us|my|our|the|a|an|that|this)\s+', re.IGNORECASE)
_MEDIALIB_MOVIE_WORD_RE = re.compile(
    r'^(?:the\s+)?(?:movie|film|flick)\s+', re.IGNORECASE)
# "show me the TED talk about X" / "show me the wikipedia page on Y" are the
# knowledge shelves' own asks — never a library title.
_MEDIALIB_KNOWLEDGE_RE = re.compile(
    r'\b(ted\s*talk|wikipedia|wiki|article|lecture|encyclopedia|weather|forecast|'
    r'schedule|calendar|recipe|email|inbox|camera|thermostat|temperature|news|'
    r'photos?|pictures?|documents?|receipts?)\b', re.IGNORECASE)
# Household stock questions share "do we have" with library questions.
_MEDIALIB_PANTRY_RE = re.compile(
    r'\b(pantry|fridge|freezer|grocer\w*|shopping|supplies|stock|milk|eggs|'
    r'bread|butter|cheese|coffee|sugar|flour|batteries|toilet paper|'
    r'medicine|water)\b', re.IGNORECASE)
_MEDIALIB_GENRE_ONLY = {
    "action", "adventure", "animation", "anime", "comedy", "comedies", "crime",
    "documentary", "documentaries", "drama", "dramas", "family", "fantasy",
    "history", "historical", "horror", "musical", "mystery", "romance",
    "romantic", "romcom", "rom com", "sci fi", "scifi", "sci-fi",
    "science fiction", "thriller", "thrillers", "war", "western", "westerns",
    "good", "new", "old", "funny", "scary",
}


def _medialib_candidate_title(body: str) -> str | None:
    """Clean a spoken fragment down to a TITLE, or None if it is not one.

    Declines quantifier/genre browses, empty leftovers, and anything long
    enough to be a sentence rather than a title.
    """
    text = (body or "").strip().strip("?.!,")
    if not text:
        return None
    text = _MEDIALIB_SCREEN_TAIL_RE.sub(" ", text).strip(" ,.?!")
    text = _MEDIALIB_MOVIE_WORD_RE.sub("", text).strip()
    text = _MEDIALIB_LEAD_STRIP_RE.sub("", text).strip()
    text = re.sub(r'\b(please|for me|right now)\b', ' ', text, flags=re.I)
    text = re.sub(r'\b(movies?|films?|flicks?)\b\s*$', ' ', text, flags=re.I)
    text = " ".join(text.split()).strip(" ,.?!")
    if not text or len(text) > 70:
        return None
    words = text.split()
    if len(words) > 9:
        return None
    if _MEDIALIB_QUANT_RE.search(text):
        return None
    if text.lower() in _MEDIALIB_GENRE_ONLY:
        return None
    if all(w.lower() in _MEDIALIB_GENRE_ONLY for w in words):
        return None
    return text


def _try_media_show(user_message: str) -> str | None:
    """"Show me <real movie title>" → resolve it against the Jellyfin library
    and queue the show-me viewer payload.

    Runs BEFORE _try_show so a library title is not swallowed by the knowledge
    shelves. Declines whenever the ask is not a title, so every other "show me"
    keeps its existing path.
    """
    text = (user_message or "").strip()
    low = text.lower()
    if not text or _SHOW_HIDE_RE.search(low):
        return None
    framed = bool(_MEDIALIB_MOVIE_NOUN_RE.search(low))
    m = _SHOW_VERB_RE.search(text)
    if not m:
        # "play the movie X" / "put on the film Y" — a VISUAL play is a library
        # request, never a radio one.
        if not (framed and _MEDIA_VERB_RE.search(text)
                and _MEDIA_VISUAL_RE.search(low)):
            return None
        m = _MEDIA_VERB_RE.search(text)
    if _MEDIALIB_KNOWLEDGE_RE.search(low) and not framed:
        return None
    try:
        from puffpai.books import show as _books_show
        if not framed and _books_show.is_book_ask(low):
            return None        # "show me the comic X" is the librarian's, not
    except Exception:          # Jellyfin's (books/show.py owns that tie-break)
        pass
    body = text[m.end():]
    title = _medialib_candidate_title(body)
    if not title:
        return None
    try:
        from puffpai import dashboard_display as dd
        if not framed and dd.resolve_app_page(title):
            return None            # "pull up my calendar" keeps its own path
        if not framed and dd.classify_source(title) in ("vault", "documents"):
            return None            # never race the vault / uploads flows
    except Exception:
        pass
    try:
        from puffpai import media_library as ml
        found = ml.find_movie(title)
        if found["status"] == "match":
            return ml.show_movie(found["match"], source="voice")
        if not framed:
            return None            # not a library title — let the shelves try
        if found["status"] == "unavailable":
            return ml.LIBRARY_UNAVAILABLE_MSG
        return ml.movie_not_found_reply(title, found["candidates"])
    except Exception as exc:
        logger.warning("media show fastpath error: %s", exc)
        return None


_MEDIALIB_HAVE_RE = re.compile(
    r'\b(?:do|does)\s+(?:we|i|you)\s+(?:have|own)\s+(?P<q>[^?.!]+)'
    r'|\b(?:is|are)\s+(?P<q2>[^?.!]+?)\s+(?:in|on)\s+'
    r'(?:my|our|the)\s+(?:library|collection|media server|jellyfin)\b',
    re.IGNORECASE)
_MEDIALIB_BOOK_NOUN_RE = re.compile(
    r'\b(books?|novels?|audiobooks?|e-?books?)\b', re.IGNORECASE)
_MEDIALIB_BOOK_BY_RE = re.compile(
    r'\bby\s+(?P<a>[A-Za-z][A-Za-z.\'\-]*(?:\s+[A-Za-z][A-Za-z.\'\-]*){0,3})\s*[?.!]*$',
    re.IGNORECASE)
_MEDIALIB_BOOK_PRE_RE = re.compile(
    r'\b(?:any|some|all|the|more|got)\s+(?P<a>[A-Za-z][A-Za-z.\'\-]*'
    r'(?:\s+[A-Za-z][A-Za-z.\'\-]*){0,3})\s+'
    r'(?:books?|novels?|audiobooks?|e-?books?)\b', re.IGNORECASE)
_MEDIALIB_PLAYLIST_RE = re.compile(
    r'\b(?:what|which|how many|list|show|do i have|do we have|any)\b[^.?!]*'
    r'\bplaylists?\b|\bmy\s+playlists?\b', re.IGNORECASE)
_MEDIALIB_PLAYLIST_WRITE_RE = re.compile(
    r'\b(play|start|shuffle|queue|resume|add|create|make|new|delete|remove|'
    r'rename|save)\b', re.IGNORECASE)
_MEDIALIB_BOOK_ASK_RE = re.compile(
    r'\b(?:do|does)\s+(?:we|i|you)\s+(?:have|own)\b[^.?!]*'
    r'\b(?:books?|novels?|audiobooks?|e-?books?)\b'
    r'|\b(?:any|what|which|how many|list|show)\b[^.?!]*'
    r'\b(?:books?|novels?|audiobooks?|e-?books?)\b'
    r'|\b(?:books?|novels?|audiobooks?)\b[^.?!]*\bby\b', re.IGNORECASE)


def _try_media_library_query(user_message: str) -> str | None:
    """Library INVENTORY questions answered from the library, never the model.

    Three shapes, in order: saved playlists, the book catalogue, and a
    direct movie-title lookup. Anything else
    falls through untouched.
    """
    text = (user_message or "").strip()
    low = text.lower()
    if not text or len(text) > 200:
        return None
    try:
        from puffpai import media_library as ml
    except Exception:
        return None

    # 1. Saved playlists — the read that was dumping the whole HA inventory.
    if _MEDIALIB_PLAYLIST_RE.search(low) \
            and not _MEDIALIB_PLAYLIST_WRITE_RE.search(low):
        try:
            return ml.playlists_reply(ml.collect_playlists())
        except Exception as exc:
            logger.warning("playlist read fastpath error: %s", exc)
            return None

    # 2. Books — the real Calibre catalogue or an honest "can't reach it".
    if _MEDIALIB_BOOK_NOUN_RE.search(low) and _MEDIALIB_BOOK_ASK_RE.search(low):
        who, by_author = "", True
        mb = _MEDIALIB_BOOK_BY_RE.search(text)
        if mb:
            who = mb.group("a").strip()
        else:
            mp = _MEDIALIB_BOOK_PRE_RE.search(text)
            if mp:
                who = mp.group("a").strip()
                by_author = bool(re.search(r'[A-Z]', who)) or len(who.split()) > 1
        if not who:
            return None
        try:
            found = ml.find_books(author=who if by_author else "",
                                  query="" if by_author else who)
            if found["status"] == "unavailable":
                return ml.BOOKS_UNAVAILABLE_MSG
            return ml.books_reply(who, found["items"], by=by_author)
        except Exception as exc:
            logger.warning("book read fastpath error: %s", exc)
            return None

    # 3. A direct movie title — "do we have Back to the Future".
    if _MEDIALIB_PANTRY_RE.search(low) or _MEDIALIB_KNOWLEDGE_RE.search(low):
        return None
    mh = _MEDIALIB_HAVE_RE.search(text)
    if not mh:
        return None
    framed = bool(_MEDIALIB_MOVIE_NOUN_RE.search(low))
    title = _medialib_candidate_title(mh.group("q") or mh.group("q2") or "")
    if not title or (len(title.split()) < 2 and not framed):
        return None
    try:
        found = ml.find_movie(title)
        if found["status"] == "match":
            return ml.movie_present_reply(found["match"])
        if not framed:
            # An unframed miss might not be about movies at all — leave the
            # turn to the paths that own it rather than denying a title we
            # were never asked about.
            return None
        if found["status"] == "unavailable":
            return ml.LIBRARY_UNAVAILABLE_MSG
        return ml.movie_not_found_reply(title, found["candidates"])
    except Exception as exc:
        logger.warning("media library fastpath error: %s", exc)
        return None


def _try_books(user_message: str, client_id: str = "") -> str | None:
    """The household librarian: find, recommend, shelve, show — from the REAL
    Calibre catalogue and Calibre-web's own shelves.

    Runs AFTER _try_media_library_query so "do we have any Jane Austen
    books" keeps its catalogue answer. Everything it is not sure about
    returns None and the turn carries on untouched; all the phrasing and every
    catalogue call live in :mod:`puffpai.books.librarian`.
    """
    try:
        from puffpai.books import librarian
        return librarian.handle(user_message, client_id=client_id)
    except Exception as exc:
        logger.warning("books fastpath error: %s", exc)
        return None


# ── Registry-driven deterministic READ dispatch ─────────────────────────────
# WHY THIS EXISTS. The concierge planning loop claims any Steward-resolver miss
# (concierge._should_plan) and hands it to the planner's CLOSED catalogue, which
# does not contain the app_*/prep_*/vault_*/media_*/streaming_* READS — so the
# turn would die "Sorry, I couldn't complete that one" or leak the planner's
# scratchpad. Two sibling hazards compound it: "what <noun> do I have" greedily
# matches list_devices (dumping every device), and a router keyword-gap
# drops some reads to RAG, which has no tools at all. In EVERY case the tool
# is already bound (see assistant_tools.py) and the data exists; only the
# ROUTING is at stake.
#
# These reads are fully determined by the words in the request, so — exactly
# like the weather/camera/meal fastpaths above — they are answered here, in the
# pre-team deterministic layer that runs BEFORE the router, the team, and the
# tool-calling brain. That one placement closes all three failure modes at once:
# nothing downstream (planner, RAG, greedy resolver) runs until this layer
# declines. Each tool below is the authority_tool (or a declared read
# also_tool) for its capability in capability_registry.py — the single source
# of truth — cross-checked against the live tool set at call time.
#
# PRECISION CONTRACT. Rules are ordered; the first whose pattern matches (and
# whose exclude does not) wins, so a NARROW intent (supplies EXPIRING) must
# precede the broad inventory read that shares its noun (supplies). Only
# question / inventory phrasings match; write verbs (add/set/log/play/approve/
# unlock/cancel) are excluded and left to their own tools and the agent path.
# The raw tool output is returned as-is: these tools already answer
# conversationally, and a raw return keeps the turn deterministic and fast
# (no summariser round-trip, no small-model tool-call roulette).

def _capread_re(pattern: str):
    return re.compile(pattern, re.IGNORECASE)


#: Leading determiners and partitives, stripped OUTSIDE the pantry capture
#: groups so the tool is handed an item NAME and not a phrase.
#:
#: Stripping only ``any|some|more|enough`` would leave the commonest English
#: determiners inside the capture: "do we have an egg in the fridge" would
#: search the pantry for the literal string "an egg" and answer ``I don't
#: see "an egg" in the pantry`` over twelve real eggs — a DETERMINISTIC false
#: denial, strictly worse than leaving the turn to the model. Same for
#: "a tomato", "the flour", "the milk", "of the rice", "of the eggs".
#:
#: ``{0,2}`` because partitives stack ("any of the rice"). Longest alternatives
#: first: Python alternation is leftmost-first, so ``of the`` must precede
#: ``of``. :meth:`AppData._pantry_term_variants` strips the same list again
#: defensively, for the paths that do not come through this table.
_PANTRY_DET = (r"(?:(?:of\s+the|of\s+our|of\s+my|enough|some|more|any|the|"
               r"our|an|my|of|a)\s+){0,2}")

#: Everything a bare "do we have X" can be about that is NOT pantry stock.
#: Used only by the bare-lookup rule at the END of the table, which
#: is the widest thing in it: every other counted or listed domain, and every
#: idiomatic non-food "have/there is", has to be named here or the bare rule
#: would silently take its turn. The domains that live BELOW this table —
#: bills, medications, lights, the calendar, in
#: :mod:`puffpai.agents.household_reads` — are the reason the first group
#: exists; the rest of the table protects itself by ordering.
_PANTRY_NOT_FOOD_SRC = (
    r"\b(?:events?|appointments?|meetings?|plans?|tasks?|chores?|to-?dos?|"
    r"reminders?|bills?|payments?|invoices?|medications?|meds|medicine|"
    r"pills?|doses?|prescriptions?|alarms?|timers?|cameras?|lights?|lamps?|"
    r"devices?|sensors?|thermostats?|switches?|outlets?|speakers?)\b"
    r"|\b(?:movies?|films?|shows?|episodes?|songs?|albums?|tracks?|stations?|"
    r"books?|photos?|pictures?|documents?|files?|uploads?|recipes?|goals?|"
    r"workouts?|records?|notes?|messages?|emails?|notifications?|"
    r"agents?|apps?|widgets?|guests?|kids?|people|members?|pets?)\b"
    r"|\b(?:supplies|supply|stockpile|emergency|prep|rations?|"
    r"shopping|groceries|grocery|store|market)\b"
    r"|\b(?:time|money|cash|dollars?|budget|luck|options?|ideas?|breath|"
    r"patience|space|room|storage|battery|charge|power|internet|wifi|"
    r"anything|everything|anyone|anybody|someone|somebody|nothing|"
    r"visitors?|company|news|weather|updates?|questions?|problems?|"
    r"issues?|plans|minutes?|seconds?|hours?|days?|weeks?|months?|years?)\b"
    # Household nouns that are not groceries. "Do we have a spare key",
    # "is there a doctor", "do we have hot water" and "do we have a printer"
    # are not pantry questions, and an honest `I don't see "printer" in the
    # pantry` is still a stolen turn.
    r"|\b(?:school|work|class|classes|practice|games?|homework|"
    r"doctors?|dentists?|nurses?|plumbers?|electricians?|babysitters?|"
    r"dogs?|cats?|pets?|cars?|trucks?|printers?|keys?|tools?|"
    r"heat|heating|air\s+conditioning|hot\s+water|signal|service|"
    r"insurance|warrant(?:y|ies)|reservations?|tickets?|passwords?|"
    r"chargers?|cables?|batteries|battery)\b"
    # Any temporal reference makes it a calendar question, not a stock one.
    r"|\b(?:today|tonight|tomorrow|yesterday|weekend|"
    r"this\s+(?:week|weekend|month|morning|afternoon|evening)|"
    r"next\s+(?:week|month|year)|monday|tuesday|wednesday|thursday|"
    r"friday|saturday|sunday)\b"
    r"|\badd\b|\bremove\b|\bbuy\b|\bput\b|\border\b|\bneed\b|\bshould\b"
)

#: (tool_name, match_re, exclude_re|None, needs_query)
#: needs_query True → the captured group ``q``/``q2`` is passed to the tool and a
#: rule that captures nothing is treated as NOT a confident match.
_CAPREAD_RULES = [
    # ── security / vault (state-safe read probes) ──────────────────────
    ("zone3_status", _capread_re(r"\bzone\s*(?:3|three)\b"), None, False),
    ("privacy_scan_network",
     _capread_re(r"\bnetwork\s+scan\b|\bscan\b[^.?!]*\bnetwork\b"
                 r"|\bwho'?s\s+on\s+my\s+network\b"
                 r"|\bunknown\s+devices?\b[^.?!]*\bnetwork\b"
                 r"|\bnetwork\b[^.?!]*\bunknown\s+devices?\b"),
     _capread_re(r"\bwidget\b|\bblock\b|\blockdown\b"), False),
    ("sentinel_list_requests",
     _capread_re(r"\b(?:pending|waiting|awaiting)\b[^.?!]{0,30}\bapprov"
                 r"|\bapprov\w*\b[^.?!]{0,30}\b(?:request|pending|waiting|queue|list)"
                 r"|\bany\s+(?:new\s+)?devices?\b[^.?!]{0,30}\b(?:approv|waiting|pending)"),
     _capread_re(r"\bapprove the\b|\bdeny\b|\ballow it\b|\bgo ahead\b"), False),
    # Lock STATE before contents. "is my vault locked" contains "my vault", so
    # without this ordering vault_list claimed it and answered a different
    # question — and on a populated vault that answer is the inventory of what
    # secrets exist. vault_status names nothing.
    ("vault_status",
     _capread_re(r"\bvault\s+status\b"
                 r"|\bstatus\s+of\s+(?:the\s+|my\s+|our\s+)?vault\b"
                 r"|\bis\s+(?:the|my|our)\s+vault\s+(?:still\s+)?"
                 r"(?:locked|unlocked|open|closed|secure|sealed)\b"),
     _capread_re(r"\bmovie\b|\bfilm\b|\bheist\b|\bin spanish\b|\bprint\b"
                 r"|\bunlock\b"), False),
    ("vault_list",
     _capread_re(r"\b(?:what'?s|what is|what do you have|anything|everything)\b"
                 r"[^.?!]*\bin\b[^.?!]*\bvault\b"
                 r"|\b(?:list|show)\b[^.?!]*\bvault\b|\bmy vault\b"),
     _capread_re(r"\bunlock\b|\bread (?:me|out)\b"
                 r"|\block(?:ed)?\b|\bunlocked\b|\bstatus\b"), False),

    # ── knowledge / documents ──────────────────────────────────────────
    # "what documents do you have" as well as "do I have": left to general
    # RAG it is answered from the ZIM encyclopedia packs instead of the
    # household's own uploads. The appliance's documents ARE the user's
    # uploads.
    ("list_my_documents",
     _capread_re(r"\b(?:what|which|list|show|how many)\b[^.?!]*"
                 r"\b(?:documents?|files?|uploads?|papers?)\b[^.?!]*"
                 r"\b(?:upload|uploaded|sent|shared|have i|do i have"
                 r"|do you have|you got|are there|i've added)\b"
                 r"|\b(?:what|which)\s+documents?\b"
                 r"|\b(?:list|show)\s+(?:me\s+)?my\s+(?:documents?|files?|uploads?)\b"
                 # "tell me what's in the document. i just let you" -
                 # ASR for "...I just sent you", full stop and all. A
                 # generic document noun followed by a clause (or a
                 # sentence break, or nothing) is the LIST question; the
                 # branch above cannot cross the stop ASR inserted.
                 r"|\b(?:what|which)(?:'s|s|\s+is|\s+was)?\s+(?:in|inside)\s+"
                 r"(?:the|this|that|my|our)\s+"
                 r"(?:documents?|files?|uploads?|attachments?|papers?)\s*"
                 r"(?:[.?!,]|$|\b(?:i|you|we|just|sent|let|gave|shared"
                 r"|got|uploaded|attached)\b)"),
     None, False),

    # ── food / pantry / recipes ────────────────────────────────────────
    ("app_list_recipes",
     _capread_re(r"\b(?:what|which|how many)\b[^.?!]*\brecipes?\b[^.?!]*"
                 r"\b(?:do i have|i have|have i|saved|are there|in my)\b"
                 r"|\b(?:list|show)\s+(?:me\s+)?(?:my\s+|all\s+)?recipes?\b"
                 r"|\bmy\s+recipes?\b"),
     _capread_re(r"\bsave\b|\badd\b|\bcreate\b|\bmake me\b"), False),
    # An item LOOKUP, not a browse: narrow, so it sits ahead of the
    # browse rule below. The reader matches item NAMES
    # (AppData._pantry_item_matches), not only the CATEGORY field, and says
    # what it searched on a miss; this rule takes "Do we have rice in the
    # pantry" deterministically so the answer does not depend on the model
    # choosing the right tool.
    ("app_list_pantry",
     _capread_re(r"\b(?:do|does|did)\s+(?:we|i|you)\s+(?:still\s+)?have\s+"
                 + _PANTRY_DET +
                 r"(?P<q>[a-z][a-z' -]{0,28}?)\s*(?:left\s+)?"
                 r"(?:in|on)\s+(?:the\s+|our\s+|my\s+)?"
                 r"(?:pantry|fridge|refrigerator|freezer|kitchen|cupboard|"
                 r"cabinet|shelf|shelves)\b"
                 r"|\b(?:is|are)\s+there\s+" + _PANTRY_DET +
                 r"(?P<q2>[a-z][a-z' -]{0,28}?)\s*(?:left\s+)?"
                 r"(?:in|on)\s+(?:the\s+|our\s+|my\s+)?"
                 r"(?:pantry|fridge|refrigerator|freezer|kitchen|cupboard|"
                 r"cabinet|shelf|shelves)\b"),
     _capread_re(r"\badd\b|\bremove\b|\bbuy\b|\bput\b|\border\b"
                 r"|\bsupplies\b|\bstockpile\b|\bemergency\b|\bprep\b"), True),
    # The same lookup without the room noun. "Are we out of milk" and "how
    # much rice do we have" are stock questions in every household and name
    # no store, so the exclude carries the whole disambiguation: every other
    # domain that gets counted ("how many events do we have") and every
    # idiomatic "out of X" that is not food ("out of time") is vetoed here.
    ("app_list_pantry",
     _capread_re(r"\bhow\s+(?:much|many)\s+" + _PANTRY_DET +
                 r"(?P<q>[a-z][a-z' -]{0,28}?)\s+"
                 r"(?:do|does)\s+(?:we|i|you)\s+have\b"
                 r"|\b(?:are|is)\s+(?:we|i|you)\s+(?:all\s+)?out\s+of\s+"
                 + _PANTRY_DET +
                 r"(?P<q2>[a-z][a-z' -]{0,28}?)\s*[?.!]*\s*\Z"),
     _capread_re(r"\badd\b|\bremove\b|\bbuy\b|\bput\b|\border\b|\bshopping\b"
                 r"|\bstore\b|\bmarket\b"
                 # prep_days_remaining owns "how much food/water do we have"
                 # and app_list_shopping owns the store phrasings. Both sit
                 # BELOW this rule in the table, so they have to be named
                 # here or this rule would silently take their turns.
                 r"|\b(?:food|water|supplies|supply|stockpile|emergency|"
                 r"prep|rations?|canned\s+goods?)\b"
                 r"|\b(?:time|money|cash|dollars?|budget|luck|options?|"
                 r"ideas?|breath|patience|space|room|storage|battery|"
                 r"charge|gas|order|town|reach|control|line|shape|sight|"
                 r"date|excuses?|words?|questions?)\b"
                 r"|\b(?:events?|appointments?|meetings?|tasks?|chores?|"
                 r"reminders?|bills?|medications?|meds|pills?|doses?|"
                 r"prescriptions?|movies?|films?|shows?|episodes?|songs?|"
                 r"albums?|photos?|pictures?|documents?|files?|devices?|"
                 r"lights?|lamps?|alarms?|timers?|recipes?|people|guests?|"
                 r"kids?|members?|days?|hours?|minutes?|weeks?|months?|"
                 r"years?|calories?|steps?|miles?|workouts?|supplies|"
                 r"degrees?|emails?|messages?|notifications?)\b"), True),
    ("app_list_pantry",
     _capread_re(r"\b(?:what'?s in|what is in|show|list|check|see)\b[^.?!]*\bpantry\b"
                 r"|\bpantry\b[^.?!]*\b(?:have|contents|inventory|list)\b"),
     _capread_re(r"\badd\b|\bremove\b|\bused up\b|\bran out\b"), False),
    # The shopping list has a name families do not use. "What do I need from
    # the store" misses the literal words "shopping"/"grocery list", and RAG
    # would INVENT a plausible grocery list, a confidently wrong answer
    # with nothing to distinguish it from a right one. The store /
    # buy / need phrasings are declared here so the real list answers them.
    ("app_list_shopping",
     _capread_re(r"\bshopping list\b|\bgrocery list\b"
                 r"|\b(?:what'?s on|show|list|check|see)\b[^.?!]*\bshopping\b"
                 r"|\b(?:what|anything)\b[^.?!]{0,24}\b(?:do|should)\s+"
                 r"(?:i|we)\s+(?:need|buy|get|pick\s+up|grab)\b"
                 r"|\b(?:what|anything)\b[^.?!]{0,24}\bneed\b[^.?!]{0,24}"
                 r"\b(?:store|market|shop)\b"),
     # "order my groceries" is a COMMAND with its own tool, and the
     # emergency-supplies reads own their own nouns further down this table.
     # "how many items are on the shopping list" is a COUNT, and this tool
     # answers with the whole list; the count then had to be inferred from the
     # prose by whatever read it. household_reads.shopping_status counts the
     # rows and says the number, so the counting phrasings are handed down to
     # it here (the two matchers are deliberately paired: everything this
     # exclude drops, that rule claims).
     _capread_re(r"\badd\b|\bput\b|\bcheck off\b|\bcross off\b"
                 r"|\border\b"
                 r"|\bhow\s+many\b|\bhow\s+much\b"
                 r"|\bsupplies\b|\bstockpile\b|\bemergency\b|\bprep\b"
                 r"|\bwear\b|\bpack\b|\bworkout\b|\bgym\b"), False),

    # ── prep / supplies (specific before general) ──────────────────────
    ("prep_check_expiration",
     _capread_re(r"\bexpir\w*\b[^.?!]*\b(?:suppl|food|water|item|prep|stock|canned)"
                 r"|\b(?:suppl|food|water|item|prep|stock|canned)\w*\b[^.?!]*\bexpir"),
     None, False),
    ("prep_recommendations",
     _capread_re(r"\b(?:supplies?|prep|stock|stockpile)\b[^.?!]*"
                 r"\b(?:missing|do i need|should i (?:buy|get|stock|add)|recommend|low on|short on)\b"
                 r"|\b(?:missing|do i need|recommend)\b[^.?!]*\bsupplies?\b"),
     None, False),
    ("prep_days_remaining",
     _capread_re(r"\bdays?\s+of\s+(?:food|water|supplies)\b"
                 r"|\bhow\s+(?:many\s+days|much\s+food|much\s+water)\b"
                 r"|\b(?:food|water)\s+do\s+we\s+have\b|\benough\s+(?:food|water)\b"),
     None, False),
    ("prep_view_inventory",
     _capread_re(r"\b(?:show|view|list|what'?s in|what do (?:i|we) have)\b[^.?!]*"
                 r"\b(?:emergency\s+)?(?:supplies|inventory|stockpile)\b"
                 r"|\bemergency\s+(?:supplies|inventory|kit)\b|\bmy\s+(?:emergency\s+)?supplies\b"),
     _capread_re(r"\badd\b|\bexpir|\bmissing\b|\brecommend\b"), False),

    # ── fitness (specific before general) ──────────────────────────────
    ("app_personal_records",
     _capread_re(r"\bpersonal records?\b|\bmy prs?\b|\b1rm\b"
                 r"|\bmax(?:imum)?\s+(?:lift|bench|squat|deadlift|press)\b"
                 r"|\bbest\s+(?:lift|bench|squat|deadlift)\b"),
     None, False),
    ("app_list_goals",
     _capread_re(r"\b(?:fitness|workout|training|lifting)\s+goals?\b"
                 r"|\bmy\s+fitness\s+goals?\b"),
     None, False),
    ("app_fitness_status",
     _capread_re(r"\b(?:workout|fitness|training)\s+(?:streak|status)\b|\bstreak\b"
                 r"|\bhow(?:'?s| is|'?re| are)\s+my\s+(?:workout|fitness|training|lifting)\b"
                 r"|\bhow\s+many\s+workouts\b"),
     None, False),
    ("app_generate_workout",
     _capread_re(r"\b(?:give me|make me|generate|create|plan|suggest|build me|what'?s)\b"
                 r"[^.?!]*\bworkout\b"
                 r"|\bworkout\s+for\s+(?:today|me|tomorrow|the day)\b"),
     _capread_re(r"\bstreak\b|\bgoals?\b|\blog\b|\bhistory\b|\bstatus\b"), False),

    # ── streaming ──────────────────────────────────────────────────────
    ("spotify_whats_playing",
     _capread_re(r"\bspotify\b[^.?!]*\b(?:playing|now playing|what'?s on|current)\b"
                 r"|\b(?:playing|now playing|what'?s on|current)\b[^.?!]*\bspotify\b"),
     _capread_re(r"\bplay\s+\w"), False),
    # Radio DISCOVERY. Left to RAG, "what radio stations can i listen to" is
    # answered out of the encyclopedia (ham repeaters, satellite dishes,
    # military listening posts) on an appliance where "play some jazz radio"
    # starts a real station four seconds later. The
    # rule below needs BOTH a radio/station noun AND an availability framing,
    # so the decline corpus's "what is a railway station", "where is the
    # nearest gas station" and "who invented the radio" stay untouched, and
    # the excludes keep the other kinds of station out.
    ("media_radio_stations",
     _capread_re(r"\b(?:what|which)\b[^.?!]{0,40}\b(?:radio\s+)?stations?\b"
                 r"[^.?!]{0,40}\b(?:can i (?:listen|play|tune|get)"
                 r"|do (?:you|we|i) have|have you got|are (?:there|available)"
                 r"|is there|available)\b"
                 r"|\bwhat\s+radio\s+stations?\b"
                 r"|\bwhat\s+(?:radio\s+)?stations?\s+do\s+you\s+have\b"
                 r"|\bwhat\s+radio\s+can\s+i\s+listen\s+to\b"
                 r"|\blist\s+(?:the\s+|your\s+|my\s+)?radio\s+stations?\b"),
     _capread_re(r"\bspotify\b|\bgas\s+station\b|\btrain\s+station\b"
                 r"|\brailway\s+station\b|\bpolice\s+station\b|\bspace\s+station\b"
                 r"|\bbus\s+station\b|\bfire\s+station\b|\bcharging\s+station\b"
                 r"|\bplay\s+\w|\bin\s+spanish\b"), False),
    ("media_sources_overview",
     _capread_re(r"\bwhat can i listen to\b|\bwhat\s+(?:are my|music)\s+(?:options|sources)\b"
                 r"|\bwhat'?s available to (?:listen|play)\b|\bhow can i listen\b"),
     None, False),
    ("media_search_music",
     _capread_re(r"\b(?:music|songs?|albums?|tracks?)\b[^.?!]*\bby\s+(?P<q>[a-z0-9 .'\-]+)"
                 r"|\bby\s+(?P<q2>[a-z0-9 .'\-]+?)\s+(?:music|songs?|albums?)\b"),
     None, True),
    ("media_search_books",
     _capread_re(r"\b(?:audio)?books?\b[^.?!]*\bby\s+(?P<q>[a-z0-9 .'\-]+)"
                 r"|\bby\s+(?P<q2>[a-z0-9 .'\-]+?)\s+(?:audio)?books?\b"),
     None, True),

    # ── cameras / calendar (the greedy-list_devices victims) ───────────
    ("ha_list_cameras",
     _capread_re(r"\b(?:what|which|how many|list|show)\b[^.?!]*\bcameras?\b"),
     _capread_re(r"\bwidget\b|\bdashboard\b|\badd\b|\balert|\bmotion\b|\bsee\b"
                 r"|\bsaw\b|\bactivity\b|\bfeed\b|\bfootage\b|\bsnapshot\b"), False),
    ("app_list_alarms",
     _capread_re(r"\b(?:what|which|how many|list|show)\b[^.?!]*\b(?:timers?|alarms?)\b"
                 r"[^.?!]*\b(?:do i have|i have|going|set|active|running|left|remaining)\b"
                 r"|\b(?:list|show)\s+(?:me\s+)?(?:my\s+|all\s+)?(?:timers?|alarms?)\b"),
     _capread_re(r"\bcancel\b|\bdismiss\b|\bstop\b|\bsnooze\b|\bset\s+(?:a|an|the)\b|\bdelete\b"),
     False),

    # ── calendar write (task completion; a task-noun is required so that a
    #    household member whose first name is also this verb cannot misfire) ──
    ("app_complete_task",
     _capread_re(r"\bmark\s+(?:the\s+|my\s+)?(?P<q>.+?)\s+(?:task|to-?do|reminder|chore)\s+"
                 r"(?:as\s+)?(?:done|complete|completed|finished)\b"
                 r"|\b(?:complete|finish|check off)\s+(?:the\s+|my\s+)?(?P<q2>.+?)\s+"
                 r"(?:task|to-?do|reminder|chore)\b"),
     None, True),

    # ── pantry lookup, bare ────────────────────────────────────────────
    # LAST in the table on purpose. "Do we have rice" and "do we have any
    # eggs" name no room and carry no "how much" frame, so the two
    # lookup rules above never see them and the turn would go to the model,
    # which answers stock questions from memory. This rule is the floor under
    # that, and being last means EVERY other rule above — recipes, shopping,
    # prep, fitness, media, cameras, alarms, task completion — wins its own
    # phrasing before this one is consulted. The exclude then carries the
    # domains that are NOT in this table: the household readers below
    # (bills, medications, lights, calendar) and the idiomatic "have/there
    # is" that is not about food at all.
    #
    # Bounded three ways: the utterance must END here (no trailing clause),
    # the captured name is <= 29 characters, and a one-character capture is
    # rejected downstream by AppData._pantry_term_variants.
    ("app_list_pantry",
     _capread_re(r"\b(?:do|does|did)\s+(?:we|i|you)\s+(?:still\s+)?have\s+"
                 + _PANTRY_DET +
                 r"(?P<q>[a-z][a-z' -]{0,28}?)"
                 r"(?:\s+left)?"
                 r"(?:\s+(?:in|on)\s+(?:the\s+|our\s+|my\s+)?"
                 r"(?:pantry|fridge|refrigerator|freezer|kitchen|cupboard|"
                 r"cabinet|shelf|shelves))?"
                 r"\s*[?.!]*\s*\Z"
                 r"|(?:\b(?:is|are)\s+there\s+|\bgot\s+)" + _PANTRY_DET +
                 r"(?P<q2>[a-z][a-z' -]{0,28}?)"
                 r"(?:\s+left)?"
                 r"(?:\s+(?:in|on)\s+(?:the\s+|our\s+|my\s+)?"
                 r"(?:pantry|fridge|refrigerator|freezer|kitchen|cupboard|"
                 r"cabinet|shelf|shelves))?"
                 r"\s*[?.!]*\s*\Z"),
     _capread_re(_PANTRY_NOT_FOOD_SRC), True),
]


#: An explicit ASK to write code: a write/generate/create/fix/refactor verb
#: followed, in the same sentence, by something that is unmistakably code.
#: Both halves are required — "write down that we need milk" has the verb and
#: no code noun; "what automations do I have" has the noun and no verb.
_CODE_ASK_RE = re.compile(
    r"(?:"
    # Imperative: a write/generate verb followed, in the same sentence, by
    # something that is unmistakably code.
    r"\b(write|writes|generate|create|make|build|code|refactor|rewrite|fix|"
    r"debug)\b[^.?!]{0,80}?\b(script|scripts|function|functions|code|program|"
    r"snippet|regex|regular expression|automation|automations|flow|flows|"
    r"systemd|unit file|python|javascript|typescript|bash|shell script|sql|"
    r"class|module)\b"
    r"|"
    # Non-imperative needs/wants: "I need a small script to rename my photo
    # files", "I want a quick automation for X".
    r"\b(i need|i want|need|want)\b[^.?!]{0,80}?\b(a|an|some)?\s*"
    r"(small|quick|little|simple)?\s*(script|program|function|automation|flow)\b"
    r"|"
    # "help me write/code/script/build ..."
    r"\b(can you |could you |would you )?help me\b[^.?!]{0,60}?\b"
    r"(write|code|script|build)\b"
    r"|"
    # "write/make/build me a script/program/code/function/automation ..."
    r"\b(write|make|build)\s+me\b[^.?!]{0,40}?\b(a|an|some)\b[^.?!]{0,40}?\b"
    r"(script|program|code|function|automation)\b"
    r"|"
    # "how do I write a python/bash/... script/function"
    r"\bhow do i write a\b[^.?!]{0,40}?\b(script|function)\b"
    r")",
    re.IGNORECASE)

#: Household senses of the same words that must never reach the coding model.
#: "the door code" and "a shopping list flow" are not programming requests, and
#: a question ABOUT what exists is a read, not an ask to author something.
_CODE_BLOCK_RE = re.compile(
    r"\b(door code|gate code|alarm code|pin code|zip code|area code|"
    r"promo code|pairing code|write down|write it down|dress code)\b",
    re.IGNORECASE)
_CODE_QUESTION_RE = re.compile(
    r"^\s*(what|which|whats|what's|do i|does|is|are|how many|when|where|who)\b",
    re.IGNORECASE)


def _try_code_request(user_message: str) -> str | None:
    """Deterministic fastpath for "write me a script/function/automation".

    Position (see tests/test_instant_answer_precedence.py): AFTER the household
    WRITES — shopping, meals, tasks, reminders — and after the untargeted
    whole-house gate, because "add oat milk to the shopping list" and "create a
    reminder for 5pm" contain create/add verbs and belong to their own stores.
    BEFORE ``_try_capability_read`` and the registry read, because a coding ask
    that falls through to those is answered with a capability blurb, and one
    that falls through to RAG is answered with invented instructions from a
    library shelf (the failure shape already seen with "tune in to NPR").

    Declines (returns None) when no coding model is configured, so a box
    without one keeps its previous behaviour exactly.
    """
    text = (user_message or "").strip()
    if not text or len(text) < 8:
        return None
    if _CODE_BLOCK_RE.search(text) or _CODE_QUESTION_RE.match(text):
        return None
    if not _CODE_ASK_RE.search(text):
        return None
    from puffpai.inference import code_model
    if not code_model.is_configured():
        # Feature OFF: fall through to the normal chain rather than announce a
        # capability this box does not have.
        return None
    try:
        result = code_model.generate_code(text)
    except Exception as exc:  # pragma: no cover - generate_code is total
        logger.warning("code fastpath failed: %s", exc)
        return None
    if result.error:
        # A configured-but-missing model is ANSWERED here, not fallen through:
        # the paths below would otherwise answer a coding ask from RAG.
        return result.explanation
    if result.unparsed:
        return ("My coding model answered without a code block. This is "
                "exactly what it said:\n\n" + result.explanation)
    print(f"[Chat] Code fastpath -> {result.model} ({result.ms} ms)")
    return result.as_markdown()


def _try_capability_read(user_message: str) -> str | None:
    """Deterministic READ dispatch for the reads the planner would swallow.

    See the block comment above. Returns the tool's own answer, or None to fall
    through to routing/team/brain unchanged. Never raises.
    """
    text = (user_message or "").strip()
    if not text or len(text) > 160:
        return None
    for tool_name, match_re, exclude_re, needs_query in _CAPREAD_RULES:
        m = match_re.search(text)
        if not m:
            continue
        if exclude_re is not None and exclude_re.search(text):
            continue
        # An app-owned read is only a read while the app is installed.
        # Resolving the tool's app id through the registry is what makes a
        # removed or renamed app disappear from the deterministic reads too,
        # instead of answering out of a data file whose app is gone.
        owner_app = app_registry.CORE_TOOL_APPS.get(tool_name)
        if owner_app is not None and not _app_installed(owner_app):
            continue
        arg = ""
        if needs_query:
            raw = ""
            for group in ("q", "q2"):
                if group in match_re.groupindex:
                    try:
                        captured = m.group(group)
                    except (IndexError, re.error):
                        captured = None
                    if captured:
                        raw = captured
                        break
            arg = raw.strip(" .?!,\"'")
            if not arg:
                # A query rule that captured nothing is not a confident match.
                continue
        try:
            tools = _get_assistant_tools()
            tool = tools.tool_dict.get(tool_name)
            if tool is None:
                logger.warning("capability-read: tool %r not bound; skipping",
                               tool_name)
                return None
            result = tool.invoke(arg)
        except Exception as exc:
            logger.debug("capability-read %s failed: %s", tool_name, exc)
            return None
        if result:
            print(f"[Chat] Capability read: {tool_name}")
            # This fastpath dispatches DYNAMICALLY, so it reports its own
            # capability here instead of being resolved from a static table.
            _chat_activity.record_capability(
                _chat_activity.capability_of_tool(tool_name), "fastpath")
            return str(result)
        return None
    return None


# ── Speaker volume fastpath ─────────────────────────────────────────────────
# "turn it up", "turn the radio up", "louder", "set the volume to 40", "mute".
# Without it, "turn up the radio" can get a shrug about pressing a button on
# the receiver, and "turn the volume up" can come back "which thermostat did
# you mean?": the Concierge's LLM intent refinement picks from a menu
# (RESOLVABLE_INTENTS) with no volume entry, so "turn ... up" lands on
# set_climate. This runs ahead of the team for exactly that reason. The durable
# fix is a volume tool in the capability registry; this is the deterministic
# floor under it.
#
# Anything naming another turnable domain (heat, lights, fan) is left alone so
# the climate and light paths keep their own phrasings.
_VOL_BLOCK_RE = re.compile(
    r"\b(heat|heater|heating|thermostat|temp|temperature|degrees?|furnace|"
    r"air\s*condition\w*|a/?c|brightness|bright|dim|dimmer|lights?|lamps?|"
    r"fan|blinds?|shades?|oven|stove)\b", re.IGNORECASE)
_VOL_NOUN_RE = re.compile(
    r"\b(volume|sound|audio|radio|music|song|stereo|speakers?)\b",
    re.IGNORECASE)
_VOL_SET_RE = re.compile(
    r"\bvolume\b[^.?!]{0,20}?\b(?:to|at)\s+(\d{1,3})\b"
    r"|\bset\b[^.?!]{0,20}?\bvolume\b[^.?!]{0,20}?\b(\d{1,3})\b",
    re.IGNORECASE)
_VOL_UP_RE = re.compile(
    r"\b(?:turn|crank|bump|pump|kick)\b[^.?!]{0,24}?\bup\b"
    r"|\bvolume\s+up\b|\bup\s+the\s+volume\b|\blouder\b"
    r"|\braise\b[^.?!]{0,24}?\b(?:volume|sound|music|radio)\b",
    re.IGNORECASE)
_VOL_DOWN_RE = re.compile(
    r"\b(?:turn|crank|bump|knock)\b[^.?!]{0,24}?\bdown\b"
    r"|\bvolume\s+down\b|\bdown\s+the\s+volume\b|\bquieter\b|\bsofter\b"
    r"|\blower\b[^.?!]{0,24}?\b(?:volume|sound|music|radio)\b"
    r"|\bkeep\s+it\s+down\b|\bnot\s+so\s+loud\b", re.IGNORECASE)
# "silence"/"stop" stay with _try_media_stop, which runs first and halts
# playback outright — the more useful reading of those words.
_VOL_MUTE_RE = re.compile(r"\bmute\b", re.IGNORECASE)
_VOL_UNMUTE_RE = re.compile(r"\bun-?mute\b", re.IGNORECASE)
_VOL_MAX_RE = re.compile(
    r"\ball\s+the\s+way\s+up\b|\bmax(?:imum)?\s+volume\b"
    r"|\bfull\s+(?:volume|blast)\b", re.IGNORECASE)
_VOL_READ_RE = re.compile(
    r"\bhow\s+loud\b|\bwhat(?:\'s| is)?\s+(?:the\s+)?volume\b"
    r"|\bvolume\s+level\b", re.IGNORECASE)


def _try_media_volume(user_message: str) -> str | None:
    """Move the appliance speaker volume — deterministic, no model.

    Returns a spoken confirmation, or None when this is not a volume command.
    Never returns None on a *recognised* command that failed: falling through
    would hand it back to the intent classifier that produced the thermostat
    misroute in the first place, so a mixer failure is reported honestly.
    """
    text = (user_message or "").strip().rstrip(".!?")
    low = text.lower()
    if not low or len(low) > 120 or _VOL_BLOCK_RE.search(low):
        return None
    # A bare "turn it up" carries no noun, so accept that form only as a short
    # command; that keeps a long sentence merely containing "up" out of here.
    scoped = bool(_VOL_NOUN_RE.search(low)) or len(low.split()) <= 9

    from puffpai import audio_volume

    unreachable = ("I couldn't reach the speaker mixer just now — "
                   "the audio service may be down.")

    def _say(pct, lead):
        return f"{lead} {pct}%." if pct is not None else unreachable

    # Unmute before mute: "unmute" contains "mute".
    if _VOL_UNMUTE_RE.search(low):
        if not audio_volume.set_mute(False):
            return unreachable
        return _say(audio_volume.get_state()[0], "Sound back on —")
    if _VOL_MUTE_RE.search(low) and scoped:
        return "Muted." if audio_volume.set_mute(True) else unreachable
    if _VOL_READ_RE.search(low):
        pct, muted = audio_volume.get_state()
        if pct is None:
            return unreachable
        return "It's muted." if muted else f"Volume is at {pct}%."

    m = _VOL_SET_RE.search(low)
    if m:
        target = int(next(g for g in m.groups() if g))
        return _say(audio_volume.set_percent(target), "Volume set to")
    if _VOL_MAX_RE.search(low) and scoped:
        return _say(audio_volume.set_percent(100), "All the way up —")
    if _VOL_UP_RE.search(low) and scoped:
        if (audio_volume.get_state()[0] or 0) >= 100:
            return "That's already all the way up."
        return _say(audio_volume.nudge(audio_volume.STEP), "Volume up —")
    if _VOL_DOWN_RE.search(low) and scoped:
        if audio_volume.get_state()[0] == 0:
            return "That's already all the way down."
        return _say(audio_volume.nudge(-audio_volume.STEP), "Volume down —")
    return None


#: Zero-argument read tools, DERIVED from the rules table so the two layers can
#: never disagree about what is safe to invoke. The three arg-capturing rules
#: are excluded deliberately: they need a captured query to mean anything, and
#: one of them (``app_complete_task``) WRITES — it completes the task it is
#: handed — so it must never be reachable from a bare capability match.
_CAPREAD_ZERO_ARG = {
    tool_name: exclude_re
    for tool_name, _match_re, exclude_re, needs_query in _CAPREAD_RULES
    if not needs_query
}

#: READ tools that legitimately appear both as a zero-arg browse rule and as a
#: query-capturing lookup rule. ``app_list_pantry`` answers both "what's in the
#: pantry" (no argument) and "do we have rice in the pantry" (argument), and
#: both readings are read-only.
#:
#: Declared HERE rather than asserted away in the test, because the invariant it
#: relaxes is a real one: the containment test reads "no tool that captures an
#: argument is bare-dispatchable", which is a proxy for "no WRITER is
#: bare-dispatchable" (``app_complete_task`` completes the task it is handed).
#: Anything added to this set must be a read; adding a writer here would be a
#: visible change to the file the guard protects.
_CAPREAD_DUAL_ARITY_READS = frozenset({"app_list_pantry"})

#: Verbs that make a turn an ACTION, not a question. The per-rule excludes state
#: this one capability at a time ("add" for the pantry, "cancel" for alarms);
#: the registry layer can reach a capability with no hand-written rule, so it
#: needs the rule once, generally.
#:
#: The second line is the list a first attempt lacked, and every entry cost a
#: real misfire: "silence my alarm" returned the alarm list, "unblock my laptop"
#: ran a network scan, "grant the tablet access" listed consent requests.
#: ``\bblock\b`` in the existing per-rule excludes does NOT match "unblock".
#:
#: Kept to unambiguous imperatives. "lock" is absent on purpose — "is the vault
#: locked" is a question, and an over-broad guard here would silently re-break
#: the very reads this layer exists to serve.
_CAPREAD_WRITE_INTENT_RE = _capread_re(
    r"\b(?:add|remove|delete|create|save|rename|clear|cancel|dismiss|snooze"
    r"|approve|deny|unlock|schedule|log"
    r"|silence|mute|unblock|grant|authorize|authorise|enable|disable|send|email|text|post|share|print|upload|export|forward|copy|tweet|announce|publish|reset|fix|ignore|stop|remind)\b"
    r"|\bwake\s+me\b|\bpermission\s+to\b|\bgive\s+(?:\w+\s+){1,3}permission\b"
    r"|\bset\s+(?:a|an|the|my)\b|\bturn\s+(?:on|off)\b|\bput\s+\w"
    r"|\bstart\s+(?:spotify|the\s+radio|playing)\b")


def _capread_registry_tool(cap) -> "str | None":
    """The one zero-arg read tool this capability may auto-dispatch, else None.

    Requiring EXACTLY ONE is the disambiguation rule. A capability is coarser
    than its tools: ``pantry.shopping`` owns both ``app_list_shopping`` and
    ``app_list_pantry``, and "what is in the pantry" must not be answered with
    the shopping list. Where a capability owns several read tools only the
    hand-written rules can tell them apart, so this declines and the explicit
    layer keeps those turns.
    """
    tools = [t for t in cap.all_tools if t in _CAPREAD_ZERO_ARG]
    return tools[0] if len(tools) == 1 else None


def _try_registry_read(user_message: str) -> "str | None":
    """READ dispatch driven by the registry's declared ``dispatch_phrases``.

    The rules table above is a hand-maintained trigger list — 25 patterns for a
    registry of 45 capabilities — so its coverage is by PHRASING. "scan my
    network" had a pattern and "what is the network status" did not, so the
    latter fell through to RAG and came back explaining an automotive LIN bus
    out of the offline library. A confident, fluent, wrong answer is worse than
    no answer, and both phrasings name ``security.network``.

    Three things keep the wider trigger honest, and each exists because its
    absence broke something:

    * The trigger is ``dispatch_phrases`` — phrasings declared, one at a time,
      to mean "run this read now". NOT the registry's ``keywords``, which are a
      binding signal: driving dispatch off those answered "tell me a secret"
      with the vault inventory.
    * CONTAINMENT: only a tool the explicit rules already trust as a zero-arg
      read, derived from that table so the two cannot drift apart. Widening the
      trigger therefore cannot widen what a chat message is able to invoke.
    * It runs LAST, behind the action fastpaths, so a turn that is really an
      action cannot be answered with a read even if the guard misses it.

    Never raises; None falls through to routing exactly as before.
    """
    text = (user_message or "").strip()
    if not text or len(text) > 160:
        return None
    if _CAPREAD_WRITE_INTENT_RE.search(text):
        return None
    try:
        from puffpai import capability_registry as _reg
        cap = _reg.find_for_dispatch(text)
    except Exception as exc:
        logger.debug("registry read dispatch unavailable: %s", exc)
        return None
    if cap is None:
        return None
    tool_name = _capread_registry_tool(cap)
    if tool_name is None:
        return None
    exclude_re = _CAPREAD_ZERO_ARG.get(tool_name)
    if exclude_re is not None and exclude_re.search(text):
        return None
    try:
        tools = _get_assistant_tools()
        tool = tools.tool_dict.get(tool_name)
        if tool is None:
            return None
        result = tool.invoke("")
    except Exception as exc:
        logger.debug("registry read %s failed: %s", tool_name, exc)
        return None
    if result:
        print(f"[Chat] Capability read (registry): {cap.id} -> {tool_name}")
        # Registry-dispatched: the row that won is known exactly, so report it
        # rather than letting the static fastpath table guess.
        _chat_activity.record_capability(cap.id, "fastpath")
        return str(result)
    return None


def _try_household_read(user_message: str) -> "str | None":
    """Answer a household question from the real store, or fall through.

    Thin hook; every rule and every reader lives in
    :mod:`puffpai.agents.household_reads` so it can be tested without Flask.
    Never raises.
    """
    try:
        from puffpai.agents import household_reads
        reader = household_reads.match(user_message)
        if reader is None:
            return None
        result = household_reads.answer(user_message)
        if result:
            # Same shape as the other capability-read journal lines, so the
            # route a turn actually took stays greppable in journalctl.
            print(f"[Chat] Household read: {reader}")
        return result
    except Exception as exc:
        logger.debug("household read unavailable: %s", exc)
        return None


# -- Briefing / locks / device count / latest upload / Zigbee fastpaths -------
#
# Each of these is a question with a deterministic answer sitting in a store,
# and each one would otherwise reach a model - with the four worst results this
# appliance can produce: a hung turn (the briefing), a confident essay about
# household wiring in answer to "how many devices can you control", a recital
# of every filename in answer to "what is in the document I just sent you",
# and an iFixit guide to 3-D glasses in answer to "what did you find when
# pairing". No model runs in any of them.

#: "give me my daily briefing", "brief me". A "brief me ON <topic>" is a
#: request about that topic and keeps its own route.
_DAILY_BRIEFING_RE = re.compile(
    r"(?i)\b(?:daily|morning|evening|my|the)\s+briefing\b"
    r"|\bbriefing\b\s*[.?!]*$"
    r"|\bbrief\s+me\b(?!\s+(?:on|about)\b)")

_RAW_HIGH_RE = re.compile(
    r"(?i)\bhigh\s+(?:of\s+|near\s+|around\s+)?(-?\d{1,3})")


def _briefing_weather_numbers():
    """``(current, high)`` from the forecast the weather fastpath already
    reads, or ``(None, None)``. Never raises; never calls a model."""
    try:
        raw = str(_get_assistant_tools().tool_dict['auto_weather_forecast']
                  .invoke('') or "")
    except Exception as exc:
        logger.debug("briefing weather failed: %s", exc)
        return None, None
    temp = None
    match = _RAW_TEMP_RE.search(raw)
    if match:
        try:
            temp = int(match.group(1) or match.group(2))
        except (TypeError, ValueError):
            temp = None
    high = None
    match = _RAW_HIGH_RE.search(raw)
    if match:
        try:
            high = int(match.group(1))
        except (TypeError, ValueError):
            high = None
    return temp, high


def _briefing_today():
    """``(today's occurrences, open task count)``. Best-effort, never raises."""
    occurrences, open_tasks = [], 0
    try:
        app = _get_app_data()
    except Exception as exc:
        logger.debug("briefing app data unavailable: %s", exc)
        return occurrences, open_tasks
    today = datetime.now().date()
    try:
        occurrences = app.cal_occurrences(
            datetime.combine(today, datetime.min.time()),
            datetime.combine(today, datetime.max.time()).replace(
                microsecond=0)) or []
    except Exception as exc:
        logger.debug("briefing occurrences failed: %s", exc)
    try:
        cal = app._load('calendar') or {}
        open_tasks = sum(1 for t in (cal.get('tasks') or [])
                         if str((t or {}).get('status') or '') == 'pending')
    except Exception as exc:
        logger.debug("briefing tasks failed: %s", exc)
    return occurrences, open_tasks


def _try_daily_briefing(user_message: str) -> str | None:
    """The spoken briefing, composed locally in four sentences.

    The briefing ROUTE (``assistant_tools.daily_briefing``) makes eight tool calls
    and then writes the result up with the LLM, which can outlast a 45s
    timeout and greet the household with "Good morning" after midnight.
    This reads the same four facts a person actually wants first thing -
    weather, air quality, today's calendar, open tasks - straight from the
    stores. See :mod:`puffpai.agents.daily_brief` for the composition.
    """
    lower = (user_message or "").lower()
    if len(lower) > 120 or not _DAILY_BRIEFING_RE.search(lower):
        return None
    try:
        from puffpai.agents import daily_brief
    except Exception as exc:                # pragma: no cover - ships with it
        logger.debug("briefing composer unavailable: %s", exc)
        return None
    temp, high = _briefing_weather_numbers()
    env = {}
    try:
        from puffpai import dashboard_widgets as _dwid
        env = _dwid.fetch_environment() or {}
    except Exception as exc:
        logger.debug("briefing air quality failed: %s", exc)
    occurrences, open_tasks = _briefing_today()
    aqi = env.get("us_aqi")
    return daily_brief.compose(
        city=_home_city(),
        temp=temp, high=high,
        aqi=aqi if isinstance(aqi, (int, float)) else None,
        aqi_label=str(env.get("aqi_label") or ""),
        occurrences=occurrences, open_tasks=open_tasks)


#: The domains this appliance can actually operate, and what to call them out
#: loud. Order is the order they are counted in.
_CONTROLLABLE_DOMAINS = (
    ("light", "light", "lights"),
    ("switch", "switch", "switches"),
    ("climate", "thermostat", "thermostats"),
    ("media_player", "media player", "media players"),
    ("script", "script", "scripts"),
    ("cover", "cover", "covers"),
    ("fan", "fan", "fans"),
    ("lock", "lock", "locks"),
)

_DEVICE_COUNT_RE = re.compile(
    r"(?i)\bhow\s+many\s+(?:different\s+|smart\s+|home\s+)?"
    r"(?:devices|things|gadgets)\b"
    r"|\bwhat\s+devices\s+(?:can|do)\s+you\s+(?:control|run|operate)\b"
    r"|\bwhat\s+can\s+you\s+control\b"
    r"|\bhow\s+many\s+devices\b")


def _entities_by_domain():
    """``{domain: [state dict]}`` for every entity HA reports. ``{}`` on any
    failure - an unreachable bridge must not produce a made-up count."""
    try:
        states = _get_ha_bridge().get_all_states() or []
    except Exception as exc:
        logger.debug("device count: HA unreachable: %s", exc)
        return {}
    out: dict = {}
    for raw in states:
        entity_id = str((raw or {}).get("entity_id") or "")
        if "." not in entity_id:
            continue
        out.setdefault(entity_id.split(".", 1)[0], []).append(raw)
    return out


def _try_device_count(user_message: str) -> str | None:
    """"how many devices can you control" is a COUNT, from the bridge.

    Left to the knowledge library it comes back with an essay about household
    wiring and circuit breakers - many seconds of confident, unrelated prose
    about somebody else's house. The number is one read away.
    """
    lower = (user_message or "").lower()
    if len(lower) > 120 or not _DEVICE_COUNT_RE.search(lower):
        return None
    # "how many devices can a 15 amp circuit breaker handle" is an
    # encyclopedia question that happens to open with the same five words.
    # The house question is about ME: it says "you", or it stops at the noun.
    if not (re.search(r"\byou(?:r)?\b", lower)
            or re.search(r"\bdevices\b\s*[.?!]*\s*$", lower)):
        return None
    by_domain = _entities_by_domain()
    if not by_domain:
        return ("I can't reach Home Assistant right now, so I can't count "
                "your devices. That's a missing connection, not a missing "
                "house.")
    parts, total = [], 0
    for domain, singular, plural in _CONTROLLABLE_DOMAINS:
        count = len(by_domain.get(domain) or [])
        if not count:
            continue
        total += count
        parts.append(f"{count} {singular if count == 1 else plural}")
    if not total:
        return ("I can't control anything yet - Home Assistant isn't "
                "reporting any lights, switches, thermostats or media "
                "players to me.")
    thing = "device" if total == 1 else "devices"
    return f"I can control {total} {thing}: " + ", ".join(parts) + "."


_DOORS_LOCKED_RE = re.compile(
    r"(?i)\b(?:are|is|did)\b[^.?!]{0,30}\b(?:doors?|deadbolts?|locks?)\b"
    r"[^.?!]{0,30}\block(?:ed|s)?\b"
    r"|\bdoors?\s+locked\b|\block\s+status\b"
    r"|\bis\s+(?:the\s+)?house\s+locked\s*(?:up)?\b"
    r"|\bare\s+we\s+locked\s+up\b")

#: "lock the front door" is a COMMAND and keeps its own path.
_LOCK_COMMAND_RE = re.compile(r"(?i)^\s*(?:please\s+)?(?:un)?lock\b")


def _try_doors_locked(user_message: str) -> str | None:
    """With no ``lock.*`` entities, say so plainly.

    Otherwise "Are the doors locked?" gets "I couldn't find a device matching
    that. Ask me to list devices..." - the household hears a lookup failure
    and cannot tell whether the door is open. The truth is that the house has
    no smart locks at all, which is a one-sentence answer.
    """
    lower = (user_message or "").lower()
    if len(lower) > 120 or _LOCK_COMMAND_RE.search(lower):
        return None
    if not _DOORS_LOCKED_RE.search(lower):
        return None
    by_domain = _entities_by_domain()
    if not by_domain:
        return ("I can't reach Home Assistant right now, so I can't check "
                "your locks.")
    locks = by_domain.get("lock") or []
    if not locks:
        return "You don't have any door locks set up in Home Assistant."
    locked, unlocked = [], []
    for raw in locks:
        attrs = (raw.get("attributes") or {})
        name = str(attrs.get("friendly_name")
                   or str(raw.get("entity_id") or "").split(".", 1)[-1]
                   .replace("_", " "))
        if str(raw.get("state") or "").lower() == "locked":
            locked.append(name)
        else:
            unlocked.append(name)
    if not unlocked:
        if len(locks) == 1:
            return f"{locked[0]} is locked."
        return f"All {len(locks)} locks are locked: " + ", ".join(locked) + "."
    return (f"{len(unlocked)} of {len(locks)} locks "
            f"{'is' if len(unlocked) == 1 else 'are'} not locked: "
            + ", ".join(unlocked) + ".")


#: "the document I just sent you", "the last file I uploaded". ``let`` is in
#: the verb list because that is what the transcriber writes for "sent" in
#: exactly this sentence (see _try_document_read's own note on the live ASR).
_LATEST_UPLOAD_RE = re.compile(
    # The gap is not sentence-bounded: the transcriber writes "what's in the
    # document. i just let you" for this exact sentence, full stop and all
    # (the same live ASR mangling _try_document_read documents).
    r"(?i)\b(?:document|file|doc|photo|picture|image|pdf|scan|attachment)\b"
    r"[^\n]{0,24}\b(?:i\s+)?(?:just|last|recently)\s+"
    r"(?:sent|send|let|gave|give|uploaded|upload|shared|share|added)\b"
    r"|\b(?:just|last|recently)\s+(?:sent|uploaded|shared)\s+(?:you\s+)?"
    r"(?:a|the|my)?\s*(?:document|file|doc|photo|picture|image|pdf)\b"
    r"|\b(?:most\s+recent|latest|newest|last)\s+"
    r"(?:document|file|doc|upload|attachment)\b"
    # "the last thing I sent you" — the same reference with no noun in it at
    # all, which is how people actually say it.
    r"|\b(?:last|latest|newest|most\s+recent)\s+thing\s+(?:i\s+)?"
    r"(?:sent|send|uploaded|upload|shared|gave|give)\b")

#: How much of an upload is read back when it carries no summary of its own.
_LATEST_UPLOAD_CHARS = 400


def _upload_gist(body: str, limit: int = _LATEST_UPLOAD_CHARS) -> str:
    """Two or three sentences off the top of an upload's indexed text.

    Deterministic on purpose: a spoken answer about the household's own
    document must be the document's words, not a model's reading of them.
    """
    text = " ".join(str(body or "").split())
    if not text:
        return ""
    out, taken = [], 0
    for sentence in re.split(r"(?<=[.!?])\s+", text):
        if not sentence:
            continue
        out.append(sentence)
        taken += len(sentence) + 1
        if len(out) >= 3 or taken >= limit:
            break
    gist = " ".join(out)
    if len(gist) > limit:
        gist = gist[:limit].rstrip() + "..."
    return gist


def _try_latest_upload_read(user_message: str) -> str | None:
    """"tell me what's in the document I just sent you".

    Without this it gets the byte-identical answer to "what documents do you
    have" - a recital of five filenames and "and 7 more", which answers a
    different question and reads the household's own file
    names out loud in a shared room. The reference is to ONE document, the
    newest one, and the manifest records when each was ingested.
    """
    text = (user_message or "").strip()
    if not text or len(text) > 200:
        return None
    if not _LATEST_UPLOAD_RE.search(text):
        return None
    try:
        from puffpai import document_lookup
        docs = [d for d in (document_lookup._load_index() or [])
                if isinstance(d, dict) and d.get("filename")]
    except Exception as exc:
        logger.debug("latest-upload lookup failed: %s", exc)
        return None
    if not docs:
        return ("You haven't sent me any documents yet, so there's nothing "
                "to read back.")
    newest = sorted(docs, key=lambda d: str(d.get("indexed_at") or ""))[-1]
    name = str(newest.get("filename") or "that file")
    # The household named it (or Puff labelled it), so say
    # THAT, not IMG_4821.jpg. The filename stays in the sentence when the two
    # differ, because it is how the file is found on a phone.
    title = str(newest.get("title") or "").strip()
    kind = _upload_kind_for(newest)
    if title and title.lower() != name.lower():
        lead = f"The last thing you sent me is '{title}'"
        if kind:
            lead += f" — a {kind}"
        lead += f", from {name}"
    else:
        lead = f"The last thing you sent me was {name}"
        if kind:
            lead += f" — a {kind}"
    when = str(newest.get("indexed_at") or "")[:10]
    lead += f", uploaded {when}." if when else "."
    try:
        body = document_lookup.text_of(newest)
    except Exception as exc:
        logger.debug("latest-upload text failed: %s", exc)
        body = ""
    gist = _upload_gist(body)
    print(f"[Chat] Capability read: latest upload -> {newest.get('id')}")
    if not gist:
        return (lead + " I have it indexed, but no readable text was "
                       "extracted from it, so there's nothing to read out.")
    # "what did you FIND in it" is a question about the reading, not a request
    # for the document: answer with the kind, the name and one line.
    if _LATEST_UPLOAD_FOUND_RE.search(text):
        return lead + " Here's the gist: " + _upload_gist(body, limit=160)
    return lead + " It reads: " + gist


#: "what did you find in the last thing I sent" — the same reference, asking
#: what the READING produced rather than for the document's words.
_LATEST_UPLOAD_FOUND_RE = re.compile(
    r"(?i)\bwhat\s+(?:did|do)\s+you\s+(?:find|make|read|get|see)\b"
    r"|\bwhat\s+(?:is|was|'s)\s+it\b")


def _upload_kind_for(doc: dict) -> str:
    """What the classifier called this upload (recipe, schedule, …), or ''.

    Read from the suggestion store, which is where the classification already
    lives — no second model pass, and nothing is invented when the pass has
    not finished (or never ran).
    """
    wanted = {str(doc.get(f) or '').strip().lower()
              for f in ('id', 'filename', 'title')} - {''}
    if not wanted:
        return ''
    try:
        from puffpai import suggestions as _suggestions
        records = _suggestions._load()
    except Exception as exc:                # pragma: no cover - defensive
        logger.debug("upload kind lookup failed: %s", exc)
        return ''
    for record in reversed(records or []):
        if not isinstance(record, dict):
            continue
        names = {str(record.get(f) or '').strip().lower()
                 for f in ('collection', 'upload_id', 'doc_name', 'title')}
        if not (names & wanted):
            continue
        kind = str(record.get('kind') or '').strip().lower()
        return '' if kind in ('', 'general') else kind.replace('_', ' ')
    return ''


# ── "the file I sent you" ───────────────────────────────────────────────────
#
# WHY. An uploaded screenshot was ingested by name and
# then, asked about twice, was never reached: "take a look at the ... photo i
# sent you" went to the agent team, which read "photo" as a security CAMERA
# snapshot, and "I sent you a file called Harbor Station, can you see it?"
# was answered by the registry capability read with a list of radio
# stations. Both answers are about the words in the sentence; neither is about
# the household's own file. The reference is deterministic — a file noun plus
# an explicit "I sent/uploaded" cue, or the file's name — so it is resolved
# here, ahead of both, out of the SAME stores fetch_my_document reads.

_FILE_NOUN = (r"(?:files?|photos?|photographs?|pictures?|pics?|images?|"
              r"screen\s?shots?|documents?|docs?|pdfs?|lists?|uploads?)")

#: An explicit "I sent this to you" — the whole gate. "send a message" and
#: "take a photo" carry no such cue and are left alone.
_SENT_CUE_RE = re.compile(
    r"\bi\s+(?:just\s+)?(?:sent|send|uploaded|upload|shared|share|gave|give)\b"
    r"|\bi'?ve\s+(?:just\s+)?(?:sent|uploaded|shared)\b"
    r"|\b(?:that|which)\s+i\s+(?:sent|uploaded|shared)\b"
    r"|\bsent\s+to\s+puff\b"
    r"|\b(?:you\s+were|i\s+had)\s+sent\b",
    re.IGNORECASE)

_FILE_NOUN_RE = re.compile(r"\b" + _FILE_NOUN + r"\b", re.IGNORECASE)

#: The inventory question: "what files do I have", "my uploads".
_MY_UPLOADS_RE = re.compile(
    r"\bmy\s+uploads\b"
    r"|\bwhat\s+" + _FILE_NOUN + r"\s+(?:do\s+i\s+have|have\s+i\s+"
    r"(?:sent|uploaded|shared))"
    r"|\bwhat\s+have\s+i\s+(?:sent|uploaded|shared)\b"
    r"|\b(?:list|show\s+me)\s+(?:my\s+)?(?:files|uploads)\b",
    re.IGNORECASE)

#: "a file called Harbor Station" — the name stops at the first punctuation,
#: which is what makes ", can you see it?" not part of the title.
_NAMED_FILE_RE = re.compile(
    r"\b" + _FILE_NOUN + r"\s+(?:called|named)\s+['\"‘“]?"
    r"([^'\"’”?.!,;]+)",
    re.IGNORECASE)

#: "the new beech station photo", the words in front of the file noun.
_FILE_QUALIFIER_RE = re.compile(
    r"\b(?:the|that|this|my)\s+"
    r"(?:new|newest|latest|last|recent|other)?\s*"
    r"([a-z0-9][\w'\- ]{1,40}?)\s+" + _FILE_NOUN + r"\b",
    re.IGNORECASE)

#: A camera request keeps the camera path. "take a look at" is not one.
_FILE_CAMERA_BLOCK_RE = re.compile(
    r"\btake\s+(?:a\s+)?(?:photo|picture|pic|snapshot|shot)\b"
    r"|\bsnapshot\b|\bcameras?\b|\bdoorbell\b",
    re.IGNORECASE)

#: A file noun WITHOUT "list". A household list is a list, not an upload: "make
#: a list called chores" and "what's on the list called chores" must not be
#: answered with "I don't have anything called 'chores'".
#: "list" only means an upload next to an explicit sent cue,
#: "that list of artists I uploaded".
_FILE_NOUN_STRICT_RE = re.compile(
    r"\b(?:files?|photos?|photographs?|pictures?|pics?|images?|"
    r"screen\s?shots?|documents?|docs?|pdfs?|uploads?)\b",
    re.IGNORECASE)

#: A list being WRITTEN, not read: "create a list called chores", "add eggs to
#: the list called groceries". Never ours, whatever else the sentence says.
_LIST_WRITE_RE = re.compile(
    r"\b(?:create|start|make|add|new|put)\b[^.?!]{0,40}?\blists?\b"
    r"|\badd\b[^.?!]{0,40}?\bto\s+(?:my|the|that)\s+lists?\b",
    re.IGNORECASE)

#: The sentence's main ask belongs to another feature entirely. Reading an
#: upload back is not an answer to "make a shopping list from the recipe I
#: sent you" — that turn is the shopping list's, and a confident "Yes — I have
#: Harbor Station" is the worst possible reply to it.
_FILE_OTHER_FEATURE_RE = re.compile(
    r"\b(?:shopping|grocery|groceries)\s+list\b"
    r"|\b(?:make|create|start|add|set|log|schedule)\b[^.?!]{0,40}?"
    r"\b(?:reminder|appointment|calendar|meal\s+plan|medication\s+log|"
    r"shopping\s+list|grocery\s+list)\b",
    re.IGNORECASE)

#: "a picture of my medication", "the screenshot of the recipe" — the thing the
#: sentence says the file is ABOUT.
_FILE_ABOUT_RE = re.compile(
    r"\b" + _FILE_NOUN + r"\s+(?:of|about|showing|with)\s+"
    r"(?:my\s+|the\s+|a\s+|an\s+|some\s+|that\s+)?"
    r"([a-z0-9][\w'\- ]{1,40})",
    re.IGNORECASE)

#: Qualifier words that name no file on their own.
_FILE_QUALIFIER_STOP = frozenset({
    "a", "an", "the", "new", "last", "latest", "other", "same", "only",
    "first", "second", "attached", "little", "big",
})


def _files_recent(limit: int = 0) -> list:
    """Every upload, newest first. The same two stores /ingest/list reads.

    Seeded test fixtures are demoted the same way ``list_my_documents``
    demotes them (``upload_index.is_fixture_doc``), so a leftover fixture row
    is never listed first and never becomes "the newest thing you sent".
    """
    try:
        from puffpai import document_lookup
        docs = document_lookup._load_index()
    except Exception as exc:                    # pragma: no cover - defensive
        logger.debug("files fastpath: index read failed: %s", exc)
        return []
    docs = sorted(docs, key=lambda d: str(d.get("indexed_at") or ""),
                  reverse=True)
    try:
        from puffpai.upload_index import is_fixture_doc
        docs = sorted(docs, key=lambda d: is_fixture_doc(
            d.get("classification"), d.get("snippet") or "",
            d.get("word_count")))
    except Exception as exc:                    # pragma: no cover - defensive
        logger.debug("files fastpath: fixture demotion unavailable: %s", exc)
    return docs[:limit] if limit else docs


def _files_title(doc: dict) -> str:
    """What to CALL an upload out loud: its title, else its filename."""
    return str(doc.get("title") or doc.get("filename") or "that file").strip()


def _files_resolve(reference: str) -> "dict | None":
    """The upload *reference* names, or None. Tolerates typos ("recipies").

    :mod:`puffpai.document_lookup` already resolves a spoken reference against
    the manifest, but only against FILENAMES; every manifest row also carries a
    title the household chose, and that is the name they say. So the filename
    pass runs first and a title pass at the same ratio runs behind it.
    """
    wanted = str(reference or "").strip()
    if not wanted:
        return None
    import difflib
    import os as _os
    from puffpai import document_lookup
    entry = document_lookup.resolve(wanted)
    if entry:
        return entry
    key = document_lookup._key(wanted)
    if not key:
        return None
    best, best_ratio = None, 0.0
    for doc in _files_recent():
        title = str(doc.get("title") or "")
        if not title:
            continue
        ratio = difflib.SequenceMatcher(
            None, key, document_lookup._key(_os.path.splitext(title)[0])
        ).ratio()
        if ratio > best_ratio:
            best, best_ratio = doc, ratio
    if best is not None and best_ratio >= document_lookup.MIN_RATIO:
        return dict(best, match="title-fuzzy", ratio=round(best_ratio, 3))
    return None


def _files_named_in(text: str) -> str:
    """The file name the sentence gives, or "" when it names none."""
    named = _NAMED_FILE_RE.search(text)
    if named:
        return named.group(1).strip()
    qualified = _FILE_QUALIFIER_RE.search(text)
    if qualified:
        words = [w for w in qualified.group(1).split()
                 if w.lower() not in _FILE_QUALIFIER_STOP]
        if words:
            return " ".join(words)
    return ""


def _files_miss_reply(reference: str, about: bool = False) -> str:
    """An honest miss names what IS held — never "I don't know what you mean"."""
    recent = _files_recent(3)
    if not recent:
        return ("You haven't sent me any files yet, so there's nothing here "
                "to look at.")
    titles = [_files_title(d) for d in recent]
    held = ", ".join(titles[:-1]) + f" and {titles[-1]}" \
        if len(titles) > 1 else titles[0]
    if reference and about:
        lead = f"I don't see one about '{reference}'."
    elif reference:
        lead = f"I don't have anything called '{reference}'."
    else:
        lead = "I couldn't tell which file you meant."
    return f"{lead} The most recent things you've sent me are {held}."


def _files_descriptor(text: str) -> str:
    """What the sentence says the file is ABOUT, or "" when it is generic.

    "the file I just sent you" is generic and may safely mean the newest
    upload. "a picture of my medication" is NOT: substituting the newest
    upload there would produce a confident "Yes — I have Harbor Station"
    about somebody's pills.
    """
    about = _FILE_ABOUT_RE.search(text or "")
    if not about:
        return ""
    words = [w for w in about.group(1).split()
             if w.lower() not in _FILE_QUALIFIER_STOP
             and w.lower() not in ("i", "you", "it", "me", "just", "sent",
                                   "uploaded", "shared", "that")]
    return " ".join(words).strip()


def _files_by_text(reference: str, limit: int = 10) -> "dict | None":
    """The newest recent upload whose opening text mentions *reference*.

    Deliberately cheap — the first ~500 characters of the ten most recent
    uploads — because this runs inside a voice turn. It is the difference
    between "I don't see one about medication" and naming the wrong file.
    """
    wanted = [w for w in re.findall(r"[a-z0-9']{3,}", (reference or "").lower())]
    if not wanted:
        return None
    from puffpai import document_lookup
    for doc in _files_recent(limit):
        try:
            head = document_lookup.text_of(doc, limit=500)[:500].lower()
        except Exception:                       # pragma: no cover - defensive
            continue
        if all(word in head for word in wanted):
            return dict(doc, match="text-head")
    return None


def _files_read_reply(entry: dict) -> str:
    """Confirm the file, then read the top of it back — or say it can't be.

    An image is OCR'd on ingest and OCR of a phone screenshot is often a
    handful of words. Saying so is the point: the alternative is a confident
    answer composed out of four words and a filename.
    """
    from puffpai import document_lookup
    title = _files_title(entry)
    when = str(entry.get("indexed_at") or "")[:10]
    stamp = f", uploaded {when}" if when else ""
    try:
        body = " ".join(document_lookup.text_of(entry).split())
    except Exception as exc:                    # pragma: no cover - defensive
        logger.debug("files fastpath: text read failed: %s", exc)
        body = ""
    words = len(body.split())
    if words < 15:
        counted = (f"could only read {words} word"
                   f"{'s' if words != 1 else ''} from it")
        return (f"Yes — I have {title}{stamp}. I can see the file but "
                f"{counted}, so I can't tell you much about what's in it.")
    snippet = body[:300].rstrip()
    if len(body) > 300:
        snippet += "..."
    return f"Yes — I have {title}{stamp}. It says: {snippet}"


def _try_my_files(user_message: str) -> str | None:
    """"Can you see the file I sent you?" — answered from the user's own uploads."""
    text = (user_message or "").strip()
    if not text or len(text) > 240:
        return None
    if _FILE_CAMERA_BLOCK_RE.search(text):
        return None
    # "search my uploads for X" is a SEARCH, which _try_documents_search owns;
    # the "my uploads" inventory rule below answered it with the file list.
    # A protected turn is not ours to redirect: _try_documents_search stands
    # down for it, so this keeps exactly its old behaviour.
    try:
        from puffpai.agents import document_reads
        if (document_reads.match(text) is not None
                and not _is_protected_query(text)):
            return None
    except Exception as exc:                    # pragma: no cover - defensive
        logger.debug("files fastpath: document search check failed: %s", exc)
    cue = bool(_SENT_CUE_RE.search(text))
    # A list being written, or an ask another feature owns, is never a file
    # read — but a playlist BUILT from an upload still is a playlist, so those
    # two shapes get the playlist rule and then stand down.
    if _LIST_WRITE_RE.search(text) or _FILE_OTHER_FEATURE_RE.search(text):
        return _try_taste_playlist(text)
    listing = bool(_MY_UPLOADS_RE.search(text)) and (
        cue or bool(_FILE_NOUN_STRICT_RE.search(text)))
    named_match = _NAMED_FILE_RE.search(text)
    # "list" counts as a file noun only next to an explicit sent/upload cue.
    named = bool(named_match) and (
        cue or not re.match(r"lists?\b", named_match.group(0), re.IGNORECASE))
    has_noun = bool(_FILE_NOUN_STRICT_RE.search(text)) or (
        cue and bool(_FILE_NOUN_RE.search(text)))
    if not (listing or named or (has_noun and cue)):
        return None
    # "make me a playlist from the file I sent" names the same file and asks
    # for something else entirely. The playlist owns that turn.
    taste = _try_taste_playlist(text)
    if taste:
        return taste
    docs = _files_recent()
    if not docs:
        return ("You haven't sent me any files yet — nothing has been "
                "uploaded to this box.")
    reference = _files_named_in(text)
    if listing and not reference:
        titles = [_files_title(d) for d in docs[:8]]
        more = (f" ...and {len(docs) - 8} more." if len(docs) > 8 else "")
        print(f"[Chat] Files fastpath: list -> {len(docs)} uploads")
        return (f"You've sent me {len(docs)} file"
                f"{'s' if len(docs) != 1 else ''}. Most recent first: "
                + ", ".join(titles) + "." + more)
    descriptor = _files_descriptor(text) if not reference else ""
    if reference or descriptor:
        wanted = reference or descriptor
        entry = _files_resolve(wanted) or _files_by_text(wanted)
    else:
        # Truly generic — "the file I just sent you" — so the newest upload IS
        # the referent. Anything with a descriptor in it has been resolved
        # above and missed, and a miss is said out loud rather than covered
        # with whatever arrived last.
        entry = docs[0]
    if entry is None:
        print("[Chat] Files fastpath: no match")
        return _files_miss_reply(reference or descriptor,
                                 about=not reference)
    print(f"[Chat] Files fastpath: read -> {_files_title(entry)}")
    return _files_read_reply(entry)


# ── A playlist that matches the listener's taste ────────────────────────────
#
# The second half of the same live ask: read the artists off that file and
# build a Jellyfin playlist from them. Five tool calls in a row (resolve the
# document, read it, parse it, search per artist, create and fill a playlist)
# is more than the on-box 3B model has ever chained, so the chain is a
# fastpath and the work is one tool call.

_TASTE_BUILD_RE = re.compile(
    r"\b(?:make|build|create|put\s+together|generate|set\s+up|throw\s+together)"
    r"\b[^?!.]{0,60}?\bplaylist\b",
    re.IGNORECASE)

#: What the playlist is to be built OUT of.
_TASTE_SOURCE_RE = re.compile(
    r"\b(?:from|based\s+on|based\s+off(?:\s+of)?|using|out\s+of|like|"
    r"matching|of|with)\b",
    re.IGNORECASE)

#: Turns that belong to the existing playlist fastpaths, not to a build.
_TASTE_BLOCK_RE = re.compile(
    r"\bplay\s+(?:my|the|that)\b|\bwhat\s+playlists\b"
    r"|\blist\s+(?:my|all)\s+playlists\b|\bplaylists\s+do\s+i\s+have\b",
    re.IGNORECASE)

_TASTE_NAME_RE = re.compile(
    r"\b(?:called|named)\s+['\"‘“]?"
    r"([^'\"’”?.!,;]+)",
    re.IGNORECASE)

#: "what artists do I have", an inventory read that would otherwise reach
#: the greedy device resolver, like the playlist inventory question.
_ARTIST_INVENTORY_RE = re.compile(
    r"\b(?:what|which|how\s+many)\s+artists\b"
    r"|\bartists?\s+(?:do\s+i\s+have|are\s+in\s+my)\b",
    re.IGNORECASE)


#: What a failed playlist build says out loud. Silence (``return None``) would
#: send the turn to the model, which then invents a playlist; and the
#: exception class name belongs in the [Media] log line, not in a sentence.
_TASTE_FAILED_REPLY = ("I couldn't build that playlist — the music server "
                       "didn't finish the job. Nothing was saved.")


def _taste_source_tail(text: str) -> str:
    """Everything after the "from"/"of"/"like" that follows the word playlist."""
    anchor = text.lower().find("playlist")
    if anchor < 0:
        return ""
    source = _TASTE_SOURCE_RE.search(text, anchor + len("playlist"))
    return text[source.end():].strip(" .!?") if source else ""


def _try_taste_playlist(user_message: str) -> str | None:
    """"Make me a playlist from the artists in that list I sent you."""
    text = (user_message or "").strip()
    if not text or len(text) > 300:
        return None
    if _ARTIST_INVENTORY_RE.search(text):
        try:
            print("[Chat] Taste playlist: artist inventory")
            return _get_assistant_tools().tool_dict['media_list_artists'].invoke("")
        except Exception as exc:
            logger.debug("artist inventory fastpath failed: %s", exc)
            _media_log(f"artist inventory -> FAILED: {type(exc).__name__}")
            return ("I couldn't read your artist list just now — the music "
                    "server didn't answer.")
    if not _TASTE_BUILD_RE.search(text) or _TASTE_BLOCK_RE.search(text):
        return None
    tail = _taste_source_tail(text)
    if not tail:
        return None
    asked_name = _TASTE_NAME_RE.search(text)
    name = asked_name.group(1).strip() if asked_name else ""
    if name:
        # "called Road Trip from coldplay" — the title ends where the source
        # clause begins, or the whole rest of the sentence becomes the title.
        cut = _TASTE_SOURCE_RE.search(name)
        if cut and cut.start() > 0:
            name = name[:cut.start()].strip()
    if asked_name:
        # "called Road Trip from coldplay, alt-j" — the title is not an artist.
        tail = _taste_source_tail(text[asked_name.end():]) or tail
    try:
        tools = _get_assistant_tools()
    except Exception as exc:                    # pragma: no cover - defensive
        logger.debug("taste playlist fastpath: no tools: %s", exc)
        return None

    # A file reference wins over a bare artist list: "from the harbor station
    # photo" names artists that are IN the file, not the file itself.
    if _FILE_NOUN_RE.search(tail) or (_FILE_NOUN_RE.search(text)
                                      and _SENT_CUE_RE.search(text)):
        reference = _files_named_in(tail) or _files_named_in(text)
        entry = _files_resolve(reference) if reference else None
        if entry is None:
            recent = _files_recent(1)
            if not recent:
                return _files_miss_reply(reference)
            entry = recent[0]
        doc_ref = str(entry.get("filename") or _files_title(entry))
        print(f"[Chat] Taste playlist: from document -> {_files_title(entry)}")
        try:
            return tools.tool_dict['media_playlist_from_document'].invoke(
                f"{doc_ref}|{name}")
        except Exception as exc:
            logger.debug("taste playlist from document failed: %s", exc)
            _media_log(f"taste playlist -> FAILED: {type(exc).__name__}")
            return _TASTE_FAILED_REPLY

    from puffpai.media_bridge import parse_artist_names
    listed = re.sub(r"\s+(?:and|&|plus)\s+", ", ", tail, flags=re.IGNORECASE)
    artists = parse_artist_names(listed)
    if not artists:
        return None
    if not name:
        name = f"{artists[0].title()} Mix"
    print(f"[Chat] Taste playlist: from artists -> {name} "
          f"({len(artists)} names)")
    try:
        return tools.tool_dict['media_playlist_from_artists'].invoke(
            f"{name}|{listed}")
    except Exception as exc:
        logger.debug("taste playlist from artists failed: %s", exc)
        _media_log(f"taste playlist -> FAILED: {type(exc).__name__}")
        return _TASTE_FAILED_REPLY


# ── Naming an upload out loud ─────────────────────────────
#
# The owner's ask: "let me name files on send, or let Puff label them". This is
# the second half said by voice — "call that picture Fall soccer" — and it
# is deliberately NARROW. Either a noun that means an upload is present, or the
# name is quoted; a bare "name that tune" renames nothing.

_UPLOAD_NOUN = (r"(?:photo|picture|pic|image|document|doc|file|recipe|"
                r"schedule|upload|scan|pdf|"
                r"last\s+thing\s+(?:i\s+)?sent(?:\s+you)?)")

_QUOTES_OPEN = "\"'‘“"
_QUOTES_CLOSE = "\"'’”"

#: "call that picture Fall soccer" / "name that document 'Recipes'".
_RENAME_NOUN_RE = re.compile(
    r"(?i)^\s*(?:please\s+)?(?:can\s+you\s+|could\s+you\s+)?"
    r"(?:call|name|label|title)\s+(?:that|this|the|my|it)\s+"
    + _UPLOAD_NOUN +
    r"\s*[" + _QUOTES_OPEN + r"]?(?P<title>[^" + _QUOTES_CLOSE + r"]{1,80}?)"
    r"[" + _QUOTES_CLOSE + r"]?\s*[.!?]*\s*$")

#: "call that 'Fall soccer'" — no noun, but the name is quoted.
_RENAME_QUOTED_RE = re.compile(
    r"(?i)^\s*(?:please\s+)?(?:can\s+you\s+|could\s+you\s+)?"
    r"(?:call|name|label|title)\s+(?:that|this|it)\s+"
    r"[" + _QUOTES_OPEN + r"](?P<title>[^" + _QUOTES_CLOSE + r"]{1,80})"
    r"[" + _QUOTES_CLOSE + r"]\s*[.!?]*\s*$")

#: "rename the soccer sheet to Fall soccer".
_RENAME_TO_RE = re.compile(
    r"(?i)^\s*(?:please\s+)?(?:can\s+you\s+|could\s+you\s+)?"
    r"rename\s+(?:the\s+|my\s+|that\s+|this\s+)?"
    r"[" + _QUOTES_OPEN + r"]?(?P<old>.{1,80}?)[" + _QUOTES_CLOSE + r"]?"
    r"\s+to\s+[" + _QUOTES_OPEN + r"]?(?P<title>[^" + _QUOTES_CLOSE + r"]{1,80}?)"
    r"[" + _QUOTES_CLOSE + r"]?\s*[.!?]*\s*$")


def _try_rename_upload(user_message: str) -> str | None:
    """"Call that picture Fall soccer" — renames ONE upload, no model.

    The newest upload is the target unless the sentence names another one,
    because "that picture" said out loud means the one just sent.
    """
    text = " ".join(str(user_message or "").split())
    if not text or len(text) > 160:
        return None
    target_phrase = None
    match = _RENAME_TO_RE.match(text)
    if match:
        target_phrase = match.group("old").strip()
    else:
        match = _RENAME_NOUN_RE.match(text) or _RENAME_QUOTED_RE.match(text)
    if not match:
        return None
    title = match.group("title").strip().strip(_QUOTES_OPEN + _QUOTES_CLOSE)
    title = title.strip(" .!?,")
    if not title:
        return None

    entry = _match_upload_entry(target_phrase) if target_phrase else None
    if entry is None and target_phrase:
        return (f"I don't have anything called {target_phrase}, so there's "
                f"nothing to rename.")
    if entry is None:
        entry = _newest_upload_entry()
    if entry is None:
        return ("You haven't sent me anything yet, so there's nothing to "
                "name.")
    old_name = str(entry.get('title') or entry.get('library') or '')
    record, error = _rename_upload(entry.get('collection'), title)
    if error == 'invalid':
        return "A name has to be between 1 and 80 characters."
    if error or record is None:
        return f"I couldn't rename {old_name} just now."
    filename = str(record.get('filename') or '')
    tail = (f" It came in as {filename}."
            if filename and filename.lower() != title.lower() else "")
    return f"Okay — that one is '{title}' now.{tail}"


# ── Answering the spoken offer ────────────────────────────
#
# After a phone upload Puff says ONE thing out loud: "That looks like a recipe
# — Chocolate chip cookies. Want me to save it to your recipes?". This is the
# other end of that sentence. Nothing is written without the yes, and an
# utterance that is neither a yes nor a no drops the offer rather than
# guessing — the same "it forgot" failure mode pending_clarifier chose.

_OFFER_YES_RE = re.compile(
    r"(?i)^\s*(?:yes|yeah|yep|yup|sure|okay|ok|absolutely|definitely|please"
    r"|go\s+ahead|do\s+it|save\s+(?:it|them|that|those)"
    r"|add\s+(?:it|them|those)|put\s+(?:it|them)\s+on|sounds\s+good)\b")

_OFFER_NO_RE = re.compile(
    r"(?i)^\s*(?:no|nope|nah|don'?t|do\s+not|not\s+(?:now|right\s+now|today)"
    r"|never\s*mind|skip\s+it|leave\s+it|cancel|forget\s+it)\b")


def _save_offered_recipes(record: dict) -> str:
    """Write the accepted recipes and say what landed."""
    params = ((record.get('action') or {}).get('params') or {})
    recipes = [r for r in (params.get('recipes') or []) if isinstance(r, dict)]
    if not recipes:
        return ("I accepted it, but I couldn't read a recipe out of it after "
                "all — it's still in your library.")
    saved = []
    app = _get_app_data()
    for recipe in recipes[:10]:
        name = str(recipe.get('name') or '').strip() or 'Untitled recipe'
        try:
            app.fresh_create_recipe(name, recipe.get('ingredients') or [],
                                    recipe.get('instructions') or '')
        except Exception as exc:
            logger.warning("Could not save offered recipe %s: %s", name, exc)
            continue
        saved.append(name)
    if not saved:
        return "I couldn't save it to your recipes just now."
    names = ", ".join(saved)
    return f"Saved {names} to your recipes in FreshTable."


def _complete_upload_offer(record: dict, said: str) -> str | None:
    """Finish the offer with the person's words, or None if they said neither."""
    from puffpai import suggestions as _suggestions
    sid = record.get('id')
    if _OFFER_NO_RE.match(said or ''):
        _suggestions.dismiss(sid)
        return ("Okay, I'll leave it. It's still in your library if you want "
                "it later.")
    if not _OFFER_YES_RE.match(said or ''):
        return None
    action = (record.get('action') or {}).get('type')
    title = _suggestions.display_title(record)
    if action == 'calendar_import':
        # Calendar events go through the ImportEvents preview, where the
        # person approves each one. Accepting here would take the card the
        # preview needs off the pending queue, so the suggestion stays
        # pending and the calendar comes up on screen instead.
        count = len(((record.get('action') or {}).get('params')
                     or {}).get('candidates') or [])
        _suggestions.clear_offer(sid)
        try:
            from puffpai import dashboard_display
            dashboard_display.show_query('show me my calendar', source='voice')
        except Exception as exc:
            logger.warning("Could not open the calendar preview: %s", exc)
        plural = "event" if count == 1 else "events"
        return (f"I put the {count} {plural} from {title} on the screen to "
                f"confirm — approve them there and they'll go on the "
                f"calendar.")
    accepted, err = _suggestions.accept(sid)
    if err or accepted is None:
        return "That one's already been handled."
    if action == 'recipe_import':
        return _save_offered_recipes(accepted)
    return f"Okay — {title} is filed."


def _try_upload_offer_reply(user_message: str,
                            conversation_id=None) -> str | None:
    """"Yes, save it" — the answer to the offer Puff spoke after an upload."""
    text = " ".join(str(user_message or "").split())
    if not text or len(text) > _pending_clarifier.MAX_ANSWER_CHARS:
        return None
    # Cheap gate first: only a yes/no shaped utterance is worth a store read.
    if not (_OFFER_YES_RE.match(text) or _OFFER_NO_RE.match(text)):
        return None
    try:
        from puffpai import suggestions as _suggestions
        record = _suggestions.offered_pending()
    except Exception as exc:
        logger.debug("offered-suggestion lookup failed: %s", exc)
        return None
    if not record:
        return None
    # The offer was SPOKEN from a background thread, which has no conversation
    # to register a question in. So the question is registered and answered in
    # this one turn, under a key both halves compute the same way — the
    # clarifier's single-use, cleared-before-completing semantics still hold.
    conversation = str(conversation_id or '').strip()
    if not conversation:
        try:
            from puffpai import turn_context
            conversation = str(turn_context.current_conversation() or '').strip()
        except Exception:
            conversation = ''
    if not conversation:
        conversation = 'upload-offer:' + str(record.get('id'))
    _pending_clarifier.register(
        "upload_offer",
        lambda _chosen, said: _complete_upload_offer(record, said),
        conversation_id=conversation,
        prompt=_suggestions.offer_text(record) or '')
    reply = _pending_clarifier.resolve(text, conversation)
    if reply:
        return reply
    # Neither a yes nor a no: forget the offer rather than let a later "yes"
    # about something else save a recipe.
    _suggestions.clear_offer(record.get('id'))
    return None


#: Any pairing question: (zigbee | pairing | pair mode/window) plus a word
#: that asks how it WENT. Bare "pair" is admitted only next to a pairing noun,
#: so "find me a pair of boots" is not a Zigbee question.
_ZIGBEE_STATUS_SUBJECT_RE = re.compile(
    r"(?i)\bzigbee\b|\bpairing\b|\bpaired\b"
    r"|\bpair\s+(?:mode|window|session|process)\b")
_ZIGBEE_STATUS_ASK_RE = re.compile(
    r"(?i)\bwindow\b|\bopen(?:ed)?\b|\bfind\b|\bfound\b|\bresults?\b"
    r"|\bhappen(?:ed)?\b|\bjoin(?:ed)?\b|\bstatus\b|\bgo\b|\bwent\b"
    r"|\bwork(?:ed)?\b|\bsucceed(?:ed)?\b")


def _try_zigbee_pair_status(user_message: str) -> str | None:
    """A question ABOUT pairing is answered from the report.

    Otherwise "did the zigbee pairing window open" falls to device
    disambiguation and reads raw script entity ids out loud
    ("script.puffpaizigbeepermit..."), and "what did you find when pairing"
    falls to the knowledge library and returns a guide about 3-D glasses.
    Both are answered by :func:`puffpai.zigbee_pairing.pairing_status`, which
    already writes the sentence from the last report plus the last
    ``pairing_window_*`` activity event - and names no entity ids.

    A REQUEST to open the window ("put the hub in pairing mode") is left to
    the Concierge's consent path, which is the only thing allowed to open it.
    """
    lower = (user_message or "").lower()
    if len(lower) > 160:
        return None
    if not (_ZIGBEE_STATUS_SUBJECT_RE.search(lower)
            and _ZIGBEE_STATUS_ASK_RE.search(lower)):
        return None
    try:
        from puffpai.agents import concierge as _conc
        if (_conc._ZIGBEE_PAIR_RE.search(lower)
                and not _conc._ZIGBEE_PAIR_STATUS_RE.search(lower)):
            return None
    except Exception as exc:                # pragma: no cover - ships with it
        logger.debug("zigbee status: concierge rules unavailable: %s", exc)
    try:
        from puffpai import zigbee_pairing
        return (zigbee_pairing.pairing_status() or {}).get("message") or None
    except Exception as exc:
        logger.debug("zigbee pairing status failed: %s", exc)
        return None


def _try_system_health(user_message: str) -> str | None:
    """"Can you do a system health check?" → the caretaker probe.

    RAG answers it with a library explanation of what a health check IS,
    citing a software guide. The probe exists
    (``CaretakerAgent.run_health_checks``) and is deterministic; the library
    must never own this question. A probe that cannot run says so rather than
    degrading into a clean bill of health. See
    :mod:`puffpai.agents.system_health`.
    """
    try:
        from puffpai.agents import system_health
        if not system_health.is_health_question(user_message):
            return None
    except Exception as exc:
        logger.debug("system-health read unavailable: %s", exc)
        return None

    report = None
    try:
        bus = _get_agent_team()
        caretaker = bus.get('caretaker') if bus is not None else None
        if caretaker is not None:
            report = caretaker.run_health_checks()
    except Exception as exc:
        logger.debug("caretaker probe failed: %s", exc)

    voice = None
    try:
        from puffpai.config import get_voice_models
        missing = [name.replace("_", " ")
                   for name, path in (get_voice_models() or {}).items()
                   if not os.path.exists(path)]
        voice = {"ready": not missing, "missing": missing}
    except Exception as exc:
        logger.debug("voice model probe failed: %s", exc)

    print("[Chat] System health -> caretaker probe")
    return system_health.reply_for(report, voice)


def _try_automations_read(user_message: str, force: bool = False) -> str | None:
    """"What automations do I have?" — the UNION of all three stores.

    On the agent route the answer can be "I don't have any personal
    automations configured" while the appliance holds HA automations and
    scripts, saved workflows and a Node-RED runtime with flows on it: with no
    single reader owning the question, whichever store the planner looks at
    decides the answer and the rest read as "none". Each source is collected here
    independently; an UNREADABLE source is reported as unread, never as empty.
    See :mod:`puffpai.agents.automations_read`.
    """
    try:
        from puffpai.agents import automations_read
        if not force and not automations_read.is_automations_question(
                user_message):
            return None
    except Exception as exc:
        logger.debug("automations read unavailable: %s", exc)
        return None

    automations, scripts = [], []
    try:
        for raw in (_get_ha_bridge().get_all_states() or []):
            entity_id = str((raw or {}).get("entity_id") or "")
            attrs = (raw.get("attributes") or {})
            name = str(attrs.get("friendly_name") or entity_id)
            if entity_id.startswith("automation."):
                automations.append({"name": name})
            elif entity_id.startswith("script."):
                scripts.append({"name": name})
    except Exception as exc:
        logger.debug("HA automation read failed: %s", exc)

    saved = []
    try:
        bus = _get_agent_team()
        majordomo = bus.get('majordomo') if bus is not None else None
        if majordomo is not None:
            saved = list(majordomo.list_tasks() or [])
    except Exception as exc:
        logger.debug("saved-workflow read failed: %s", exc)

    flows, nodered_readable = [], True
    try:
        listed = _bridge_list_workflows() or {}
        if listed.get("success"):
            flows = list((listed.get("result") or {}).get("workflows") or [])
        else:
            nodered_readable = False
    except Exception as exc:
        logger.debug("Node-RED flow read failed: %s", exc)
        nodered_readable = False

    reply = automations_read.reply_for(automations, scripts, saved, flows,
                                       nodered_readable=nodered_readable)
    print(f"[Chat] Automations read: {len(automations)} automation(s), "
          f"{len(scripts)} script(s), {len(saved)} saved, {len(flows)} flow(s)")
    return reply


def _try_recent_activity(user_message: str,
                         conversation_id: str | None = None) -> str | None:
    """"What did you just do?" — the real list, from the turn record.

    A model answer can claim "I didn't change anything ... I can't directly
    control devices or run scripts" two minutes after setting a thermostat and
    adding to the shopping list. Every write
    fastpath's own evidence-backed confirmation is kept per conversation (see
    :mod:`puffpai.turn_context`, filled by the ``chat_activity`` probe), so
    this reads them back instead of describing the appliance. This
    conversation's actions come first, the rest of the household's follow.
    Declines everything that is not an activity question.
    """
    try:
        from puffpai.agents import recent_activity
        if not recent_activity.is_activity_question(user_message):
            return None
        window = recent_activity.window_for(user_message)
        records = _turn_context.recent_actions(conversation_id, window=window)
        return recent_activity.reply_for(records, window)
    except Exception as exc:
        logger.debug("recent-activity fastpath failed: %s", exc)
        return None


def _try_source_citation(user_message: str,
                         conversation_id: str | None = None) -> str | None:
    """"Where did you find that?" — cite the PREVIOUS turn, never search again.

    Asked right after a correctly cited library answer, a new retrieval on
    the words of the question would read out dictionary entries for "find".
    A source question is about the last answer, and the last answer's citations are
    already recorded (``puffpai.turn_context``), so no retrieval runs here at
    all. Declines everything that is not a source question. See
    :mod:`puffpai.agents.source_citation`.
    """
    try:
        from puffpai.agents import source_citation
        if not source_citation.is_source_question(user_message):
            return None
        record = _turn_context.last_answer(conversation_id)
        return source_citation.reply_for(record)
    except Exception as exc:
        logger.debug("source-citation fastpath failed: %s", exc)
        return None


def _try_knowledge_search(user_message, conversation_history=None,
                          persona=None):
    """Answer an explicit "search my knowledge library for X" from retrieval.

    Returns a chat-result dict, or None to leave the turn exactly where it was.

    The router calls this phrasing ``agent`` (its keyword list owns "search"),
    the planner then picks a memory tool, and its work-log report is swallowed
    by the reasoning-leak guard, so the appliance would answer "Sorry, I
    couldn't complete that one" while the same store answers the un-keyworded
    phrasing correctly with a citation. Retrieval runs FIRST here and decides:
    no hits and the turn falls through untouched; hits and the answer is this
    layer's, prose if the model is warm and the passages themselves if it is
    not. See :mod:`puffpai.agents.knowledge_reads` for the trigger table.

    Costs one extra retrieval pass on a matched turn (~1 s): the guarantee is
    "never a canned failure when FTS has hits", and that has to be established
    before the model is consulted, not after. Never raises.
    """
    try:
        from puffpai.agents import knowledge_reads
        topic = knowledge_reads.match(user_message)
        if topic is None:
            return None
        ctx = _get_rag_context(topic)
    except Exception as exc:
        logger.debug("knowledge search unavailable: %s", exc)
        return None
    if not isinstance(ctx, dict):
        return None
    hits = ctx.get('hits') or []
    sources = ctx.get('sources') or []
    if not hits:
        print("[Chat] Knowledge search: no FTS hits -> unchanged route")
        return None
    print(f"[Chat] Knowledge search: {len(hits)} hit(s) for {_log_safe(topic)}")
    try:
        # The TOPIC, not the whole utterance: "search the knowledge library
        # for" is scaffolding that only dilutes the embedding, and the prose
        # the user wants is the answer to what follows it.
        result = _query_ollama_direct(topic, conversation_history,
                                      persona, enriched=True,
                                      strip_echo=False)
        if isinstance(result, dict) and str(result.get('response') or '').strip():
            return result
    except Exception as exc:
        logger.warning("knowledge search prose leg failed (%s); "
                       "answering from the passages", exc)
    fallback = knowledge_reads.render(topic, hits)
    if not fallback:
        return None
    return {'response': fallback, 'sources': sources, 'suggestions': []}


def _try_documents_search(user_message: str) -> str | None:
    """Answer an explicit "search my documents for X" from the upload index.

    Through router -> planner the plan can run dry, leaving the legacy agent
    to spend a whole model round only to pick ``search_my_documents`` and a
    second one writing up the hits: 40-60 s for a correct, local answer. The
    words already name the tool and
    the topic, so this runs the tool's own retrieval
    (``upload_index.search_my_documents``) and renders the hits with no model.

    What stays exactly as it was:

    * the index it reads is the redact-and-index output
      (``ingestion.screen_text_for_pii``), so vaulted PII values are not in it,
      same as for the tool;
    * a turn the vault gate treats as protected (``_is_protected_query``)
      stands down to its old route here, whatever that route does with it,
      and so does a topic naming a password, PIN, login or credentials
      (checked in ``document_reads``, not by widening that gate);
    * fixture-shaped rows (``upload_index.is_fixture_doc``: PII-marker or
      text-less test uploads) are never read out;
    * no egress: nothing here reaches the network.

    Declines (None) anything :func:`puffpai.agents.document_reads.match` does
    not claim, and a compound turn, which the planner finishes. Never raises.
    """
    try:
        from puffpai.agents import document_reads
        topic = document_reads.match(user_message)
        if topic is None:
            return None
        if _is_compound_request(user_message):
            return None
        if _is_protected_query(user_message):
            print("[Chat] Document search: protected topic -> unchanged route")
            return None
    except Exception as exc:
        logger.debug("document search unavailable: %s", exc)
        return None
    failed = False
    rows = []
    try:
        from puffpai.upload_index import is_fixture_doc, search_my_documents
        rows = [r for r in (search_my_documents(topic) or [])
                if isinstance(r, dict)
                and not is_fixture_doc(r.get('classification'),
                                       r.get('snippet', ''),
                                       r.get('word_count'))]
    except Exception as exc:
        logger.warning("document search failed: %s", exc)
        failed = True
    print(f"[Chat] Document search: {len(rows)} hit(s) for {_log_safe(topic)}"
          f"{' (search failed)' if failed else ''}")
    return document_reads.render(topic, rows, failed=failed)


#: A turn that sequences two requests ("do X, then Y"). The instant-answer
#: layer answers ONE thing and returns, so on a compound turn it silently
#: dropped the tail: "check whats in the pantry, then tell me the network
#: status too" answered only the pantry, with no error and no partial-
#: completion notice. The planner already completes such turns correctly when
#: neither clause happens to hit a fastpath, so the fix is to stand down and
#: let it, rather than to teach every fastpath to resume.
#:
#: Deliberately narrow — an explicit sequencing marker only. A plain "and"
#: joins one action to one object far more often than it joins two requests
#: ("turn off the kitchen and hallway lights"), and treating that as compound
#: would push working single-intent turns onto the slow path.
_COMPOUND_REQUEST_RE = re.compile(
    r"(?i)(?:,\s*|\s)(?:and\s+)?then\s+\w"
    r"|\bafter\s+that\b"
    r"|\band\s+(?:also\s+)?after\s+(?:that|this)\b"
    # "... and tell me ..." sequences the same way "... then
    # tell me ..." does. Kept in step with compound_turns._AND_READBACK /
    # _AND_ALSO by tests/test_compound_turn_second_clause.py — a bare "and" between two
    # objects still joins them.
    r"|(?:\s*,\s*|\s+)and\s+(?:then\s+|also\s+)?"
    r"(?=(?:tell|read|show|give|list)\s+(?:me|us)\b"
    r"|let\s+(?:me|us)\s+know\b)"
    r"|(?:\s*,\s*|\s+)and\s+also\s+"
    r"(?!(?:the|a|an|my|our|your|his|her|their|its|this|that|these|"
    r"those|some|both|it|one)\b)(?=\w)")
#: Ordinary English uses of "then" that sequence nothing.
_COMPOUND_FALSE_FRIEND_RE = re.compile(
    # "and then" is DELIBERATELY absent — it is the commonest sequencer in the
    # transcripts. "now and then" is excluded by its own alternative below.
    r"(?i)\b(?:back|even|since|by|until|right|way)\s+then\b"
    r"|\bnow\s+and\s+then\b|\bevery\s+now\s+and\s+then\b"
    r"|\bif\b[^.?!]{0,60}\bthen\b|\bthen\s+again\b")


def _dispatch_toolsmith_web(intent: str, payload: dict) -> dict:
    """Send ONE Toolsmith web intent on the bus and hand back its reply dict.

    Everything that can refuse still refuses, and each in its own place:

    * the ``chat_allow_egress`` opt-in is checked here, because it is a
      property of *this turn's origin* (an ad-hoc chat message) and no other
      layer knows that;
    * the ``web_fetch`` / ``web_search`` **door** is deliberately NOT checked
      here. ``egress_policy.chat_egress_allowed`` ANDs both halves, and calling
      it would refuse a shut door before the Toolsmith ever ran — costing the
      ledger's ``refused`` line and the gate's own "[Egress door closed]"
      sentence. Letting the Toolsmith answer keeps the same AND (its
      ``_require_door`` is the first statement on every hop) while producing
      the trail and the wording the owner needs. This orders two gates; it
      removes neither.
    """
    from puffpai.security import egress_policy
    from puffpai.web_lookup import OPT_IN_OFF_MARK

    try:
        opted_in = egress_policy.enabled("chat_allow_egress")
    except Exception as exc:  # a registry that will not read is not consent
        logger.warning("chat egress opt-in unreadable: %s", exc)
        opted_in = False
    if not opted_in:
        return {"ok": False, "egress_denied": True,
                "error": f"toolsmith: {OPT_IN_OFF_MARK} Chat turns are not "
                         "allowed to go online right now. Turn on "
                         "'chat_allow_egress' in Settings > Egress if you want "
                         "me to read web pages from chat."}

    bus = _get_agent_team()
    if bus is None:
        return {"ok": False,
                "error": "toolsmith: the agent team is not running, so I have "
                         "no way to reach the web right now"}

    from puffpai.agents import Budget, Envelope
    envelope = Envelope(
        intent=intent,
        payload=dict(payload or {}),
        requester="owner",
        origin_agent="chat",
        # A fetch is several hops at most (redirects) and reads nothing durable,
        # so this is not state-changing and needs no Sentinel veto. Egress is
        # granted here and nowhere else on this path; the door decides whether
        # it means anything.
        budget=Budget(max_actions=8, max_seconds=45.0, allow_egress=True),
        state_changing=False,
    )
    try:
        reply = bus.send(envelope, to="toolsmith")
    except Exception as exc:
        logger.warning("web lookup %s failed: %s", intent, exc)
        return {"ok": False,
                "error": f"toolsmith: {type(exc).__name__}: {exc}"}
    return reply if isinstance(reply, dict) else {
        "ok": False, "error": "toolsmith: the web lookup returned nothing"}


def _try_web_lookup(user_message: str) -> str | None:
    """Chat asked for a PAGE. Fetch it, or say honestly why not.

    Left to the planner, a phrasing naming a URL may never reach
    ``web_fetch``: the planner substitutes ``web_search`` or answers from the
    model's own memory, even inventing a listing it never fetched. A confident answer
    with no ledger line is the failure mode, so the decision is taken here,
    deterministically, before any model sees the turn.

    Declines everything that does not name a URL or a site, which is why it can
    sit this early in the chain. See :mod:`puffpai.web_lookup`.
    """
    try:
        from puffpai import web_lookup
    except Exception as exc:  # pragma: no cover - import guard
        logger.warning("web_lookup unavailable: %s", exc)
        return None
    lookup = web_lookup.parse_web_lookup(user_message)
    if lookup is None:
        return None
    if lookup.intent == web_lookup.INTENT_CAPABILITY:
        # Not a Toolsmith call — "can you search the web at all?" is answered
        # from the live switches. Logged distinctly so the transcript cannot
        # be read as an outbound lookup that never happened.
        print("[Chat] Web lookup fastpath -> websearch status (no egress)")
    else:
        print(f"[Chat] Web lookup fastpath -> toolsmith:{lookup.intent}")
    return web_lookup.run_web_lookup(lookup, _dispatch_toolsmith_web)


def _try_chitchat(user_message: str) -> str | None:
    """A greeting/acknowledgement gets a short social reply, never RAG.

    Declines everything that is not purely social — see
    :func:`puffpai.chitchat.match_social` for the bounded pattern set and the
    three defences that keep "how's the weather going" and "what's going on
    tomorrow" on their own paths. Never raises.
    """
    try:
        from puffpai import chitchat as _chitchat
        return _chitchat.match_social(user_message)
    except Exception as exc:  # pragma: no cover - import guard
        logger.debug("chit-chat fastpath failed: %s", exc)
        return None


def _is_compound_request(user_message: str) -> bool:
    """True when the turn sequences a second request after the first."""
    text = (user_message or "")
    if not text.strip():
        return False
    if _COMPOUND_FALSE_FRIEND_RE.search(text):
        return False
    return bool(_COMPOUND_REQUEST_RE.search(text))


def _try_voice_fragment_guard(user_message: str,
                              conversation_history=None,
                              truncated: bool = False) -> str | None:
    """A cut-off sentence gets asked back, never answered from the shelves.

    A speaker who pauses after a fronted time phrase can have the utterance
    closed by the 1.0 s ``PUFF_SILENCE_HANG`` in ``puffpai/voice/service.py``,
    so standalone fragments like "every week." or "every Tuesday." reach the
    brain as whole turns and would each get a confident encyclopedia answer.
    The capture-side guard is in the voice service; this is the
    second line of defence, because STT will always be able to hand over a
    fragment. The rule itself lives in ``puffpai.fragments`` so both sides use
    exactly one definition of "fragment".

    Stands down when the assistant's own last message asked a question: then
    the fragment is an ANSWER ("Wednesday.") and belongs to whoever asked.
    """
    from puffpai import fragments as _fragments
    from puffpai.agents.conversation_history import normalise_history
    if not _fragments.is_fragment(user_message):
        # The OTHER shape of a cut sentence: a long, grammatical head that
        # stops mid-phrase because the recorder cap closed the capture,
        # "...at 6.15, I have to take". Answered as-is, the brain would answer
        # the piece it got and invent the rest.
        # ``truncated`` is the recorder's own word for it when the voice
        # service sends it; the text test stands alone when it does not.
        if truncated or _fragments.ends_mid_phrase(user_message):
            return _fragments.ask_again_cut(user_message)
        return None
    # Every production caller passes the PAIRED history shape (see
    # puffpai.agents.conversation_history), so read it through
    # normalise_history; reading ``msg["role"]`` would never stand down, and
    # an answer to Puff's own clarify question would be asked back at her.
    for role, content in reversed(normalise_history(conversation_history)[-2:]):
        if role == "assistant":
            if "?" in content:
                return None
            break
    return _fragments.ask_again(user_message)


# ── Zone 3 (the Bridge) enforcement, ahead of the light switch ──────────────
# "turn on enforcement" is a `turn on <X>` sentence, and the home-control path
# claims those and answers with a Home Assistant disambiguation list ("which
# of these did you mean?"), while "start enforcing at the network edge" (the
# same act, phrased without the words a light switch owns) reaches
# `zone3_enforce` correctly. The registry already BINDS these phrases to
# security.zone3; binding is not dispatch, so the sentence still has to
# survive routing to get there. This fastpath is that step, registered in
# `_try_instant_answer` like every other fastpath (never `_detect_route`).
#
# It requires a Zone-3 SUBJECT word — enforcement / enforcing / filtering /
# telemetry / zone 3 / network edge. That single requirement is what keeps
# "turn on the kitchen lights", "turn on the porch light" and "turn off the
# tv" out: none of them names the network edge, so this declines and the home
# path keeps them.
_ZONE3_SUBJECT_RE = re.compile(
    r"\b(?:zone\s*-?\s*3|zone\s+three|enforcement|enforcing|filtering|"
    r"unfiltered|telemetry|network\s+edge|dns\s+filter(?:ing)?)\b",
    re.IGNORECASE)
# OFF is tested FIRST: "turn enforcement off" and "stop blocking telemetry"
# both contain an on-ish word ("turn", "blocking") and only the off word
# decides them.
_ZONE3_OFF_RE = re.compile(
    r"\b(?:off|stop|stops|disable|disabled|deactivate|unblock|unfilter|"
    r"pause|quit|cancel)\b",
    re.IGNORECASE)
_ZONE3_ON_RE = re.compile(
    # No bare "filtering"/"enforcing" here: they are SUBJECT words, and
    # counting them as verbs turns the question "is my network filtering?"
    # into a proposal to change it. Every real on-phrasing carries a real
    # verb ("start enforcing", "enable zone 3 enforcement").
    r"\b(?:on|start|starts|begin|enable|enabled|activate|resume|enforce|"
    r"block|blocking)\b",
    re.IGNORECASE)


def _try_zone3_enforce(user_message: str) -> str | None:
    """Zone-3 enforcement phrasings -> the `zone3_enforce` PROPOSAL, or None.

    Returns the tool's own words. `zone3_enforce` never flips the switch: it
    describes the change and stops, and the owner's confirmation on the
    Firewall page is what actuates. So this fastpath cannot change what
    reaches the internet, no matter what sentence reaches it.

    Deliberately does NOT reach `zone3_secure_device` for a named device
    ("block my tv's telemetry"). That tool WRITES a per-device policy while
    Zone 3 is observing — a fastpath that actuates is exactly what this layer
    must not be — so a device-shaped telemetry sentence is answered with the
    enforcement proposal, which lists the per-device rules that would go live
    anyway. Securing one named device stays a deliberate act on the Firewall
    page.
    """
    text = (user_message or "").strip()
    if not text or len(text) > 160:
        return None
    if not _ZONE3_SUBJECT_RE.search(text):
        return None
    if _ZONE3_OFF_RE.search(text):
        setting = "off"
    elif _ZONE3_ON_RE.search(text):
        setting = "on"
    else:
        # A bare status question ("is my network being filtered?") names the
        # subject and asks for nothing to change — leave it to zone3_status.
        return None
    try:
        tools = _get_assistant_tools()
        reply = tools.tool_dict['zone3_enforce'].invoke(setting)
    except Exception as exc:                       # pragma: no cover - defensive
        print(f"[Chat] zone3 enforce fastpath failed: {exc}")
        return None
    if not reply:
        return None
    print(f"[Chat] Zone 3 fastpath -> zone3_enforce({setting})")
    return str(reply)


# ── HA management ────────────────────────────────────────────────────────────
#
# A request for an automation must reach the provisioning path even when it
# says "workflow" or "with your agent team", the pairing close report must
# reach the chat, and an approved change with a locked vault must not end at
# "unlock it and ask me again". These helpers are deterministic fastpaths inside _try_instant_answer, which BOTH
# _process_chat_query (/v1/chat/completions, /chat/send) and
# _process_voice_query (/api/chat, voice) consult. No model chooses any of
# them, and none of them approves anything on its own.

def _ha_states_for_turn():
    """Live HA states through the EVERYDAY bridge, or None. Never raises."""
    try:
        bridge = _get_assistant_tools()._ha_bridge
        try:
            return bridge.get_all_states(force=True)
        except TypeError:
            return bridge.get_all_states()
    except Exception as exc:
        logger.debug("ha states unavailable for this turn: %s",
                     type(exc).__name__)
        return None


def _try_automation_author(user_message, conversation_history=None,
                           conversation_id=None):
    """A request for a NEW Home Assistant automation -> the builder.

    Runs before the agent-team roster, the compound splitter and the planner,
    so "make the automations with your agent team" and "you make the workflow"
    reach :mod:`puffpai.ha_automation_builder`. The builder only PROPOSES,
    through the existing ha_provision consent queue.
    """
    try:
        from puffpai import ha_automation_builder as _hab
        if not _hab.claims_turn(user_message):
            return None
    except Exception as exc:                        # never break the turn
        logger.debug("automation author unavailable: %s", exc)
        return None
    llm = None
    try:
        llm = getattr(_get_assistant_tools(), "_llm_chat", None)
    except Exception:
        llm = None
    if _hab.is_automation_question(user_message):
        # A question ABOUT automations is the read path's, never a proposal.
        return _try_automations_read(user_message, force=True)
    try:
        reply = _hab.handle_turn(user_message, _ha_states_for_turn(),
                                 history=conversation_history, llm=llm,
                                 conversation_id=conversation_id)
    except Exception as exc:
        # Claimed turn, failed builder: say so plainly. Never fall through to
        # the tool agent, which would improvise a write.
        logger.warning("automation author failed: %s", type(exc).__name__)
        return ("I couldn't set that up just now because something went wrong "
                "on my side, so nothing was changed in Home Assistant.")
    if reply:
        print("[Chat] Automation author -> ha_automation_builder")
    return reply


# The PIN slot: APPROVED ha_provision changes that could not run because the
# vault was locked, keyed to the CONVERSATION that was asked (one shared slot
# would let any surface answer). The next turn in that
# conversation may carry the PIN. It is caught at EVERY chat entry point before
# routing (_ha_pin_intercept), never reaches a model, history, memory or log,
# and opens a vault session only for the exact records the owner approved.
HA_PIN_SLOT_SECONDS = 240.0
HA_PIN_MAX_ATTEMPTS = 3
_ha_pin_lock = threading.Lock()
_ha_pin_slots: dict = {}

HA_PIN_ASK = ("One more step: the vault is locked, and this change needs the "
              "Home Assistant admin key that lives in it. Say or type your "
              "vault PIN now and I'll make it right away. The PIN stays out of "
              "the chat history.")


HA_PIN_ELSEWHERE = ("That looks like a PIN, so I kept it out of the chat "
                    "history, but I didn't use it: the change waiting for your "
                    "PIN was approved in another conversation. Enter it there.")


def _approver_identity():
    """The paired device (``device:``) or direct session (``peer:``) behind
    this request, as ``_get_chat_client_id`` derives it (never from a header
    a LAN client can choose), or None: anonymous, unknown, no request. Used to
    tie a waiting HA approval to the device that tapped Approve, and to tell
    which device fired a vault unlock."""
    try:
        if not has_request_context():
            return None
        cid = _get_chat_client_id()
    except Exception:
        return None
    if isinstance(cid, str) and cid.startswith(('device:', 'peer:')):
        return cid
    return None


def _ha_pin_key(conversation_id) -> str:
    # No id means the household thread: an ask filed by a caller with no id
    # and one answered on any surface of the household thread line up.
    return str(conversation_id or _household_thread_id())


def _ha_pin_slot_add(entity_id: str, conversation_id=None,
                     record: dict | None = None) -> None:
    key = _ha_pin_key(conversation_id)
    with _ha_pin_lock:
        slot = _ha_pin_slots.get(key)
        if slot is None or time.monotonic() > slot["expires"]:
            slot = {"records": {}, "attempts": 0, "expires": 0.0}
            _ha_pin_slots[key] = slot
        slot["records"][entity_id] = dict(record) if isinstance(record, dict) \
            else {"entity_id": entity_id}
        slot["expires"] = time.monotonic() + HA_PIN_SLOT_SECONDS


def _ha_pin_slot_ids(conversation_id=None) -> list:
    key = _ha_pin_key(conversation_id)
    with _ha_pin_lock:
        slot = _ha_pin_slots.get(key)
        if slot is None:
            return []
        if time.monotonic() > slot["expires"]:
            _ha_pin_slots.pop(key, None)
            _ha_pin_closed[key] = slot["expires"]
            return []
        return list(slot["records"])


def _ha_pin_slot_take(conversation_id=None) -> list:
    """The exact approved records for this conversation's slot."""
    with _ha_pin_lock:
        slot = _ha_pin_slots.get(_ha_pin_key(conversation_id))
        return [dict(r) for r in (slot or {}).get("records", {}).values()]


def _ha_pin_slot_clear(conversation_id=None, *, void: bool = False) -> None:
    """Close this conversation's slot. *void* also spends the approvals at
    once, so a cancelled PIN prompt leaves nothing usable behind."""
    with _ha_pin_lock:
        slot = _ha_pin_slots.pop(_ha_pin_key(conversation_id), None)
        if slot is not None:
            _ha_pin_note_closed(_ha_pin_key(conversation_id))
    if void and slot:
        try:
            from puffpai import ha_provisioning as _prov
            for record in slot["records"].values():
                _prov.void_approval(record)
            from puffpai import ha_pending_apply as _hpa
            _hpa.discard(list(slot["records"]))
        except Exception as exc:                    # pragma: no cover
            logger.debug("ha pin: void failed: %s", type(exc).__name__)


def _ha_pin_reset() -> None:
    """Tests only: drop every slot."""
    with _ha_pin_lock:
        _ha_pin_slots.clear()
        _ha_pin_closed.clear()


def _ha_pin_any_open() -> bool:
    now = time.monotonic()
    with _ha_pin_lock:
        return any(s["expires"] >= now for s in _ha_pin_slots.values())


_SPACED_PIN_RE = re.compile(r"[\d\s.\-]{4,64}")
_DIGIT_RUN_RE = re.compile(r"\d(?:[\s.\-]?\d){3,}")
_DIGIT_WORDS = {"zero": "0", "oh": "0", "o": "0", "one": "1", "two": "2",
                "three": "3", "four": "4", "five": "5", "six": "6",
                "seven": "7", "eight": "8", "nine": "9"}
_WORD_RUN_RE = re.compile(
    r"\b(?:zero|oh|one|two|three|four|five|six|seven|eight|nine)"
    r"(?:[\s,\-]+(?:zero|oh|one|two|three|four|five|six|seven|eight|nine)){3,}\b",
    re.IGNORECASE)
#: After a slot closes, a PIN-shaped message in that conversation is still
#: held back for this long (a late PIN must not reach a model or history).
HA_PIN_LATE_SECONDS = 600.0
_ha_pin_closed: dict = {}

HA_PIN_HELD = ("I kept that out of the chat because it looks like a PIN. Type "
               "just the PIN digits to finish, or say cancel.")


def _pin_digits_in(text: str):
    """Digits of a PIN said INSIDE a message ("my pin is 4821", "four eight
    two one"), or None. Never logged."""
    t = text or ""
    m = _DIGIT_RUN_RE.search(t)
    if m:
        return re.sub(r"\D", "", m.group(0))
    m = _WORD_RUN_RE.search(t)
    if m:
        return "".join(_DIGIT_WORDS[w.lower()]
                       for w in re.findall(r"[a-zA-Z]+", m.group(0)))
    return None


def _ha_pin_note_closed(key: str) -> None:
    _ha_pin_closed[key] = time.monotonic()


def _ha_pin_recently_closed(conversation_id) -> bool:
    key = _ha_pin_key(conversation_id)
    now = time.monotonic()
    with _ha_pin_lock:
        slot = _ha_pin_slots.get(key)
        if slot is not None and slot["expires"] < now:
            _ha_pin_slots.pop(key, None)
            _ha_pin_closed[key] = slot["expires"]
        closed = _ha_pin_closed.get(key)
    return closed is not None and now - closed <= HA_PIN_LATE_SECONDS


def _ha_pin_candidate(text: str):
    """The PIN in *text*, normalised, or None. "4 8 2 1" -> "4821"."""
    t = (text or "").strip()
    if _SPACED_PIN_RE.fullmatch(t):
        digits = re.sub(r"\D", "", t)
        if 4 <= len(digits) <= 32:
            return digits
    if _looks_like_pin(t):
        return t
    return None


def _apply_ha_changes_with_pin(conversation_id, pin: str) -> str:
    """Open a vault session with *pin*, apply THIS conversation's approved
    records (no others), close the session. Never logs the PIN."""
    from puffpai.security.vault import AuthenticationError, VaultError
    from puffpai import ha_provisioning as _prov
    from puffpai.ha_bridge import HUMAN_CONFIRMED as _HC

    allowed, wait = _vault_display_rl_check()
    if not allowed:
        _ha_pin_slot_clear(conversation_id, void=True)
        return (f"Too many PIN attempts. For safety I've paused vault access "
                f"for about {max(1, wait // 60)} more minute(s), and I haven't "
                f"made the change.")
    vault = _get_vault()
    if vault is None or not getattr(vault, "is_initialized", False):
        _ha_pin_slot_clear(conversation_id, void=True)
        return "The vault isn't available, so I haven't made the change."
    records = _ha_pin_slot_take(conversation_id)
    _vault_display_rl_note()
    try:
        try:
            session = vault.authenticate_mfa(pin, notify=False)
        except TypeError:                           # a vault without notify
            session = vault.authenticate_mfa(pin)
    except (AuthenticationError, VaultError):
        key = _ha_pin_key(conversation_id)
        with _ha_pin_lock:
            slot = _ha_pin_slots.get(key)
            if slot is not None:
                slot["attempts"] += 1
            spent = slot is None or slot["attempts"] >= HA_PIN_MAX_ATTEMPTS
        if spent:
            _ha_pin_slot_clear(conversation_id, void=True)
            return "That PIN didn't match, so I haven't made the change."
        return "That PIN didn't match. Try once more, or say cancel."
    sid = session.session_id
    messages = []
    try:
        from puffpai import ha_pending_apply as _hpa
        _hpa.discard([r.get("entity_id") for r in records])
        if not records:
            messages.append("That approval has expired, so I haven't made the "
                            "change. Ask me again and approve it.")
        for record in records:
            try:
                out = _prov.apply_approved_change(
                    request=record, bridge=_get_assistant_tools()._ha_bridge,
                    human_confirmed=_HC, vault_session_id=sid,
                    freshness_seconds=_hpa.WAIT_SECONDS)
                messages.append(out.get("message") or "Done.")
            except Exception as exc:
                messages.append("I couldn't make that change "
                                f"({type(exc).__name__}).")
        try:
            # Only the asks THIS PIN was given for: the ones waiting on this
            # conversation (a card key matches none, its record ran above).
            # Never every waiting approval in the house.
            _key = _ha_pin_key(conversation_id)
            _mine = [e.get("entity_id") for e in _hpa.list_waiting()
                     if _ha_pin_key(e.get("conversation_id")) == _key]
            if _mine:
                messages.extend(_hpa.apply_waiting(sid, only=_mine))
        except Exception as exc:                    # pragma: no cover
            logger.debug("ha pending: apply after PIN failed: %s",
                         type(exc).__name__)
    finally:
        try:
            vault.logout(sid)
        except Exception:
            pass
        sid = None
        _ha_pin_slot_clear(conversation_id)
    return " ".join(messages)


def _ha_pin_any_recently_closed() -> bool:
    """Did ANY conversation's PIN prompt close in the last 10 minutes?"""
    now = time.monotonic()
    with _ha_pin_lock:
        for key, slot in list(_ha_pin_slots.items()):
            if slot["expires"] < now:
                _ha_pin_slots.pop(key, None)
                _ha_pin_closed[key] = slot["expires"]
        return any(now - t <= HA_PIN_LATE_SECONDS for t in _ha_pin_closed.values())


_WORD = r"(?:zero|oh|one|two|three|four|five|six|seven|eight|nine)"
_PIN_TOKEN = (r"(?:\d(?:[\s.\-]?\d){3,31}"
              r"|(?=[A-Za-z0-9]*\d)[A-Za-z0-9]{4,32}"
              r"|" + _WORD + r"(?:[\s,\-]+" + _WORD + r"){3,11})")
#: The only shapes TRIED as the PIN: a bare PIN, "my pin is X", "pin X",
#: "pin: X", "it's X", "X please", or digit words.
_PIN_SHAPED_RE = re.compile(
    r"\s*(?:(?:my\s+)?(?:vault\s+)?pin(?:\s+(?:is|number\s+is|code\s+is))?"
    r"\s*[:\-]?\s*|it'?s\s+|it\s+is\s+|the\s+pin\s+is\s+)?"
    r"(?P<x>" + _PIN_TOKEN + r")"
    r"\s*(?:,?\s*(?:please|thanks|thank\s+you))?\s*[.!]*\s*",
    re.IGNORECASE)
#: Speech-to-text mishearings of digit words, read as digits ONLY while a PIN
#: matters (a slot open, or the 10-minute hold: ``_pin_shape`` is called from
#: nowhere else) and ONLY when the WHOLE message (bar the "my pin is" / "it's"
#: lead-in and a trailing "please"/"thanks") is a run of 4 to 12 digit-ish
#: words. "for eight to one" -> 4821, then used or held like any PIN. Inside
#: an ordinary sentence nothing changes: "I want to go for a walk", "two for
#: one" (3 words) and "set it to 4 for now" keep their old reading. Chosen:
#: won=1, to/too=2, for/fore=4, ate=8 (asked for), plus free=3: Whisper writes
#: "three" as "free" for th-fronting speakers, and a whole message of nothing
#: but digit-ish words is not an ordinary sentence, so the cost of the extra
#: word is nil while the cost of missing it is a voided approval. "oh"/"o"=0
#: were already digit words. Left out on purpose: "tree", "sex", "nein",
#: "tu", "fife": rarer, and each widens what a non-PIN message can look like.
_PIN_HOMOPHONES = {"won": "1", "to": "2", "too": "2", "for": "4",
                   "fore": "4", "ate": "8", "free": "3"}
_SPOKEN_DIGIT = (r"(?:zero|oh|o|one|won|two|to|too|three|free|four|for|fore|"
                 r"five|six|seven|eight|ate|nine)")
_HOMOPHONE_PIN_RE = re.compile(
    r"\s*(?:(?:my\s+)?(?:vault\s+)?pin(?:\s+(?:is|number\s+is|code\s+is))?"
    r"\s*[:\-]?\s*|it'?s\s+|it\s+is\s+|the\s+pin\s+is\s+)?"
    r"(?P<x>" + _SPOKEN_DIGIT + r"(?:[\s,\-]+" + _SPOKEN_DIGIT + r"){3,11})"
    r"\s*(?:,?\s*(?:please|thanks|thank\s+you))?\s*[.!]*\s*",
    re.IGNORECASE)


def _spoken_digits(text: str) -> str:
    out = []
    for w in re.findall(r"[A-Za-z]+", text):
        w = w.lower()
        d = _DIGIT_WORDS.get(w) or _PIN_HOMOPHONES.get(w)
        if d:
            out.append(d)
    return "".join(out)


#: A 2-3 digit piece of a PIN sent on its own ("48", then "21").
_FRAGMENT_RE = re.compile(
    r"\s*(?P<x>\d{2,3}|" + _WORD + r"(?:[\s,\-]+" + _WORD + r"){1,2})\s*[.!]*\s*",
    re.IGNORECASE)
#: Any letters-and-digits token of 4+ characters with at least one digit.
_MIXED_TOKEN_RE = re.compile(r"(?<![A-Za-z0-9])(?=[A-Za-z0-9]*\d)[A-Za-z0-9]{4,}")
HA_PIN_FRAGMENT_SECONDS = 60.0

HA_PIN_NUMBERS = ("I kept that out of the chat because it has numbers in it "
                  "while I'm waiting for your PIN. Type just the PIN, or say "
                  "cancel, and then ask me again.")
HA_PIN_FRAGMENT = ("I kept that out of the chat. Send the rest of the PIN, or "
                   "type the whole PIN, or say cancel.")


def _words_to_digits(text: str) -> str:
    return "".join(_DIGIT_WORDS[w.lower()] for w in re.findall(r"[A-Za-z]+", text)
                   if w.lower() in _DIGIT_WORDS)


def _pin_shape(text: str):
    """(kind, value) for a message while a PIN prompt matters. Never logs.

    kind is "pin" (try it), "fragment" (2-3 digits, join), "contains"
    (has numbers or a letters-and-digits token; hold, do not try) or None.
    A whole message of 4+ digit-ish words with common mishearings ("for
    eight to one") is read as that PIN; see ``_PIN_HOMOPHONES``.
    """
    t = (text or "").strip()
    if not t:
        return None, None
    m = _PIN_SHAPED_RE.fullmatch(t)
    if m:
        x = m.group("x")
        if re.search(r"\d", x):
            digits = re.sub(r"[\s.\-]", "", x)
            return "pin", digits
        return "pin", _words_to_digits(x)
    m = _HOMOPHONE_PIN_RE.fullmatch(t)
    if m:
        return "pin", _spoken_digits(m.group("x"))
    m = _FRAGMENT_RE.fullmatch(t)
    if m:
        x = m.group("x")
        return "fragment", (x if x.isdigit() else _words_to_digits(x))
    if (_DIGIT_RUN_RE.search(t) or _WORD_RUN_RE.search(t)
            or _MIXED_TOKEN_RE.search(t)):
        return "contains", None
    return None, None


def _ha_pin_hold(text: str, reply: str) -> str:
    _mark_vault_turn_private()
    _register_private_turn(text)
    return reply


def _ha_pin_fragment(conversation_id, piece: str):
    """Join 2-3 digit pieces sent within 60 s. Returns the joined PIN once it
    has 4+ digits, else None (the piece is held)."""
    key = _ha_pin_key(conversation_id)
    now = time.monotonic()
    with _ha_pin_lock:
        slot = _ha_pin_slots.get(key)
        if slot is None:
            return None
        prev, at = slot.get("frag") or ("", 0.0)
        joined = (prev if now - at <= HA_PIN_FRAGMENT_SECONDS else "") + piece
        if len(joined) >= 4:
            slot.pop("frag", None)
            return joined
        slot["frag"] = (joined, now)
        return None


def _ha_pin_core(text: str, conversation_id=None):
    """The whole PIN rule. Returns a reply (turn already marked private and
    registered) or None (the message is not PIN business)."""
    asked = bool(_ha_pin_slot_ids(conversation_id))
    if not (asked or _ha_pin_any_open() or _ha_pin_any_recently_closed()):
        return None
    msg = (text or "").strip()
    low = msg.lower()
    kind, value = _pin_shape(msg)
    if asked:
        if ("cancel" in low or "never mind" in low or "nevermind" in low
                or low in ("no", "stop", "forget it", "no thanks")):
            _ha_pin_slot_clear(conversation_id, void=True)
            return "OK, I haven't made the change, and that approval is cancelled."
        if kind == "pin" and 4 <= len(value or "") <= 32:
            _ha_pin_hold(msg, "")
            if value != msg:
                _register_private_turn(value)
            print("[Chat] HA change PIN follow-up (private turn)")
            return _apply_ha_changes_with_pin(conversation_id, value)
        if kind == "fragment":
            joined = _ha_pin_fragment(conversation_id, value)
            _ha_pin_hold(msg, "")
            if joined is None:
                return HA_PIN_FRAGMENT
            print("[Chat] HA change PIN follow-up (private turn)")
            return _apply_ha_changes_with_pin(conversation_id, joined)
        if kind in ("pin", "contains"):
            # Numbers in a sentence: held, and NOT an attempt.
            return _ha_pin_hold(msg, HA_PIN_NUMBERS)
        # No numbers at all: the prompt closes and its approval is void, so a
        # number said later cannot bind to it.
        _ha_pin_slot_clear(conversation_id, void=True)
        return None
    # Not the asked conversation, or every prompt has closed (late window):
    # anything PIN-like is held and never used.
    if kind in ("pin", "contains"):
        return _ha_pin_hold(msg, HA_PIN_HELD)
    return None


def _try_ha_change_pin_followup(user_message: str, conversation_id=None):
    """The PIN reply to HA_PIN_ASK (instant-layer copy of the entry guard)."""
    return _ha_pin_core(user_message, conversation_id)


def _ha_pin_intercept(text: str, conversation_id=None, consume: bool = True):
    """Entry-point guard: run BEFORE routing, logging or PII prep on every chat
    surface and the direct voice path. Returns the reply for a PIN turn (marked
    private and registered so /chat/save refuses it), or None."""
    reply = _ha_pin_core(text, conversation_id)
    if reply is None:
        return None
    if consume:
        _consume_vault_turn_private()
        _flush_turn_log(True)
    return reply


_SEE_LIGHTS_RE = re.compile(
    r"\b(?:do|can)\s+you\s+(?:see|find|detect|spot)\b(?P<rest>[^?.!]{0,60})",
    re.IGNORECASE)
_LIGHT_NOUN_RE = re.compile(r"\b(?:bulbs?|lights?|lamps?)\b", re.IGNORECASE)
_INDICATOR_LIGHT_RE = re.compile(r"led|status|ring|indicator|backlight",
                                 re.IGNORECASE)


def _try_ha_management_rules(user_message, conversation_history=None,
                             conversation_id=None):
    """The HA handlers for the streaming RAG branches, which skip
    _try_instant_answer: automation author/draft answers, a spoken consent
    answer, the pairing reopen and "do you see the bulbs"."""
    for rule in (
            lambda: _try_automation_author(user_message, conversation_history,
                                           conversation_id),
            lambda: _try_consent_approval(user_message, conversation_id),
            lambda: _try_pairing_reopen(user_message),
            lambda: _try_see_lights(user_message)):
        try:
            reply = rule()
        except Exception as exc:                    # never break the turn
            logger.debug("ha management rule failed: %s", type(exc).__name__)
            reply = None
        if reply:
            return reply
    return None


def _openai_private_reply(text: str, stream: bool):
    """An OpenAI-shaped reply for a private (PIN) turn, stream or not."""
    cmpl_id = f"chatcmpl-{uuid.uuid4().hex[:12]}"
    created = int(time.time())
    if stream:
        def _gen():
            yield "data: " + json.dumps({
                "id": cmpl_id, "object": "chat.completion.chunk",
                "created": created, "model": "puffpai",
                "choices": [{"index": 0, "delta": {"content": text},
                             "finish_reason": None}]}) + "\n\n"
            yield "data: " + json.dumps({
                "id": cmpl_id, "object": "chat.completion.chunk",
                "created": created, "model": "puffpai",
                "choices": [{"index": 0, "delta": {}, "finish_reason": "stop"}],
                "puffpai_meta": {"private": True}}) + "\n\n"
            yield "data: [DONE]\n\n"
        return Response(_gen(), mimetype='text/event-stream')
    return jsonify({"id": cmpl_id, "object": "chat.completion",
                    "created": created, "model": "puffpai",
                    "choices": [{"index": 0, "message": {
                        "role": "assistant", "content": text},
                        "finish_reason": "stop"}],
                    "puffpai_meta": {"private": True},
                    "usage": {"prompt_tokens": 0, "completion_tokens": 0,
                              "total_tokens": 0}})


def _try_see_lights(user_message: str):
    """"do you see the (new) bulbs" -> answered from live HA state, no model.

    Through the model, "do you see the smart bulbs" takes two LLM rounds.
    This reads the everyday bridge once and the last pairing report.
    """
    low = (user_message or "").lower()
    if len(low) > 140:
        return None
    m = _SEE_LIGHTS_RE.search(low)
    if not m or not _LIGHT_NOUN_RE.search(m.group("rest")):
        return None
    states = _ha_states_for_turn()
    if states is None:
        return "I can't reach Home Assistant right now, so I can't check."
    lights = {}
    for st in states:
        eid = st.get("entity_id") if isinstance(st, dict) else None
        if not isinstance(eid, str) or not eid.startswith("light."):
            continue
        name = str(((st.get("attributes") or {}).get("friendly_name")) or eid)
        if _INDICATOR_LIGHT_RE.search(name + " " + eid):
            continue
        lights[eid] = (name, st.get("state"))
    newest = []
    try:
        from puffpai import zigbee_pairing as _zp
        report = _zp.read_report() or {}
        for ent in report.get("new_entities") or []:
            eid = ent.get("entity_id") if isinstance(ent, dict) else None
            if eid in lights and eid not in newest:
                newest.append(eid)
    except Exception:
        pass

    def _say(ids):
        parts = [f"{lights[e][0]} ({lights[e][1]})" for e in ids]
        return parts[0] if len(parts) == 1 else \
            ", ".join(parts[:-1]) + " and " + parts[-1]

    if not lights:
        return "I don't see any lights in Home Assistant right now."
    print("[Chat] See-lights -> live HA state")
    others = [e for e in sorted(lights, key=lambda e: lights[e][0])
              if e not in newest]
    if newest:
        text = f"Yes. From the last pairing window I can see {_say(newest)}."
        if others:
            text += (f" I can also see {len(others)} other "
                     f"light{'s' if len(others) != 1 else ''}.")
        return text
    if re.search(r"\bnew\b", low):
        return ("I don't see any new bulbs from the last pairing window. "
                f"I can see {len(lights)} light{'s' if len(lights) != 1 else ''} "
                f"in all. To add more, say \"pair my bulbs\".")
    shown = others[:8]
    more = len(others) - len(shown)
    return (f"Yes. I can see {len(lights)} light{'s' if len(lights) != 1 else ''}: "
            f"{_say(shown)}" + (f", and {more} more." if more > 0 else "."))


_REOPEN_WORDS = {"yes", "yeah", "yep", "sure", "ok", "okay", "please", "do",
                 "it", "open", "again", "pair", "try", "the", "window", "one",
                 "more", "time"}
_REOPEN_TRIGGERS = {"yes", "yeah", "yep", "sure", "ok", "okay", "again"}


def _try_pairing_reopen(user_message: str):
    """"yes, open it again" right after an empty pairing window.

    Files a NEW pairing consent request (it does not open the radio); the
    owner approves that one as usual.
    """
    try:
        from puffpai import zigbee_pairing as _zp
        if not _zp.reopen_offer_active():
            return None
    except Exception:
        return None
    words = re.findall(r"[a-z]+", (user_message or "").lower())
    if not words or len(words) > 8 or not set(words) <= _REOPEN_WORDS \
            or not set(words) & _REOPEN_TRIGGERS:
        return None
    _zp.clear_reopen_offer()
    print("[Chat] Pairing reopen -> new consent request")
    try:
        return (_zp.request_pairing("asked to open it again") or {}).get(
            "message")
    except Exception as exc:
        logger.warning("pairing reopen failed: %s", type(exc).__name__)
        return None


def _post_to_recent_thread(text: str, conversation_id=None) -> bool:
    """Append an assistant message to the most recently active chat thread.

    Used for the pairing close report, so it lands where the owner was typing
    and not only on the kiosk speaker. Only a thread active in the last two
    hours qualifies; otherwise nothing is posted.
    """
    try:
        now = datetime.now(timezone.utc)
        best, best_ts = None, None
        with _chat_history_lock:
            if conversation_id:
                for conv in _chat_history:
                    if conv.get('id') == conversation_id:
                        conv.setdefault('messages', []).append({
                            'role': 'assistant', 'content': text,
                            'timestamp': now.isoformat(),
                            'source': 'zigbee_pairing'})
                        _save_conversation(conv)
                        return True
            for conv in _chat_history:
                msgs = conv.get('messages') or []
                if not msgs:
                    continue
                ts = str(msgs[-1].get('timestamp') or '')
                if best_ts is None or ts > best_ts:
                    best, best_ts = conv, ts
            if best is None:
                return False
            try:
                last = datetime.fromisoformat(best_ts)
                if last.tzinfo is None:
                    last = last.replace(tzinfo=timezone.utc)
            except ValueError:
                return False
            if (now - last).total_seconds() > 2 * 3600:
                return False
            best['messages'].append({'role': 'assistant', 'content': text,
                                     'timestamp': now.isoformat(),
                                     'source': 'zigbee_pairing'})
            _save_conversation(best)
        return True
    except Exception as exc:
        logger.debug("thread post failed: %s", type(exc).__name__)
        return False


try:
    from puffpai import zigbee_pairing as _zp_hook
    _zp_hook.set_thread_poster(_post_to_recent_thread)
except Exception as _exc:                           # pragma: no cover
    logger.debug("pairing thread poster not registered: %s", _exc)

try:
    from puffpai import ha_pending_apply as _hpa_hook
    from puffpai.security import vault as _vault_hook
    _hpa_hook.set_poster(_post_to_recent_thread)
    _hpa_hook.set_bridge_getter(lambda: _get_assistant_tools()._ha_bridge)
    _vault_hook.add_unlock_listener(_hpa_hook.on_unlock)
    _vault_hook.set_unlock_requester_provider(lambda: _approver_identity())
except Exception as _exc:                           # pragma: no cover
    logger.debug("ha pending-apply hooks not registered: %s", _exc)


def _pending_pin_notice():
    """"Your approval for 'X' is waiting for your vault PIN." Once per entry."""
    try:
        from puffpai import ha_pending_apply as _hpa
        return _hpa.take_unmentioned_notice()
    except Exception:
        return None


def _pending_pin_notice_waiting() -> bool:
    try:
        from puffpai import ha_pending_apply as _hpa
        return _hpa.has_unmentioned()
    except Exception:
        return False


def _set_turn_surface(surface: str) -> None:
    """Record which surface THIS request came in on (request-scoped flask.g,
    so a reused worker thread can never carry it into another turn)."""
    try:
        from flask import g, has_request_context
        if has_request_context():
            g.puffpai_surface = surface
    except Exception:                               # pragma: no cover
        pass


def _current_turn_surface() -> str:
    """'chat' or 'voice'. Outside a request (the direct voice path) it is
    voice; inside one it is whatever the entry route set, voice by default."""
    try:
        from flask import g, has_request_context
        if has_request_context():
            return getattr(g, "puffpai_surface", "voice")
    except Exception:                               # pragma: no cover
        pass
    return "voice"

_APPROVE_ALL_RE = re.compile(
    r"\b(?:yes\s+to\s+(?:both|all|them\s+all|all\s+of\s+them)|"
    r"approve\s+(?:both|all|them\s+all|all\s+of\s+them|them|"
    r"(?:the|these|those)\s+changes)|both\s+of\s+them|all\s+of\s+them|"
    r"yes\s+both)\b", re.IGNORECASE)


def _consent_resolver() -> str:
    return "user_via_chat" if _current_turn_surface() == "chat" else "user_via_voice"


def _req_conversation(req: dict) -> str:
    return _ha_pin_key(((req or {}).get("context") or {}).get("conversation_id"))


def _scoped_consent_decision(user_message, conversation_id):
    """(verdict, requests) for a spoken/typed answer, scoped to ONE ask.

    A bare "yes" must not approve every open request across conversations:
    it answers only the request Puff asked about most
    recently IN THIS CONVERSATION, inside that ask's freshness window. When
    that ask offered several together (a batch), "yes to both" / "approve
    all" takes them all; a name picks one; anything else gets ("ask", text).
    """
    from puffpai import consent_voice
    verdict, explicit = consent_voice.classify(user_message)
    take_all = bool(_APPROVE_ALL_RE.search(user_message or ""))
    if verdict is None and take_all:
        verdict, explicit = "approve", True
    # "yes the porch one": a loose yes counts ONLY if a name picks exactly one
    # request from Puff's own ask (checked below); otherwise it is not an answer.
    loose = False
    if verdict is None and re.match(r"\s*(?:yes|yeah|yep|approve|ok(?:ay)?)\b",
                                    user_message or "", re.IGNORECASE):
        verdict, explicit, loose = "approve", False, True
    if verdict is None:
        return None, []
    window = (consent_voice.EXPLICIT_WINDOW_SECONDS if explicit
              else consent_voice.BARE_WINDOW_SECONDS)
    key = _ha_pin_key(conversation_id)
    here = [r for r in consent_voice.eligible_requests(window)
            if _req_conversation(r) == key]
    if not here:
        return None, []
    newest = max(here, key=lambda r: str(r.get("created_at") or ""))
    batch = (newest.get("context") or {}).get("batch")
    group = ([r for r in here if (r.get("context") or {}).get("batch") == batch]
             if batch else [newest])
    if len(group) == 1 and not loose:
        return verdict, group
    if (take_all or verdict == "deny") and not loose:
        return verdict, group
    words = set(re.findall(r"[a-z0-9]+", (user_message or "").lower()))
    generic = {"yes", "approve", "the", "a", "one", "it", "please", "ok",
               "home", "assistant", "automation", "script", "puffpai", "on",
               "off", "and", "to", "switch", "light", "lights"}
    named = [r for r in group
             if (set(re.findall(r"[a-z0-9]+", str(r.get("label") or "").lower()))
                 - generic) & (words - generic)]
    if len(named) == 1:
        return verdict, named
    if loose:
        return None, []
    labels = " or ".join(f"'{r.get('label') or r.get('entity_id')}'"
                         for r in group[:4])
    return "ask", (f"Which one should I approve: {labels}? Or say yes to "
                   f"{'both' if len(group) == 2 else 'all'}.")


def _try_consent_approval(user_message: str,
                          conversation_id=None) -> str | None:
    """A SPOKEN answer to a consent question PuffPAI already asked, or None.

    The third approval surface, and the only deterministic one. The pairing
    assistant tells the owner *say "approve pairing" here, or tap Approve on
    the dashboard*; both must be real. Left to the LLM, the spoken answer
    takes ~50 s and can call the wrong tool entirely, so the window the owner
    just approved never opens.

    Everything this does mirrors ``sentinel_consent_resolve`` (the dashboard
    route) one for one: ``consent_requests.resolve`` records the owner's own
    answer, and the completion hook re-reads that durable record and refuses
    without it. Nothing here opens a window, writes to Home Assistant, or keeps
    a second copy of the queue.

    Declines — returns None, leaving the turn untouched — whenever the words do
    not match or nothing eligible is open, so an unrelated "yes" is never
    hijacked. See :mod:`puffpai.consent_voice` for the phrase rules and the
    freshness windows.
    """
    try:
        from puffpai import consent_voice
        verdict, pending = _scoped_consent_decision(user_message,
                                                    conversation_id)
    except Exception as exc:                        # never break the turn
        logger.debug("consent approval fastpath failed: %s", exc)
        return None
    if verdict == "ask":
        return pending                    # "Which one: ...?" (a string)
    if not verdict or not pending:
        # Nothing to resolve. An EXPLICIT "approve pairing" still deserves a
        # deterministic answer: left to the agent it costs ~60 s plus
        # speculative device-approval tool calls.
        # A bare "yes" keeps falling through, untouched.
        try:
            return consent_voice.nothing_open_reply(user_message)
        except Exception as exc:                    # never break the turn
            logger.debug("consent decline fastpath failed: %s", exc)
            return None

    from puffpai.security import consent_requests as _creq
    approved = verdict == "approve"
    messages: list[str] = []
    for req in pending:
        entity_id = req.get("entity_id")
        if not isinstance(entity_id, str) or not entity_id:
            continue
        try:
            resolved = _creq.resolve(entity_id, approved=approved,
                                     by=_consent_resolver(),
                                     note=("answered out loud"
                                           if _consent_resolver() ==
                                           "user_via_voice" else
                                           "typed in chat"))
        except Exception as exc:
            logger.warning("consent approval: resolve failed for %s: %s",
                           entity_id, exc)
            continue
        if resolved is None:            # raced with the dashboard, or expired
            continue
        if not approved:
            messages.append(
                f"Denied — {resolved.get('label') or entity_id} stays as it is.")
            continue
        action = resolved.get("action")
        if action == "zigbee_pair":
            from puffpai import zigbee_pairing as _zp
            try:
                messages.append(_zp.complete_approved_pairing(
                    _get_assistant_tools()._ha_bridge, request=resolved
                ).get("message") or "The pairing window is open.")
            except Exception as exc:
                messages.append("I recorded your approval, but the pairing "
                                f"window did not open: {exc}")
        elif action == "ha_provision":
            # Same two-key rule as the dashboard route: the recorded yes above,
            # plus the in-process HUMAN_CONFIRMED token that no request body
            # and no tool call can supply.
            from puffpai import ha_provisioning as _prov
            from puffpai.ha_bridge import HUMAN_CONFIRMED as _HC
            try:
                outcome = _prov.apply_approved_change(
                    request=resolved, bridge=_get_assistant_tools()._ha_bridge,
                    human_confirmed=_HC) or {}
                if outcome.get("vault_locked"):
                    from puffpai import ha_pending_apply as _hpa
                    # The chat/voice reply already asks for the PIN (HA_PIN_ASK),
                    # so no extra "waiting" mention on the next turn.
                    _hpa.add_waiting(resolved, mentioned=True,
                                     approver=_approver_identity())
                    _ha_pin_slot_add(str(resolved.get("entity_id")),
                                     conversation_id, resolved)
                    if HA_PIN_ASK not in messages:
                        messages.append(HA_PIN_ASK)
                else:
                    messages.append(outcome.get("message")
                                    or "I made the change in Home Assistant.")
            except Exception as exc:
                messages.append("I recorded your approval, but the change was "
                                f"not made: {exc}")
    if not messages:
        return None
    print(f"[Chat] Consent {verdict} by voice -> "
          f"{[r.get('entity_id') for r in pending]}")
    prefix = "Approved. " if approved else ""
    return prefix + " ".join(m for m in messages if m)


def _try_pending_clarifier(user_message: str,
                           conversation_id: str | None = None) -> str | None:
    """The answer to a question PuffPAI ITSELF asked, finished here.

    Without it, a clarifying question leaves no state behind and the next
    turn re-enters routing as if it had never been asked: "delete the soccer
    reminder" asks which of two events to remove, and the answer ("the
    every-weekday one") is routed as a fresh query and answered with a
    DICTIONARY DEFINITION of "every weekday", nothing deleted. "set an alarm
    for seven" asks "7 AM or 7 PM?" and "PM" comes back as post-mortem /
    prime minister / private message, no alarm.

    One mechanism, not one patch per question: the hook that ASKS registers a
    record with :mod:`puffpai.pending_clarifier` (what it asked, the options,
    and how to finish), and this runs ahead of every rule in the layer that
    listens for a request, so a one-word answer can never be mistaken for a
    knowledge query. The only hook before it is the PIN reply to a waiting
    Home Assistant change, which declines unless such a change exists. An utterance that does not answer the question
    clears the record and returns None, and the turn carries on untouched.

    Stands down for the two subsystems that already keep their own answer
    slot, so a "yes" is never handled twice: the meal plan's overwrite
    confirmation (``meal_plan_guard``) and the vault display's PIN challenge.
    """
    try:
        if _pending_clarifier.peek(conversation_id) is None:
            return None
    except Exception as exc:      # pragma: no cover - never worth a turn
        logger.debug("pending-clarifier peek failed: %s", exc)
        return None
    try:
        from puffpai.agents import meal_plan_guard
        if meal_plan_guard.get_pending():
            return None
    except Exception as exc:      # pragma: no cover - import guard
        logger.debug("meal-guard deferral check failed: %s", exc)
    try:
        from puffpai import dashboard_display as _dd_clar
        if _dd_clar.pending_vault_active():
            return None
    except Exception as exc:      # pragma: no cover - import guard
        logger.debug("vault deferral check failed: %s", exc)
    try:
        return _pending_clarifier.resolve(user_message, conversation_id)
    except Exception as exc:
        logger.debug("pending-clarifier resolve failed: %s", exc)
        return None


# ── skills: the sandboxed packages the owner approved ──────
#
# Four hooks and one helper, and the ORDER of them is the security argument:
#
# * the management hooks (list / disable / remove) are ordinary fastpaths that
#   talk about skills and never run one;
# * ``_try_skill_dispatch`` is the LAST call in ``_try_instant_answer`` -- after
#   every hand-tuned fastpath AND after ``_try_registry_read``, the registry's
#   own declared-phrase dispatcher. A skill answers only once the whole
#   appliance has declined, so a skill can never outrank anything this box
#   already does. That ordering is belt; the braces are in
#   ``skills.manifest.trigger_collision``, which refuses to INSTALL a skill
#   whose trigger the registry claims at all. "Turn off the lights" is
#   unavailable to a skill at install time, not just at dispatch time;
# * ``_try_capability_gap`` is not a fastpath at all. It runs behind the agent
#   route, on a reply that already said "I can't", and replaces it with a
#   sentence that names what was asked. It never claims an ability.

_SKILLS_LIST_RE = re.compile(
    r"(?i)^\s*(?:what|which)\s+skills?\b"
    r"|^\s*list\s+(?:my|your|the)\s+skills?\b"
    r"|^\s*(?:do\s+i\s+have\s+any|what\s+are\s+my)\s+skills?\b"
    r"|^\s*(?:show|tell)\s+me\s+(?:my|your|the)\s+skills?\b")

_SKILL_REMOVE_RE = re.compile(
    r"(?i)\b(?:remove|delete|uninstall|get\s+rid\s+of)\s+"
    r"(?:the\s+|my\s+|that\s+)?(?P<name>[\w' -]{2,60}?)\s+skill\b")

_SKILL_DISABLE_RE = re.compile(
    r"(?i)\b(?:disable|turn\s+off|switch\s+off|stop\s+using|pause)\s+"
    r"(?:the\s+|my\s+|that\s+)?(?P<name>[\w' -]{2,60}?)\s+skill\b")

_SKILL_ENABLE_RE = re.compile(
    r"(?i)\b(?:enable|re-?enable|turn\s+on|switch\s+on|start\s+using|"
    r"resume|put\s+back)\s+"
    r"(?:the\s+|my\s+|that\s+)?(?P<name>[\w' -]{2,60}?)\s+skill\b")

# Said at an ENABLE confirmation, these are not a yes. ``_skill_confirm``
# counts "turn it off"/"disable it" as yes, which is right for the disable and
# remove prompts it was written for and exactly wrong here: the safe reading of
# "turn it off" in answer to "switch it back on?" is that the person does not
# want it on. Checked first, and it resolves to leaving the skill OFF.
_SKILL_ENABLE_NOT_YES_RE = re.compile(
    r"(?i)^\s*(?:(?:turn|switch)\s+it\s+off|disable\s+it|leave\s+it\s+off|"
    r"remove\s+it|delete\s+it)\b")

# A yes/no confirmation is registered WITHOUT clarifier options on purpose.
# ``pending_clarifier.match_options`` is a "which one did you mean" matcher and
# its filler list swallows exactly the words a confirmation is made of ("yes",
# "remove", "keep", "cancel"), so an options-based confirm would silently never
# resolve. Free-form registration hands the raw words here instead, and anything
# that is not plainly yes or no returns None and routes normally -- an unclear
# answer must not be read as consent to remove something.
_SKILL_CONFIRM_YES_RE = re.compile(
    r"(?i)^\s*(?:yes|yeah|yep|yup|sure|ok(?:ay)?|do it|go ahead|"
    r"confirm(?:ed)?|please do|remove it|delete it|get rid of it|"
    r"turn it off|switch it off|disable it)\b")
_SKILL_CONFIRM_NO_RE = re.compile(
    r"(?i)^\s*(?:no|nope|nah|cancel|stop|never ?mind|leave it|keep it|"
    r"don'?t|do not)\b")


def _skill_confirm(text):
    """True (yes), False (no), or None for "that did not answer the question"."""
    said = " ".join(str(text or "").split())
    if _SKILL_CONFIRM_YES_RE.match(said):
        return True
    if _SKILL_CONFIRM_NO_RE.match(said):
        return False
    return None


def _skills_enabled_note():
    """The honest sentence when the skills tier is off, or None when it is on."""
    try:
        from puffpai.skills import dispatch as _sk
        usable, reason = _sk.available()
        return None if usable else reason
    except Exception as exc:
        logger.debug("skills unavailable: %s", exc)
        return "Skills are not available on this appliance."


def _skill_named(said):
    """The installed skill a person meant, or None. Name, id or trigger."""
    try:
        from puffpai.skills import dispatch as _sk
        wanted = " ".join(str(said or "").strip().lower().split()).strip(" .?!")
        if not wanted:
            return None
        for row in _sk.listing():
            candidates = {row["id"].replace("_", " "), row["id"],
                          row["name"].lower()}
            candidates.update(t.lower() for t in row["triggers"])
            if wanted in candidates:
                return row
        for row in _sk.listing():
            if wanted and wanted in row["name"].lower():
                return row
        return None
    except Exception as exc:
        logger.debug("skill lookup failed: %s", exc)
        return None


def _try_skills_list(user_message):
    """"What skills do I have?" -- names, reach and state. Reads only."""
    said = (user_message or "").strip()
    if not said or len(said) > 120 or not _SKILLS_LIST_RE.search(said):
        return None
    try:
        from puffpai.skills import dispatch as _sk
        rows = _sk.listing()
    except Exception as exc:
        logger.debug("skills listing failed: %s", exc)
        return None
    off = _skills_enabled_note()
    if not rows:
        return ("You haven't approved any skills. A skill is a small piece of "
                "code that runs in a sandbox and can reach exactly one website "
                "you approved -- I can't add one without showing you the code "
                "first." + (f" ({off})" if off else ""))
    parts = []
    for row in rows:
        state = ("on" if row["enabled"] and row["intact"] and row["tested"]
                 else "off")
        where = ", ".join(row["domains"]) or "nothing"
        parts.append(f"{row['name']} ({state}), which reaches {where}")
    sentence = f"You've approved {len(rows)} skill(s): " + "; ".join(parts) + "."
    if off:
        sentence += f" None of them can run right now: {off}"
    return sentence


def _try_skill_disable(user_message):
    """"Disable the X skill" -- asks first, then flips it off."""
    said = (user_message or "").strip()
    if not said or len(said) > 120:
        return None
    match = _SKILL_DISABLE_RE.search(said)
    if not match:
        return None
    row = _skill_named(match.group("name"))
    if row is None:
        return (f"I don't have a skill called \"{match.group('name').strip()}\".")
    if not row["enabled"]:
        return f"The {row['name']} skill is already switched off."

    def _complete(chosen, text, skill_id=row["id"], label=row["name"]):
        picked = _skill_confirm(text)
        if picked is None:
            return None
        if picked is False:
            return f"Leaving the {label} skill on."
        from puffpai.skills import store as _store
        _store.set_enabled(skill_id, False, reason="you asked me to")
        return (f"The {label} skill is off. Say \"enable the {label} skill\" "
                f"-- or use the Skills page -- and I'll check its code is still "
                f"the code you approved before turning it back on.")

    sentence = (f"Switch the {row['name']} skill off? It stays installed and "
                f"its door stays shut until you turn it back on.")
    try:
        _pending_clarifier.register("skill_disable", _complete,
                                    prompt=sentence)
    except Exception as exc:  # pragma: no cover - never worth the answer
        logger.debug("skill clarifier not registered: %s", exc)
    return sentence


def _try_skill_enable(user_message):
    """"Enable the X skill" -- asks first, then re-verifies, then turns it on.

    The turning-on is NOT done here: ``skills.install.enable_installed`` owns
    it, because switching a skill back on re-asserts its egress door and that
    has to happen behind the same two checks the dashboard route uses -- the
    files still hash to what was approved, and the reach it asks for is still
    the reach that was approved. A voice or chat "yes" cannot skip either one,
    and it cannot approve NEW code: a skill that fails the checks is told to go
    back through a consent card.
    """
    said = (user_message or "").strip()
    if not said or len(said) > 120:
        return None
    match = _SKILL_ENABLE_RE.search(said)
    if not match:
        return None
    row = _skill_named(match.group("name"))
    if row is None:
        return (f"I don't have a skill called \"{match.group('name').strip()}\".")
    if row["enabled"]:
        return f"The {row['name']} skill is already on."

    def _complete(chosen, text, skill_id=row["id"], label=row["name"]):
        if _SKILL_ENABLE_NOT_YES_RE.match(" ".join(str(text or "").split())):
            return f"Leaving the {label} skill off."
        picked = _skill_confirm(text)
        if picked is None:
            return None
        if picked is False:
            return f"Leaving the {label} skill off."
        from puffpai.skills import install as _install
        result = _install.enable_installed(skill_id)
        return result.get("message") or (
            f"I couldn't switch the {label} skill back on.")

    sentence = (f"Switch the {row['name']} skill back on? I'll check its code "
                f"is still the code you approved first, and reopen the door it "
                f"uses ({', '.join(row['domains']) or 'none'}).")
    try:
        _pending_clarifier.register("skill_enable", _complete, prompt=sentence)
    except Exception as exc:  # pragma: no cover - never worth the answer
        logger.debug("skill clarifier not registered: %s", exc)
    return sentence


def _try_skill_remove(user_message):
    """"Remove the X skill" -- asks first, then takes it (and its door) away."""
    said = (user_message or "").strip()
    if not said or len(said) > 120:
        return None
    match = _SKILL_REMOVE_RE.search(said)
    if not match:
        return None
    row = _skill_named(match.group("name"))
    if row is None:
        return (f"I don't have a skill called \"{match.group('name').strip()}\".")

    def _complete(chosen, text, skill_id=row["id"], label=row["name"]):
        picked = _skill_confirm(text)
        if picked is None:
            return None
        if picked is False:
            return f"Keeping the {label} skill."
        from puffpai.skills import store as _store
        _store.remove(skill_id)
        try:
            from puffpai.agent_activity import log_activity
            log_activity("toolsmith", "skill_removed",
                         f"Removed the skill '{label}' ({skill_id}) at your "
                         f"request; its egress door is gone with it.",
                         "done", {})
        except Exception as exc:  # pragma: no cover
            logger.debug("skill removal not recorded: %s", exc)
        return (f"The {label} skill is gone, and so is the door it used. "
                f"Nothing of it can run or reach out any more.")

    sentence = (f"Remove the {row['name']} skill? That takes away the code and "
                f"closes the door it used ({', '.join(row['domains']) or 'none'}).")
    try:
        _pending_clarifier.register("skill_remove", _complete,
                                    prompt=sentence)
    except Exception as exc:  # pragma: no cover - never worth the answer
        logger.debug("skill clarifier not registered: %s", exc)
    return sentence


def _try_skill_dispatch(user_message):
    """Answer from an installed skill. THE LAST hook in the chain.

    Whole-utterance equality with a declared trigger, nothing else: no
    containment, no scoring, no keywords. Everything about a skill is less
    trusted than everything else on this appliance, so it gets the narrowest
    matcher and the last turn.
    """
    said = (user_message or "").strip()
    if not said or len(said) > 160:
        return None
    skill_id = None
    try:
        from puffpai.skills import dispatch as _sk
        if _sk.env_disabled():
            return None
        # Disabled skills match too: a trigger the household approved gets a
        # true answer about the skill, never a fall-through to the model,
        # which would happily invent a live reading.
        skill_id = _sk.match(said, include_disabled=True)
        if skill_id is None:
            return None
        usable, reason = _sk.available()
        if not usable:
            # A trigger the household approved deserves an honest answer about
            # WHY it is not running, rather than a fall-through to the model.
            return f"That's one of your skills, but it can't run right now: {reason}"
        blocked = _sk.blocked_sentence(skill_id)
        if blocked:
            return blocked
        print(f"[Chat] Skill dispatch: {skill_id}")
        outcome = _sk.run(skill_id)
    except Exception as exc:
        logger.warning("skill dispatch failed: %s", type(exc).__name__)
        if skill_id is not None:
            return "That's one of your skills, but it didn't work just now."
        return None
    speech = (outcome or {}).get("speech") or ""
    if not speech:
        return "That's one of your skills, but it gave no answer just now."
    return speech


def _try_capability_gap(user_message, reply):
    """Replace an "I can't" with a sentence that says WHAT it can't do, or None.

    Decline-only and deliberately behind the agent route: by the time this
    runs, every fastpath, the registry read, the team and the legacy agent have
    all had the turn. It makes no offer -- this build cannot write a skill --
    and it claims no ability. See :mod:`puffpai.skills.gap` for the gate and for
    the decline corpus that shaped it.
    """
    try:
        from puffpai.skills import gap as _gap
        honest = _gap.detect(user_message, reply)
    except Exception as exc:
        logger.debug("capability gap check unavailable: %s", exc)
        return None
    if not honest:
        return None
    try:
        _chat_activity.record_capability("introspection.capabilities", "fastpath")
    except Exception as exc:  # pragma: no cover - attribution never costs a reply
        logger.debug("gap attribution not recorded: %s", exc)
    print("[Chat] Capability gap -> honest decline")
    return honest


def _try_app_fastpath(user_message) -> str | None:
    """A declarative app's lists, answered from its manifest. None if not ours.

    The house pattern for a misroute is a new ``_try_*`` fastpath rather than a
    change to ``_detect_route``, and this is that fastpath for every app nobody
    wrote Python for — a scaffolded persona, or a folder an owner copied in. It
    is registered ONCE, in :func:`_try_instant_answer`, which both the chat
    (`/chat/send`) and the voice (`/api/chat`) pipelines consult, so the typed
    and the spoken sentence get the same deterministic answer.

    Thin on purpose: the grammar, the bounds and the read-back verification all
    live in :mod:`puffpai.app_fastpath`, which knows no app ids and runs no code
    from a manifest. This wrapper only supplies the shared AppData instance, so
    the fastpath writes under the same per-file locks every other writer uses.
    """
    if not isinstance(user_message, str) or not user_message.strip():
        return None
    try:
        from puffpai import app_fastpath
        return app_fastpath.handle(user_message, _get_app_data())
    except Exception as exc:  # pragma: no cover - chat must not crash on this
        print(f"[Apps] generic app fastpath unavailable: {exc}")
        return None


def _try_media_bypass_rules(user_message: str) -> str | None:
    """The media/files fastpaths AND the rules that outrank them, for the two
    streaming branches that bypass ``_try_instant_answer``
    (``openai_chat_completions`` and ``chat_stream``, rag route only).

    Faithfulness is the whole contract: whenever this returns a reply it must
    be the reply ``_try_instant_answer`` would have given. Running the five
    media rules alone would make "turn off everything" come back here as
    a media stop ("I stopped the radio") while the same words through
    ``_try_instant_answer`` got the honest untargeted-house sentence, and a
    TuneIn-named station skipped its own route. Every
    rule that sits before or between the media rules there and can claim the
    same utterance is listed below, in that same relative order; see the
    parity test for the ordering.
    """
    for rule in (_try_radio_sources, _try_taste_playlist, _try_my_files,
                 _try_untargeted_house_command, _try_now_playing,
                 _try_tunein_radio, _try_radio_extras, _try_media_skip,
                 _try_media_play, _try_tv_stop, _try_media_stop):
        reply = rule(user_message)
        if reply:
            return reply
    return None


def _try_instant_answer(user_message: str, *,
                        conversation_history=None,
                        conversation_id: str | None = None) -> str | None:
    """The pre-team deterministic layer: trivial certainties, zero models.

    ``conversation_history`` is OPTIONAL and defaults to None so every existing
    caller keeps working unchanged. Two rules need it and only two: the meal
    write (which carries a recipe surfaced earlier in the conversation onto the
    plan) and the voice-fragment guard (which stands down when the fragment is
    an answer to a question the assistant just asked).

    Consulted before routing in BOTH chat and voice pipelines. Everything
    here is fully determined by the words in the request; sending these
    through the team costs seconds and can land on
    the wrong capability entirely (indoor sensors for outdoor weather, the
    thermostat rule for a kitchen timer).
    """
    # Fresh privacy state for this turn (consume-once flag; see the vault-display
    # transcript-leak protection above).
    _reset_vault_turn_privacy()
    # The PIN answering HA_PIN_ASK (an approved HA change, vault locked) comes
    # first of all: strictly slot-gated and PIN-shaped only, and it marks the
    # turn vault-private before any other rule can read or keep the text.
    ha_pin = _try_ha_change_pin_followup(user_message, conversation_id)
    if ha_pin:
        _mark_vault_turn_private()
        return ha_pin
    # An answer to a question PuffPAI asked comes before EVERYTHING, including
    # the compound check and the URL claim: "the every-weekday one" and "PM"
    # are answers, and every rule below only listens for requests.
    clarified = _try_pending_clarifier(user_message, conversation_id)
    if clarified:
        return clarified
    # ...and so is the answer to the offer Puff spoke, unprompted, after a
    # phone upload ("that looks like a recipe — want me to save it?"). Behind
    # the clarifier, so an open question the household was ASKED still wins.
    offered = _try_upload_offer_reply(user_message, conversation_id)
    if offered:
        return offered
    # A NEW Home Assistant automation ("workflow", "routine", "rule", or a
    # rule-shaped sentence). Ahead of the agent-team roster, the compound
    # check and the planner.
    authored = _try_automation_author(user_message, conversation_history,
                                      conversation_id)
    if authored:
        return authored
    # An open "which one should I delete?" prompt is answerable by the NEXT
    # turn and no other. Told here, at the top of the layer, so a turn some
    # other capability answers still counts as an intervening turn and closes
    # it.
    _note_calendar_turn(user_message, conversation_id)
    # A named URL or a named site is claimed FIRST — ahead of the compound
    # check and ahead of every keyword fastpath below. Two reasons, both
    # measured: "fetch <url> and then summarise it" is compound, and handing a
    # URL to the planner produces a fabricated page
    # summary with no ledger line; and "look up the current
    # weather on weather.gov" is absorbed whole by _try_weather_answer's
    # "weather" match and answered with the local forecast instead of the site
    # the owner named. This helper declines anything without a URL or an
    # explicit site, so nothing else it precedes can be stolen from.
    web = _try_web_lookup(user_message)
    if web:
        return web
    # A compound turn belongs to the planner, which can finish both clauses.
    # Every helper below answers ONE thing and returns, so claiming a compound
    # turn here drops the tail silently. See _is_compound_request.
    if _is_compound_request(user_message):
        print("[Chat] Compound request -> planner (instant answers stand down)")
        return None
    clock = _try_time_answer(user_message)
    if clock:
        return clock
    # The daily briefing, composed from the stores in four sentences. Early,
    # because the alternative is the briefing ROUTE: eight tool calls and an
    # LLM write-up that can outlast a 45s timeout.
    briefing = _try_daily_briefing(user_message)
    if briefing:
        return briefing
    # "what tools/capabilities do you have for X" is a meta question about
    # the registry, not a domain query — BEFORE the weather fastpath, or
    # "what tools do you have for weather" is absorbed by the "for weather"
    # match in _try_weather_answer's phrase set and answered with a live
    # forecast instead of the registry read.
    cap_lookup_early = _try_capability_lookup(user_message)
    if cap_lookup_early:
        return cap_lookup_early
    # Zone 3 enforcement BEFORE every other fastpath and before routing, so
    # "turn on enforcement" cannot be claimed by the home-control `turn on
    # <X>` path (which answers with an HA disambiguation list). Declines
    # anything that does not name the network edge — see _try_zone3_enforce.
    zone3 = _try_zone3_enforce(user_message)
    if zone3:
        return zone3
    # An answer to a question PuffPAI ASKED comes before every rule that only
    # listens for a request. "approve pairing" (and, while the question is
    # fresh, a bare "yes") closes the consent request the pairing assistant
    # opened; with nothing open it declines and this layer carries on.
    consent = _try_consent_approval(user_message, conversation_id)
    if consent:
        return consent
    reopen = _try_pairing_reopen(user_message)
    if reopen:
        return reopen
    # Weather ALERTS before the forecast fastpath: "severe weather alerts"
    # contains "weather" and would otherwise be answered as a plain forecast.
    alerts = _try_weather_alerts(user_message)
    if alerts:
        return alerts
    weather = _try_weather_answer(user_message)
    if weather:
        return weather
    # Offline directions, from the box's own map engines. After
    # the weather fastpaths (it never claims a weather sentence) and before
    # everything below, none of which owns a "directions to"/"how far is"/
    # "nearest" place ask; RAG answered those from memory.
    directions = _try_maps_directions(user_message, conversation_id)
    if directions:
        return directions
    timer = _try_timer_set(user_message)
    if timer:
        return timer
    # Alarms after timers (a "timer" sentence is excluded from the alarm rule
    # anyway) and before everything that can be fooled by a clock time — the
    # Concierge can read "set an alarm for 7am" as a thermostat setpoint.
    # Ask before writing when the hour could be either half of the day: this
    # runs ahead of both the set fastpath and the LLM, which would otherwise
    # guess the half of the day and write it.
    alarm_ask = _try_alarm_clarify(user_message)
    if alarm_ask:
        return alarm_ask
    alarm_set = _try_alarm_set(user_message)
    if alarm_set:
        return alarm_set
    camera = _try_camera_alerts(user_message)
    if camera:
        return camera
    # AFTER the alarm/timer fastpaths above, so "delete the alarm" still
    # reaches AlarmFlow, and before the task fastpath, which only adds. A
    # delete that falls all the way to the planner can be confirmed without
    # having happened.
    # Declines anything that names nothing in the calendar store.
    calendar_delete = _try_calendar_delete(user_message, conversation_id)
    if calendar_delete:
        return calendar_delete
    # BEFORE the task fastpath, never after: "set up a reminder every weekday
    # except Wednesdays at 6:15 take the kids to practice" is a
    # repeating calendar item, and _try_add_task would store the whole sentence
    # as a one-off to-do title. Declines anything without an add
    # intent AND a day set AND a time, so every plain reminder,
    # "remind me to do the dishes" — still reaches it untouched.
    recurring = _try_calendar_recurring(user_message)
    if recurring:
        return recurring
    # BEFORE the task fastpath, and only for a medication that is ON FILE:
    # "set up a daily reminder to take my X" is a medication schedule and
    # "I took my X this morning" is a dose log. Left to the agent, both take
    # 25 seconds, read the drug name out loud and can end in a claim that
    # there is no reminder tool. An unknown name still falls
    # through to _try_add_task, the owner of the reminder phrasing.
    med_log = _try_med_log(user_message)
    if med_log:
        return med_log
    # AFTER _try_med_log (which owns "remind me to take my <named drug>") and
    # BEFORE _try_add_task: a medication reminder that names no medication is
    # a question, not a to-do, and above all not a write.
    med_ask = _try_med_schedule_ask(user_message)
    if med_ask:
        return med_ask
    # The household roster, BEFORE the task fastpath: "add Riley to my
    # family" has the same shape as "add milk to the list" and would
    # otherwise become a to-do item called Riley.
    household_added = _try_household_add(user_message)
    if household_added:
        return household_added
    household_roster = _try_household_list(user_message)
    if household_roster:
        return household_roster
    task = _try_add_task(user_message)
    if task:
        return task
    # AFTER the task fastpath, never before: "remind me to take my blood
    # pressure pill at 8" is a REMINDER, and _try_add_task owns it on all five
    # surfaces. The medication rules below must not steal it.
    med = _try_med_fastpath(user_message)
    if med:
        return med
    # Meal WRITE from conversation context BEFORE the whole-week planner: "add
    # both of those salmon recipes to the dinner meals for this week" is an add
    # to named slots, not a request to regenerate the week. Declines unless a
    # recipe was actually surfaced earlier in this conversation.
    # A grocery add BEFORE the meal fastpaths and before the capability reads:
    # "add oat milk to the shopping list" is a one-item write to FreshTable's
    # list, and every other reading of that sentence (a week's meal plan, a
    # read of the list) is a different question. Verified from the store.
    shopping_add = _try_shopping_add(user_message)
    if shopping_add:
        return shopping_add
    # ...and its inverse, in the same place: "remove oat milk from the shopping
    # list" / "cross oat milk off the list" would otherwise fall through
    # to a READ that recites the whole list.
    shopping_remove = _try_shopping_remove(user_message)
    if shopping_remove:
        return shopping_remove
    meal_add = _try_meal_add(user_message, conversation_history)
    if meal_add:
        return meal_add
    meal = _try_meal_plan(user_message)
    if meal:
        return meal
    agents = _try_list_agents(user_message)
    if agents:
        return agents
    asked = _try_ask_agent(user_message)
    if asked:
        return asked
    # "what did you just do" BEFORE "what can you do": the capability blurb is
    # a self-description, and a self-description is exactly the wrong answer to
    # a question about what happened ("I didn't change anything ...
    # I can't directly control devices", two minutes after a thermostat write).
    did = _try_recent_activity(user_message, conversation_id)
    if did:
        return did
    # "What automations do I have" is a UNION read of three stores, and a
    # false negative ("I don't have any personal automations
    # configured") is the worst answer available. Ahead of the registry and the
    # capability reads, which each know about one of the three.
    automations = _try_automations_read(user_message)
    if automations:
        return automations
    # An OPS question about this appliance, answered by the caretaker probe.
    # Ahead of the document rule and RAG, which would answer "can you do a
    # system health check" with a library explanation of what a health check IS.
    ops = _try_system_health(user_message)
    if ops:
        return ops
    # "how many devices can you control" is a COUNT of the house, not a
    # self-description and not a library question (RAG answers it with an
    # essay on circuit breakers). Ahead of _try_capabilities,
    # whose "what can you ..." shapes overlap it.
    seen_lights = _try_see_lights(user_message)
    if seen_lights:
        return seen_lights
    device_count = _try_device_count(user_message)
    if device_count:
        return device_count
    # "are the doors locked" with no lock.* entity, said plainly.
    doors = _try_doors_locked(user_message)
    if doors:
        return doors
    # A question ABOUT the pairing window is answered from the pairing report,
    # never by the device resolver (which reads raw script ids out loud) and
    # never by the library (which answers with a 3-D glasses guide).
    zigbee_status = _try_zigbee_pair_status(user_message)
    if zigbee_status:
        return zigbee_status
    # "what radio sources do you have" / "can you use TuneIn": a fact about two
    # egress doors, read from the doors. Ahead of _try_capabilities and every
    # media rule; the model can call TuneIn unreachable with its door open and
    # the library answers with quasars.
    radio_sources = _try_radio_sources(user_message)
    if radio_sources:
        return radio_sources
    caps = _try_capabilities(user_message)
    if caps:
        return caps
    dash = _try_dashboard_manage(user_message)
    if dash:
        return dash
    # Vault PIN follow-up runs BEFORE _try_show: when a display challenge is
    # pending, a PIN-shaped reply is captured here (never reaches the LLM).
    # "open the vault" / "let me in the vault": one sentence, no graph. It
    # only SAYS the PIN is required — see _try_vault_open.
    vault_open = _try_vault_open(user_message)
    if vault_open:
        return vault_open
    vault_pin = _try_vault_pin_followup(user_message)
    if vault_pin:
        return vault_pin
    # Delete/undo a logged workout. Ahead of the media/show fastpaths
    # so a one-word answer to its own "whose workout?" question is not
    # swallowed by a title search, and ahead of _try_fitness_program, whose
    # block-regex already excludes every delete phrasing by design. Declines
    # (returns None) for anything that is not a FitFam delete.
    fitness_delete = _try_fitness_delete(user_message)
    if fitness_delete:
        return fitness_delete
    # A "show me <title>" that names something in the MOVIE library is
    # answered from the library, before the knowledge shelves get to guess at
    # the leftover words. Declines everything else.
    media_show = _try_media_show(user_message)
    if media_show:
        return media_show
    show = _try_show(user_message)
    if show:
        return show
    # Arithmetic BEFORE anything that can be fooled by a number.
    # Declines everything it cannot parse as pure arithmetic.
    calculated = _try_calculate(user_message)
    if calculated:
        return calculated
    # A file the household SENT, and a playlist built from one — both ahead of
    # the media fastpaths and of _try_capability_read. Otherwise "I sent
    # you a file called Harbor Station, can you see it?" is answered by the
    # registry read with a list of radio stations, and the same file asked
    # about as a "photo" is read by the agent team as a security camera
    # snapshot. Both decline anything without an explicit sent/uploaded cue or
    # a named file, so no camera and no music phrasing is taken from them.
    taste_playlist = _try_taste_playlist(user_message)
    if taste_playlist:
        return taste_playlist
    my_files = _try_my_files(user_message)
    if my_files:
        return my_files
    # A bare whole-house "turn off everything" BEFORE the media fastpaths:
    # "turn off" + "everything" is exactly the media-stop shape, and the
    # honest answer is about the untargeted gate, not about music.
    untargeted = _try_untargeted_house_command(user_message)
    if untargeted:
        return untargeted
    # "what's playing" is answered from the PLAYER, not from a declaration,
    # which can claim silence over a live stream.
    playing_now = _try_now_playing(user_message)
    if playing_now:
        return playing_now
    # TuneIn-named / "put X on" radio phrasings BEFORE the generic media play
    # fastpath: a play-intent must never reach RAG, where "tune in to NPR"
    # is answered with invented Raspberry Pi instructions.
    tunein = _try_tunein_radio(user_message)
    if tunein:
        return tunein
    # Discovery / variety / favorites BEFORE the generic play fastpath: "play
    # something else", "play the second one" and "play my favorite stations"
    # all carry a media verb, so _try_media_play would otherwise take them and
    # search the catalog for the literal words "something else".
    # Declines to None for everything that is not radio.
    radio_extra = _try_radio_extras(user_message)
    if radio_extra:
        return radio_extra
    # A bare "next"/"skip" carries no media verb at all, so it
    # reached nobody while a station played. After the radio
    # rules — "next station" is theirs — and before the play fastpath.
    media_skip = _try_media_skip(user_message)
    if media_skip:
        return media_skip
    media = _try_media_play(user_message)
    if media:
        return media
    # The kiosk TV player first: "stop the tv" names no media word the
    # generic stop knows. Claims the turn only while the player is on.
    tv_stop = _try_tv_stop(user_message)
    if tv_stop:
        return tv_stop
    media_stop = _try_media_stop(user_message)
    if media_stop:
        return media_stop
    # Volume AFTER stop (so "silence"/"stop" still halt playback outright) and
    # before the registry reads and the team — see _try_media_volume for the
    # thermostat misroute this closes.
    volume = _try_media_volume(user_message)
    if volume:
        return volume
    # A thermostat set, with every target called and every target read back.
    # AFTER the volume fastpath so "set the volume to 74" keeps its meaning,
    # and after the timer/alarm fastpaths above so no clock time is read as a
    # setpoint. The team route resolves ONE entity, so "set the living room
    # and bedroom to 74" would set one thermostat and confirm two.
    # See puffpai.agents.climate_writes.
    climate = _try_climate_set(user_message, conversation_history)
    if climate:
        return climate
    # Library INVENTORY reads (playlists / books / a direct movie title) —
    # before the registry reads and the greedy list_devices resolver, which
    # answers "what playlists do I have saved" with every HA entity.
    medialib = _try_media_library_query(user_message)
    if medialib:
        return medialib
    # The librarian, right beside the library inventory read it extends:
    # categories, comic series, recommendations and Calibre-web shelves. It
    # runs SECOND so the book-author question keeps its own answer.
    books = _try_books(user_message, conversation_id or "")
    if books:
        return books
    # Household reads, each declared from natural phrasings and each ahead of
    # the generic capability-read table and RAG: capabilities that work,
    # which those phrasings would otherwise never reach.
    # BEFORE the program READ: "log my workout" names the same session, and
    # the read would answer a write request with a recital.
    workout_done = _try_workout_log(user_message)
    if workout_done:
        return workout_done
    fitness_program_read = _try_fitness_program(user_message)
    if fitness_program_read:
        return fitness_program_read
    trivia = _try_trivia_start(user_message)
    if trivia:
        return trivia
    # "what's in the document I just sent you" names ONE document - the
    # newest - and _try_document_read declines it (its head noun is generic),
    # which would leave it to the list-every-filename answer.
    # Naming an upload comes BEFORE reading one back: "call that picture Fall
    # soccer" names the same document the read hook answers about.
    renamed = _try_rename_upload(user_message)
    if renamed:
        return renamed
    latest_upload = _try_latest_upload_read(user_message)
    if latest_upload:
        return latest_upload
    document = _try_document_read(user_message)
    if document:
        return document
    cap_lookup = _try_capability_lookup(user_message)
    if cap_lookup:
        return cap_lookup
    # An app NOBODY wrote code for — a scaffolded persona, a folder an owner
    # copied in — keeping one of its own declared lists. Placed here on purpose:
    # BEHIND every hand-written household fastpath above (FreshTable's shopping
    # list, the calendar's tasks, the med log, the household roster), which own
    # their phrasings and must keep them, and AHEAD of _try_code_request,
    # _try_capability_read, _try_registry_read and the model — the loose,
    # declaration-driven matchers that answered "add a torque wrench to the tools
    # list" with a capability blurb, and the model that 503'd on a box with no
    # Ollama. The app is installed and the write either lands or is reported, so
    # there is nothing here for a capability refusal to protect anyone from.
    # Declines (returns None) unless the sentence names a list this build
    # actually keeps for a non-hand-written app. See _try_app_fastpath.
    declared_app = _try_app_fastpath(user_message)
    if declared_app:
        return declared_app
    # Registry-driven READ dispatch: the app_*/prep_*/vault_*/media_*/streaming_*
    # reads the planner would otherwise swallow. Runs after the hand-
    # tuned fastpaths above so those keep precedence, and before the greedy
    # list_devices / RAG / planner paths downstream. See _try_capability_read.
    # An explicit ask to WRITE CODE, ahead of the registry-driven reads and of
    # RAG: "write me a python function ..." matches the capability tables on
    # the word "function" and is answered with a blurb, and reaching RAG it is
    # answered with instructions invented from a library shelf. Declines every
    # household phrasing and stands down entirely when no coding model is
    # configured. See _try_code_request.
    coded = _try_code_request(user_message)
    if coded:
        return coded
    read = _try_capability_read(user_message)
    if read:
        return read
    # Household reads from the real app_data / HA stores: house status,
    # medications, bills, the calendar, tonight's meal. Behind the rules table
    # above (which owns pantry/shopping/alarms/recipes and must keep them) and
    # ahead of the team, whose LLM intent refinement can answer these with the
    # media server, a device list and a thermostat. See
    # puffpai.agents.household_reads.
    household = _try_household_read(user_message)
    if household:
        return household
    try:
        dismissed = _try_alarm_dismiss((user_message or "").lower(),
                                       _get_assistant_tools())
    except Exception:
        dismissed = None
    if dismissed:
        return dismissed
    # "Where did you find that information?" is a question about the PREVIOUS
    # turn, answered from the record of it. Placed here — after every fastpath
    # that owns its own follow-ups (the calendar delete's "which one?", the
    # vault PIN, the meal-plan confirm) and before the retrieval layers — so it
    # can never steal a follow-up and can never reach a new search.
    cited = _try_source_citation(user_message, conversation_id)
    if cited:
        return cited
    # Managing the skills the household approved: listing them, switching one
    # off, taking one away. These TALK about skills and never run one, so they
    # sit with the other reads rather than with the dispatch hook at the very
    # bottom. Removal and disabling ask before they act.
    skills_list = _try_skills_list(user_message)
    if skills_list:
        return skills_list
    skill_off = _try_skill_disable(user_message)
    if skill_off:
        return skill_off
    skill_on = _try_skill_enable(user_message)
    if skill_on:
        return skill_on
    skill_gone = _try_skill_remove(user_message)
    if skill_gone:
        return skill_gone
    # LATE on purpose: every hand-tuned fastpath above has already had its
    # chance, so a real short command ("stop", "louder", "next") is long gone
    # by the time an obvious sentence fragment reaches here. See
    # _try_voice_fragment_guard.
    fragment = _try_voice_fragment_guard(user_message, conversation_history)
    if fragment:
        return fragment
    # Small talk, LATE: every hand-tuned fastpath above has already declined,
    # so "how's the weather going" is long gone by the time we get here and
    # only a bare social utterance is left. Without it, greetings route to
    # `rag` and come back citing knowledge-library documents ("nothing urgent
    # on the health front"). See puffpai.chitchat.
    social = _try_chitchat(user_message)
    if social:
        return social
    # LAST of the appliance's own layers, deliberately: the registry layer
    # below is triggered by declared phrases rather than by a hand-tuned regex,
    # so it is the loosest matcher in this function and must not outrank an
    # ACTION. Placed above _try_alarm_dismiss it would claim "silence my alarm"
    # on the word "alarm" and return the alarm LIST while the alarm kept
    # ringing. Ordering is the second defence here; _CAPREAD_WRITE_INTENT_RE is
    # the first.
    registry = _try_registry_read(user_message)
    if registry:
        return registry
    # THE terminal call. A skill is the least trusted thing
    # on this appliance -- code the appliance did not ship, running against a
    # door the owner opened by hand -- so it answers only after every declared capability
    # has declined, and only on whole-utterance equality with a trigger that
    # collided with nothing in the registry at install time. A skill can never
    # answer "turn off the lights": the installer refuses the trigger, and even
    # if it did not, home.control has already had this turn.
    return _try_skill_dispatch(user_message)


def _try_direct_handle(user_message: str) -> str | None:
    """Try to handle common queries directly without the agent.

    Returns the response string, or None if this message should go
    through the normal agent pipeline.
    """
    from puffpai.router import get_route_category
    category = get_route_category(user_message)
    lower = user_message.lower()

    tools = _get_assistant_tools()

    try:
        # ── Alarm/timer dismiss & delete: deterministic fast-path ──
        # Shared with the pre-team layer (see _try_alarm_dismiss); kept
        # here too so the direct-handle contract is unchanged for callers
        # that reach it on other routes.
        dismissed = _try_alarm_dismiss(lower, tools)
        if dismissed is not None:
            return dismissed

        # ── Weather / news: deterministic fast-paths ──
        # The 7B sometimes ignores the offered tool and asks "which
        # city?" even though the forecast tool knows the location. These
        # are fully determined by the words in the command — call the
        # tool directly, no LLM tool-selection roulette.
        if ('widget' not in lower and 'dashboard' not in lower
                and len(lower) < 80):
            if re.search(r"(?i)\b(?:weather|forecast)\b", lower):
                raw = tools.tool_dict['auto_weather_forecast'].invoke('')
                return _summarize_tool_result(user_message, raw)
            if re.search(r"(?i)\b(?:news|headlines?)\b", lower):
                raw = tools.tool_dict['auto_news_summary'].invoke('')
                return _summarize_tool_result(user_message, raw)

        # ── Home Assistant: list / discover devices ──
        if category == 'home':
            if any(k in lower for k in [
                'what device', 'list device', 'connected device',
                'show device', 'my device', 'discover device',
            ]):
                raw = tools.tool_dict['ha_list_devices'].invoke('')
                return _summarize_tool_result(user_message, raw)

        # ── Security: network scan, block, lockdown ──
        if category == 'security':
            if any(k in lower for k in [
                'scan my network', 'scan the network', 'network scan',
                'who is on my network', 'devices on my network',
                'devices connected to my network',
            ]):
                raw = tools.tool_dict['privacy_scan_network'].invoke('')
                return _summarize_tool_result(user_message, raw)

            if any(k in lower for k in ['zone3 status', 'zone 3 status',
                                         'network security status',
                                         'security status']):
                raw = tools.tool_dict['zone3_status'].invoke('')
                return _summarize_tool_result(user_message, raw)

            # Block device + lockdown combo
            if 'block' in lower and 'lockdown' in lower:
                results = []
                # Find the unknown device IP from the last scan
                scan_raw = tools.tool_dict['privacy_scan_network'].invoke('')
                # Extract IPs that need review from the scan
                import re as _re
                untrusted_ips = _re.findall(
                    r'(\d+\.\d+\.\d+\.\d+).*?(?:unknown|untrusted|needs review|not recognized)',
                    scan_raw, _re.IGNORECASE)
                if not untrusted_ips:
                    # Try reverse pattern
                    untrusted_ips = _re.findall(
                        r'(?:unknown|untrusted|needs review|not recognized).*?(\d+\.\d+\.\d+\.\d+)',
                        scan_raw, _re.IGNORECASE)
                for ip in untrusted_ips:
                    block_result = tools.tool_dict['privacy_block_device'].invoke(ip)
                    results.append(f"Blocked {ip}: {block_result}")
                if not untrusted_ips:
                    results.append("No unknown/untrusted devices found to block.")
                # Enable lockdown
                lockdown_result = tools.tool_dict['privacy_lockdown_mode'].invoke('enable')
                results.append(f"Lockdown mode: {lockdown_result}")
                return _summarize_tool_result(user_message, "\n".join(results))

            # Block device only
            if 'block' in lower and ('device' in lower or 'unknown' in lower):
                scan_raw = tools.tool_dict['privacy_scan_network'].invoke('')
                import re as _re
                untrusted_ips = _re.findall(
                    r'(\d+\.\d+\.\d+\.\d+).*?(?:unknown|untrusted|needs review|not recognized)',
                    scan_raw, _re.IGNORECASE)
                if not untrusted_ips:
                    untrusted_ips = _re.findall(
                        r'(?:unknown|untrusted|needs review|not recognized).*?(\d+\.\d+\.\d+\.\d+)',
                        scan_raw, _re.IGNORECASE)
                results = []
                for ip in untrusted_ips:
                    block_result = tools.tool_dict['privacy_block_device'].invoke(ip)
                    results.append(f"Blocked {ip}: {block_result}")
                if not results:
                    results.append("No unknown/untrusted devices found to block.")
                return _summarize_tool_result(user_message, "\n".join(results))

            # Lockdown mode only
            if 'lockdown' in lower:
                action = 'disable' if any(k in lower for k in ['disable', 'off', 'stop', 'end']) else 'enable'
                raw = tools.tool_dict['privacy_lockdown_mode'].invoke(action)
                return _summarize_tool_result(user_message, raw)

        # ── Media: deterministic fast-paths ──
        # Transport controls and playlist playback are fully determined by
        # the words in the command — no LLM round-trips (which cost seconds
        # even on GPU). Anything ambiguous falls through to the agent.
        if category == 'media':
            from puffpai.media_bridge import get_media_bridge, MediaBridgeError
            import re as _re
            try:
                bridge = get_media_bridge()

                # "play the playlist X [on shuffle]" / "play [the|my] X playlist"
                m = (_re.search(r"\bplay\b.*?\bplaylist\b[\s:]+(?:called\s+|named\s+)?(.+)$", lower)
                     or _re.search(r"\bplay\s+(?:the\s+|my\s+)?(.+?)\s+playlist\b", lower))
                if m:
                    name = _re.sub(r"\b(?:on\s+)?shuffle\b", "", m.group(1))
                    name = name.strip(" .!?,'\"")
                    if name:
                        return bridge.play_playlist(name, shuffle="shuffle" in lower)

                # Transport controls — bridge auto-picks the active session.
                # Confirm a session actually exists first: blind "Paused the
                # music." with nothing playing is a trust leak.
                _transport = _re.search(
                    r"\bpause\b|\b(?:resume|unpause|keep\s+playing)\b|"
                    r"\b(?:next|skip)\b|\b(?:previous|go\s+back|last\s+song|"
                    r"back\s+a\s+(?:song|track))\b|"
                    r"\bstop\b.*\b(?:music|song|playing|playback)\b", lower)
                if _transport and not _re.search(r"\bplaylist\b", lower):
                    if not any(s.now_playing for s in bridge.now_playing()):
                        return ("Nothing is playing right now, so there's "
                                "nothing to control.")
                if _re.search(r"\bpause\b", lower):
                    bridge.playback_control("", "pause")
                    return "Paused the music."
                if _re.search(r"\b(?:resume|unpause|keep\s+playing)\b", lower):
                    bridge.playback_control("", "resume")
                    return "Resumed the music."
                if _re.search(r"\b(?:next|skip)\b", lower) and not _re.search(r"\bplaylist\b", lower):
                    bridge.playback_control("", "next")
                    return "Skipped to the next track."
                if _re.search(r"\b(?:previous|go\s+back|last\s+song|back\s+a\s+(?:song|track))\b", lower):
                    bridge.playback_control("", "previous")
                    return "Went back a track."
                if _re.search(r"\bstop\b.*\b(?:music|song|playing|playback)\b", lower):
                    bridge.playback_control("", "stop")
                    return "Stopped playback."

                # "play [the] music/song/it" (incl. "the now playing music"):
                # if something is paused, resuming is unambiguous
                if (_re.search(r"^\s*play\s*[.!]?\s*$", lower)
                        or _re.search(r"\bplay\s+(?:the\s+)?(?:now\s+playing\s+)?"
                                      r"(?:music|song|it|that)\b", lower)):
                    paused = [s for s in bridge.now_playing()
                              if s.now_playing and s.is_paused]
                    if paused:
                        bridge.playback_control(paused[0].session_id, "resume")
                        return f"Resumed {paused[0].now_playing.display}."

                # "what's playing" / "now playing"
                if _re.search(r"\bwhat(?:'s| is)?\b.*\bplaying\b|\bnow playing\b", lower):
                    return tools.tool_dict['media_now_playing'].invoke('')

                # "what playlists do I have" / "list my playlists"
                if (_re.search(r"\bplaylists\b", lower)
                        and _re.search(r"\b(?:what|list|show|which|all)\b", lower)):
                    return tools.tool_dict['media_list_playlists'].invoke('')

            except MediaBridgeError as exc:
                # Real, actionable error (e.g. "No active Jellyfin player…")
                # — say it fast rather than burning an LLM round on it.
                return str(exc)

        # ── Multi-step compound commands ──
        # Detect multiple action verbs → execute each step directly
        if category == 'home' and _count_actions(lower) >= 3:
            return _handle_compound_command(user_message, lower, tools)

    except Exception as e:
        print(f"[Direct] Direct handler failed: {e}")

    return None  # Fall through to agent


def _count_actions(lower: str) -> int:
    """Count how many distinct action verbs appear in a message."""
    actions = ['dim ', 'turn on', 'turn off', 'set the', 'search ',
               'add ', 'play ', 'find ', 'enable ', 'disable ']
    return sum(1 for a in actions if a in lower)


def _handle_compound_command(user_message: str, lower: str, tools) -> str:
    """Execute a multi-step compound command by parsing and running each step."""
    import re as _re
    results = []

    # Step 1: Light control (dim/brightness)
    light_match = _re.search(
        r'(?:dim|set)\s+(?:the\s+)?(.+?)\s+(?:lights?|bulbs?)\s+(?:to\s+)?(\d+)%?',
        lower)
    if light_match:
        room = light_match.group(1).strip()
        brightness = light_match.group(2)
        try:
            raw = tools.tool_dict['ha_set_light'].invoke(
                f"entity_id=light.{room.replace(' ', '_')}|brightness_pct={brightness}")
            results.append(f"**Lights**: Set {room} lights to {brightness}% brightness")
        except Exception as e:
            results.append(f"**Lights**: Could not set {room} lights — {e}")

    # Step 2: Temperature control
    temp_match = _re.search(r'(?:set\s+)?(?:the\s+)?temperature\s+(?:to\s+)?(\d+)', lower)
    if temp_match:
        temp = temp_match.group(1)
        try:
            raw = tools.tool_dict['ha_set_temperature'].invoke(f"{temp}")
            results.append(f"**Temperature**: Set thermostat to {temp}°F")
        except Exception as e:
            results.append(f"**Temperature**: Could not set temperature — {e}")

    # Step 3: Media search
    media_match = _re.search(
        r'search\s+(?:my\s+)?(?:movie|music|book)\s+(?:library\s+)?(?:for\s+)?(.+?)(?:,|and\s|$)',
        lower)
    if media_match:
        query = media_match.group(1).strip()
        tool_name = 'media_search_movies'
        if 'music' in lower:
            tool_name = 'media_search_music'
        elif 'book' in lower:
            tool_name = 'media_search_books'
        try:
            raw = tools.tool_dict[tool_name].invoke(query)
            results.append(f"**Media Search**: {raw}")
        except Exception as e:
            results.append(f"**Media Search**: Search failed — {e}")

    # Step 4: Shopping list
    shopping_match = _re.search(r'add\s+(.+?)\s+to\s+(?:my\s+)?shopping\s+list', lower)
    if shopping_match:
        item = shopping_match.group(1).strip()
        try:
            raw = tools.tool_dict['app_add_shopping'].invoke(item)
            results.append(f"**Shopping List**: Added {item}")
        except Exception as e:
            results.append(f"**Shopping List**: Could not add {item} — {e}")

    # Step 5: Timer
    timer_match = _re.search(r'set\s+(?:a\s+)?timer\s+(?:for\s+)?(\d+)\s*(min|hour|sec)', lower)
    if timer_match:
        duration = timer_match.group(1)
        unit = timer_match.group(2)
        try:
            raw = tools.tool_dict['app_set_timer'].invoke(f"{duration} {unit}")
            results.append(f"**Timer**: Set for {duration} {unit}")
        except Exception as e:
            results.append(f"**Timer**: Could not set timer — {e}")

    if not results:
        return None  # Nothing matched, fall through to agent

    header = "Here's what I've done for movie night:\n\n"
    return _summarize_tool_result(user_message, header + "\n".join(results))


def _summarize_tool_result(question: str, raw_result: str) -> str:
    """Have the LLM summarize a raw tool result into a natural response.

    The payload MUST carry an ``options`` dict: without one, ollama sizes the
    runner from the model's whole trained context and starts a second
    ``-c 131072`` copy of the model, evicting the chat model to fit it.
    Twelve fastpath call sites (the weather fastpath among them) funnel
    through this function, so it fires on most tool-backed answers.
    """
    import requests as _requests
    try:
        from puffpai.config import get_config
        cfg = get_config()
        _request = {
            "model": cfg.ollama.model,
            "stream": False,
            "keep_alive": _model_options.keep_alive(),
            "options": _model_options.chat_options(),
            "messages": [{
                "role": "user",
                "content": (
                    f"The user asked: \"{question}\"\n\n"
                    f"Here is the raw data:\n{raw_result}\n\n"
                    f"Summarize this data clearly for the user. "
                    f"Use bullet points or numbered lists if appropriate."
                ),
            }],
        }
        # See _ollama_chat: a thinking model otherwise spends its whole token
        # budget reasoning and returns EMPTY content, and the right lever is
        # per family, not the literal "think": False.
        _request.update(_model_options.thinking_control(cfg.ollama.model))
        resp = _requests.post(
            f"{cfg.ollama.url}/api/chat",
            json=_request,
            timeout=60,
        )
        if resp.status_code == 200:
            return resp.json().get('message', {}).get('content', raw_result)
    except Exception as e:
        print(f"[Direct] Summarization failed: {e}")
    return raw_result


# ── Talk-page reasoning-leak / loop guard ────────────────────────────────────
# Mirror of voice.service.guard_reply. The brain occasionally returns its internal
# planning notes ("The user hasn't specified which station...") instead of
# a real reply. Stored verbatim it poisons the conversation and she parrots it
# every turn — the echo loop this guard exists to break (on /chat/send).
# Never surface or store one; break a verbatim repeat. Real fix is brain-side.
_CHAT_LEAK_MARKERS = (
    "need to ask for clarification", "to proceed with any action",
    "incomplete and unclear", "the user's request", "the user wants me",
    "planned step", "a step failed", "step(s):",
    "the user hasn't", "hasn't specified", "haven't specified", "didn't specify",
    "the user mentioned", "the user wants to", "the user's question",
    "the user's input", "need to clarify", "clarify if the user", "clarify which",
    "clarify the user", "need to get the specific", "ask for the specific",
    "to proceed with playing", "unclear and might",
)
_CHAT_LEAK_FALLBACK = "Sorry, I couldn't complete that one. Could you rephrase?"
_CHAT_LOOP_FALLBACK = ("I caught myself repeating that. Let's start fresh — "
                       "what would you like me to do?")


def _guard_chat_reply(text, conv_history=None):
    """Return a safe reply: swap out a reasoning-leak, and break a verbatim repeat
    of the previous assistant turn. Belt-and-suspenders around the brain output."""
    # The trivia tools hand the answer key to the grading layer as a
    # trailing ``[answer=C]``. No routing surface may ever print it.
    text = _strip_trivia_answer(text)
    low = (text or "").lower()
    _leak_marker = next((m for m in _CHAT_LEAK_MARKERS if m in low), None)
    if _leak_marker is not None:
        # The MARKER, never the reply. This ran on every surface, including a
        # turn answered out of an unlocked vault, so those 100 characters
        # could be the decrypted secret itself -- written to journald and to
        # the rotating log. The marker is one of our own literals above and
        # says everything the line was for: which rule fired.
        logger.warning("suppressed chat reasoning-leak: marker %r",
                       _leak_marker)
        return _CHAT_LEAK_FALLBACK
    # Break only on a 3rd identical reply in a row (the real leak-loop spammed it
    # 5+ times). Two in a row is fine — media controls ("stop", "next") repeat.
    if conv_history and len(conv_history) >= 2:
        t = (text or "").strip().lower()
        last2 = [(c.get("assistant") or "").strip().lower()
                 for c in conv_history[-2:]]
        if t and all(t == p for p in last2):
            logger.warning("chat loop detected (3rd identical reply) — breaking out")
            return _CHAT_LOOP_FALLBACK
    return text


# ── Sequenced turns: "do X, then Y" ─────────────────────────────────────────
# Handing an ACTION + read sequence ("turn on the hallway light, then tell me
# the weather") to the planner fails two ways: the second clause can be
# silently dropped, or the reply can say "Hallway Light has been turned on."
# while the entity's last_changed never moves, the planner's PROSE asserting
# a device state change that never happened.
#
# So a sequence that CONTAINS AN ACTION is not handed to the planner at all. It
# is split into ordered clauses; each clause runs through its ordinary path with
# every safety gate intact (an action clause still goes through the Concierge →
# Sentinel veto → Steward); and an action clause's reply is worded from the
# entity state read back AFTER the call, never from what a model said it did.
#
# A sequence with NO action clause is handled here too: each read
# clause runs through its own instant-answer / capability-read path, the ones
# that are correct one clause at a time. The planner is not the path for
# a sequence of reads: it can answer "your pantry is currently empty" for a
# pantry holding one item.
_COMPOUND_TL = threading.local()

#: Action intents whose end state a single entity read can actually settle.
#: set_climate / activate_scene / siren are deliberately absent — their prose
#: comes from the Steward's own reply (concierge._render), not from a model, so
#: there is nothing to fabricate, and "cool" is not a setpoint check.
_COMPOUND_VERIFIABLE_INTENTS = frozenset({"control_device", "control"})

#: Action intents that write APP DATA and whose specialist returns the evidence
#: of the write (``verified``/``count``, read back from the store after it).
#: The device intents above are settled by reading an HA entity; these are
#: settled by reading the store, and the check is the same in kind: a clause is
#: confirmed by what the appliance holds now, never by the fact that a handler
#: was called. ``list_add`` is the only intent in
#: :data:`puffpai.agents.steward.STATE_CHANGING_INTENTS` that writes app data —
#: the others actuate HA (control_device/control, activate_scene, media_play,
#: set_climate, siren, notify_user, announce) or file a consent request that
#: words its own reply (zigbee_pair). Tasks, meals, timers and alarms never
#: reach the Steward at all: they are owned by the ``_try_add_task`` /
#: ``_try_meal_add`` / ``_try_alarm_set`` fastpaths, which write their store
#: directly and report its result.
_COMPOUND_STORE_VERIFIED_INTENTS = frozenset({"list_add"})


def _compound_action_resolution(clause: str):
    """The deterministic Steward resolution for *clause*, if it is an ACTION.

    ``concierge.resolve_intent`` is pure and does no I/O, so this classifies a
    clause without executing anything. Returns None for a read.
    """
    try:
        from puffpai.agents.concierge import resolve_intent
        res = resolve_intent(clause)
    except Exception as exc:
        logger.debug("compound clause resolution failed: %s", exc)
        return None
    if res is None or not getattr(res, "state_changing", False):
        return None
    return res


def _observe_entity_after_action(entity_id: str, action: str):
    """Read an entity back after a service call: ``(friendly_name, state)``.

    One short retry when the state has not settled yet — HA's state machine can
    lag a service call by a few hundred milliseconds, and reporting "still reads
    off" for a light that is mid-transition would be its own dishonesty.
    """
    from puffpai.compound_turns import EXPECTED_STATE
    expected = EXPECTED_STATE.get(str(action or ""))
    name, state = entity_id, None
    for attempt in (0, 1):
        try:
            raw = _get_ha_bridge().get_entity_state(entity_id) or {}
        except Exception as exc:
            logger.debug("compound action read-back failed for %s: %s",
                         entity_id, exc)
            return entity_id, None
        name = ((raw.get("attributes") or {}).get("friendly_name")
                or entity_id)
        state = raw.get("state")
        if expected is None or str(state or "").lower() == expected:
            break
        if attempt == 0:
            time.sleep(0.4)
    return name, state


def _store_verified_clause_reply(team: dict, response):
    """A store-writing clause's reply, allowed through only WITH the evidence.

    The specialist's result dict carries what the store said after the write.
    A reply is repeated only when that dict says the write is verified; when it
    does not, the honest sentence is composed here from the same dict, so a
    clause can never confirm a write this appliance cannot see. (The Concierge
    already words it this way — this is the compound path refusing to take a
    confirmation on trust, the same refusal ``_observe_entity_after_action``
    makes for a device.)
    """
    reply = (team or {}).get("result")
    if not isinstance(reply, dict) or reply.get("list") != "shopping":
        return response          # todo lists / other shapes: unchanged
    from puffpai.agents import shopping_writes
    if reply.get("verified"):
        return response or shopping_writes.reply_for(reply)
    return shopping_writes.reply_for(reply)


def _run_compound_action_clause(clause: str, resolution, requester: str):
    """Execute one ACTION clause and word the reply from the observed state."""
    from puffpai import compound_turns as ct
    # The deterministic untargeted-house gate answers "turn off
    # everything" standalone, from _try_instant_answer — a layer an ACTION
    # clause never reaches, because it is dispatched here instead. Without this
    # the gate's refusal would be replaced by "I couldn't complete ... ask me that
    # one on its own", which is both wrong (there is a real, deliberate answer)
    # and an invitation to retry the thing the gate exists to refuse. The gate
    # itself is untouched; this only makes a compound clause see it.
    gated = _try_untargeted_house_command(clause)
    if gated:
        print("[Chat] Compound clause: untargeted-house gate refused")
        return gated
    if _detect_route(clause) != "agent":
        return None
    result = _try_team_chat(clause, "agent", requester=requester)
    if not result:
        return None
    team = result.get("team") or {}
    if team.get("intent") != resolution.intent:
        # The team answered by some other route (a plan, a clarification). Its
        # prose is a model's account of the turn, not the Steward's reply, so it
        # is not evidence that anything happened. Refuse to repeat it.
        return None
    if resolution.intent in _COMPOUND_STORE_VERIFIED_INTENTS:
        return _store_verified_clause_reply(team, result.get("response"))
    targets = [t for t in (team.get("targets") or []) if isinstance(t, str)]
    if resolution.intent in _COMPOUND_VERIFIABLE_INTENTS and len(targets) == 1:
        action = (resolution.payload or {}).get("action") or resolution.intent
        name, state = _observe_entity_after_action(targets[0], action)
        return ct.observed_action_reply(name, action, state)
    return result.get("response")


def _dedup_sources(sources):
    """Merge clause sources for a compound turn: order kept, repeats dropped.

    A sequenced turn answers each clause with its own reader, so the same
    library document can be cited by two clauses. Identity is the whole
    record (sources are small JSON-shaped dicts), compared on a stable
    serialisation so an unhashable dict still de-duplicates.
    """
    out, seen = [], set()
    for source in (sources or []):
        try:
            key = json.dumps(source, sort_keys=True, default=str)
        except (TypeError, ValueError):
            key = repr(source)
        if key in seen:
            continue
        seen.add(key)
        out.append(source)
    return out


def _merge_clause_sources(entries):
    """Merge PER-CLAUSE sources for a compound turn: order kept, repeats dropped.

    "tell me about the Great Wall of China, then check if any lights are on"
    can come back with ``sources[]`` of 8, and without attribution the reader
    cannot tell which clause any of them belongs to: the Great Wall prose would
    appear to be cited by a car check-engine-light manual that is really the
    SECOND clause's retrieval. The retrieval itself is per-clause; what
    :func:`_dedup_sources` alone loses is the attribution, because it flattens
    both clauses' hits into one anonymous list.

    *entries* is ``(clause_index, clause_text, source)`` in the order the
    clauses were asked. Each dict source comes back with ``clause`` and
    ``clause_index`` added — a shallow copy, so the retriever's own record is
    never mutated — and a record cited by two clauses keeps the FIRST clause
    that cited it, which is what "order kept, repeats dropped" means.
    """
    out, seen = [], set()
    for entry in (entries or []):
        try:
            index, clause, source = entry
        except (TypeError, ValueError):
            index, clause, source = None, None, entry
        try:
            key = json.dumps(source, sort_keys=True, default=str)
        except (TypeError, ValueError):
            key = repr(source)
        if key in seen:
            continue
        seen.add(key)
        if isinstance(source, dict) and clause is not None:
            tagged = dict(source)
            tagged.setdefault('clause', clause)
            tagged.setdefault('clause_index', index)
            out.append(tagged)
        else:
            out.append(source)
    return out


def _compound_read_clause(clause, read_handler):
    """One READ clause of a sequence: a real reader, or an honest decline.

    A sequence clause must never be answered from the encyclopedia: "check
    whats in the pantry, then tell me the network status too" could return the
    real pantry for the first clause and, for the second, an explanation of an
    automotive LIN bus and generic HTTP status codes lifted from the offline
    library, presented as this household's network status. The true half makes
    the fabricated half credible.

    Two things prevent it and this is the second. The first is the cause:
    ``capability_registry._normalize_utterance`` strips the conversational
    tail ("too", "as well", "for me", "now") as well as the ask-prefix, so this
    exact clause reaches its reader in the first place. This is the backstop
    for every phrasing the trim list does not cover: when a clause NAMES an
    appliance read (``mentions_dispatch_subject``) and no reader answers it, say
    so instead of routing it onward.

    A clause that is not about the appliance is untouched and takes its ordinary
    path — "tell me about the moon landing, then whats in the pantry" must still
    answer its first clause from the cited knowledge library.
    """
    try:
        from puffpai import capability_registry as _reg
        subject = _reg.mentions_dispatch_subject(clause)
    except Exception as exc:
        logger.debug("compound clause subject check unavailable: %s", exc)
        subject = None
    if subject is None:
        return read_handler(clause)
    # compound clauses: no conversation id in scope; prompts raised here are unanswerable by design
    answer = _try_instant_answer(clause)
    if answer:
        return answer
    print(f"[Chat] Compound clause: no reader for {subject.id} -> declined")
    return ('I don\'t have a reader for "{}" yet, so I am not going to guess '
            'at it - ask me that one on its own and I will tell you what I '
            'can.'.format(clause))


#: A read clause that says "the list" and names no list. In a sequence it means
#: the list the clause before it just wrote to — "add oat milk to the
#: shopping list, then tell me how many items are on the list". Standalone the
#: same words are ambiguous and are left alone; this only ever fires with a
#: list_add earlier in the SAME turn.
_BARE_LIST_RE = re.compile(
    r"(?i)\b(?:the|that|this|my|our)\s+list\b(?!\s+of\b)")
_NAMED_LIST_RE = re.compile(
    r"(?i)\bshopping\b|\bgrocer(?:y|ies)\b|\bto-?do\b|\btasks?\b|\bchores?\b")


def _resolve_bare_list(clause: str, which: str | None) -> str:
    """Name the list a follow-on clause is asking about, if an earlier clause did.

    Anaphora, not rewriting: only the bare noun phrase is qualified, and only
    with the list the same turn already named out loud. Without this, "then
    tell me how many items are on the list" carries no readable subject, falls
    through every deterministic reader to the model, and can come back "There
    are five items listed." over a list of 31.
    """
    text = clause or ""
    if which not in ("shopping", "todo"):
        return text
    if _NAMED_LIST_RE.search(text) or not _BARE_LIST_RE.search(text):
        return text
    return _BARE_LIST_RE.sub(f"the {which} list", text, count=1)


def _try_compound_request(user_message, read_handler, requester="owner"):
    """Answer a sequenced turn clause by clause, in order. None to stand down.

    *read_handler* answers one non-action clause the way the calling pipeline
    normally would (chat and voice pass their own), so a read clause keeps its
    instant answers, capability reads, RAG and planner exactly as it has them —
    which is precisely why a read-only sequence belongs here rather than on the
    planner: one clause at a time, those readers are already correct.
    """
    if getattr(_COMPOUND_TL, "active", False):
        return None
    try:
        from puffpai import ha_automation_builder as _hab
        if _hab.is_author_request(user_message) \
                or _hab.is_rule_shaped(user_message):
            return None
    except Exception as exc:                        # never break the turn
        logger.debug("automation stand-down check failed: %s", exc)
    from puffpai import compound_turns as ct
    try:
        clauses = ct.split_clauses(user_message)
    except Exception as exc:
        logger.debug("compound split failed: %s", exc)
        return None
    if not clauses:
        return None
    resolutions = [_compound_action_resolution(c) for c in clauses]
    # A sequence with NO action clause is not handed to the planner: that path
    # can FABRICATE household state ("check whats in the pantry, then tell me
    # the network status too" answered "Your pantry is currently empty" over a
    # pantry holding one item). The planner is not the pantry reader; the
    # capability read is. So a read-only
    # sequence goes through the SAME splitter, and each clause through its
    # own instant-answer / registry path (the readers that are already
    # correct one clause at a time), concatenated in the order asked.
    replies = []
    _COMPOUND_TL.active = True
    list_context = [None]
    try:
        for clause, resolution in zip(clauses, resolutions):
            if resolution is not None:
                if resolution.intent == "list_add":
                    list_context[0] = (resolution.payload or {}).get("list")
                answer = _run_compound_action_clause(clause, resolution,
                                                     requester)
            else:
                try:
                    answer = _compound_read_clause(
                        _resolve_bare_list(clause, list_context[0]),
                        read_handler)
                except Exception as exc:
                    logger.debug("compound read clause failed: %s", exc)
                    answer = None
            if not answer:
                if not replies:
                    # Nothing has run yet — leave the whole turn to the
                    # existing path rather than half-doing it.
                    return None
                answer = (f"I couldn't complete \"{clause}\" as part of that — "
                          f"ask me that one on its own and I'll try again.")
            replies.append(str(answer))
    finally:
        _COMPOUND_TL.active = False
    print(f"[Chat] Compound turn: {len(clauses)} clauses executed in order")
    return ct.join_clause_replies(replies)


# Agent Team attribution, half two: wrap every fastpath the dispatcher calls so
# a TRUTHY return records the capability's owning agent. Installed HERE — after
# the last `_try_*` definition and before the first caller runs — as ONE hook
# over the whole chain rather than an edit inside each of the 41 helpers. The
# dispatcher's own body is untouched, so the call order pinned by
# tests/test_instant_answer_precedence.py is unchanged, and the wrapper carries
# `functools.wraps` so `inspect.getsource` still reads the original source.
# Never raises: install_probes swallows its own failures.
_chat_activity.install_probes(sys.modules[__name__])


def _process_chat_query(user_message, conversation_history=None, *,
                        user_id=None, conversation_id=None):
    """
    Full PuffPAI pipeline for a TEXT chat query.
    Returns an enriched dict with response, sources, and suggestions.
    Unlike _process_voice_query, preserves markdown and rich metadata.

    ``user_id`` (multi-user, Increment 1): when the flag is on, the caller's own
    long-term memory is injected into the persona and this turn is recorded into
    the caller's memory. No-op with the flag off (byte-for-byte as today).
    """
    _pin_reply = _ha_pin_intercept(user_message, conversation_id, consume=False)
    if _pin_reply is not None:
        return {'response': _pin_reply, 'sources': [], 'suggestions': [],
                'private': True}
    persona = _augment_persona_with_memory(_system_prompt(), user_id)
    _remember_for_user(user_id, user_message)
    # The agent-bus requester is the AUTHENTICATED principal, so the Archivist
    # scopes Zone-1 (vault RAG) to the real caller — never a default/client id.
    requester = _requester_for(user_id)
    route = _detect_route(user_message, conversation_history)
    # A route line is emitted only once the fastpaths have declined the turn.
    # Printed earlier, "[Chat] Route: rag" would sit immediately before
    # "[Chat] Capability read: app_list_shopping" for the SAME request, a log
    # describing a route that was never taken.
    _route_logged = []

    def _log_route():
        if not _route_logged:
            _route_logged.append(True)
            _log_turn_text(f"[Chat] Route: {route}", "[Chat] Turn text:",
                           user_message)

    # THE post-route attribution hook. One scope around the whole
    # turn, closed in the `finally` below, so every one of this function's eight
    # exits is covered by a single hook instead of 41 edits inside the `_try_*`
    # chain. Who answered is recorded by `chat_activity`'s fastpath probes (see
    # the `install_probes` call after `_try_instant_answer`), by the agent
    # graph's executed-tool list, and by `record_source` on the model paths.
    # Nested clauses of a compound turn JOIN this scope, so a two-clause turn
    # that lands twice on one agent still writes one line for it.
    _chat_activity.begin_turn()
    # See _process_voice_query: one scope, both surfaces.
    _turn_context.begin(conversation_id)
    try:
        # A sequenced turn that CONTAINS AN ACTION is executed clause by clause
        # here, with each action confirmed from the entity state read back after
        # the call. Everything else falls straight through. See
        # _try_compound_request.
        #
        # Each clause's SOURCES ride along with its prose. A read handler that
        # takes only 'response' would answer "tell me about the moon landing,
        # then whats in the pantry" with `sources: []` while the same question
        # standalone returns `zim_fts` citations. The citation is what proves
        # the answer came from the offline library rather than the model.
        #
        # Each clause's hits are recorded WITH the clause that
        # retrieved them, so a two-clause turn's citation list says which half
        # of the question each source backs instead of pooling them anonymously.
        # The retrieval is per-clause (the recursion below passes only
        # `clause`), so this is the attribution, not a change of what is
        # retrieved. See _merge_clause_sources.
        _compound_sources = []
        _compound_clause_no = [0]

        def _compound_read(clause):
            index = _compound_clause_no[0]
            _compound_clause_no[0] += 1
            sub = _process_chat_query(
                clause, conversation_history, user_id=user_id,
                conversation_id=conversation_id) or {}
            for source in (sub.get('sources') or []):
                _compound_sources.append((index, clause, source))
            return sub.get('response')

        compound = _try_compound_request(
            user_message, _compound_read, requester=requester)
        if compound:
            return {'response': compound,
                    'sources': _merge_clause_sources(_compound_sources),
                    'suggestions': []}

        instant = _try_instant_answer(
            user_message, conversation_history=conversation_history,
            conversation_id=conversation_id)
        if instant:
            return {'response': instant, 'sources': [], 'suggestions': []}

        # "search my documents for X": the upload index, rendered, ahead of
        # the planner and the legacy agent. Before the route split, as in
        # _process_voice_query, because "search my docs for X" routes to rag.
        docs = _try_documents_search(user_message)
        if docs:
            _chat_activity.record_capability("knowledge.documents", "fastpath")
            return {'response': docs, 'sources': [], 'suggestions': []}

        _log_route()

        if route == "briefing":
            tools = _get_assistant_tools()
            response = tools.daily_briefing()
            return {'response': response, 'sources': [], 'suggestions': []}

        elif route == "agent":
            # An explicit knowledge-library search is a READ of the FTS/RAG
            # store that the router's "search" keyword drags onto this route.
            # Answer it from retrieval before the planner gets a turn to lose
            # it. Falls through untouched when retrieval finds nothing.
            knowledge = _try_knowledge_search(user_message,
                                              conversation_history, persona)
            if knowledge:
                _chat_activity.record_capability("knowledge.library", "rag")
                return knowledge

            # Product team first — it owns the house. Falls through to the
            # legacy agent whenever the team has no hand for the request.
            team = _try_team_chat(user_message, route, requester=requester,
                                  history=conversation_history)
            if team:
                # An "I can't" from the team is replaced with a sentence that
                # names what was asked, when the request was action-shaped and
                # nothing in the registry claims it. It never
                # claims an ability; it makes the decline honest.
                if isinstance(team, dict):
                    honest = _try_capability_gap(user_message,
                                                 team.get('response'))
                    if honest:
                        team = dict(team, response=honest, sources=[])
                # The team reply's `targets` are resolved HOME ENTITY IDS, so
                # they must not reach the feed. The Concierge routed the turn
                # and is the honest owner of it.
                # TODO(agent-activity): carry the planner's per-step AGENT ids
                # (not its targets) out of _route_via_concierge so a planned
                # turn credits the agents that actually ran the steps.
                _chat_activity.record_source("planner")
                return team

            # Try direct handling first (bypasses agent for common queries)
            direct = _try_direct_handle(user_message)
            if direct:
                _chat_activity.record_source("agent_graph")
                direct = _try_capability_gap(user_message, direct) or direct
                return {'response': direct, 'sources': [], 'suggestions': []}

            # Fall through to full agent for complex multi-step requests
            before_counts = _snapshot_counts(user_message)
            tools = _get_assistant_tools()
            response = tools.run(user_message, conversation_history or [])
            # Attribution for a graph turn: each agent whose tool ACTUALLY ran.
            # Names only — `executed_tool_names()` deliberately drops the graph's
            # result snippets, which hold reply content.
            _chat_activity.record_tools(
                getattr(tools, "executed_tool_names", lambda: [])())
            _chat_activity.record_source("agent_graph")
            response = _verify_and_fix(user_message, response, before_counts)
            # The legacy agent is where "none of the provided functions..."
            # comes from most often. Same rule: replace a refusal, never an
            # answer.
            response = _try_capability_gap(user_message, response) or response
            return {'response': response, 'sources': [], 'suggestions': []}

        elif route == "library":
            response = _get_indexed_libraries_direct()
            return {'response': response, 'sources': [], 'suggestions': [
                "What topics are covered in the TED Talks?",
                "Search the knowledge base for emergency preparedness",
                "Tell me about the medical references available",
            ]}

        else:  # "rag"
            _chat_activity.record_source("rag")
            return _query_ollama_direct(
                user_message, conversation_history, persona, enriched=True)

    except Exception as e:
        print(f"[Chat] Error in processing: {e}")
        return {
            'response': f"Sorry, something went wrong: {e}",
            'sources': [],
            'suggestions': [],
        }
    finally:
        # Never raises (chat_activity swallows its own failures), so the feed
        # can neither change a reply nor mask the error path above it.
        _chat_activity.end_turn(route)


