#  VAULT ENDPOINTS
# ══════════════════════════════════════════════════════════════════════════════

@app.route('/vault/unlock', methods=['POST'])
def vault_unlock():
    """Authenticate a vault session with PIN + optional TOTP (MFA).

    Body: { "pin": "...", "totp_code": "123456" }
    If TOTP is configured, both pin and totp_code are required.
    """
    data = request.json or {}
    pin = data.get('pin', '')
    totp_code = data.get('totp_code', None)

    if not pin:
        return jsonify({'success': False, 'message': 'PIN required'}), 400

    try:
        vault = _get_vault()
        if vault is None:
            return jsonify({'success': False, 'message': 'Vault module unavailable'}), 503

        # Require explicit initialization — don't auto-init on first unlock
        if not vault.is_initialized:
            initialize = data.get('initialize', False)
            if not initialize:
                return jsonify({
                    'success': False,
                    'message': 'Vault not initialized. Send {"pin": "...", "initialize": true} to set up.',
                    'needs_initialization': True,
                }), 400
            vault.initialize(pin)
            logger.info("Vault explicitly initialized with PIN")

        # Use MFA-aware authentication
        session = vault.authenticate_mfa(pin, totp_code)
        # Create a short API-level token that maps to the vault session
        api_token = secrets.token_hex(16)
        _vault_sessions[api_token] = session.session_id

        # One-shot migration: re-encrypt any legacy plaintext files now that we
        # hold the PIN-derived key. Idempotent and safe to run on every unlock.
        try:
            migration = vault.migrate_plaintext_files(session.session_id)
            if migration.get('migrated'):
                logger.info("Vault migration: re-encrypted %d plaintext file(s)",
                            len(migration['migrated']))
            if migration.get('failed'):
                logger.warning(
                    "Vault migration: %d file(s) could not be migrated",
                    len(migration['failed']))
        except Exception as e:
            logger.warning("Vault migration skipped: %s", e)

        return jsonify({
            'success': True,
            'message': 'Vault unlocked' + (' (MFA verified)' if vault.totp_enabled else ''),
            'session_token': api_token,
            'mfa_enabled': vault.totp_enabled,
        })

    except Exception as e:
        logger.warning("Vault unlock failed: %s", e)
        return jsonify({'success': False, 'message': str(e)}), 401


@app.route('/vault/setup-totp', methods=['POST'])
def vault_setup_totp():
    """Set up TOTP MFA for the vault. Requires an active vault session.

    Returns the TOTP secret and provisioning URI for QR code generation.
    """
    data = request.json or {}
    session_token = data.get('session_token', '') or request.headers.get('X-Vault-Token', '')

    if not session_token:
        return jsonify({'success': False, 'message': 'Session token required'}), 401

    try:
        vault = _get_vault()
        if vault is None:
            return jsonify({'success': False, 'message': 'Vault module unavailable'}), 503

        vault_sid = _vault_sessions.get(session_token)
        if not vault_sid:
            return jsonify({'success': False, 'message': 'Invalid session'}), 401

        result = vault.setup_totp(vault_sid)
        return jsonify({
            'success': True,
            'message': 'TOTP MFA configured',
            'secret': result['secret'],
            'provisioning_uri': result['provisioning_uri'],
        })

    except Exception as e:
        logger.error("TOTP setup error: %s", e)
        return jsonify({'success': False, 'message': str(e)}), 500


@app.route('/vault/mfa-status', methods=['GET'])
def vault_mfa_status():
    """Check whether TOTP MFA is enabled for the vault."""
    try:
        vault = _get_vault()
        if vault is None:
            return jsonify({'mfa_enabled': False, 'vault_available': False})
        return jsonify({
            'mfa_enabled': vault.totp_enabled,
            'vault_available': True,
            'vault_initialized': vault.is_initialized,
        })
    except Exception as e:
        return jsonify({'mfa_enabled': False, 'error': str(e)})


@app.route('/vault/lock', methods=['POST'])
def vault_lock():
    """Lock the vault (end the session)."""
    session_token = (request.json or {}).get('session_token', '')
    if not session_token:
        # Also try header
        session_token = request.headers.get('X-Vault-Token', '')

    try:
        vault = _get_vault()
        if vault is None:
            return jsonify({'success': False, 'message': 'Vault module unavailable'}), 503

        vault_sid = _vault_sessions.pop(session_token, None)
        if vault_sid:
            vault.logout(vault_sid)

        return jsonify({'success': True, 'message': 'Vault locked'})

    except Exception as e:
        logger.error("Vault lock error: %s", e)
        return jsonify({'success': False, 'message': str(e)}), 500


def _resolve_vault_session(data=None):
    """Extract and validate a vault session from the request.

    Returns (vault, session_id) or raises an exception.
    """
    if data is None:
        data = request.json or {}

    session_token = data.get('session_token', '') or request.headers.get('X-Vault-Token', '')
    if not session_token:
        return None, None

    vault = _get_vault()
    if vault is None:
        return None, None

    vault_sid = _vault_sessions.get(session_token)
    if vault_sid is None:
        return vault, None

    # Validate that the session is still alive
    try:
        vault._validate_session(vault_sid)
    except Exception:
        _vault_sessions.pop(session_token, None)
        return vault, None

    return vault, vault_sid


@app.route('/vault/scan-pii', methods=['POST'])
def vault_scan_pii():
    """Scan text for PII and return detection results.

    Body: { "text": "My SSN is 123-45-6789 and birthday is March 15, 1990" }
    """
    data = request.json or {}
    text = data.get('text', '')
    if not text:
        return jsonify({'success': False, 'message': 'No text provided'}), 400

    result = _scan_and_redact_message(text)
    return jsonify({
        'success': True,
        'pii_detected': result['pii_detected'],
        'severity': result['severity'],
        'summary': result['pii_summary'],
        'types': result['pii_types'],
        'redacted_text': result['redacted_text'],
        'vaulted': result['vaulted_items'],
    })


@app.route('/vault/contents', methods=['GET'])
def vault_contents():
    """List vault contents (requires unlocked session)."""
    session_token = request.headers.get('X-Vault-Token', '') or request.args.get('session_token', '')

    try:
        vault = _get_vault()
        if vault is None:
            return jsonify({'success': False, 'message': 'Vault module unavailable'}), 503

        vault_sid = _vault_sessions.get(session_token)
        if not vault_sid:
            return jsonify({'success': False, 'message': 'Vault is locked. Unlock first.'}), 403

        # Validate session
        try:
            vault._validate_session(vault_sid)
        except Exception:
            _vault_sessions.pop(session_token, None)
            return jsonify({'success': False, 'message': 'Vault session expired. Re-authenticate.'}), 401

        # List files in vault directory
        items = []
        pii_summary = None
        if vault._vault_dir.exists():
            for fname in sorted(os.listdir(vault._vault_dir)):
                if fname.startswith('.'):
                    continue
                fpath = vault._vault_dir / fname
                try:
                    stat = fpath.stat()
                    item = {
                        'key': fname,
                        'size': stat.st_size,
                        'modified': datetime.fromtimestamp(
                            stat.st_mtime, tz=timezone.utc
                        ).isoformat(),
                    }
                    # Enrich auto-detected PII records with summary info.
                    # The file is encrypted at rest; decrypt with the session
                    # key. Only type names and counts are surfaced, never values.
                    if fname == 'auto_detected_pii.json':
                        try:
                            records = vault.read_secure_session(
                                fname, vault_sid, allow_plaintext=True)
                            if not isinstance(records, list):
                                records = []
                            item['type'] = 'auto_detected_pii'
                            item['record_count'] = len(records)
                            # Summarize PII types found across all records
                            all_types = set()
                            for rec in records:
                                all_types.update(rec.get('items', {}).keys())
                            item['pii_types'] = sorted(all_types)
                            pii_summary = {
                                'total_detections': len(records),
                                'types_found': sorted(all_types),
                            }
                        except Exception:
                            item['type'] = 'auto_detected_pii'
                            item['record_count'] = 0
                    items.append(item)
                except OSError:
                    items.append({'key': fname, 'size': 0, 'modified': None})

        result = {'success': True, 'items': items, 'count': len(items)}
        if pii_summary:
            result['pii_summary'] = pii_summary
        return jsonify(result)

    except Exception as e:
        logger.error("Vault contents error: %s", e)
        return jsonify({'success': False, 'message': str(e)}), 500


@app.route('/vault/store', methods=['POST'])
def vault_store():
    """Store an item in the vault."""
    data = request.json or {}
    key = (data.get('key') or '').strip()
    value = data.get('value')
    item_type = data.get('type', 'text')
    session_token = data.get('session_token', '') or request.headers.get('X-Vault-Token', '')

    if not key:
        return jsonify({'success': False, 'message': 'Key required'}), 400
    if value is None:
        return jsonify({'success': False, 'message': 'Value required'}), 400

    try:
        vault = _get_vault()
        if vault is None:
            return jsonify({'success': False, 'message': 'Vault module unavailable'}), 503

        vault_sid = _vault_sessions.get(session_token)
        if not vault_sid:
            return jsonify({'success': False, 'message': 'Vault is locked. Unlock first.'}), 403

        # Ensure the key has a .json extension for vault storage
        filename = key if key.endswith('.json') else f"{key}.json"
        # Encrypted write only. If the session is locked/expired (no cached key)
        # this raises VaultError — we FAIL EXPLICITLY (423) rather than ever
        # falling back to the plaintext vault.write path.
        try:
            vault.write_secure_session(
                filename, {'value': value, 'type': item_type}, vault_sid)
        except VaultError:
            _vault_sessions.pop(session_token, None)
            return jsonify({
                'success': False,
                'message': 'Vault is locked. Unlock first.',
            }), 423

        return jsonify({'success': True, 'message': f'Stored {key} in vault'})

    except Exception as e:
        logger.error("Vault store error: %s", e)
        return jsonify({'success': False, 'message': str(e)}), 500


#: Vault records that hold a CREDENTIAL PuffPAI uses on the owner's behalf, not
#: a document the owner stores to read later. They are never served back over
#: HTTP: an unlocked vault session is authorisation to USE them, not to export
#: them, and a route that hands a bearer token to a browser turns one stolen
#: session cookie into a permanent credential theft. ``ha_token.json`` is
#: already unreadable here (it is SDK-encrypted, so the DEK read fails), but it
#: is named anyway so the rule does not depend on an encryption accident.
_VAULT_CREDENTIAL_RECORDS = frozenset({'ha_token.json', 'ha_admin_token.json'})


@app.route('/vault/secrets/ha_admin_token', methods=['POST'])
def vault_store_ha_admin_token():
    """One-time owner step: store the ELEVATED Home Assistant token.

    Body ``{"token": "<long-lived access token from an ADMIN HA account>"}``,
    with the caller's existing unlocked vault session carried exactly as every
    other ``/vault/*`` route carries it (``X-Vault-Token`` header or
    ``session_token`` in the body).

    The token is written straight into the vault under the PIN-derived key
    (session tier — there is no unattended read path for it, by design) and is
    never logged, echoed back, or written anywhere else. The response says only
    that it was stored.
    """
    body = request.json or {}
    token = body.get('token')
    session_token = (request.headers.get('X-Vault-Token', '')
                     or body.get('session_token', ''))
    if not isinstance(token, str) or not token.strip():
        return jsonify({'success': False, 'message': 'Token required'}), 400

    vault = _get_vault()
    if vault is None:
        return jsonify({'success': False,
                        'message': 'Vault module unavailable'}), 503
    vault_sid = _vault_sessions.get(session_token)
    if not vault_sid:
        return jsonify({'success': False,
                        'message': 'Vault is locked. Unlock first.'}), 403
    try:
        from puffpai.security.ha_token_source import store_ha_admin_token
        store_ha_admin_token(token, vault_sid)
    except ValueError as exc:
        # Shape rejection. Safe to echo: it never contains the value.
        return jsonify({'success': False, 'message': str(exc)}), 400
    except VaultError:
        _vault_sessions.pop(session_token, None)
        return jsonify({'success': False,
                        'message': 'Vault is locked. Unlock first.'}), 423
    except Exception:
        # Deliberately content-free: an exception raised while handling a
        # credential is the last place to start interpolating strings.
        logger.error("vault: storing the HA admin credential failed")
        return jsonify({'success': False,
                        'message': 'Could not store the credential'}), 500
    return jsonify({'success': True,
                    'message': ('Home Assistant administrator credential '
                                'stored in the vault. I will use it only for '
                                'changes you approve, and only while the '
                                'vault is unlocked.')})


def _vault_credential_session():
    """Resolve the caller's live vault session for a credential route.

    Returns ``(vault, vault_sid, None)`` when the caller holds a live session,
    else ``(None, None, (response, status))``. Same header/body convention as
    every other ``/vault/*`` route; the session is what authorises USING the
    credential, so these routes are exactly as gated as the store route.
    """
    body = request.get_json(silent=True) or {}
    session_token = (request.headers.get('X-Vault-Token', '')
                     or body.get('session_token', ''))
    vault = _get_vault()
    if vault is None:
        return None, None, (jsonify({'success': False,
                                     'message': 'Vault module unavailable'}),
                            503)
    vault_sid = _vault_sessions.get(session_token)
    if not vault_sid:
        return None, None, (jsonify({'success': False,
                                     'message': 'Vault is locked. Unlock '
                                                'first.'}), 403)
    try:
        vault._validate_session(vault_sid)
    except Exception:
        _vault_sessions.pop(session_token, None)
        return None, None, (jsonify({'success': False,
                                     'message': 'Vault session expired.'}),
                            401)
    return vault, vault_sid, None


@app.route('/vault/secrets/ha_admin_token/verify', methods=['POST'])
def vault_verify_ha_admin_token():
    """Is the stored elevated credential actually worth anything?

    Reads the record under the caller's live vault session and asks Home
    Assistant two questions on a throwaway session: does this token
    authenticate (``GET /api/config``), and is the account an administrator
    (a GET on the admin-only script-config endpoint, which answers 404 for an
    admin and 401 for everyone else). Nothing is written in Home Assistant.

    The value never leaves the process: the response carries a *fingerprint*
    (length and last four characters) so the owner can tell two tokens apart
    without the route becoming an export path.
    """
    vault, vault_sid, refusal = _vault_credential_session()
    if refusal is not None:
        return refusal

    from puffpai.security.ha_token_source import resolve_ha_admin_token
    resolution = resolve_ha_admin_token(vault_sid)
    token = resolution.token
    if not token:
        return jsonify({
            'success': True,
            'present': False,
            'fingerprint': None,
            'ha': {'reachable': False, 'valid': False, 'admin': None,
                   'status': None},
            'message': ('No Home Assistant administrator credential is stored '
                        'in the vault yet. ' + resolution.detail),
        })

    fingerprint = {'length': len(token), 'suffix': token[-4:]}
    try:
        from puffpai.ha_provisioning import (verify_admin_credential,
                                             verify_message)
        ha = verify_admin_credential(token)
    except Exception:
        logger.error("vault: verifying the HA admin credential failed")
        return jsonify({'success': False,
                        'message': 'Could not check the credential'}), 500
    finally:
        token = None
        resolution = None

    return jsonify({'success': True, 'present': True,
                    'fingerprint': fingerprint, 'ha': ha,
                    'message': verify_message(ha)})


@app.route('/vault/secrets/ha_admin_token/reveal', methods=['POST'])
def vault_reveal_ha_admin_token():
    """Show the owner the stored credential, once, on an explicit confirmation.

    ``GET /vault/item/ha_admin_token.json`` stays a 403 -- a browsing route must
    never hand a bearer token back. This is the deliberate exception: a live
    vault session PLUS ``{"confirm": true}`` in the body, so nothing reaches it
    by accident and nothing reaches it without the owner's PIN. It exists
    because the owner debugging a 401 needs to compare what PuffPAI holds with
    what Home Assistant shows them, and the alternative is re-pasting blind.

    The value is logged nowhere; the activity feed records only that it
    happened.
    """
    vault, vault_sid, refusal = _vault_credential_session()
    if refusal is not None:
        return refusal

    body = request.get_json(silent=True) or {}
    if body.get('confirm') is not True:
        return jsonify({
            'success': False,
            'message': ('This shows a live Home Assistant administrator '
                        'credential. Send {"confirm": true} to see it.'),
        }), 400

    from puffpai.security.ha_token_source import resolve_ha_admin_token
    resolution = resolve_ha_admin_token(vault_sid)
    if not resolution.token:
        return jsonify({'success': False,
                        'message': resolution.detail}), 404

    logger.warning("ha admin credential revealed to the owner (vault session)")
    try:
        from puffpai.security import consent_requests as _creq
        _creq.log_agent_activity('steward', 'credential_revealed',
                                 'ha_admin_token', 'completed',
                                 {'record': 'ha_admin_token.json'})
    except Exception as exc:                       # pragma: no cover
        logger.debug("credential reveal activity log failed: %s",
                     type(exc).__name__)

    return jsonify({'success': True, 'token': resolution.token})


@app.route('/vault/item/<path:key>', methods=['GET'])
def vault_read_item(key):
    """Read and return the content of a single vault item.

    Handles both the JSON items (manually stored via /vault/store) and
    the raw document files auto-moved here by the PII detection pipeline
    (e.g. ``doc_<id>_filename.txt``).

    Credential records (:data:`_VAULT_CREDENTIAL_RECORDS`) are refused: see the
    note on that set.
    """
    session_token = (request.headers.get('X-Vault-Token', '')
                     or request.args.get('session_token', ''))
    try:
        vault = _get_vault()
        if vault is None:
            return jsonify({'success': False, 'message': 'Vault module unavailable'}), 503

        vault_sid = _vault_sessions.get(session_token)
        if not vault_sid:
            return jsonify({'success': False, 'message': 'Vault is locked. Unlock first.'}), 403

        try:
            vault._validate_session(vault_sid)
        except Exception:
            _vault_sessions.pop(session_token, None)
            return jsonify({'success': False, 'message': 'Vault session expired.'}), 401

        # Resolve the file, trying the key as-is then with .json appended
        safe_name = os.path.basename(key)
        if '..' in safe_name or '/' in safe_name or '\\' in safe_name:
            return jsonify({'success': False, 'message': 'Invalid key'}), 400

        if (safe_name in _VAULT_CREDENTIAL_RECORDS
                or f'{safe_name}.json' in _VAULT_CREDENTIAL_RECORDS):
            logger.warning("vault: refused to serve credential record %s",
                           safe_name)
            return jsonify({
                'success': False,
                'message': ('That record is a credential PuffPAI uses on your '
                            'behalf. It is never displayed or exported.'),
            }), 403

        filepath = vault._vault_dir / safe_name
        if not filepath.exists():
            alt = vault._vault_dir / f"{safe_name}.json"
            if alt.exists():
                filepath = alt
            else:
                return jsonify({'success': False,
                                'message': f'Item {key} not found'}), 404

        # Decrypt the file with the session key. Vault files are AES-256-GCM
        # at rest; read_secure_blob returns the plaintext text (best-effort
        # UTF-8 decode) and tolerates a not-yet-migrated legacy plaintext file
        # during the migration window. A locked/expired session raises VaultError
        # — surface that as 423 rather than leaking ciphertext.
        try:
            raw = vault.read_secure_blob(
                filepath.name, vault_sid, allow_plaintext=True)
        except VaultError:
            _vault_sessions.pop(session_token, None)
            return jsonify({'success': False,
                            'message': 'Vault is locked. Unlock first.'}), 423
        if raw is None:
            return jsonify({'success': False,
                            'message': f'Item {key} not found'}), 404

        suffix = filepath.suffix.lower()
        payload = {
            'success': True,
            'key': safe_name,
            'size': filepath.stat().st_size,
            'modified': datetime.fromtimestamp(
                filepath.stat().st_mtime, tz=timezone.utc).isoformat(),
        }
        if suffix == '.json':
            try:
                payload['content'] = json.loads(raw)
                payload['content_type'] = 'json'
            except json.JSONDecodeError:
                payload['content'] = raw
                payload['content_type'] = 'text'
        else:
            payload['content'] = raw
            payload['content_type'] = 'text'

        logger.info("Vault item read: %s", safe_name)
        return jsonify(payload)

    except Exception as e:
        logger.error("Vault read error: %s", e)
        return jsonify({'success': False, 'message': str(e)}), 500


@app.route('/vault/item/<path:key>', methods=['DELETE'])
def vault_delete(key):
    """Remove an item from the vault."""
    session_token = request.headers.get('X-Vault-Token', '') or request.args.get('session_token', '')

    try:
        vault = _get_vault()
        if vault is None:
            return jsonify({'success': False, 'message': 'Vault module unavailable'}), 503

        vault_sid = _vault_sessions.get(session_token)
        if not vault_sid:
            return jsonify({'success': False, 'message': 'Vault is locked. Unlock first.'}), 403

        try:
            vault._validate_session(vault_sid)
        except Exception:
            _vault_sessions.pop(session_token, None)
            return jsonify({'success': False, 'message': 'Vault session expired.'}), 401

        # Resolve filename — first try as given, then with .json suffix.
        # This lets us delete both JSON items and raw doc_* files.
        safe_name = os.path.basename(key)
        if '..' in safe_name or '/' in safe_name or '\\' in safe_name:
            return jsonify({'success': False, 'message': 'Invalid key'}), 400

        filepath = vault._vault_dir / safe_name
        if not filepath.exists():
            alt = vault._vault_dir / f"{safe_name}.json"
            if alt.exists():
                filepath = alt
            else:
                return jsonify({'success': False,
                                'message': f'Item {key} not found'}), 404

        os.remove(filepath)
        logger.info("Vault item deleted: %s", filepath.name)
        return jsonify({'success': True, 'message': f'Deleted {key} from vault'})

    except Exception as e:
        logger.error("Vault delete error: %s", e)
        return jsonify({'success': False, 'message': str(e)}), 500


# ── Ephemeral secure vault-doc serve (Piece C) — LOOPBACK-ONLY ──────────────
# Decrypted PII must NEVER cross the LAN: these routes serve only to the on-box
# kiosk browser (a loopback peer). A phone hitting :8000 directly is non-loopback
# → the SAME opaque 404 as every other not-servable state. The frontend builds
# the iframe src as ${API}${item.url} so the KIOSK fetches this directly (its
# remote_addr is loopback); it must NOT be routed through the Next proxy.
_VAULT_VIEW_HEADERS = {
    "Cache-Control": "no-store, no-cache, must-revalidate, private",
    "Pragma": "no-cache",
    "Expires": "0",
    "X-Content-Type-Options": "nosniff",
    "Referrer-Policy": "no-referrer",
    # frame-ancestors names the KIOSK ORIGIN (:3003), NOT 'self' — the :3003
    # dashboard frames this cross-origin :8000 iframe. No `sandbox` in the
    # RESPONSE CSP (it breaks Chrome's PDF viewer; the sandbox goes on the iframe
    # ELEMENT, frontend Piece E). No X-Frame-Options on this route.
    "Content-Security-Policy": (
        "default-src 'none'; img-src 'self' data:; style-src 'unsafe-inline'; "
        "frame-ancestors http://localhost:3003 http://127.0.0.1:3003"),
    "Accept-Ranges": "none",
}


def _vault_view_opaque_404():
    """The ONE identical opaque 404 for EVERY not-servable state (unknown /
    expired / exhausted / non-loopback / bad-mime). Never reveals which."""
    return Response(status=404)


@app.route('/vault/view/<token>', methods=['GET'])
def vault_view_get(token):
    from puffpai.security.endpoint_gate import is_loopback_peer
    if not is_loopback_peer(request.remote_addr):
        return _vault_view_opaque_404()
    from puffpai.security import vault_view
    from puffpai.security.vault import VAULT_DOC_MIME_ALLOWLIST
    got = vault_view.fetch(token)
    if not got:
        return _vault_view_opaque_404()
    data, mime = got
    if mime not in VAULT_DOC_MIME_ALLOWLIST:
        return _vault_view_opaque_404()
    # Full 200 with the exact bytes; never a 206/range response.
    resp = Response(data, mimetype=mime)
    for k, v in _VAULT_VIEW_HEADERS.items():
        resp.headers[k] = v
    return resp


@app.route('/vault/view/<token>', methods=['DELETE'])
def vault_view_delete(token):
    from puffpai.security.endpoint_gate import is_loopback_peer
    if not is_loopback_peer(request.remote_addr):
        return _vault_view_opaque_404()
    from puffpai.security import vault_view
    vault_view.clear(token)
    try:
        from puffpai import dashboard_display as dd
        dd.clear_ephemeral_display()
    except Exception:
        pass
    # 204 regardless of whether the token matched (don't reveal existence).
    return Response(status=204)


@app.route('/vault/document', methods=['POST'])
def vault_document_store():
    """Seed/tag a document for the vault display feature.

    Auth: a live ``session_token`` from /vault/unlock, OR an inline ``pin``
    (authenticate + logout around the store). Body:
    ``{owner, doc_type, label, mime, content_b64}``. mime-allowlist-validated;
    content-free audit (the store itself logs doc_id only).
    """
    data = request.json or {}
    owner = (data.get('owner') or '').strip().lower()
    doc_type = (data.get('doc_type') or '').strip().lower()
    label = (data.get('label') or '').strip()
    mime = (data.get('mime') or '').strip().lower()
    content_b64 = data.get('content_b64') or ''

    if not doc_type or not mime or not content_b64:
        return jsonify({'success': False,
                        'message': 'doc_type, mime and content_b64 are required'}), 400
    try:
        from puffpai.security.vault import (
            VAULT_DOC_MIME_ALLOWLIST, VaultError, AuthenticationError)
    except Exception:
        return jsonify({'success': False, 'message': 'Vault module unavailable'}), 503
    if mime not in VAULT_DOC_MIME_ALLOWLIST:
        return jsonify({'success': False, 'message': 'Unsupported document type'}), 415
    try:
        raw = base64.b64decode(content_b64, validate=True)
    except Exception:
        return jsonify({'success': False, 'message': 'Invalid content_b64'}), 400
    if not raw:
        return jsonify({'success': False, 'message': 'Empty content'}), 400
    if len(raw) > 25 * 1024 * 1024:  # defensive cap
        return jsonify({'success': False, 'message': 'Document too large'}), 413

    vault = _get_vault()
    if vault is None:
        return jsonify({'success': False, 'message': 'Vault module unavailable'}), 503
    if not vault.is_initialized:
        return jsonify({'success': False, 'message': 'Vault not initialized'}), 400

    session_token = (data.get('session_token', '')
                     or request.headers.get('X-Vault-Token', ''))
    pin = data.get('pin')
    own_session = False
    vault_sid = None
    try:
        if session_token:
            vault_sid = _vault_sessions.get(session_token)
            if not vault_sid:
                return jsonify({'success': False,
                                'message': 'Vault is locked. Unlock first.'}), 403
            try:
                vault._validate_session(vault_sid)
            except Exception:
                _vault_sessions.pop(session_token, None)
                return jsonify({'success': False,
                                'message': 'Vault session expired.'}), 401
        elif pin:
            try:
                sess = vault.authenticate(pin)
            except (AuthenticationError, VaultError):
                return jsonify({'success': False,
                                'message': 'Authentication failed'}), 401
            vault_sid = sess.session_id
            own_session = True
        else:
            return jsonify({'success': False,
                            'message': 'session_token or pin required'}), 401

        try:
            doc_id = vault.store_document(owner=owner, doc_type=doc_type,
                                          label=label, data=raw, mime=mime,
                                          session_id=vault_sid)
        except VaultError:
            return jsonify({'success': False,
                            'message': 'Could not store document'}), 400
        return jsonify({'success': True, 'doc_id': doc_id})
    finally:
        if own_session and vault_sid:
            try:
                vault.logout(vault_sid)
            except Exception:
                pass
# Sink kinds the served resolver will construct. The client names a KIND; the
# server builds the corresponding authorized ResolveSink itself. The client can
# NEVER hand in a sink object, so it can never smuggle an LLM/persistence sink or
# flip the authorized flag — an unknown kind is refused before the vault is read.
_RESOLVE_SINK_KINDS = frozenset({'form_field', 'user_reveal'})

# resolve_handle status -> HTTP code for /vault/resolve. Fail-closed: any status
# not listed maps to 500.
_RESOLVE_STATUS_HTTP = {
    'OK': 200,
    'VAULT_LOCKED': 423,      # unlock the vault first (not a crash)
    'NOT_FOUND': 404,         # dangling ref OR a ref the caller does not own
    'SINK_REFUSED': 400,      # unauthorized destination (defensive; pre-rejected)
    'STEP_UP_REQUIRED': 401,  # critical tier needs fresh re-auth
    'DISABLED': 403,          # feature flag off
    'RESOLVE_ERROR': 500,     # unexpected failure (fail closed)
}


# ── HIGH/CRITICAL reveal: in-process ephemeral loopback serve ────────────────
# MEDIUM values are returned in the /vault/resolve body for immediate display.
# HIGH/CRITICAL values must never traverse a stateless JSON surface (a body can be
# cached, proxied, or logged upstream), so they are handed back as a one-time,
# loopback-only URL instead: /vault/resolve mints an unguessable token bound to
# the plaintext held in memory, and GET /vault/reveal/<token> serves that
# plaintext EXACTLY ONCE to a loopback peer, then zeroes it. Every property is
# fail-closed:
#   * loopback-only     : a non-127.0.0.1/::1 peer gets 403 and the value is
#                         never served (and the token is NOT consumed);
#   * single-use        : the token is popped on the first successful fetch;
#                         a second fetch -> 404;
#   * short TTL         : entries auto-expire (~45s); expired -> 404 and cleared;
#   * in-memory only    : plaintext is held in a bytearray, never written to disk,
#                         and zeroed on serve / expiry / eviction;
#   * not logged verbatim: the APPLICATION logger never logs the value and never
#                         logs more than a short token prefix. The token DOES
#                         appear in the request URL, so it also reaches werkzeug's
#                         SEPARATE access log — that leak is closed by the access-
#                         log redaction filter in logging_config.py, which
#                         rewrites /vault/(reveal|view)/<token> to <redacted>
#                         before any handler (journald or file) sees it.
# The token IS the capability: it is minted only AFTER /vault/resolve has already
# enforced the unlocked session, owner scope, and (for critical) a fresh step-up,
# so an off-box or cross-principal caller can neither mint nor guess one. This
# mirrors the loopback-only "browser cannot carry the API key" pattern already
# used by spotify_callback.
#
# Loopback is DEFENSE-IN-DEPTH, not an on-box-only guarantee: a same-box reverse
# proxy makes LAN callers appear as 127.0.0.1, so the unguessable, single-use
# token behind the PIN/owner/step-up chain is the real access control. In-transit
# caveat: the token travels in the URL in cleartext to the same-box proxy, so on
# an untrusted LAN a TLS terminator in front of the dashboard is recommended. The
# token-in-URL contract is kept intentionally (it matches the /vault/view show-me
# pattern); this is a flagged caveat, not a change.
_REVEAL_TTL_SECONDS = 45
_REVEAL_STORE_MAX = 256          # bound memory; evict-oldest (zeroed) past this
_reveal_store: dict = {}          # token -> {"buf": bytearray, "exp": float,
#                                             "owner": str, "tier": str}
_reveal_lock = threading.Lock()
_REVEAL_LOOPBACK = frozenset({"127.0.0.1", "::1", "::ffff:127.0.0.1"})


def _reveal_zero(entry):
    """Best-effort scrub of the plaintext bytes held by a reveal entry."""
    try:
        buf = entry.get("buf")
        if isinstance(buf, bytearray):
            for i in range(len(buf)):
                buf[i] = 0
            del buf[:]
    except Exception:
        pass


def _reveal_prune_locked(now):
    """Drop (and zero) every expired entry. Caller MUST hold _reveal_lock."""
    for tok in [t for t, e in _reveal_store.items() if e["exp"] <= now]:
        _reveal_zero(_reveal_store.pop(tok))


def _mint_reveal_token(plaintext, owner, tier):
    """Register *plaintext* for a one-time loopback reveal; return (token, ttl).

    The plaintext is copied into a zeroable bytearray held only in memory. The
    caller is responsible for dropping its own reference to the source str.
    Never logs the value."""
    token = secrets.token_urlsafe(32)           # 256 bits of entropy
    buf = bytearray(plaintext.encode("utf-8"))
    now = time.time()
    with _reveal_lock:
        _reveal_prune_locked(now)
        # Bound memory: evict oldest (nearest-expiry) beyond the cap, zeroing.
        if len(_reveal_store) >= _REVEAL_STORE_MAX:
            oldest = sorted(_reveal_store, key=lambda t: _reveal_store[t]["exp"])
            for tok in oldest[:len(_reveal_store) - _REVEAL_STORE_MAX + 1]:
                _reveal_zero(_reveal_store.pop(tok))
        _reveal_store[token] = {
            "buf": buf, "exp": now + _REVEAL_TTL_SECONDS,
            "owner": owner, "tier": tier,
        }
    return token, _REVEAL_TTL_SECONDS


def _reveal_take(token):
    """Single-use, TTL-checked fetch. Consumes the token atomically. Returns the
    bytearray (caller zeroes it after serving) or None if missing / expired /
    already consumed — all indistinguishable, so no existence info leaks."""
    now = time.time()
    with _reveal_lock:
        _reveal_prune_locked(now)
        entry = _reveal_store.pop(token, None)
    if entry is None:
        return None
    if entry["exp"] <= now:          # belt-and-suspenders (prune already ran)
        _reveal_zero(entry)
        return None
    return entry["buf"]


@app.route('/vault/reveal/<token>', methods=['GET'])
def vault_reveal(token):
    """One-time, loopback-only serve of a HIGH/CRITICAL vaulted plaintext minted
    by POST /vault/resolve. See the reveal-store block above for the full threat
    model. Public (a loopback browser opening the URL cannot carry the API key),
    but gated by loopback + unguessable single-use token + short TTL, and
    feature-gated exactly like the resolver."""
    from puffpai.security.scrub_and_vault import scrub_and_vault_enabled
    # Loopback-only FIRST: an off-box peer must never learn feature state or burn
    # a token — it just gets 403, and the token (if any) is left intact.
    if request.remote_addr not in _REVEAL_LOOPBACK:
        logger.warning("vault_reveal: non-loopback peer refused tok=%s..",
                       (token or '')[:6])
        return jsonify({'error': 'loopback only'}), 403
    # Feature gate: with scrub-and-vault off, no tokens exist and the door is
    # closed entirely.
    if not scrub_and_vault_enabled():
        return ('', 404)
    buf = _reveal_take(token)
    if buf is None:
        # missing / expired / already consumed — indistinguishable, no info leak.
        return ('', 404)
    try:
        # Serve exactly once as raw bytes, never cached, never sniffed.
        resp = app.response_class(bytes(buf),
                                  mimetype='text/plain; charset=utf-8')
        resp.headers['Cache-Control'] = 'no-store'
        resp.headers['X-Content-Type-Options'] = 'nosniff'
        return resp
    finally:
        # Scrub the stored buffer immediately; the transient bytes() copy the
        # response holds is dropped once the response is sent.
        for i in range(len(buf)):
            buf[i] = 0
        del buf[:]


@app.route('/vault/resolve', methods=['POST'])
def vault_resolve():
    """Rehydrate a ``{{vault:<ref-id>}}`` handle (or bare ref-id) to its original
    value on an AUTHORIZED, non-LLM surface — the served front door for
    ``security.scrub_and_vault.resolve_handle``.

    Body::

        { "handle": "{{vault:XXXX}}" | "<ref-id>",   # or "ref_id"
          "sink": "form_field" | "user_reveal",        # REQUIRED
          "field_name": "email",                        # form_field only, optional
          "step_up": {"pin": "..."} | {"otp": "..."} }  # critical tier only

    Session: the caller's EXISTING unlocked vault session, carried exactly as
    every other ``/vault/*`` route carries it (``X-Vault-Token`` header or
    ``session_token`` body). No live unlocked session -> ``VAULT_LOCKED`` (HTTP
    423), never a crash — this endpoint reuses the /vault/unlock flow and never
    performs its own unlock.

    Fail-closed, delegating the security decisions to ``resolve_handle``:

      * feature-gated on ``PUFFPAI_SCRUB_AND_VAULT`` (``DISABLED`` -> 403);
      * the sink is built SERVER-SIDE from the requested KIND — the client can
        never pass a sink object, and an unknown/forbidden kind is refused (400)
        before the vault is touched;
      * ``caller_user_id = _caller_user()`` so a ref the caller does not own
        resolves to ``NOT_FOUND`` (owner scoping lives inside resolve_handle);
      * tiered auth is resolve_handle's: MEDIUM returns the value for display;
        HIGH delivers to the sink only (value NEVER in the body); CRITICAL needs
        a fresh step-up (``STEP_UP_REQUIRED`` -> 401 without it).

    The resolved plaintext is NEVER logged and NEVER written to chat history,
    RAG, or user memory. For HIGH/CRITICAL the value lands only in the
    server-side ephemeral sink (discarded when the request ends) and is not
    returned to the caller — a stateless JSON surface deliberately cannot
    exfiltrate a high/critical secret; that is the most restrictive behavior.
    """
    from puffpai.security.scrub_and_vault import (
        resolve_handle, FormFieldSink, UserRevealSink,
        STATUS_RESOLVE_OK,
    )

    data = request.json or {}

    # 1) Sink kind -> server-created authorized sink. Unknown kind = refuse now,
    #    before the vault is read (never trust a client-supplied sink object).
    sink_kind = str(data.get('sink') or '').strip().lower()
    if sink_kind not in _RESOLVE_SINK_KINDS:
        return jsonify({
            'success': False, 'status': 'SINK_REFUSED',
            'message': ('unknown or unauthorized sink; '
                        'use "form_field" or "user_reveal"'),
        }), 400
    if sink_kind == 'form_field':
        field_name = str(data.get('field_name') or 'field')[:64]
        sink = FormFieldSink(field_name)
    else:  # user_reveal
        sink = UserRevealSink()

    # 2) Handle / ref-id presence check (resolve_handle re-validates shape).
    handle = data.get('handle')
    if handle is None:
        handle = data.get('ref_id')
    if not isinstance(handle, str) or not handle.strip():
        return jsonify({
            'success': False, 'status': 'NOT_FOUND',
            'message': 'handle or ref_id is required',
        }), 400

    # 3) Optional step-up (critical tier). Must be a JSON object if present.
    step_up = data.get('step_up')
    if step_up is not None and not isinstance(step_up, dict):
        return jsonify({
            'success': False, 'status': 'RESOLVE_ERROR',
            'message': 'step_up must be a JSON object',
        }), 400

    # 4) Reuse the EXISTING unlocked vault session (same as every /vault/* route).
    vault = _get_vault()
    if vault is None:
        return jsonify({'success': False,
                        'message': 'Vault module unavailable'}), 503
    session_token = (data.get('session_token', '')
                     or request.headers.get('X-Vault-Token', ''))
    vault_sid = _vault_sessions.get(session_token)
    if vault_sid:
        try:
            vault._validate_session(vault_sid)
        except Exception:
            _vault_sessions.pop(session_token, None)
            vault_sid = None
    if not vault_sid:
        # Fail-closed: no live unlocked session -> locked, not a crash.
        return jsonify({
            'success': False, 'status': 'VAULT_LOCKED',
            'message': 'Vault is locked. Unlock first.',
        }), 423

    # 5) caller identity for owner-scoping (a ref the caller does not own -> 404).
    caller = _caller_user()

    # 6) Resolve. resolve_handle owns feature-gating, tier logic, owner filter,
    #    sink discipline, and never returns/logs a high/critical value.
    result = resolve_handle(
        handle, vault_sid, sink, vault=vault, step_up=step_up,
        require_feature_flag=True, caller_user_id=caller)

    http_code = _RESOLVE_STATUS_HTTP.get(result.status, 500)
    body = {
        'success': result.status == STATUS_RESOLVE_OK,
        'status': result.status,
        'ref_id': result.ref_id,
        'tier': result.tier,
        'type': result.type,
        'label': result.label,
        'delivered': result.delivered,
    }
    if result.status == STATUS_RESOLVE_OK:
        # MEDIUM: resolve_handle populates .value for immediate display — the
        # body carries it, exactly as before (contract unchanged).
        if result.value is not None:
            body['value'] = result.value
        else:
            # HIGH/CRITICAL: resolve_handle delivered the plaintext to the
            # server-side sink ONLY (result.value is None). Rather than discard
            # it (protected-but-unrevealable) or return it in this JSON body
            # (defeats the tier), route it through a one-time, loopback-only
            # ephemeral reveal and hand back an unguessable URL — the value is
            # never in this response.
            secret = getattr(sink, 'value', None)
            if isinstance(secret, str) and secret != '':
                token, ttl = _mint_reveal_token(secret, caller, result.tier)
                # Drop every reference to the plaintext str we still hold so it
                # becomes GC-eligible; the zeroable copy now lives in the store.
                try:
                    sink.value = None
                except Exception:
                    pass
                secret = None
                body['status'] = 'reveal_ready'
                body['success'] = True
                body['reveal_url'] = f'/vault/reveal/{token}'
                body['ttl'] = ttl
            else:
                # Delivered but nothing to reveal (empty value) — no token.
                body['message'] = f'delivered to {sink_kind} sink'
    elif result.detail:
        # detail is content-free (no secret material) by resolve_handle contract.
        body['message'] = result.detail

    # NEVER log the resolved value; status + ref prefix only.
    logger.info("vault_resolve: status=%s ref=%s sink=%s",
                result.status,
                (result.ref_id or '')[:6] + '..' if result.ref_id else '-',
                sink_kind)
    return jsonify(body), http_code


# ══════════════════════════════════════════════════════════════════════════════
#  VAULT RECOVERY-CODE SURFACE
#
#  The recovery code is the safety net that must exist BEFORE Scrub & Vault is
#  enabled: once the vault holds the only copy of scrubbed secrets, a forgotten
#  PIN would otherwise mean permanent, total data loss. Minting a code wraps the
#  EXISTING DEK under a second, recovery-code-derived KEK (vault.generate_recovery
#  _code) — the DEK is unchanged, so all existing ciphertext still decrypts and a
#  rollback stays safe. Either the PIN OR the code can then unlock.
#
#  These routes are DELIBERATELY not gated on PUFFPAI_SCRUB_AND_VAULT: the code is
#  a PREREQUISITE to turning that flag on, so the surface must work with it off.
#  GET /vault/recovery/status returns the has-code boolean the go-live check reads
#  to BLOCK enabling Scrub & Vault until a code is minted.
#
#  Threat model, plainly: minting a recovery code mints a MASTER credential (it
#  can unlock the whole vault and reset the PIN). So generate requires a FRESH PIN
#  re-entry (step-up) on top of the already-unlocked session — the same rate-
#  limited step-up path the resolver's critical tier uses — never session-only.
#  The code is returned in the body exactly once and is NEVER logged or persisted
#  in the clear; regenerating replaces (invalidates) the prior code.
# ══════════════════════════════════════════════════════════════════════════════

@app.route('/vault/recovery/generate', methods=['POST'])
def vault_recovery_generate():
    """Mint a one-time PIN-recovery code for an UNLOCKED vault (owner surface).

    Body::

        { "step_up": {"pin": "..."} }   # or a top-level {"pin": "..."}

    Auth chain (fail-closed at each step):

      * global API-key guard (``_check_api_key`` before_request);
      * an EXISTING unlocked vault session (``X-Vault-Token`` header or
        ``session_token`` body -> ``_vault_sessions`` -> ``_validate_session``);
        no live session -> 423 ``VAULT_LOCKED``;
      * a FRESH step-up proof (PIN re-entry, or a second factor if enrolled),
        verified through the resolver's rate-limited ``_verify_step_up`` — the
        session alone is NOT sufficient; missing/wrong -> 401
        ``STEP_UP_REQUIRED`` and NO code is minted.

    On success the current DEK is wrapped under a fresh recovery-code KEK
    (``vault.generate_recovery_code``); the DEK is unchanged. The plaintext code
    is returned ONCE in the body (never the URL, never a log) with ``no-store``
    caching. Regenerating replaces/invalidates any prior code.
    """
    from puffpai.security.scrub_and_vault import _verify_step_up

    data = request.json or {}

    vault = _get_vault()
    if vault is None:
        return jsonify({'success': False,
                        'message': 'Vault module unavailable'}), 503

    # 1) Existing unlocked session — same carriage as every other /vault/* route.
    session_token = (data.get('session_token', '')
                     or request.headers.get('X-Vault-Token', ''))
    vault_sid = _vault_sessions.get(session_token)
    if vault_sid:
        try:
            vault._validate_session(vault_sid)
        except Exception:
            _vault_sessions.pop(session_token, None)
            vault_sid = None
    if not vault_sid:
        return jsonify({
            'success': False, 'status': 'VAULT_LOCKED',
            'message': 'Vault is locked. Unlock first.',
        }), 423

    # 2) STEP-UP: minting a master credential requires a FRESH PIN re-entry (or a
    #    second factor if enrolled), NOT just the unlocked session. Reuse the
    #    resolver's rate-limited helper verbatim (verifies via vault.authenticate,
    #    which enforces the PIN lockout budget). Accept the resolver's step_up
    #    object, or a top-level pin for a PIN-only box.
    step_up = data.get('step_up')
    if step_up is None and data.get('pin'):
        step_up = {'pin': data.get('pin')}
    if step_up is not None and not isinstance(step_up, dict):
        return jsonify({
            'success': False, 'status': 'STEP_UP_REQUIRED',
            'message': 'step_up must be a JSON object',
        }), 401
    ok, _detail = _verify_step_up(vault, step_up)
    if not ok:
        # _detail is content-free by contract, but never echo anything that
        # could carry the attempted secret; use a fixed message.
        logger.info("vault_recovery_generate: step-up refused")
        return jsonify({
            'success': False, 'status': 'STEP_UP_REQUIRED',
            'message': 'Fresh PIN re-entry required to mint a recovery code.',
        }), 401

    # 3) Mint. generate_recovery_code wraps the SAME DEK (no re-encryption) and
    #    replaces any prior recovery wrap (one-time semantics).
    try:
        code = vault.generate_recovery_code(vault_sid)
    except Exception as e:
        # Never let an exception string carry the code (it is minted last, so
        # this path cannot hold one, but stay defensive).
        logger.error("vault_recovery_generate: mint failed: %s", type(e).__name__)
        return jsonify({'success': False, 'status': 'RECOVERY_ERROR',
                        'message': 'Could not generate a recovery code.'}), 500

    # Go-live interlock: a recovery code now exists, so scrub-and-vault may
    # activate. Invalidate the activation cache so the feature flips LIVE on the
    # next request without a restart. (generate_recovery_code also invalidates;
    # this is a redundant, explicit belt-and-suspenders at the served surface.)
    try:
        from puffpai.security.scrub_and_vault import invalidate_recovery_code_cache
        invalidate_recovery_code_cache()
    except Exception:
        pass

    # Belt-and-suspenders: log that a code was minted, NEVER the value.
    logger.info("vault_recovery_generate: recovery code minted (value not logged)")

    resp = jsonify({
        'status': 'ok',
        'recovery_code': code,
        'message': ('Save this offline now — it is shown ONCE and cannot be '
                    'retrieved again. Generating a new code invalidates this one.'),
    })
    resp.headers['Cache-Control'] = 'no-store'
    resp.headers['X-Content-Type-Options'] = 'nosniff'
    # Drop our local reference so the plaintext code becomes GC-eligible once the
    # response body has been serialized.
    code = None
    return resp, 200


@app.route('/vault/recovery/status', methods=['GET'])
def vault_recovery_status():
    """Report whether a PIN-recovery code is enrolled (no secret, ever).

    Requires the unlocked session (``X-Vault-Token`` header or ``session_token``
    query param) but NOT step-up — it returns no secret material. Response::

        { "has_recovery_code": bool, "generated_at"?: "<iso8601>" }

    The go-live check reads ``has_recovery_code`` to BLOCK enabling Scrub &
    Vault until a code has been minted. The code itself is NEVER returned here.
    """
    vault = _get_vault()
    if vault is None:
        return jsonify({'success': False,
                        'message': 'Vault module unavailable'}), 503

    session_token = (request.headers.get('X-Vault-Token', '')
                     or request.args.get('session_token', ''))
    vault_sid = _vault_sessions.get(session_token)
    if vault_sid:
        try:
            vault._validate_session(vault_sid)
        except Exception:
            _vault_sessions.pop(session_token, None)
            vault_sid = None
    if not vault_sid:
        return jsonify({
            'success': False, 'status': 'VAULT_LOCKED',
            'message': 'Vault is locked. Unlock first.',
        }), 423

    has_code = bool(vault.has_recovery_code)
    body = {'has_recovery_code': has_code}
    if has_code:
        created = vault.recovery_code_created_at
        if isinstance(created, (int, float)):
            body['generated_at'] = datetime.fromtimestamp(
                created, tz=timezone.utc).isoformat()
    return jsonify(body), 200


# ══════════════════════════════════════════════════════════════════════════════
#  KNOWLEDGE BASE ENDPOINTS
# ══════════════════════════════════════════════════════════════════════════════

def _knowledge_libraries_rows():
    """Build the library inventory rows served by /knowledge/libraries.

    Shared by the endpoint and the chat-facing listing so "what libraries do
    you have?" can never disagree with the dashboard again.
    """
    from puffpai.knowledge.fts_index import library_id_for

    manifest = _load_library_manifest()
    zim_libs = _discover_zim_libraries()
    fts_ready = _fts_ready_libraries()

    rag = None
    try:
        rag = _get_dual_zone_rag()
    except Exception:
        pass

    def _chunk_count(collection_name):
        if not rag or not collection_name:
            return 0
        try:
            return rag.client.get_collection(name=collection_name).count()
        except Exception:
            return 0

    # ── ZIM-backed libraries (one row per file on disk) ───────────────
    by_library_id = {}
    zim_titled = set()   # packs whose name came from their own metadata
    for library_id, zim_path in sorted(zim_libs.items()):
        try:
            size = os.path.getsize(zim_path)
        except OSError:
            size = 0
        meta = _zim_metadata(zim_path)
        if meta.get('title'):
            zim_titled.add(library_id)
        by_library_id[library_id] = {
            'name': meta.get('title') or _zim_filename_label(zim_path),
            'description': meta.get('description', ''),
            'language': meta.get('language', ''),
            # The routes accept the library_id as a <collection>, so the
            # dashboard's existing links work without knowing about ZIMs.
            'collection': library_id,
            'library_id': library_id,
            'zone': 'knowledge',
            'chunk_count': 0,
            'size': size,
            'added': '',
            'uploaded_at': '',
            'is_upload': False,
            'source_available': False,
            'source_content_type': '',
            'source': 'zim',
            'fts_ready': library_id in fts_ready,
            'zim_filename': os.path.basename(zim_path),
        }

    # ── ChromaDB collections and user uploads ────────────────────────
    results = list(by_library_id.values())
    for lib in manifest:
        collection = lib.get('collection', '')
        uploaded_at = lib.get('uploaded_at', '')
        zim_path = None if uploaded_at else _resolve_zim_path(collection)

        if zim_path is not None:
            merged_id = library_id_for(zim_path)
            merged = by_library_id.get(merged_id)
            if merged is not None:
                # The pack's own title wins; the manifest's curated name is
                # only better than a filename.
                if merged_id not in zim_titled:
                    merged['name'] = lib.get('library') or merged['name']
                merged['collection'] = collection or merged['collection']
                merged['chunk_count'] = _chunk_count(collection)
                merged['source'] = 'zim'
                continue

        results.append({
            'name': lib.get('library', collection or 'unknown'),
            'collection': collection,
            'library_id': lib.get('library_id', ''),
            'zone': lib.get('zone', 'knowledge'),
            'chunk_count': _chunk_count(collection),
            'size': lib.get('size', 0),
            'added': uploaded_at,
            # Upload/source metadata so the dashboard can offer a
            # "View source" affordance and pick PDF-embed vs text view.
            'uploaded_at': uploaded_at,
            'is_upload': bool(uploaded_at),
            'source_available': bool(lib.get('source_file')),
            'source_content_type': lib.get('content_type') or '',
            'source': 'chromadb',
            'fts_ready': False,
        })

    # ── Uploads that live in the OTHER store ─────────────────────────
    # The manifest loop above lists the knowledge-upload store. A document sent
    # through /ingest/upload lives in the ingestion catalog + the user_uploads
    # collection instead, and so appeared on the Documents page and NOWHERE on
    # the Knowledge page — the same document, invisible through the other door.
    # /ingest/list already reports both stores; this makes the two listings show
    # the same set. Read-only: nothing is migrated and nothing is copied.
    listed = {str(r.get('name') or '').lower() for r in results}
    try:
        from puffpai.upload_index import all_uploaded_docs
        for doc in all_uploaded_docs():
            if doc.get('store') == 'knowledge_upload':
                continue                      # already listed from the manifest
            label = str(doc.get('title') or doc.get('filename') or '')
            if not label or label.lower() in listed:
                continue
            listed.add(label.lower())
            results.append({
                'name': label,
                'collection': 'user_uploads',
                'library_id': str(doc.get('id') or ''),
                'zone': 'knowledge',
                'chunk_count': int(doc.get('chunk_count') or 0),
                'size': 0,
                'added': doc.get('indexed_at') or '',
                'uploaded_at': doc.get('indexed_at') or '',
                'is_upload': True,
                'source_available': False,
                'source_content_type': '',
                # Named for the store it is in, so a caller can tell the two
                # upload doors apart without guessing from the collection.
                'source': 'upload',
                'document_id': str(doc.get('id') or ''),
                'fts_ready': False,
            })
    except Exception as exc:
        logger.debug("ingestion-store uploads unavailable for listing: %s", exc)

    # Publisher titles collide ("Wikipedia" x4); qualify only those.
    _disambiguate_library_names(results)
    return results


@app.route('/knowledge/libraries', methods=['GET'])
def knowledge_libraries():
    """List all knowledge libraries: every ZIM pack plus ChromaDB collections.

    ZIM packs are listed straight off disk (``source: "zim"``) whether or not
    they have ever been ingested, so browsing and full-text search no longer
    depend on the ChromaDB ingestion manifest. Manifest entries that map to a
    discovered ZIM are folded into that ZIM's row (contributing the collection
    name and chunk count) rather than listed twice; the rest — user uploads and
    collections with no ZIM behind them — are listed as ``source: "chromadb"``.
    """
    try:
        results = _knowledge_libraries_rows()
        return jsonify({
            'success': True,
            'libraries': results,
            'total': len(results),
        })
    except Exception as e:
        logger.error("Knowledge libraries error: %s", e)
        return jsonify({'success': False, 'message': str(e)}), 500


def _unified_upload_hits(query, limit=5, exclude=()):
    """Upload hits from BOTH stores, shaped for /knowledge/search.

    ``upload_index.search_uploads`` is the single retrieval path that reads the
    ingestion store (``user_uploads`` + the JSON catalog) AND the
    knowledge-upload store (one collection per document). Both are embedded and
    queried with the shared embedding function, so the scores here and the
    relevance ``_get_rag_context`` reports are the same quantity.

    ``exclude`` is the set of lowercased document names the RAG pass already
    cited, so a document that both paths found is listed once.

    Why this is merged in at the endpoint rather than left to
    ``_get_rag_context``: that function applies a deliberately high upload floor
    (``_RAG_UPLOAD_RELEVANCE_MIN``) because in a CHAT turn a weak upload match
    becomes a false citation. An explicit search is the opposite case — the
    person typed the name of their own file and is owed the honest ranked list.
    The chat floor is left exactly as it was.
    """
    try:
        from puffpai.upload_index import search_uploads
        rows = search_uploads(query, max_results=max(1, int(limit)))
    except Exception as exc:
        logger.debug("unified upload search unavailable: %s", exc)
        return [], []
    skip = {str(name or '').lower() for name in exclude}
    results, sources = [], []
    for row in rows:
        name = str(row.get('filename') or row.get('id') or '')
        if not name or name.lower() in skip:
            continue
        skip.add(name.lower())
        library = f"Your upload: {name}"
        score = min(1.0, max(0.0, float(row.get('score') or 0.0)))
        results.append({'library': library,
                        'text': str(row.get('snippet') or ''),
                        'store': row.get('store', ''),
                        'relevance': round(score, 3)})
        sources.append({
            'library': library,
            'collection': str(row.get('id') or 'user_uploads'),
            'type': 'user_upload',
            'source_type': 'user_upload',
            'title': name,
            'url': '',
            'relevance': round(score, 3),
            'classification': row.get('classification', 'unknown'),
            'file_id': str(row.get('id') or ''),
            'store': row.get('store', ''),
        })
    return results, sources


@app.route('/knowledge/sources', methods=['GET'])
def knowledge_sources():
    """What this build chose, what it downloaded, and what it actually indexed.

    Read-only and offline: the manifest, the shipped registry, the download
    folders and the pack index, reconciled. It opens no socket and starts no
    download - a source that was chosen and never downloaded comes back with
    its size and the command that would fetch it, which is the owner's job to
    run, not this endpoint's.
    """
    try:
        from puffpai.knowledge import build_sources
        return jsonify({'success': True, **build_sources.source_status()})
    except Exception as e:
        logger.error("Knowledge sources error: %s", e)
        return jsonify({'success': False, 'message': str(e)}), 500


@app.route('/knowledge/search', methods=['GET'])
def knowledge_search():
    """Search across the knowledge base AND every document the household sent.

    One searchable truth: the reference libraries, plus both upload stores (see
    :func:`_unified_upload_hits`). A document uploaded on the Documents page
    used to be findable only through ``/ingest/search``, so the Knowledge page
    and the chat citations behaved as if it did not exist.
    """
    query = request.args.get('q', '').strip()
    n_results = min(int(request.args.get('n', '10')), 50)

    if not query:
        return jsonify({'success': False, 'message': 'Query parameter q is required'}), 400

    try:
        # Checked BEFORE the search, not after: "no results" and "nothing here
        # can compare your question to anything" are different answers, and
        # only one of them is the user's problem to fix.
        emb = _embedding_status()
        if not emb.get('available'):
            return jsonify({
                'success': False,
                'results': [],
                'query': query,
                'embeddings': emb,
                'message': emb.get('message', ''),
            }), 503

        rag_result = _get_rag_context(query, n_results=n_results)
        if rag_result is None:
            # No library match is NOT "nothing matched": the household's own
            # documents are a second store, and on a box with uploads and no
            # ZIM packs this branch is the only one there is.
            up_results, up_sources = _unified_upload_hits(query, limit=n_results)
            return jsonify({
                'success': True,
                'results': up_results,
                'sources': up_sources,
                'query': query,
                'count': len(up_results),
                'message': ('' if up_results else
                            'No results found or knowledge base not available'),
            })

        # _get_rag_context returns a dict with context_text and sources
        context_text = rag_result['context_text']
        sources = rag_result.get('sources', [])

        # Parse the context string back into structured results
        results = []
        for chunk in context_text.split('\n\n'):
            chunk = chunk.strip()
            if not chunk:
                continue
            # Format is "[library] text..."
            if chunk.startswith('[') and ']' in chunk:
                bracket_end = chunk.index(']')
                library = chunk[1:bracket_end]
                text = chunk[bracket_end + 1:].strip()
                results.append({
                    'library': library,
                    'text': text,
                })
            else:
                results.append({'library': 'unknown', 'text': chunk})

        # Fold in the uploads the RAG pass did not cite — de-duplicated against
        # the ones it did, by document name, so one document is one row however
        # many doors it can be reached through.
        # The cited name may be the bare filename or the "Your upload: X"
        # label, depending on which store answered; compare on the filename.
        cited = []
        for s in sources:
            if s.get('source_type') != 'user_upload':
                continue
            for value in (s.get('title'), s.get('library')):
                name = str(value or '')
                if name.startswith('Your upload: '):
                    name = name[len('Your upload: '):]
                if name:
                    cited.append(name)
        up_results, up_sources = _unified_upload_hits(
            query, limit=n_results, exclude=cited)
        results.extend(up_results)
        sources = list(sources) + up_sources

        return jsonify({
            'success': True,
            'results': results,
            'sources': sources,
            'query': query,
            'count': len(results),
        })

    except Exception as e:
        logger.error("Knowledge search error: %s", e)
        return jsonify({'success': False, 'message': str(e)}), 500


@app.route('/knowledge/upload', methods=['POST'])
def knowledge_upload():
    """Upload a document to the knowledge base."""
    try:
        # Cap at 50 MB. Checked before touching request.files, which parses
        # (and spools to disk) the whole body; the post-save size check below
        # backstops clients that send no Content-Length.
        max_upload_bytes = 50 * 1024 * 1024
        if request.content_length and request.content_length > max_upload_bytes:
            return jsonify({'success': False,
                            'error': 'file too large',
                            'message': 'File too large (max 50 MB)',
                            'max_mb': 50}), 413

        if 'file' not in request.files:
            return jsonify({'success': False, 'message': 'No file provided'}), 400

        file = request.files['file']
        if not file.filename:
            return jsonify({'success': False, 'message': 'No filename'}), 400

        # What to CALL this document. ``library`` is the
        # long-standing field the dashboard sends and the collection id is
        # derived from it, so it still wins; ``title`` is the one the phone's
        # "Send to Puff" sheet can send. When neither arrives the title is the
        # filename for now and the classifier's label replaces it below — but
        # only then, because a name the household typed is never overwritten.
        explicit_title = (request.form.get('title') or '').strip()
        library_name = (request.form.get('library')
                        or explicit_title or file.filename)
        upload_title = explicit_title or library_name
        zone = request.form.get('zone', 'knowledge')

        # Save to temp file and extract text via file_processor.
        # NOTE: the temp file is retained until the very end of the request
        # (cleaned up in the outer ``finally``) because we may need to copy the
        # ORIGINAL into data/library_sources AFTER the PII screen decides it is
        # safe to keep a plaintext copy — see the retention block below.
        import tempfile
        import mimetypes
        import shutil
        ext = os.path.splitext(file.filename)[1].lower()
        # Best-effort MIME for later inline serving. Prefer the extension
        # guess over a generic browser value: scripted/multipart clients often
        # send application/octet-stream, which would stop the dashboard from
        # rendering PDFs inline.
        _browser_ct = file.content_type
        if _browser_ct in (None, '', 'application/octet-stream'):
            _browser_ct = None
        upload_content_type = (
            _browser_ct
            or mimetypes.guess_type(file.filename)[0]
            or 'application/octet-stream')
        tmp_path = None
        with tempfile.NamedTemporaryFile(delete=False, suffix=ext) as tmp:
            file.save(tmp)
            tmp_path = tmp.name

        # Backstop for uploads that declared no (or a lying) Content-Length.
        # The temp file is removed by the outer ``finally``.
        if os.path.getsize(tmp_path) > max_upload_bytes:
            return jsonify({'success': False,
                            'error': 'file too large',
                            'message': 'File too large (max 50 MB)',
                            'max_mb': 50}), 413

        from puffpai.file_processor import extract_text, SUPPORTED_EXTENSIONS
        if ext in SUPPORTED_EXTENSIONS:
            # Phone photos of schedules/recipes land here — inject the vision
            # escalation so tesseract-garbled images get read by the VLM.
            _vision_fn, _vision_min = _build_vision_fn()
            content, file_meta = extract_text(
                tmp_path, vision_fn=_vision_fn, vision_min_chars=_vision_min)
        else:
            # Fallback: read as text
            with open(tmp_path, 'r', encoding='utf-8', errors='replace') as f:
                content = f.read()
            file_meta = {"extractor": "plaintext_fallback"}

        if not content.strip():
            # Surface WHY extraction failed when the extractor reported it
            # (e.g. "Install python-docx to read .docx files"), instead of a
            # generic "empty" message the user can't act on.
            reason = (file_meta or {}).get('error')
            msg = ('File is empty or could not extract text'
                   if not reason else f'Could not extract text: {reason}')
            return jsonify({'success': False, 'message': msg}), 400

        # ── PII screen (BEFORE chunking) ────────────────────────────────
        # This is the path the dashboard library upload actually uses. Scan
        # the extracted text: high/critical PII (SSN/CC/address/DOB) → the
        # original is encrypted into the Zone 1 Vault and only the REDACTED
        # text is chunked/indexed; medium-only (email/phone/name) → indexed
        # as-is. Fail closed: if the vault is locked/uninitialized while
        # high/critical PII is present, refuse — nothing is indexed.
        from puffpai.ingestion import screen_text_for_pii, PiiVaultRefusal
        pii_detected = False
        pii_vaulted = False
        pii_types: list = []
        try:
            screen = screen_text_for_pii(
                content, file.filename, source="knowledge_upload")
        except PiiVaultRefusal as refusal:
            # 409 Conflict: the request can't proceed in the vault's current
            # (locked) state. Message is actionable and PII-free.
            return jsonify({
                'success': False,
                'message': refusal.message,
                'pii_detected': True,
                'pii_vaulted': False,
            }), 409
        content = screen.text_for_index
        pii_detected = screen.pii_detected
        pii_vaulted = screen.pii_vaulted
        pii_types = screen.pii_types

        # Chunk the content (simple paragraph-based chunking)
        paragraphs = [p.strip() for p in content.split('\n\n') if p.strip()]
        if not paragraphs:
            paragraphs = [content]

        # Create chunks with overlap
        chunks = []
        max_chunk_size = 1000
        for para in paragraphs:
            if len(para) <= max_chunk_size:
                chunks.append(para)
            else:
                # Split long paragraphs
                words = para.split()
                current = []
                current_len = 0
                for word in words:
                    if current_len + len(word) + 1 > max_chunk_size and current:
                        chunks.append(' '.join(current))
                        current = current[-20:]  # overlap
                        current_len = sum(len(w) + 1 for w in current)
                    current.append(word)
                    current_len += len(word) + 1
                if current:
                    chunks.append(' '.join(current))

        # Index into ChromaDB
        try:
            rag = _get_dual_zone_rag()
            collection_name = re.sub(r'[^a-zA-Z0-9_]', '_', library_name)[:60]

            # Ensure collection name is valid for ChromaDB
            if not collection_name or not collection_name[0].isalpha():
                collection_name = 'lib_' + collection_name

            client = rag.client
            # Pin NEW collections to the configured embedder + cosine (reusing
            # the cached query embedder so we don't load a second model). Existing
            # collections are returned untouched — see helper docstring.
            from puffpai.ingestion import get_or_create_upload_collection
            collection = get_or_create_upload_collection(
                client, collection_name,
                extra_metadata={'zone': zone},
                embedding_function=_get_query_embedder(),
            )
            count_before = collection.count()

            ids = [f"{collection_name}_{i}" for i in range(len(chunks))]
            metadatas = [{'library': library_name, 'zone': zone, 'chunk_index': i}
                         for i in range(len(chunks))]

            # ChromaDB has batch size limits, chunk the adds
            batch_size = 100
            for start in range(0, len(chunks), batch_size):
                end = min(start + batch_size, len(chunks))
                collection.add(
                    ids=ids[start:end],
                    documents=chunks[start:end],
                    metadatas=metadatas[start:end],
                    # Explicit vectors — otherwise chroma embeds with whatever
                    # function this collection persisted. See puffpai.embeddings.
                    embeddings=_get_query_embedder()(chunks[start:end]),
                )

            # Verify the chunks actually landed before reporting success.
            # ids are deterministic per collection, so re-uploads overwrite in
            # place — the collection must hold at least `len(chunks)` docs.
            verified_count = collection.count()
            if verified_count < len(chunks):
                logger.error(
                    "Knowledge upload verification failed for %s: expected >= "
                    "%d docs, collection has %d (was %d before)",
                    library_name, len(chunks), verified_count, count_before)
                return jsonify({
                    'success': False,
                    'message': (
                        f'Indexing verification failed: expected {len(chunks)} '
                        f'chunks but the collection reports {verified_count}. '
                        'The document was not fully indexed.'),
                    'collection': collection_name,
                }), 500

            # Update indexed_libraries.json
            manifest_path = os.path.join(_SRC_DIR, 'indexed_libraries.json')
            try:
                with open(manifest_path, 'r') as f:
                    manifest = json.load(f)
            except (FileNotFoundError, json.JSONDecodeError):
                manifest = []

            # ── Retain the original document (source material) ───────────
            # Only when the PII screen did NOT vault the doc. High/critical-PII
            # docs are vaulted (encrypted) and only their REDACTED text is
            # indexed — we must NEVER drop a plaintext original next to the DB.
            # For those, source_file stays null and the redacted Chroma text is
            # the viewable fallback.
            source_file = None
            source_content_type = None
            if not pii_vaulted and tmp_path and os.path.exists(tmp_path):
                try:
                    os.makedirs(_LIBRARY_SOURCES_DIR, exist_ok=True)
                    dest = os.path.join(_LIBRARY_SOURCES_DIR,
                                        collection_name + ext)
                    shutil.copyfile(tmp_path, dest)
                    # Store a repo-root-relative, forward-slash path so it is
                    # portable and resolvable by the serve endpoint.
                    source_file = os.path.relpath(
                        dest, _REPO_ROOT).replace(os.sep, '/')
                    source_content_type = upload_content_type
                except OSError as copy_exc:
                    # Retention is best-effort: a failed copy must not fail the
                    # (already-verified) index. Fall back to reconstructed text.
                    logger.warning(
                        "Could not retain source for %s: %s",
                        collection_name, copy_exc)
                    source_file = None
                    source_content_type = None

            # Remove existing entry if re-uploading
            manifest = [m for m in manifest if m.get('collection') != collection_name]
            manifest.append({
                'library': library_name,
                'title': upload_title,
                'collection': collection_name,
                'zone': zone,
                'chunks': len(chunks),
                'uploaded_at': datetime.now(timezone.utc).isoformat(),
                'source_file': source_file,
                'content_type': source_content_type,
            })

            with open(manifest_path, 'w') as f:
                json.dump(manifest, f, indent=2)

            logger.info("Uploaded library %s: %d chunks (verified %d docs)",
                        library_name, len(chunks), verified_count)

            # Proactive suggestion pass — classify what just arrived and queue
            # a nudge for the dashboard. Runs on a daemon thread so the upload
            # response doesn't wait on a (possibly cold) model, and never
            # executes anything: the user accepts or dismisses. When the PII
            # screen redacted the document, `content` is the REDACTED text —
            # which is exactly what the classifier should see.
            try:
                from puffpai import suggestions as _suggestions

                def _suggest_llm(messages):
                    resp = _ollama_chat(messages, timeout=180, num_predict=2048)
                    resp.raise_for_status()
                    return resp.json().get('message', {}).get('content', '')

                # The same pass writes the title back (only
                # when the household did not name the file themselves) and
                # says ONE offer out loud for a recipe or a dated schedule.
                _named_by_user = bool(
                    explicit_title or (request.form.get('library') or '').strip())

                def _store_title(title, _collection=collection_name):
                    _set_library_title(_collection, title)

                _suggestions.queue_suggestion_async(
                    doc_name=library_name, text=content,
                    collection=collection_name, zone=zone,
                    llm_chat=_suggest_llm,
                    title=upload_title if _named_by_user else '',
                    upload_id=collection_name,
                    on_title=_store_title)
            except Exception as suggest_exc:
                logger.warning("Could not start suggestion pass for %s: %s",
                               library_name, suggest_exc)

            return jsonify({
                'success': True,
                'message': f'Uploaded {library_name}',
                'title': upload_title,
                'chunks': len(chunks),
                'indexed_count': verified_count,
                'collection': collection_name,
                'pii_detected': pii_detected,
                'pii_vaulted': pii_vaulted,
                'pii_types': pii_types,
            })

        except Exception as exc:
            logger.error("Knowledge upload indexing error: %s", exc)
            return jsonify({'success': False, 'message': f'Indexing failed: {exc}'}), 500

    except Exception as e:
        logger.error("Knowledge upload error: %s", e)
        return jsonify({'success': False, 'message': str(e)}), 500
    finally:
        # Always remove the staging temp file, on every return path. The
        # retained original (if kept) is a COPY in data/library_sources.
        if locals().get('tmp_path'):
            try:
                os.unlink(tmp_path)
            except OSError:
                pass


@app.route('/knowledge/suggestions/pending', methods=['GET'])
def knowledge_suggestions_pending():
    """Suggestions waiting on the user. Expiry is applied on read."""
    from puffpai import suggestions as _suggestions
    return jsonify({'suggestions': _suggestions.list_pending()})


@app.route('/knowledge/suggestions/<sid>/accept', methods=['POST'])
def knowledge_suggestion_accept(sid):
    """Accept a suggestion and hand back its action params.

    Accepting NEVER executes: a calendar_import returns its candidate events
    for the dashboard's preview-confirm flow, where the user still approves
    each event before it is written.
    """
    from puffpai import suggestions as _suggestions
    record, err = _suggestions.accept(sid)
    if err == 'not_found':
        return jsonify({'error': 'Unknown suggestion'}), 404
    if err == 'not_pending':
        return jsonify({'error': f"Suggestion already {record['status']}",
                        'status': record['status']}), 409
    return jsonify({'suggestion': record})


@app.route('/knowledge/suggestions/<sid>/dismiss', methods=['POST'])
def knowledge_suggestion_dismiss(sid):
    from puffpai import suggestions as _suggestions
    record, err = _suggestions.dismiss(sid)
    if err == 'not_found':
        return jsonify({'error': 'Unknown suggestion'}), 404
    if err == 'not_pending':
        return jsonify({'error': f"Suggestion already {record['status']}",
                        'status': record['status']}), 409
    return jsonify({'ok': True})


# ── Naming an upload ──────────────────────────────────────
#
# The collection id is IMMUTABLE: it keys the ChromaDB collection, the retained
# source file and every chunk id, so renaming it would orphan all three. What
# the household changes is the display title, which is the only thing they ever
# see or say.

#: A title is a name, not a note.
_TITLE_MIN_CHARS = 1
_TITLE_MAX_CHARS = 80


def _set_library_title(collection_id: str, title: str) -> dict | None:
    """Write a display title into the upload manifest. Returns the entry."""
    manifest = _load_library_manifest()
    target = None
    for entry in manifest:
        if isinstance(entry, dict) and entry.get('collection') == collection_id:
            target = entry
            break
    if target is None:
        return None
    target['title'] = str(title)
    try:
        with open(os.path.join(_SRC_DIR, 'indexed_libraries.json'), 'w') as f:
            json.dump(manifest, f, indent=2)
    except OSError as exc:
        logger.warning("Could not write title for %s: %s", collection_id, exc)
        return None
    return target


def _match_upload_entry(target: str) -> dict | None:
    """One manifest entry named by collection id, filename or current title.

    Also accepts the on-disk id the image list reports (``<collection><ext>``),
    so ``PUT /ingest/<upload_id>/title`` and the picker agree on what an id is.
    """
    needle = str(target or '').strip().lower()
    if not needle:
        return None
    stem = os.path.splitext(needle)[0]
    entries = [e for e in _load_library_manifest() if isinstance(e, dict)]
    for field in ('collection', 'library', 'title'):
        for entry in entries:
            value = str(entry.get(field) or '').strip().lower()
            if value and value in (needle, stem):
                return entry
    return None


def _newest_upload_entry() -> dict | None:
    """The most recently uploaded manifest entry, or None."""
    entries = [e for e in _load_library_manifest()
               if isinstance(e, dict) and e.get('collection')]
    if not entries:
        return None
    return sorted(entries, key=lambda e: str(e.get('uploaded_at') or ''))[-1]


def _upload_record(entry: dict) -> dict:
    """The public shape of a renamed upload."""
    return {
        'id': entry.get('collection'),
        'collection': entry.get('collection'),
        'filename': entry.get('library'),
        'title': entry.get('title') or entry.get('library'),
        'store': 'knowledge_upload',
    }


def _rename_upload(target: str, title: str) -> tuple[dict | None, str | None]:
    """Retitle one upload. Returns ``(record, error)``.

    Errors are ``'invalid'`` (a title nobody could have meant) and
    ``'not_found'``.
    """
    title = ' '.join(str(title or '').split())
    if not (_TITLE_MIN_CHARS <= len(title) <= _TITLE_MAX_CHARS):
        return None, 'invalid'
    entry = _match_upload_entry(target)
    if entry is not None:
        updated = _set_library_title(entry.get('collection'), title)
        if updated is None:
            return None, 'not_found'
        return _upload_record(updated), None
    # Not in the knowledge-upload manifest — it may be a catalog document from
    # the other upload store, which keeps its own title beside its id.
    try:
        from puffpai import ingestion
        if ingestion.set_doc_title(str(target or '').strip(), title):
            return ({'id': str(target).strip(), 'collection': None,
                     'filename': str(target).strip(), 'title': title,
                     'store': 'ingestion'}, None)
    except Exception as exc:
        logger.warning("Catalog rename failed for %s: %s", target, exc)
    return None, 'not_found'


def _rename_upload_response(target: str):
    """Shared handler for the two rename routes."""
    body, err = _json_object_body()
    if err:
        return err
    record, error = _rename_upload(target, body.get('title'))
    if error == 'invalid':
        return jsonify({'error': 'A title is 1 to 80 characters.'}), 400
    if error == 'not_found':
        return jsonify({'error': f'No upload named {target}'}), 404
    return jsonify({'ok': True, 'document': record})


@app.route('/knowledge/library/<collection_id>', methods=['PUT'])
def knowledge_library_rename(collection_id):
    """Rename ONE upload: ``{"title": "Fall soccer"}``.

    The collection id in the URL does not change — only what it is called.
    """
    return _rename_upload_response(collection_id)


@app.route('/ingest/<upload_id>/title', methods=['PUT'])
def ingest_upload_rename(upload_id):
    """Alias of :func:`knowledge_library_rename` for upload ids."""
    return _rename_upload_response(upload_id)


@app.route('/knowledge/library/<name>', methods=['DELETE'])
def knowledge_delete(name):
    """Remove a knowledge library."""
    try:
        # Find the collection in the manifest
        manifest_path = os.path.join(_SRC_DIR, 'indexed_libraries.json')
        try:
            with open(manifest_path, 'r') as f:
                manifest = json.load(f)
        except (FileNotFoundError, json.JSONDecodeError):
            manifest = []

        # Find matching entry (by library name or collection name)
        target = None
        for entry in manifest:
            if entry.get('library') == name or entry.get('collection') == name:
                target = entry
                break

        if target is None:
            return jsonify({'success': False, 'message': f'Library {name} not found'}), 404

        collection_name = target['collection']

        # Delete from ChromaDB
        try:
            rag = _get_dual_zone_rag()
            rag.client.delete_collection(name=collection_name)
        except Exception as exc:
            logger.warning("Could not delete ChromaDB collection %s: %s",
                           collection_name, exc)

        # Remove the retained source file (if any). Confined to
        # _LIBRARY_SOURCES_DIR so a tampered manifest path can't delete
        # arbitrary files.
        src_rel = target.get('source_file')
        if src_rel:
            try:
                src_abs = os.path.realpath(os.path.join(_REPO_ROOT, src_rel))
                sources_root = os.path.realpath(_LIBRARY_SOURCES_DIR)
                if (os.path.commonpath([src_abs, sources_root]) == sources_root
                        and os.path.isfile(src_abs)):
                    os.remove(src_abs)
            except (OSError, ValueError) as exc:
                logger.warning("Could not delete source file for %s: %s",
                               collection_name, exc)

        # Remove from manifest
        manifest = [m for m in manifest
                    if m.get('collection') != collection_name]
        with open(manifest_path, 'w') as f:
            json.dump(manifest, f, indent=2)

        logger.info("Deleted library: %s (collection: %s)", name, collection_name)
        return jsonify({
            'success': True,
            'message': f'Deleted library {name}',
        })

    except Exception as e:
        logger.error("Knowledge delete error: %s", e)
        return jsonify({'success': False, 'message': str(e)}), 500


def _find_manifest_entry(name: str):
    """Return the manifest entry matching *name* (library or collection), or None."""
    manifest_path = os.path.join(_SRC_DIR, 'indexed_libraries.json')
    try:
        with open(manifest_path, 'r') as f:
            manifest = json.load(f)
    except (FileNotFoundError, json.JSONDecodeError):
        return None
    for entry in manifest:
        if entry.get('library') == name or entry.get('collection') == name:
            return entry
    return None


def _reconstruct_collection_text(collection_name: str) -> str | None:
    """Rebuild a document's text from its ChromaDB chunks, ordered by chunk_index.

    Returns the joined text, or None if the collection can't be read. Used as the
    viewable fallback for uploads that have no retained original on disk (e.g.
    PII-vaulted docs, or the three pre-existing uploads indexed before source
    retention existed).
    """
    try:
        rag = _get_dual_zone_rag()
        collection = rag.client.get_collection(name=collection_name)
        data = collection.get(include=['documents', 'metadatas'])
    except Exception as exc:
        logger.warning("Could not read collection %s for reconstruction: %s",
                       collection_name, exc)
        return None

    docs = data.get('documents') or []
    metas = data.get('metadatas') or []
    # Pair each chunk with its index metadata; chunks missing chunk_index sort
    # last but keep insertion order among themselves.
    paired = []
    for i, doc in enumerate(docs):
        meta = metas[i] if i < len(metas) else {}
        idx = meta.get('chunk_index') if isinstance(meta, dict) else None
        paired.append(((idx is None, idx if idx is not None else i), doc))
    paired.sort(key=lambda p: p[0])
    return '\n\n'.join(doc for _, doc in paired if doc)


@app.route('/knowledge/library/<name>/source', methods=['GET'])
def knowledge_serve_source(name):
    """Serve the original uploaded document for a user-uploaded library.

    If the manifest entry retains a ``source_file`` (no high/critical PII), the
    original is streamed inline with its stored Content-Type — this lets the
    dashboard embed PDFs directly in an <embed>/<iframe>. Because embedded
    media elements cannot send an Authorization header, this endpoint is in
    ``_PUBLIC_ENDPOINTS`` (same treatment as knowledge_serve_asset) and stays
    CORS-restricted to localhost via ``add_cors``.

    When no original was retained (PII-vaulted docs, or pre-retention uploads),
    OR when ``?format=text`` is passed, the document text is reconstructed from
    the Chroma collection (chunks ordered by chunk_index) and returned as JSON
    ``{success, text, note}``.
    """
    force_text = request.args.get('format', '').lower() == 'text'

    entry = _find_manifest_entry(name)
    if entry is None:
        return jsonify({'success': False,
                        'message': f'Library {name} not found'}), 404

    collection_name = entry.get('collection', '')
    source_rel = entry.get('source_file')

    # Stream the retained original unless the caller explicitly wants text.
    if source_rel and not force_text:
        try:
            src_abs = os.path.realpath(os.path.join(_REPO_ROOT, source_rel))
            sources_root = os.path.realpath(_LIBRARY_SOURCES_DIR)
            within = os.path.commonpath([src_abs, sources_root]) == sources_root
        except ValueError:
            within = False
        if within and os.path.isfile(src_abs):
            mime = entry.get('content_type') or 'application/octet-stream'
            resp = send_file(src_abs, mimetype=mime, as_attachment=False,
                             download_name=os.path.basename(src_abs))
            resp.headers['Cache-Control'] = 'private, max-age=3600'
            return resp
        # Manifest points at a missing file — fall through to text.
        logger.warning("Retained source missing for %s; using text fallback",
                       collection_name)

    # Text fallback: reconstruct from ChromaDB chunks.
    if not collection_name:
        return jsonify({'success': False,
                        'message': 'No collection for this library'}), 404
    text = _reconstruct_collection_text(collection_name)
    if text is None:
        return jsonify({
            'success': False,
            'message': 'Source document is not available for this library.',
        }), 404
    note = ('Reconstructed from the indexed text — the original file was not '
            'retained for this document.')
    return jsonify({'success': True, 'text': text, 'note': note})


@app.route('/knowledge/rescan_pii', methods=['POST'])
def knowledge_rescan_pii():
    """Remediate documents indexed BEFORE the PII screen existed.

    Iterates user-upload collections (manifest entries whose collection name
    does not start with ``kiwix_`` and that carry an ``uploaded_at`` — the
    shape written by ``knowledge_upload``). For each, scans every chunk; for
    chunks holding high/critical PII (SSN/CC/address/DOB):

      * vault UNLOCKED  → encrypt the ORIGINAL chunk text into the Zone 1
        Vault, append a PII record, then replace the chunk document in place
        with its REDACTED text (``collection.update`` keeps the same ids).
      * vault LOCKED    → change NOTHING; the collection is reported under
        ``collections_needing_attention``.

    Optional JSON body (all fields optional; no/empty body = scan every
    upload collection and really remediate when the vault is unlocked):

      * ``collections`` (list[str]) — restrict processing to these collection
        names. Only names inside the non-``kiwix_``/``uploaded_at`` manifest
        subset are eligible; any requested name outside that subset (unknown,
        kiwix, or legacy) is NEVER processed and is echoed back under
        ``skipped_unknown``. Omit to process the whole subset.
      * ``dry_run`` (bool, default ``false``) — preview mode. Scans and builds
        the full report (``pii_found``, ``severity``, ``needs_attention``) but
        performs NO vault writes and NO ``collection.update`` regardless of
        vault state; the response carries ``"dry_run": true`` and every row's
        ``remediated`` stays 0.

    Fail closed: the request body is strictly validated (wrong types → 400,
    no mutation). The unlock state is checked ONCE up front, and each chunk is
    vaulted BEFORE it is redacted, so a locked vault can never leave an
    unredacted chunk deleted or a redaction without a vaulted original. Kiwix
    reference collections are never touched. Always returns a JSON report.
    """
    from puffpai.ingestion import _vault_original_text, PiiVaultRefusal
    from puffpai.security.pii_classifier import PIIClassifier

    # Parse the OPTIONAL scoping body. Use silent parsing so a missing body or
    # a missing Content-Type is treated as "no body" (current behavior), not an
    # error. Validate strictly and fail closed: any malformed field aborts with
    # 400 BEFORE the scan/remediation loop, so a typo can never trigger a wider
    # or unintended mutation.
    body = request.get_json(silent=True)
    if body is None:
        body = {}
    if not isinstance(body, dict):
        return jsonify({'success': False,
                        'message': 'request body must be a JSON object'}), 400

    dry_run = body.get('dry_run', False)
    if not isinstance(dry_run, bool):
        return jsonify({'success': False,
                        'message': "'dry_run' must be a boolean"}), 400

    requested_collections = body.get('collections', None)
    if requested_collections is not None and not (
        isinstance(requested_collections, list)
        and all(isinstance(c, str) for c in requested_collections)
    ):
        return jsonify({'success': False,
                        'message': "'collections' must be a list of strings"}), 400

    try:
        manifest_path = os.path.join(_SRC_DIR, 'indexed_libraries.json')
        try:
            with open(manifest_path, 'r') as f:
                manifest = json.load(f)
        except (FileNotFoundError, json.JSONDecodeError):
            manifest = []

        # User uploads only: skip kiwix reference libraries and any legacy
        # entry without the knowledge_upload shape.
        targets = [
            m for m in manifest
            if isinstance(m, dict)
            and isinstance(m.get('collection'), str)
            and not m['collection'].startswith('kiwix_')
            and 'uploaded_at' in m
        ]

        # Optional scoping: restrict to caller-named collections. Only names in
        # the eligible manifest subset above are processed; every other
        # requested name (unknown, kiwix, or legacy) is reported back and never
        # touched.
        skipped_unknown = []
        if requested_collections is not None:
            eligible_names = {m['collection'] for m in targets}
            requested_set = set(requested_collections)
            skipped_unknown = sorted(requested_set - eligible_names)
            targets = [m for m in targets if m['collection'] in requested_set]

        active_vault = _get_vault()
        vault_unlocked = bool(active_vault is not None and active_vault.has_live_session)

        rag = _get_dual_zone_rag()
        classifier = PIIClassifier()

        report = []
        needs_attention = []

        for entry in targets:
            collection_name = entry['collection']
            row = {
                'collection': collection_name,
                'library': entry.get('library'),
                'scanned': 0,
                'pii_found': 0,
                'remediated': 0,
                'severity': None,
                'needs_attention': False,
                'error': None,
            }
            try:
                collection = rag.client.get_collection(name=collection_name)

                # First pass: find chunks with high/critical PII.
                # Retrieve in batches so a large collection (some hold ~10k
                # chunks) is never loaded into memory all at once; only the
                # flagged chunks are retained across batches.
                affected = []  # (chunk_id, original_doc, detection, redacted)
                _RESCAN_BATCH = 300
                offset = 0
                while True:
                    batch = collection.get(
                        include=['documents'],
                        limit=_RESCAN_BATCH,
                        offset=offset,
                    )
                    ids = batch.get('ids') or []
                    documents = batch.get('documents') or []
                    if not ids:
                        break
                    row['scanned'] += len(ids)
                    for chunk_id, doc in zip(ids, documents):
                        if not doc:
                            continue
                        redacted, detection = classifier.redact_pii(doc)
                        if detection.has_pii and detection.severity in ('high', 'critical'):
                            affected.append((chunk_id, doc, detection, redacted))
                    if len(ids) < _RESCAN_BATCH:
                        break
                    offset += len(ids)

                row['pii_found'] = len(affected)
                if affected:
                    row['severity'] = max(
                        (d.severity for _, _, d, _ in affected),
                        key=lambda s: 0 if s == 'high' else 1)

                if not affected:
                    report.append(row)
                    continue

                if dry_run or not vault_unlocked:
                    # Change NOTHING for this collection. A locked vault still
                    # flags the collection as needing attention (a real run
                    # could not remediate it either); a dry run against an
                    # unlocked vault simply reports what WOULD be remediated
                    # with remediated == 0.
                    if not vault_unlocked:
                        row['needs_attention'] = True
                        needs_attention.append(collection_name)
                    report.append(row)
                    continue

                # Remediate: vault original THEN redact in place, per chunk.
                for chunk_id, doc, detection, redacted in affected:
                    try:
                        _vault_original_text(
                            doc, detection,
                            filename=f"{collection_name}.txt",
                            file_id=str(chunk_id),
                            vault=active_vault,
                            source="knowledge_rescan")
                    except PiiVaultRefusal:
                        # Vault became locked mid-run: stop remediating this
                        # collection, leave remaining chunks untouched.
                        row['needs_attention'] = True
                        if collection_name not in needs_attention:
                            needs_attention.append(collection_name)
                        break
                    # Re-embed the redacted text ourselves: update() would
                    # otherwise re-embed with chroma's default function and
                    # leave this one chunk in a different vector space from
                    # the rest of its collection.
                    collection.update(
                        ids=[chunk_id], documents=[redacted],
                        embeddings=_get_query_embedder()([redacted]))
                    row['remediated'] += 1

            except Exception as exc:
                logger.error("Rescan error for %s: %s", collection_name, exc)
                row['error'] = str(exc)

            report.append(row)

        return jsonify({
            'success': True,
            'dry_run': dry_run,
            'vault_unlocked': vault_unlocked,
            'scanned_collections': len(targets),
            'skipped_unknown': skipped_unknown,
            'total_remediated': sum(r['remediated'] for r in report),
            'collections_needing_attention': needs_attention,
            'report': report,
        })

    except Exception as e:
        logger.error("Knowledge rescan_pii error: %s", e)
        return jsonify({'success': False, 'message': str(e)}), 500


@app.route('/knowledge/search/titles', methods=['GET'])
def knowledge_search_titles():
    """Search article titles across ALL indexed libraries.

    Returns article-level results (title, collection, url) for display
    like a search engine. Served from the FTS shards' title column
    (:meth:`FTSSearcher.search_titles`), not by walking ZIM directory
    entries: the per-ZIM linear scan took ~33s across the full library
    while the shard query answers in well under a second, and the shards
    also cover the multi-gigabyte packs the scan had to skip. Libraries
    with no built shard do not contribute results, exactly as with
    /knowledge/search/fulltext.

    Query params:
        q: search query (required)
        limit: max total results (default 50)
        per_lib: max results per library (default 5)
    """
    query = request.args.get('q', '').strip()
    if not query or len(query) < 2:
        return jsonify({'success': True, 'results': [], 'query': query})

    try:
        limit = min(max(int(request.args.get('limit', '50')), 1), 200)
    except ValueError:
        limit = 50
    try:
        per_lib = min(max(int(request.args.get('per_lib', '5')), 1), 20)
    except ValueError:
        per_lib = 5

    try:
        searcher = _fts_searcher()
        hits = (searcher.search_titles(query, max_results=limit,
                                       per_library=per_lib)
                if searcher is not None else [])

        zim_libs = _discover_zim_libraries()
        results = []
        # The household's OWN documents first, from both upload stores. Titles
        # used to come only from the ZIM shards, so searching the name of a file
        # uploaded a minute earlier returned nothing at all — through either
        # door. Needs no embedding model and no shard, which is also why it is
        # the one search that still works on a box whose embedder is down.
        try:
            from puffpai.upload_index import title_matches
            for doc in title_matches(query, limit=limit):
                name = str(doc.get('title') or doc.get('filename') or '')
                results.append({
                    'title': name,
                    'url': '',
                    'collection': str(doc.get('id') or ''),
                    'library_id': str(doc.get('id') or ''),
                    'library_name': 'Your uploads',
                    'mime_type': '',
                    'source': 'upload',
                    'store': doc.get('store', ''),
                })
        except Exception as exc:
            logger.debug("upload title search unavailable: %s", exc)
        for hit in hits:
            library_id = hit['library_id']
            zim_path = zim_libs.get(library_id)
            results.append({
                'title': hit['title'],
                # docs.path is namespace-prefixed ('C/Article'), the same
                # shape the article endpoint already accepts from fulltext
                # results.
                'url': hit['path'],
                'collection': library_id,
                'library_id': library_id,
                'library_name': (_zim_library_name(zim_path)
                                 if zim_path else library_id),
                # Shards do not record per-entry mime types; the key stays
                # for response-shape compatibility and no client reads it.
                'mime_type': '',
            })

        return jsonify({
            'success': True,
            # ONE page, whichever source filled it: the caller asked for at
            # most `limit` rows and the upload rows are rows too.
            'results': results[:limit],
            'query': query,
            'total': min(len(results), limit),
        })

    except Exception as e:
        logger.error("Cross-library title search error: %s", e)
        return jsonify({'success': False, 'message': str(e)}), 500


@app.route('/knowledge/search/fulltext', methods=['GET'])
def knowledge_search_fulltext():
    """Full-text search across the SQLite FTS5 shards built from ZIM packs.

    Unlike /knowledge/search (semantic, ChromaDB) this searches the *body* of
    every article in every indexed pack, offline and without an embedding
    model. Shards are built by `python -m puffpai.knowledge.fts_build_cli`;
    libraries with no shard yet simply do not contribute results.

    Query params:
        q: search query (required)
        max_results: max total results (default 20, cap 100)
        library: restrict to one library id (repeatable)
    """
    query = request.args.get('q', '').strip()
    if not query:
        return jsonify({'success': False,
                        'message': 'Query parameter q is required'}), 400

    try:
        max_results = min(max(int(request.args.get('max_results', '20')), 1), 100)
    except ValueError:
        max_results = 20

    libraries = [lib for lib in request.args.getlist('library') if lib] or None

    try:
        searcher = _fts_searcher()
        if searcher is None:
            return jsonify({
                'success': True, 'results': [], 'query': query, 'total': 0,
                'libraries_searched': [],
                'message': 'Full-text index is not available',
            })

        searcher.refresh()  # pick up shards finished since the last request
        ready = searcher.ready_library_ids()
        results = searcher.search(query, max_results=max_results,
                                  libraries=libraries)

        zim_libs = _discover_zim_libraries()
        for hit in results:
            zim_path = zim_libs.get(hit['library_id'])
            hit['library_name'] = (_zim_library_name(zim_path) if zim_path
                                   else hit['library_id'])

        return jsonify({
            'success': True,
            'results': results,
            'query': query,
            'total': len(results),
            'libraries_searched': ready if libraries is None
                                  else [l for l in ready if l in libraries],
        })

    except Exception as e:
        logger.error("Full-text search error: %s", e)
        return jsonify({'success': False, 'message': str(e)}), 500


def _shard_path_for_collection(collection):
    """Path of this collection's complete FTS shard, or None.

    Maps a library id OR a legacy collection name onto the shard the same
    way /knowledge/search/fulltext does, so browse and search always agree
    on which library is which.
    """
    try:
        from puffpai.knowledge.fts_index import library_id_for
        zim_path = _resolve_zim_path(collection)
        if zim_path is None:
            return (None, None)
        library_id = library_id_for(zim_path)
        searcher = _fts_searcher()
        if searcher is None:
            return (library_id, None)
        return (library_id, searcher.shards.get(library_id))
    except Exception as exc:
        logger.debug("Shard lookup failed for %s: %s", collection, exc)
        return (None, None)


@app.route('/knowledge/library/<collection>/articles', methods=['GET'])
def knowledge_browse_articles(collection):
    """List articles in a ZIM-backed library for offline browsing.

    Served from the library's FTS shard whenever one is built: ``docs.id``
    is ZIM directory order (= path order), so a page is an indexed keyset
    window and ``total`` is a meta lookup. The old code iterated the whole
    ZIM directory on EVERY request just to count — 26.6M entries for
    wikipedia_en_all_maxi, which never returned and pinned a core at 100%.

    Query params:
        page:   page number (default 0) — fine for shallow paging
        limit:  page size (default 50, cap 200)
        after:  keyset cursor (a previous response's ``next_after``); use
                this for deep paging, it costs the same at page 100000
        prefix: jump to the first article whose PATH starts here
        q:      title search, scoped to THIS library (shard-backed)
    """
    try:
        page = max(int(request.args.get('page', '0')), 0)
    except ValueError:
        page = 0
    try:
        limit = min(max(int(request.args.get('limit', '50')), 1), 200)
    except ValueError:
        limit = 50
    try:
        after = int(request.args['after']) if request.args.get('after') else None
    except ValueError:
        after = None
    query = request.args.get('q', '').strip()
    prefix = request.args.get('prefix', '').strip()

    try:
        from puffpai.knowledge import shard_browse

        library_id, shard_path = _shard_path_for_collection(collection)

        # ── Title search, scoped to this one library ──────────────────────
        if query:
            searcher = _fts_searcher() if shard_path else None
            hits = (searcher.search_titles(query, max_results=limit,
                                           per_library=limit,
                                           libraries=[library_id])
                    if searcher is not None else [])
            return jsonify({
                'success': True,
                'articles': [{
                    'index': i,
                    'title': hit['title'],
                    'url': hit['path'],
                    'mime_type': '',
                    'source': 'shard',
                } for i, hit in enumerate(hits)],
                'total': len(hits),
                'has_more': False,
                'next_after': None,
                'source': 'shard' if shard_path else 'none',
                'query': query,
            })

        # ── Browse from the shard ─────────────────────────────────────────
        if shard_path:
            result = shard_browse.browse_shard(
                shard_path, page=page, limit=limit, after=after,
                prefix=prefix)
            result['success'] = True
            return jsonify(result)

        # ── No shard: a strictly bounded directory walk ───────────────────
        zim_reader = _get_zim_reader_for_collection(collection)
        if zim_reader is None:
            return jsonify({
                'success': True,
                'articles': [],
                'total': 0,
                'has_more': False,
                'next_after': None,
                'source': 'none',
                'message': 'No browsable ZIM file found for this collection',
            })

        result = shard_browse.browse_zim_bounded(
            shard_browse.html_entries(zim_reader), page=page, limit=limit)
        result['success'] = True
        result['message'] = ('Listing is limited until this library is '
                             'indexed (no full-text shard yet)')
        return jsonify(result)

    except Exception as e:
        logger.error("Knowledge browse error for %s: %s", collection, e)
        return jsonify({'success': False, 'message': str(e)}), 500


@app.route('/knowledge/library/<collection>/article', methods=['GET'])
def knowledge_get_article(collection):
    """Get a single article's HTML content from a ZIM-backed library."""
    url = request.args.get('url', '').strip()
    if not url:
        return jsonify({'success': False, 'message': 'url parameter is required'}), 400

    try:
        zim_reader = _get_zim_reader_for_collection(collection)
        if zim_reader is None:
            return jsonify({
                'success': False,
                'message': 'No browsable ZIM file found for this collection',
            }), 404

        article = zim_reader.get_article_by_url(url)
        if article is None:
            return jsonify({
                'success': False,
                'message': f'Article not found: {url}',
            }), 404

        # Decode content
        content = article.content
        if isinstance(content, bytes):
            content = content.decode('utf-8', errors='replace')

        # Internal links -> data-zim-url for the reader, then relative asset
        # URLs (video/img/poster/subtitles) -> the asset endpoint. See
        # _rewrite_zim_article_html for why that order is load-bearing.
        content = _rewrite_zim_article_html(content, collection, url)

        return jsonify({
            'success': True,
            'article': {
                'title': article.title,
                'url': url,
                'mime_type': article.mime_type,
                'html': content,
            },
        })

    except Exception as e:
        logger.error("Knowledge article error for %s/%s: %s", collection, url, e)
        return jsonify({'success': False, 'message': str(e)}), 500


# Paths a ZIM may use for its landing page when the header names none.
_ZIM_MAIN_PAGE_FALLBACKS = ('index', 'Main_Page', 'mainPage')


@app.route('/knowledge/library/<collection>/main', methods=['GET'])
def knowledge_get_main_page(collection):
    """Get a library's MAIN page — the front door of an offline wiki.

    Same response shape, same rewriting and the same (authenticated) gate as
    /knowledge/library/<collection>/article: this endpoint is deliberately
    NOT in _PUBLIC_ENDPOINTS or endpoint_gate.LOCAL_ONLY_ENDPOINTS, exactly
    like the article route it mirrors.
    """
    try:
        zim_reader = _get_zim_reader_for_collection(collection)
        if zim_reader is None:
            return jsonify({
                'success': False,
                'message': 'No browsable ZIM file found for this collection',
            }), 404

        article = zim_reader.get_main_page()
        if article is None:
            for ns in ('C', 'A'):
                for name in _ZIM_MAIN_PAGE_FALLBACKS:
                    article = zim_reader.get_article_by_url(f'{ns}/{name}')
                    if article is not None:
                        break
                if article is not None:
                    break

        if article is None:
            return jsonify({'success': False, 'message': 'no main page'}), 404

        url = f'{article.namespace}/{article.url}'
        content = article.content
        if isinstance(content, bytes):
            content = content.decode('utf-8', errors='replace')
        content = _rewrite_zim_article_html(content, collection, url)

        return jsonify({
            'success': True,
            'article': {
                'title': article.title,
                'url': url,
                'mime_type': article.mime_type,
                'html': content,
            },
        })

    except Exception as e:
        logger.error("Knowledge main page error for %s: %s", collection, e)
        return jsonify({'success': False, 'message': str(e)}), 500


def _rewrite_zim_article_html(content: str, collection: str, url: str) -> str:
    """Rewrite an article's internal links, then its assets. Order matters.

    Links go first: rewrite_article_links parks the target in
    data-zim-url and leaves ``href="#"``, which _rewrite_zim_asset_urls
    skips — so the asset pass no longer turns every internal article link
    into an asset download (it matches any ``href=``, not just stylesheets).

    ZIM content is third-party, and the dashboard renders this string with
    React's dangerouslySetInnerHTML, so the same pass re-serialises the
    article through an element/attribute allowlist (zim_links). That pass is
    the security boundary, so it FAILS CLOSED: if it raises we escape the
    article rather than serve raw pack markup. A page of visible HTML source
    is ugly; a live javascript: href is not.
    """
    try:
        from puffpai.knowledge.zim_links import rewrite_article_links
        content = rewrite_article_links(content, url)
    except Exception as exc:
        import html as _html_mod
        logger.warning("Link rewrite failed for %s/%s: %s — serving the "
                       "article escaped", collection, url, exc)
        return _html_mod.escape(content or '')

    # Assets must reach the API THROUGH the dashboard's same-origin proxy
    # (/api/pai); a bare /knowledge/... path resolves against the dashboard
    # origin (:3003), which does not serve it.
    # Quoted so a collection name can never carry markup into an attribute.
    import urllib.parse as _urlparse
    safe_collection = _urlparse.quote(str(collection), safe="-_.~")
    asset_base = f'/api/pai/knowledge/library/{safe_collection}/asset?path='
    return _rewrite_zim_asset_urls(content, asset_base)


def _parse_byte_range(range_header: str, size: int):
    """Parse a single HTTP byte range against a known content *size*.

    Returns inclusive ``(start, end)`` offsets, or ``None`` when the header is
    absent, malformed, multi-range, or unsatisfiable (the caller then serves
    the full body with 200). Supports ``bytes=start-``, ``bytes=start-end``,
    and suffix ``bytes=-N`` (final N bytes).
    """
    if not range_header or size <= 0:
        return None
    m = re.match(r'^\s*bytes=(\d*)-(\d*)\s*$', range_header)
    if not m:
        return None          # absent/multi-range/garbage -> full body
    start_s, end_s = m.group(1), m.group(2)
    if start_s == '' and end_s == '':
        return None
    if start_s == '':
        n = int(end_s)       # suffix range: the last N bytes
        if n == 0:
            return None
        start, end = max(0, size - n), size - 1
    else:
        start = int(start_s)
        end = int(end_s) if end_s != '' else size - 1
    if start > end or start >= size:
        return None          # unsatisfiable -> full body (simpler than a 416)
    return (start, min(end, size - 1))


@app.route('/knowledge/library/<collection>/asset', methods=['GET'])
def knowledge_serve_asset(collection):
    """Serve a raw binary asset (video, image, CSS, JS, font) from a ZIM file.

    This enables TED talk videos, article images, stylesheets, etc. to load
    in the browser when viewing ZIM-backed library content.
    """
    asset_path = request.args.get('path', '').strip()
    if not asset_path:
        return _zim_asset_harden(jsonify(
            {'success': False, 'message': 'path parameter is required'})), 400

    try:
        zim_reader = _get_zim_reader_for_collection(collection)
        if zim_reader is None:
            return _zim_asset_harden(Response(
                'Collection not found', status=404, mimetype='text/plain'))

        # Try the path as-is first (e.g. "C/videos/1940/video.webm")
        article = zim_reader.get_article_by_url(asset_path)

        # If not found, try common namespace prefixes
        if article is None:
            for ns in ['-', 'I', 'C', 'A', 'M']:
                article = zim_reader.get_article_by_url(f'{ns}/{asset_path}')
                if article is not None:
                    break

        if article is None:
            logger.debug("ZIM asset not found: %s in %s", asset_path, collection)
            return _zim_asset_harden(Response(
                'Asset not found', status=404, mimetype='text/plain'))

        # The pack's MIME string is third-party: never forwarded. Only an
        # exact display-only type is served inline, as the clean type WE
        # choose; anything else is an application/octet-stream attachment.
        mime, inline = _zim_asset_content_type(article.mime_type)
        content = article.content if isinstance(article.content, bytes) else article.content.encode('utf-8')

        # Media (video/audio) must be genuinely seekable: honor a Range request
        # with a real 206 + Content-Range rather than shipping the whole file
        # and only *claiming* range support (which made scrubbing a TED talk
        # re-download from zero). Non-media (images/CSS/JS) stay a plain 200.
        is_media = inline and mime.startswith(('video/', 'audio/'))
        rng = _parse_byte_range(request.headers.get('Range', ''), len(content)) \
            if is_media else None

        if rng is not None:
            start, end = rng  # inclusive offsets
            # content_type, not mimetype: send exactly the clean type (Flask
            # would add "; charset=utf-8" to text/vtt).
            resp = Response(content[start:end + 1], status=206,
                            content_type=mime)
            resp.headers['Content-Range'] = f'bytes {start}-{end}/{len(content)}'
        else:
            resp = Response(content, content_type=mime)

        resp.headers['Cache-Control'] = 'public, max-age=86400'  # cache 24h
        resp.headers['Access-Control-Allow-Origin'] = '*'
        # An HTML/SVG/XML file inside a pack would otherwise render as a PAGE
        # on the dashboard origin when opened directly (the proxy serves it
        # same-origin). As an attachment it downloads instead. <img>/<video>
        # loads ignore Content-Disposition, so embedded use is unaffected.
        _zim_asset_harden(resp, inline=inline)
        if is_media:
            resp.headers['Accept-Ranges'] = 'bytes'

        return resp

    except Exception as e:
        logger.error("ZIM asset error for %s/%s: %s", collection, asset_path, e)
        return _zim_asset_harden(Response(
            'Internal error', status=500, mimetype='text/plain'))


#: The ONLY asset types served inline: images, audio, video, fonts and
#: WebVTT subtitles (a <track> needs text/vtt), which a browser can display
#: but never run. Key = the bare type a pack declares (before any ';',
#: trimmed, lower-cased); value = the clean type we send.
#: Not listed (HTML, SVG, XML, CSS, PDF, script, unknown): attachment.
#: Must match INLINE_ASSET_TYPES in the dashboard's proxyHeaders.ts.
_ZIM_INLINE_ASSET_TYPES = {
    'image/png': 'image/png',
    'image/jpeg': 'image/jpeg',
    'image/jpg': 'image/jpeg',
    'image/pjpeg': 'image/jpeg',
    'image/gif': 'image/gif',
    'image/webp': 'image/webp',
    'image/avif': 'image/avif',
    'image/bmp': 'image/bmp',
    'image/x-icon': 'image/x-icon',
    'image/vnd.microsoft.icon': 'image/x-icon',
    'video/mp4': 'video/mp4',
    'video/webm': 'video/webm',
    'video/ogg': 'video/ogg',
    'audio/mpeg': 'audio/mpeg',
    'audio/mp3': 'audio/mpeg',
    'audio/mp4': 'audio/mp4',
    'audio/aac': 'audio/aac',
    'audio/ogg': 'audio/ogg',
    'audio/opus': 'audio/opus',
    'audio/webm': 'audio/webm',
    'audio/wav': 'audio/wav',
    'audio/x-wav': 'audio/wav',
    'audio/wave': 'audio/wav',
    'audio/flac': 'audio/flac',
    'audio/x-flac': 'audio/flac',
    'font/woff': 'font/woff',
    'font/woff2': 'font/woff2',
    'font/ttf': 'font/ttf',
    'font/otf': 'font/otf',
    'text/vtt': 'text/vtt',
    'application/font-woff': 'font/woff',
    'application/x-font-woff': 'font/woff',
    'application/font-woff2': 'font/woff2',
    'application/x-font-ttf': 'font/ttf',
    'application/x-font-otf': 'font/otf',
}
_ZIM_ASSET_FALLBACK_TYPE = 'application/octet-stream'
_ZIM_ASSET_CSP = "default-src 'none'; sandbox"
#: A comma or quote can smuggle a second type past a parser; a control
#: character (newline included) has no business in a header value.
_ZIM_MIME_REJECT_RE = re.compile(r'[,"\x00-\x1f\x7f]')


def _zim_asset_content_type(raw) -> tuple:
    """``(content_type_to_send, inline)`` for a pack-declared MIME string.

    Fails closed: anything not an exact allowlisted bare type, or carrying a
    comma, quote or control character anywhere, is
    ``('application/octet-stream', False)``. Parameters are never kept.
    """
    value = raw if isinstance(raw, str) else ''
    if not value or _ZIM_MIME_REJECT_RE.search(value):
        return (_ZIM_ASSET_FALLBACK_TYPE, False)
    bare = value.split(';', 1)[0].strip().lower()
    clean = _ZIM_INLINE_ASSET_TYPES.get(bare)
    if clean is None:
        return (_ZIM_ASSET_FALLBACK_TYPE, False)
    return (clean, True)


def _zim_asset_renders_inert(mime) -> bool:
    return _zim_asset_content_type(mime)[1]


def _zim_asset_harden(resp, inline: bool = False):
    """Headers every asset-endpoint response carries. Returns ``resp``."""
    resp.headers['X-Content-Type-Options'] = 'nosniff'
    resp.headers['Content-Security-Policy'] = _ZIM_ASSET_CSP
    if inline:
        resp.headers.pop('Content-Disposition', None)
    else:
        resp.headers['Content-Disposition'] = 'attachment'
    return resp


def _rewrite_zim_asset_urls(html: str, asset_base: str) -> str:
    """Rewrite relative src/href URLs in HTML to point to our asset endpoint.

    Converts paths like '../videos/1940/video.webm' or '/videos/1940/video.webm'
    to 'http://localhost:8000/knowledge/library/<col>/asset?path=C/videos/1940/video.webm'
    """
    import urllib.parse
    from html import unescape as html_unescape

    def _rewrite_match(match):
        attr = match.group(1)   # src= or href= or poster=
        quote = match.group(2)  # " or '
        url = match.group(3)    # the URL value

        # Skip absolute URLs, data URIs, anchors, and javascript:
        if url.startswith(('http://', 'https://', 'data:', '#', 'javascript:', 'mailto:')):
            return match.group(0)

        # The serialiser escaped every attribute value (& -> &amp;, " ->
        # &quot;). Undo that before percent-encoding, or "a&b.png" becomes
        # "a%26amp%3Bb.png" and the asset 404s. The value is re-encoded
        # below, so nothing unescaped reaches the markup.
        url = html_unescape(url)

        # Clean up relative path prefixes (../, ./, /)
        clean = url.lstrip('./')
        # Remove leading slashes
        clean = clean.lstrip('/')

        # URL-encode the path for the query parameter
        encoded = urllib.parse.quote(clean, safe='/')

        return f'{attr}={quote}{asset_base}{encoded}{quote}'

    # Rewrite src="...", href="...", poster="..." attributes
    pattern = r'(src|href|poster)\s*=\s*(["\'])((?:(?!\2).)+?)\2'
    return re.sub(pattern, _rewrite_match, html, flags=re.IGNORECASE)


# ══════════════════════════════════════════════════════════════════════════════
#  ZIM LIBRARY REGISTRY
#
#  Every ZIM file on disk is a first-class library, keyed by a stable
#  filename-derived id (knowledge.fts_index.library_id_for). This is
#  deliberately independent of indexed_libraries.json: a pack that was never
#  ingested into ChromaDB is still browsable, title-searchable and (once its
#  FTS shard is built) full-text searchable. The manifest still describes the
#  ChromaDB collections and user uploads, and _resolve_zim_path() accepts
#  legacy collection names so existing dashboard links keep working.
# ══════════════════════════════════════════════════════════════════════════════

# Cache for open ZIM readers, keyed by ZIM path (avoid re-opening large files).
# Bounded because each reader holds a file handle and a decompressed-cluster
# cache; the working set is a handful of libraries at a time.
_ZIM_READER_CACHE_SIZE = 8
_zim_readers: dict = {}
_zim_readers_lock = threading.Lock()

# Discovery can hit a network share, so the library map is cached briefly.
_ZIM_LIBRARY_TTL = 60.0
_zim_library_cache: dict = {'at': 0.0, 'libs': {}}


def _discover_zim_libraries(force: bool = False) -> dict:
    """Return ``{library_id: zim_path}`` for every discovered ZIM file."""
    now = time.time()
    with _zim_readers_lock:
        if not force and (now - _zim_library_cache['at']) < _ZIM_LIBRARY_TTL:
            return dict(_zim_library_cache['libs'])

    libs: dict = {}
    try:
        from puffpai.knowledge.discovery import discover_zim_files
        from puffpai.knowledge.fts_index import library_id_for
        from puffpai.config import get_config

        cfg = get_config()
        for zim_path in discover_zim_files(zim_dirs=cfg.paths.zim_dirs,
                                           zim_files=cfg.paths.zim_files):
            libs[library_id_for(zim_path)] = zim_path
    except Exception as exc:
        logger.warning("ZIM library discovery failed: %s", exc)
        with _zim_readers_lock:
            return dict(_zim_library_cache['libs'])

    with _zim_readers_lock:
        _zim_library_cache['at'] = now
        _zim_library_cache['libs'] = dict(libs)
    return libs


# Embedded ZIM metadata (M/Title, M/Description, M/Language), keyed by path
# and invalidated when the file's size or mtime changes. Without this,
# /knowledge/libraries would open all 67 archives on every request.
_zim_metadata_cache: dict = {}

_ZIM_METADATA_FIELDS = (
    ('title', 'M/Title'),
    ('description', 'M/Description'),
    ('language', 'M/Language'),
)


def _zim_filename_label(zim_path: str) -> str:
    """Fallback display name derived from the filename."""
    stem = os.path.splitext(os.path.basename(zim_path))[0]
    return re.sub(r'[_-]+', ' ', stem).strip() or stem


def _zim_metadata(zim_path: str) -> dict:
    """Read a ZIM's embedded metadata. Cached, and never raises.

    Every ZIM carries its own publisher-set title in the M namespace, which
    is far better than the filename: "Biology Courses" rather than
    "biologycourses en all 2025 10". A pack that cannot be read (truncated
    download, missing metadata) yields empty strings and the caller falls
    back to the filename.
    """
    try:
        stat = os.stat(zim_path)
        version = (stat.st_size, int(stat.st_mtime))
    except OSError:
        version = None

    with _zim_readers_lock:
        cached = _zim_metadata_cache.get(zim_path)
    if cached is not None and version is not None and cached[0] == version:
        return cached[1]

    meta = {'title': '', 'description': '', 'language': ''}
    reader = _get_zim_reader(zim_path)  # returns None for a truncated pack
    if reader is not None:
        for field, url in _ZIM_METADATA_FIELDS:
            try:
                article = reader.get_article_by_url(url)
                if article is None:
                    continue
                value = (article.text or '').strip()
            except Exception as exc:
                logger.debug("ZIM metadata %s unreadable in %s: %s",
                             url, os.path.basename(zim_path), exc)
                continue
            if value:
                meta[field] = value

    if version is not None:
        with _zim_readers_lock:
            _zim_metadata_cache[zim_path] = (version, meta)
    return meta


def _zim_library_name(zim_path: str) -> str:
    """Human-readable display name: the pack's own title, else its filename."""
    try:
        title = _zim_metadata(zim_path).get('title', '')
    except Exception as exc:
        logger.debug("ZIM metadata lookup failed for %s: %s", zim_path, exc)
        title = ''
    return title or _zim_filename_label(zim_path)


def _filename_tokens(zim_filename: str) -> list:
    """Split a ZIM filename stem into its underscore-separated tokens.

    Splitting on '_' only keeps dates like "2025-08" in one piece.
    """
    stem = os.path.splitext(os.path.basename(zim_filename))[0]
    return [tok for tok in stem.split('_') if tok]


def _disambiguate_library_names(rows: list) -> None:
    """Qualify display names shared by two or more ZIM packs, in place.

    Publisher titles collide: four Wikipedia variants are all called
    "Wikipedia". Colliding rows get a terse parenthetical built from the
    filename tokens that actually differ between them -- "Wikipedia (maxi
    2025-08)" vs "Wikipedia (mini 2025-06)". Unique titles are never touched.
    """
    by_name: dict = {}
    for row in rows:
        if row.get('source') == 'zim' and row.get('zim_filename'):
            by_name.setdefault(row['name'], []).append(row)

    for name, group in by_name.items():
        if len(group) < 2:
            continue
        token_lists = [_filename_tokens(r['zim_filename']) for r in group]
        shared = set(token_lists[0])
        for tokens in token_lists[1:]:
            shared &= set(tokens)
        for row, tokens in zip(group, token_lists):
            distinct = [tok for tok in tokens if tok not in shared][:3]
            if not distinct:
                distinct = [row['library_id']]
            row['name'] = f"{name} ({' '.join(distinct)})"


def _load_library_manifest() -> list:
    """Load indexed_libraries.json, or [] when it is missing/corrupt."""
    try:
        with open(os.path.join(_SRC_DIR, 'indexed_libraries.json'), 'r') as f:
            manifest = json.load(f)
    except (FileNotFoundError, json.JSONDecodeError, OSError):
        return []
    return manifest if isinstance(manifest, list) else []


def _resolve_zim_path(identifier: str) -> str | None:
    """Resolve a route identifier to a ZIM file path.

    Accepts BOTH the filename-derived library_id and the legacy ChromaDB
    collection name (resolved through the manifest's library_id and the old
    substring match), so the dashboard keeps working unmodified.
    """
    if not identifier:
        return None

    libs = _discover_zim_libraries()
    if identifier in libs:
        return libs[identifier]

    # Legacy path: collection name -> manifest library_id -> filename substring.
    library_id = ''
    for entry in _load_library_manifest():
        if entry.get('collection') == identifier:
            library_id = entry.get('library_id', '') or ''
            break
    if not library_id:
        library_id = identifier

    normalized_id = library_id.replace('-', '_').lower()
    if not normalized_id:
        return None
    for zim_path in libs.values():
        stem = os.path.splitext(os.path.basename(zim_path))[0]
        if normalized_id in stem.replace('-', '_').lower():
            return zim_path

    logger.debug("No ZIM match for identifier=%s among %d files",
                 identifier, len(libs))
    return None


def _get_zim_reader(zim_path: str):
    """Open (or reuse) a ZIMReader for a path. Returns None on any failure.

    A truncated pack — an interrupted download — is logged once and treated as
    "no reader", never as a 500.
    """
    with _zim_readers_lock:
        reader = _zim_readers.get(zim_path)
        if reader is not None:
            return reader

    try:
        from puffpai.knowledge.zim_reader import ZIMReader, ZIMTruncatedError
        try:
            reader = ZIMReader(zim_path)
        except ZIMTruncatedError as exc:
            logger.warning("Skipping truncated ZIM %s: %s bytes missing",
                           os.path.basename(zim_path), exc.missing_bytes)
            return None
    except Exception as exc:
        logger.warning("Could not open ZIM %s: %s", zim_path, exc)
        return None

    with _zim_readers_lock:
        # Another thread may have won the race; keep whichever is cached.
        existing = _zim_readers.get(zim_path)
        if existing is not None:
            try:
                reader.close()
            except Exception:
                pass
            return existing
        while len(_zim_readers) >= _ZIM_READER_CACHE_SIZE:
            oldest_path, oldest = next(iter(_zim_readers.items()))
            del _zim_readers[oldest_path]
            try:
                oldest.close()
            except Exception:
                pass
        _zim_readers[zim_path] = reader
    return reader


def _get_zim_reader_for_collection(collection_name: str):
    """Find and return a ZIMReader for a library id or legacy collection name."""
    zim_path = _resolve_zim_path(collection_name)
    if zim_path is None:
        return None
    return _get_zim_reader(zim_path)


def _fts_searcher():
    """Return the shared FTSSearcher, or None if the module/config is unusable."""
    try:
        from puffpai.knowledge.fts_index import get_searcher
        return get_searcher()
    except Exception as exc:
        logger.debug("FTS searcher unavailable: %s", exc)
        return None


def _fts_ready_libraries() -> set:
    """Library ids whose FTS shard is built and complete."""
    searcher = _fts_searcher()
    if searcher is None:
        return set()
    try:
        return set(searcher.ready_library_ids())
    except Exception as exc:
        logger.debug("FTS shard scan failed: %s", exc)
        return set()


# Characters of article text handed to the LLM per full-text hit.
_ZIM_FTS_EXCERPT_CHARS = 1500

# How far below the best hit an OR-fallback result may fall before it is
# dropped from the RAG context.
_OR_TAIL_MARGIN = 0.25


def _trim_or_tail(hits: list) -> list:
    """Drop the weak tail of an OR-fallback full-text result set.

    When FTSSearcher finds no document containing every query term it retries
    with the terms OR-ed (see fts_index.FTSSearcher.search). The top hit of
    that pass is reliable — bm25 weights by inverse document frequency, so the
    rare, meaningful terms decide it — but the tail is typically documents that
    matched only the question's stopwords. A natural-language question would
    otherwise drag two topically unrelated articles into the LLM context as
    cited sources: the same class of noise as indexing a sourcemap.

    AND-pass results are returned untouched; every one of them contains every
    term, so there is no tail to trim.
    """
    if not hits or hits[0].get('match_mode') != 'or':
        return hits
    # Results are interleaved round-robin across shards rather than sorted, so
    # take the best score from the whole set rather than trusting position 0.
    cutoff = max(h['relevance'] for h in hits) - _OR_TAIL_MARGIN
    return [h for h in hits if h['relevance'] >= cutoff]


def _zim_fts_excerpt(text: str, question: str) -> str:
    """Take an excerpt of article text, centred on the first query term.

    Falls back to the opening of the article when no term is found, which is
    usually the lead paragraph and therefore the best generic summary anyway.
    """
    if len(text) <= _ZIM_FTS_EXCERPT_CHARS:
        return text

    lowered = text.lower()
    positions = [
        pos for pos in (lowered.find(term.lower())
                        for term in re.split(r'\W+', question) if len(term) > 2)
        if pos >= 0
    ]
    if not positions:
        return text[:_ZIM_FTS_EXCERPT_CHARS]

    start = max(0, min(positions) - 200)
    return text[start:start + _ZIM_FTS_EXCERPT_CHARS]


def _get_zim_fts_results(question: str, max_hits: int = 5) -> list:
    """Full-text hits from the ZIM shards, shaped like _get_rag_context rows.

    Returns [] whenever no shard is ready, so an appliance that has never run
    the builder simply gets no full-text hits.
    """
    searcher = _fts_searcher()
    if searcher is None:
        return []

    try:
        hits = searcher.search(question, max_results=max_hits)
    except Exception as exc:
        logger.debug("FTS RAG query failed: %s", exc)
        return []
    if not hits:
        return []

    hits = _trim_or_tail(hits)

    zim_libs = _discover_zim_libraries()
    rows = []
    for hit in hits:
        zim_path = zim_libs.get(hit['library_id'])
        if not zim_path:
            continue
        reader = _get_zim_reader(zim_path)
        if reader is None:
            continue
        try:
            article = reader.get_article_by_url(hit['path'])
        except Exception as exc:
            logger.debug("FTS article fetch failed for %s: %s", hit['path'], exc)
            continue
        if article is None:
            continue

        text = _zim_fts_excerpt(article.plain_text, question)
        if not text:
            continue

        # FTSSearcher hands back a shard-relative 0.5-1.0 band (see
        # fts_index._relevance_from_bm25). Map it onto 0.35-0.85 here: every
        # literal match stays comfortably clear of the 0.25 relevance floor,
        # while a near-exact semantic hit can still outrank it.
        relevance = min(1.0, max(0.0, 0.35 + (hit['relevance'] - 0.5)))

        rows.append({
            'text': text,
            'library': _zim_library_name(zim_path),
            'collection': hit['library_id'],
            'distance': None,
            'relevance': relevance,
            'title': hit['title'],
            'url': hit['path'],
            'is_user_upload': False,
            'source_type': 'zim_fts',
        })
    return rows


# ══════════════════════════════════════════════════════════════════════════════
#  PROFILE / SETTINGS ENDPOINTS
# ══════════════════════════════════════════════════════════════════════════════

_DEFAULT_PROFILE = {
    'name': '',
    'email': '',
    'created_at': '',
}

_DEFAULT_AI_SETTINGS = {
    'ai_name': 'PuffPAI',
    'personality': 'helpful',
    'temperature': 0.7,
    # This key is displayed by the settings UI and is NOT read by any
    # inference path (only /profile uses it). It reports the real configured
    # chat context so the UI never advertises a number the chat runners do
    # not use; it is deliberately not a live override.
    'context_length': _model_options.num_ctx(),
    'avatar_character': 'puff',
    'avatar_3d_url': '',
}

# Avatar bodies the dashboard can render.  'glb' loads the custom model at
# avatar_3d_url below.
_AVATAR_CHARACTERS = ('puff', 'human', 'glb')

_AVATAR_URL_MAX_LEN = 2048
_AVATAR_RELATIVE_URL_RE = re.compile(r'^/[A-Za-z0-9_\-./]+$')


def _valid_avatar_url(value) -> bool:
    """Whether *value* is safe to hand to the browser's 3D model loader.

    Only three shapes are accepted:
      * ''                      — clear the custom model
      * '/path/to/model.glb'    — same-origin relative path (an uploaded model
                                  is ``avatar_model.MODEL_URL``, which is one
                                  of these)
      * 'http(s)://host/…'      — absolute http/https URL **whose host resolves
                                  entirely inside this house** (loopback, RFC
                                  1918, unique-local), proven by
                                  :func:`puffpai.security.lan_http.validate_url`

    Everything else is rejected, notably javascript:/data:/file:/blob:
    URLs, protocol-relative '//host/…' (which is off-origin), path
    traversal, non-ASCII, control characters and whitespace.

    On the absolute form, be honest about who fetches it: the BROWSER loads the
    model, not this process, so this check is a gate on what the appliance will
    *store and hand out as a setting* — it is not a network door. That is why
    the only absolute URLs allowed are house-local ones: a public URL saved
    here would have every dashboard in the house fetch a model off the internet
    with no door and no consent, which is exactly Zone 3's line.
    """
    if not isinstance(value, str):
        return False
    if value == '':
        return True
    if len(value) > _AVATAR_URL_MAX_LEN:
        return False
    # Reject anything a browser might normalise away: whitespace, C0/C1
    # control characters, DEL, and non-ASCII.  Callers must percent-encode.
    for ch in value:
        if ch.isspace() or not ch.isascii() or ord(ch) < 0x20 or ord(ch) == 0x7f:
            return False
    if value.startswith('/'):
        # '//host/x' is protocol-relative, i.e. not same-origin at all.
        if value.startswith('//') or '..' in value:
            return False
        return bool(_AVATAR_RELATIVE_URL_RE.match(value))
    from puffpai.security import lan_http
    try:
        lan_http.validate_url(value)
    except Exception as exc:
        # ValueError (not http(s)/no host), AddressRefused (off-house) and
        # ResolutionError ("we could not tell") are all one answer: no.
        logger.info("avatar_3d_url refused: %s", type(exc).__name__)
        return False
    return True


@app.route('/profile', methods=['GET'])
def profile_get():
    """Get current user profile and AI settings."""
    try:
        profile = _load_json_file(_PROFILE_PATH, _DEFAULT_PROFILE)
        ai_settings = _load_json_file(_AI_SETTINGS_PATH, _DEFAULT_AI_SETTINGS)

        # The owner is a household member like any other, so the
        # page that shows this profile shows the same picture the roster
        # does. Name too: profiles.json is the roster, and its owner row is
        # healed from THIS file, so the two can no longer disagree.
        profile = dict(profile)
        profile['avatar_url'] = _owner_avatar_url()

        from puffpai import household
        owner = household.owner_id()
        member = household.get_member(owner) if owner else None
        profile['preferences'] = dict((member or {}).get('preferences') or {})

        return jsonify({
            'success': True,
            'profile': profile,
            'ai_settings': ai_settings,
        })

    except Exception as e:
        logger.error("Profile get error: %s", e)
        return jsonify({'success': False, 'message': str(e)}), 500


@app.route('/profile', methods=['PUT'])
def profile_update():
    """Update user profile."""
    data = request.json or {}

    try:
        profile = _load_json_file(_PROFILE_PATH, _DEFAULT_PROFILE)

        # Only update allowed fields
        allowed_fields = {'name', 'email', 'phone', 'location', 'timezone'}
        for field in allowed_fields:
            if field in data:
                profile[field] = data[field]

        if not profile.get('created_at'):
            profile['created_at'] = datetime.now(timezone.utc).isoformat()
        profile['updated_at'] = datetime.now(timezone.utc).isoformat()

        _save_json_file(_PROFILE_PATH, profile)
        logger.info("Profile updated")

        # ...and into profiles.json, which is what every OTHER surface reads.
        # Written here alone, the dashboard would say the owner's real name
        # while voice, the calendar and fitness went on saying "Owner".
        if 'name' in data:
            from puffpai import household
            household.set_owner_name(profile.get('name'))

        profile = dict(profile, avatar_url=_owner_avatar_url())
        return jsonify({'success': True, 'profile': profile})

    except Exception as e:
        logger.error("Profile update error: %s", e)
        return jsonify({'success': False, 'message': str(e)}), 500


# ══════════════════════════════════════════════════════════════════════════════
# HOUSEHOLD — one roster, one name, one picture per person
# ══════════════════════════════════════════════════════════════════════════════
#
# Every route here is a thin shell over :mod:`puffpai.household`: validation,
# propagation and the avatar pipeline live there, so the voice hooks and the
# dashboard cannot answer from different rules. All of them sit behind the
# global API-key guard, exactly like /profile.

#: household error code -> HTTP status. One table, so a new code cannot
#: quietly become a 500.
_HOUSEHOLD_STATUS = {
    'invalid_name': 400,
    'invalid_role': 400,
    'not_an_image': 400,
    'too_large': 413,
    'duplicate': 409,
    'owner_undeletable': 409,
    'not_found': 404,
    'upload_not_found': 404,
    'invalid_preference': 400,
}


def _household_error(exc):
    from puffpai.household import HouseholdError
    if not isinstance(exc, HouseholdError):
        raise exc
    status = _HOUSEHOLD_STATUS.get(exc.code, 400)
    # 'error' is what the dashboard reads; 'code' is the stable machine
    # reason and 'message' the sentence. All three say the same thing.
    return jsonify({'success': False, 'code': exc.code,
                    'error': str(exc), 'message': str(exc)}), status


def _owner_avatar_url():
    """``/household/<owner>/avatar`` when the owner has a picture, else None."""
    try:
        from puffpai import household
        member_id = household.owner_id()
        if member_id and household.avatar_path(member_id).exists():
            return f"/household/{member_id}/avatar"
    except Exception as exc:
        logger.debug("owner avatar unavailable: %s", exc)
    return None


def _resolve_owner_id():
    from puffpai import household
    member_id = household.owner_id()
    if not member_id:
        raise household.HouseholdError(
            'not_found', 'No household profile exists yet.')
    return member_id


def _household_body():
    """The JSON object body, or a 400 response. Same shape as every other
    route's body guard (see ``_json_object_body``)."""
    body = request.get_json(silent=True)
    if body is None:
        return {}, None
    if not isinstance(body, dict):
        return None, (jsonify({'success': False, 'code': 'bad_body',
                               'error': _NON_OBJECT_BODY_MSG,
                               'message': _NON_OBJECT_BODY_MSG}), 400)
    return body, None


@app.route('/household', methods=['GET'])
def household_list():
    """The household roster — the source every other surface projects."""
    from puffpai import household
    return jsonify({'members': household.members(),
                    'owner_id': household.owner_id(),
                    'active_id': household.active_id()})


@app.route('/household', methods=['POST'])
def household_create():
    """Add a member. Creates the profile AND propagates it to the apps."""
    from puffpai import household
    body, error = _household_body()
    if error is not None:
        return error
    try:
        member = household.create_member(
            body.get('display_name'), role=body.get('role'),
            emoji=body.get('emoji'), color=body.get('color'))
    except household.HouseholdError as exc:
        return _household_error(exc)
    return jsonify({'success': True, 'member': member}), 201


@app.route('/household/<member_id>', methods=['PUT'])
def household_update(member_id):
    from puffpai import household
    body, error = _household_body()
    if error is not None:
        return error
    # A PARTIAL body is the normal case: the dashboard sends one field at a
    # time. Absent means "leave it"; an explicit null on emoji/color means
    # "clear it" (the roster then serves the role default again), which is a
    # different request and cannot be expressed by omission.
    fields = {}
    for key in ('display_name', 'role', 'emoji', 'color'):
        if key in body:
            fields[key] = body[key]
    if 'preferences' in body:
        fields['preferences'] = body['preferences']
    try:
        member = household.update_member(member_id, **fields)
    except household.HouseholdError as exc:
        return _household_error(exc)
    return jsonify({'success': True, 'member': member})


@app.route('/household/active', methods=['POST'])
def household_set_active():
    """Switch which profile is active."""
    from puffpai import household
    body, error = _household_body()
    if error is not None:
        return error
    member_id = body.get('id')
    if not member_id:
        return jsonify({'success': False, 'code': 'invalid_id',
                        'error': 'id is required',
                        'message': 'id is required'}), 400
    try:
        household.set_active(member_id)
    except household.HouseholdError as exc:
        return _household_error(exc)
    return jsonify({'success': True, 'active_id': household.active_id()})


@app.route('/household/<member_id>', methods=['DELETE'])
def household_delete(member_id):
    from puffpai import household
    try:
        removed = household.delete_member(member_id)
    except household.HouseholdError as exc:
        return _household_error(exc)
    return jsonify({'success': True, 'removed': removed})


def _household_avatar_upload(member_id):
    """POST a picture from the device. Shared by the member and owner routes."""
    from puffpai import household
    if 'file' not in request.files:
        return jsonify({'success': False, 'code': 'no_file',
                        'error': 'No file provided', 'message': 'No file provided'}), 400
    upload = request.files['file']
    data = upload.read()
    if not data:
        return jsonify({'success': False, 'code': 'no_file',
                        'error': 'Empty file', 'message': 'Empty file'}), 400
    try:
        result = household.save_avatar(member_id, data)
    except household.HouseholdError as exc:
        return _household_error(exc)
    return jsonify({'success': True, 'member_id': member_id,
                    'avatar_url': f"/household/{member_id}/avatar",
                    'decoded': result['decoded'], 'bytes': result['bytes']})


def _household_avatar_from_upload(member_id):
    """POST {"upload_id": ...} — a picture already sent to Puff."""
    from puffpai import household
    body, error = _household_body()
    if error is not None:
        return error
    try:
        result = household.avatar_from_upload(member_id, body.get('upload_id'))
    except household.HouseholdError as exc:
        return _household_error(exc)
    return jsonify({'success': True, 'member_id': member_id,
                    'avatar_url': f"/household/{member_id}/avatar",
                    'decoded': result['decoded'], 'bytes': result['bytes']})


def _household_avatar_get(member_id):
    from puffpai import household
    path = household.avatar_path(member_id)
    if not path.exists():
        return jsonify({'success': False, 'code': 'no_avatar',
                        'error': 'No avatar for this member.', 'message': 'No avatar for this member.'}), 404
    # Read and hand over the BYTES rather than streaming the file: send_file
    # holds the handle open until the response is consumed, and on a surface
    # that can replace or delete the picture in the very next request that is
    # a locked file (Windows) or a stale fd (everywhere).
    resp = Response(path.read_bytes(), mimetype='image/jpeg')
    # A picture the owner just replaced must not keep showing the old face.
    resp.headers['Cache-Control'] = 'no-cache'
    return resp


def _household_avatar_delete(member_id):
    from puffpai import household
    return jsonify({'success': True,
                    'removed': household.delete_avatar(member_id)})


@app.route('/household/<member_id>/avatar', methods=['POST'])
def household_avatar_post(member_id):
    return _household_avatar_upload(member_id)


@app.route('/household/<member_id>/avatar/from-upload', methods=['POST'])
def household_avatar_from_upload(member_id):
    return _household_avatar_from_upload(member_id)


@app.route('/household/<member_id>/avatar', methods=['GET'])
def household_avatar_get(member_id):
    return _household_avatar_get(member_id)


@app.route('/household/<member_id>/avatar', methods=['DELETE'])
def household_avatar_delete(member_id):
    return _household_avatar_delete(member_id)


