@app.route('/profile/ai', methods=['GET'])
def profile_ai_get():
    """Get AI personality settings (dashboard reads avatar_character here)."""
    try:
        ai_settings = _load_json_file(_AI_SETTINGS_PATH, _DEFAULT_AI_SETTINGS)
        # A name the owner never set reads as this build's own name (the
        # wizard's bot name or the persona they made), not the old default.
        if str(ai_settings.get('ai_name') or '').strip() in ('', 'PuffPAI'):
            ai_settings = {**ai_settings, 'ai_name': _live_ai_name()}
        return jsonify({'success': True, 'settings': ai_settings})

    except Exception as e:
        logger.error("AI settings get error: %s", e)
        return jsonify({'success': False, 'message': str(e)}), 500


@app.route('/profile/ai', methods=['PUT'])
def profile_ai_update():
    """Update AI personality settings."""
    data = request.json or {}

    try:
        ai_settings = _load_json_file(_AI_SETTINGS_PATH, _DEFAULT_AI_SETTINGS)

        # Only update allowed fields
        allowed_fields = {'ai_name', 'personality', 'temperature', 'context_length',
                          'system_prompt', 'response_style', 'avatar_style',
                          'avatar_character', 'avatar_3d_url'}
        for field_name in allowed_fields:
            if field_name in data:
                value = data[field_name]
                # Validate numeric fields
                if field_name == 'temperature':
                    value = max(0.0, min(2.0, float(value)))
                elif field_name == 'context_length':
                    value = max(512, min(32768, int(value)))
                elif field_name == 'avatar_character':
                    # Only the avatar bodies the dashboard can render
                    if value not in _AVATAR_CHARACTERS:
                        continue
                elif field_name == 'avatar_3d_url':
                    # User-supplied URL, loaded by the browser — strict allowlist
                    if not _valid_avatar_url(value):
                        continue
                ai_settings[field_name] = value

        ai_settings['updated_at'] = datetime.now(timezone.utc).isoformat()

        _save_json_file(_AI_SETTINGS_PATH, ai_settings)
        logger.info("AI settings updated")

        return jsonify({'success': True, 'ai_settings': ai_settings})

    except Exception as e:
        logger.error("AI settings update error: %s", e)
        return jsonify({'success': False, 'message': str(e)}), 500


# ══════════════════════════════════════════════════════════════════════════════
#  HOSTNAME RESOLUTION CACHE
# ══════════════════════════════════════════════════════════════════════════════

_hostname_cache: dict[str, str] = {}
_hostname_cache_lock = threading.Lock()


def _resolve_hostname(ip: str) -> str:
    with _hostname_cache_lock:
        if ip in _hostname_cache:
            return _hostname_cache[ip]

    hostname = ''
    try:
        old_timeout = socket.getdefaulttimeout()
        socket.setdefaulttimeout(2)
        try:
            hostname = socket.gethostbyaddr(ip)[0]
        finally:
            socket.setdefaulttimeout(old_timeout)
    except (socket.herror, socket.gaierror, OSError, socket.timeout):
        pass

    if not hostname and sys.platform == 'win32':
        try:
            result = subprocess.run(
                ['nbtstat', '-A', ip], capture_output=True, text=True, timeout=3,
            )
            for line in result.stdout.splitlines():
                if '<00>' in line and 'UNIQUE' in line:
                    hostname = line.split()[0].strip()
                    break
        except Exception:
            pass

    with _hostname_cache_lock:
        _hostname_cache[ip] = hostname
    return hostname


# ══════════════════════════════════════════════════════════════════════════════
#  FIREWALL EXTENDED ENDPOINTS
# ══════════════════════════════════════════════════════════════════════════════

@app.route('/firewall/rules', methods=['GET'])
def firewall_rules_list():
    try:
        backend = _get_fw_backend()
        if backend is None:
            return jsonify({'success': False, 'message': 'Firewall backend unavailable'}), 503

        rules = backend.get_rules()

        blocked_rules = []
        for d in backend.blocked_devices:
            blocked_rules.append({
                'id': d.get('rule_name', d.get('ip', '')),
                'name': f"Block {d.get('ip', 'unknown')}",
                'direction': 'both',
                'action': 'block',
                'protocol': 'ALL',
                'port': '*',
                'status': 'active',
            })

        return jsonify({
            'success': True,
            'rules': rules + blocked_rules,
            'count': len(rules) + len(blocked_rules),
            'backend': backend.backend_name,
        })

    except Exception as e:
        logger.error("Firewall rules list error: %s", e)
        return jsonify({'success': False, 'message': str(e)}), 500


@app.route('/firewall/rules', methods=['POST'])
def firewall_rules_add():
    data = request.json or {}
    name = (data.get('name') or '').strip()
    direction = data.get('direction', 'outbound')
    action = data.get('action', 'block')
    protocol = data.get('protocol', 'TCP')
    port = data.get('port', '*')

    if not name:
        return jsonify({'success': False, 'message': 'Rule name is required'}), 400

    try:
        backend = _get_fw_backend()
        if backend is None:
            return jsonify({'success': False, 'message': 'Firewall backend unavailable'}), 503

        refusal = _fw_write_refusal(backend)
        if refusal:
            return jsonify(refusal[0]), refusal[1]

        result = backend.add_rule(name, direction, action, protocol, port)
        return jsonify(result)

    except Exception as e:
        logger.error("Firewall rule add error: %s", e)
        return jsonify({'success': False, 'message': str(e)}), 500


@app.route('/firewall/rules/<rule_id>', methods=['DELETE'])
def firewall_rules_delete(rule_id):
    try:
        backend = _get_fw_backend()
        if backend is None:
            return jsonify({'success': False, 'message': 'Firewall backend unavailable'}), 503

        refusal = _fw_write_refusal(backend)
        if refusal:
            return jsonify(refusal[0]), refusal[1]

        if backend.delete_rule(rule_id):
            return jsonify({'success': True, 'message': f'Rule {rule_id} deleted'})

        target_ip = None
        for device in backend.blocked_devices:
            if device.get('ip') == rule_id or device.get('rule_name') == rule_id:
                target_ip = device['ip']
                break

        if target_ip:
            result = backend.unblock_device(target_ip)
            return jsonify(result)

        return jsonify({'success': False, 'message': f'Rule {rule_id} not found'}), 404

    except Exception as e:
        logger.error("Firewall rule delete error: %s", e)
        return jsonify({'success': False, 'message': str(e)}), 500


