_network_monitor = None
_network_monitor_lock = threading.Lock()


def _get_network_monitor():
    global _network_monitor
    if _network_monitor is None:
        with _network_monitor_lock:
            if _network_monitor is None:
                from puffpai.network_monitor import NetworkMonitor
                _network_monitor = NetworkMonitor()
    return _network_monitor


@app.route('/network/connections', methods=['GET'])
def network_connections():
    """Get a real-time snapshot of all active network connections.

    Returns total connections, external connections count, and
    an is_isolated flag proving zero cloud traffic.
    """
    try:
        monitor = _get_network_monitor()
        snap = monitor.snapshot()
        return jsonify(snap.to_dict())
    except Exception as e:
        logger.error("Network monitor error: %s", e)
        return jsonify({'error': str(e)}), 500


@app.route('/network/isolation-check', methods=['GET'])
def network_isolation_check():
    """Quick check: is the system fully isolated (zero external connections)?

    Returns a simple {isolated: true/false, external_count: N}.
    """
    try:
        monitor = _get_network_monitor()
        snap = monitor.snapshot()
        return jsonify({
            'isolated': snap.is_isolated,
            'external_count': snap.external_count,
            'lockdown_active': fw.get_status().get('lockdown_active', False),
            'timestamp': snap.timestamp,
        })
    except Exception as e:
        logger.error("Isolation check error: %s", e)
        return jsonify({'error': str(e)}), 500


@app.route('/firewall/devices', methods=['GET'])
def firewall_devices():
    """List detected network devices with classification.

    Scans ARP table, classifies each device via MAC OUI + hostname,
    cross-references with Home Assistant managed devices, and returns
    enriched device objects matching the dashboard's NetworkDevice interface.
    """
    try:
        import re as _re
        import ipaddress as _ipa

        raw_devices = []

        # ── ARP scan ──────────────────────────────────────────────
        try:
            import subprocess
            if sys.platform == 'win32':
                result = subprocess.run(
                    ['arp', '-a'], shell=False, capture_output=True,
                    text=True, timeout=10,
                )
            else:
                result = subprocess.run(
                    ['arp', '-n'], shell=False, capture_output=True,
                    text=True, timeout=10,
                )

            if result.returncode == 0:
                for line in result.stdout.splitlines():
                    line = line.strip()
                    # Extract IP and MAC from ARP output
                    ip_match = _re.search(r'(\d+\.\d+\.\d+\.\d+)', line)
                    mac_match = _re.search(
                        r'([0-9a-fA-F]{2}[:\-]){5}[0-9a-fA-F]{2}', line
                    )
                    if ip_match:
                        try:
                            addr = _ipa.ip_address(ip_match.group(1))
                            if not addr.is_private or addr.is_loopback:
                                continue
                            mac = mac_match.group(0) if mac_match else 'unknown'
                            # Skip broadcast MACs
                            if mac.replace('-', ':').upper() == 'FF:FF:FF:FF:FF:FF':
                                continue
                            raw_devices.append({
                                'ip': str(addr),
                                'mac': mac,
                            })
                        except (ValueError, TypeError):
                            continue
        except Exception as exc:
            logger.debug("ARP scan failed: %s", exc)

        # ── Classify each device ──────────────────────────────────
        try:
            from puffpai.security.device_classifier import (
                classify_device, DeviceClassifier, DeviceCategory,
            )
            classifier = DeviceClassifier()
        except ImportError:
            classifier = None

        # ── Cross-reference with Home Assistant ───────────────────
        ha_devices_by_ip = {}   # ip -> {name, entity_id}
        ha_devices_by_mac = {}  # normalised MAC -> {name, entity_id}
        try:
            from puffpai.config import get_config
            from puffpai.security.ha_token_source import ha_token as _ha_token
            ha_cfg = get_config().ha
            # The credential comes from the one token source.
            # cfg.ha.token is blanked at config build, so reading it here
            # would silently and permanently switch this cross-reference off.
            # _usable_token() in ha_vault already rejects the setup
            # placeholder and the MIGRATED_TO_VAULT marker, so no string
            # comparison is needed here.
            _tok = _ha_token()
            if ha_cfg and ha_cfg.enabled and _tok:
                import requests as _ha_req
                headers = {
                    'Authorization': f"Bearer {_tok}",
                    'Content-Type': 'application/json',
                }
                r = _ha_req.get(
                    f"{ha_cfg.url}/api/states",
                    headers=headers, timeout=5,
                )
                if r.ok:
                    for entity in r.json():
                        eid = entity.get('entity_id', '')
                        attrs = entity.get('attributes', {})
                        friendly = attrs.get('friendly_name', '')
                        if not friendly:
                            continue
                        # Match by IP
                        entity_ip = attrs.get('ip_address') or attrs.get('ip')
                        if entity_ip:
                            ha_devices_by_ip[entity_ip] = {
                                'name': friendly,
                                'entity_id': eid,
                            }
                        # Match by MAC (device_tracker entities often have this)
                        entity_mac = attrs.get('mac') or attrs.get('mac_address')
                        if entity_mac:
                            norm_mac = entity_mac.replace('-', ':').lower()
                            ha_devices_by_mac[norm_mac] = {
                                'name': friendly,
                                'entity_id': eid,
                            }
        except Exception as exc:
            logger.debug("HA device cross-reference failed: %s", exc)

        # ── Build enriched device list ────────────────────────────
        backend = _get_fw_backend()
        blocked_ips = set()
        if backend:
            blocked_ips = {d.get('ip') for d in backend.blocked_devices}

        # Check Zone 3 managed devices
        zone3_managed = {}
        try:
            engine = _get_zone3()
            if engine:
                for d in engine.get_managed_devices():
                    zone3_managed[d['ip']] = d
        except Exception:
            pass

        devices = []
        seen_ips = set()
        for raw in raw_devices:
            ip = raw['ip']
            if ip in seen_ips:
                continue
            seen_ips.add(ip)

            mac = raw['mac']
            is_blocked = ip in blocked_ips

            device_name = "Unknown Device"
            device_class = ""
            hostname = _resolve_hostname(ip)

            if classifier and mac != 'unknown':
                try:
                    result = classify_device(mac=mac, hostname=hostname)
                    if result.manufacturer:
                        device_name = result.manufacturer
                    if hostname and not result.manufacturer:
                        device_name = hostname
                    if result.category.value != 'unknown':
                        device_class = result.category.value.replace('_', ' ').title()
                except Exception:
                    pass
            elif hostname:
                device_name = hostname

            # Override with HA name if available (most reliable source)
            # Try IP match first, then MAC match
            norm_mac = mac.replace('-', ':').lower() if mac != 'unknown' else ''
            ha_info = ha_devices_by_ip.get(ip)
            if not ha_info and norm_mac:
                ha_info = ha_devices_by_mac.get(norm_mac)
            if ha_info:
                device_name = ha_info['name']

            # Override with Zone 3 info if managed
            z3_info = zone3_managed.get(ip)
            if z3_info:
                if z3_info.get('manufacturer'):
                    device_name = z3_info['manufacturer']
                    if z3_info.get('hostname'):
                        device_name = z3_info['hostname']
                if z3_info.get('category'):
                    device_class = z3_info['category'].replace('_', ' ').title()

            if is_blocked:
                trust = 'blocked'
            elif ha_info or (z3_info and z3_info.get('user_confirmed')):
                trust = 'trusted'
            elif device_class and device_class.lower() not in ('unknown',):
                trust = 'classified'
            else:
                trust = 'unknown'

            devices.append({
                'name': device_name,
                'ip': ip,
                'mac': mac,
                'device_class': device_class,
                'trust': trust,
                'blocked': is_blocked,
                # Extra fields for Zone 3 UI
                'zone3_managed': ip in zone3_managed,
                'zone3_mode': z3_info.get('mode') if z3_info else None,
            })

        return jsonify({
            'success': True,
            'devices': devices,
            'count': len(devices),
        })

    except Exception as e:
        logger.error("Firewall devices error: %s", e)
        return jsonify({'success': False, 'message': str(e)}), 500


# ══════════════════════════════════════════════════════════════════════════════
#  ZONE 3 — NETWORK EDGE SECURITY ENDPOINTS
#  puff puff pass
# ══════════════════════════════════════════════════════════════════════════════

def _get_zone3():
    """The Zone 3 policy engine, or None when Zone 3 is disabled.

    The factory itself lives in :mod:`puffpai.zone3.engine`, because these
    routes are not its only caller: the four ``zone3_*`` LLM tools use it
    too. An engine of their own (e.g. against ``PiholeController``) would
    make PuffPAI's spoken answers describe a different system from the one
    this endpoint reports. One factory means one answer on every surface.

    ``enforce`` is resolved there as ``env > owner overlay > config > off``, so
    the switch survives a restart. See ``puffpai/zone3/engine.py``.

    Kept as a thin alias rather than replaced at every call site: this name
    appears throughout the ``/zone3/*`` block and in tests, and a rename would
    have buried the actual change in noise.
    """
    from puffpai.zone3.engine import get_engine
    return get_engine()


#: Every ``/zone3`` route that accepts a write method, mapped to the consent
#: kind that gates it.
#:
#: This exists because the omission it closes was invisible. ``POST
#: /zone3/policy`` was gated and ``PUT /zone3/device/<ip>/mode`` was not, while
#: both call into ``apply_policy`` and both push live rules through
#: ``sync_dns()`` — one route asked the owner and its twin did not. Nothing in
#: the code said so; a reader had to hold six route bodies in their head at
#: once to notice.
#:
#: ``tests/test_zone3_gates.py`` walks ``app.url_map``, collects every rule
#: under ``/zone3`` carrying POST/PUT/DELETE/PATCH, and fails if one is not
#: listed here. So a new write route added without a gate turns a test red
#: rather than shipping quietly. Listing a route here is a claim that it
#: redeems that kind; the per-route tests in the same file check the claim.
_ZONE3_MINTS_ONLY = '(mints tickets; actuates nothing)'

GATED_ZONE3_WRITES = {
    'zone3_secure_device': 'zone3_secure',   # POST   /zone3/secure
    'zone3_set_policy': 'zone3_mode',        # POST   /zone3/policy
    'zone3_change_mode': 'zone3_mode',       # PUT    /zone3/device/<ip>/mode
    'zone3_remove_device': 'zone3_remove',   # DELETE /zone3/device/<ip>
    'zone3_setup': 'zone3_setup',            # POST   /zone3/setup
    'zone3_enforce': 'zone3_enforce',        # POST   /zone3/enforce
    'zone3_bucket_policy': 'zone3_bucket',   # POST   /zone3/bucket-policy
    'zone3_confirm': _ZONE3_MINTS_ONLY,      # POST   /zone3/confirm
}


def _zone3_ticket(data=None):
    """The consent ticket a Zone 3 write is presenting, or ``''``.

    Read from the JSON body, or from ``X-Zone3-Ticket`` when the body has
    none. The header is here for ``DELETE /zone3/device/<ip>``, whose body
    many HTTP clients will not send, and is accepted on every route so a
    caller never has to remember which one wants which.

    A query parameter is deliberately NOT accepted. A live ticket is a
    short-lived secret, and a URL is the one place in an HTTP request that
    reliably ends up in an access log, a proxy log and a browser history.
    """
    if isinstance(data, dict):
        value = data.get('ticket')
        if isinstance(value, str) and value:
            return value
    header = request.headers.get('X-Zone3-Ticket', '')
    return header if isinstance(header, str) else ''


@app.route('/zone3/status', methods=['GET'])
def zone3_status():
    """Get Zone 3 overall status including AdGuard Home and managed devices."""
    engine = _get_zone3()
    if engine is None:
        return jsonify({
            'success': False,
            'message': ('Zone 3 not enabled. Start the sinkhole '
                        '(sudo systemctl start puffpai-zone3), then set '
                        'zone3.enabled=true in config/puffpai_config.json and '
                        'restart puffpai-api.'),
        }), 503
    try:
        return jsonify({'success': True, **engine.get_zone3_status()})
    except Exception as e:
        logger.error("Zone 3 status error: %s", e)
        return jsonify({'success': False, 'message': str(e)}), 500


@app.route('/zone3/discover', methods=['GET'])
def zone3_discover():
    """Discover network devices and classify them."""
    engine = _get_zone3()
    if engine is None:
        # Fall back to basic discovery without Zone 3 engine
        try:
            from puffpai.zone3.policy_engine import PolicyEngine
            engine = PolicyEngine(pihole=None)
            devices = engine.discover_devices()
            return jsonify({'success': True, 'devices': devices, 'zone3_active': False})
        except Exception as e:
            return jsonify({'success': False, 'message': str(e)}), 500

    try:
        devices = engine.discover_devices()
        return jsonify({'success': True, 'devices': devices, 'zone3_active': True})
    except Exception as e:
        logger.error("Zone 3 discover error: %s", e)
        return jsonify({'success': False, 'message': str(e)}), 500


