@app.route('/zone3/secure', methods=['POST'])
def zone3_secure_device():
    """Auto-classify and apply recommended policy to a device.

    Body: {"ip": "...", "mac": "...", "hostname": "..."}
    """
    engine = _get_zone3()
    if engine is None:
        return jsonify({'success': False, 'message': 'Zone 3 not enabled'}), 503

    data = request.json or {}
    ip = (data.get('ip') or '').strip()
    mac = (data.get('mac') or '').strip()
    hostname = data.get('hostname', '')

    if not ip or not mac:
        return jsonify({'success': False, 'message': 'ip and mac are required'}), 400

    # Owner-gated: putting a device under policy decides what it may resolve.
    ok, _verdict = _zone3_redeem(_zone3_ticket(data), 'zone3_secure', ip,
                                 'secure')
    if not ok:
        return _zone3_needs_confirmation('zone3_secure', ip, 'secure')

    try:
        # push=True: this route redeemed an owner ticket, so it is a caller
        # allowed to write the household's rule block. The engine defaults to
        # record-only precisely so the LLM tool path cannot.
        result = engine.secure_device(ip, mac, hostname, push=True,
                                      recorded_by='owner')
        return jsonify(result)
    except Exception as e:
        logger.error("Zone 3 secure error: %s", e)
        return jsonify({'success': False, 'message': str(e)}), 500


@app.route('/zone3/policy', methods=['POST'])
def zone3_set_policy():
    """Apply a specific security mode to a device.

    Body: {"ip": "...", "mac": "...", "mode": "lockdown|balanced|open|always_allow", ...}
    """
    engine = _get_zone3()
    if engine is None:
        return jsonify({'success': False, 'message': 'Zone 3 not enabled'}), 503

    data = request.json or {}
    ip = (data.get('ip') or '').strip()
    mac = (data.get('mac') or '').strip()
    mode_str = (data.get('mode') or 'balanced').strip().lower()

    if not ip or not mac:
        return jsonify({'success': False, 'message': 'ip and mac are required'}), 400

    try:
        from puffpai.zone3.policy_engine import SecurityMode
        mode = SecurityMode(mode_str)
    except ValueError:
        return jsonify({'success': False, 'message': f'Invalid mode: {mode_str}. Use: lockdown, balanced, open, always_allow'}), 400

    # Owner-gated: a mode change decides what one device may reach.
    ok, _verdict = _zone3_redeem(_zone3_ticket(data), 'zone3_mode', ip,
                                 mode_str)
    if not ok:
        return _zone3_needs_confirmation('zone3_mode', ip, mode_str)

    try:
        result = engine.apply_policy(
            ip=ip,
            mac=mac,
            mode=mode,
            manufacturer=data.get('manufacturer'),
            hostname=data.get('hostname', ''),
            category=data.get('category', 'unknown'),
            is_safety_critical=data.get('is_safety_critical', False),
            push=True,             # owner-gated above; see /zone3/secure
            recorded_by='owner',
        )
        return jsonify(result)
    except Exception as e:
        logger.error("Zone 3 policy error: %s", e)
        return jsonify({'success': False, 'message': str(e)}), 500


@app.route('/zone3/device/<ip>', methods=['GET'])
def zone3_device_status(ip):
    """Get the policy status and security report for a managed device."""
    engine = _get_zone3()
    if engine is None:
        return jsonify({'success': False, 'message': 'Zone 3 not enabled'}), 503
    try:
        report = engine.generate_security_report(ip)
        return jsonify(report)
    except Exception as e:
        return jsonify({'success': False, 'message': str(e)}), 500


@app.route('/zone3/device/<ip>', methods=['DELETE'])
def zone3_remove_device(ip):
    """Stop managing a device and remove its DNS blocks.

    **Owner-gated** (kind ``zone3_remove``). Un-managing is not the harmless
    half of the pair: it drops that device's rules, retires its AdGuard client
    entry and rewrites the live block. On a device whose entry was the
    ``filtering_enabled: false`` exemption keeping a safety-critical thing
    reachable, deleting the entry is what puts it back under the house-wide
    baseline. A call that can quietly UN-protect is exactly as worth confirming
    as the one that protects.
    """
    engine = _get_zone3()
    if engine is None:
        return jsonify({'success': False, 'message': 'Zone 3 not enabled'}), 503

    data = request.get_json(silent=True) or {}
    ok, _verdict = _zone3_redeem(_zone3_ticket(data), 'zone3_remove', ip,
                                 'remove')
    if not ok:
        return _zone3_needs_confirmation('zone3_remove', ip, 'remove')

    try:
        result = engine.remove_device(ip)
        return jsonify(result)
    except Exception as e:
        return jsonify({'success': False, 'message': str(e)}), 500


@app.route('/zone3/device/<ip>/mode', methods=['PUT'])
def zone3_change_mode(ip):
    """Change the security mode for an already-managed device.

    Body: {"mode": "lockdown|balanced|open", "ticket": "..."}

    **Owner-gated** (kind ``zone3_mode``) — the SAME kind ``POST /zone3/policy``
    redeems, because this is the same act. Both end in ``apply_policy`` and
    both push through ``sync_dns()``, so while Zone 3 is enforcing either one
    changes what that device may resolve, right now. Sharing the kind (rather
    than minting a fourth) is deliberate: a ticket the owner approved for
    "(this ip, this mode)" is good on whichever route the caller reaches for,
    and one act with two consent vocabularies invites an ungated twin.
    """
    engine = _get_zone3()
    if engine is None:
        return jsonify({'success': False, 'message': 'Zone 3 not enabled'}), 503

    data = request.get_json(silent=True) or {}
    mode_str = (data.get('mode') or '').strip().lower()

    try:
        from puffpai.zone3.policy_engine import SecurityMode
        mode = SecurityMode(mode_str)
    except ValueError:
        return jsonify({'success': False, 'message': f'Invalid mode: {mode_str}'}), 400

    ok, _verdict = _zone3_redeem(_zone3_ticket(data), 'zone3_mode', ip,
                                 mode_str)
    if not ok:
        return _zone3_needs_confirmation('zone3_mode', ip, mode_str)

    try:
        result = engine.change_device_mode(ip, mode, push=True,
                                           recorded_by='owner')
        return jsonify(result)
    except Exception as e:
        return jsonify({'success': False, 'message': str(e)}), 500


@app.route('/zone3/setup', methods=['POST'])
def zone3_setup():
    """Push the recorded policy to the DNS sinkhole.

    Idempotent: it rewrites PuffPAI's rule block and per-client settings from
    the managed-device ledger. Safe to call any time the two might have drifted
    (after restoring a ledger, after recreating the AdGuard container).

    On the legacy Pi-hole path this still creates the Pi-hole groups.

    **Owner-gated** (kind ``zone3_setup``). "Idempotent" is not "harmless":
    ``sync_dns()`` REPLACES PuffPAI's whole rule block and rewrites the
    per-client entries from the ledger. Whatever the ledger says becomes what
    the household's DNS does, immediately, whenever Zone 3 is enforcing —
    including rules recorded by tool calls while it was only observing. That
    is the same blast radius as the enforce switch, reached by a route whose
    name sounds like first-run plumbing, so it asks the same question.
    """
    engine = _get_zone3()
    if engine is None:
        return jsonify({'success': False, 'message': 'Zone 3 not enabled'}), 503

    data = request.get_json(silent=True) or {}
    ok, _verdict = _zone3_redeem(_zone3_ticket(data), 'zone3_setup', 'zone3',
                                 'sync')
    if not ok:
        return _zone3_needs_confirmation('zone3_setup', 'zone3', 'sync')

    try:
        if getattr(engine, '_adguard', None) is not None:
            return jsonify({'success': True, **engine.sync_dns()})
        result = engine.setup_pihole_groups()
        return jsonify(result)
    except Exception as e:
        return jsonify({'success': False, 'message': str(e)}), 500


@app.route('/zone3/buckets', methods=['GET'])
def zone3_buckets():
    """Home Assistant integration buckets, with any recorded Zone 3 policy.

    Read-only, and the join is done HERE rather than in the dashboard so the
    two halves cannot disagree about which integration a mode belongs to.
    Buckets with no recorded policy come back with ``mode: null`` — absent is
    not "open", and rendering it as a mode would claim a decision nobody made.
    """
    engine = _get_zone3()
    try:
        from puffpai import bridge_ha
        rows = list(bridge_ha.buckets())
    except Exception as e:
        logger.warning("Zone 3 bucket roll unavailable: %s", e)
        return jsonify({'success': False, 'buckets': [],
                        'message': f'Bucket roll unavailable: {e}'}), 200

    managed = {}
    if engine is not None:
        try:
            managed = {b['bucket_id']: b for b in engine.get_managed_buckets()}
        except Exception as e:
            logger.warning("Zone 3 bucket policy read failed: %s", e)

    out = []
    for row in rows:
        policy = managed.get(row.get('id'))
        out.append({
            'id': row.get('id'),
            'tier': row.get('tier'),
            'integration': row.get('integration'),
            'label': row.get('label', ''),
            'device_count': row.get('device_count', 0),
            # Entities and rooms so the Firewall page can say what a local
            # integration actually IS. A row that offers no policy has to earn
            # its line some other way, and "23 entities across 4 rooms" is the
            # sentence that does it.
            'entity_count': row.get('entity_count', 0),
            'areas': dict(row.get('areas') or {}),
            'lookups_24h': row.get('lookups', 0),
            'watching_24h': row.get('watching', 0),
            'mode': (policy or {}).get('mode'),
            'recorded_by': (policy or {}).get('recorded_by'),
            'recorded_at': (policy or {}).get('recorded_at'),
            'domains_recorded': len((policy or {}).get('blocked_domains') or []),
            # The dashboard greys these out; it does not have to know the rule.
            'policy_supported': row.get('tier') == 'cloud',
        })
    return jsonify({'success': True, 'buckets': out,
                    'zone3_enabled': engine is not None,
                    'enforcing': bool(getattr(engine, 'enforcing', False))})


@app.route('/zone3/bucket-policy', methods=['POST'])
def zone3_bucket_policy():
    """Set the Zone 3 mode for one Home Assistant integration.

    Body: ``{"bucket": "cloud:ring", "mode": "balanced", "ticket": "..."}``

    **Owner-gated** (kind ``zone3_bucket``). The rules this writes name the
    HUB as their client, so they are not scoped to one gadget: LOCKDOWN here
    refuses the vendor's cloud API for Home Assistant and stops every device
    in that integration from answering. The 409 proposal says so in those
    words before a ticket is minted.
    """
    engine = _get_zone3()
    if engine is None:
        return jsonify({'success': False, 'message': 'Zone 3 not enabled'}), 503

    data = request.get_json(silent=True) or {}
    bucket = (data.get('bucket') or data.get('bucket_id') or '').strip()
    mode_str = (data.get('mode') or '').strip().lower()
    if not bucket:
        return jsonify({'success': False,
                        'message': 'bucket is required'}), 400
    try:
        from puffpai.zone3.policy_engine import SecurityMode
        mode = SecurityMode(mode_str)
    except ValueError:
        return jsonify({
            'success': False,
            'message': (f'Invalid mode: {mode_str}. Use: lockdown, balanced, '
                        f'open, always_allow'),
        }), 400

    # Only cloud-backed buckets have anything that leaves the house. A local
    # tier (Zigbee radio, Z-Wave, ESPHome...) never reaches a vendor, so there
    # is nothing to refuse — say that plainly instead of minting a proposal
    # that talks about "the vendor's cloud API" for a radio.
    if bucket.startswith('system:'):
        return jsonify({
            'success': False,
            'code': 'bucket_not_cloud_backed',
            'message': (f"{bucket} is Home Assistant's own internals — the "
                        f"supervisor, backups, sun position, the helpers you "
                        f"defined. They are not devices and they are never "
                        f"offered a policy. Policy applies to cloud-backed "
                        f"integrations only."),
        }), 422
    if not bucket.startswith('cloud:'):
        tier = bucket.split(':', 1)[0] or 'unknown'
        return jsonify({
            'success': False,
            'code': 'bucket_not_cloud_backed',
            'message': (f"{bucket} is a {tier} bucket: these devices talk only "
                        f"to Home Assistant on this LAN, nothing leaves the "
                        f"house for them, so there is nothing to block. Policy "
                        f"applies to cloud-backed integrations only."),
        }), 422

    ok, _verdict = _zone3_redeem(_zone3_ticket(data), 'zone3_bucket', bucket,
                                 mode_str)
    if not ok:
        return _zone3_needs_confirmation('zone3_bucket', bucket, mode_str)

    try:
        result = engine.apply_bucket_policy(bucket, mode, recorded_by='owner',
                                            push=True)
        return jsonify(result), (200 if result.get('success') else 400)
    except Exception as e:
        logger.error("Zone 3 bucket policy error: %s", e)
        return jsonify({'success': False, 'message': str(e)}), 500


@app.route('/zone3/enforce', methods=['POST'])
def zone3_enforce():
    """The observe -> enforce switch.  Body: {"enabled": bool, "ticket": str}

    This is the ONE call that starts or stops actual blocking. It rewrites
    every rule (live, or commented out) AND sets AdGuard's global protection
    to match, so the two can never disagree.

    **Owner-gated.** Without a ticket from ``POST /zone3/confirm`` this answers
    **409 and a proposal** and changes nothing. The API key alone is not enough
    to start filtering a household's DNS: the key is held by the dashboard, the
    voice service and every LLM tool in the appliance, so gating on it would
    put the switch inside reach of a single poisoned tool call. The ticket
    requires a deliberate two-step protocol the model cannot execute, and it
    guarantees whatever confirmed was shown the proposal below.

    **Persistent.** The flag is written to the owner overlay
    (``$PUFFPAI_DATA_DIR/state/zone3_enforce.json``) and re-read at
    construction, so a restart keeps it. Previously this changed the running
    object only and an owner lost enforcement at the next power cut with
    nothing on disk saying it had ever been on. See ``puffpai/zone3/engine.py``
    for why the overlay and not the appliance config.
    """
    engine = _get_zone3()
    if engine is None:
        return jsonify({'success': False, 'message': 'Zone 3 not enabled'}), 503

    data = request.json or {}
    if 'enabled' not in data or not isinstance(data.get('enabled'), bool):
        return jsonify({'success': False,
                        'message': 'Body must be {"enabled": true|false}'}), 400

    want_on = bool(data['enabled'])
    action = 'on' if want_on else 'off'
    ok, _verdict = _zone3_redeem(_zone3_ticket(data), 'zone3_enforce',
                                 'zone3', action)
    if not ok:
        return _zone3_needs_confirmation('zone3_enforce', 'zone3', action)

    try:
        from puffpai.zone3.engine import set_enforce_persistent
        result = set_enforce_persistent(want_on)
        return jsonify(result), (200 if result.get('success') else 409)
    except Exception as e:
        logger.error("Zone 3 enforce error: %s", e)
        return jsonify({'success': False, 'message': str(e)}), 500


# ── Zone 3 consent tickets ────────────────────────────────────────────────────
#
# The SAME primitives the Home Assistant gate uses (``_ha_mint_ticket`` /
# ``_ha_redeem_ticket``): single-use, sha256-compared, TTL-bounded, evicted at a
# cap, and bound to one (kind, target, action) triple. Reused rather than
# reimplemented — a second ticket store would be a second place to get constant-
# time comparison, single-use semantics and expiry wrong, and the first
# implementation is the audited one.
#
# What is NOT shared is the vocabulary. ``_ha_confirmation_proposal`` speaks in
# entity ids and service domains, which describe nothing about "start refusing
# your television's telemetry at DNS". Zone 3 kinds are minted at
# ``/zone3/confirm`` and are refused by ``/ha/confirm`` (they are not in
# ``_HA_TICKET_KINDS``), so a ticket for one can never redeem against the other.

#: Every Zone 3 act that changes what reaches the internet, and the routes that
#: redeem it. One line per WRITE ROUTE, not per interesting act: a count of
#: "acts" smaller than the count of write routes makes an ungated route look
#: like a deliberate scope rather than an omission. ``GATED_ZONE3_WRITES`` (up beside the routes) is
#: the machine-checked half of the same statement.
_ZONE3_TICKET_KINDS = frozenset({
    # target "zone3",  action "on" | "off"   POST   /zone3/enforce
    "zone3_enforce",
    # target <ip>,     action <mode>         POST   /zone3/policy
    #                                        PUT    /zone3/device/<ip>/mode
    "zone3_mode",
    # target <ip>,     action "secure"       POST   /zone3/secure
    "zone3_secure",
    # target <ip>,     action "remove"       DELETE /zone3/device/<ip>
    "zone3_remove",
    # target "zone3",  action "sync"         POST   /zone3/setup
    "zone3_setup",
    # target <bucket id>, action <mode>     POST   /zone3/bucket-policy
    #
    # A SEPARATE kind from zone3_mode, not a reuse of it. The subject differs
    # (a Home Assistant integration, whose rules name the HUB as the client,
    # not one device) and so does the worst case: LOCKDOWN on a bucket is the
    # one Zone 3 act that deliberately BREAKS something the household uses.
    # A ticket the owner approved for a device mode must not redeem against
    # that.
    "zone3_bucket",
})


def _zone3_proposal(kind: str, target: str, action: str) -> dict:
    """What a ticket would authorise, in words fit to show a person.

    Reads the engine for counts so the numbers are this household's, not a
    template. Never actuates and never writes: minting must be free of side
    effects, or the confirmation step becomes the thing it is meant to gate.
    """
    engine = _get_zone3()
    managed = 0
    critical = 0
    rules = 0
    # Unknown posture reads as ENFORCING for the purpose of the WORDS shown.
    # This value only ever decides how loudly a proposal is phrased, and the
    # restrictive reading of "I could not tell" is the one that does not
    # reassure an owner that nothing will start being blocked.
    enforcing = True
    buckets = 0
    bucket_rules = 0
    if engine is not None:
        try:
            status = engine.get_zone3_status()
            managed = status.get('managed_devices', 0)
            critical = status.get('safety_critical_count', 0)
            rules = status.get('total_recorded_domains', 0)
            buckets = status.get('managed_bucket_count', 0)
            bucket_rules = status.get('bucket_recorded_domains', 0)
            enforcing = bool(status.get('enforcing', True))
        except Exception:
            pass  # a status read that fails must not block the proposal

    proposal = {'kind': kind, 'target': target, 'action': action,
                'headline': '', 'effects': [], 'always_allowed': []}

    if kind == 'zone3_enforce' and action == 'on':
        # A COUNT is not a proposal. Rules recorded by tool calls while Zone 3
        # was only observing go live on this one click, and without this
        # listing the owner's only description of them would be "about N
        # rule(s)", which names no device, and hides the fact that some of
        # those N were recorded by the model rather than asked for by them. The per-device
        # rows are the dry run made readable.
        from puffpai.zone3.engine import enforce_preview
        preview = enforce_preview(engine)
        proposal['headline'] = (
            "Turn Zone 3 enforcement ON — PuffPAI starts refusing telemetry "
            "at DNS for this whole house.")
        proposal['devices'] = preview['devices']
        proposal['devices_omitted'] = preview['more']
        proposal['effects'] = [
            f"{preview['rules']} recorded rule(s) go live across "
            f"{preview['managed']} managed device(s), listed below.",
            "AdGuard's global protection is turned on at the same time, so "
            "the rules and the switch can never disagree.",
            "The setting is written to disk and survives a restart.",
        ] + preview['lines']
        proposal['always_allowed'] = [
            f"{preview['critical']} safety-critical device(s) stay "
            f"ALWAYS_ALLOW and are never filtered.",
            "Cloud services a device needs to work are not blocked — this is "
            "BALANCED, not LOCKDOWN.",
        ]
    elif kind == 'zone3_enforce':
        proposal['headline'] = (
            "Turn Zone 3 enforcement OFF — nothing on this network will be "
            "filtered.")
        proposal['effects'] = [
            f"Every rule across {managed} device(s) goes back to commented-"
            f"out, and AdGuard protection is turned off.",
            "PuffPAI keeps logging what each device reaches out to. She just "
            "stops refusing any of it.",
        ]
    elif kind == 'zone3_mode':
        proposal['headline'] = (
            f"Change {target} to {str(action).upper()} mode.")
        proposal['effects'] = [
            "This changes which domains that one device may resolve.",
            "It takes effect immediately if Zone 3 is enforcing; otherwise it "
            "is recorded and blocks nothing until you turn enforcement on.",
        ]
    elif kind == 'zone3_bucket':
        # Read-only lookup so the proposal states THIS household's numbers.
        integration = target.split(':', 1)[-1] or target
        devices = 0
        try:
            from puffpai import bridge_ha
            facts = bridge_ha.bucket(target) or {}
            integration = str(facts.get('integration') or integration)
            devices = int(facts.get('device_count') or 0)
        except Exception:
            pass  # a lookup that fails must not block the proposal
        act = str(action).lower()
        proposal['headline'] = (
            f"Set the {integration} integration ({devices} device(s)) to "
            f"{act.upper()}.")
        proposal['effects'] = [
            "These rules name Home Assistant as the client, because the hub "
            "is what talks to this vendor's cloud — not the devices "
            "themselves.",
            "It takes effect immediately if Zone 3 is enforcing; otherwise it "
            "is recorded and blocks nothing until you turn enforcement on.",
        ]
        try:
            from puffpai.zone3.policy_engine import BUCKET_MODE_EFFECTS
            effect = BUCKET_MODE_EFFECTS.get(act)
            if effect:
                proposal['effects'].insert(0, effect)
        except Exception:
            pass
        if act == 'lockdown':
            from puffpai.zone3.policy_engine import bucket_lockdown_warning
            warning = bucket_lockdown_warning(integration, devices)
            proposal['breaks_integration'] = True
            proposal['warning'] = warning
            proposal['headline'] = (
                f"Set {integration} to LOCKDOWN — {warning}")
            proposal['effects'].insert(0, warning)
        else:
            proposal['breaks_integration'] = False
        proposal['always_allowed'] = [
            "Devices under their own ALWAYS_ALLOW policy are unaffected: "
            "these rules only apply to Home Assistant's own lookups.",
        ]
    elif kind == 'zone3_secure':
        proposal['headline'] = (
            f"Put {target} under PuffPAI's DNS policy for the first time.")
        proposal['effects'] = [
            "PuffPAI classifies the device and applies the mode she "
            "recommends for its kind — normally BALANCED.",
            "It takes effect immediately if Zone 3 is enforcing; otherwise it "
            "is recorded only.",
        ]
    elif kind == 'zone3_remove':
        proposal['headline'] = (
            f"Stop managing {target} — PuffPAI drops its DNS policy.")
        proposal['effects'] = [
            f"{target}'s recorded rules are deleted and the whole rule block "
            f"is rewritten without them.",
            "Its AdGuard client entry is retired.",
            "Nothing about that device is filtered afterwards. This is the "
            "un-protect direction, not the protect one.",
        ]
        proposal['always_allowed'] = [
            "If this device was ALWAYS_ALLOW, the client entry keeping it "
            "exempt goes away too, and the house-wide baseline applies to it "
            "again.",
        ]
    elif kind == 'zone3_setup':
        # The number and the posture, not just "sync". An owner reading "push
        # the policy to the sinkhole" cannot tell whether that means anything
        # is about to start being refused; on this route it depends entirely
        # on the enforce flag, so the flag is said out loud.
        proposal['headline'] = (
            "Push PuffPAI's recorded policy to the DNS sinkhole, replacing "
            "whatever is there now.")
        posture = ("Zone 3 is ENFORCING, so these rules take effect the "
                   "moment they are written."
                   if enforcing else
                   "Zone 3 is OBSERVING, so the rules are written commented "
                   "out and nothing starts being refused.")
        proposal['effects'] = [
            f"{rules} recorded rule(s) across {managed} managed device(s) are "
            f"rewritten into AdGuard's PuffPAI block.",
            *([f"{bucket_rules} vendor-domain rule(s) for {buckets} Home "
               f"Assistant integration bucket(s), scoped to the hub's address, "
               f"are written in the same block."] if buckets else []),
            posture,
            "Per-client entries are rewritten from the ledger, and PuffPAI "
            "client entries for devices no longer managed are retired.",
        ]
        proposal['always_allowed'] = [
            f"{critical} safety-critical device(s) keep their ALWAYS_ALLOW "
            f"client entry, which is written in both postures.",
        ]
    else:
        proposal['headline'] = "This change needs your confirmation."
    return proposal


def _zone3_needs_confirmation(kind: str, target: str, action: str):
    """The 409 a Zone 3 write answers with when no valid ticket was presented.

    Same shape as the HA gate's 409 — ``needs_confirmation``, ``proposal``,
    ``confirm_endpoint`` — so a UI can render both refusals with one component
    and neither surface has to special-case the other.
    """
    proposal = _zone3_proposal(kind, target, action)
    return jsonify({
        'success': False,
        'needs_confirmation': True,
        'message': proposal['headline'],
        'error': proposal['headline'],
        'proposal': proposal,
        'confirm_endpoint': '/zone3/confirm',
    }), 409


def _zone3_redeem(ticket, kind: str, target: str, action: str):
    """Consume *ticket* if it is live and bound to exactly this act."""
    return _ha_redeem_ticket(ticket, kind=kind, entity_id=target,
                             action=action)


@app.route('/zone3/confirm', methods=['POST'])
def zone3_confirm():
    """Mint a single-use Zone 3 consent ticket. **Actuates nothing.**

    Body: ``{"kind": ..., "target": ..., "action": ...}`` — see
    :data:`_ZONE3_TICKET_KINDS`. Redeem by including ``"ticket": "<value>"`` in
    the body of the call that performs the change.

    The response echoes the proposal the ticket is bound to, so the dashboard
    renders the SERVER's description of the change rather than its own copy of
    the request. A mismatch between what the owner meant and what the backend
    is about to do is exactly what this step exists to expose, and it can only
    be caught by showing the far side's version.

    See :func:`_ha_confirmation_token` for an honest statement of what
    completing this flow does and does not prove. In short: it proves a
    deliberate two-step protocol was executed against this API and that
    whatever confirmed was shown this proposal. It does not prove a person.
    """
    body = request.get_json(silent=True) or {}
    if not isinstance(body, dict):
        return jsonify({'success': False,
                        'error': 'Request body must be a JSON object'}), 400

    kind = str(body.get('kind') or '').strip().lower()
    if kind not in _ZONE3_TICKET_KINDS:
        return jsonify({
            'success': False,
            'error': f"Unknown kind {kind!r}. "
                     f"Use one of: {', '.join(sorted(_ZONE3_TICKET_KINDS))}.",
        }), 400

    target = body.get('target')
    action = body.get('action')
    if not target or not isinstance(target, str):
        return jsonify({'success': False,
                        'error': 'target is required (a single string)'}), 400
    if not action or not isinstance(action, str):
        return jsonify({
            'success': False,
            'error': 'action is required — a ticket is bound to one action on '
                     'one target, so there is no default',
        }), 400

    proposal = _zone3_proposal(kind, target, action)
    secret, record = _ha_mint_ticket(kind, target, action)

    return jsonify({
        'success': True,
        'ticket': secret,
        'ticket_id': record['id'],
        'expires_in': _HA_TICKET_TTL_SECONDS,
        'single_use': True,
        'proposal': proposal,
        'message': (
            f"Ticket authorises exactly {action} on {target} once, within "
            f"{_HA_TICKET_TTL_SECONDS}s. Nothing has been changed."),
    }), 201


# ══════════════════════════════════════════════════════════════════════════════
#  HOME ASSISTANT ENDPOINTS  (powered by ha_bridge)
#  puff puff pass
# ══════════════════════════════════════════════════════════════════════════════

def _get_ha_bridge():
    """Lazy-import the HA bridge singleton."""
    from puffpai.ha_bridge import get_bridge
    return get_bridge()


# ══════════════════════════════════════════════════════════════════════════════
#  Human-confirmation tickets
#
#  The bridge refuses to actuate the always-confirm class unless it is handed
#  the in-process ``HUMAN_CONFIRMED`` token (see puffpai.ha_bridge). That closes
#  the spoof — decoded JSON can never *be* that object — but it left no way for
#  an actual person to say yes, because nothing over HTTP could legitimately
#  produce the token either.
#
#  Why an API key is not enough on its own: the key authenticates a *client*,
#  and the appliance's own agent stack holds the same key. An LLM that has been
#  prompt-injected by a document it summarised presents byte-identical
#  credentials to a person at the dashboard. Authentication cannot separate them
#  because they are, at the HTTP layer, the same caller.
#
#  What does separate them is a round trip. The ticket flow requires the caller
#  to make one call that returns a fresh unguessable value and a second call
#  that presents it back, bound to the same action. A single injected tool call
#  emits one request with arguments the model wrote; it cannot contain a value
#  the server had not generated yet.
# ══════════════════════════════════════════════════════════════════════════════

#: How long a minted confirmation ticket stays redeemable, in seconds.
#:
#: 90s. The ticket is sized to one human interaction and nothing more: the
#: dashboard renders the proposal ("this will turn OFF camera.hallway — the only
#: witness this house has"), the person reads a sentence and clicks. Ninety
#: seconds covers a distracted read and a deliberate click; two minutes would
#: not buy any more decisions, it would only widen the window in which a ticket
#: that leaked — into a screenshot, a shared log, an LLM context — is still
#: worth something. Every second above the read-and-click time is attack
#: surface, so the TTL tracks the interaction, not the user's patience. A ticket
#: that expires costs the user one extra click; a ticket that lives too long
#: costs them a camera.
_HA_TICKET_TTL_SECONDS = 90

#: Hard cap on simultaneously-live tickets.
#:
#: Minting is authenticated, so a caller holding the API key (which, per above,
#: includes a compromised in-process agent) could otherwise mint in a loop until
#: the process runs out of memory — turning a confirmation feature into a way to
#: kill the appliance. At the cap the oldest ticket is evicted rather than the
#: mint refused: eviction only ever *removes* a capability, whereas refusing to
#: mint would let a flood permanently lock the household out of confirming
#: anything.
_HA_TICKET_MAX = 32

#: In memory only, by design. A ticket must not survive a restart: it is
#: evidence that a person was present a moment ago, and a process that has been
#: restarted has no idea whether that is still true. There is deliberately no
#: persistence path here.
_ha_ticket_lock = threading.Lock()
_ha_tickets: list = []


#: Request-body keys that must never reach a bridge call.
#:
#: ``/ha/control`` and ``/ha/service/<domain>/<service>`` splat the request body
#: into the bridge call, so a body key named after the gate parameter *binds to
#: the gate parameter*. It cannot open the gate — ha_bridge compares by object
#: identity and a decoded JSON value is never the token — but forwarding it at
#: all would mean the gate's safety rests entirely on that one identity check
#: staying correct forever. Two independent barriers, not one. The aliases are
#: here because the next person to rename the parameter should not silently
#: reopen the hole; ``tests/test_ha_confirmation_tickets.py`` asserts that
#: ha_bridge.CONFIRMATION_KEYWORD is still a member of this set.
#:
#: ``force`` is included because it is the name of :func:`enforce_confirmation`'s
#: bypass argument. It is not currently a parameter of any bridge method a route
#: splats into, so today it would merely be forwarded to HA as service data —
#: this is the restrictive choice, taken deliberately. The cost is that an HA
#: service genuinely taking a ``force`` field cannot be driven through
#: ``/ha/service``; use a purpose-built route if one ever needs to be.
_HA_RESERVED_BODY_KEYS = frozenset({
    "human_confirmed", "humanconfirmed", "human_confirm", "humanconfirm",
    "confirmed", "confirm", "confirmation", "is_human", "human",
    "force", "ticket",
})


def _ha_strip_reserved(body: dict, *, also=()) -> dict:
    """Copy *body* without any key that could bind to a gate parameter.

    Matching is case-insensitive and whitespace-insensitive. JSON key lookup for
    Python keyword binding is exact, so ``{"Human_Confirmed": true}`` could not
    bind today; it is stripped anyway so that the guarantee does not depend on
    the spelling of a parameter someone may rename.
    """
    drop = {str(k).strip().lower() for k in also} | _HA_RESERVED_BODY_KEYS
    if not isinstance(body, dict):
        return {}
    return {k: v for k, v in body.items()
            if str(k).strip().lower() not in drop}


def _ha_norm_entity(entity_id) -> str:
    """Canonical form of an entity target for ticket binding."""
    if isinstance(entity_id, (list, tuple, set)):
        return ",".join(sorted(
            _ha_norm_entity(item) for item in entity_id if item))
    return str(entity_id or "").strip().lower()


def _ha_binding(kind: str, entity_id, action) -> str:
    """The exact string a ticket is bound to.

    The binding rule is *exact equality of the whole triple*: the route family
    (``control`` / ``service`` / ``scene`` / ``automation``), the normalised
    target, and the normalised action. A ticket minted for
    ``camera.hallway|turn_off`` does not authorise ``camera.hallway|turn_on``,
    does not authorise ``camera.porch|turn_off``, and does not authorise the
    same pair reached through ``/ha/service``. There is no wildcard, no prefix
    match and no domain-level ticket — the unit of consent is one action on one
    target, because that is the unit the person was shown.
    """
    return "\x1f".join((
        str(kind).strip().lower(),
        _ha_norm_entity(entity_id),
        str(action or "").strip().lower(),
    ))


def _ha_ticket_log(event: str, *, ticket_id: str, binding_kind: str,
                   entity_id, action, result: str, detail: str = "") -> None:
    """Record a ticket lifecycle event. Never records the ticket secret.

    Only the short non-secret ``ticket_id`` is written, so the trail can be
    correlated (this redeem belongs to that mint) without the trail itself
    becoming a place to harvest redeemable capabilities.
    """
    summary = (f"ha-confirm {event}: {binding_kind} "
               f"{_ha_norm_entity(entity_id)}|{str(action or '').lower()} "
               f"[{ticket_id}] -> {result}")
    logger.info("%s%s", summary, f" ({detail})" if detail else "")
    try:
        from puffpai.security.audit_log import AuditLog
        AuditLog().log(
            action=f"ha_confirmation_{event}",
            user="api-client",
            result=result,
            details=summary,
            extra={
                "kind": binding_kind,
                "entity_id": _ha_norm_entity(entity_id),
                "action": str(action or "").strip().lower(),
                "ticket_id": ticket_id,
                "verdict": result,
                "remote_addr": (request.remote_addr
                                if has_request_context() else None),
            },
        )
    except Exception as exc:
        # The audit ledger is fail-closed about its own directory and will
        # raise if it cannot write. That must not take down the refusal path —
        # the logger call above already put this event in the journal, which is
        # itself a trail. Losing the JSONL copy is a monitoring gap, not an
        # authorisation gap.
        logger.warning("ha-confirm: audit ledger unavailable (%s)", exc)


def _ha_mint_ticket(kind: str, entity_id, action):
    """Mint a single-use ticket bound to exactly (kind, entity_id, action).

    Returns ``(secret, record)``. The secret is returned to the caller once and
    never stored — only its SHA-256 is kept, so a memory dump or a stray repr of
    the store yields nothing redeemable.
    """
    secret = secrets.token_urlsafe(32)
    ticket_id = secrets.token_urlsafe(6)
    now = time.monotonic()
    record = {
        "id": ticket_id,
        "digest": hashlib.sha256(secret.encode("utf-8")).digest(),
        "binding": _ha_binding(kind, entity_id, action),
        "kind": str(kind).strip().lower(),
        "entity_id": _ha_norm_entity(entity_id),
        "action": str(action or "").strip().lower(),
        "expires_at": now + _HA_TICKET_TTL_SECONDS,
        "minted_at": time.time(),
    }
    with _ha_ticket_lock:
        _ha_tickets[:] = [t for t in _ha_tickets if t["expires_at"] > now]
        while len(_ha_tickets) >= _HA_TICKET_MAX:
            _ha_tickets.pop(0)
        _ha_tickets.append(record)
    _ha_ticket_log("mint", ticket_id=ticket_id, binding_kind=kind,
                   entity_id=entity_id, action=action, result="minted")
    return secret, record


def _ha_redeem_ticket(ticket, *, kind: str, entity_id, action):
    """Consume *ticket* if it is live and bound to this exact action.

    Returns ``(ok, verdict)`` where verdict is one of ``absent`` (no ticket
    offered), ``unknown`` (no such live ticket — forged, garbage, or already
    spent), ``expired``, ``mismatch`` (a real ticket, for a different action) or
    ``ok``.

    Single use is enforced by removing the record the moment its digest matches,
    *before* the binding is checked. A ticket presented for the wrong action is
    burned rather than handed back: presenting a valid ticket against an action
    it was not minted for is misuse, not a typo, and the restrictive reading is
    that the ticket's holder should have to start over in front of the person
    again.
    """
    if not isinstance(ticket, str) or not ticket:
        return False, "absent"

    offered = hashlib.sha256(ticket.encode("utf-8", "replace")).digest()
    want = _ha_binding(kind, entity_id, action)
    now = time.monotonic()

    with _ha_ticket_lock:
        matched = None
        for record in _ha_tickets:
            # Every record is compared, with no early break: the work done does
            # not depend on which record matched or on whether one did.
            if secrets.compare_digest(record["digest"], offered):
                matched = record
        if matched is not None:
            _ha_tickets.remove(matched)          # single use, unconditionally
        _ha_tickets[:] = [t for t in _ha_tickets if t["expires_at"] > now]

    if matched is None:
        _ha_ticket_log("refuse", ticket_id="-", binding_kind=kind,
                       entity_id=entity_id, action=action, result="unknown",
                       detail="no live ticket matches the value presented")
        return False, "unknown"
    if matched["expires_at"] <= now:
        _ha_ticket_log("refuse", ticket_id=matched["id"], binding_kind=kind,
                       entity_id=entity_id, action=action, result="expired")
        return False, "expired"
    if not secrets.compare_digest(matched["binding"], want):
        _ha_ticket_log(
            "refuse", ticket_id=matched["id"], binding_kind=kind,
            entity_id=entity_id, action=action, result="mismatch",
            detail=f"ticket was minted for {matched['kind']} "
                   f"{matched['entity_id']}|{matched['action']}")
        return False, "mismatch"

    _ha_ticket_log("redeem", ticket_id=matched["id"], binding_kind=kind,
                   entity_id=entity_id, action=action, result="consumed")
    return True, "ok"


def _ha_confirmation_token(ticket, *, kind: str, entity_id, action):
    """The value to pass as ``human_confirmed=`` for this request.

    Returns the in-process ``HUMAN_CONFIRMED`` token only when a ticket was
    offered, was live, and was bound to this exact action. Otherwise returns
    ``False``, which is what the bridge refuses on.

    **What this proves, precisely.** It proves the caller completed a two-step
    flow: it obtained a fresh, server-generated, unguessable value from
    ``/ha/confirm`` and presented that same value back, bound to the same
    action, within 90 seconds. A prompt injection that reaches the model inside
    a single tool call cannot do that — the injected text was written before the
    ticket existed, and a model emitting one tool call cannot invent a value the
    server generated afterwards.

    **What this does not prove.** It is not cryptographic proof of a human. It
    does not attest to a keypress, a session, or a person. Any caller that can
    make two sequential HTTP requests with the API key — including a compromised
    agent running an autonomous loop, or malware on a host that holds the key —
    can mint a ticket and redeem it. The ticket raises the cost from "emit one
    poisoned tool call" to "execute a deliberate two-step protocol against this
    specific API", and it guarantees that whatever did the confirming was shown
    the exact proposal it approved. It does not, and cannot, establish that a
    person was on the other end. Real proof of presence would need a channel the
    in-process agent does not have at all — a signed dashboard session, a device
    PIN, a physical button.
    """
    from puffpai.ha_bridge import HUMAN_CONFIRMED
    ok, _verdict = _ha_redeem_ticket(
        ticket, kind=kind, entity_id=entity_id, action=action)
    return HUMAN_CONFIRMED if ok else False


def _ha_confirmation_proposal(kind: str, entity_id, action) -> dict:
    """The machine-readable description of what a ticket would authorise.

    Pure: derives the touched domains from the identifiers themselves and makes
    no call to Home Assistant, so minting a ticket cannot read — let alone
    actuate — anything in the house.
    """
    from puffpai.ha_bridge import SAFETY_CRITICAL_DOMAINS, touched_domains
    service_domain = None
    act = str(action or "").strip().lower()
    if kind == "service" and "." in act:
        service_domain = act.split(".", 1)[0]
    domains = touched_domains(service_domain, entity_id)
    critical = sorted(domains & set(SAFETY_CRITICAL_DOMAINS))
    proposal = {
        "kind": kind,
        "entity_id": entity_id,
        "action": act,
        "domains": sorted(domains),
        "safety_critical_domains": critical,
        "safety_critical": bool(critical),
    }
    if kind == "scene":
        # A scene's members — and a script's steps — are only knowable from HA,
        # and this endpoint does not call HA. Say so rather than implying the
        # list is complete. ``/ha/scenes/<id>/activate`` accepts ``script.*`` as
        # well as ``scene.*``, and a script is gated on what its steps would do,
        # so the same kind covers both rather than forcing the dashboard to
        # choose a ticket kind by inspecting the entity id.
        if str(entity_id or "").startswith("script."):
            proposal["safety_critical"] = None
            proposal["note"] = (
                "a script is gated on what its steps would do, not on the "
                "script domain; the bridge resolves its stored config at "
                "actuation time and fails closed when it cannot read it — show "
                "the domains from the 409 proposal instead")
        else:
            proposal["note"] = (
                "scene membership is not expanded here; the bridge expands it "
                "at actuation time and fails closed if it cannot read the "
                "members")
    elif kind == "automation":
        # The target is an automation *alias*, not an entity id, so no domain
        # can be derived from it. The domains that matter are the ones named
        # inside the submitted config, and the bridge derives those itself when
        # the config is submitted. Surface the 409's own domain list in the UI
        # rather than trusting this field.
        proposal["domains"] = []
        proposal["safety_critical_domains"] = []
        proposal["safety_critical"] = None
        proposal["note"] = (
            "an automation is identified by its alias, not an entity id; the "
            "domains it would actuate are derived from the submitted config at "
            "creation time — show the domains from the 409 proposal instead")
    elif kind == "automation_run":
        # ``automation.<slug>`` only ever yields the ``automation`` domain,
        # which is never safety-critical — that is precisely the hole this kind
        # exists to cover. What matters is the domains the automation's actions
        # reach, and those are only knowable from its stored config, which this
        # endpoint does not fetch (minting must not touch HA).
        proposal["safety_critical"] = None
        proposal["note"] = (
            "an automation is gated on what its actions would do, not on the "
            "automation domain; the bridge resolves its stored config at "
            "actuation time and fails closed when it cannot read it — show the "
            "domains from the 409 proposal instead")
    return proposal


def _ha_error_response(exc):
    """Convert an HABridgeError into a Flask JSON response tuple.

    :class:`~puffpai.ha_bridge.ConfirmationRequired` is checked **first and by
    type**, before the string-matching classifier below ever sees it. Two
    reasons, both load-bearing:

    * It subclasses ``HABridgeError``, so ``except HABridgeError`` catches it
      and, left to the generic tail, it became a **502** — "the upstream broke".
      That is wrong in a way that matters: a refusal to blind the house's only
      camera is the system working, and reporting it as an upstream fault
      invites exactly the wrong response (retry, restart, escalate).
    * Its message is assembled partly from caller-supplied identifiers, so a
      request naming ``camera.invalid_thing`` could steer the ``startswith
      ("invalid ")`` branch and be reported as a 400. Branching on type removes
      the possibility.

    The 409 body carries the proposal verbatim from the exception so a UI can
    render precisely what was refused and hand the same triple straight to
    ``POST /ha/confirm``.
    """
    from puffpai.ha_bridge import ConfirmationRequired
    if isinstance(exc, ConfirmationRequired):
        proposal = dict(getattr(exc, "proposal", None) or {})
        message = str(getattr(exc, "reason", "") or exc)
        return jsonify({
            "success": False,
            "needs_confirmation": True,
            "error": message,        # legacy clients read .error
            "message": message,
            "proposal": proposal,
            "confirm_endpoint": "/ha/confirm",
        }), 409

    msg = str(exc)
    if msg.startswith("invalid "):
        # Bridge-level input validation (entity_id / service segments): the
        # caller sent something malformed, so this is a 400, not an upstream
        # failure. Checked first so an echoed input cannot pick another branch.
        return jsonify({"success": False, "error": msg}), 400
    if "disabled" in msg.lower():
        return jsonify({"success": False, "error": msg}), 503
    if "connect" in msg.lower():
        return jsonify({"success": False, "error": msg}), 502
    if "timed out" in msg.lower():
        return jsonify({"success": False, "error": msg}), 504
    return jsonify({"success": False, "error": msg}), 502


@app.route('/ha/status', methods=['GET'])
def ha_status():
    """Check if Home Assistant is reachable and return connection info."""
    bridge = _get_ha_bridge()
    status = bridge.get_status()
    status["success"] = status.get("connected", False)
    code = 200 if status["connected"] else 502
    return jsonify(status), code


@app.route('/ha/entities', methods=['GET'])
def ha_entities():
    """Return all HA entities grouped by domain."""
    from puffpai.ha_bridge import HABridgeError
    bridge = _get_ha_bridge()
    try:
        states = bridge.get_all_states()
    except HABridgeError as exc:
        return _ha_error_response(exc)

    domains: dict[str, int] = {}
    for entity in states:
        eid = entity.get("entity_id", "")
        domain = eid.split(".")[0] if "." in eid else "unknown"
        domains[domain] = domains.get(domain, 0) + 1

    return jsonify({
        "success": True,
        "entities": states,
        "count": len(states),
        "domains": domains,
    })


@app.route('/ha/devices', methods=['GET'])
def ha_devices():
    """Return controllable devices, optionally filtered by domain or search query."""
    from puffpai.ha_bridge import HABridgeError
    bridge = _get_ha_bridge()
    try:
        domain = request.args.get("domain")
        query = request.args.get("q")

        if query:
            devices = bridge.find_devices(query)
        else:
            devices = bridge.list_devices(domain=domain)

        return jsonify({
            "success": True,
            "devices": [
                {
                    "entity_id": d.entity_id,
                    "domain": d.domain,
                    "friendly_name": d.friendly_name,
                    "state": d.state,
                    "is_on": d.is_on,
                    "area_name": d.area_name,
                    "attributes": d.attributes,
                }
                for d in devices
            ],
            "count": len(devices),
        })
    except HABridgeError as exc:
        return _ha_error_response(exc)


@app.route('/ha/entity/<entity_id>', methods=['GET'])
def ha_entity(entity_id):
    """Get full state for a single entity."""
    from puffpai.ha_bridge import HABridgeError
    bridge = _get_ha_bridge()
    try:
        dev = bridge.get_device(entity_id)
        return jsonify({
            "success": True,
            "entity": {
                "entity_id": dev.entity_id,
                "domain": dev.domain,
                "friendly_name": dev.friendly_name,
                "state": dev.state,
                "is_on": dev.is_on,
                "area_name": dev.area_name,
                "attributes": dev.attributes,
                "last_changed": dev.last_changed,
                "last_updated": dev.last_updated,
            },
        })
    except HABridgeError as exc:
        return _ha_error_response(exc)


#: The route families a ticket can be bound to. A caller cannot invent a kind:
#: an unknown value is refused at mint time, so the binding namespace stays
#: closed and a ticket can never end up bound to a string nothing redeems
#: against (which would look like a working confirmation and silently never
#: authorise anything).
#:
#: ``automation`` and ``automation_run`` are deliberately two kinds, not one.
#: ``automation`` binds an automation *alias* to ``create``; ``automation_run``
#: binds an automation *entity id* to ``trigger`` / ``enable`` / ``disable``.
#: They name different things (an alias is not an entity id), so folding them
#: together would make a ticket minted to create "Night mode" look like it might
#: authorise firing ``automation.night_mode``.
_HA_TICKET_KINDS = frozenset({
    "control", "service", "scene", "automation", "automation_run",
})


@app.route('/ha/confirm', methods=['POST'])
def ha_confirm():
    """Mint a single-use human-confirmation ticket. **Does not actuate.**

    Body: ``{entity_id, action, kind?}`` where *kind* is one of ``control``
    (default), ``service``, ``scene`` or ``automation``. For ``service`` the
    action is the full ``domain.service``; for ``scene`` it is ``activate``; for
    ``automation`` the *entity_id* is the config's ``alias`` and the action is
    ``create``.

    Makes no call to Home Assistant at all — not even a read — so minting cannot
    have a side effect on the house. The response echoes back the proposal the
    ticket is bound to, so the dashboard can render exactly what is being
    approved rather than a generic "are you sure".

    Redeem by including ``"ticket": "<value>"`` in the body of the actuating
    call. The ticket is consumed on first presentation, expires after
    ``_HA_TICKET_TTL_SECONDS``, and authorises only the exact triple it was
    minted for. See :func:`_ha_confirmation_token` for an honest statement of
    what completing this flow does and does not prove.
    """
    body = request.get_json(silent=True) or {}
    if not isinstance(body, dict):
        return jsonify({"success": False,
                        "error": "Request body must be a JSON object"}), 400

    kind = str(body.get("kind") or "control").strip().lower()
    if kind not in _HA_TICKET_KINDS:
        return jsonify({
            "success": False,
            "error": f"Unknown kind {kind!r}. "
                     f"Use one of: {', '.join(sorted(_HA_TICKET_KINDS))}.",
        }), 400

    entity_id = body.get("entity_id")
    action = body.get("action", body.get("service"))
    if not entity_id or not isinstance(entity_id, str):
        return jsonify({"success": False,
                        "error": "entity_id is required (a single string)"}), 400
    if not action or not isinstance(action, str):
        return jsonify({
            "success": False,
            "error": "action is required — a ticket is bound to one action on "
                     "one target, so there is no default",
        }), 400

    proposal = _ha_confirmation_proposal(kind, entity_id, action)
    secret, record = _ha_mint_ticket(kind, entity_id, action)

    return jsonify({
        "success": True,
        "ticket": secret,
        "ticket_id": record["id"],
        "expires_in": _HA_TICKET_TTL_SECONDS,
        "single_use": True,
        "proposal": proposal,
        "message": (
            f"Ticket authorises exactly {proposal['action']} on "
            f"{proposal['entity_id']} once, within "
            f"{_HA_TICKET_TTL_SECONDS}s. Nothing has been actuated."),
    }), 201


@app.route('/ha/control', methods=['POST'])
def ha_control():
    """Control a device. Body: {entity_id, action, ticket?, ...extra service_data}.

    Safety-critical targets (camera, cover, lock, …) are refused with **409** and
    a proposal unless the body carries a ticket from ``POST /ha/confirm`` bound
    to this exact entity and action.
    """
    from puffpai.ha_bridge import HABridgeError
    bridge = _get_ha_bridge()
    body = request.get_json(silent=True) or {}
    if not isinstance(body, dict):
        return jsonify({"success": False,
                        "error": "Request body must be a JSON object"}), 400
    entity_id = body.get("entity_id")
    action = body.get("action", "toggle")

    if not entity_id:
        return jsonify({"success": False, "error": "entity_id is required"}), 400

    # Extra service data (brightness_pct, temperature, …) is splatted into
    # control_device, so this filter is a security boundary, not tidiness: any
    # body key that survives it binds to a *parameter* of the bridge method.
    # _ha_strip_reserved removes entity_id/action (already consumed) plus every
    # spelling of the confirmation parameter, so a caller-supplied
    # "human_confirmed": true is dropped here and never reaches the gate.
    # Regression-tested in tests/test_ha_confirmation_tickets.py.
    extra = _ha_strip_reserved(body, also=("entity_id", "action"))
    extra["human_confirmed"] = _ha_confirmation_token(
        body.get("ticket"), kind="control", entity_id=entity_id, action=action)

    try:
        result = bridge.control_device(entity_id, action, **extra)
        return jsonify(result)
    except HABridgeError as exc:
        return _ha_error_response(exc)


@app.route('/ha/light', methods=['POST'])
def ha_light():
    """Set light properties. Body: {entity_id, brightness_pct?, color_temp?, rgb_color?}."""
    from puffpai.ha_bridge import HABridgeError
    bridge = _get_ha_bridge()
    body = request.json or {}
    entity_id = body.get("entity_id")
    if not entity_id:
        return jsonify({"success": False, "error": "entity_id is required"}), 400

    try:
        result = bridge.set_light(
            entity_id,
            brightness_pct=body.get("brightness_pct"),
            color_temp=body.get("color_temp"),
            rgb_color=body.get("rgb_color"),
        )
        return jsonify(result)
    except HABridgeError as exc:
        return _ha_error_response(exc)


@app.route('/ha/climate', methods=['POST'])
def ha_climate():
    """Set thermostat. Body: {entity_id, temperature?, hvac_mode?}."""
    from puffpai.ha_bridge import HABridgeError
    bridge = _get_ha_bridge()
    body = request.json or {}
    entity_id = body.get("entity_id")
    if not entity_id:
        return jsonify({"success": False, "error": "entity_id is required"}), 400

    try:
        result = bridge.set_climate(
            entity_id,
            temperature=body.get("temperature"),
            hvac_mode=body.get("hvac_mode"),
        )
        return jsonify(result)
    except HABridgeError as exc:
        return _ha_error_response(exc)


@app.route('/ha/service/<domain>/<service>', methods=['POST'])
def ha_service(domain, service):
    """Generic service call passthrough. Body: {ticket?, ...service_data}.

    A ticket for this route must be minted with ``kind: "service"`` and
    ``action: "<domain>.<service>"``. A ``control``-kind ticket for the same
    entity and verb does not redeem here — the two routes reach the bridge by
    different paths and consent is bound to the path the person was shown.
    """
    from puffpai.ha_bridge import HABridgeError
    bridge = _get_ha_bridge()
    body = request.get_json(silent=True) or {}
    if not isinstance(body, dict):
        return jsonify({"success": False,
                        "error": "Request body must be a JSON object"}), 400

    # Same security boundary as /ha/control: the whole body is splatted into
    # call_service, so anything left here binds to a parameter.
    payload = _ha_strip_reserved(body)
    confirmation = _ha_confirmation_token(
        body.get("ticket"), kind="service", entity_id=body.get("entity_id"),
        action=f"{domain}.{service}")
    try:
        result = bridge.call_service(domain, service,
                                     human_confirmed=confirmation, **payload)
        return jsonify({"success": True, "result": result})
    except HABridgeError as exc:
        return _ha_error_response(exc)


@app.route('/ha/rooms', methods=['GET'])
def ha_rooms():
    """Return all HA areas/rooms with their devices."""
    from puffpai.ha_bridge import HABridgeError
    bridge = _get_ha_bridge()
    try:
        rooms = bridge.get_rooms()
        return jsonify({
            "success": True,
            "rooms": [
                {
                    "area_id": r.area_id,
                    "name": r.name,
                    "device_count": len(r.devices),
                    "devices": [
                        {
                            "entity_id": d.entity_id,
                            "domain": d.domain,
                            "friendly_name": d.friendly_name,
                            "state": d.state,
                            "is_on": d.is_on,
                        }
                        for d in r.devices
                    ],
                }
                for r in rooms
            ],
            "count": len(rooms),
        })
    except HABridgeError as exc:
        return _ha_error_response(exc)


# ── Home Blueprint ────────────────────────────────────────────────────────────
#  /ha/rooms above answers "which entities are in which area" and nothing more.
#  The blueprint page needs the house: floors, areas, devices (not entities) and
#  the geometry the owner drew. Two halves, deliberately separate:
#
#  * /ha/home is HA's truth, resolved through puffpai.home_topology — read-only,
#    and it never raises: a hub that is down yields registry.ok=false and a page
#    with no rooms rather than a 502 on the house's own floorplan.
#  * /ha/home/layout is PuffPAI's own file. HA's everyday user is non-admin by
#    design, so areas and geometry the owner invents cannot be written back to
#    the hub; they live here instead. Nothing on this path reaches HA.
#
#  Both are covered by the app-level API-key hook like every other /ha route —
#  no exemption. Actuation stays where it was (/ha/service, /ha/light,
#  /ha/climate) so the always-confirm ticket flow keeps being the only way in.

@app.route('/ha/home', methods=['GET'])
def ha_home():
    """Floors, areas and devices for the blueprint. Read-only."""
    from puffpai.home_topology import home_payload
    include_system = str(request.args.get('include_system', '')).lower() in (
        '1', 'true', 'yes')
    try:
        return jsonify(home_payload(include_system=include_system))
    except Exception:
        # home_payload() is written not to raise — a hub that is down yields
        # registry.ok=false, not an exception. If one gets out anyway, the
        # answer is the same envelope and the same 502 the neighbouring /ha
        # routes give upstream trouble (see _ha_error_response's tail), with a
        # fixed message: the traceback belongs in the log, not in a reply to
        # whoever asked. Note the route stays behind the app-level API-key
        # hook; nothing here is exempt.
        logger.exception("/ha/home failed to build the blueprint payload")
        return jsonify({"success": False,
                        "error": "home blueprint unavailable"}), 502


@app.route('/ha/home/traffic', methods=['GET'])
def ha_home_traffic():
    """Which devices on the floorplan are talking, from the Zone 3 ledger.

    Read-only in the strongest sense: it reuses the telemetry rollup and the
    inventory that already exist and changes nothing — no filter rule, no
    zone3 mode, no bucket, no ledger append, no query-log pull. The only
    network call it can make is AdGuard's own status, over a transport that
    refuses non-LAN addresses.

    Behind the app-level API-key hook like every other /ha route: not in
    _PUBLIC_ENDPOINTS, no loopback exemption. The domains in this payload are
    a record of what the household looked at, so they are never logged here.
    """
    from puffpai.home_traffic import parse_hours, traffic_payload
    hours = parse_hours(request.args.get('hours'))
    if hours is None:
        return jsonify({"success": False,
                        "error": "hours must be an integer from 1 to 168"}), 400
    try:
        return jsonify(traffic_payload(hours))
    except Exception:
        # Same envelope, same fixed message and same 502 as /ha/home above:
        # traffic_payload() is written not to raise (a ledger or an AdGuard
        # that is down is zeros and adguard_reachable=false), so anything that
        # gets out here is a bug, and its traceback belongs in the log rather
        # than in a reply. The message carries no domain and no device.
        logger.exception("/ha/home/traffic failed to build the payload")
        return jsonify({"success": False,
                        "error": "home traffic unavailable"}), 502


@app.route('/ha/home/layout', methods=['GET'])
def ha_home_layout():
    """The stored floorplan, or the empty one the dashboard seeds from."""
    from puffpai import home_layout
    return jsonify({"success": True, **home_layout.load()})


@app.route('/ha/home/layout', methods=['PUT'])
def ha_home_layout_put():
    """Replace the floorplan. Validated strictly, written atomically."""
    from puffpai import home_layout
    too_big = {"success": False,
               "error": f"layout larger than {home_layout.MAX_BYTES} bytes"}
    # Content-Length first so an oversize body can be refused before it is
    # read, and the real length after so a lying header buys nothing.
    if (request.content_length or 0) > home_layout.MAX_BYTES:
        return jsonify(too_big), 400
    body = request.get_data(cache=False)
    if len(body) > home_layout.MAX_BYTES:
        return jsonify(too_big), 400
    if not request.is_json:
        return jsonify({"success": False,
                        "error": "expected application/json"}), 400
    try:
        payload = json.loads(body.decode('utf-8'))
    except (UnicodeDecodeError, ValueError):
        return jsonify({"success": False, "error": "invalid JSON"}), 400
    ok, reason = home_layout.validate(payload)
    if not ok:
        return jsonify({"success": False, "error": reason}), 400
    try:
        stored = home_layout.save(payload)
    except OSError as exc:
        logger.warning("home layout save failed: %s", exc)
        return jsonify({"success": False, "error": "could not store layout"}), 500
    return jsonify({"success": True, **stored})


