@app.route('/ha/automations', methods=['POST'])
def ha_create_automation():
    """Create a new HA automation. Body follows HA automation schema, plus ticket?.

    An automation naming a safety-critical domain is a *stored instruction to
    actuate it later*, so the bridge gates writing it on the same terms as doing
    it. Refusals come back as 409 with a proposal, same shape as ``/ha/control``.
    Ticket kind is ``automation``, entity_id is the config's ``alias``, action is
    ``create``.
    """
    from puffpai.ha_bridge import HABridgeError
    bridge = _get_ha_bridge()
    body = request.get_json(silent=True)
    if not body or not isinstance(body, dict):
        return jsonify({"success": False, "error": "Request body required"}), 400

    # The body is forwarded wholesale to HA's config API, so the ticket and any
    # confirmation-shaped key must be removed before it becomes part of a stored
    # automation — both to keep the gate parameter out of a bridge call and to
    # avoid writing a (spent) ticket into HA's config store.
    ticket = body.get("ticket")
    body = _ha_strip_reserved(body)

    # Consent-gate every entity referenced anywhere in
    # the submitted automation config (triggers, actions, nested targets).
    def _collect_entity_ids(node, out):
        if isinstance(node, dict):
            for k, v in node.items():
                if k == 'entity_id':
                    if isinstance(v, str):
                        out.add(v)
                    elif isinstance(v, list):
                        out.update(x for x in v if isinstance(x, str))
                else:
                    _collect_entity_ids(v, out)
        elif isinstance(node, list):
            for item in node:
                _collect_entity_ids(item, out)

    from puffpai.security.consent_gate import gate_targets
    _targets: set = set()
    _collect_entity_ids(body, _targets)
    review = gate_targets(
        sorted(_targets),
        name=str(body.get('alias', '')),
        task_text='REST /ha/automations POST',
        authored_by='api-client',
    )
    if review['action'] == 'deny' and review['binding']:
        return jsonify({
            "success": False,
            "error": "Denied by Sentinel consent gate",
            "sentinel_review": review,
        }), 403

    try:
        result = bridge.create_automation(
            body,
            human_confirmed=_ha_confirmation_token(
                ticket, kind="automation",
                entity_id=str(body.get('alias', '')), action="create"))
        if isinstance(result, dict):
            result.setdefault('sentinel_review', {
                'action': review['action'],
                'binding': review['binding'],
                'reasons': review['reasons'],
            })
        return jsonify(result), 201
    except HABridgeError as exc:
        return _ha_error_response(exc)


@app.route('/ha/automations/<entity_id>/trigger', methods=['POST'])
def ha_trigger_automation(entity_id):
    """Trigger an automation manually. Optional body: {ticket?}.

    Firing a pre-existing automation is deferred actuation: the bridge resolves
    the automation's stored actions and refuses with **409** when they touch the
    always-confirm class — or when they cannot be read at all. Ticket kind is
    ``automation_run``, action ``trigger``.
    """
    from puffpai.ha_bridge import HABridgeError
    bridge = _get_ha_bridge()
    body = request.get_json(silent=True) or {}
    ticket = body.get("ticket") if isinstance(body, dict) else None
    try:
        result = bridge.trigger_automation(
            entity_id,
            human_confirmed=_ha_confirmation_token(
                ticket, kind="automation_run", entity_id=entity_id,
                action="trigger"))
        return jsonify(result)
    except HABridgeError as exc:
        return _ha_error_response(exc)


@app.route('/ha/automations/<entity_id>/toggle', methods=['POST'])
def ha_toggle_automation(entity_id):
    """Enable or disable an automation. Body: {enable: true/false, ticket?}.

    Gated on the same rule as ``/trigger``: an automation whose actions are
    safety-critical or unreadable cannot be switched on *or* off without a
    confirmation, because disabling the routine that closes the garage is itself
    a security action. Ticket kind is ``automation_run``; the action is
    ``enable`` or ``disable``, and a ticket for one does not redeem for the
    other.

    ``enable`` must be a real boolean (or the strings ``"true"``/``"false"``).
    Anything else is a 400 rather than a guess: the value decides which action
    the ticket has to be bound to, so a truthy ``"no"`` would both do the
    opposite of what was asked and be checked against the wrong binding.
    """
    from puffpai.ha_bridge import HABridgeError
    bridge = _get_ha_bridge()
    body = request.get_json(silent=True) or {}
    if not isinstance(body, dict):
        return jsonify({"success": False,
                        "error": "Request body must be a JSON object"}), 400

    raw = body.get("enable", True)
    if isinstance(raw, bool):
        enable = raw
    elif isinstance(raw, str) and raw.strip().lower() in ("true", "false"):
        enable = raw.strip().lower() == "true"
    else:
        return jsonify({
            "success": False,
            "error": "enable must be true or false",
        }), 400

    try:
        result = bridge.toggle_automation(
            entity_id, enable,
            human_confirmed=_ha_confirmation_token(
                body.get("ticket"), kind="automation_run", entity_id=entity_id,
                action="enable" if enable else "disable"))
        return jsonify(result)
    except HABridgeError as exc:
        return _ha_error_response(exc)


