@app.route('/ha/camera/<entity_id>', methods=['GET'])
def ha_camera(entity_id):
    """Proxy camera image from HA, with per-camera failure backoff.

    The dashboard polls every tile every 30 s, so a camera that stays
    unavailable would produce 20 x 502 per 10-minute window, 2,880 doomed
    upstream requests a day. A failing camera enters an exponential backoff
    (30 s → 10 min, see
    :mod:`puffpai.ha_camera_backoff`); while it is in that window the request
    is answered from here WITHOUT touching Home Assistant, and the failure is
    logged at ERROR exactly once per outage instead of on every poll. The
    status code and body shape are unchanged for existing clients; the added
    ``unavailable`` marker and ``Retry-After`` let the dashboard stop asking.
    One success clears the streak.
    """
    from puffpai.ha_bridge import HABridgeError
    from puffpai import ha_camera_backoff as _cam_backoff

    wait = _cam_backoff.retry_after(entity_id)
    if wait:
        # A poll landing IN the backoff window is not an error: it is this
        # code correctly declining to hammer HA. Answering it with a 502
        # would keep the access log at ~20 failures per 10 min even though
        # the real signal (ERROR lines, upstream calls) is one per outage.
        # So it gets a 200 with an availability flag, and logs at DEBUG, not
        # ERROR (the one ERROR line still fires in record_failure below, at
        # the start of the outage).
        logger.debug("camera %s in backoff, %ss left — not polling HA",
                     entity_id, wait)
        resp = jsonify({
            "success": False,
            "available": False,
            "unavailable": True,
            "entity_id": entity_id,
            "reason": "camera unavailable",
            "retry_after": wait,
            "error": ("camera is reporting unavailable; not polling upstream "
                      "for another %ss" % wait),
        })
        resp.headers["Retry-After"] = str(wait)
        resp.headers["X-PuffPAI-Camera-Unavailable"] = "1"
        resp.headers["Cache-Control"] = "no-store"
        return resp, 200

    bridge = _get_ha_bridge()
    try:
        image_bytes, content_type = bridge.get_camera_image(entity_id)
    except HABridgeError as exc:
        streak, wait, first = _cam_backoff.record_failure(entity_id)
        if first:
            logger.error("camera %s unavailable: %s — backing off, next "
                         "attempt in %ss (further failures at debug)",
                         entity_id, exc, wait)
        else:
            logger.debug("camera %s still unavailable (failure %d): %s — "
                         "next attempt in %ss", entity_id, streak, exc, wait)
        response = _ha_error_response(exc)
        body, status = response if isinstance(response, tuple) else (response, 502)
        try:
            body.headers["Retry-After"] = str(wait)
            body.headers["X-PuffPAI-Camera-Unavailable"] = "1"
        except Exception:                                # pragma: no cover
            pass
        return body, status
    _cam_backoff.record_success(entity_id)
    return Response(
        image_bytes,
        content_type=content_type,
        headers={"Cache-Control": "no-cache"},
    )


@app.route('/ha/devices/overview', methods=['GET'])
def ha_devices_overview():
    """Unified device-management view.

    Merges the live HA entity list (same source /ha/entities uses) with the
    device watcher's known-devices file (managed = status approved/auto) and
    pending-devices file (is_new). Returns per-entity management status plus
    rollup counts.
    """
    from puffpai.ha_bridge import HABridgeError
    bridge = _get_ha_bridge()
    try:
        states = bridge.get_all_states()
    except HABridgeError as exc:
        return _ha_error_response(exc)

    watcher = _get_device_watcher()
    with watcher._lock:
        known = dict(watcher._known)
        pending = dict(watcher._pending)

    devices = []
    counts = {"total": 0, "managed": 0, "unmanaged": 0, "new": 0}

    for entity in states:
        eid = entity.get("entity_id", "")
        if not eid:
            continue
        domain = eid.split(".")[0] if "." in eid else "unknown"
        attrs = entity.get("attributes", {}) or {}
        name = attrs.get("friendly_name", eid)
        state = entity.get("state", "unknown")

        kd = known.get(eid)
        pd = pending.get(eid)

        is_new = pd is not None
        is_managed = (kd is not None and kd.status in ("approved", "auto"))
        security_mode = kd.security_mode if kd is not None else None

        if pd is not None:
            first_seen = pd.discovered_at or None
        elif kd is not None:
            first_seen = kd.approved_at or None
        else:
            first_seen = None

        devices.append({
            "entity_id": eid,
            "name": name,
            "domain": domain,
            "state": state,
            "managed": is_managed,
            "is_new": is_new,
            "security_mode": security_mode,
            "first_seen": first_seen,
        })

        counts["total"] += 1
        if is_new:
            counts["new"] += 1
        elif is_managed:
            counts["managed"] += 1
        else:
            counts["unmanaged"] += 1

    return jsonify({
        "success": True,
        "devices": devices,
        "counts": counts,
    })


