@app.route('/devices/simulate-discovery', methods=['POST'])
def devices_simulate_discovery():
    """Inject a synthetic pending device so testing has a reliable
    trigger for the 'new device detected' notification.

    Body (all optional):
        entity_id: HA-style entity id (default: a fake zigbee sensor)
        friendly_name: display name
        domain: light, sensor, switch, etc. (default: sensor)
        manufacturer: default "Zigbee USB Adapter"
        model: default "CC2652P"
    """
    from puffpai.ha_device_watcher import PendingDevice, get_watcher
    import uuid as _uuid
    body = request.json or {}
    watcher = get_watcher()

    nonce = _uuid.uuid4().hex[:6]
    eid = body.get('entity_id') or f"sensor.new_zigbee_device_{nonce}"
    domain = body.get('domain') or (eid.split('.', 1)[0] if '.' in eid else 'sensor')
    friendly = body.get('friendly_name') or 'Zigbee Device (just plugged in)'
    manufacturer = body.get('manufacturer') or 'Zigbee USB Adapter'
    model = body.get('model') or 'CC2652P'

    pending = PendingDevice(
        entity_id=eid,
        domain=domain,
        friendly_name=friendly,
        state='discovered',
        manufacturer=manufacturer,
        model=model,
        suggested_action='lockdown',
        category='smart_home',
        discovered_at=datetime.now().isoformat(),
        attributes={'simulated': True, 'source': 'demo_injection'},
    )
    with watcher._lock:
        watcher._pending[eid] = pending
        watcher._save_pending()
    logger.info("Simulated discovery: %s (%s)", friendly, eid)
    return jsonify({
        'success': True,
        'message': f'Discovered {friendly}',
        'device': pending.to_dict(),
        'total_pending': watcher.get_pending_count(),
    })


