@app.route('/automation/status', methods=['GET'])
def automation_status():
    """Check automation-engine connectivity and return webhook info."""
    try:
        from puffpai.automation_client import AutomationClient
        client = AutomationClient()
        reachable = client.is_reachable()
        webhooks = {
            'block_device': client.webhook_url('block_device'),
            'network_scan': client.webhook_url('network_scan'),
            'weather_alerts': client.webhook_url('weather_alerts'),
            'puffpai_voice': client.webhook_url('puffpai_voice'),
        }
        return jsonify({
            'success': True,
            'connected': reachable,
            'engine': 'node-red',
            'base_url': client.base_url,
            'webhooks': webhooks,
        })
    except Exception as exc:
        return jsonify({
            'success': False,
            'connected': False,
            'error': str(exc),
        })


@app.route('/automation/trigger/<webhook_name>', methods=['POST'])
def automation_trigger(webhook_name):
    """Trigger an automation webhook by name.

    A flow that reaches the internet is not started while its Bridge switch is
    off: 403 with ``reason: bridge_closed`` and the sentence naming the switch.
    """
    try:
        from puffpai.automation_client import (
            WEBHOOK_SWITCHES, AutomationClient, switch_refusal)
        refused = switch_refusal(webhook_name)
        if refused:
            return jsonify({'success': False, 'reason': 'bridge_closed',
                            'switches': list(WEBHOOK_SWITCHES[webhook_name]),
                            'error': refused}), 403
        client = AutomationClient()
        payload = request.get_json(silent=True) or {}
        ok, data = client.call(webhook_name, payload)
        return jsonify({'success': ok, 'data': data})
    except ValueError as exc:
        return jsonify({'success': False, 'error': str(exc)}), 400
    except Exception as exc:
        return jsonify({'success': False, 'error': str(exc)}), 500


@app.route('/automation/flows', methods=['GET'])
@app.route('/workflows', methods=['GET'])
def automation_flows():
    """The real Node-RED flow list — every tab in the runtime + active status.

    A hand-maintained list in the dashboard Workflows tab would hide every
    automation it does not name and show static blurbs. This reads the *live*
    flows the same way the Bridge "list workflows" task does
    (Node-RED admin ``GET /flows``), so the tab shows what is really deployed.
    Response: ``{success, total, active, inactive, workflows:[{id,name,active}]}``.
    """
    out = _bridge_list_workflows()
    result = dict(out.get('result') or {})
    result['success'] = bool(out.get('success'))
    return jsonify(result)


# ══════════════════════════════════════════════════════════════════════════════
#  AGENT TEAM ENDPOINTS
# ══════════════════════════════════════════════════════════════════════════════

# Resolved by puffpai.agent_activity, which owns the feed. The resolution lives
# outside this module because this file is the feed's only READER while
# security/consent_requests.py is one of its writers, and a writer too low in
# the import graph to ask the server where the feed lives would otherwise
# answer for itself, possibly into a path where every consent request and
# verdict is dropped by a silent `except OSError`. One resolver keeps reader
# and writers on one file under every configuration.
# The env-unset default is <repo>/data with a legacy logs directory adopted
# per FILE, so a dev install keeps the history the dashboard already shows.
from puffpai import agent_activity as _agent_activity  # noqa: E402


# Called on FIRST USE, never at import. These were module-scope constants
# (`_ACTIVITY_LOG = _agent_activity.get_activity_log_path()`), which resolved
# while api_server was still being imported: puffpai.agent_activity is a leaf
# and safe to import here, but the RESOLUTION it performs reaches
# puffpai.config, and with it the secrets provider and the vault. That is the
# import-time cycle risk puffpai.statedir exists to avoid, and it also froze
# the answer before a test (or a late `os.environ` edit) could move it.
# agent_activity caches per filename, so calling these per use is a dict hit.

def _agent_logs_dir() -> str:
    return _agent_activity.agent_logs_dir()


def _activity_log() -> str:
    return _agent_activity.get_activity_log_path()


def _task_queue() -> str:
    return _agent_activity.resolve_agent_log("task-queue.jsonl")

# ── Six-agent product team (PUFFPAI_PRODUCT_AGENT_TEAM_PLAN) ──────────────────
# Built lazily and cached. Engines inside each agent are themselves lazy, so
# construction is cheap; enabled by default and gated by PUFFPAI_AGENT_TEAM_ENABLED.
_agent_team_bus = None


def _agent_team_enabled() -> bool:
    return os.environ.get("PUFFPAI_AGENT_TEAM_ENABLED", "1").lower() in (
        "1", "true", "yes",
    )


def _get_agent_team():
    """Return the cached AgentBus for the six-agent team, or None if disabled."""
    global _agent_team_bus
    if not _agent_team_enabled():
        return None
    if _agent_team_bus is None:
        try:
            from puffpai.agents import build_team
            _agent_team_bus = build_team()
            # Share the bus with the event-intake module so pushed events and
            # chat go through ONE bus (one Sentinel, one audit ledger).
            from puffpai import agent_events as _agent_events
            _agent_events.set_bus(_agent_team_bus)
            # Count from the roster, never from a literal: the line said "six
            # agents" while seven were being built (Toolsmith joined and the
            # string did not), so the one place an operator looks to confirm
            # the team came up was telling them the wrong number.
            from puffpai.agents.registry import ROSTER
            logger.info("Product-agent team initialized (%d agents + bus).",
                        len(ROSTER))
        except Exception as exc:
            logger.warning("Product-agent team failed to initialize: %s", exc)
            _agent_team_bus = None
    return _agent_team_bus


def _chat_envelope_budget():
    """The budget a chat message carries onto the bus.

    Two sizes, because chat has two shapes.

    With the planning loop **off**, a chat turn is one delegated action plus the
    Concierge's read-only device-list lookup, and a tight ceiling is the honest
    bound on that.

    With the loop **on**, the very same envelope is also the *parent* of a
    planned run, and :meth:`PlanningLoop._derive_budget` takes the minimum of the
    loop's own limits and this one — invariant 2, a run may never mint or extend
    its own budget. So a budget sized for single-step delegation silently becomes
    the loop's ceiling: at 20s a two-step run spent its whole wall clock on the
    planner call and came back "I'm not able to read the temperature sensor or
    scan for devices right now." The fix belongs here, at the caller, precisely
    because the loop is right to refuse to grow.

    When the loop is on, this therefore must not be the binding constraint. It
    carries the loop's own ceiling in actions, and twice its ceiling in seconds:
    the planner call and target resolution run on the parent's clock before the
    derived budget exists, so the extra headroom keeps *this* number from
    becoming the limit again by a different route.
    """
    from puffpai.agents import Budget
    from puffpai.agents.planning_loop import (
        DEFAULT_MAX_ACTIONS,
        DEFAULT_MAX_SECONDS,
        planning_loop_enabled,
    )

    if planning_loop_enabled():
        # Chat egress is opt-in and DEFAULT OFF. A chat turn carries egress only
        # when BOTH (a) the planning loop is on (this branch) AND (b) the owner
        # has set the explicit opt-in. Read through the same env-then-config flag
        # mechanism the loop kill-switch uses, so the toggle lives beside it in
        # puffpai_config.json (agents.chat_allow_egress) or the unit file
        # (PUFFPAI_CHAT_ALLOW_EGRESS=1). With the opt-in unset — the default —
        # allow_egress stays False and behaviour is exactly as before.
        #
        # This is the ONLY place a chat envelope can acquire egress. The planning
        # loop inherits egress and never mints it (planning_loop._derive_budget),
        # and the sealed EgressScope still decides WHICH host each step may reach.
        # So this flag gates whether the door can open at all; it never widens
        # what is reachable once open.
        #
        # ANDed with the egress DOORS. The opt-in answers "may an
        # ad-hoc chat turn reach outward at all"; the door answers "may this
        # appliance reach that class of destination at all". Both are the
        # owner's, both default off, and neither substitutes for the other —
        # with every web door shut the opt-in now grants nothing, which is what
        # an owner who closed those doors expects. The grant here is coarse ("a
        # web door is open") on purpose: the Toolsmith re-checks the exact door
        # before any socket opens, so this budget can only ever be the outer
        # bound, never the thing that decides.
        from puffpai.security.egress_policy import chat_egress_allowed
        allow_egress, egress_reason = chat_egress_allowed()
        if not allow_egress:
            logger.debug("chat envelope carries no egress: %s", egress_reason)
        return Budget(max_actions=DEFAULT_MAX_ACTIONS,
                      max_seconds=DEFAULT_MAX_SECONDS * 2,
                      allow_egress=allow_egress)
    # Loop off: behaviour is exactly as today — no egress, tight ceiling. The
    # opt-in above has no effect without the loop, so egress needs both halves.
    # Headroom for the Concierge's read-only device-list lookup on top of
    # the delegated action it resolves.
    return Budget(max_actions=6, max_seconds=20.0, allow_egress=False)


def _trim_history_for_team(history, max_pairs: int = 3,
                           max_chars: int = 400) -> list[dict]:
    """Clip chat history to what the team may reasonably carry.

    The planner's context is 4096 tokens and a single assistant turn can be a
    111-device enumeration, so both dimensions are bounded: the last
    *max_pairs* exchanges, each side clipped to *max_chars*.
    """
    if not isinstance(history, list):
        return []
    trimmed = []
    for pair in history[-max_pairs:]:
        if not isinstance(pair, dict):
            continue
        trimmed.append({
            "user": str(pair.get("user") or "")[:max_chars],
            "assistant": str(pair.get("assistant") or "")[:max_chars],
        })
    return trimmed


def _route_via_concierge(task_text: str, requester: str = "owner",
                         history: list | None = None) -> dict | None:
    """Route a task through the Concierge on the bus (veto + audit apply).

    Returns the Concierge reply dict, or None if the team is disabled/unavailable.
    Never raises — task submission must keep working if the team is off.
    """
    bus = _get_agent_team()
    if bus is None:
        return None
    try:
        from puffpai.agents import Envelope
        payload = {"text": task_text}
        trimmed = _trim_history_for_team(history)
        if trimmed:
            payload["conversation_history"] = trimmed
        env = Envelope(
            intent="chat",
            payload=payload,
            requester=requester,
            # NOT a HUMAN_ORIGINS value: the Steward's always-confirm siren gate
            # is exactly that check, so chat can propose a siren but never fire it.
            origin_agent="api_server",
            # Read per request: the loop is a runtime toggle the owner can reach,
            # so the size is decided now, not at import.
            budget=_chat_envelope_budget(),
            state_changing=False,
        )
        return bus.send(env, to="concierge")
    except Exception as exc:
        logger.debug("concierge routing failed: %s", exc)
        return None


# ── Product team as the chat front door ──────────────────────────────────────
# The dashboard chat has always reached the LEGACY PuffPAIAgent: every chat
# route funnels through _detect_route() and the "agent" branch calls
# _get_assistant_tools().run(). The six-agent team was only reachable via
# /agents/task, so "the agent team" never actually ran the user's command.
#
# PREDICATE (deliberately narrow):
#   _detect_route(...) == "agent"  AND  the kill-switch is on  AND  the
#   Concierge comes back with handled=True.
#
# * "rag" and "library" never reach the team — knowledge answers are already
#   good and the Archivist would be a regression.
# * "briefing" stays legacy — daily_briefing() aggregates sources the team
#   cannot see yet.
# * Within "agent", the CONCIERGE decides: it only claims a turn when its
#   deterministic resolver matched a real Steward intent (or the router already
#   called the message "home"). Calendar, timers, recipes, uploaded documents,
#   web search and firewall traffic all come back handled=False and fall
#   through to the legacy agent unchanged.
_CHAT_VIA_TEAM_ENV = "PUFFPAI_CHAT_VIA_TEAM"


def _chat_via_team_enabled() -> bool:
    """Kill-switch: set PUFFPAI_CHAT_VIA_TEAM=0 to restore the legacy-only chat."""
    return os.environ.get(_CHAT_VIA_TEAM_ENV, "1").strip().lower() in (
        "1", "true", "yes", "on",
    )


def _try_team_chat(user_message: str, route: str,
                   requester: str = "owner",
                   history: list | None = None) -> dict | None:
    """Let the product team answer an action-shaped chat turn.

    Returns an enriched chat-result dict, or None to fall back to the legacy
    path. Never raises.
    """
    if route != "agent" or not _chat_via_team_enabled():
        return None
    try:
        reply = _route_via_concierge(user_message, requester=requester,
                                     history=history)
    except Exception as exc:  # defence in depth; _route_via_concierge swallows
        logger.debug("team chat failed: %s", exc)
        return None
    if not isinstance(reply, dict) or not reply.get("ok"):
        return None
    if not reply.get("handled") or not reply.get("reply"):
        return None

    # HIGH-PRECISION GUARD for PLANNED turns. Mirrors the rule the
    # composed-plan interceptor already applies on briefing/library/rag:
    # a plan that stalls into a clarification, or stops after a
    # reconnaissance step, is NOT better than the legacy answer.
    #
    # This is what makes widening _should_plan to information goals safe.
    # When the planner fails to finish an unmatched turn it degrades to
    # exactly the answer it would have given before, so Blocker-1 holds
    # by construction rather than by the gate being narrow. A wrong
    # guess costs latency, never a worse answer.
    plan = reply.get("plan")
    if isinstance(plan, dict) and plan:
        try:
            executed = int(plan.get("executed") or 0)
        except (TypeError, ValueError):
            executed = 0
        if str(plan.get("stop_reason") or "") != "goal_satisfied" or executed < 1:
            print("[Chat] Plan did not satisfy the goal -> legacy agent")
            return None

    # A report the leak guard will REJECT is not an answer either. The planner's
    # success report is a work log ("I ran 1 of 1 planned step(s): 1.
    # archivist.get_memory — done"), and _CHAT_LEAK_MARKERS matches "planned
    # step" / "step(s):" — so downstream it became "Sorry, I couldn't complete
    # that one" while the plan had, by its own account, succeeded. Checking the
    # SAME predicate here turns that dead end back into the legacy answer, which
    # is what the guard above already does for every other way a plan can fail.
    # The guard itself is untouched: a work log still never reaches the user.
    reply_text = str(reply['reply'])
    if any(m in reply_text.lower() for m in _CHAT_LEAK_MARKERS):
        print("[Chat] Plan reported only a work log -> legacy agent")
        return None

    print(f"[Chat] Team handled: {reply.get('intent')} -> {reply.get('targets')}")
    reply_text = _reword_single_control_reply(reply, reply_text)
    return {
        'response': reply_text,
        'sources': [],
        'suggestions': [],
        # Structured result for clients that can render more than prose.
        'team': {
            'agent': reply.get('delegated_to'),
            'intent': reply.get('intent'),
            'targets': reply.get('targets') or [],
            'result': reply.get('delegate_reply'),
        },
    }


def _reword_single_control_reply(reply: dict, reply_text: str) -> str:
    """Say a control action the way the compound path says it.

    Without this the SAME action has two voices: the compound clause answers
    ``Hallway Light is now on.`` while the plain single command answers
    ``Done - light.hallway_light turn on.``, the raw entity id and a broken
    verb phrase. The compound path is right because it READS THE ENTITY BACK
    after the call, so its friendly name and its tense both come from the
    house rather than from the request. This routes the single-command path
    through the same helper.

    Falls back to the specialist's own prose whenever the read-back is not
    applicable: a denial, an unavailable device, more than one target, or an
    intent that has no settled end state to observe.
    """
    if getattr(_COMPOUND_TL, "active", False):
        return reply_text  # the compound path does its own read-back
    if reply.get('intent') not in _COMPOUND_VERIFIABLE_INTENTS:
        return reply_text
    targets = [t for t in (reply.get('targets') or []) if isinstance(t, str)]
    if len(targets) != 1:
        return reply_text
    delegate = reply.get('delegate_reply')
    if not isinstance(delegate, dict) or not delegate.get('ok'):
        return reply_text
    if delegate.get('denied') or delegate.get('unavailable'):
        return reply_text
    result = delegate.get('result')
    action = result.get('action') if isinstance(result, dict) else None
    action = action or reply.get('intent')
    try:
        from puffpai import compound_turns as ct
        name, state = _observe_entity_after_action(targets[0], action)
        return ct.observed_action_reply(name, action, state)
    except Exception as exc:
        logger.debug("control reply read-back failed for %s: %s",
                     targets[0], exc)
        return reply_text


def _read_jsonl_tail(path: str, limit: int = 50) -> list[dict]:
    """Read the last *limit* lines from a JSONL file."""
    if not os.path.isfile(path):
        return []
    lines: list[str] = []
    try:
        with open(path, 'r', encoding='utf-8') as f:
            lines = f.readlines()
    except OSError:
        return []
    result = []
    for line in lines[-limit:]:
        line = line.strip()
        if not line:
            continue
        try:
            result.append(json.loads(line))
        except json.JSONDecodeError:
            pass
    return result


def _append_jsonl(path: str, entry: dict) -> None:
    """Append a single JSON object as a line to a JSONL file."""
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, 'a', encoding='utf-8') as f:
        f.write(json.dumps(entry) + '\n')


