# ══════════════════════════════════════════════════════════════════════════════
#  MEDIA SERVER ENDPOINTS (Jellyfin + Calibre-Web on Pi 4)
# ══════════════════════════════════════════════════════════════════════════════

def _get_media_bridge():
    """Lazy-load media bridge singleton."""
    from puffpai.media_bridge import get_media_bridge
    return get_media_bridge()


def _media_error_response(exc):
    """Convert a MediaBridgeError into a Flask JSON response tuple.

    Bridge-level input validation (session/item/playlist ids, which become
    Jellyfin URL path segments) is a *caller* error, so it answers 400 rather
    than the 503 used for an unreachable or disabled media server. Checked
    first so a sanitised echo of the rejected input cannot pick another branch.
    """
    msg = str(exc)
    if msg.startswith('invalid '):
        return jsonify({'error': msg}), 400
    return jsonify({'error': msg}), 503


@app.route('/api/media/status', methods=['GET'])
def media_status():
    """Connection health for media server (Jellyfin + Calibre-Web)."""
    bridge = _get_media_bridge()
    return jsonify(bridge.get_status())


@app.route('/api/media/search', methods=['GET'])
def media_search():
    """Unified media search. Params: type (music|movie|book), q, artist, genre, year."""
    from puffpai.media_bridge import MediaBridgeError
    bridge = _get_media_bridge()
    media_type = request.args.get('type', 'music')
    query = request.args.get('q', '')

    try:
        if media_type == 'music':
            items = bridge.search_music(
                query,
                artist=request.args.get('artist', ''),
                genre=request.args.get('genre', ''),
            )
        elif media_type == 'movie':
            year = int(request.args.get('year', 0) or 0)
            items = bridge.search_movies(
                query,
                genre=request.args.get('genre', ''),
                year=year,
            )
        elif media_type == 'book':
            items = bridge.search_books(
                query,
                author=request.args.get('author', ''),
            )
        else:
            return jsonify({'error': f'Unknown type: {media_type}'}), 400

        return jsonify({
            'type': media_type,
            'query': query,
            'count': len(items),
            'items': [
                {
                    'id': i.item_id, 'title': i.title, 'artist': i.artist,
                    'album': i.album, 'genre': i.genre, 'year': i.year,
                    'display': i.display,
                }
                for i in items
            ],
        })
    except MediaBridgeError as exc:
        return jsonify({'error': str(exc)}), 503


@app.route('/api/media/now-playing', methods=['GET'])
def media_now_playing():
    """Currently active playback sessions."""
    from puffpai.media_bridge import MediaBridgeError
    bridge = _get_media_bridge()
    try:
        sessions = _now_playing_payload(bridge)
    except MediaBridgeError as exc:
        return jsonify({'error': str(exc)}), 503

    # Additive: 'sessions' keeps its exact old shape for existing callers.
    # Jellyfin is the only source with a server to ask; the rest report in.
    from puffpai import media_hub
    return jsonify({
        'sessions': sessions,
        'sources': media_hub.aggregate_sources(_get_app_data(), sessions),
    })


def _now_playing_payload(bridge):
    """Shared now-playing serialisation for the media API + dashboard widget."""
    from puffpai.config import get_config
    jf_url = get_config().media_server.jellyfin_url.rstrip('/')
    out = []
    for s in bridge.now_playing():
        art_url = None
        if s.now_playing:
            art_id = s.now_playing.extra.get('album_id') or s.now_playing.item_id
            if art_id:
                art_url = f"{jf_url}/Items/{art_id}/Images/Primary?maxWidth=400"
        out.append({
            'session_id': s.session_id,
            'client': s.client_name,
            'device': s.device_name,
            'user': s.user_name,
            'is_paused': s.is_paused,
            'position_seconds': s.position_seconds,
            'volume_level': s.volume_level,
            'now_playing': {
                'item_id': s.now_playing.item_id,
                'title': s.now_playing.title,
                'artist': s.now_playing.artist,
                'album': s.now_playing.album,
                'type': s.now_playing.media_type,
                'duration_seconds': s.now_playing.duration_seconds,
                'art_url': art_url,
            } if s.now_playing else None,
        })
    return out


@app.route('/api/media/play', methods=['POST'])
def media_play():
    """Start playback. Body: { "item_id": "...", "session_id": "..." }."""
    from puffpai.media_bridge import MediaBridgeError, is_valid_media_id
    bridge = _get_media_bridge()
    data, err = _json_object_body()
    if err:
        return err
    item_id = data.get('item_id', '')
    session_id = data.get('session_id', '')

    if not item_id:
        return jsonify({'error': 'item_id required'}), 400
    # Both become Jellyfin URL path/query components downstream. Reject here so
    # a malformed id never reaches an API-key-authenticated request at all; the
    # bridge re-checks as the last hop. An empty session_id means "auto-pick".
    if not is_valid_media_id(item_id):
        return jsonify({'error': 'item_id must be a valid Jellyfin id'}), 400
    if session_id and not is_valid_media_id(session_id):
        return jsonify({'error': 'session_id must be a valid Jellyfin id'}), 400

    try:
        result = bridge.play_music(item_id, session_id)
        return jsonify({'success': True, 'message': result})
    except MediaBridgeError as exc:
        return _media_error_response(exc)


@app.route('/api/media/control', methods=['POST'])
def media_control():
    """Playback control. Body: { "session_id": "...", "action": "pause|resume|stop|next|previous" }
    or { "session_id": "...", "action": "volume", "volume": 0-100 }."""
    from puffpai.media_bridge import MediaBridgeError, is_valid_media_id
    bridge = _get_media_bridge()
    data, err = _json_object_body()
    if err:
        return err
    session_id = data.get('session_id', '')
    action = data.get('action', '')

    if not session_id or not action:
        return jsonify({'error': 'session_id and action required'}), 400
    # session_id becomes a Jellyfin URL path segment (/Sessions/<id>/...).
    if not is_valid_media_id(session_id):
        return jsonify({'error': 'session_id must be a valid Jellyfin id'}), 400

    try:
        if action == 'volume':
            volume = data.get('volume')
            if volume is None:
                return jsonify({'error': 'volume (0-100) required for volume action'}), 400
            result = bridge.set_volume(session_id, int(volume))
        else:
            result = bridge.playback_control(session_id, action)
        return jsonify({'success': True, 'message': result})
    except MediaBridgeError as exc:
        return _media_error_response(exc)


@app.route('/api/media/stats', methods=['GET'])
def media_stats():
    """Library statistics: counts of tracks, albums, movies, books."""
    from puffpai.media_bridge import MediaBridgeError
    bridge = _get_media_bridge()
    try:
        return jsonify(bridge.library_stats())
    except MediaBridgeError as exc:
        return jsonify({'error': str(exc)}), 503


@app.route('/api/media/scan', methods=['POST'])
def media_scan():
    """Trigger Jellyfin library rescan."""
    from puffpai.media_bridge import MediaBridgeError
    bridge = _get_media_bridge()
    try:
        result = bridge.trigger_scan()
        return jsonify({'success': True, 'message': result})
    except MediaBridgeError as exc:
        return jsonify({'error': str(exc)}), 503


# ══════════════════════════════════════════════════════════════════════════════
#  SERVER STARTUP
# ══════════════════════════════════════════════════════════════════════════════

_background_services_started = False


def start_background_services() -> None:
    """Start LLM warm-up, chat history, and the Device Sentinel.

    Lives outside the ``__main__`` block so ``puffpai.service`` (the
    production entry point) starts the Sentinel too; otherwise quarantine
    protection would be silently absent in service mode. Both entry points
    call this. Idempotent.
    """
    global _background_services_started
    if _background_services_started:
        return
    _background_services_started = True

    # App-data at-rest sweep. FIRST, synchronously, and before anything can
    # serve a request: a file's mode is fixed at CREATION from the umask, and
    # write_json_secure only corrects a document the appliance happens to
    # rewrite. The documents nobody rewrites are not the harmless ones: a
    # calendar.json holding medications and bills, or a fitfam.json holding a
    # minor's health history, can otherwise sit group- or world-readable
    # while the least sensitive file is 0600. Logs BASENAMES ONLY and never
    # opens a file. Never fatal.
    try:
        from puffpai.security.app_data_store import sweep_app_data_modes
        from puffpai.app_data import _data_dir as _app_data_dir
        sweep_app_data_modes(_app_data_dir())
    except Exception as _exc:
        logger.warning("[Startup] app-data mode sweep skipped: %s", _exc)

    # Pre-warm the LLM model so the first real prompt is fast.
    # NOTE: must warm at the RUNTIME num_ctx, or the first real prompt reloads.
    def _warmup():
        try:
            _ollama_chat(
                [{"role": "user", "content": "ping"}],
                num_predict=1,
                timeout=60,
            )
            print("[Startup] LLM model warmed up and ready (runtime ctx).")
        except Exception as e:
            print(f"[Startup] LLM warm-up failed (non-critical): {e}")

    threading.Thread(target=_warmup, daemon=True).start()

    # Load persisted chat history from disk
    _load_chat_history()

    # Device Sentinel: OPT-IN. Active quarantine + firewall enforcement is OFF
    # by default: a quarantine enforcing against a stale or unreviewed
    # baseline can block legitimate devices. A first enabled run seeds a
    # fresh baseline, so the load-bearing safety step is the observe-only
    # period. The enable procedure (check the baseline, observe-only 1–2
    # weeks, then enforcement with the consent flow) lives in
    # docs/DEVICE_SENTINEL.md.
    if _sentinel_enabled():
        try:
            from puffpai.device_sentinel import get_sentinel, DEFAULT_INTERVAL_SECONDS
            _sentinel = get_sentinel(
                interval_seconds=DEFAULT_INTERVAL_SECONDS,
                on_alert=_sentinel_chat_push,
            )
            _sentinel.start()
            print(f"[Startup] Device Sentinel running ({DEFAULT_INTERVAL_SECONDS}s interval, "
                  f"baseline={_sentinel.status()['baseline_size']} devices).")
        except Exception as _exc:
            print(f"[Startup] Device Sentinel failed to start: {_exc}")
    else:
        print("[Startup] Device Sentinel DISABLED on purpose "
              "(PUFFPAI_SENTINEL_ENABLED not set). It is opt-in: "
              "auto-quarantine against an unreviewed baseline could block "
              "legitimate devices. Enabling it must start "
              f"observe-only. See {SENTINEL_DOCS}.")

    # Six-agent product team — ON by default, gated by PUFFPAI_AGENT_TEAM_ENABLED.
    # Construction is cheap (engines are lazy); this just warms the roster + bus.
    if _agent_team_enabled():
        try:
            bus = _get_agent_team()
            if bus is not None:
                h = bus.health()
                print(f"[Startup] Product-agent team ready: {h['agent_count']} agents, "
                      f"reviewer={h['reviewer']} (wired={h['reviewer_wired']}).")
            else:
                print("[Startup] Product-agent team enabled but unavailable "
                      "(see warning above).")
        except Exception as _exc:
            print(f"[Startup] Product-agent team failed to start: {_exc}")
    else:
        print("[Startup] Product-agent team DISABLED (PUFFPAI_AGENT_TEAM_ENABLED=0).")

    # HA event listener — event inflow for the agent team (orchestration Phase 1).
    # Read-only WebSocket subscription; starts only when HA and ha_events are
    # both enabled. Same daemon-thread pattern as the Device Sentinel above.
    try:
        from puffpai.ha_events import start_listener as _start_ha_events
        _ha_listener = _start_ha_events()
        if _ha_listener is not None:
            _st = _ha_listener.status()
            print(f"[Startup] HA event listener running "
                  f"({len(_st['watch_entities'])} watched entities, "
                  f"{_st['debounce_seconds']}s debounce).")
        else:
            print("[Startup] HA event listener DISABLED "
                  "(ha.enabled / ha_events.enabled off, or no token).")
    except Exception as _exc:
        print(f"[Startup] HA event listener failed to start: {_exc}")

    # The clock: server-side firing for AlarmFlow alarms/timers and Calendar
    # reminders. Before this, an alarm only rang while its own screen was the
    # mounted one and a "remind me on Monday" row was never looked at
    # again. Same daemon-thread pattern as the Sentinel above; the
    # sentence reaches the speaker through puffpai.announcer, which the voice
    # service drains under the duck policy (this process has no PulseAudio).
    try:
        from puffpai.scheduler import start_scheduler as _start_scheduler
        _sched = _start_scheduler()
        if _sched is not None:
            _ss = _sched.status()
            print(f"[Startup] Scheduler running ({_ss['tick_seconds']}s tick, "
                  f"sources={', '.join(_ss['sources']) or 'none'}).")
        else:
            print("[Startup] Scheduler DISABLED (PUFFPAI_SCHEDULER=0) — "
                  "alarms and reminders will not fire on their own.")
    except Exception as _exc:
        print(f"[Startup] Scheduler failed to start: {_exc}")

    # Majordomo task dispatcher — initiative for the agent team (Phase 2).
    # Consumes the scheduled-task queue and sends each due task through the
    # SAME bus as chat/events, so Sentinel veto + audit cover scheduled work.
    try:
        from puffpai.agents.dispatcher import start_dispatcher as _start_dispatcher
        _dispatch = _start_dispatcher()
        if _dispatch is not None:
            _ds = _dispatch.status()
            print(f"[Startup] Task dispatcher running "
                  f"({_ds['tick_seconds']}s tick, disable after "
                  f"{_ds['max_consecutive_failures']} consecutive failures).")
        else:
            print("[Startup] Task dispatcher DISABLED (dispatcher.enabled off).")
    except Exception as _exc:
        print(f"[Startup] Task dispatcher failed to start: {_exc}")


# ── The Hatch: naming ritual + adoption certificate ─────────────────────────
# Routes live in puffpai.hatch_api (registered here so they inherit the API
# key gate + rate limiter — none are in _PUBLIC_ENDPOINTS). The hook keeps the
# import-time AI_NAME honest when the owner hatches or renames the Puff, so
# the deterministic identity answers (_maybe_identity_answer) name the same
# Puff the dashboard shows without waiting for a restart.

def _on_puff_renamed(new_name):
    global AI_NAME
    AI_NAME = new_name
    logger.info("Puff renamed via hatch: AI_NAME refreshed to %r", new_name)


try:
    from puffpai import hatch_api as _hatch_api
    _hatch_api.register(app, on_name_change=_on_puff_renamed)
except Exception as _hatch_exc:  # the hatch must never take the API down
    logger.warning("hatch API unavailable: %s", _hatch_exc)


# ══════════════════════════════════════════════════════════════════════════════
#  SETUP / ONBOARDING ENDPOINTS  (the browser face of `puffpai setup`)
# ══════════════════════════════════════════════════════════════════════════════
#
# These back the graphical first-run wizard in the dashboard. Every one of them
# is a THIN call into :mod:`puffpai.setup_ops`; no wizard policy is restated
# here, so the CLI face and the browser face cannot drift.
#
# ── auth ────────────────────────────────────────────────────────────────────
# All of them require the app API key, exactly like every other route. NONE is
# added to ``_PUBLIC_ENDPOINTS`` and none is added to
# ``endpoint_gate.LOCAL_ONLY_ENDPOINTS``.
#
# That is the stricter of the two behaviours available:
#
#   * BuildBot's release build gates the whole /setup/* family behind the key
#     and makes nothing public ("none are public", api_server.py:8628).
#   * This build additionally owns a same-host exemption tier
#     (LOCAL_ONLY_ENDPOINTS) for callers that genuinely cannot attach a header.
#
# The setup family has no such caller. The dashboard reaches the backend through
# its own server-side proxy (dashboard/app/api/pai/[...path]/route.ts), which
# injects the key; the CLI wizard does not go through HTTP at all. And there is
# no first-run bootstrap hole to open: ``_load_or_create_api_key()`` mints the
# key before the first request is ever served, so "the owner has no key yet" is
# not a state this build can be in. Adding a keyless tier would therefore buy
# nothing and would hand any LAN peer the vault-sealing and HA-token routes.
#
# ── after completion ────────────────────────────────────────────────────────
# Once ``setup_ops.is_complete()`` is true the wizard is over. Reads stay open
# (the dashboard renders a summary from them); STATE-CHANGING calls need a live
# vault session (``X-Vault-Token`` from /vault/unlock) or get 409
# ``setup_complete``. The vault routes are stricter still: they are refused
# outright after completion, with no session bypass, because re-sealing a vault
# through an onboarding route would destroy the household's data under a PIN the
# caller chose. See ``_setup_gate``.
#
# ── secrets ─────────────────────────────────────────────────────────────────
# The vault PIN, the recovery code and the Home Assistant token are consumed and
# forgotten. None is logged, echoed, put in a manifest, or handed to the
# agent-activity feed; the responses that carry one are ``Cache-Control:
# no-store``. ``tests/test_setup_api_secrets.py`` greps captured logs to prove
# it.

_SETUP_NO_STORE = {'Cache-Control': 'no-store', 'Pragma': 'no-cache'}

# ── first-run setup code ────────────────────────────────────────────────────
#
# The "no first-run bootstrap hole" reasoning above is true of the BACKEND and
# false of the system: the dashboard's proxy attaches the appliance's API key
# server-side, `next start` bound every interface, and pairing enforcement
# defaults to "knowledge" — which gates /api/pai/knowledge and NOT
# /api/pai/setup/*. So on a fresh install the first device on the network to
# open http://<box>:3003 could name the bot, write the HA token, and call
# POST /setup/vault, whose response carries the vault RECOVERY CODE.
#
# The control is a console-only code (puffpai.security.setup_code) required on
# every state-changing /setup/* call whose effective client is not this machine.
#
# WHO COUNTS AS "THIS MACHINE"
# ----------------------------
# ``request.remote_addr`` is the peer. For the dashboard that peer is always
# loopback — it is the Next.js server proxying on a browser's behalf — so the
# peer alone would exempt every LAN device that goes through the dashboard,
# which is the entire population this code exists to stop. The proxy therefore
# forwards the address of ITS client in ``X-PuffPAI-Client-Addr``, and this
# backend trusts that header ONLY from a loopback peer.
#
# Spoofing is closed at both ends:
#   * a REMOTE peer that sends the header is ignored — the peer check runs
#     first, so "X-PuffPAI-Client-Addr: 127.0.0.1" from the LAN buys nothing;
#   * a LAN client cannot smuggle the header through the dashboard, because the
#     proxy forwards a fixed ALLOW-LIST of headers (Content-Type, Accept,
#     Authorization) and sets this one itself from the connection.
#
# Fail-closed on ambiguity: a header present but unparseable, or naming any
# non-loopback address, means REMOTE. "Absent" means the caller is a direct
# loopback client (the CLI, a local curl, the voice service).
_SETUP_CLIENT_ADDR_HEADER = 'X-PuffPAI-Client-Addr'

#: Methods that cannot change state; reads stay open exactly as before.
_SETUP_READ_METHODS = frozenset({'GET', 'HEAD', 'OPTIONS'})

# ── the rest of the build surface ───────────────────────────────────────────
#
# A hook that covered ``/setup/*`` and nothing else would leave the same hole
# open a second time: ``/wizard/*`` IS the wizard (the card renderer
# the dashboard drives -- ``/wizard/apply`` writes config, ``/wizard/run``
# builds, ``/wizard/resume`` decides what a stopped run may skip), and
# ``/build/prove*`` runs proofs against the running build and rewrites the
# recorded proof. Without this hook those answer to the appliance's API key
# alone, and the dashboard proxy attaches that key server-side for any client
# that can load the page, so an unpaired LAN device could drive the build
# through a door with a different name.
#
# Covered ONLY while ``setup_code.is_required()`` -- i.e. during first run. The
# code is destroyed when setup completes (``setup_ops.mark_complete``, on every
# completion path). After that, WRITES under ``/wizard`` and ``/persona`` need
# an unlocked vault session, the same rule ``/setup/*`` follows (see
# ``_enforce_post_setup_gate``), with the pairing gate in the dashboard in front.
#
# Reads are gated here too, unlike ``/setup/*`` where GET must stay open (it is
# how a browser learns a code is required at all). ``GET /wizard/cards`` and
# ``GET /wizard/state`` describe the machine and what is still open in the
# build; there is no equivalent bootstrap need, and the restrictive choice is
# the right default for a surface that exists to configure the appliance.
#
# ``/build/self`` is named although no such route ships today: a prefix that
# matches nothing costs nothing, and the day it is added it is already covered.
#
# ``/persona`` WRITES are the same build surface (``POST /persona/scaffold``
# writes an app folder and a pack; PATCH and DELETE rewrite or remove one), so
# they need the code during first run too. Its reads stay open: the kiosk asks
# ``GET /persona/list`` as an unpaired client by design.
_SETUP_CODE_PREFIXES = ('/setup', '/wizard', '/persona', '/build/prove',
                        '/build/self')

#: Prefixes whose READS stay open (/setup and /persona -- see above).
_SETUP_CODE_READS_OPEN = ('/setup', '/persona')


def _under_prefix(path, prefixes):
    """Segment-anchored prefix match: '/buildings' is not '/build'."""
    for prefix in prefixes:
        if path == prefix or path.startswith(prefix + '/'):
            return True
    return False


def _setup_client_is_local():
    """True when the effective client of this request is on this machine."""
    from puffpai.security.netaddr import is_loopback_peer
    if not is_loopback_peer(request.remote_addr):
        return False
    forwarded = (request.headers.get(_SETUP_CLIENT_ADDR_HEADER) or '').strip()
    if not forwarded:
        return True
    return is_loopback_peer(forwarded)


def _setup_code_required_for_request():
    """True when THIS caller must present the first-run setup code."""
    try:
        from puffpai.security import setup_code
        if not setup_code.is_required():
            return False
    except Exception:
        return False
    return not _setup_client_is_local()


@app.before_request
def _enforce_setup_code():
    """Gate the first-run build surface on the console-only setup code.

    A ``before_request`` hook rather than a per-route call on purpose: the
    /setup family is 20-odd routes and several of them already forgot to call
    ``_setup_gate``. A route added tomorrow is covered by construction, which is
    the only version of this that stays true.

    Covers ``/setup/*`` (state-changing calls only, as before) and the rest of
    the build surface -- ``/wizard/*``, ``/build/prove*``, ``/build/self`` --
    for EVERY method, while first-run setup is still required. See
    ``_SETUP_CODE_PREFIXES``.
    """
    path = request.path or ''
    if not _under_prefix(path, _SETUP_CODE_PREFIXES):
        return None
    if (request.method in _SETUP_READ_METHODS
            and _under_prefix(path, _SETUP_CODE_READS_OPEN)):
        return None
    if not _setup_code_required_for_request():
        return None

    from puffpai.security import setup_code
    supplied = request.headers.get(setup_code.HEADER, '')
    ok, reason, retry_after = setup_code.verify(supplied)
    if ok:
        return None

    messages = {
        'missing': ('Setup in the browser needs the first-run code shown '
                    'on the console of the machine running HomeBot. Run '
                    '`puffpai setup-code` there to see it again.'),
        'bad_code': ('That first-run code is not right. Check the console of '
                     'the machine running HomeBot.'),
        'locked_out': ('Too many wrong codes. The code has been REPLACED — read '
                       'the new one from the console of the machine running '
                       'HomeBot (`puffpai setup-code`) and try again in '
                       f'{retry_after} seconds.'),
        'unavailable': ('The first-run code could not be read on the machine '
                        'running HomeBot, so setup cannot be driven remotely. '
                        'Run `puffpai setup` on that machine instead.'),
    }
    extra = {'setup_code_required': True, 'reason': reason}
    if retry_after:
        extra['retry_after'] = retry_after
    # 403, not 401: no WWW-Authenticate challenge is on offer and the caller
    # already passed the API-key gate. Never echoes back what was supplied.
    return _setup_error('setup_code_required',
                        messages.get(reason, messages['missing']),
                        403, extra=extra, no_store=True)


# ── after completion: the rest of the build surface ─────────────────────────
#
# ``/setup/*`` has refused state changes after completion (409, unless a vault
# session is unlocked) since the first cut, through ``_setup_gate``. The card
# wizard and the persona writer change the same build by other names:
# ``POST /wizard/apply`` renames the bot or rewrites the Bridge posture, and
# ``POST /persona/scaffold`` writes folders. Once first run was over those
# answered to the API key alone, and the dashboard proxy attaches that key for
# any paired device. Same rule now, from the same helper, as a hook so a route
# added under these prefixes tomorrow is covered by construction.
_POST_SETUP_GATED_PREFIXES = ('/wizard', '/persona')

#: POSTs that change nothing: ``/persona/preview`` answers "what WOULD
#: scaffold write" and writes nothing. Exact paths, not prefixes.
_POST_SETUP_READ_ONLY_POSTS = frozenset({'/persona/preview'})


@app.before_request
def _enforce_post_setup_gate():
    """After completion, wizard and persona WRITES need an unlocked vault.

    Before completion this does nothing (the first-run code gate above is in
    charge). Reads stay open to any caller the API key and pairing already let
    in, as they do for ``/setup/*``.
    """
    path = request.path or ''
    if not _under_prefix(path, _POST_SETUP_GATED_PREFIXES):
        return None
    if request.method in _SETUP_READ_METHODS:
        return None
    if path in _POST_SETUP_READ_ONLY_POSTS:
        return None
    return _setup_gate()


def _setup_ok(payload=None, *, status=200, no_store=False):
    """``{"ok": true, ...}`` with the setup_ops dict inlined verbatim."""
    body = {'ok': True}
    body.update(payload or {})
    resp = jsonify(body)
    if no_store:
        resp.headers.update(_SETUP_NO_STORE)
    return resp, status


def _setup_error(code, message, status=400, *, extra=None, no_store=False):
    """``{"ok": false, "error": <code>, "message": <plain>}``.

    *message* is written to be shown to a person and must never quote back a
    PIN, a recovery code or a token.
    """
    body = {'ok': False, 'error': str(code), 'message': str(message)}
    body.update(extra or {})
    resp = jsonify(body)
    if no_store:
        resp.headers.update(_SETUP_NO_STORE)
    return resp, status


def _setup_vault_session_live():
    """True when the caller holds an UNLOCKED vault session.

    Same token plumbing every other /vault/* route uses: ``X-Vault-Token`` maps
    to a vault session id, and the vault itself is asked whether that session is
    still valid. Fails closed on anything unexpected.
    """
    token = request.headers.get('X-Vault-Token', '')
    if not token and request.is_json:
        try:
            token = (request.get_json(silent=True) or {}).get('session_token', '')
        except Exception:
            token = ''
    if not token or not isinstance(token, str):
        return False
    vault_sid = _vault_sessions.get(token)
    if not vault_sid:
        return False
    try:
        vault = _get_vault()
        if vault is None:
            return False
        vault._validate_session(vault_sid)
        return True
    except Exception:
        _vault_sessions.pop(token, None)
        return False


def _setup_gate(*, vault_route=False):
    """Refuse a state-changing setup call that arrives after completion.

    Returns a response tuple to return, or ``None`` to carry on.

    * Before completion: everything is allowed (that is what the wizard is).
    * After completion: a caller holding a live vault session may still adjust
      the build — that is the owner, standing at an unlocked vault.
    * After completion, ``vault_route=True``: refused unconditionally. There is
      no PIN a caller could supply that should let an onboarding route re-seal a
      vault that already holds the household's data.
    """
    from puffpai import setup_ops
    try:
        complete = setup_ops.is_complete()
    except Exception:
        complete = True           # unreadable flag => assume finished, fail closed
    if not complete:
        return None
    if vault_route:
        return _setup_error(
            'setup_complete',
            'Setup is finished, so the vault cannot be created from this '
            'screen. Use the vault settings page to change your PIN.',
            409)
    if _setup_vault_session_live():
        return None
    return _setup_error(
        'setup_complete',
        'Setup is already finished. Unlock the vault first to change this.',
        409)


def _setup_census(data):
    """A fresh census with any owner-stated correction overlaid.

    Stateless by design: the server never holds a census between calls, so each
    request that needs one re-runs it and applies the correction carried in the
    body. Never raises.
    """
    from puffpai import hardware_census as hc
    census = hc.run_census()
    if not isinstance(data, dict):
        return census
    stated_ram = data.get('stated_ram')
    accel = data.get('accelerator_kind')
    cpu = data.get('cpu_model')
    if stated_ram or accel or cpu:
        try:
            census = hc.apply_stated(
                census,
                total_ram_gb=float(stated_ram) if stated_ram else None,
                accelerator_kind=accel,
                cpu_model=cpu,
            )
        except (TypeError, ValueError):
            pass
    return census


def _setup_str_list(value):
    """Untrusted JSON -> a list of non-empty strings. Never raises."""
    if not isinstance(value, list):
        return []
    return [item.strip() for item in value
            if isinstance(item, str) and item.strip()]


# ── status, defaults, identity ──────────────────────────────────────────────

@app.route('/setup/status', methods=['GET'])
def setup_status():
    """Which setup steps are done. Contains no secrets.

    ``?ollama=0`` skips the Ollama network probe - the first-run gate only needs
    the ``complete`` flag and uses that to stay snappy.

    ``setup_code_required`` tells THIS caller whether its state-changing calls
    will need ``X-Setup-Code``. It is per-caller, not a global fact: a loopback
    client (the CLI, a local curl) is told False, a browser coming through the
    dashboard proxy is told True while setup is open. The code itself is NEVER
    in this response — only whether one is needed.
    """
    from puffpai import setup_ops
    probe = request.args.get('ollama', '1') not in ('0', 'false', 'no')
    status = setup_ops.setup_status(probe_ollama=probe)
    if isinstance(status, dict):
        status = dict(status)
        status['setup_code_required'] = _setup_code_required_for_request()
    return jsonify(status)


@app.route('/setup/defaults', methods=['GET'])
def setup_defaults():
    """The preselected persona, name, pack and goal. All of it editable."""
    from puffpai import setup_ops
    return _setup_ok(setup_ops.homebot_defaults())


@app.route('/setup/identity', methods=['POST'])
def setup_identity():
    """Persist the bot's name. Body: ``{bot_name, persona?}``."""
    from puffpai import setup_ops
    blocked = _setup_gate()
    if blocked is not None:
        return blocked
    data = request.json or {}
    bot_name = str(data.get('bot_name') or '').strip()
    if not bot_name:
        return _setup_error('bot_name_required', 'Give your bot a name.')
    defaults = setup_ops.homebot_defaults()
    # `persona` is accepted so the dashboard can send the shape it already
    # builds, but only the SHIPPED persona is honoured: setup_ops.set_identity
    # takes a name and nothing else, so an arbitrary persona string here would
    # be a field the wizard pretends to store. Echoed back, never invented.
    persona = str(data.get('persona') or '').strip() or str(defaults.get('persona') or '')
    if persona != str(defaults.get('persona') or ''):
        return _setup_error(
            'unknown_persona',
            'This build ships one persona and cannot switch to another.')
    path = setup_ops.set_identity(bot_name)
    return _setup_ok({'bot_name': bot_name, 'persona': persona,
                      'config_path': path})


# ── posture (build network x run egress) ────────────────────────────────────

@app.route('/setup/posture', methods=['GET', 'POST'])
def setup_posture():
    """GET the two menus + the enumerated egress table; POST the answers.

    POST body: ``{build_network?, run_egress?, enabled_switches?[]}``. A missing
    axis means "the owner skipped it" and the assessment records that it was
    defaulted rather than chosen. The answer is persisted into the config the
    runtime actually reads (``setup_ops.persist_posture``).
    """
    from puffpai import setup_ops
    if request.method == 'GET':
        return _setup_ok(setup_ops.posture_options())

    blocked = _setup_gate()
    if blocked is not None:
        return blocked
    data = request.json or {}
    build_network = str(data.get('build_network') or '').strip() or None
    run_egress = str(data.get('run_egress') or '').strip() or None
    switches = _setup_str_list(data.get('enabled_switches'))
    posture = setup_ops.assess_posture(build_network, run_egress, switches)
    config_path = setup_ops.persist_posture(posture)
    payload = dict(posture)
    payload['gates'] = setup_ops.posture_gates(posture)
    payload['manifest_block'] = setup_ops.posture_block(posture)
    payload['config_path'] = config_path
    return _setup_ok(payload)


# ── bridge (Zone 3) ─────────────────────────────────────────────────────────

@app.route('/setup/bridge', methods=['GET', 'POST'])
def setup_bridge():
    """GET the four Bridge postures + a suggestion; POST the owner's choice.

    GET query (all optional booleans): ``home_assistant``, ``external_firewall``,
    ``managed_lan`` - what the owner says they have. A suggestion, never a
    setting: the whole ladder always comes back.

    POST body, either shape:

    * ``{posture, network_edge?: bool}`` - what the dashboard sends. ``true``
      maps to ``edge.kind = "zone3"``, ``false`` to ``"none"``.
    * ``{posture, edge: {kind, external_kind?, external_url?}}`` - the whole
      edge answer, the same one the terminal wizard collects.

    Both go through ``setup_ops.reconcile_bridge``'s dict form, so the browser
    and the terminal record the SAME ``manifest.bridge.edge``. The boolean route
    used to skip it, which is why a browser-built manifest always said nothing
    was at the edge even when the owner had said otherwise.

    The choice is reconciled against Step 0's egress tier (stricter wins) before
    it is recorded. ``external_url`` is data only: it is validated as a LAN or
    loopback address by ``setup_ops.validate_edge_url`` (the helper the terminal
    wizard uses) and is never fetched - an address that fails is dropped with a
    note rather than recorded. The network-edge half is NOT applied here - it
    needs files this wizard does not own - so it is recorded through
    ``setup_ops.record_pending_apply`` under the one kind name,
    ``zone3_network_edge``, and reported.
    """
    from puffpai import build_manifest, setup_ops

    def _flag(name):
        return str(request.args.get(name, '')).strip().lower() in (
            '1', 'true', 'yes', 'on')

    if request.method == 'GET':
        return _setup_ok(setup_ops.bridge_options(
            _flag('home_assistant'), _flag('external_firewall'),
            _flag('managed_lan')))

    blocked = _setup_gate()
    if blocked is not None:
        return blocked
    data = request.json or {}
    posture = str(data.get('posture') or '').strip()
    if not posture:
        return _setup_error('posture_required', 'Pick one of the four Bridge postures.')
    # `reconcile_bridge` already fails CLOSED on an unknown posture (it
    # substitutes the safe default). Refuse instead: an id that is not on the
    # ladder means the caller is confused, and answering 200 with a posture they
    # did not ask for hides that. Defence in depth keeps the substitution below.
    known = {str(item.get('id')) for item in
             (setup_ops.bridge_options().get('postures') or [])}
    if known and posture not in known:
        return _setup_error('unknown_posture',
                            'That is not one of the Bridge postures.')

    manifest = build_manifest.read_manifest() or {}
    run_egress = (manifest.get('posture') or {}).get('run_egress')
    if not run_egress:
        run_egress = setup_ops.assess_posture(None, None, None).get('run_egress')
    # One answer, two spellings. `edge` wins when it is present; otherwise the
    # dashboard's boolean is translated into the same shape, so exactly one code
    # path below builds the edge block.
    raw_edge = data.get('edge')
    if isinstance(raw_edge, dict):
        edge_answer = {
            'kind': str(raw_edge.get('kind') or 'none'),
            'external_kind': str(raw_edge.get('external_kind') or ''),
            'external_url': str(raw_edge.get('external_url') or ''),
        }
    else:
        edge_answer = {
            'kind': 'zone3' if bool(data.get('network_edge')) else 'none'}

    try:
        answer = setup_ops.reconcile_bridge(
            {'posture': posture, 'edge': edge_answer}, run_egress)
    except (KeyError, ValueError):
        return _setup_error('unknown_posture',
                            'That is not one of the Bridge postures.')
    reconciled = answer.get('posture')
    explanation = answer.get('note')
    edge = answer.get('edge') or {}

    # The sinkhole/edge half lives outside this wizard's files. Record the
    # decision rather than half-applying it.
    # 'zone3_network_edge' is the ONE name for this record. The CLI wizard
    # writes it (setup_ops.record_zone3_pending) and record_pending_apply
    # de-duplicates on `kind`, so a second spelling would be a second row that
    # the reader of the first never saw.
    pending_path = setup_ops.record_zone3_pending(edge)
    zone3 = edge.get('zone3') or {}
    if not pending_path and zone3.get('requested'):
        # Asked for, cannot run here. Record that it was asked for, with the
        # reasons and NO commands - a command list on a machine that cannot run
        # it reads as a to-do the owner can finish, and this one they cannot.
        pending_path = setup_ops.record_pending_apply(
            'zone3_network_edge',
            {'needs': 'nothing to run here; this machine cannot host Zone 3',
             'requested': True, 'supported': False,
             'reasons': list(zone3.get('reasons') or []),
             'posture': reconciled, 'run_egress': run_egress})
    return _setup_ok({
        'bridge': setup_ops.bridge_block(reconciled, run_egress=run_egress,
                                         chosen_by='owner', edge=edge),
        'posture': reconciled,
        'requested_posture': posture,
        'run_egress': run_egress,
        'explanation': explanation,
        'edge': edge,
        'network_edge_recorded': bool(pending_path),
    })


# ── household ───────────────────────────────────────────────────────────────

@app.route('/setup/household', methods=['GET', 'POST'])
def setup_household():
    """GET the roster; POST ``{owner_name, members?[{name}]}`` to create it.

    A member's ROLE is deliberately not taken from the request. This build's
    :mod:`puffpai.household` promotes the oldest profile to ``owner``, and a
    setup route is not the place to let a caller name themselves anything else -
    so every extra member is created with the module's own default.
    """
    from puffpai import setup_ops
    if request.method == 'GET':
        return _setup_ok(setup_ops.household_status())

    blocked = _setup_gate()
    if blocked is not None:
        return blocked
    data = request.json or {}
    owner_name = str(data.get('owner_name') or '').strip()
    if not owner_name:
        return _setup_error('owner_name_required',
                            'Tell HomeBot who the household belongs to.')
    members = []
    raw = data.get('members')
    if isinstance(raw, list):
        for entry in raw:
            if not isinstance(entry, dict):
                continue
            name = str(entry.get('name') or '').strip()
            if name:
                members.append({'name': name})
    status = setup_ops.create_household(owner_name, members)
    payload = dict(status)
    payload['manifest_block'] = setup_ops.household_block(status)
    return _setup_ok(payload)


# ── storage ─────────────────────────────────────────────────────────────────

@app.route('/setup/storage', methods=['GET', 'POST'])
def setup_storage():
    """GET the default storage paths; POST the owner's four answers.

    POST body: ``{state_dir?, media_dir?, knowledge_dir?, vault_dir?}``. Any key
    the caller omits falls back to this install's default rather than to empty -
    a half-applied storage layout is worse than a refused one, and
    ``setup_ops.apply_storage`` refuses the whole write if any answer fails
    validation.
    """
    from puffpai import setup_ops
    defaults = setup_ops.storage_defaults()
    if request.method == 'GET':
        return _setup_ok({'paths': defaults, 'problems': {}, 'config_path': ''})

    blocked = _setup_gate()
    if blocked is not None:
        return blocked
    data = request.json or {}
    paths = {}
    for key, default_value in defaults.items():
        supplied = data.get(key)
        paths[key] = (str(supplied).strip() if isinstance(supplied, str)
                      else default_value)
    result = setup_ops.apply_storage(paths)
    if not result.get('ok'):
        problems = result.get('problems') or {}
        first = next(iter(problems.values()), 'That storage layout cannot be used.')
        return _setup_error('invalid_storage_path', first,
                            extra={'problems': problems,
                                   'paths': result.get('paths') or paths})
    payload = dict(result)
    payload['manifest_block'] = setup_ops.storage_block(result.get('paths') or paths)
    return _setup_ok(payload)


# ── goal -> surfaces ────────────────────────────────────────────────────────

@app.route('/setup/surfaces', methods=['GET', 'POST'])
def setup_surfaces():
    """The surface allowlist a stated goal implies, with the owner's edits.

    Stateless: nothing is written here. The derivation is carried by the caller
    into the manifest commit, which is where a surface allowlist becomes real -
    so this route is a read on both verbs and is not gated after completion.

    GET ``?goal=``; POST ``{goal?, add?[], remove?[]}``. The goal is DATA, used
    only for offline keyword matching, never an instruction.
    """
    from puffpai import build_interview as _bi, setup_ops
    data = (request.json or {}) if request.method == 'POST' else {}
    goal = str((data.get('goal') if request.method == 'POST'
                else request.args.get('goal')) or '').strip()
    if not goal:
        goal = str(setup_ops.homebot_defaults().get('goal') or '')
    derivation = setup_ops.derive_surfaces(setup_ops.build_interview(goal))
    if request.method == 'POST':
        derivation = setup_ops.apply_surface_choices(
            derivation,
            add=_setup_str_list(data.get('add')),
            remove=_setup_str_list(data.get('remove')))
    derivation = setup_ops.ensure_surfaces(derivation, goal)
    payload = dict(derivation)
    payload['available'] = sorted(_bi.surface_taxonomy())
    payload['manifest_block'] = setup_ops.surfaces_block(derivation)
    return _setup_ok(payload)


# ── vault (Zone 1) ──────────────────────────────────────────────────────────
#
# The PIN and the recovery code are the two values in this whole file that must
# never touch a log line, a manifest or an error message. Both routes answer
# no-store, neither takes the value into a `logger` call, and the confirmation
# slot below holds a DIGEST of the issued code rather than the code itself - so
# a heap dump after the screen has been shown does not hand anyone the code.

#: Single-slot, process-local, never persisted: ``{"digest", "issued_at",
#: "attempts"}``. Holding a digest (not the code) is what lets the typed-back
#: check run server-side without the server keeping the secret.
_setup_recovery_pending: dict = {}
_setup_recovery_lock = threading.Lock()

#: The confirmation throttle IS the vault's throttle: same attempt ceiling and
#: same lockout, read from the vault module so the two cannot drift.
try:
    from puffpai.security.vault import (
        _MAX_FAILED_ATTEMPTS as _SETUP_RECOVERY_MAX_ATTEMPTS,
        _LOCKOUT_SECONDS as _SETUP_RECOVERY_LOCKOUT,
    )
except Exception:                            # pragma: no cover - import guard
    _SETUP_RECOVERY_MAX_ATTEMPTS, _SETUP_RECOVERY_LOCKOUT = 5, 300

#: How long a shown-but-unconfirmed code stays checkable. Past this the owner
#: rotates rather than guesses.
_SETUP_RECOVERY_TTL = 1800


def _setup_recovery_digest(code):
    """Digest of a recovery code in its comparable form.

    The normalisation is the wizard's own (``zone_vault._normalize_recovery_code``
    - uppercase, alphanumeric only) so a person who wrote the dashes down
    somewhere else is not failed for it. ``tests/test_setup_api_vault.py`` pins
    this against ``setup_ops.confirm_vault_recovery`` so the restatement cannot
    drift from the wizard's rule.
    """
    normalized = ''.join(ch for ch in str(code or '').upper() if ch.isalnum())
    if not normalized:
        return b''
    return hashlib.sha256(normalized.encode('utf-8')).digest()


@app.route('/setup/vault', methods=['POST'])
def setup_create_vault():
    """Seal the vault under ``{pin}`` and return its recovery code ONCE.

    The code is shown here and nowhere else: it is not persisted, not logged and
    not placed in the manifest. The response is ``Cache-Control: no-store``.
    """
    from puffpai import setup_ops
    blocked = _setup_gate(vault_route=True)
    if blocked is not None:
        return blocked

    data = request.json or {}
    # `password` is BuildBot's spelling of the same field; accepted so a client
    # written against that contract still works.
    pin = data.get('pin') or data.get('password') or ''
    if not pin:
        return _setup_error('pin_required', 'A vault PIN is required.',
                            no_store=True)
    if setup_ops.vault_initialized():
        return _setup_error(
            'vault_exists',
            'A vault already exists on this build. Setting a new PIN here '
            'would lock away what is already in it.',
            409, extra={'already_initialized': True}, no_store=True)
    ok, reason = setup_ops.validate_vault_pin(pin)
    if not ok:
        # `reason` is zone_vault's plain sentence and never quotes the PIN.
        return _setup_error('weak_pin', reason, no_store=True)
    try:
        block, recovery_code = setup_ops.seal_vault_with_recovery(pin)
    except (VaultError, ValueError) as exc:
        logger.warning("Setup vault seal refused")   # no PIN, no exception text
        return _setup_error('vault_refused', str(exc), 400, no_store=True)
    except Exception:
        logger.exception("Setup vault seal failed")
        return _setup_error('vault_unavailable',
                            'The vault could not be created on this build.',
                            503, no_store=True)

    with _setup_recovery_lock:
        _setup_recovery_pending.clear()
        _setup_recovery_pending.update({
            'digest': _setup_recovery_digest(recovery_code),
            'issued_at': time.time(),
            'attempts': 0,
            'locked_until': 0.0,
        })
    logger.info("Setup: vault sealed and a recovery code issued")
    return _setup_ok({
        'vault': block,
        'initialized': True,
        'recovery_issued': True,
        'recovery_code': recovery_code,
        'recovery_code_notice': setup_ops.vault_recovery_notice(),
    }, no_store=True)


@app.route('/setup/vault/confirm', methods=['POST'])
def setup_confirm_vault_recovery():
    """The owner types the recovery code back. Body: ``{recovery_code}``.

    Adjudicated against a DIGEST of the code that was issued in this process,
    under the vault's own attempt ceiling and lockout. A wrong answer never says
    how much of it was right, and exhausting the attempts destroys the slot: the
    way forward is then to rotate the code, not to keep guessing.
    """
    blocked = _setup_gate(vault_route=True)
    if blocked is not None:
        return blocked

    data = request.json or {}
    typed = data.get('recovery_code') or ''
    now = time.time()
    with _setup_recovery_lock:
        slot = dict(_setup_recovery_pending)
        if not slot.get('digest'):
            return _setup_error(
                'no_pending_confirmation',
                'There is no recovery code waiting to be confirmed. Create the '
                'vault first.', 409, no_store=True)
        if now - float(slot.get('issued_at') or 0) > _SETUP_RECOVERY_TTL:
            _setup_recovery_pending.clear()
            return _setup_error(
                'confirmation_expired',
                'That code has been on screen too long to confirm. Issue a new '
                'one and write it down.', 409, no_store=True)
        if now < float(slot.get('locked_until') or 0):
            remaining = int(float(slot['locked_until']) - now)
            return _setup_error(
                'too_many_attempts',
                f'Too many attempts. Try again in {remaining} seconds.',
                429, no_store=True)

        if not typed or not secrets.compare_digest(
                _setup_recovery_digest(typed), slot['digest']):
            attempts = int(slot.get('attempts') or 0) + 1
            if attempts >= _SETUP_RECOVERY_MAX_ATTEMPTS:
                # Fail closed: the slot is gone, so the only way on is a fresh
                # code the owner actually has in front of them.
                _setup_recovery_pending.clear()
                logger.warning("Setup: recovery confirmation attempts exhausted")
                return _setup_error(
                    'too_many_attempts',
                    'That code did not match too many times. Issue a new '
                    'recovery code and write it down.', 429, no_store=True)
            _setup_recovery_pending['attempts'] = attempts
            return _setup_error(
                'recovery_code_mismatch',
                'That is not the code that was shown. Check what you wrote '
                'down and try again.', 400,
                extra={'attempts_remaining':
                       _SETUP_RECOVERY_MAX_ATTEMPTS - attempts},
                no_store=True)

        _setup_recovery_pending.clear()

    logger.info("Setup: recovery code confirmed by the owner")
    return _setup_ok({'confirmed': True,
                      'vault': {'recovery_confirmed': True}}, no_store=True)


# ── Home Assistant, which is optional ───────────────────────────────────────

def _setup_run_egress():
    """The run posture this browser onboarding is building against.

    The answer THIS run declared, then the manifest if one exists, then the
    settled default. The LAN-posture write path falls back to 'sealed' when it
    is told nothing, which is right for the CLI -- its Step 1 always declares
    the answer before anything is written -- and wrong here: this face never
    asks the posture question, so an undeclared posture would mean a browser
    wizard that can write nothing but loopback and an owner who is told their
    own Home Assistant box is off-limits with no way to say otherwise. Stating
    the settled posture is not inventing a permissive one: lan_posture
    re-normalises it through build_posture, and 'island' still refuses every
    address that is not on this house's own network.

    The run's own answer comes FIRST because a stated posture overrides
    ``lan_posture.write_path_posture()`` outright, active declaration included.
    Without that order, an owner who answers 'sealed' at /setup/posture and then
    saves a service URL before the manifest is written would have their answer
    silently replaced by the default - the one direction this helper must never
    move.
    """
    from puffpai import build_manifest, setup_ops
    from puffpai.security import lan_posture
    declared = lan_posture.active_posture()
    if declared:
        return declared
    manifest = build_manifest.read_manifest() or {}
    run_egress = (manifest.get('posture') or {}).get('run_egress')
    return run_egress or setup_ops.assess_posture(None, None, None).get(
        'run_egress')


def _setup_refuse_offhouse_ha(url):
    """Refuse a Home Assistant address that is not inside this house.

    Two checks, not one, and they answer different questions.

    THIS one runs at the trust boundary, through
    ``security.lan_http.validate_url``: it resolves the host and refuses unless
    EVERY address it answers with is loopback/RFC1918/ULA. It is posture-blind
    on purpose - it is what closes /setup/ha and /setup/ha/test as SSRF
    primitives, so a key-holding caller cannot use them to probe arbitrary
    internet hosts with a token attached, whatever posture the build claims.

    The second runs inside ``setup_ops.set_ha_config``, through
    ``security.lan_posture``, and asks whether this BUILD's run posture allows
    that address at all - a sealed build may not talk to another box even on
    its own LAN. Its refusal arrives here as a ``PostureViolation`` whose
    ``user_message`` the caller below returns verbatim, which is how the HTTP
    route and the CLI say the same plain sentence.

    Returns a response tuple to return, or ``None`` to carry on.
    """
    from puffpai.security import lan_http, netaddr
    try:
        lan_http.validate_url(url)
        return None
    except ValueError as exc:
        return _setup_error('bad_ha_url', str(exc), no_store=True)
    except netaddr.AddressRefused:
        return _setup_error(
            'ha_not_local',
            'That address is not inside your house. Home Assistant has to be '
            'on your own network - this build will not send a token off it.',
            no_store=True)
    except Exception:
        # Resolution failed, or the module would not load. "We could not tell"
        # is a refusal, never a pass.
        return _setup_error(
            'ha_unresolvable',
            'That address could not be checked, so no token was saved. Try the '
            'IP address of your Home Assistant box.', no_store=True)


@app.route('/setup/ha', methods=['POST'])
def setup_set_ha():
    """Record the Home Assistant answer. Body: ``{present, url?, token?}``.

    ``present: false`` is a COMPLETE answer - a household without Home Assistant
    is a finished build, not a degraded one - and nothing is written for it.
    The token is written only to the gitignored HA config file; it is never
    logged, never echoed and never placed in the manifest.
    """
    from puffpai import setup_ops
    blocked = _setup_gate()
    if blocked is not None:
        return blocked

    data = request.json or {}
    present = bool(data.get('present', True))
    if not present:
        return _setup_ok({'ha': setup_ops.ha_block(False), 'configured': False})

    url = str(data.get('url') or '').strip()
    token = data.get('token') or ''
    if not url or not token:
        return _setup_error('ha_credentials_required',
                            'Both an address and a token are required.',
                            no_store=True)
    refusal = _setup_refuse_offhouse_ha(url)
    if refusal is not None:
        return refusal
    try:
        setup_ops.set_ha_config(url, token, enabled=True,
                                posture=_setup_run_egress())
    except Exception as exc:
        message = getattr(exc, 'user_message', None) or (
            'Home Assistant could not be configured.')
        logger.warning("Setup: Home Assistant config refused")  # no token
        return _setup_error('ha_refused', message, no_store=True)
    return _setup_ok({'ha': setup_ops.ha_block(True, url, token_configured=True),
                      'configured': True}, no_store=True)


@app.route('/setup/ha/test', methods=['POST'])
def setup_test_ha():
    """Probe candidate Home Assistant credentials WITHOUT saving them.

    Same house-local refusal as the save route, so this cannot be used to reach
    off-network hosts. The result never contains the token.

    After completion it follows the other post-setup setup routes: without an
    unlocked vault session it is refused, so a finished box cannot be used as a
    port prober against its own LAN.
    """
    from puffpai import setup_ops
    blocked = _setup_gate()
    if blocked is not None:
        return blocked
    data = request.json or {}
    url = str(data.get('url') or '').strip()
    token = data.get('token') or ''
    if not url or not token:
        return _setup_error('ha_credentials_required',
                            'Both an address and a token are required.',
                            no_store=True)
    refusal = _setup_refuse_offhouse_ha(url)
    if refusal is not None:
        return refusal
    result = setup_ops.test_ha_connection(url, token)
    if result.get('ok'):
        return _setup_ok(result, no_store=True)
    return _setup_error('ha_unreachable',
                        str(result.get('error') or 'Home Assistant did not answer.'),
                        400, extra={k: v for k, v in result.items()
                                    if k not in ('ok', 'error')},
                        no_store=True)


# ── ollama, knowledge ───────────────────────────────────────────────────────

@app.route('/setup/ollama', methods=['POST'])
def setup_set_ollama():
    """Persist the chosen Ollama model (and optional URL).

    The URL is judged against the build's SETTLED run posture, stated the same
    way ``/setup/ha`` states it (``_setup_run_egress``). Without that, the write
    path falls back to ``sealed`` - correct for the CLI, where Step 1 always
    declares the posture first, and wrong here, where this face never asks: an
    ``island`` build was told its own LAN Ollama box was off-limits with no way
    to say otherwise. A refusal is still a refusal: under ``sealed`` a
    non-loopback address is turned away with the posture module's own sentence,
    and nothing is written.
    """
    from puffpai import setup_ops
    blocked = _setup_gate()
    if blocked is not None:
        return blocked
    data = request.json or {}
    model = str(data.get('model') or '').strip()
    if not model:
        return jsonify({'success': False, 'ok': False, 'error': 'model_required',
                        'message': 'A model name is required.'}), 400
    url = str(data.get('url') or '').strip() or None
    from puffpai.security.lan_posture import PostureViolation
    try:
        path = setup_ops.set_ollama_config(model, url,
                                           posture=_setup_run_egress())
    except PostureViolation as exc:
        # Only the posture refusal is answered as a 400 with a sentence. Any
        # other failure (an unwritable config file, say) stays a 500 rather than
        # being dressed up as the owner's fault.
        logger.warning("Setup: Ollama address refused by the run posture")
        return _setup_error('ollama_refused',
                            getattr(exc, 'user_message', None)
                            or 'That address cannot be used by this build.')
    return jsonify({'success': True, 'ok': True, 'model': model,
                    'config_path': path})


@app.route('/setup/knowledge', methods=['POST'])
def setup_set_knowledge():
    """Set the knowledge-pack (ZIM) folder and the auto-index flag."""
    from puffpai import setup_ops
    blocked = _setup_gate()
    if blocked is not None:
        return blocked
    data = request.json or {}
    zim_dir = str(data.get('zim_dir') or '').strip()
    auto_index = bool(data.get('auto_index', True))
    create_dir = bool(data.get('create_dir', False))
    path = setup_ops.set_knowledge_config(zim_dir, auto_index=auto_index,
                                          create_dir=create_dir)
    return jsonify({'success': True, 'ok': True, 'zim_dir': zim_dir,
                    'auto_index': auto_index, 'config_path': path})


# ── census-first steps: hardware, brain menu, crew, interview ───────────────
#
# Read-only on BOTH verbs: the POST body carries an owner-stated CORRECTION to
# the census, not a change to the build, so nothing here is gated after
# completion and nothing here writes.

@app.route('/setup/hardware', methods=['GET', 'POST'])
def setup_hardware():
    """Report the hardware census. POST an owner-stated correction to overlay it.

    Body (POST, all optional): ``stated_ram`` (GB), ``accelerator_kind``,
    ``cpu_model``. Contains no secrets.
    """
    from puffpai import hardware_census as hc
    data = (request.json or {}) if request.method == 'POST' else {}
    census = _setup_census(data)
    return jsonify({'census': census, 'summary': hc.census_summary_lines(census)})


@app.route('/setup/brain-menu', methods=['GET', 'POST'])
def setup_brain_menu():
    """Fit the local-model menu to this hardware, RAM-first."""
    from puffpai import model_catalog, setup_ops
    data = (request.json or {}) if request.method == 'POST' else {}
    census = _setup_census(data)
    menu = setup_ops.brain_menu(census)
    return jsonify({'menu': menu, 'summary': model_catalog.menu_summary_lines(menu)})


@app.route('/setup/crew', methods=['GET', 'POST'])
def setup_crew():
    """Report the specialist crew budget for this hardware."""
    from puffpai import crew_sizing
    data = (request.json or {}) if request.method == 'POST' else {}
    census = _setup_census(data)
    budget = crew_sizing.crew_budget(census)
    return jsonify({'crew': budget, 'summary': crew_sizing.crew_summary_lines(budget)})


@app.route('/setup/interview', methods=['POST'])
def setup_interview():
    """Suggest capabilities for a stated goal, within the crew budget.

    Body: ``goal`` (required-ish), plus optional ``stated_ram``. The goal is
    DATA, used only for offline keyword matching, never an instruction.
    """
    from puffpai import build_interview as _bi, crew_sizing, persona_scaffold
    data = request.json or {}
    goal = str(data.get('goal') or '').strip()
    census = _setup_census(data)
    budget = crew_sizing.crew_budget(census)
    proposal = _bi.propose(goal, crew_budget=budget)
    name = str(data.get('name') or '').strip()
    offer = _bi.scaffold_offer(proposal)
    suggested_id = (persona_scaffold.suggest_id(name, goal)
                    or persona_scaffold.FALLBACK_ID)
    return jsonify({
        'proposal': proposal,
        'summary': _bi.proposal_summary_lines(proposal),
        # Every proposed surface carries the one line saying WHY it is on the
        # list, citing the word in the goal that matched. The CLI has shown
        # those reasons since the surfaces step existed; the dashboard could
        # not, because the route did not send them.
        'surfaces': _bi.derive_surfaces(proposal),
        # ALWAYS offered. The old rule offered the scaffold only when the
        # catalog matched nothing, which hid it from the owner who needed it
        # most. What the match changes is the reason shown, not the offer.
        'scaffold': {
            'offered': True,
            'default_yes': offer['default_yes'],
            'question': offer['question'],
            'reason': offer['reason'],
            'matched_household': offer['matched_household'],
            'step': _bi.SCAFFOLD_STEP,
            'suggested_id': suggested_id,
            'suggested_lists': offer['suggested_lists'],
            'surface': persona_scaffold.persona_surface(suggested_id),
            'message': proposal.get('message') or '',
        },
    })


# ── manifest, pending apply, completion ─────────────────────────────────────

@app.route('/setup/manifest', methods=['GET', 'POST'])
def setup_manifest():
    """Read the build manifest (GET), or assemble/preview/commit it (POST).

    POST body sections are all optional: ``identity``, ``brain``, ``crew``,
    ``storage``, ``knowledge``, ``egress``, ``integrations``, ``posture``,
    ``surfaces``, ``vault``, ``bridge``, ``household``, ``persona``,
    ``interview``, plus ``stated_ram`` and a ``commit`` flag. Without ``commit`` it previews (assemble + diff + warnings, no write);
    with ``commit`` truthy it writes, and the contract guard runs on write - so
    no manifest field can disable a contract.

    The preview is a read and is open after completion; the COMMIT is a write
    and is gated.
    """
    from puffpai import build_manifest, setup_ops
    if request.method == 'GET':
        return jsonify(setup_ops.manifest_status())

    data = request.json or {}
    if data.get('commit'):
        blocked = _setup_gate()
        if blocked is not None:
            return blocked
    census = _setup_census(data)
    # `household`, `persona` and `interview` are on this list because the CLI
    # wizard writes them (setup_cli._step_manifest). Leaving them off meant a
    # browser-built manifest silently had no household block at all, so the two
    # faces recorded different builds for the same answers. They take the same
    # route as every other section: preview_manifest -> sanitize_manifest, so
    # the _FORBIDDEN_KEYS / secret guard still runs over them.
    sections = {k: data[k] for k in
                ('identity', 'brain', 'crew', 'storage', 'knowledge', 'egress',
                 'integrations', 'posture', 'surfaces', 'vault', 'bridge',
                 'household', 'persona', 'interview')
                if isinstance(data.get(k), dict)}
    preview = setup_ops.preview_manifest(census, **sections)
    written = False
    path = None
    if data.get('commit'):
        path = setup_ops.commit_manifest(preview['manifest'])
        written = True
    return jsonify({
        'manifest': preview['manifest'],
        'summary': build_manifest.manifest_summary_lines(preview['manifest']),
        'diff': preview['diff'],
        'warnings': preview['warnings'],
        'written': written,
        'path': path,
    })


@app.route('/setup/pending-apply', methods=['GET'])
def setup_pending_apply():
    """Decisions the wizard recorded but could not apply itself. No secrets."""
    from puffpai import setup_ops
    return _setup_ok({'pending': setup_ops.pending_apply()})


# --- The wizard as cards ------------------------------------------------------
#
# Spec B.6: the CLI and the dashboard are two renderers of ONE card set. These
# three routes are the whole of what a browser needs to be the second renderer
# -- what the cards are, what changed when answers came back, and what the run
# log says. No question is written here; a question lives in the skill that
# proposes it, which is the drift these routes exist to make unrepresentable.
#
# Same gate as every neighbour: not listed in _PUBLIC_ENDPOINTS, so the
# default-deny _check_api_key before_request hook requires the app API key.
#
# Secrets discipline: a card never carries a value for a secret_entry field,
# and an answer to one is replaced by wizard.cards.redact_answers before it is
# logged or returned. Nothing on these routes echoes a PIN, a recovery code or
# a key. Nothing here logs a request body either: a body may carry a Home
# Assistant token, and a token in a log is a token that has leaked.
#
# Show-once: a request carries NO show-once face (wizard.service._context), so
# the vault card refuses to create a vault from a browser and says where the
# PIN can be set instead, and Handoff shows no pairing code here.

#: A separate, much smaller allowance for requests that carry a secret_entry
#: answer. The general limiter above is sized for dashboard polling; guessing a
#: PIN or a token is not polling, so these get their own budget per client.
_WIZARD_SECRET_LIMIT = 5
_WIZARD_SECRET_WINDOW = 60
_wizard_secret_store: dict = {}  # ip -> (count, window_start)


def _wizard_secret_attempt():
    """Count one attempt that carried a secret. True when it is over budget.

    In memory, per process, same shape as ``_rate_limit``: it survives nothing
    and it is not a defence against a determined attacker with time. It is the
    difference between a thousand tries a minute and five.
    """
    ip = request.remote_addr or '127.0.0.1'
    now = time.time()
    count, start = _wizard_secret_store.get(ip, (0, 0.0))
    if now - start > _WIZARD_SECRET_WINDOW:
        _wizard_secret_store[ip] = (1, now)
        return False
    if count >= _WIZARD_SECRET_LIMIT:
        return True
    _wizard_secret_store[ip] = (count + 1, start)
    return False


def _wizard_carries_secret(data) -> bool:
    """Does this body claim to answer a secret_entry field on that card?

    Decided from the card this build actually proposes, never from a name
    pattern: the question is whether a field of kind ``secret_entry`` exists
    with that id, which is the same source of truth the applier uses.
    """
    from puffpai.wizard import service
    return service.asks_for_secret(data.get('skill'), data.get('answers'))


@app.route('/wizard/cards', methods=['GET'])
def wizard_cards():
    """The ordered cards for every skill that can propose one. Read-only.

    Runs each converted skill's ``propose``, which measures and surveys and
    writes nothing -- no run state, no config, no manifest. A skill that cannot
    propose is listed in ``refusals`` rather than taking the page down.

    ``order`` is the card ids in the order the wizard runs them (with the part
    for a skill that asks more than one question, ``secure:vault``), and
    ``not_converted`` names the skills that have no card at all.
    """
    from puffpai.wizard import service
    return jsonify(service.propose_cards())


@app.route('/wizard/apply', methods=['POST'])
def wizard_apply():
    """Apply one card's answers: ``{"skill": "secure:vault", "answers": {...}}``.

    The answers are checked against a freshly proposed card first, so a bad
    answer is a 400 the caller can act on and never a gap in the owner's build.
    Returns the updated card, which field a refusal was about, what verify
    observed, and the skills this change made stale (spec B.4).
    """
    from puffpai.wizard import cards as wizard_cards_mod, service
    data = request.json if isinstance(request.json, dict) else {}
    skill = data.get('skill')
    if not isinstance(skill, str):
        return jsonify({'success': False, 'field': None,
                        'message': 'Name the step to apply.'}), 400
    if _wizard_carries_secret(data) and _wizard_secret_attempt():
        return jsonify({'success': False, 'field': None,
                        'message': 'Too many attempts. Wait a minute and try '
                                   'again.'}), 429
    try:
        result = service.apply_skill(skill, data.get('answers') or {})
    except service.SkillNotConverted as exc:
        return jsonify({'success': False, 'field': None,
                        'message': str(exc)}), 404
    except wizard_cards_mod.CardError as exc:
        # A refusal the caller can act on, and the message is written to be
        # shown to a person. Nothing was applied.
        return jsonify({'success': False,
                        'field': getattr(exc, 'field', None),
                        'message': str(exc)}), 400
    result['success'] = True
    return jsonify(result)


@app.route('/wizard/run', methods=['POST'])
def wizard_run():
    """Accept the rest: ``{"acknowledged": ["brain", "integrate"]}``.

    Applies, in the wizard's own order, every card the owner has not already
    answered -- and refuses, on the server, to accept any card that is
    consequential and not in ``acknowledged``, any card that asks for a secret,
    and anything that is not a card at all. The browser's list of opened rows
    is a claim about what the owner read; it is checked against the real card
    set before it means anything.

    One at a time: a second run while one is in progress is a 409, not a race
    between two writers of the same sections.
    """
    from puffpai.wizard import service
    data = request.json if isinstance(request.json, dict) else {}
    acknowledged = data.get('acknowledged') or []
    if not isinstance(acknowledged, list) or len(acknowledged) > 40:
        return jsonify({'success': False, 'field': None,
                        'message': 'Acknowledged steps are a short list of '
                                   'step ids.'}), 400
    try:
        result = service.run_rest(acknowledged)
    except service.RunInProgress as exc:
        return jsonify({'success': False, 'field': None,
                        'message': str(exc)}), 409
    except service.SkillNotConverted as exc:
        return jsonify({'success': False, 'field': None,
                        'message': str(exc)}), 400
    result['success'] = True
    return jsonify(result)


@app.route('/wizard/state', methods=['GET'])
def wizard_state():
    """The run log, summarised: one row per skill, the gaps, what is stale.

    Carries ``resume``: whether a setup was stopped part-way and is still worth
    continuing, what it stopped at, and what was already decided. Read-only --
    nothing is verified and nothing is written until the owner answers.
    """
    from puffpai.wizard import service
    return jsonify(service.run_state())


@app.route('/wizard/resume', methods=['POST'])
def wizard_resume():
    """``{"choice": "continue"}`` or ``{"choice": "restart"}``. Nothing else.

    Continue re-verifies every blocking card the record calls done against this
    machine and drops the ones that no longer hold, so they are asked again --
    the vault is checked on disk whatever the record says. Restart moves the old
    record aside. One at a time, behind the same lock ``/wizard/run`` takes.
    """
    from puffpai.wizard import cards as wizard_cards_mod, service
    data = request.json if isinstance(request.json, dict) else {}
    try:
        result = service.resume_choice(data.get('choice'))
    except wizard_cards_mod.CardError as exc:
        return jsonify({'success': False,
                        'field': getattr(exc, 'field', None),
                        'message': str(exc)}), 400
    except service.RunInProgress as exc:
        return jsonify({'success': False, 'field': None,
                        'message': str(exc)}), 409
    result['success'] = True
    return jsonify(result)


def _prove_payload(record):
    """The one shape every /build/prove* route answers with.

    Copied field by field out of the record: checks, plain reasons, gaps whose
    fix command is re-rendered from the typed fix by ``fixes.safe_gaps``, and
    the live half. Nothing here echoes a stored string as a command line, and
    the API key is never part of a prove record in the first place.
    """
    from puffpai.wizard import fixes

    if not record:
        return {'ran': False, 'verdict': '', 'checks': [], 'gaps': [],
                'live': None,
                'message': 'Not proven yet: run puffpai prove'}

    live = record.get('live') if isinstance(record.get('live'), dict) else None
    return {
        'ran': True,
        'verdict': str(record.get('verdict') or ''),
        'static_at': record.get('static_at'),
        'bot_name': str(record.get('bot_name') or ''),
        'persona_id': str(record.get('persona_id') or ''),
        'checks': [
            {'id': str(c.get('id') or ''), 'title': str(c.get('title') or ''),
             'result': str(c.get('result') or ''),
             'reason': str(c.get('reason') or '')}
            for c in (record.get('checks') or []) if isinstance(c, dict)],
        'gaps': [
            {'what': g['what'], 'why': g['why'], 'impact': g['impact'],
             'fix': g['fix'], 'fix_command': g['fix_command']}
            for g in fixes.safe_gaps(record.get('gaps'), drop_invalid=True)],
        'live': None if live is None else {
            'ran': bool(live.get('ran')),
            'at': live.get('at'),
            'note': str(live.get('note') or ''),
            'owner': str(live.get('owner') or ''),
            'dashboard_url': str(live.get('dashboard_url') or ''),
            'checks': [
                {'id': str(c.get('id') or ''),
                 'title': str(c.get('title') or ''),
                 'result': str(c.get('result') or ''),
                 'reason': str(c.get('reason') or '')}
                for c in (live.get('checks') or []) if isinstance(c, dict)],
            'transcript': [
                {'question': str(t.get('question') or ''),
                 'reply': str(t.get('reply') or ''),
                 'verdict': str(t.get('verdict') or '')}
                for t in (live.get('transcript') or []) if isinstance(t, dict)],
        },
    }


#: One proof at a time. The live half makes real generations and rewrites the
#: run record; two at once would interleave both. Held without blocking, so a
#: second caller is told no rather than queued behind a model.
_PROVE_RUN_LOCK = threading.Lock()


def _prove_no_body():
    """``None`` when the request carried no instructions, else a 400 response.

    These routes prove **this** build. They take no path, no manifest and no
    record: everything they grade is read server-side from this install's own
    state. A body is therefore not ignored quietly - it is refused, so nobody
    is left believing the server was told which build to look at.
    """
    try:
        body = request.get_json(silent=True)
    except Exception:  # noqa: BLE001 - a body we cannot parse is still a body
        body = None
    if body in (None, {}, ''):
        return None
    return jsonify({'error': 'This route proves the build that is running and '
                             'takes no arguments.'}), 400


def _self_prove_url():
    """The loopback address this backend answers on, for the live half.

    127.0.0.1 whenever the bind address does not name one host, because
    loopback is the narrowest thing that can be true here; a configured host is
    used as given and still has to pass ``check_local_url``.
    """
    from puffpai.config import get_config

    cfg = get_config()
    host = str(getattr(cfg.api_server, 'host', '') or '127.0.0.1')
    if host in ('0.0.0.0', '::', '', '*'):
        host = '127.0.0.1'
    return f"http://{host}:{_bound_port(cfg)}"


def _bound_port(cfg):
    """The port this process is really listening on.

    `puffpai serve --port N` never writes N back to the config, so the stored
    port is only a fallback. SERVER_PORT comes from the WSGI server's own
    listening socket, never from the Host header, so a request cannot steer
    the callback somewhere else.
    """
    stored = int(getattr(cfg.api_server, 'port', 8000) or 8000)
    try:
        port = int(request.environ.get('SERVER_PORT') or 0)
    except (RuntimeError, TypeError, ValueError):
        return stored
    return port if 1024 <= port <= 65535 else stored


@app.route('/build/prove/static', methods=['POST'])
def build_prove_static():
    """Re-run the static half **here**, against this server's own state.

    ``puffpai prove`` used to run the static half in the shell it was typed
    in, which graded the caller's machine and then judged this backend's
    answers against a bot name read from somewhere else entirely. The running
    backend is the build being proved, so the static half runs in it.

    Reads this install's manifest, its knowledge folders and its launchers.
    Takes nothing from the request. Writes only this install's own run record.
    """
    from puffpai import prove

    refusal = _prove_no_body()
    if refusal is not None:
        return refusal
    try:
        record = prove.static_prove()
    except Exception as exc:
        logger.debug("Static prove failed: %s", exc)
        return jsonify({'error': 'The static checks could not be run on this '
                                 'build.'}), 500
    try:
        prove.write_record(record)
    except OSError as exc:
        logger.debug("Prove record write failed: %s", exc)
    return jsonify(_prove_payload(prove.read_record() or record))


@app.route('/build/prove/live', methods=['POST'])
def build_prove_live():
    """Run the live half from inside the build, against its own loopback.

    The same module ``puffpai prove`` used to run in the caller's shell, with
    the same three rules: at most ``prove.MAX_CHAT_CALLS`` generations, a
    destination that must pass ``check_local_url`` (this is the server calling
    itself on 127.0.0.1), and no redirect followed. The owner line is not
    touched here - nobody at this end can see a browser.
    """
    from puffpai import prove, prove_live

    refusal = _prove_no_body()
    if refusal is not None:
        return refusal
    if not _PROVE_RUN_LOCK.acquire(blocking=False):
        return jsonify({'error': 'A proof is already running on this build.'}), 409
    try:
        record = prove.read_record()
        if not record:
            record = prove.static_prove()
        goal = ''
        try:
            from puffpai import build_context
            goal = build_context.collect_goal()
        except Exception as exc:
            logger.debug("Goal read failed: %s", exc)
        dashboard_url = ''
        try:
            from puffpai import cli
            from puffpai.config import get_config
            dashboard_url = (cli.installed_launchers() or {}).get(
                'dashboard_url') or cli._dashboard_url(get_config())
        except Exception as exc:
            logger.debug("Dashboard address unknown: %s", exc)
        live = prove_live.live_prove(record, url=_self_prove_url(),
                                     api_key=_API_KEY, goal=goal, timeout=120.0,
                                     ask_owner=None,
                                     dashboard_url=str(dashboard_url or ''))
        record['live'] = live
        try:
            prove.write_record(record)
        except OSError as exc:
            logger.debug("Prove record write failed: %s", exc)
        return jsonify(_prove_payload(record))
    finally:
        _PROVE_RUN_LOCK.release()


@app.route('/build/prove/owner', methods=['POST'])
def build_prove_owner():
    """Record the one answer this build cannot observe: the owner's own eyes.

    The whole body is a single enum. Nothing else is read from it - not a
    check, not a transcript, not a verdict - because a record merged from a
    request is a build agreeing with whatever it was sent.
    """
    from puffpai import prove, prove_live

    body = request.get_json(silent=True)
    if not isinstance(body, dict) or set(body) - {'owner'}:
        return jsonify({'error': "This route takes one field: 'owner'."}), 400
    owner = body.get('owner')
    if owner not in prove_live.OWNER_ANSWERS:
        return jsonify({'error': 'owner is one of '
                                 f'{list(prove_live.OWNER_ANSWERS)}.'}), 400
    record = prove.read_record()
    if not record or not isinstance(record.get('live'), dict):
        return jsonify({'error': 'Nothing has been proved on this build yet.'}), 409
    record['live']['owner'] = owner
    try:
        prove.write_record(record)
    except OSError as exc:
        logger.debug("Prove record write failed: %s", exc)
        return jsonify({'error': 'The answer could not be written down.'}), 500
    return jsonify({'ok': True, 'owner': owner})


@app.route('/build/prove', methods=['GET'])
def build_prove():
    """The last proof this build recorded: checks, gaps, transcript, owner line.

    Read-only, and it proves nothing itself - it reports what
    :mod:`puffpai.prove` wrote during setup and what ``puffpai prove`` wrote
    after. A build that has never been proved answers ``ran: false`` rather
    than an empty payload, because "not proven yet" is a thing the dashboard
    has to be able to say in those words.

    No secrets: the record holds checks, plain-language reasons, rendered fix
    commands and reply text. The API key is never part of it.
    """
    from puffpai import prove

    try:
        record = prove.read_record()
    except Exception as exc:
        logger.debug("Prove record read failed: %s", exc)
        record = {}

    return jsonify(_prove_payload(record))



@app.route('/setup/complete', methods=['POST'])
def setup_mark_complete():
    """Mark first-run setup as complete (flips the onboarding gate)."""
    from puffpai import setup_ops
    blocked = _setup_gate()
    if blocked is not None:
        return blocked
    # mark_complete() also retires the first-run code: one function for every
    # way setup can finish (this route, the CLI, the card wizard).
    setup_ops.mark_complete()
    return jsonify({'success': True, 'ok': True, 'complete': True})



# ── one-time "waiting for your vault PIN" mention ───────────────────────────
_process_chat_query_unwrapped = _process_chat_query
_process_voice_query_unwrapped = _process_voice_query


def _process_chat_query(*args, **kwargs):
    out = _process_chat_query_unwrapped(*args, **kwargs)
    if isinstance(out, dict) and not out.get('private'):
        notice = _pending_pin_notice()
        if notice:
            out = dict(out)
            out['response'] = f"{notice} {out.get('response') or ''}".strip()
    return out


def _process_voice_query(*args, **kwargs):
    out = _process_voice_query_unwrapped(*args, **kwargs)
    if isinstance(out, str) and out:
        try:
            private = bool(getattr(_turn_privacy, 'vault_private', False))
        except Exception:
            private = True
        if not private:
            notice = _pending_pin_notice()
            if notice:
                out = f"{notice} {out}"
    return out


